--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: claim_agent_action_budget(uuid, integer[], integer[]); Type: FUNCTION; Schema: local_analytics; Owner: -
--

CREATE FUNCTION local_analytics.claim_agent_action_budget(p_action_id uuid, p_windows integer[], p_caps integer[]) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i integer; current_at timestamptz;
BEGIN
    IF array_ndims(p_windows) IS DISTINCT FROM 1
       OR array_ndims(p_caps) IS DISTINCT FROM 1
       OR array_lower(p_windows, 1) IS DISTINCT FROM 1
       OR array_lower(p_caps, 1) IS DISTINCT FROM 1
       OR cardinality(p_windows) NOT BETWEEN 1 AND 16
       OR cardinality(p_windows) IS DISTINCT FROM cardinality(p_caps) THEN
        RETURN 'unavailable';
    END IF;
    -- All callers share this transaction-scoped lock, including fresh processes.
    PERFORM pg_advisory_xact_lock(731904216583::bigint);
    current_at := clock_timestamp();
    IF NOT EXISTS (SELECT 1 FROM local_analytics.agent_action_records
                   WHERE action_id = p_action_id AND result_code IS NULL)
       OR EXISTS (SELECT 1 FROM local_analytics.agent_action_results WHERE action_id = p_action_id) THEN
        RETURN 'unavailable';
    END IF;
    IF EXISTS (SELECT 1 FROM local_analytics.agent_action_budget_claims WHERE action_id = p_action_id) THEN
        RETURN 'duplicate';
    END IF;
    FOR i IN 1..cardinality(p_windows) LOOP
        IF p_windows[i] IS NULL OR p_windows[i] <= 0 OR p_caps[i] IS NULL OR p_caps[i] < 0 THEN
            RETURN 'unavailable';
        END IF;
        IF (SELECT count(*) FROM local_analytics.agent_action_budget_claims
            WHERE claimed_at > current_at - (p_windows[i]::bigint * 60) * interval '1 second') >= p_caps[i] THEN
            RETURN 'limited';
        END IF;
    END LOOP;
    INSERT INTO local_analytics.agent_action_budget_claims(action_id, claimed_at)
        VALUES (p_action_id, current_at);
    RETURN 'created';
END;
$$;


--
-- Name: reserve_agent_action(uuid, text, text, text, text); Type: FUNCTION; Schema: local_analytics; Owner: -
--

CREATE FUNCTION local_analytics.reserve_agent_action(p_action_id uuid, p_trigger text, p_severity text, p_kind text, p_approval text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
BEGIN
    IF p_action_id IS NULL OR p_trigger IS NULL OR p_kind IS NULL THEN
        RETURN 'unavailable';
    END IF;
    -- Under READ COMMITTED each VOLATILE function query obtains a fresh
    -- snapshot after this transaction-scoped lock. A competing reservation
    -- therefore observes the first worker's durable pending row before acting.
    -- Stronger isolation could retain a stale snapshot: deny it explicitly.
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RETURN 'unavailable';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(p_trigger, 731904216584::bigint));
    IF EXISTS (SELECT 1 FROM local_analytics.agent_action_records
               WHERE trigger_signal_id=p_trigger AND action_kind_id=p_kind) THEN
        RETURN 'duplicate';
    END IF;
    IF EXISTS (SELECT 1 FROM local_analytics.agent_action_state
               WHERE trigger_signal_id=p_trigger AND (result_code IS NULL OR result_code IN
                 ('agent_action_unverified','agent_action_record_unavailable'))) THEN
        RETURN 'halted';
    END IF;
    INSERT INTO local_analytics.agent_action_records
        (action_id,trigger_signal_id,signal_severity,action_kind_id,human_approval_ref)
        VALUES (p_action_id,p_trigger,p_severity,p_kind,p_approval);
    RETURN 'created';
END;
$$;


--
-- Name: authorize_review_receipt_ocr_execution(uuid, uuid, uuid, uuid, text, text, text, jsonb, text, text, text, text); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.authorize_review_receipt_ocr_execution(p_user_id uuid, p_review_id uuid, p_generation uuid, p_recovery_operation_id uuid, p_verification_photo_hash text, p_image_hash text, p_input_context_hash text, p_model_policy jsonb, p_thinking_level text, p_prompt_version text, p_preprocess_version text, p_normalization_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  review_row public.reviews%ROWTYPE;
  current_generation uuid;
  recovery_row ocr_private.receipt_ocr_indeterminate_recoveries%ROWTYPE;
  current_photo_hash text;
BEGIN
  IF p_user_id IS NULL OR p_review_id IS NULL OR p_generation IS NULL
    OR p_verification_photo_hash !~ '^[0-9a-f]{64}$'
    OR p_image_hash !~ '^[0-9a-f]{64}$'
    OR p_input_context_hash !~ '^[0-9a-f]{64}$'
    OR pg_catalog.jsonb_typeof(p_model_policy) IS DISTINCT FROM 'array'
    OR p_thinking_level NOT IN ('LOW', 'MEDIUM', 'HIGH')
    OR p_prompt_version IS NULL OR p_preprocess_version IS NULL OR p_normalization_version IS NULL
  THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('receipt-ocr-recovery-review:' || p_review_id::text, 0)
  );
  SELECT * INTO review_row
  FROM public.reviews AS review
  WHERE review.id = p_review_id AND review.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND OR review_row.verification_photo IS NULL
    OR review_row.ocr_processed_at IS NOT NULL
    OR review_row.receipt_data IS NOT NULL
    OR review_row.receipt_hash IS NOT NULL
    OR review_row.is_duplicate IS DISTINCT FROM false
  THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;

  SELECT generation INTO current_generation
  FROM ocr_private.review_generations AS generation_row
  WHERE generation_row.review_id = p_review_id AND generation_row.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND OR current_generation IS DISTINCT FROM p_generation THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;

  current_photo_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(review_row.verification_photo, 'UTF8'), 'sha256'),
    'hex'
  );
  IF current_photo_hash IS DISTINCT FROM p_verification_photo_hash THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO recovery_row
  FROM ocr_private.receipt_ocr_indeterminate_recoveries AS operation_row
  WHERE operation_row.review_id = p_review_id
    AND operation_row.recovery_generation = p_generation
  FOR UPDATE;

  IF NOT FOUND THEN
    IF p_recovery_operation_id IS NOT NULL THEN
      RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'allowed_normal',
      'review_id', p_review_id,
      'generation', p_generation,
      'recovery_operation_id', NULL
    );
  END IF;

  IF p_recovery_operation_id IS NULL
    OR recovery_row.operation_id IS DISTINCT FROM p_recovery_operation_id
    OR recovery_row.verification_photo_hash IS DISTINCT FROM p_verification_photo_hash
    OR recovery_row.expected_image_hash IS DISTINCT FROM p_image_hash
    OR recovery_row.model_policy IS DISTINCT FROM p_model_policy
    OR recovery_row.thinking_level IS DISTINCT FROM p_thinking_level
    OR recovery_row.prompt_version IS DISTINCT FROM p_prompt_version
    OR recovery_row.preprocess_version IS DISTINCT FROM p_preprocess_version
    OR recovery_row.normalization_version IS DISTINCT FROM p_normalization_version
    OR (
      recovery_row.admitted_input_context_hash IS NOT NULL
      AND recovery_row.admitted_input_context_hash IS DISTINCT FROM p_input_context_hash
    )
  THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;

  IF recovery_row.admitted_input_context_hash IS NULL THEN
    UPDATE ocr_private.receipt_ocr_indeterminate_recoveries AS operation_row
    SET admitted_input_context_hash = p_input_context_hash,
        execution_admitted_at = pg_catalog.clock_timestamp()
    WHERE operation_row.operation_id = recovery_row.operation_id
      AND operation_row.admitted_input_context_hash IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'schema_version', 1,
    'status', 'allowed_recovery',
    'review_id', p_review_id,
    'generation', p_generation,
    'recovery_operation_id', recovery_row.operation_id
  );
END;
$_$;


--
-- Name: claim_receipt_ocr_recovery_result(uuid, uuid, text, text, text, jsonb, uuid, text, text, text, uuid, boolean); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.claim_receipt_ocr_recovery_result(p_recovery_operation_id uuid, p_user_id uuid, p_image_hash text, p_input_context_hash text, p_provider text, p_model_policy jsonb, p_generation uuid, p_prompt_version text, p_preprocess_version text, p_normalization_version text, p_operation_id uuid, p_force_refresh boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  recovery_row ocr_private.receipt_ocr_indeterminate_recoveries%ROWTYPE;
  recovery_review_id uuid;
  current_generation uuid;
  review_row public.reviews%ROWTYPE;
  current_photo_hash text;
  claim_result jsonb;
  claimed_result_id uuid;
BEGIN
  IF p_recovery_operation_id IS NULL THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_operation_required' USING ERRCODE = '55000';
  END IF;
  SELECT recovery.review_id INTO recovery_review_id
  FROM ocr_private.receipt_ocr_indeterminate_recoveries AS recovery
  WHERE recovery.operation_id = p_recovery_operation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('receipt-ocr-recovery-review:' || recovery_review_id::text, 0)
  );
  SELECT * INTO review_row
  FROM public.reviews AS review
  WHERE review.id = recovery_review_id AND review.user_id = p_user_id
  FOR SHARE;
  IF NOT FOUND OR review_row.verification_photo IS NULL
    OR review_row.ocr_processed_at IS NOT NULL
    OR review_row.receipt_data IS NOT NULL
    OR review_row.receipt_hash IS NOT NULL
    OR review_row.is_duplicate IS DISTINCT FROM false
  THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;
  SELECT generation INTO current_generation
  FROM ocr_private.review_generations AS generation_row
  WHERE generation_row.review_id = recovery_review_id
    AND generation_row.user_id = p_user_id
  FOR SHARE;
  IF NOT FOUND OR current_generation IS DISTINCT FROM p_generation THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO recovery_row
  FROM ocr_private.receipt_ocr_indeterminate_recoveries AS recovery
  WHERE recovery.operation_id = p_recovery_operation_id
  FOR UPDATE;
  IF NOT FOUND OR recovery_row.recovery_generation IS DISTINCT FROM p_generation
    OR recovery_row.expected_image_hash IS DISTINCT FROM p_image_hash
    OR recovery_row.admitted_input_context_hash IS NULL
    OR recovery_row.admitted_input_context_hash IS DISTINCT FROM p_input_context_hash
    OR recovery_row.model_policy IS DISTINCT FROM p_model_policy
    OR recovery_row.prompt_version IS DISTINCT FROM p_prompt_version
    OR recovery_row.preprocess_version IS DISTINCT FROM p_preprocess_version
    OR recovery_row.normalization_version IS DISTINCT FROM p_normalization_version
  THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;

  current_photo_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(review_row.verification_photo, 'UTF8'), 'sha256'),
    'hex'
  );
  IF current_photo_hash IS DISTINCT FROM recovery_row.verification_photo_hash THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
  END IF;

  claim_result := ocr_private.claim_receipt_ocr_result_core(
    p_user_id, p_image_hash, p_input_context_hash, p_provider, p_model_policy,
    p_generation, p_prompt_version, p_preprocess_version, p_normalization_version,
    p_operation_id, p_force_refresh
  );

  IF claim_result->>'status' IN ('claimed', 'processing') THEN
    BEGIN
      claimed_result_id := (claim_result->>'result_ref')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
    END;
    IF claimed_result_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM ocr_private.receipt_results AS result_row
      WHERE result_row.id = claimed_result_id
        AND result_row.user_id = p_user_id
        AND result_row.generation = p_generation
        AND result_row.status = 'processing'
    ) THEN
      RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
    END IF;

    INSERT INTO ocr_private.receipt_ocr_recovery_execution_leases (
      recovery_operation_id,
      review_id,
      result_id,
      recovery_generation
    ) VALUES (
      recovery_row.operation_id,
      recovery_row.review_id,
      claimed_result_id,
      recovery_row.recovery_generation
    ) ON CONFLICT DO NOTHING;

    IF NOT EXISTS (
      SELECT 1
      FROM ocr_private.receipt_ocr_recovery_execution_leases AS lease
      WHERE lease.recovery_operation_id = recovery_row.operation_id
        AND lease.review_id = recovery_row.review_id
        AND lease.result_id = claimed_result_id
        AND lease.recovery_generation = recovery_row.recovery_generation
    ) THEN
      RAISE EXCEPTION 'receipt_ocr_recovery_execution_conflict' USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN claim_result;
END;
$$;


--
-- Name: claim_receipt_ocr_result(uuid, text, text, text, jsonb, uuid, text, text, text, uuid, boolean); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.claim_receipt_ocr_result(p_user_id uuid, p_image_hash text, p_input_context_hash text, p_provider text, p_model_policy jsonb, p_generation uuid, p_prompt_version text, p_preprocess_version text, p_normalization_version text, p_operation_id uuid, p_force_refresh boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  claim_review_id uuid;
BEGIN
  SELECT generation_row.review_id INTO claim_review_id
  FROM ocr_private.review_generations AS generation_row
  WHERE generation_row.user_id = p_user_id
    AND generation_row.generation = p_generation;
  IF FOUND THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('receipt-ocr-recovery-review:' || claim_review_id::text, 0)
    );
    IF NOT EXISTS (
      SELECT 1
      FROM ocr_private.review_generations AS generation_row
      WHERE generation_row.review_id = claim_review_id
        AND generation_row.user_id = p_user_id
        AND generation_row.generation = p_generation
    ) THEN
      RAISE EXCEPTION 'receipt_ocr_review_generation_stale' USING ERRCODE = '55000';
    END IF;
  ELSIF p_prompt_version LIKE 'admin-receipt-%' THEN
    -- A deleted review or rotated generation cannot be reclassified as an
    -- ordinary admin claim merely because its recovery receipt cascaded away.
    RAISE EXCEPTION 'receipt_ocr_review_generation_stale' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM ocr_private.receipt_ocr_indeterminate_recoveries AS recovery
    WHERE recovery.recovery_generation = p_generation
      OR recovery.expected_generation = p_generation
  ) THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_operation_required' USING ERRCODE = '55000';
  END IF;
  RETURN ocr_private.claim_receipt_ocr_result_core(
    p_user_id, p_image_hash, p_input_context_hash, p_provider, p_model_policy,
    p_generation, p_prompt_version, p_preprocess_version, p_normalization_version,
    p_operation_id, p_force_refresh
  );
END;
$$;


--
-- Name: claim_receipt_ocr_result_core(uuid, text, text, text, jsonb, uuid, text, text, text, uuid, boolean); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.claim_receipt_ocr_result_core(p_user_id uuid, p_image_hash text, p_input_context_hash text, p_provider text, p_model_policy jsonb, p_generation uuid, p_prompt_version text, p_preprocess_version text, p_normalization_version text, p_operation_id uuid, p_force_refresh boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
BEGIN
  IF p_user_id IS NULL
    OR p_operation_id IS NULL
    OR p_image_hash IS NULL
    OR p_input_context_hash IS NULL
    OR p_provider IS NULL
    OR NOT ocr_private.valid_model_policy(p_model_policy)
    OR p_generation IS NULL
    OR p_prompt_version IS NULL
    OR p_preprocess_version IS NULL
    OR p_normalization_version IS NULL
    OR p_image_hash !~ '^[0-9a-f]{64}$'
    OR p_input_context_hash !~ '^[0-9a-f]{64}$'
    OR p_provider <> 'gemini'
    OR length(p_prompt_version) NOT BETWEEN 1 AND 160
    OR length(p_preprocess_version) NOT BETWEEN 1 AND 160
    OR length(p_normalization_version) NOT BETWEEN 1 AND 160
  THEN
    RAISE EXCEPTION 'invalid_receipt_ocr_claim' USING ERRCODE = '22023';
  END IF;

  INSERT INTO ocr_private.receipt_results (
    user_id, image_hash, input_context_hash, provider, model_policy, generation,
    prompt_version, preprocess_version, normalization_version,
    status, dispatch_stage, claim_token
  ) VALUES (
    p_user_id, p_image_hash, p_input_context_hash, p_provider, p_model_policy, p_generation,
    p_prompt_version, p_preprocess_version, p_normalization_version,
    'processing', 'reserved', p_operation_id
  )
  ON CONFLICT (
    user_id, image_hash, input_context_hash, provider, model_policy, generation,
    prompt_version, preprocess_version, normalization_version
  ) DO NOTHING
  RETURNING * INTO v_result;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'status', 'claimed',
      'result_ref', v_result.id,
      'claim_token', v_result.claim_token
    );
  END IF;

  SELECT * INTO v_result
  FROM ocr_private.receipt_results
  WHERE user_id = p_user_id
    AND image_hash = p_image_hash
    AND input_context_hash = p_input_context_hash
    AND provider = p_provider
    AND model_policy = p_model_policy
    AND generation = p_generation
    AND prompt_version = p_prompt_version
    AND preprocess_version = p_preprocess_version
    AND normalization_version = p_normalization_version
  FOR UPDATE;

  IF v_result.status = 'succeeded' AND (NOT p_force_refresh OR v_result.dispatch_stage = 'uncertain') THEN
    RETURN jsonb_build_object(
      'status', 'cached',
      'result_ref', v_result.id,
      'result_revision', v_result.result_revision,
      'result_payload', v_result.result_payload,
      'retry_blocked', v_result.dispatch_stage = 'uncertain'
    );
  END IF;

  IF v_result.status = 'processing' THEN
    IF p_force_refresh AND v_result.dispatch_stage = 'reserved' THEN
      UPDATE ocr_private.receipt_results
      SET claim_token = p_operation_id,
          claimed_at = now(),
          updated_at = now()
      WHERE id = v_result.id
        AND status = 'processing'
        AND dispatch_stage = 'reserved'
        AND claim_token = v_result.claim_token
      RETURNING * INTO v_result;
      IF FOUND THEN
        RETURN jsonb_build_object(
          'status', 'claimed',
          'result_ref', v_result.id,
          'claim_token', v_result.claim_token,
          'recovered_reservation', true
        );
      END IF;
    ELSIF p_force_refresh AND v_result.dispatch_stage = 'possibly_dispatched' THEN
      UPDATE ocr_private.receipt_results
      SET status = CASE WHEN result_payload IS NULL THEN 'indeterminate' ELSE 'succeeded' END,
          dispatch_stage = 'uncertain',
          claim_token = NULL,
          completed_at = now(),
          updated_at = now()
      WHERE id = v_result.id
        AND status = 'processing'
        AND dispatch_stage = 'possibly_dispatched'
        AND claim_token = v_result.claim_token
      RETURNING * INTO v_result;
      IF FOUND AND v_result.result_payload IS NOT NULL THEN
        RETURN jsonb_build_object(
          'status', 'cached',
          'result_ref', v_result.id,
          'result_revision', v_result.result_revision,
          'result_payload', v_result.result_payload,
          'retry_blocked', true
        );
      ELSIF FOUND THEN
        RETURN jsonb_build_object('status', 'indeterminate', 'result_ref', v_result.id);
      END IF;
    END IF;
    RETURN jsonb_build_object('status', 'processing', 'result_ref', v_result.id);
  END IF;

  -- An uncertain provider dispatch is never replayed by force refresh. Any
  -- future retry needs a separate reviewed server operation, not this route.
  IF v_result.status = 'indeterminate' OR NOT p_force_refresh THEN
    RETURN jsonb_build_object('status', 'indeterminate', 'result_ref', v_result.id);
  END IF;

  UPDATE ocr_private.receipt_results
  SET status = 'processing',
      dispatch_stage = 'reserved',
      claim_token = p_operation_id,
      claimed_at = now(),
      completed_at = NULL,
      updated_at = now()
  WHERE id = v_result.id
  RETURNING * INTO v_result;

  RETURN jsonb_build_object(
    'status', 'claimed',
    'result_ref', v_result.id,
    'claim_token', v_result.claim_token
  );
END;
$_$;


--
-- Name: complete_receipt_ocr_result(uuid, uuid, jsonb); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.complete_receipt_ocr_result(p_result_id uuid, p_claim_token uuid, p_result_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
BEGIN
  IF NOT ocr_private.valid_result_payload(p_result_payload) THEN
    RAISE EXCEPTION 'invalid_receipt_ocr_result' USING ERRCODE = '22023';
  END IF;

  UPDATE ocr_private.receipt_results
  SET status = 'succeeded',
      dispatch_stage = 'completed',
      claim_token = NULL,
      result_payload = p_result_payload,
      result_revision = extensions.gen_random_uuid(),
      completed_at = now(),
      updated_at = now()
  WHERE id = p_result_id
    AND status = 'processing'
    AND dispatch_stage = 'possibly_dispatched'
    AND claim_token = p_claim_token
    AND provider = p_result_payload->>'provider'
    AND model_policy ? (p_result_payload->>'model')
    AND normalization_version = p_result_payload->>'normalization_version'
  RETURNING * INTO v_result;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'status', 'succeeded',
      'result_ref', v_result.id,
      'result_revision', v_result.result_revision
    );
  END IF;

  SELECT * INTO v_result FROM ocr_private.receipt_results WHERE id = p_result_id;
  IF v_result.status = 'succeeded' AND v_result.result_payload = p_result_payload THEN
    RETURN jsonb_build_object(
      'status', 'succeeded',
      'result_ref', v_result.id,
      'result_revision', v_result.result_revision
    );
  END IF;
  RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
END;
$$;


--
-- Name: create_review_with_receipt_ocr(uuid, uuid, uuid, text, text, timestamp with time zone, text, text[], text[], uuid, uuid, uuid, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.create_review_with_receipt_ocr(p_review_id uuid, p_user_id uuid, p_restaurant_id uuid, p_title text, p_content text, p_visited_at timestamp with time zone, p_verification_photo text, p_food_photos text[], p_categories text[], p_ocr_result_id uuid, p_ocr_result_revision uuid, p_verification_object_id uuid, p_verification_object_version text, p_verification_object_updated_at timestamp with time zone, p_verification_photo_sha256 text, p_user_corrections jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
  v_normalized jsonb;
  v_receipt_data jsonb;
  v_receipt_hash text;
  v_duplicate_of uuid;
  v_owner_prefix text := p_user_id::text || '/reviews/' || p_review_id::text || '/';
  v_verification_object storage.objects%ROWTYPE;
  v_food_object storage.objects%ROWTYPE;
  v_food_photo text;
BEGIN
  IF p_review_id IS NULL OR p_user_id IS NULL OR p_restaurant_id IS NULL
    OR p_ocr_result_id IS NULL OR p_ocr_result_revision IS NULL
    OR p_verification_object_id IS NULL OR p_verification_object_updated_at IS NULL
    OR p_verification_photo_sha256 IS NULL OR p_verification_photo_sha256 !~ '^[0-9a-f]{64}$'
    OR p_verification_photo IS NULL OR p_verification_photo NOT LIKE v_owner_prefix || 'verification/%'
    OR substring(p_verification_photo FROM length(v_owner_prefix || 'verification/') + 1) LIKE '%/%'
    OR p_food_photos IS NULL OR cardinality(p_food_photos) = 0
    OR EXISTS (SELECT 1 FROM unnest(p_food_photos) AS photo WHERE photo NOT LIKE v_owner_prefix || 'food/%')
    OR EXISTS (SELECT 1 FROM unnest(p_food_photos) AS photo WHERE substring(photo FROM length(v_owner_prefix || 'food/') + 1) LIKE '%/%')
    OR (SELECT count(*) FROM unnest(p_food_photos)) <> (SELECT count(DISTINCT photo) FROM unnest(p_food_photos) AS photo)
    OR p_user_corrections IS NULL OR jsonb_typeof(p_user_corrections) <> 'object'
    OR p_user_corrections ?| ARRAY['receipt_hash', 'ocr_result_id', 'ocr_result_revision', 'source', 'schema_version', 'status']
  THEN
    RAISE EXCEPTION 'invalid_review_receipt_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_result
  FROM ocr_private.receipt_results
  WHERE id = p_ocr_result_id
    AND user_id = p_user_id
    AND generation = '00000000-0000-0000-0000-000000000000'::uuid
    AND status = 'succeeded'
  FOR SHARE;
  IF NOT FOUND OR NOT ocr_private.valid_result_payload(v_result.result_payload) THEN
    RAISE EXCEPTION 'receipt_ocr_result_not_available' USING ERRCODE = '42501';
  END IF;
  IF v_result.result_revision IS DISTINCT FROM p_ocr_result_revision THEN
    RAISE EXCEPTION 'receipt_ocr_result_stale' USING ERRCODE = '42501';
  END IF;
  IF v_result.image_hash <> p_verification_photo_sha256 THEN
    RAISE EXCEPTION 'receipt_ocr_image_mismatch' USING ERRCODE = '42501';
  END IF;

  -- This row lock protects only Storage metadata. Correct byte binding requires
  -- the Storage service to update version/updated_at atomically with content,
  -- immutable verification keys (browser upsert:false and no authenticated
  -- UPDATE policy), and no out-of-band direct S3 overwrite.
  SELECT * INTO v_verification_object
  FROM storage.objects
  WHERE id = p_verification_object_id
    AND bucket_id = 'review-verifications'
    AND name = p_verification_photo
    AND owner_id = p_user_id::text
    AND archived_at IS NULL
    AND is_delete_marker = false
  FOR SHARE;
  IF NOT FOUND
    OR v_verification_object.version IS DISTINCT FROM p_verification_object_version
    OR v_verification_object.updated_at IS DISTINCT FROM p_verification_object_updated_at
  THEN
    RAISE EXCEPTION 'receipt_verification_object_not_available' USING ERRCODE = '42501';
  END IF;

  FOREACH v_food_photo IN ARRAY p_food_photos LOOP
    SELECT * INTO v_food_object
    FROM storage.objects
    WHERE bucket_id = 'review-photos'
      AND name = v_food_photo
      AND owner_id = p_user_id::text
      AND archived_at IS NULL
      AND is_delete_marker = false
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'review_food_object_not_available' USING ERRCODE = '42501';
    END IF;
  END LOOP;

  v_normalized := v_result.result_payload->'normalized';
  IF v_result.result_payload ? 'failure_code' THEN
    v_receipt_data := jsonb_build_object(
      'schema_version', 'receipt_summary_v1',
      'status', 'failed',
      'failure_code', v_result.result_payload->>'failure_code',
      'source', 'public_ocr',
      'ocr_result_id', v_result.id,
      'ocr_result_revision', v_result.result_revision
    );
  ELSE
    v_receipt_data := jsonb_strip_nulls(jsonb_build_object(
      'schema_version', 'receipt_summary_v1',
      'status', 'processed',
      'source', 'public_ocr',
      'ocr_result_id', v_result.id,
      'ocr_result_revision', v_result.result_revision,
      'store_name', v_normalized->'store_name',
      'date', v_normalized->'date',
      'time', v_normalized->'time',
      'total_amount', v_normalized->'total_amount',
      'items', v_normalized->'items',
      'item_count', COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(v_normalized->'items') = 'array' THEN v_normalized->'items' ELSE '[]'::jsonb END), 0),
      'confidence', v_result.result_payload->'confidence',
      'user_corrections', p_user_corrections
    ));

    IF NULLIF(v_normalized->>'store_name', '') IS NOT NULL
      AND (v_normalized->>'date') ~ '^\d{4}-\d{2}-\d{2}$'
      AND (v_normalized->>'time') ~ '^\d{2}:\d{2}$'
      AND jsonb_typeof(v_normalized->'total_amount') = 'number'
    THEN
      v_receipt_hash := encode(extensions.digest(
        (v_normalized->>'store_name') || '|' || (v_normalized->>'date') || '|'
        || (v_normalized->>'time') || '|' || (v_normalized->>'total_amount'),
        'sha256'
      ), 'hex');
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_receipt_hash, 0));
      SELECT id INTO v_duplicate_of
      FROM public.reviews
      WHERE receipt_hash = v_receipt_hash
      ORDER BY created_at, id
      LIMIT 1;
      IF v_duplicate_of IS NOT NULL THEN
        v_receipt_data := v_receipt_data || jsonb_build_object('duplicate_of', v_duplicate_of);
      END IF;
    END IF;
  END IF;

  INSERT INTO public.reviews (
    id, user_id, restaurant_id, title, content, visited_at,
    verification_photo, food_photos, categories, is_verified,
    receipt_hash, receipt_data, is_duplicate, ocr_processed_at
  ) VALUES (
    p_review_id, p_user_id, p_restaurant_id, p_title, p_content, p_visited_at,
    p_verification_photo, p_food_photos, p_categories, false,
    CASE WHEN v_duplicate_of IS NULL THEN v_receipt_hash ELSE NULL END,
    v_receipt_data,
    v_duplicate_of IS NOT NULL,
    now()
  );

  RETURN p_review_id;
END;
$_$;


--
-- Name: get_feature_runtime_capability(uuid); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.get_feature_runtime_capability(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_ready boolean;
  v_contracts_ready boolean;
  v_review_ocr_columns_ready boolean;
  v_review_ocr_indexes_ready boolean;
  v_trigger_helper_oid oid := pg_catalog.to_regprocedure(
    'ocr_private.register_review_ocr_generation()'
  );
BEGIN
  IF p_user_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM auth.users AS user_row WHERE user_row.id = p_user_id
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'held',
      'code', 'FEATURE_DATABASE_HELD',
      'capability_version', 'review-media-feature-v1'
    );
  END IF;

  SELECT NOT EXISTS (
    SELECT 1
    FROM (
      VALUES
        ('public.claim_receipt_ocr_result(uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)', 'jsonb'::pg_catalog.regtype, false, 'v'::"char"),
        ('public.mark_receipt_ocr_dispatched(uuid,uuid)', 'jsonb'::pg_catalog.regtype, false, 'v'::"char"),
        ('public.complete_receipt_ocr_result(uuid,uuid,jsonb)', 'jsonb'::pg_catalog.regtype, false, 'v'::"char"),
        ('public.mark_receipt_ocr_result_indeterminate(uuid,uuid)', 'jsonb'::pg_catalog.regtype, false, 'v'::"char"),
        ('public.release_receipt_ocr_claim(uuid,uuid)', 'jsonb'::pg_catalog.regtype, false, 'v'::"char"),
        ('public.read_receipt_ocr_result(uuid,text,text,text,jsonb,uuid,text,text,text)', 'jsonb'::pg_catalog.regtype, false, 's'::"char"),
        ('public.get_review_receipt_ocr_generation(uuid,uuid)', 'jsonb'::pg_catalog.regtype, false, 's'::"char"),
        ('public.publish_review_receipt_ocr_result(uuid,uuid,uuid,uuid,uuid,text,jsonb,boolean)', 'jsonb'::pg_catalog.regtype, false, 'v'::"char"),
        ('public.get_feature_runtime_capability(uuid)', 'jsonb'::pg_catalog.regtype, false, 's'::"char"),
        ('public.get_owned_review_storage_objects(uuid,uuid,text,text[])', 'record'::pg_catalog.regtype, true, 'v'::"char"),
        ('public.create_review_with_receipt_ocr(uuid,uuid,uuid,text,text,timestamptz,text,text[],text[],uuid,uuid,uuid,text,timestamptz,text,jsonb)', 'uuid'::pg_catalog.regtype, false, 'v'::"char")
    ) AS required(signature, return_type, returns_set, volatility)
    LEFT JOIN pg_catalog.pg_proc AS procedure_row
      ON procedure_row.oid = pg_catalog.to_regprocedure(required.signature)
    WHERE procedure_row.oid IS NULL
      OR procedure_row.proowner <> 'privacy_workflow_owner'::pg_catalog.regrole
      OR NOT procedure_row.prosecdef
      OR procedure_row.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
      OR procedure_row.prokind <> 'f'
      OR procedure_row.provolatile <> required.volatility
      OR procedure_row.prorettype <> required.return_type
      OR procedure_row.proretset IS DISTINCT FROM required.returns_set
      OR procedure_row.prolang <> (
        SELECT language.oid
        FROM pg_catalog.pg_language AS language
        WHERE language.lanname = 'sql'
      )
      OR NOT pg_catalog.has_function_privilege('service_role', procedure_row.oid, 'EXECUTE')
      OR pg_catalog.has_function_privilege('anon', procedure_row.oid, 'EXECUTE')
      OR pg_catalog.has_function_privilege('authenticated', procedure_row.oid, 'EXECUTE')
  ) INTO v_contracts_ready;

  -- Keep the runtime decision tied to the same exact review-column contract
  -- that the migration and successor controller admit. A later same-name
  -- column with a different type, default, nullability, identity or generated
  -- shape must put the feature back on hold.
  SELECT pg_catalog.count(*) = 4
    AND pg_catalog.bool_and(
      NOT attribute.attnotnull
      AND attribute.atttypmod = -1
      AND attribute.attidentity = ''
      AND attribute.attgenerated = ''
      AND CASE attribute.attname
        WHEN 'receipt_hash' THEN
          attribute.atttypid = 'text'::pg_catalog.regtype
          AND default_value.oid IS NULL
        WHEN 'receipt_data' THEN
          attribute.atttypid = 'jsonb'::pg_catalog.regtype
          AND default_value.oid IS NULL
        WHEN 'is_duplicate' THEN
          attribute.atttypid = 'boolean'::pg_catalog.regtype
          AND pg_catalog.pg_get_expr(
            default_value.adbin,
            default_value.adrelid
          ) = 'false'
        WHEN 'ocr_processed_at' THEN
          attribute.atttypid = 'timestamp with time zone'::pg_catalog.regtype
          AND default_value.oid IS NULL
        ELSE false
      END
    )
  INTO v_review_ocr_columns_ready
  FROM pg_catalog.pg_attribute AS attribute
  LEFT JOIN pg_catalog.pg_attrdef AS default_value
    ON default_value.adrelid = attribute.attrelid
   AND default_value.adnum = attribute.attnum
  WHERE attribute.attrelid = 'public.reviews'::regclass
    AND attribute.attnum > 0
    AND NOT attribute.attisdropped
    AND attribute.attname = ANY (ARRAY[
      'receipt_hash',
      'receipt_data',
      'is_duplicate',
      'ocr_processed_at'
    ]::name[]);

  -- Index identity is not enough: method, key, predicate and online-validity
  -- flags are all part of the runtime contract.
  SELECT pg_catalog.count(*) = 3
    AND pg_catalog.bool_and(
      index_relation.relkind = 'i'
      AND index_row.indrelid = 'public.reviews'::regclass
      AND access_method.amname = 'btree'
      AND index_row.indnkeyatts = 1
      AND index_row.indnatts = 1
      AND index_row.indexprs IS NULL
      AND index_row.indisvalid
      AND index_row.indisready
      AND index_row.indislive
      AND NOT index_row.indisprimary
      AND NOT index_row.indisexclusion
      AND CASE index_relation.relname
        WHEN 'idx_reviews_receipt_hash' THEN
          index_row.indisunique
          AND pg_catalog.pg_get_indexdef(index_relation.oid, 1, true) = 'receipt_hash'
          AND pg_catalog.pg_get_expr(
            index_row.indpred,
            index_row.indrelid
          ) = '(receipt_hash IS NOT NULL)'
        WHEN 'reviews_ocr_pending_idx' THEN
          NOT index_row.indisunique
          AND pg_catalog.pg_get_indexdef(index_relation.oid, 1, true) = 'ocr_processed_at'
          AND pg_catalog.pg_get_expr(
            index_row.indpred,
            index_row.indrelid
          ) = '(verification_photo IS NOT NULL)'
        WHEN 'reviews_duplicate_idx' THEN
          NOT index_row.indisunique
          AND pg_catalog.pg_get_indexdef(index_relation.oid, 1, true) = 'is_duplicate'
          AND index_row.indpred IS NULL
        ELSE false
      END
    )
  INTO v_review_ocr_indexes_ready
  FROM pg_catalog.pg_class AS index_relation
  JOIN pg_catalog.pg_namespace AS namespace
    ON namespace.oid = index_relation.relnamespace
  JOIN pg_catalog.pg_index AS index_row
    ON index_row.indexrelid = index_relation.oid
  JOIN pg_catalog.pg_am AS access_method
    ON access_method.oid = index_relation.relam
  WHERE namespace.nspname = 'public'
    AND index_relation.relname = ANY (ARRAY[
      'idx_reviews_receipt_hash',
      'reviews_ocr_pending_idx',
      'reviews_duplicate_idx'
    ]::name[]);

  SELECT EXISTS (
    SELECT 1
    FROM ocr_private.feature_runtime_capability AS capability
    WHERE capability.capability_version = 'review-media-feature-v1'
      AND capability.schema_version = 1
  )
  AND v_contracts_ready
  AND coalesce(v_review_ocr_columns_ready, false)
  AND coalesce(v_review_ocr_indexes_ready, false)
  AND pg_catalog.to_regprocedure('public.storyboard_production_admin(uuid,text,uuid,integer,jsonb)') IS NOT NULL
  AND pg_catalog.to_regprocedure('public.storyboard_production_worker(uuid,text,uuid,uuid,jsonb)') IS NOT NULL
  AND EXISTS (
    SELECT 1
    FROM pg_catalog.pg_class AS table_row
    WHERE table_row.oid = 'ocr_private.receipt_results'::pg_catalog.regclass
      AND table_row.relowner = 'postgres'::pg_catalog.regrole
      AND table_row.relrowsecurity
      AND table_row.relforcerowsecurity
  )
  AND EXISTS (
    SELECT 1
    FROM pg_catalog.pg_class AS table_row
    WHERE table_row.oid = 'ocr_private.review_generations'::pg_catalog.regclass
      AND table_row.relowner = 'postgres'::pg_catalog.regrole
      AND table_row.relrowsecurity
      AND table_row.relforcerowsecurity
  )
  AND EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS helper
    WHERE helper.oid = v_trigger_helper_oid
      AND helper.proowner = 'postgres'::pg_catalog.regrole
      AND helper.prosecdef
      AND helper.proconfig = ARRAY['search_path=""']::text[]
      AND helper.prorettype = 'trigger'::pg_catalog.regtype
      AND helper.prolang = (
        SELECT language.oid
        FROM pg_catalog.pg_language AS language
        WHERE language.lanname = 'plpgsql'
      )
      AND NOT pg_catalog.has_function_privilege('anon', helper.oid, 'EXECUTE')
      AND NOT pg_catalog.has_function_privilege('authenticated', helper.oid, 'EXECUTE')
      AND NOT pg_catalog.has_function_privilege('service_role', helper.oid, 'EXECUTE')
  )
  AND EXISTS (
    SELECT 1
    FROM pg_catalog.pg_trigger AS trigger_row
    WHERE trigger_row.tgrelid = 'public.reviews'::pg_catalog.regclass
      AND trigger_row.tgfoid = v_trigger_helper_oid
      AND trigger_row.tgname IN (
        'review_ocr_generation_on_insert',
        'review_ocr_generation_on_reset'
      )
      AND NOT trigger_row.tgisinternal
    GROUP BY trigger_row.tgfoid
    HAVING pg_catalog.count(*) = 2
  )
  -- The metadata fence is operational only while both installed triggers and
  -- their implementation functions retain the exact audited contract. A
  -- disabled, retargeted, redefined or newly exposed helper holds the feature.
  AND EXISTS (
    SELECT 1
    FROM pg_catalog.pg_trigger AS trigger_row
    JOIN pg_catalog.pg_proc AS function_row
      ON function_row.oid = trigger_row.tgfoid
    WHERE trigger_row.tgrelid = 'storage.objects'::pg_catalog.regclass
      AND trigger_row.tgname = 'a01_review_verification_immutable_update'
      AND trigger_row.tgenabled = 'O'
      AND NOT trigger_row.tgisinternal
      AND trigger_row.tgtype = 19
      AND pg_catalog.pg_get_triggerdef(trigger_row.oid, false) =
        'CREATE TRIGGER a01_review_verification_immutable_update BEFORE UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION review_media_private.reject_verification_object_update()'
      AND function_row.oid =
        'review_media_private.reject_verification_object_update()'::pg_catalog.regprocedure
      AND NOT function_row.prosecdef
      AND function_row.proowner = 'privacy_workflow_owner'::pg_catalog.regrole
      AND function_row.proconfig = ARRAY['search_path=""']::text[]
      AND function_row.prokind = 'f'
      AND function_row.provolatile = 'v'
      AND NOT function_row.proretset
      AND function_row.prorettype = 'trigger'::pg_catalog.regtype
      AND function_row.prolang = (
        SELECT language.oid
        FROM pg_catalog.pg_language AS language
        WHERE language.lanname = 'plpgsql'
      )
      AND pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(function_row.prosrc, 'UTF8')),
        'hex'
      ) = 'aa1d4951b8d5fdd15249b090c6d6efba897f39eaceee86bf09221eb1d942d545'
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.unnest(ARRAY[
          'anon',
          'authenticated',
          'service_role',
          'supabase_storage_admin',
          'postgres'
        ]) AS role_name
        WHERE pg_catalog.has_function_privilege(
          role_name,
          function_row.oid,
          'EXECUTE'
        )
      )
  )
  AND EXISTS (
    SELECT 1
    FROM pg_catalog.pg_trigger AS trigger_row
    JOIN pg_catalog.pg_proc AS function_row
      ON function_row.oid = trigger_row.tgfoid
    WHERE trigger_row.tgrelid = 'storage.objects'::pg_catalog.regclass
      AND trigger_row.tgname = 'a01_review_verification_guard_delete'
      AND trigger_row.tgenabled = 'O'
      AND NOT trigger_row.tgisinternal
      AND trigger_row.tgtype = 11
      AND pg_catalog.pg_get_triggerdef(trigger_row.oid, false) =
        'CREATE TRIGGER a01_review_verification_guard_delete BEFORE DELETE ON storage.objects FOR EACH ROW EXECUTE FUNCTION review_media_private.guard_verification_object_delete()'
      AND function_row.oid =
        'review_media_private.guard_verification_object_delete()'::pg_catalog.regprocedure
      AND function_row.prosecdef
      AND function_row.proowner = 'privacy_workflow_owner'::pg_catalog.regrole
      AND function_row.proconfig = ARRAY['search_path=""']::text[]
      AND function_row.prokind = 'f'
      AND function_row.provolatile = 'v'
      AND NOT function_row.proretset
      AND function_row.prorettype = 'trigger'::pg_catalog.regtype
      AND function_row.prolang = (
        SELECT language.oid
        FROM pg_catalog.pg_language AS language
        WHERE language.lanname = 'plpgsql'
      )
      AND pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(function_row.prosrc, 'UTF8')),
        'hex'
      ) = '24311fc7071597fbc78c4c54897690da5aaa70edb62c24f7912fd23fecf515b0'
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.unnest(ARRAY[
          'anon',
          'authenticated',
          'service_role',
          'supabase_storage_admin',
          'postgres'
        ]) AS role_name
        WHERE pg_catalog.has_function_privilege(
          role_name,
          function_row.oid,
          'EXECUTE'
        )
      )
  )
  INTO v_ready;

  RETURN pg_catalog.jsonb_build_object(
    'schema_version', 1,
    'status', CASE WHEN v_ready THEN 'ready' ELSE 'held' END,
    'code', CASE WHEN v_ready THEN 'FEATURE_DATABASE_READY' ELSE 'FEATURE_DATABASE_HELD' END,
    'capability_version', 'review-media-feature-v1'
  );
END;
$$;


--
-- Name: get_owned_review_storage_objects(uuid, uuid, text, text[]); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.get_owned_review_storage_objects(p_user_id uuid, p_review_id uuid, p_purpose text, p_names text[]) RETURNS TABLE(id uuid, bucket_id text, name text, owner_id text, version text, updated_at timestamp with time zone, metadata jsonb, archived_at timestamp with time zone, is_delete_marker boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_bucket text;
  v_prefix text;
BEGIN
  v_bucket := CASE p_purpose
    WHEN 'verification' THEN 'review-verifications'
    WHEN 'food' THEN 'review-photos'
    ELSE NULL
  END;
  v_prefix := p_user_id::text || '/reviews/' || p_review_id::text || '/' || p_purpose || '/';
  IF p_user_id IS NULL OR p_review_id IS NULL OR v_bucket IS NULL
    OR p_names IS NULL OR cardinality(p_names) NOT BETWEEN 1 AND 20
    OR (SELECT count(*) FROM unnest(p_names)) <> (SELECT count(DISTINCT object_name) FROM unnest(p_names) AS object_name)
    OR EXISTS (
      SELECT 1 FROM unnest(p_names) AS object_name
      WHERE object_name NOT LIKE v_prefix || '%'
        OR substring(object_name FROM length(v_prefix) + 1) LIKE '%/%'
    )
  THEN
    RAISE EXCEPTION 'invalid_review_storage_lookup' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT object_row.id, object_row.bucket_id, object_row.name, object_row.owner_id,
         object_row.version, object_row.updated_at, object_row.metadata,
         object_row.archived_at, object_row.is_delete_marker
  FROM storage.objects AS object_row
  WHERE object_row.bucket_id = v_bucket
    AND object_row.name = ANY(p_names)
    AND object_row.owner_id = p_user_id::text
    AND object_row.archived_at IS NULL
    AND object_row.is_delete_marker = false
  ORDER BY object_row.name;
END;
$$;


--
-- Name: get_receipt_ocr_credential_release_capability(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.get_receipt_ocr_credential_release_capability() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  catalog_contract ocr_private.receipt_credential_release_catalog_contract%ROWTYPE;
  contract_found boolean := false;
  actual_function_contract jsonb;
  actual_table_contract jsonb;
  actual_ledger_count integer := 0;
  actual_ledger_identity_root text;
  ready boolean := false;
  acl_admitted boolean := false;
BEGIN
  SELECT *
  INTO catalog_contract
  FROM ocr_private.receipt_credential_release_catalog_contract AS contract_row
  WHERE contract_row.capability_version = 'receipt-ocr-definitive-credential-release-v2';
  contract_found := FOUND;

  SELECT pg_catalog.jsonb_object_agg(
           required.signature,
           pg_catalog.jsonb_build_object(
             'definition_sha256', pg_catalog.encode(
               extensions.digest(
                 pg_catalog.convert_to(pg_catalog.pg_get_functiondef(procedure.oid), 'UTF8'),
                 'sha256'
               ),
               'hex'
             ),
             'language', language.lanname,
             'volatility', procedure.provolatile::text,
             'owner', pg_catalog.pg_get_userbyid(procedure.proowner),
             'acl', (
               SELECT coalesce(
                        pg_catalog.jsonb_agg(
                          pg_catalog.jsonb_build_object(
                            'grantor', pg_catalog.pg_get_userbyid(acl.grantor),
                            'grantee', CASE
                              WHEN acl.grantee = 0 THEN 'PUBLIC'
                              ELSE pg_catalog.pg_get_userbyid(acl.grantee)::text
                            END,
                            'privilege', acl.privilege_type,
                            'grantable', acl.is_grantable
                          )
                          ORDER BY acl.grantor, acl.grantee, acl.privilege_type, acl.is_grantable
                        ),
                        '[]'::jsonb
                      )
               FROM pg_catalog.aclexplode(
                 coalesce(
                   procedure.proacl,
                   pg_catalog.acldefault('f', procedure.proowner)
                 )
               ) AS acl
             )
           )
           ORDER BY required.signature
         )
  INTO actual_function_contract
  FROM (VALUES
    ('public.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'::text),
    ('ocr_private.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'::text),
    ('public.get_receipt_ocr_credential_release_capability()'::text),
    ('ocr_private.get_receipt_ocr_credential_release_capability()'::text),
    ('ocr_private.receipt_credential_release_acl_admitted_v2()'::text)
  ) AS required(signature)
  JOIN pg_catalog.pg_proc AS procedure
    ON procedure.oid = pg_catalog.to_regprocedure(required.signature)
  JOIN pg_catalog.pg_language AS language
    ON language.oid = procedure.prolang;

  SELECT pg_catalog.jsonb_object_agg(
           required.relation_name,
           pg_catalog.jsonb_build_object(
             'owner', pg_catalog.pg_get_userbyid(relation.relowner),
             'acl', (
               SELECT coalesce(
                        pg_catalog.jsonb_agg(
                          pg_catalog.jsonb_build_object(
                            'grantor', pg_catalog.pg_get_userbyid(acl.grantor),
                            'grantee', CASE
                              WHEN acl.grantee = 0 THEN 'PUBLIC'
                              ELSE pg_catalog.pg_get_userbyid(acl.grantee)::text
                            END,
                            'privilege', acl.privilege_type,
                            'grantable', acl.is_grantable
                          )
                          ORDER BY acl.grantor, acl.grantee, acl.privilege_type, acl.is_grantable
                        ),
                        '[]'::jsonb
                      )
               FROM pg_catalog.aclexplode(
                 coalesce(
                   relation.relacl,
                   pg_catalog.acldefault('r', relation.relowner)
                 )
               ) AS acl
             )
           )
           ORDER BY required.relation_name
         )
  INTO actual_table_contract
  FROM (VALUES
    ('ocr_private.receipt_credential_rejection_releases'::text),
    ('ocr_private.receipt_credential_release_catalog_contract'::text)
  ) AS required(relation_name)
  JOIN pg_catalog.pg_class AS relation
    ON relation.oid = pg_catalog.to_regclass(required.relation_name);

  IF pg_catalog.to_regclass('supabase_migrations.schema_migrations') IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'held',
      'capability_version', 'receipt-ocr-definitive-credential-release-v2'
    );
  END IF;

    WITH ledger_identity AS (
      SELECT
        migration.version,
        migration.name,
        pg_catalog.cardinality(migration.statements)::integer AS statement_count,
        pg_catalog.encode(
          extensions.digest(
            pg_catalog.convert_to(pg_catalog.array_to_json(migration.statements)::text, 'UTF8'),
            'sha256'
          ),
          'hex'
        ) AS statement_vector_sha256,
        pg_catalog.octet_length(pg_catalog.convert_to(migration.version, 'UTF8'))::text
          || ':' || migration.version || pg_catalog.chr(31)
          || CASE
            WHEN migration.name IS NULL THEN '-1:'
            ELSE pg_catalog.octet_length(pg_catalog.convert_to(migration.name, 'UTF8'))::text
              || ':' || migration.name
          END
          || pg_catalog.chr(31)
          || pg_catalog.cardinality(migration.statements)::text
          || pg_catalog.chr(31)
          || pg_catalog.encode(
            extensions.digest(
              pg_catalog.convert_to(pg_catalog.array_to_json(migration.statements)::text, 'UTF8'),
              'sha256'
            ),
            'hex'
          ) AS row_material
      FROM supabase_migrations.schema_migrations AS migration
    )
    SELECT
      pg_catalog.count(*)::integer,
      pg_catalog.encode(
        extensions.digest(
          pg_catalog.convert_to(
            coalesce(
              pg_catalog.string_agg(
                ledger_identity.row_material,
                pg_catalog.chr(30)
                ORDER BY ledger_identity.version COLLATE "C", ledger_identity.name COLLATE "C"
              ),
              ''
            ),
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      )
    INTO actual_ledger_count, actual_ledger_identity_root
    FROM ledger_identity;


  SELECT ocr_private.receipt_credential_release_acl_admitted_v2()
  INTO acl_admitted;

  ready := contract_found
    AND acl_admitted
    AND catalog_contract.migration_version IS NOT NULL
    AND catalog_contract.migration_name IS NOT NULL
    AND catalog_contract.statement_count IS NOT NULL
    AND catalog_contract.statement_vector_sha256 IS NOT NULL
    AND catalog_contract.ledger_count IS NOT NULL
    AND catalog_contract.ledger_identity_root IS NOT NULL
    AND catalog_contract.sealed_at IS NOT NULL
    AND actual_function_contract IS NOT NULL
    AND actual_function_contract = catalog_contract.function_contract
    AND actual_table_contract IS NOT NULL
    AND actual_table_contract = catalog_contract.table_contract
    AND actual_ledger_count = catalog_contract.ledger_count
    AND actual_ledger_identity_root = catalog_contract.ledger_identity_root
    AND EXISTS (
      SELECT 1
      FROM supabase_migrations.schema_migrations AS migration
      WHERE migration.version = catalog_contract.migration_version
        AND migration.name = catalog_contract.migration_name
        AND pg_catalog.cardinality(migration.statements) = catalog_contract.statement_count
        AND pg_catalog.encode(
          extensions.digest(
            pg_catalog.convert_to(pg_catalog.array_to_json(migration.statements)::text, 'UTF8'),
            'sha256'
          ),
          'hex'
        ) = catalog_contract.statement_vector_sha256
    )
    AND EXISTS (
      SELECT 1
      FROM pg_catalog.pg_class AS relation
      WHERE relation.oid = pg_catalog.to_regclass(
        'ocr_private.receipt_credential_rejection_releases'
      )
        AND relation.relkind = 'r'
        AND relation.relrowsecurity
        AND relation.relforcerowsecurity
        AND (
          SELECT pg_catalog.count(*)
          FROM pg_catalog.pg_constraint AS constraint_row
          WHERE constraint_row.conrelid = relation.oid
            AND constraint_row.contype = 'p'
        ) = 1
        AND EXISTS (
          SELECT 1
          FROM pg_catalog.pg_constraint AS constraint_row
          WHERE constraint_row.conrelid = relation.oid
            AND constraint_row.contype = 'p'
            AND pg_catalog.pg_get_constraintdef(constraint_row.oid, false) =
              'PRIMARY KEY (result_id, claim_token)'
        )
        AND (
          SELECT pg_catalog.count(*)
          FROM pg_catalog.pg_policy AS policy
          WHERE policy.polrelid = relation.oid
        ) = 1
        AND EXISTS (
          SELECT 1
          FROM pg_catalog.pg_policy AS policy
          WHERE policy.polrelid = relation.oid
            AND policy.polname = 'receipt_credential_rejection_releases_owner_only'
            AND policy.polpermissive
            AND policy.polroles = ARRAY['postgres'::regrole::oid]
            AND pg_catalog.pg_get_expr(policy.polqual, policy.polrelid) = 'true'
            AND pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid) = 'true'
        )
    )
    AND EXISTS (
      SELECT 1
      FROM pg_catalog.pg_class AS relation
      WHERE relation.oid = pg_catalog.to_regclass(
        'ocr_private.receipt_credential_release_catalog_contract'
      )
        AND relation.relkind = 'r'
        AND relation.relrowsecurity
        AND relation.relforcerowsecurity
        AND (
          SELECT pg_catalog.count(*)
          FROM pg_catalog.pg_constraint AS constraint_row
          WHERE constraint_row.conrelid = relation.oid
            AND constraint_row.contype = 'p'
        ) = 1
        AND EXISTS (
          SELECT 1
          FROM pg_catalog.pg_constraint AS constraint_row
          WHERE constraint_row.conrelid = relation.oid
            AND constraint_row.contype = 'p'
            AND pg_catalog.pg_get_constraintdef(constraint_row.oid, false) =
              'PRIMARY KEY (capability_version)'
        )
        AND (
          SELECT pg_catalog.count(*)
          FROM pg_catalog.pg_policy AS policy
          WHERE policy.polrelid = relation.oid
        ) = 1
        AND EXISTS (
          SELECT 1
          FROM pg_catalog.pg_policy AS policy
          WHERE policy.polrelid = relation.oid
            AND policy.polname = 'receipt_credential_release_catalog_contract_owner_only'
            AND policy.polpermissive
            AND policy.polroles = ARRAY['postgres'::regrole::oid]
            AND pg_catalog.pg_get_expr(policy.polqual, policy.polrelid) = 'true'
            AND pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid) = 'true'
        )
    )
    AND NOT pg_catalog.has_table_privilege(
      'service_role',
      'ocr_private.receipt_credential_rejection_releases',
      'SELECT,INSERT,UPDATE,DELETE'
    )
    AND NOT pg_catalog.has_table_privilege(
      'service_role',
      'ocr_private.receipt_credential_release_catalog_contract',
      'SELECT,INSERT,UPDATE,DELETE'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM (VALUES
        ('public.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'::text, 'privacy_workflow_owner'::name, 'sql'::name, 'v'::"char", true),
        ('ocr_private.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'::text, 'postgres'::name, 'plpgsql'::name, 'v'::"char", false),
        ('public.get_receipt_ocr_credential_release_capability()'::text, 'privacy_workflow_owner'::name, 'sql'::name, 's'::"char", true),
        ('ocr_private.get_receipt_ocr_credential_release_capability()'::text, 'postgres'::name, 'plpgsql'::name, 's'::"char", false),
        ('ocr_private.receipt_credential_release_acl_admitted_v2()'::text, 'postgres'::name, 'sql'::name, 's'::"char", false)
      ) AS required(signature, owner_name, language_name, volatility, service_executable)
      LEFT JOIN pg_catalog.pg_proc AS procedure
        ON procedure.oid = pg_catalog.to_regprocedure(required.signature)
      LEFT JOIN pg_catalog.pg_language AS language
        ON language.oid = procedure.prolang
      WHERE procedure.oid IS NULL
        OR procedure.proowner <> required.owner_name::regrole
        OR NOT procedure.prosecdef
        OR procedure.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
        OR procedure.provolatile <> required.volatility
        OR language.lanname <> required.language_name
        OR pg_catalog.has_function_privilege('service_role', procedure.oid, 'EXECUTE') IS DISTINCT FROM required.service_executable
        OR pg_catalog.has_function_privilege('anon', procedure.oid, 'EXECUTE')
        OR pg_catalog.has_function_privilege('authenticated', procedure.oid, 'EXECUTE')
    )
    AND EXISTS (
      SELECT 1
      FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.source_signature = 'public.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'
        AND allowed.grantee = 'service_role'
    )
    AND EXISTS (
      SELECT 1
      FROM privacy_retention.g014_nested_helper_allowlist AS allowed
      WHERE allowed.source_signature = 'ocr_private.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'
    )
    AND EXISTS (
      SELECT 1
      FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.source_signature = 'public.get_receipt_ocr_credential_release_capability()'
        AND allowed.grantee = 'service_role'
    )
    AND EXISTS (
      SELECT 1
      FROM privacy_retention.g014_nested_helper_allowlist AS allowed
      WHERE allowed.source_signature = 'ocr_private.get_receipt_ocr_credential_release_capability()'
    )
    AND EXISTS (
      SELECT 1
      FROM privacy_retention.g014_nested_helper_allowlist AS allowed
      WHERE allowed.source_signature = 'ocr_private.receipt_credential_release_acl_admitted_v2()'
    );

  RETURN pg_catalog.jsonb_build_object(
    'schema_version', 1,
    'status', CASE WHEN ready THEN 'ready' ELSE 'held' END,
    'capability_version', 'receipt-ocr-definitive-credential-release-v2'
  );
END;
$$;


--
-- Name: get_receipt_ocr_indeterminate_recovery_capability(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.get_receipt_ocr_indeterminate_recovery_capability() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  catalog_contract ocr_private.receipt_ocr_recovery_catalog_contract%ROWTYPE;
  actual_snapshot jsonb;
  actual_ledger_count integer := 0;
  actual_ledger_identity_root text;
  ready boolean := false;
BEGIN
  SELECT * INTO catalog_contract
  FROM ocr_private.receipt_ocr_recovery_catalog_contract AS contract
  WHERE contract.capability_version = 'receipt-ocr-indeterminate-recovery-v1';
  IF NOT FOUND OR pg_catalog.to_regclass('supabase_migrations.schema_migrations') IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'held',
      'capability_version', 'receipt-ocr-indeterminate-recovery-v1'
    );
  END IF;

  actual_snapshot := ocr_private.receipt_ocr_recovery_catalog_snapshot_v1();

  WITH ledger_identity AS (
    SELECT
      migration.version,
      migration.name,
      pg_catalog.octet_length(pg_catalog.convert_to(migration.version, 'UTF8'))::text
        || ':' || migration.version || pg_catalog.chr(31)
        || CASE WHEN migration.name IS NULL THEN '-1:'
          ELSE pg_catalog.octet_length(pg_catalog.convert_to(migration.name, 'UTF8'))::text
            || ':' || migration.name END
        || pg_catalog.chr(31)
        || pg_catalog.cardinality(migration.statements)::text
        || pg_catalog.chr(31)
        || pg_catalog.encode(
          extensions.digest(
            pg_catalog.convert_to(pg_catalog.array_to_json(migration.statements)::text, 'UTF8'),
            'sha256'
          ),
          'hex'
        ) AS row_material
    FROM supabase_migrations.schema_migrations AS migration
  )
  SELECT
    pg_catalog.count(*)::integer,
    pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(
          coalesce(
            pg_catalog.string_agg(
              ledger_identity.row_material,
              pg_catalog.chr(30)
              ORDER BY ledger_identity.version COLLATE "C", ledger_identity.name COLLATE "C"
            ),
            ''
          ),
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    )
  INTO actual_ledger_count, actual_ledger_identity_root
  FROM ledger_identity;

  ready := catalog_contract.migration_version IS NOT NULL
    AND catalog_contract.migration_name IS NOT NULL
    AND catalog_contract.statement_count IS NOT NULL
    AND catalog_contract.statement_vector_sha256 IS NOT NULL
    AND catalog_contract.predecessor_ledger_count = 107
    AND catalog_contract.predecessor_terminal_identity_root = 'cd04aebfc1efcc5588486adf3b7ba47fc5b5b76e39a9c23e316768f2919d9d9e'
    AND catalog_contract.ledger_count = 108
    AND catalog_contract.ledger_identity_root IS NOT NULL
    AND catalog_contract.sealed_at IS NOT NULL
    AND actual_snapshot->'functions' IS NOT NULL
    AND actual_snapshot->'functions' = catalog_contract.function_contract
    AND actual_snapshot->'tables' IS NOT NULL
    AND actual_snapshot->'tables' = catalog_contract.table_contract
    AND actual_snapshot->'triggers' IS NOT NULL
    AND actual_snapshot->'triggers' = catalog_contract.trigger_contract
    AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(actual_snapshot->'functions')) = 17
    AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(actual_snapshot->'tables')) = 3
    AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(actual_snapshot->'triggers')) = 2
    AND actual_ledger_count = catalog_contract.ledger_count
    AND actual_ledger_identity_root = catalog_contract.ledger_identity_root
    AND EXISTS (
      SELECT 1
      FROM supabase_migrations.schema_migrations AS migration
      WHERE migration.version = catalog_contract.migration_version
        AND migration.name = catalog_contract.migration_name
        AND pg_catalog.cardinality(migration.statements) = catalog_contract.statement_count
        AND pg_catalog.encode(
          extensions.digest(
            pg_catalog.convert_to(pg_catalog.array_to_json(migration.statements)::text, 'UTF8'),
            'sha256'
          ),
          'hex'
        ) = catalog_contract.statement_vector_sha256
    )
    AND NOT EXISTS (
      SELECT 1
      FROM (VALUES
        ('public.reviews'::pg_catalog.regclass, 'receipt_ocr_recovery_photo_update_guard'::name),
        ('ocr_private.receipt_results'::pg_catalog.regclass, 'receipt_ocr_recovery_execution_lease_release'::name)
      ) AS required(relation_oid, trigger_name)
      LEFT JOIN pg_catalog.pg_trigger AS trigger_row
        ON trigger_row.tgrelid = required.relation_oid
       AND trigger_row.tgname = required.trigger_name
       AND NOT trigger_row.tgisinternal
      WHERE trigger_row.oid IS NULL OR trigger_row.tgenabled <> 'O'
    )
    AND EXISTS (
      SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.source_signature = 'public.preview_review_receipt_ocr_indeterminate_recovery(uuid)'
        AND allowed.grantee = 'service_role'
    )
    AND EXISTS (
      SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.source_signature = 'public.recover_review_receipt_ocr_indeterminate(uuid,uuid,uuid,uuid,text,jsonb,text,text,text,text)'
        AND allowed.grantee = 'service_role'
    )
    AND EXISTS (
      SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.source_signature = 'public.authorize_review_receipt_ocr_execution(uuid,uuid,uuid,uuid,text,text,text,jsonb,text,text,text,text)'
        AND allowed.grantee = 'service_role'
    )
    AND EXISTS (
      SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.source_signature = 'public.claim_receipt_ocr_recovery_result(uuid,uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'
        AND allowed.grantee = 'service_role'
    )
    AND EXISTS (
      SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.source_signature = 'public.get_receipt_ocr_indeterminate_recovery_capability()'
        AND allowed.grantee = 'service_role'
    )
    AND ocr_private.receipt_ocr_recovery_acl_admitted_v1();

  RETURN pg_catalog.jsonb_build_object(
    'schema_version', 1,
    'status', CASE WHEN ready THEN 'ready' ELSE 'held' END,
    'capability_version', 'receipt-ocr-indeterminate-recovery-v1'
  );
END;
$$;


--
-- Name: get_review_receipt_ocr_generation(uuid, uuid); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.get_review_receipt_ocr_generation(p_user_id uuid, p_review_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_generation uuid;
BEGIN
  IF p_user_id IS NULL OR p_review_id IS NULL THEN
    RAISE EXCEPTION 'invalid_review_ocr_generation_read' USING ERRCODE = '22023';
  END IF;
  SELECT generation INTO v_generation
  FROM ocr_private.review_generations
  WHERE review_id = p_review_id AND user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('status', 'not_found');
  END IF;
  RETURN pg_catalog.jsonb_build_object(
    'status', 'ready',
    'review_id', p_review_id,
    'generation', v_generation
  );
END;
$$;


--
-- Name: guard_receipt_ocr_recovery_photo_update(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.guard_receipt_ocr_recovery_photo_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.verification_photo IS DISTINCT FROM OLD.verification_photo
    AND OLD.verification_photo IS NOT NULL
    AND OLD.ocr_processed_at IS NULL
    AND OLD.receipt_data IS NULL
    AND OLD.receipt_hash IS NULL
    AND OLD.is_duplicate IS DISTINCT FROM true
    AND EXISTS (
      SELECT 1
      FROM ocr_private.review_generations AS generation_row
      JOIN ocr_private.receipt_ocr_indeterminate_recoveries AS recovery
        ON recovery.review_id = generation_row.review_id
       AND recovery.recovery_generation = generation_row.generation
      WHERE generation_row.review_id = OLD.id
        AND generation_row.user_id = OLD.user_id
    )
  THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_photo_locked' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: mark_receipt_ocr_dispatched(uuid, uuid); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.mark_receipt_ocr_dispatched(p_result_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
BEGIN
  UPDATE ocr_private.receipt_results
  SET dispatch_stage = 'possibly_dispatched',
      updated_at = now()
  WHERE id = p_result_id
    AND status = 'processing'
    AND dispatch_stage = 'reserved'
    AND claim_token = p_claim_token
  RETURNING * INTO v_result;

  IF FOUND THEN
    RETURN jsonb_build_object('status', 'dispatched', 'result_ref', v_result.id);
  END IF;
  SELECT * INTO v_result FROM ocr_private.receipt_results WHERE id = p_result_id;
  IF v_result.status = 'processing'
    AND v_result.dispatch_stage = 'possibly_dispatched'
    AND v_result.claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object('status', 'dispatched', 'result_ref', v_result.id);
  END IF;
  RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
END;
$$;


--
-- Name: mark_receipt_ocr_result_indeterminate(uuid, uuid); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.mark_receipt_ocr_result_indeterminate(p_result_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
BEGIN
  UPDATE ocr_private.receipt_results
  SET status = CASE WHEN result_payload IS NULL THEN 'indeterminate' ELSE 'succeeded' END,
      dispatch_stage = 'uncertain',
      claim_token = NULL,
      completed_at = now(),
      updated_at = now()
  WHERE id = p_result_id
    AND status = 'processing'
    AND dispatch_stage = 'possibly_dispatched'
    AND claim_token = p_claim_token
  RETURNING * INTO v_result;

  IF FOUND THEN
    RETURN jsonb_build_object('status', v_result.status, 'result_ref', v_result.id);
  END IF;
  SELECT * INTO v_result FROM ocr_private.receipt_results WHERE id = p_result_id;
  IF v_result.status = 'succeeded' THEN
    RETURN jsonb_build_object('status', 'succeeded', 'result_ref', v_result.id);
  END IF;
  RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
END;
$$;


--
-- Name: preview_review_receipt_ocr_indeterminate_recovery(uuid); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.preview_review_receipt_ocr_indeterminate_recovery(p_review_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  review_row public.reviews%ROWTYPE;
  current_generation uuid;
  durable_result ocr_private.receipt_results%ROWTYPE;
  current_operation ocr_private.receipt_ocr_indeterminate_recoveries%ROWTYPE;
  processing_count integer;
  indeterminate_count integer;
  snapshot_hash text;
BEGIN
  IF p_review_id IS NULL THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO review_row
  FROM public.reviews AS review
  WHERE review.id = p_review_id;
  IF NOT FOUND
    OR review_row.verification_photo IS NULL
    OR review_row.ocr_processed_at IS NOT NULL
    OR review_row.receipt_data IS NOT NULL
    OR review_row.receipt_hash IS NOT NULL
    OR review_row.is_duplicate IS DISTINCT FROM false
  THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'conflict',
      'review_id', p_review_id,
      'expected_generation', NULL,
      'input_snapshot_hash', NULL,
      'recovery_operation_id', NULL
    );
  END IF;

  SELECT generation INTO current_generation
  FROM ocr_private.review_generations AS generation_row
  WHERE generation_row.review_id = review_row.id
    AND generation_row.user_id = review_row.user_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'expected_generation', NULL, 'input_snapshot_hash', NULL, 'recovery_operation_id', NULL
    );
  END IF;

  SELECT pg_catalog.count(*)::integer INTO processing_count
  FROM ocr_private.receipt_results AS result_row
  WHERE result_row.user_id = review_row.user_id
    AND result_row.generation = current_generation
    AND result_row.status = 'processing';
  IF processing_count > 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'processing', 'review_id', p_review_id,
      'expected_generation', current_generation, 'input_snapshot_hash', NULL, 'recovery_operation_id', NULL
    );
  END IF;

  SELECT pg_catalog.count(*)::integer INTO indeterminate_count
  FROM ocr_private.receipt_results AS result_row
  WHERE result_row.user_id = review_row.user_id
    AND result_row.generation = current_generation
    AND result_row.status = 'indeterminate'
    AND result_row.dispatch_stage = 'uncertain';

  IF indeterminate_count > 1 THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'expected_generation', current_generation, 'input_snapshot_hash', NULL, 'recovery_operation_id', NULL
    );
  END IF;

  IF indeterminate_count = 1 THEN
    SELECT * INTO durable_result
    FROM ocr_private.receipt_results AS result_row
    WHERE result_row.user_id = review_row.user_id
      AND result_row.generation = current_generation
      AND result_row.status = 'indeterminate'
      AND result_row.dispatch_stage = 'uncertain';
    snapshot_hash := pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(
          pg_catalog.jsonb_build_array(
            'receipt-ocr-indeterminate-recovery-snapshot-v1',
            review_row.id,
            review_row.user_id,
            review_row.verification_photo,
            current_generation,
            durable_result.id,
            durable_result.image_hash,
            durable_result.input_context_hash,
            durable_result.provider,
            durable_result.model_policy,
            durable_result.prompt_version,
            durable_result.preprocess_version,
            durable_result.normalization_version,
            durable_result.status,
            durable_result.dispatch_stage,
            durable_result.completed_at,
            durable_result.updated_at
          )::text,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'eligible',
      'review_id', p_review_id,
      'expected_generation', current_generation,
      'input_snapshot_hash', snapshot_hash,
      'recovery_operation_id', NULL
    );
  END IF;

  SELECT * INTO current_operation
  FROM ocr_private.receipt_ocr_indeterminate_recoveries AS operation_row
  WHERE operation_row.review_id = review_row.id
    AND operation_row.recovery_generation = current_generation;
  IF FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'recovery_in_progress',
      'review_id', p_review_id,
      'expected_generation', current_operation.expected_generation,
      'input_snapshot_hash', current_operation.input_snapshot_hash,
      'recovery_operation_id', current_operation.operation_id
    );
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'schema_version', 1,
    'status', 'not_indeterminate',
    'review_id', p_review_id,
    'expected_generation', current_generation,
    'input_snapshot_hash', NULL,
    'recovery_operation_id', NULL
  );
END;
$$;


--
-- Name: publish_review_receipt_ocr_result(uuid, uuid, uuid, uuid, uuid, text, jsonb, boolean); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.publish_review_receipt_ocr_result(p_user_id uuid, p_review_id uuid, p_generation uuid, p_result_id uuid, p_result_revision uuid, p_receipt_hash text, p_receipt_data jsonb, p_is_duplicate boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_generation uuid;
  v_result ocr_private.receipt_results%ROWTYPE;
  v_review public.reviews%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_review_id IS NULL OR p_generation IS NULL
    OR p_result_id IS NULL OR p_result_revision IS NULL OR p_is_duplicate IS NULL
    OR p_receipt_data IS NULL OR pg_catalog.jsonb_typeof(p_receipt_data) <> 'object'
    OR pg_catalog.octet_length(pg_catalog.convert_to(p_receipt_data::text, 'UTF8')) > 32768
    OR (p_receipt_hash IS NOT NULL AND p_receipt_hash !~ '^[0-9a-f]{64}$')
  THEN
    RAISE EXCEPTION 'invalid_review_ocr_publish' USING ERRCODE = '22023';
  END IF;

  -- Match reset's lock order: both paths lock the review row before the
  -- generation row. This removes the reviews -> generations / generations ->
  -- reviews inversion while preserving a fixed stale-generation rejection.
  SELECT * INTO v_review
  FROM public.reviews
  WHERE id = p_review_id AND user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'review_ocr_publish_conflict' USING ERRCODE = '42501';
  END IF;

  SELECT generation INTO v_generation
  FROM ocr_private.review_generations
  WHERE review_id = p_review_id AND user_id = p_user_id
  FOR SHARE;
  IF NOT FOUND OR v_generation IS DISTINCT FROM p_generation THEN
    RAISE EXCEPTION 'review_ocr_generation_stale' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_result
  FROM ocr_private.receipt_results
  WHERE id = p_result_id
    AND user_id = p_user_id
    AND generation = p_generation
    AND status = 'succeeded'
  FOR SHARE;
  IF NOT FOUND
    OR v_result.result_revision IS DISTINCT FROM p_result_revision
    OR NOT ocr_private.valid_result_payload(v_result.result_payload)
    OR NOT (v_result.model_policy ? (v_result.result_payload->>'model'))
  THEN
    RAISE EXCEPTION 'review_ocr_result_stale' USING ERRCODE = '42501';
  END IF;

  UPDATE public.reviews
  SET receipt_hash = p_receipt_hash,
      receipt_data = p_receipt_data,
      is_duplicate = p_is_duplicate,
      ocr_processed_at = now()
  WHERE id = p_review_id
    AND user_id = p_user_id
    AND receipt_hash IS NULL
    AND receipt_data IS NULL
    AND ocr_processed_at IS NULL
    AND is_duplicate = false
  RETURNING * INTO v_review;

  IF NOT FOUND THEN
    SELECT * INTO v_review
    FROM public.reviews
    WHERE id = p_review_id AND user_id = p_user_id;
    IF NOT FOUND
      OR v_review.receipt_hash IS DISTINCT FROM p_receipt_hash
      OR v_review.receipt_data IS DISTINCT FROM p_receipt_data
      OR v_review.is_duplicate IS DISTINCT FROM p_is_duplicate
      OR v_review.ocr_processed_at IS NULL
    THEN
      RAISE EXCEPTION 'review_ocr_publish_conflict' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'status', 'published',
    'review_id', v_review.id,
    'generation', p_generation,
    'result_ref', p_result_id,
    'result_revision', p_result_revision,
    'receipt_hash', v_review.receipt_hash,
    'receipt_data', v_review.receipt_data,
    'is_duplicate', v_review.is_duplicate,
    'ocr_processed_at', v_review.ocr_processed_at
  );
END;
$_$;


--
-- Name: read_receipt_ocr_result(uuid, text, text, text, jsonb, uuid, text, text, text); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.read_receipt_ocr_result(p_user_id uuid, p_image_hash text, p_input_context_hash text, p_provider text, p_model_policy jsonb, p_generation uuid, p_prompt_version text, p_preprocess_version text, p_normalization_version text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
BEGIN
  IF p_user_id IS NULL
    OR p_image_hash !~ '^[0-9a-f]{64}$'
    OR p_input_context_hash !~ '^[0-9a-f]{64}$'
    OR p_provider <> 'gemini'
    OR NOT ocr_private.valid_model_policy(p_model_policy)
    OR p_generation IS NULL
    OR pg_catalog.length(p_prompt_version) NOT BETWEEN 1 AND 160
    OR pg_catalog.length(p_preprocess_version) NOT BETWEEN 1 AND 160
    OR pg_catalog.length(p_normalization_version) NOT BETWEEN 1 AND 160
  THEN
    RAISE EXCEPTION 'invalid_receipt_ocr_read' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_result
  FROM ocr_private.receipt_results
  WHERE user_id = p_user_id
    AND image_hash = p_image_hash
    AND input_context_hash = p_input_context_hash
    AND provider = p_provider
    AND model_policy = p_model_policy
    AND generation = p_generation
    AND prompt_version = p_prompt_version
    AND preprocess_version = p_preprocess_version
    AND normalization_version = p_normalization_version;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('status', 'not_found');
  END IF;
  IF v_result.status = 'succeeded' THEN
    IF NOT ocr_private.valid_result_payload(v_result.result_payload)
      OR NOT (v_result.model_policy ? (v_result.result_payload->>'model'))
    THEN
      RAISE EXCEPTION 'invalid_receipt_ocr_result' USING ERRCODE = '22023';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'status', 'succeeded',
      'result_ref', v_result.id,
      'result_revision', v_result.result_revision,
      'result_payload', v_result.result_payload
    );
  END IF;
  RETURN pg_catalog.jsonb_build_object('status', v_result.status, 'result_ref', v_result.id);
END;
$_$;


--
-- Name: receipt_credential_release_acl_admitted_v2(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.receipt_credential_release_acl_admitted_v2() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH required_functions(signature, owner_name, allowed_nonowner_name) AS (
    VALUES
      ('public.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('public.get_receipt_ocr_credential_release_capability()'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('ocr_private.release_receipt_ocr_definitive_credential_rejection(uuid,uuid)'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.get_receipt_ocr_credential_release_capability()'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.receipt_credential_release_acl_admitted_v2()'::text, 'postgres'::name, 'privacy_workflow_owner'::name)
  ),
  function_catalog AS (
    SELECT
      required.signature,
      procedure.oid,
      procedure.proowner,
      owner_role.oid AS expected_owner,
      allowed_role.oid AS allowed_nonowner
    FROM required_functions AS required
    JOIN pg_catalog.pg_roles AS owner_role
      ON owner_role.rolname = required.owner_name
    LEFT JOIN pg_catalog.pg_roles AS allowed_role
      ON allowed_role.rolname = required.allowed_nonowner_name
    LEFT JOIN pg_catalog.pg_proc AS procedure
      ON procedure.oid = pg_catalog.to_regprocedure(required.signature)
  ),
  actual_function_acl AS (
    SELECT
      function_row.signature,
      acl.grantor,
      acl.grantee,
      acl.privilege_type,
      acl.is_grantable
    FROM function_catalog AS function_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      coalesce(
        (SELECT procedure.proacl FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = function_row.oid),
        pg_catalog.acldefault('f', function_row.proowner)
      )
    ) AS acl
  ),
  expected_function_acl AS (
    SELECT
      function_row.signature,
      acl.grantor,
      acl.grantee,
      acl.privilege_type,
      acl.is_grantable
    FROM function_catalog AS function_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      pg_catalog.acldefault('f', function_row.expected_owner)
    ) AS acl
    WHERE acl.grantee = function_row.expected_owner
    UNION ALL
    SELECT
      function_row.signature,
      function_row.expected_owner,
      function_row.allowed_nonowner,
      'EXECUTE'::text,
      false
    FROM function_catalog AS function_row
    WHERE function_row.allowed_nonowner IS NOT NULL
  ),
  required_tables(relation_name, owner_name) AS (
    VALUES
      ('ocr_private.receipt_credential_rejection_releases'::text, 'postgres'::name),
      ('ocr_private.receipt_credential_release_catalog_contract'::text, 'postgres'::name)
  ),
  table_catalog AS (
    SELECT
      required.relation_name,
      relation.oid,
      relation.relowner,
      owner_role.oid AS expected_owner
    FROM required_tables AS required
    JOIN pg_catalog.pg_roles AS owner_role
      ON owner_role.rolname = required.owner_name
    LEFT JOIN pg_catalog.pg_class AS relation
      ON relation.oid = pg_catalog.to_regclass(required.relation_name)
  ),
  actual_table_acl AS (
    SELECT
      table_row.relation_name,
      acl.grantor,
      acl.grantee,
      acl.privilege_type,
      acl.is_grantable
    FROM table_catalog AS table_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      coalesce(
        (SELECT relation.relacl FROM pg_catalog.pg_class AS relation WHERE relation.oid = table_row.oid),
        pg_catalog.acldefault('r', table_row.relowner)
      )
    ) AS acl
  ),
  expected_table_acl AS (
    SELECT
      table_row.relation_name,
      acl.grantor,
      acl.grantee,
      acl.privilege_type,
      acl.is_grantable
    FROM table_catalog AS table_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      pg_catalog.acldefault('r', table_row.expected_owner)
    ) AS acl
    WHERE acl.grantee = table_row.expected_owner
  )
  SELECT
    (SELECT pg_catalog.count(*) FROM function_catalog) = 5
    AND NOT EXISTS (
      SELECT 1
      FROM function_catalog AS function_row
      WHERE function_row.oid IS NULL
        OR function_row.proowner IS DISTINCT FROM function_row.expected_owner
    )
    AND NOT EXISTS (
      (SELECT * FROM actual_function_acl)
      EXCEPT
      (SELECT * FROM expected_function_acl)
    )
    AND NOT EXISTS (
      (SELECT * FROM expected_function_acl)
      EXCEPT
      (SELECT * FROM actual_function_acl)
    )
    AND (SELECT pg_catalog.count(*) FROM table_catalog) = 2
    AND NOT EXISTS (
      SELECT 1
      FROM table_catalog AS table_row
      WHERE table_row.oid IS NULL
        OR table_row.relowner IS DISTINCT FROM table_row.expected_owner
    )
    AND NOT EXISTS (
      (SELECT * FROM actual_table_acl)
      EXCEPT
      (SELECT * FROM expected_table_acl)
    )
    AND NOT EXISTS (
      (SELECT * FROM expected_table_acl)
      EXCEPT
      (SELECT * FROM actual_table_acl)
    );
$$;


--
-- Name: receipt_ocr_recovery_acl_admitted_v1(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.receipt_ocr_recovery_acl_admitted_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH required_functions(signature, owner_name, allowed_nonowner_name) AS (
    VALUES
      ('public.preview_review_receipt_ocr_indeterminate_recovery(uuid)'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('public.recover_review_receipt_ocr_indeterminate(uuid,uuid,uuid,uuid,text,jsonb,text,text,text,text)'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('public.authorize_review_receipt_ocr_execution(uuid,uuid,uuid,uuid,text,text,text,jsonb,text,text,text,text)'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('public.claim_receipt_ocr_result(uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('public.claim_receipt_ocr_recovery_result(uuid,uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('public.get_receipt_ocr_indeterminate_recovery_capability()'::text, 'privacy_workflow_owner'::name, 'service_role'::name),
      ('ocr_private.preview_review_receipt_ocr_indeterminate_recovery(uuid)'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.recover_review_receipt_ocr_indeterminate(uuid,uuid,uuid,uuid,text,jsonb,text,text,text,text)'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.authorize_review_receipt_ocr_execution(uuid,uuid,uuid,uuid,text,text,text,jsonb,text,text,text,text)'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.claim_receipt_ocr_result(uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.claim_receipt_ocr_recovery_result(uuid,uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.claim_receipt_ocr_result_core(uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text, 'postgres'::name, NULL::name),
      ('ocr_private.release_receipt_ocr_recovery_execution_lease()'::text, 'postgres'::name, NULL::name),
      ('ocr_private.guard_receipt_ocr_recovery_photo_update()'::text, 'postgres'::name, NULL::name),
      ('ocr_private.receipt_ocr_recovery_catalog_snapshot_v1()'::text, 'postgres'::name, NULL::name),
      ('ocr_private.get_receipt_ocr_indeterminate_recovery_capability()'::text, 'postgres'::name, 'privacy_workflow_owner'::name),
      ('ocr_private.receipt_ocr_recovery_acl_admitted_v1()'::text, 'postgres'::name, 'privacy_workflow_owner'::name)
  ),
  function_catalog AS (
    SELECT required.signature, procedure.oid, procedure.proowner,
      owner_role.oid AS expected_owner, allowed_role.oid AS allowed_nonowner
    FROM required_functions AS required
    JOIN pg_catalog.pg_roles AS owner_role ON owner_role.rolname = required.owner_name
    LEFT JOIN pg_catalog.pg_roles AS allowed_role ON allowed_role.rolname = required.allowed_nonowner_name
    LEFT JOIN pg_catalog.pg_proc AS procedure
      ON procedure.oid = pg_catalog.to_regprocedure(required.signature)
  ),
  actual_function_acl AS (
    SELECT function_row.signature, acl.grantor, acl.grantee,
      acl.privilege_type, acl.is_grantable
    FROM function_catalog AS function_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      coalesce(
        (SELECT procedure.proacl FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = function_row.oid),
        pg_catalog.acldefault('f', function_row.proowner)
      )
    ) AS acl
  ),
  expected_function_acl AS (
    SELECT function_row.signature, acl.grantor, acl.grantee,
      acl.privilege_type, acl.is_grantable
    FROM function_catalog AS function_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      pg_catalog.acldefault('f', function_row.expected_owner)
    ) AS acl
    WHERE acl.grantee = function_row.expected_owner
    UNION ALL
    SELECT function_row.signature, function_row.expected_owner,
      function_row.allowed_nonowner, 'EXECUTE'::text, false
    FROM function_catalog AS function_row
    WHERE function_row.allowed_nonowner IS NOT NULL
  ),
  required_tables(relation_name, owner_name) AS (
    VALUES
      ('ocr_private.receipt_ocr_indeterminate_recoveries'::text, 'postgres'::name),
      ('ocr_private.receipt_ocr_recovery_execution_leases'::text, 'postgres'::name),
      ('ocr_private.receipt_ocr_recovery_catalog_contract'::text, 'postgres'::name)
  ),
  table_catalog AS (
    SELECT required.relation_name, relation.oid, relation.relowner,
      owner_role.oid AS expected_owner
    FROM required_tables AS required
    JOIN pg_catalog.pg_roles AS owner_role ON owner_role.rolname = required.owner_name
    LEFT JOIN pg_catalog.pg_class AS relation
      ON relation.oid = pg_catalog.to_regclass(required.relation_name)
  ),
  actual_table_acl AS (
    SELECT table_row.relation_name, acl.grantor, acl.grantee,
      acl.privilege_type, acl.is_grantable
    FROM table_catalog AS table_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      coalesce(
        (SELECT relation.relacl FROM pg_catalog.pg_class AS relation WHERE relation.oid = table_row.oid),
        pg_catalog.acldefault('r', table_row.relowner)
      )
    ) AS acl
  ),
  expected_table_acl AS (
    SELECT table_row.relation_name, acl.grantor, acl.grantee,
      acl.privilege_type, acl.is_grantable
    FROM table_catalog AS table_row
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      pg_catalog.acldefault('r', table_row.expected_owner)
    ) AS acl
    WHERE acl.grantee = table_row.expected_owner
  )
  SELECT
    (SELECT pg_catalog.count(*) FROM function_catalog) = 17
    AND NOT EXISTS (
      SELECT 1 FROM function_catalog AS function_row
      WHERE function_row.oid IS NULL OR function_row.proowner IS DISTINCT FROM function_row.expected_owner
    )
    AND NOT EXISTS ((SELECT * FROM actual_function_acl) EXCEPT (SELECT * FROM expected_function_acl))
    AND NOT EXISTS ((SELECT * FROM expected_function_acl) EXCEPT (SELECT * FROM actual_function_acl))
    AND (SELECT pg_catalog.count(*) FROM table_catalog) = 3
    AND NOT EXISTS (
      SELECT 1 FROM table_catalog AS table_row
      WHERE table_row.oid IS NULL OR table_row.relowner IS DISTINCT FROM table_row.expected_owner
    )
    AND NOT EXISTS ((SELECT * FROM actual_table_acl) EXCEPT (SELECT * FROM expected_table_acl))
    AND NOT EXISTS ((SELECT * FROM expected_table_acl) EXCEPT (SELECT * FROM actual_table_acl));
$$;


--
-- Name: receipt_ocr_recovery_catalog_snapshot_v1(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.receipt_ocr_recovery_catalog_snapshot_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  function_contract jsonb;
  table_contract jsonb;
  trigger_contract jsonb;
BEGIN
  SELECT pg_catalog.jsonb_object_agg(
           required.signature,
           pg_catalog.jsonb_build_object(
             'definition_sha256', pg_catalog.encode(
               extensions.digest(
                 pg_catalog.convert_to(pg_catalog.pg_get_functiondef(procedure.oid), 'UTF8'),
                 'sha256'
               ),
               'hex'
             ),
             'language', language.lanname,
             'volatility', procedure.provolatile::text,
             'securityDefiner', procedure.prosecdef,
             'configuration', procedure.proconfig,
             'owner', pg_catalog.pg_get_userbyid(procedure.proowner),
             'acl', (
               SELECT coalesce(
                        pg_catalog.jsonb_agg(
                          pg_catalog.jsonb_build_object(
                            'grantor', pg_catalog.pg_get_userbyid(acl.grantor),
                            'grantee', CASE
                              WHEN acl.grantee = 0 THEN 'PUBLIC'
                              ELSE pg_catalog.pg_get_userbyid(acl.grantee)::text
                            END,
                            'privilege', acl.privilege_type,
                            'grantable', acl.is_grantable
                          )
                          ORDER BY acl.grantor, acl.grantee, acl.privilege_type, acl.is_grantable
                        ),
                        '[]'::jsonb
                      )
               FROM pg_catalog.aclexplode(
                 coalesce(procedure.proacl, pg_catalog.acldefault('f', procedure.proowner))
               ) AS acl
             )
           )
           ORDER BY required.signature
         )
  INTO function_contract
  FROM (VALUES
    ('public.preview_review_receipt_ocr_indeterminate_recovery(uuid)'::text),
    ('public.recover_review_receipt_ocr_indeterminate(uuid,uuid,uuid,uuid,text,jsonb,text,text,text,text)'::text),
    ('public.authorize_review_receipt_ocr_execution(uuid,uuid,uuid,uuid,text,text,text,jsonb,text,text,text,text)'::text),
    ('public.claim_receipt_ocr_result(uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text),
    ('public.claim_receipt_ocr_recovery_result(uuid,uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text),
    ('public.get_receipt_ocr_indeterminate_recovery_capability()'::text),
    ('ocr_private.preview_review_receipt_ocr_indeterminate_recovery(uuid)'::text),
    ('ocr_private.recover_review_receipt_ocr_indeterminate(uuid,uuid,uuid,uuid,text,jsonb,text,text,text,text)'::text),
    ('ocr_private.authorize_review_receipt_ocr_execution(uuid,uuid,uuid,uuid,text,text,text,jsonb,text,text,text,text)'::text),
    ('ocr_private.claim_receipt_ocr_result(uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text),
    ('ocr_private.claim_receipt_ocr_recovery_result(uuid,uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text),
    ('ocr_private.claim_receipt_ocr_result_core(uuid,text,text,text,jsonb,uuid,text,text,text,uuid,boolean)'::text),
    ('ocr_private.release_receipt_ocr_recovery_execution_lease()'::text),
    ('ocr_private.guard_receipt_ocr_recovery_photo_update()'::text),
    ('ocr_private.get_receipt_ocr_indeterminate_recovery_capability()'::text),
    ('ocr_private.receipt_ocr_recovery_acl_admitted_v1()'::text),
    ('ocr_private.receipt_ocr_recovery_catalog_snapshot_v1()'::text)
  ) AS required(signature)
  JOIN pg_catalog.pg_proc AS procedure
    ON procedure.oid = pg_catalog.to_regprocedure(required.signature)
  JOIN pg_catalog.pg_language AS language
    ON language.oid = procedure.prolang;

  SELECT pg_catalog.jsonb_object_agg(
           required.relation_name,
           pg_catalog.jsonb_build_object(
             'owner', pg_catalog.pg_get_userbyid(relation.relowner),
             'kind', relation.relkind::text,
             'rowSecurity', relation.relrowsecurity,
             'forceRowSecurity', relation.relforcerowsecurity,
             'acl', (
               SELECT coalesce(
                        pg_catalog.jsonb_agg(
                          pg_catalog.jsonb_build_object(
                            'grantor', pg_catalog.pg_get_userbyid(acl.grantor),
                            'grantee', CASE
                              WHEN acl.grantee = 0 THEN 'PUBLIC'
                              ELSE pg_catalog.pg_get_userbyid(acl.grantee)::text
                            END,
                            'privilege', acl.privilege_type,
                            'grantable', acl.is_grantable
                          )
                          ORDER BY acl.grantor, acl.grantee, acl.privilege_type, acl.is_grantable
                        ),
                        '[]'::jsonb
                      )
               FROM pg_catalog.aclexplode(
                 coalesce(relation.relacl, pg_catalog.acldefault('r', relation.relowner))
               ) AS acl
             ),
             'columns', (
               SELECT coalesce(
                        pg_catalog.jsonb_agg(
                          pg_catalog.jsonb_build_object(
                            'name', attribute.attname,
                            'type', pg_catalog.format_type(attribute.atttypid, attribute.atttypmod),
                            'notNull', attribute.attnotnull,
                            'identity', attribute.attidentity::text,
                            'generated', attribute.attgenerated::text,
                            'default', pg_catalog.pg_get_expr(default_value.adbin, default_value.adrelid)
                          ) ORDER BY attribute.attnum
                        ),
                        '[]'::jsonb
                      )
               FROM pg_catalog.pg_attribute AS attribute
               LEFT JOIN pg_catalog.pg_attrdef AS default_value
                 ON default_value.adrelid = attribute.attrelid
                AND default_value.adnum = attribute.attnum
               WHERE attribute.attrelid = relation.oid
                 AND attribute.attnum > 0
                 AND NOT attribute.attisdropped
             ),
             'constraints', (
               SELECT coalesce(
                        pg_catalog.jsonb_agg(
                          pg_catalog.jsonb_build_object(
                            'name', constraint_row.conname,
                            'type', constraint_row.contype::text,
                            'definition', pg_catalog.pg_get_constraintdef(constraint_row.oid, false)
                          ) ORDER BY constraint_row.conname
                        ),
                        '[]'::jsonb
                      )
               FROM pg_catalog.pg_constraint AS constraint_row
               WHERE constraint_row.conrelid = relation.oid
             ),
             'policies', (
               SELECT coalesce(
                        pg_catalog.jsonb_agg(
                          pg_catalog.jsonb_build_object(
                            'name', policy.polname,
                            'permissive', policy.polpermissive,
                            'command', policy.polcmd::text,
                            'roles', (
                              SELECT coalesce(
                                       pg_catalog.jsonb_agg(
                                         CASE WHEN role_oid = 0 THEN 'PUBLIC'
                                           ELSE pg_catalog.pg_get_userbyid(role_oid)::text END
                                         ORDER BY role_oid
                                       ),
                                       '[]'::jsonb
                                     )
                              FROM pg_catalog.unnest(policy.polroles) AS role_value(role_oid)
                            ),
                            'using', pg_catalog.pg_get_expr(policy.polqual, policy.polrelid),
                            'withCheck', pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid)
                          ) ORDER BY policy.polname
                        ),
                        '[]'::jsonb
                      )
               FROM pg_catalog.pg_policy AS policy
               WHERE policy.polrelid = relation.oid
             )
           )
           ORDER BY required.relation_name
         )
  INTO table_contract
  FROM (VALUES
    ('ocr_private.receipt_ocr_indeterminate_recoveries'::text),
    ('ocr_private.receipt_ocr_recovery_execution_leases'::text),
    ('ocr_private.receipt_ocr_recovery_catalog_contract'::text)
  ) AS required(relation_name)
  JOIN pg_catalog.pg_class AS relation
    ON relation.oid = pg_catalog.to_regclass(required.relation_name);

  SELECT pg_catalog.jsonb_object_agg(
           required.trigger_key,
           pg_catalog.jsonb_build_object(
             'definition_sha256', pg_catalog.encode(
               extensions.digest(
                 pg_catalog.convert_to(pg_catalog.pg_get_triggerdef(trigger_row.oid, false), 'UTF8'),
                 'sha256'
               ),
               'hex'
             ),
             'enabled', trigger_row.tgenabled::text,
             'internal', trigger_row.tgisinternal,
             'function', trigger_row.tgfoid::pg_catalog.regprocedure::text
           )
           ORDER BY required.trigger_key
         )
  INTO trigger_contract
  FROM (VALUES
    ('public.reviews.receipt_ocr_recovery_photo_update_guard'::text, 'public.reviews'::pg_catalog.regclass, 'receipt_ocr_recovery_photo_update_guard'::name),
    ('ocr_private.receipt_results.receipt_ocr_recovery_execution_lease_release'::text, 'ocr_private.receipt_results'::pg_catalog.regclass, 'receipt_ocr_recovery_execution_lease_release'::name)
  ) AS required(trigger_key, relation_oid, trigger_name)
  JOIN pg_catalog.pg_trigger AS trigger_row
    ON trigger_row.tgrelid = required.relation_oid
   AND trigger_row.tgname = required.trigger_name
   AND NOT trigger_row.tgisinternal;

  RETURN pg_catalog.jsonb_build_object(
    'functions', function_contract,
    'tables', table_contract,
    'triggers', trigger_contract
  );
END;
$$;


--
-- Name: recover_review_receipt_ocr_indeterminate(uuid, uuid, uuid, uuid, text, jsonb, text, text, text, text); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.recover_review_receipt_ocr_indeterminate(p_actor_user_id uuid, p_review_id uuid, p_recovery_operation_id uuid, p_expected_generation uuid, p_input_snapshot_hash text, p_model_policy jsonb, p_thinking_level text, p_prompt_version text, p_preprocess_version text, p_normalization_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  review_row public.reviews%ROWTYPE;
  current_generation uuid;
  recovery_generation uuid;
  durable_result ocr_private.receipt_results%ROWTYPE;
  prior_operation ocr_private.receipt_ocr_indeterminate_recoveries%ROWTYPE;
  result_row ocr_private.receipt_results%ROWTYPE;
  processing_count integer := 0;
  indeterminate_count integer := 0;
  snapshot_hash text;
  verification_photo_hash text;
BEGIN
  IF p_actor_user_id IS NULL
    OR p_review_id IS NULL
    OR p_recovery_operation_id IS NULL
    OR p_expected_generation IS NULL
    OR p_input_snapshot_hash !~ '^[0-9a-f]{64}$'
    OR NOT ocr_private.valid_model_policy(p_model_policy)
    OR p_thinking_level NOT IN ('LOW', 'MEDIUM', 'HIGH')
    OR p_prompt_version IS DISTINCT FROM 'admin-receipt-summary-v1'
    OR p_preprocess_version IS DISTINCT FROM 'admin-canonical-jpeg-v2'
    OR p_normalization_version IS DISTINCT FROM 'receipt-normalization-v1'
  THEN
    RAISE EXCEPTION 'receipt_ocr_recovery_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('receipt-ocr-recovery-operation:' || p_recovery_operation_id::text, 0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('receipt-ocr-recovery-review:' || p_review_id::text, 0)
  );

  -- Keep the established publish/reset order: review row, generation row, then
  -- durable result rows. This makes a concurrent late publish either win first
  -- or observe a stale generation, never a half-rotated recovery.
  SELECT * INTO review_row
  FROM public.reviews AS review
  WHERE review.id = p_review_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;

  SELECT generation INTO current_generation
  FROM ocr_private.review_generations AS generation_row
  WHERE generation_row.review_id = review_row.id
    AND generation_row.user_id = review_row.user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;

  SELECT * INTO prior_operation
  FROM ocr_private.receipt_ocr_indeterminate_recoveries AS operation_row
  WHERE operation_row.operation_id = p_recovery_operation_id;
  IF FOUND THEN
    IF prior_operation.review_id IS DISTINCT FROM p_review_id
      OR prior_operation.expected_generation IS DISTINCT FROM p_expected_generation
      OR prior_operation.input_snapshot_hash IS DISTINCT FROM p_input_snapshot_hash
    THEN
      RETURN pg_catalog.jsonb_build_object(
        'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
        'operation_id', p_recovery_operation_id
      );
    END IF;
    IF current_generation IS DISTINCT FROM prior_operation.recovery_generation THEN
      RETURN pg_catalog.jsonb_build_object(
        'schema_version', 1, 'status', 'stale_operation', 'review_id', p_review_id,
        'operation_id', p_recovery_operation_id
      );
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1,
      'status', 'rotated',
      'review_id', p_review_id,
      'operation_id', p_recovery_operation_id,
      'previous_generation', prior_operation.expected_generation,
      'generation', prior_operation.recovery_generation,
      'input_snapshot_hash', prior_operation.input_snapshot_hash,
      'idempotent', true,
      'provider_outcome_certain', false,
      'model_policy', prior_operation.model_policy,
      'thinking_level', prior_operation.thinking_level
    );
  END IF;

  IF review_row.verification_photo IS NULL
    OR review_row.ocr_processed_at IS NOT NULL
    OR review_row.receipt_data IS NOT NULL
    OR review_row.receipt_hash IS NOT NULL
    OR review_row.is_duplicate IS DISTINCT FROM false
    OR current_generation IS DISTINCT FROM p_expected_generation
  THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;

  FOR result_row IN
    SELECT *
    FROM ocr_private.receipt_results AS locked_result
    WHERE locked_result.user_id = review_row.user_id
      AND locked_result.generation = current_generation
    ORDER BY locked_result.id
    FOR UPDATE
  LOOP
    IF result_row.status = 'processing' THEN
      processing_count := processing_count + 1;
    ELSIF result_row.status = 'indeterminate' AND result_row.dispatch_stage = 'uncertain' THEN
      indeterminate_count := indeterminate_count + 1;
      durable_result := result_row;
    END IF;
  END LOOP;

  IF processing_count > 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'processing', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;
  IF indeterminate_count = 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'not_indeterminate', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;
  IF indeterminate_count <> 1 THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;

  snapshot_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        pg_catalog.jsonb_build_array(
          'receipt-ocr-indeterminate-recovery-snapshot-v1',
          review_row.id,
          review_row.user_id,
          review_row.verification_photo,
          current_generation,
          durable_result.id,
          durable_result.image_hash,
          durable_result.input_context_hash,
          durable_result.provider,
          durable_result.model_policy,
          durable_result.prompt_version,
          durable_result.preprocess_version,
          durable_result.normalization_version,
          durable_result.status,
          durable_result.dispatch_stage,
          durable_result.completed_at,
          durable_result.updated_at
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  IF snapshot_hash IS DISTINCT FROM p_input_snapshot_hash THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;

  verification_photo_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(review_row.verification_photo, 'UTF8'), 'sha256'),
    'hex'
  );

  recovery_generation := extensions.gen_random_uuid();
  UPDATE ocr_private.review_generations AS generation_row
  SET generation = recovery_generation,
      updated_at = pg_catalog.clock_timestamp()
  WHERE generation_row.review_id = review_row.id
    AND generation_row.user_id = review_row.user_id
    AND generation_row.generation = current_generation;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'schema_version', 1, 'status', 'conflict', 'review_id', p_review_id,
      'operation_id', p_recovery_operation_id
    );
  END IF;

  INSERT INTO ocr_private.receipt_ocr_indeterminate_recoveries (
    operation_id,
    review_id,
    actor_user_id,
    expected_generation,
    recovery_generation,
    input_snapshot_hash,
    verification_photo_hash,
    expected_image_hash,
    model_policy,
    thinking_level,
    prompt_version,
    preprocess_version,
    normalization_version
  ) VALUES (
    p_recovery_operation_id,
    review_row.id,
    p_actor_user_id,
    current_generation,
    recovery_generation,
    snapshot_hash,
    verification_photo_hash,
    durable_result.image_hash,
    p_model_policy,
    p_thinking_level,
    p_prompt_version,
    p_preprocess_version,
    p_normalization_version
  );

  RETURN pg_catalog.jsonb_build_object(
    'schema_version', 1,
    'status', 'rotated',
    'review_id', p_review_id,
    'operation_id', p_recovery_operation_id,
    'previous_generation', current_generation,
    'generation', recovery_generation,
    'input_snapshot_hash', snapshot_hash,
    'idempotent', false,
    'provider_outcome_certain', false,
    'model_policy', p_model_policy,
    'thinking_level', p_thinking_level
  );
END;
$_$;


--
-- Name: register_review_ocr_generation(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.register_review_ocr_generation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO ocr_private.review_generations (review_id, user_id, generation)
  VALUES (NEW.id, NEW.user_id, extensions.gen_random_uuid())
  ON CONFLICT (review_id) DO UPDATE SET
    user_id = EXCLUDED.user_id,
    generation = extensions.gen_random_uuid(),
    updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: release_receipt_ocr_claim(uuid, uuid); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.release_receipt_ocr_claim(p_result_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_restored boolean := false;
BEGIN
  UPDATE ocr_private.receipt_results
  SET status = 'succeeded',
      dispatch_stage = 'completed',
      claim_token = NULL,
      completed_at = now(),
      updated_at = now()
  WHERE id = p_result_id
    AND status = 'processing'
    AND dispatch_stage = 'reserved'
    AND claim_token = p_claim_token
    AND result_payload IS NOT NULL;
  v_restored := FOUND;

  DELETE FROM ocr_private.receipt_results
  WHERE id = p_result_id
    AND status = 'processing'
    AND dispatch_stage = 'reserved'
    AND claim_token = p_claim_token
    AND result_payload IS NULL;
  IF NOT FOUND AND NOT v_restored THEN
    RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object('status', 'released', 'result_ref', p_result_id);
END;
$$;


--
-- Name: release_receipt_ocr_definitive_credential_rejection(uuid, uuid); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.release_receipt_ocr_definitive_credential_rejection(p_result_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  durable_result ocr_private.receipt_results%ROWTYPE;
  prior_release ocr_private.receipt_credential_rejection_releases%ROWTYPE;
  release_disposition text;
BEGIN
  IF p_result_id IS NULL OR p_claim_token IS NULL THEN
    RAISE EXCEPTION 'receipt_ocr_credential_release_invalid' USING ERRCODE = '22023';
  END IF;


  IF ocr_private.get_receipt_ocr_credential_release_capability() IS DISTINCT FROM
    '{"schema_version":1,"status":"ready","capability_version":"receipt-ocr-definitive-credential-release-v2"}'::jsonb
  THEN
    RAISE EXCEPTION 'receipt_ocr_credential_release_capability_held' USING ERRCODE = '55000';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'receipt-ocr-definitive-credential-rejection:' || p_result_id::text,
      0
    )
  );

  SELECT *
  INTO prior_release
  FROM ocr_private.receipt_credential_rejection_releases AS release_row
  WHERE release_row.result_id = p_result_id
    AND release_row.claim_token = p_claim_token;

  IF FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'status', 'released',
      'result_ref', prior_release.result_id,
      'disposition', prior_release.disposition,
      'result_revision', prior_release.result_revision,
      'idempotent', true
    );
  END IF;

  SELECT *
  INTO durable_result
  FROM ocr_private.receipt_results AS result_row
  WHERE result_row.id = p_result_id
  FOR UPDATE;

  IF NOT FOUND
    OR durable_result.status <> 'processing'
    OR durable_result.dispatch_stage <> 'possibly_dispatched'
    OR durable_result.claim_token IS DISTINCT FROM p_claim_token
  THEN
    RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
  END IF;

  IF durable_result.result_payload IS NOT NULL
    AND (
      NOT ocr_private.valid_result_payload(durable_result.result_payload)
      OR durable_result.provider IS DISTINCT FROM durable_result.result_payload->>'provider'
      OR NOT (durable_result.model_policy ? (durable_result.result_payload->>'model'))
      OR durable_result.normalization_version IS DISTINCT FROM durable_result.result_payload->>'normalization_version'
    )
  THEN
    RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
  END IF;

  release_disposition := CASE
    WHEN durable_result.result_payload IS NULL THEN 'deleted'
    ELSE 'restored'
  END;

  INSERT INTO ocr_private.receipt_credential_rejection_releases (
    result_id,
    claim_token,
    disposition,
    result_revision
  ) VALUES (
    durable_result.id,
    p_claim_token,
    release_disposition,
    CASE WHEN release_disposition = 'restored' THEN durable_result.result_revision ELSE NULL END
  );

  IF release_disposition = 'restored' THEN
    UPDATE ocr_private.receipt_results AS result_row
    SET status = 'succeeded',
        dispatch_stage = 'completed',
        claim_token = NULL,
        completed_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    WHERE result_row.id = p_result_id
      AND result_row.status = 'processing'
      AND result_row.dispatch_stage = 'possibly_dispatched'
      AND result_row.claim_token = p_claim_token
      AND result_row.result_payload IS NOT NULL
      AND result_row.result_revision IS NOT NULL;
  ELSE
    DELETE FROM ocr_private.receipt_results AS result_row
    WHERE result_row.id = p_result_id
      AND result_row.status = 'processing'
      AND result_row.dispatch_stage = 'possibly_dispatched'
      AND result_row.claim_token = p_claim_token
      AND result_row.result_payload IS NULL
      AND result_row.result_revision IS NULL;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'status', 'released',
    'result_ref', durable_result.id,
    'disposition', release_disposition,
    'result_revision', CASE
      WHEN release_disposition = 'restored' THEN durable_result.result_revision
      ELSE NULL
    END,
    'idempotent', false
  );
END;
$$;


--
-- Name: release_receipt_ocr_recovery_execution_lease(); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.release_receipt_ocr_recovery_execution_lease() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status = 'processing' AND NEW.status <> 'processing' THEN
    DELETE FROM ocr_private.receipt_ocr_recovery_execution_leases AS lease
    WHERE lease.result_id = OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: resolve_ocr_daily_quota(uuid, boolean); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.resolve_ocr_daily_quota(p_operation_id uuid, p_reserve boolean) RETURNS TABLE(allowed boolean, used_count integer, quota_limit integer, remaining_count integer, unlimited boolean, reset_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_quota_day date := (pg_catalog.clock_timestamp() AT TIME ZONE 'Asia/Seoul')::date;
  v_reset_at timestamptz;
  v_used integer := 0;
  v_unlimited boolean := false;
  v_existing_user_id uuid;
  v_existing_quota_day date;
  v_allowed boolean;
BEGIN
  IF auth.role() <> 'authenticated' OR v_user_id IS NULL OR p_reserve IS NULL THEN
    RAISE EXCEPTION 'ocr_quota_authenticated_user_required' USING ERRCODE = '42501';
  END IF;
  IF p_reserve AND p_operation_id IS NULL THEN
    RAISE EXCEPTION 'ocr_quota_operation_required' USING ERRCODE = '22023';
  END IF;

  v_reset_at := ((v_quota_day + 1)::timestamp AT TIME ZONE 'Asia/Seoul');

  WITH expired AS (
    SELECT reservations.ctid
      FROM ocr_private.ocr_daily_quota_reservations AS reservations
     WHERE reservations.quota_day < v_quota_day
     ORDER BY reservations.quota_day, reservations.reserved_at
     LIMIT 100
  )
  DELETE FROM ocr_private.ocr_daily_quota_reservations AS reservations
  USING expired
  WHERE reservations.ctid = expired.ctid;

  SELECT EXISTS (
    SELECT 1
      FROM public.user_roles AS roles
      JOIN public.user_account_status AS account_status
        ON account_status.user_id = roles.user_id
       AND account_status.account_status = 'active'
     WHERE roles.user_id = v_user_id
       AND roles.role = 'admin'
  ) INTO v_unlimited;

  IF p_reserve THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('ocr-operation:' || p_operation_id::text, 0)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_user_id::text || ':' || v_quota_day::text, 0)
    );

    SELECT reservations.user_id, reservations.quota_day
      INTO v_existing_user_id, v_existing_quota_day
      FROM ocr_private.ocr_daily_quota_reservations AS reservations
     WHERE reservations.operation_id = p_operation_id;

    IF FOUND AND (v_existing_user_id IS DISTINCT FROM v_user_id OR v_existing_quota_day IS DISTINCT FROM v_quota_day) THEN
      RAISE EXCEPTION 'ocr_quota_operation_binding_mismatch' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT pg_catalog.count(*)::integer
    INTO v_used
    FROM ocr_private.ocr_daily_quota_reservations AS reservations
   WHERE reservations.user_id = v_user_id
     AND reservations.quota_day = v_quota_day;

  IF v_unlimited THEN
    RETURN QUERY SELECT true, v_used, NULL::integer, NULL::integer, true, v_reset_at;
    RETURN;
  END IF;

  IF p_reserve AND v_existing_user_id IS NOT NULL THEN
    RETURN QUERY SELECT true, v_used, 5, pg_catalog.greatest(0, 5 - v_used), false, v_reset_at;
    RETURN;
  END IF;

  IF p_reserve AND v_used < 5 THEN
    INSERT INTO ocr_private.ocr_daily_quota_reservations (
      operation_id,
      user_id,
      quota_day
    ) VALUES (
      p_operation_id,
      v_user_id,
      v_quota_day
    );
    v_used := v_used + 1;
    v_allowed := true;
  ELSE
    v_allowed := v_used < 5;
  END IF;

  RETURN QUERY
    SELECT v_allowed, v_used, 5, pg_catalog.greatest(0, 5 - v_used), false, v_reset_at;
END;
$$;


--
-- Name: valid_model_policy(jsonb); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.valid_model_policy(p_policy jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  SELECT p_policy IS NOT NULL
    AND pg_catalog.jsonb_typeof(p_policy) = 'array'
    AND pg_catalog.jsonb_array_length(p_policy) BETWEEN 1 AND 8
    AND NOT EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_array_elements(p_policy) AS entry(value)
      WHERE pg_catalog.jsonb_typeof(entry.value) <> 'string'
        OR pg_catalog.length(pg_catalog.btrim(entry.value #>> '{}')) NOT BETWEEN 1 AND 160
        OR pg_catalog.btrim(entry.value #>> '{}') <> entry.value #>> '{}'
        OR (entry.value #>> '{}') !~ '^[a-zA-Z0-9][a-zA-Z0-9._:/-]*$'
    )
    AND (
      SELECT pg_catalog.count(*)
      FROM pg_catalog.jsonb_array_elements_text(p_policy) AS model(value)
    ) = (
      SELECT pg_catalog.count(DISTINCT model.value)
      FROM pg_catalog.jsonb_array_elements_text(p_policy) AS model(value)
    );
$_$;


--
-- Name: valid_result_payload(jsonb); Type: FUNCTION; Schema: ocr_private; Owner: -
--

CREATE FUNCTION ocr_private.valid_result_payload(p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_normalized jsonb;
  v_entry jsonb;
  v_item jsonb;
  v_review_field text;
BEGIN
  IF p_payload IS NULL
    OR pg_catalog.jsonb_typeof(p_payload) <> 'object'
    OR pg_catalog.octet_length(pg_catalog.convert_to(p_payload::text, 'UTF8')) > 32768
    OR NOT (p_payload ?& ARRAY[
      'schema_version', 'provider', 'model', 'normalized', 'field_trust',
      'confidence', 'needs_review', 'normalization_version'
    ])
    OR EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_object_keys(p_payload) AS key(value)
      WHERE value <> ALL (ARRAY[
        'schema_version', 'provider', 'model', 'normalized', 'failure_code',
        'field_trust', 'confidence', 'needs_review', 'normalization_version'
      ])
    )
    OR pg_catalog.jsonb_typeof(p_payload->'schema_version') <> 'string'
    OR pg_catalog.jsonb_typeof(p_payload->'provider') <> 'string'
    OR pg_catalog.jsonb_typeof(p_payload->'model') <> 'string'
    OR pg_catalog.jsonb_typeof(p_payload->'normalization_version') <> 'string'
    OR p_payload->>'schema_version' <> 'receipt-public-ocr-v1'
    OR p_payload->>'provider' <> 'gemini'
    OR pg_catalog.length(pg_catalog.btrim(p_payload->>'model')) NOT BETWEEN 1 AND 160
    OR pg_catalog.btrim(p_payload->>'model') <> p_payload->>'model'
    OR pg_catalog.length(p_payload->>'normalization_version') NOT BETWEEN 1 AND 160
    OR pg_catalog.btrim(p_payload->>'normalization_version') <> p_payload->>'normalization_version'
    OR (p_payload ? 'failure_code' AND (
      pg_catalog.jsonb_typeof(p_payload->'failure_code') <> 'string'
      OR p_payload->>'failure_code' NOT IN ('not_receipt', 'unreadable', 'low_quality', 'ocr_failed')
    ))
  THEN
    RETURN false;
  END IF;

  IF pg_catalog.jsonb_typeof(p_payload->'confidence') <> 'number'
    OR (p_payload->>'confidence')::numeric NOT BETWEEN 0 AND 1
  THEN
    RETURN false;
  END IF;

  v_normalized := p_payload->'normalized';
  IF pg_catalog.jsonb_typeof(v_normalized) <> 'object'
    OR EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_object_keys(v_normalized) AS key(value)
      WHERE value <> ALL (ARRAY[
        'store_name', 'date', 'time', 'total_amount', 'category',
        'review_draft', 'items', 'confidence'
      ])
    )
  THEN
    RETURN false;
  END IF;

  IF v_normalized ? 'store_name'
    AND (pg_catalog.jsonb_typeof(v_normalized->'store_name') <> 'string'
      OR pg_catalog.length(v_normalized->>'store_name') NOT BETWEEN 1 AND 160
      OR pg_catalog.btrim(v_normalized->>'store_name') <> v_normalized->>'store_name')
  THEN RETURN false; END IF;

  IF v_normalized ? 'date'
    AND (pg_catalog.jsonb_typeof(v_normalized->'date') <> 'string'
      OR (v_normalized->>'date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
  THEN RETURN false; END IF;

  IF v_normalized ? 'time'
    AND (pg_catalog.jsonb_typeof(v_normalized->'time') <> 'string'
      OR (v_normalized->>'time') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')
  THEN RETURN false; END IF;

  IF v_normalized ? 'total_amount' THEN
    IF pg_catalog.jsonb_typeof(v_normalized->'total_amount') <> 'number'
      OR (v_normalized->>'total_amount')::numeric NOT BETWEEN 0 AND 1000000000
    THEN RETURN false; END IF;
  END IF;

  IF v_normalized ? 'category'
    AND (pg_catalog.jsonb_typeof(v_normalized->'category') <> 'string'
      OR pg_catalog.length(v_normalized->>'category') NOT BETWEEN 1 AND 32
      OR pg_catalog.btrim(v_normalized->>'category') <> v_normalized->>'category')
  THEN RETURN false; END IF;

  IF v_normalized ? 'review_draft'
    AND (pg_catalog.jsonb_typeof(v_normalized->'review_draft') <> 'string'
      OR pg_catalog.length(v_normalized->>'review_draft') NOT BETWEEN 1 AND 4000
      OR pg_catalog.btrim(v_normalized->>'review_draft') <> v_normalized->>'review_draft')
  THEN RETURN false; END IF;

  IF v_normalized ? 'confidence' THEN
    IF pg_catalog.jsonb_typeof(v_normalized->'confidence') <> 'number'
      OR (v_normalized->>'confidence')::numeric NOT BETWEEN 0 AND 1
    THEN RETURN false; END IF;
  END IF;

  IF v_normalized ? 'items' THEN
    IF pg_catalog.jsonb_typeof(v_normalized->'items') <> 'array'
      OR pg_catalog.jsonb_array_length(v_normalized->'items') > 50
    THEN RETURN false; END IF;
    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_normalized->'items') LOOP
      IF pg_catalog.jsonb_typeof(v_item) <> 'object'
        OR NOT (v_item ?& ARRAY['name', 'price'])
        OR EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_object_keys(v_item) AS key(value)
          WHERE value <> ALL (ARRAY['name', 'price'])
        )
        OR pg_catalog.jsonb_typeof(v_item->'name') <> 'string'
        OR pg_catalog.length(v_item->>'name') NOT BETWEEN 1 AND 160
        OR pg_catalog.btrim(v_item->>'name') <> v_item->>'name'
      THEN RETURN false; END IF;
      IF pg_catalog.jsonb_typeof(v_item->'price') NOT IN ('number', 'null') THEN RETURN false; END IF;
      IF pg_catalog.jsonb_typeof(v_item->'price') = 'number'
        AND (v_item->>'price')::numeric NOT BETWEEN 0 AND 1000000000
      THEN RETURN false; END IF;
    END LOOP;
  END IF;

  IF pg_catalog.jsonb_typeof(p_payload->'field_trust') <> 'array'
    OR pg_catalog.jsonb_array_length(p_payload->'field_trust') > 16
  THEN RETURN false; END IF;
  FOR v_entry IN SELECT value FROM pg_catalog.jsonb_array_elements(p_payload->'field_trust') LOOP
    IF pg_catalog.jsonb_typeof(v_entry) <> 'object'
      OR NOT (v_entry ?& ARRAY['field', 'level', 'source', 'reason', 'needsReview'])
      OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_object_keys(v_entry) AS key(value)
        WHERE value <> ALL (ARRAY['field', 'level', 'source', 'reason', 'needsReview'])
      )
      OR v_entry->>'field' NOT IN ('store_name', 'restaurant_id', 'date', 'time', 'total_amount', 'items', 'category', 'review_draft')
      OR v_entry->>'level' NOT IN ('high', 'medium', 'low')
      OR v_entry->>'source' NOT IN ('model_raw', 'model_candidate', 'selected_restaurant', 'db_exact', 'db_fuzzy', 'rule_validation', 'user_required')
      OR pg_catalog.jsonb_typeof(v_entry->'reason') <> 'string'
      OR pg_catalog.length(v_entry->>'reason') NOT BETWEEN 1 AND 240
      OR pg_catalog.jsonb_typeof(v_entry->'needsReview') <> 'boolean'
    THEN RETURN false; END IF;
  END LOOP;

  IF pg_catalog.jsonb_typeof(p_payload->'needs_review') <> 'array'
    OR pg_catalog.jsonb_array_length(p_payload->'needs_review') > 8
  THEN RETURN false; END IF;
  FOR v_review_field IN SELECT value #>> '{}' FROM pg_catalog.jsonb_array_elements(p_payload->'needs_review') LOOP
    IF v_review_field NOT IN ('store_name', 'restaurant_id', 'date', 'time', 'total_amount', 'items', 'category', 'review_draft')
    THEN RETURN false; END IF;
  END LOOP;
  IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements_text(p_payload->'needs_review'))
    <> (SELECT pg_catalog.count(DISTINCT value) FROM pg_catalog.jsonb_array_elements_text(p_payload->'needs_review') AS field(value))
  THEN RETURN false; END IF;

  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: jobs; Type: TABLE; Schema: pipeline_control; Owner: -
--

CREATE TABLE pipeline_control.jobs (
    id uuid NOT NULL,
    target text NOT NULL,
    profile text NOT NULL,
    status text NOT NULL,
    idempotency_key text NOT NULL,
    payload_hash text NOT NULL,
    actor text NOT NULL,
    request_id text NOT NULL,
    lease_until timestamp with time zone NOT NULL,
    heartbeat_at timestamp with time zone NOT NULL,
    adapter_index integer DEFAULT 0 NOT NULL,
    dry_run boolean DEFAULT true NOT NULL,
    error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pause_requested boolean DEFAULT false NOT NULL,
    cancel_requested boolean DEFAULT false NOT NULL,
    checkpoint jsonb DEFAULT '{}'::jsonb NOT NULL,
    claimed_by text,
    execution_mode text DEFAULT 'dry_run'::text NOT NULL,
    data_sink text DEFAULT 'local'::text NOT NULL,
    desired_action text DEFAULT 'none'::text NOT NULL,
    claim_token uuid,
    attempt integer DEFAULT 0 NOT NULL,
    next_step integer DEFAULT 0 NOT NULL,
    worker_id text,
    control_version integer DEFAULT 0 NOT NULL,
    requested_at timestamp with time zone,
    approved_at timestamp with time zone,
    CONSTRAINT jobs_profile_check CHECK ((profile = ANY (ARRAY['heavy_local'::text, 'lite_gha'::text]))),
    CONSTRAINT jobs_status_check CHECK ((status = ANY (ARRAY['Queued'::text, 'Fetching'::text, 'Inserting'::text, 'Paused'::text, 'Cancelled'::text, 'Failed'::text, 'Succeeded'::text])))
);


--
-- Name: _job_json(pipeline_control.jobs); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control._job_json(j pipeline_control.jobs) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
    SELECT jsonb_build_object(
        'id', j.id,
        'target', j.target,
        'profile', j.profile,
        'status', j.status,
        'idempotency_key', j.idempotency_key,
        'payload_hash', j.payload_hash,
        'actor', j.actor,
        'request_id', j.request_id,
        'lease_until', EXTRACT(EPOCH FROM j.lease_until),
        'heartbeat_at', EXTRACT(EPOCH FROM j.heartbeat_at),
        'adapter_index', j.adapter_index,
        'dry_run', j.dry_run,
        'error_code', j.error_code,
        'pause_requested', j.pause_requested,
        'cancel_requested', j.cancel_requested,
        'claimed_by', j.claimed_by,
        'checkpoint', j.checkpoint,
        'execution_mode', j.execution_mode,
        'data_sink', j.data_sink,
        'desired_action', j.desired_action,
        'claim_token', j.claim_token,
        'attempt', j.attempt,
        'next_step', j.next_step,
        'worker_id', j.worker_id,
        'control_version', j.control_version
    );
$$;


--
-- Name: ack_outbox(bigint[], uuid); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.ack_outbox(p_ids bigint[], p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_count integer := 0;
BEGIN
    IF p_claim_token IS NULL THEN
        RAISE EXCEPTION 'outbox_claim_token_required' USING ERRCODE = '22023';
    END IF;

    UPDATE pipeline_control.outbox
    SET published_at = now()
    WHERE id = ANY (COALESCE(p_ids, ARRAY[]::bigint[]))
      AND claim_token = p_claim_token
      AND published_at IS NULL;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN jsonb_build_object('acked', v_count);
END;
$$;


--
-- Name: admin_eval_address_status(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_address_status(value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE flags jsonb:=pipeline_control.admin_eval_flags(value); metrics jsonb:=pipeline_control.admin_eval_metrics(value->'evaluation_results');
 location jsonb:=metrics->'location_match_TF'; details jsonb:=value->'db_error_details'; review jsonb;
 status text:=flags->>'status'; reason text:=location->>'pending_reason'; geo boolean:=coalesce(value->'geocoding_success'='true'::jsonb,false);
 origin text; candidate text; a text; b text; score numeric; label text; families text[]:='{}'; texts text[]; item text;
BEGIN
 IF status IN ('deleted','not_selected','missing') OR value->'is_missing'='true'::jsonb OR value->'is_not_selected'='true'::jsonb THEN RETURN 'not_applicable'; END IF;
 IF reason IN ('ambiguous_chain','multi_candidate') OR (geo AND reason='insufficient_evidence') THEN RETURN 'review'; END IF;
 IF geo THEN RETURN 'true'; END IF;
 IF jsonb_typeof(value->'geocoding_false_stage') IS DISTINCT FROM 'number' THEN RETURN 'failed'; END IF;
 IF jsonb_typeof(details)='object' AND jsonb_typeof(details->'address_consistency_review')='object' THEN review:=details->'address_consistency_review'; END IF;
 IF jsonb_typeof(review->'ahp_score')='number' THEN score:=least(100,greatest(0,(review->>'ahp_score')::numeric)); END IF;
 label:=CASE WHEN btrim(review->>'ahp_label') IN ('정정 승인 후보','주소 후보 검토','재수집 필요','영업상태 확인','원천 품질 문제','AHP 미산정') THEN btrim(review->>'ahp_label') ELSE CASE WHEN score>=98 THEN '정정 승인 후보' ELSE '' END END;
 origin:=coalesce(nullif(btrim(value->>'origin_name'),''),pipeline_control.admin_eval_display_name(value));
 candidate:=coalesce(nullif(btrim(value->>'approved_name'),''),nullif(btrim(value->>'naver_name'),''),nullif(btrim(value->>'google_name'),''),nullif(btrim(location->>'matched_name'),''),nullif(btrim(location->>'naver_name'),''),nullif(btrim(location->>'google_name'),''));
 a:=pipeline_control.admin_eval_name_key(origin);b:=pipeline_control.admin_eval_name_key(candidate);
 IF jsonb_typeof(review->'evidence_families')='array' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(review->'evidence_families')='array' THEN review->'evidence_families' ELSE '[]'::jsonb END) v WHERE jsonb_typeof(v)<>'string') THEN
  SELECT array_agg(v) INTO families FROM jsonb_array_elements_text(review->'evidence_families') v WHERE btrim(v)<>'';
 END IF;
 SELECT coalesce(families,'{}')||coalesce(array_agg(v),'{}') INTO families FROM jsonb_array_elements_text(coalesce(location->'evidence_families','[]')) v WHERE btrim(v)<>'';
 texts:=ARRAY[CASE WHEN pipeline_control.admin_eval_valid_meta(value->'youtube_meta') THEN value#>>'{youtube_meta,title}' END,
 value->>'reasoning_basis',value->>'description_map_url',value->>'trace_id_name_source',value->>'db_error_message',review->>'reason_ko',location->>'falseMessage'];
 SELECT texts||coalesce(array_agg(v),'{}') INTO texts FROM jsonb_array_elements_text(coalesce(location->'evidence_summary','[]')) v;
 IF score>=98 AND label='정정 승인 후보' AND nullif(value->>'updated_by_admin_id','') IS NULL
  AND status<>'db_conflict' AND details->>'error_type' IS DISTINCT FROM 'duplicate'
  AND NOT coalesce((jsonb_typeof(details->'conflicting_restaurant')='object' AND jsonb_typeof(details#>'{conflicting_restaurant,id}')='string' AND jsonb_typeof(details#>'{conflicting_restaurant,name}')='string' AND jsonb_typeof(details#>'{conflicting_restaurant,jibun_address}')='string' AND (NOT (details->'conflicting_restaurant') ? 'road_address' OR jsonb_typeof(details#>'{conflicting_restaurant,road_address}')='string')),false)
  AND NOT coalesce((jsonb_typeof(details->'similarity_score')='number' AND (details->>'similarity_score')::numeric>=0.85),false)
  AND coalesce(reason NOT IN ('cross_country_mismatch','ambiguous_chain','multi_candidate'),true)
  AND (a='' OR b='' OR a=b OR (length(a)>=3 AND strpos(b,a)>0) OR (length(b)>=3 AND strpos(a,b)>0))
  AND 'provider_candidate'=ANY(families) AND families && ARRAY['source_geo','cross_provider','browser_verification']
  AND NOT EXISTS(SELECT 1 FROM unnest(texts) v WHERE v ~ '폐업|휴업|영업\s*종료|이전|상호\s*변경|구상호|옛\s*상호') THEN RETURN 'candidate'; END IF;
 IF nullif(review->>'queue','') IS NOT NULL THEN RETURN 'review'; END IF;
 RETURN 'false';
END;
$$;


--
-- Name: admin_eval_descriptor(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_descriptor(value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE display text:=pipeline_control.admin_eval_display_name(value); flags jsonb:=pipeline_control.admin_eval_flags(value);
 metrics jsonb:=pipeline_control.admin_eval_metrics(value->'evaluation_results'); vals jsonb:='{}'; key text; title text;
 latest numeric; created numeric:=pipeline_control.admin_eval_epoch(value->>'created_at'); reason text; not_reason text;
BEGIN
 IF pipeline_control.admin_eval_valid_meta(value->'youtube_meta') THEN title:=value#>>'{youtube_meta,title}'; END IF;
 latest:=CASE WHEN pipeline_control.admin_eval_valid_meta(value->'youtube_meta') AND btrim(value#>>'{youtube_meta,publishedAt}')<>'' THEN pipeline_control.admin_eval_epoch(value#>>'{youtube_meta,publishedAt}') ELSE created END;
 FOREACH key IN ARRAY ARRAY['visit_authenticity','rb_inference_score','review_faithfulness_score','rb_grounding_TF','category_TF','category_validity_TF'] LOOP
  vals:=vals||jsonb_build_object(key,metrics#>ARRAY[key,'eval_value']);
 END LOOP;
 IF metrics->'location_match_TF' IS NOT NULL AND metrics->'location_match_TF'<>'null'::jsonb AND metrics#>'{location_match_TF,eval_value}' IS DISTINCT FROM 'true'::jsonb THEN
  reason:=CASE WHEN btrim(metrics#>>'{location_match_TF,falseMessage}')<>'' THEN metrics#>>'{location_match_TF,falseMessage}'
    WHEN btrim(metrics#>>'{location_match_TF,pending_reason}')<>'' THEN 'location_match pending ('||(metrics#>>'{location_match_TF,pending_reason}')||')'
    ELSE 'location_match 실패(사유 없음)' END;
 END IF;
 not_reason:=CASE WHEN value->'is_not_selected' IS DISTINCT FROM 'true'::jsonb THEN '평가 미대상(기타)'
  WHEN value->'is_missing'='true'::jsonb THEN '평가 미대상(missing target)'
  WHEN value->'geocoding_false_stage'='0'::jsonb THEN '평가 미대상(address null 등)'
  WHEN value->'geocoding_false_stage'='1'::jsonb THEN '평가 미대상(지오코딩 1단계 실패)'
  WHEN value->'geocoding_false_stage'='2'::jsonb THEN '평가 미대상(지오코딩 2단계 실패)'
  WHEN value->'geocoding_success' IS DISTINCT FROM 'true'::jsonb THEN '평가 미대상(지오코딩 실패)' ELSE '평가 미대상(기타)' END;
 RETURN jsonb_build_object('flags',flags,'metrics',vals,'address',pipeline_control.admin_eval_address_status(value),
  'latest',latest,'created',created,'video',pipeline_control.admin_eval_video_id(value->>'youtube_link'),
  'search',jsonb_build_array(coalesce(nullif(btrim(title),''),CASE WHEN display<>'이름 없음' THEN display ELSE '영상 제목 없음' END),
    display,value->>'origin_name',value->>'approved_name',value->>'naver_name',value->>'youtube_link'),
  'notSelection',coalesce(value->'is_not_selected'='true'::jsonb,false),'notReason',not_reason,'ruleReason',reason,
  'laajGap',(coalesce(metrics->'category_validity_TF','null')<>'null'::jsonb OR coalesce(metrics->'location_match_TF','null')<>'null'::jsonb)
    AND coalesce(metrics->'visit_authenticity','null')='null'::jsonb AND coalesce(metrics->'rb_inference_score','null')='null'::jsonb
    AND coalesce(metrics->'rb_grounding_TF','null')='null'::jsonb AND coalesce(metrics->'review_faithfulness_score','null')='null'::jsonb AND coalesce(metrics->'category_TF','null')='null'::jsonb);
END;
$$;


--
-- Name: admin_eval_display_name(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_display_name(value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE candidate text; location jsonb:=pipeline_control.admin_eval_metrics(value->'evaluation_results')->'location_match_TF';
BEGIN
 IF jsonb_typeof(value->'approved_name')='string' AND btrim(value->>'approved_name')<>'' THEN RETURN btrim(value->>'approved_name'); END IF;
 IF location->'eval_value'='true'::jsonb OR location->>'match_status'='matched' THEN
   FOREACH candidate IN ARRAY ARRAY[value->>'naver_name',location->>'naver_name',
     CASE WHEN location->>'matched_provider'='naver' THEN location->>'matched_name' END] LOOP
     IF candidate IS NOT NULL AND btrim(candidate)<>'' AND pipeline_control.admin_eval_names_compatible(value->>'origin_name',candidate)
       THEN RETURN btrim(candidate); END IF;
   END LOOP;
 END IF;
 FOREACH candidate IN ARRAY ARRAY[value->>'restaurant_name',value->>'name',value->>'origin_name'] LOOP
   IF candidate IS NOT NULL AND btrim(candidate)<>'' THEN RETURN btrim(candidate); END IF;
 END LOOP;
 RETURN '이름 없음';
END;
$$;


--
-- Name: admin_eval_epoch(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_epoch(value text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, MDY'
    AS $$
DECLARE parsed numeric;
BEGIN
 IF value IS NULL OR btrim(value)='' THEN RETURN 0; END IF;
 -- Relative/special Postgres timestamps are not dates in Date.parse and would
 -- make an IMMUTABLE projection depend on the time of the write.
 IF value ~* '\m(now|today|tomorrow|yesterday|infinity|epoch)\M' THEN RETURN 0; END IF;
 parsed:=trunc(extract(epoch FROM value::timestamptz)*1000);
 IF parsed NOT BETWEEN -8640000000000000 AND 8640000000000000 THEN RETURN 0; END IF;
 RETURN parsed;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN 0;
END;
$$;


--
-- Name: admin_eval_filter_number(text, boolean); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_filter_number(value text, allow_fraction boolean) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE text_value text:=pipeline_control.admin_eval_js_trim(value); digits text; numeric_value numeric:=0; sign_value integer:=1; position integer; digit integer;
BEGIN
 IF allow_fraction THEN
  digits:=substring(text_value FROM '^([+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?)');
 ELSIF text_value ~ '^[+-]?0[xX]' THEN
  IF left(text_value,1)='-' THEN sign_value:=-1; END IF;
  digits:=substring(text_value FROM '^[+-]?0[xX]([0-9a-fA-F]+)');
  IF digits IS NULL THEN RETURN NULL; END IF;
  FOR position IN 1..length(digits) LOOP
   digit:=strpos('0123456789abcdef',lower(substr(digits,position,1)))-1;
   numeric_value:=numeric_value*16+digit;
  END LOOP;
  RETURN (sign_value*numeric_value)::double precision;
 ELSE digits:=substring(text_value FROM '^([+-]?[0-9]+)');
 END IF;
 IF digits IS NULL THEN RETURN NULL; END IF;
 RETURN digits::double precision;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
END;
$$;


--
-- Name: admin_eval_flags(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_flags(value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE status text; metrics jsonb; reason text; missing boolean; not_selected boolean; geo boolean; ready boolean; unconfirmed boolean;
BEGIN
  status:=CASE WHEN value->>'status' IN ('pending','approved','rejected','hold','deleted','missing','db_conflict','geocoding_failed','address_review_geocode_recovered','not_selected') THEN value->>'status' ELSE 'pending' END;
  metrics:=pipeline_control.admin_eval_metrics(value->'evaluation_results');
  reason:=metrics#>>'{location_match_TF,pending_reason}';
  missing:=coalesce(value->'is_missing'='true'::jsonb,false);
  not_selected:=coalesce(value->'is_not_selected'='true'::jsonb,false);
  geo:=coalesce(value->'geocoding_success'='true'::jsonb,false);
  ready:=coalesce(status IN ('pending','hold') AND geo
    AND metrics#>'{visit_authenticity,eval_value}'='1'::jsonb
    AND metrics#>'{rb_inference_score,eval_value}'='1'::jsonb
    AND metrics#>'{rb_grounding_TF,eval_value}'='true'::jsonb
    AND metrics#>'{review_faithfulness_score,eval_value}'='1'::jsonb
    AND metrics#>'{category_validity_TF,eval_value}'='true'::jsonb
    AND metrics#>'{category_TF,eval_value}'='true'::jsonb
    AND coalesce(reason NOT IN ('ambiguous_chain','multi_candidate','insufficient_evidence'),true),false);
  unconfirmed:=coalesce(status NOT IN ('deleted','approved') AND NOT missing AND NOT not_selected
    AND reason IN ('insufficient_evidence','ambiguous_chain','multi_candidate'),false);
  RETURN jsonb_build_object('status',status,'missing',missing OR status IN ('missing','geocoding_failed'),
    'not_selected',not_selected OR status='not_selected','ready_for_approval',ready,'unconfirmed_map',unconfirmed);
END;
$$;


--
-- Name: admin_eval_js_trim(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_js_trim(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT btrim(value,E' \t\n\r\f'||chr(11)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279));
$$;


--
-- Name: admin_eval_matches(jsonb, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_matches(d jsonb, q jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE f jsonb:=q->'evalFilters'; deep jsonb:=q->'deepLinkFilter'; needle text:=lower(pipeline_control.admin_eval_js_trim(coalesce(q->>'searchQuery','')));
 status text:=f->>'status'; key text; wanted text; number_value double precision;
BEGIN
 IF needle<>'' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(d->'search') text_value WHERE strpos(lower(text_value),needle)>0) THEN RETURN false; END IF;
 IF status IS NOT NULL AND status<>'' THEN
  IF status IN ('missing','not_selected','ready_for_approval','unconfirmed_map') THEN
   IF d#>ARRAY['flags',status] IS DISTINCT FROM 'true'::jsonb THEN RETURN false; END IF;
  ELSIF d#>>'{flags,status}' IS DISTINCT FROM status THEN RETURN false; END IF;
 END IF;
 FOREACH key IN ARRAY ARRAY['visit_authenticity','rb_inference_score','review_faithfulness_score'] LOOP
  wanted:=f->>key;
  IF wanted IS NULL OR wanted='' THEN CONTINUE; END IF;
  number_value:=pipeline_control.admin_eval_filter_number(wanted,key='review_faithfulness_score');
  IF number_value IS NULL THEN RETURN false; END IF;
  BEGIN
   IF (d#>>ARRAY['metrics',key])::double precision IS DISTINCT FROM number_value THEN RETURN false; END IF;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false; END;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['rb_grounding_TF','category_validity_TF','category_TF'] LOOP
  wanted:=f->>key;
  IF wanted IS NOT NULL AND wanted<>'' AND d#>ARRAY['metrics',key] IS DISTINCT FROM to_jsonb(wanted='True') THEN RETURN false; END IF;
 END LOOP;
 wanted:=f->>'geocoding_success';
 IF wanted='true' AND d->>'address'<>'true' THEN RETURN false; END IF;
 IF wanted='false_match' AND d->>'address'<>'false' THEN RETURN false; END IF;
 IF wanted='false_geocode' AND d->>'address'<>'failed' THEN RETURN false; END IF;
 IF wanted='review' AND d->>'address' NOT IN ('review','candidate') THEN RETURN false; END IF;
 IF coalesce(deep->>'videoId','')<>'' AND d->>'video' IS DISTINCT FROM deep->>'videoId' THEN RETURN false; END IF;
 IF deep->>'issue'='notSelection' THEN
  IF d->'notSelection' IS DISTINCT FROM 'true'::jsonb THEN RETURN false; END IF;
  IF coalesce(deep->>'reason','')<>'' AND d->>'notReason' IS DISTINCT FROM deep->>'reason' THEN RETURN false; END IF;
 ELSIF deep->>'issue'='ruleFalse' THEN
  IF d->>'ruleReason' IS NULL OR d->>'ruleReason'='' THEN RETURN false; END IF;
  IF coalesce(deep->>'reason','')<>'' AND d->>'ruleReason' IS DISTINCT FROM deep->>'reason' THEN RETURN false; END IF;
 ELSIF deep->>'issue'='laajGap' AND d->'laajGap' IS DISTINCT FROM 'true'::jsonb THEN RETURN false;
 END IF;
 RETURN true;
END;
$$;


--
-- Name: admin_eval_metrics(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_metrics(value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE result jsonb:='{}'; metric jsonb; normalized jsonb; key text; field text; kind text;
  location jsonb; nested jsonb; fields jsonb;
BEGIN
  IF jsonb_typeof(value) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
  FOREACH key IN ARRAY ARRAY['visit_authenticity','rb_inference_score','review_faithfulness_score','rb_grounding_TF','category_TF','category_validity_TF'] LOOP
    metric:=value->key; normalized:='null';
    kind:=CASE WHEN key IN ('visit_authenticity','rb_inference_score','review_faithfulness_score') THEN 'number' ELSE 'boolean' END;
    IF jsonb_typeof(metric)='object' AND jsonb_typeof(metric->'eval_value')=kind
      AND (key<>'category_TF' OR (
        (NOT metric ? 'category_revision' OR jsonb_typeof(metric->'category_revision') IN ('string','null'))
        AND (NOT metric ? 'eval_basis' OR jsonb_typeof(metric->'eval_basis')='string'))) THEN
      normalized:=jsonb_build_object('name',CASE WHEN jsonb_typeof(metric->'name')='string' THEN metric->>'name' ELSE '' END,'eval_value',metric->'eval_value');
      IF key IN ('visit_authenticity','rb_inference_score','review_faithfulness_score','rb_grounding_TF') THEN
        normalized:=normalized||jsonb_build_object('eval_basis',CASE WHEN jsonb_typeof(metric->'eval_basis')='string' THEN metric->>'eval_basis' ELSE '' END);
      ELSIF key='category_TF' THEN
        normalized:=normalized||jsonb_build_object('category_revision',CASE WHEN jsonb_typeof(metric->'category_revision') IN ('string','null') THEN metric->'category_revision' ELSE 'null'::jsonb END);
        IF jsonb_typeof(metric->'eval_basis')='string' THEN normalized:=normalized||jsonb_build_object('eval_basis',metric->'eval_basis'); END IF;
      END IF;
    END IF;
    result:=result||jsonb_build_object(key,normalized);
  END LOOP;
  location:=value->'location_match_TF'; normalized:='null';
  IF jsonb_typeof(location)='object' THEN
    normalized:='{}';
    FOREACH field IN ARRAY ARRAY['name','origin_address'] LOOP
      IF jsonb_typeof(location->field)='string' THEN normalized:=normalized||jsonb_build_object(field,location->field); END IF;
    END LOOP;
    FOREACH field IN ARRAY ARRAY['origin_name','matched_name','naver_name','google_name','falseMessage'] LOOP
      IF jsonb_typeof(location->field) IN ('string','null') THEN normalized:=normalized||jsonb_build_object(field,location->field); END IF;
    END LOOP;
    IF jsonb_typeof(location->'eval_value')='boolean' THEN normalized:=normalized||jsonb_build_object('eval_value',location->'eval_value'); END IF;
    IF location->>'match_status' IN ('matched','pending','failed') THEN normalized:=normalized||jsonb_build_object('match_status',location->'match_status'); END IF;
    IF location->>'matched_provider' IN ('naver','google','playwright','gemini','ncp_geocode') OR location->'matched_provider'='null'::jsonb THEN normalized:=normalized||jsonb_build_object('matched_provider',location->'matched_provider'); END IF;
    IF location->>'pending_reason' IN ('insufficient_evidence','cross_country_mismatch','ambiguous_chain','multi_candidate','timeout','rate_limited') OR location->'pending_reason'='null'::jsonb THEN normalized:=normalized||jsonb_build_object('pending_reason',location->'pending_reason'); END IF;
    IF jsonb_typeof(location->'evidence_summary')='array' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(location->'evidence_summary')='array' THEN location->'evidence_summary' ELSE '[]'::jsonb END) item WHERE jsonb_typeof(item)<>'string') THEN normalized:=normalized||jsonb_build_object('evidence_summary',location->'evidence_summary'); END IF;
    IF jsonb_typeof(location->'evidence_families')='array' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(location->'evidence_families')='array' THEN location->'evidence_families' ELSE '[]'::jsonb END) item WHERE jsonb_typeof(item)<>'string' OR item#>>'{}' NOT IN ('provider_candidate','source_geo','cross_provider','browser_verification','llm_verification','geocode_provider')) THEN normalized:=normalized||jsonb_build_object('evidence_families',location->'evidence_families'); END IF;
    IF location->'naver_address'='null'::jsonb OR (jsonb_typeof(location->'naver_address')='array' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(location->'naver_address')='array' THEN location->'naver_address' ELSE '[]'::jsonb END) item WHERE jsonb_typeof(item)<>'object')) THEN normalized:=normalized||jsonb_build_object('naver_address',location->'naver_address'); END IF;
    IF location->'matched_address'='null'::jsonb THEN normalized:=normalized||jsonb_build_object('matched_address','null'::jsonb);
    ELSIF jsonb_typeof(location->'matched_address')='object' THEN
      nested:=location->'matched_address';fields:='{}';
      FOREACH field IN ARRAY ARRAY['roadAddress','jibunAddress','englishAddress','x','y'] LOOP
        IF jsonb_typeof(nested->field) IN ('string','null') THEN fields:=fields||jsonb_build_object(field,nested->field); END IF;
      END LOOP;
      normalized:=normalized||jsonb_build_object('matched_address',fields);
    END IF;
    IF location->'second_pass'='null'::jsonb THEN normalized:=normalized||jsonb_build_object('second_pass','null'::jsonb);
    ELSIF jsonb_typeof(location->'second_pass')='object' THEN
      nested:=location->'second_pass';fields:='{}';
      FOREACH field IN ARRAY ARRAY['attempted','timed_out','rate_limited'] LOOP
        IF jsonb_typeof(nested->field)='boolean' THEN fields:=fields||jsonb_build_object(field,nested->field); END IF;
      END LOOP;
      IF jsonb_typeof(nested->'provider') IN ('string','null') THEN fields:=fields||jsonb_build_object('provider',nested->'provider'); END IF;
      IF jsonb_typeof(nested->'duration_ms') IN ('number','null') THEN fields:=fields||jsonb_build_object('duration_ms',nested->'duration_ms'); END IF;
      normalized:=normalized||jsonb_build_object('second_pass',fields);
    END IF;
  END IF;
  RETURN result||jsonb_build_object('location_match_TF',normalized);
END;
$$;


--
-- Name: admin_eval_name_key(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_name_key(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 SELECT btrim(regexp_replace(regexp_replace(regexp_replace(lower(normalize(coalesce(value,''),NFKC)),
   '\([^)]*\)|\[[^\]]*\]|（[^）]*）',' ','g'),
   '(^|\s)(구|현|전)(\s|$)',' ','g'),
   '[\s·・ㆍ._\-–—,，()（）\[\]{}<>《》"''`´’‘“”:：]','','g'));
$_$;


--
-- Name: admin_eval_name_tokens(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_name_tokens(value text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 SELECT coalesce(array_agg(DISTINCT pipeline_control.admin_eval_name_key(regexp_replace(token,'점$',''))),'{}')
 FROM regexp_split_to_table(regexp_replace(regexp_replace(normalize(coalesce(value,''),NFKC),
   '\(([^)]*)\)|（([^）]*)）',' \1\2 ','g'),
   '[·・ㆍ._\-–—,，\[\]{}<>《》"''`´’‘“”:：]',' ','g'),'\s+') token
 WHERE length(btrim(token))>=2 AND token NOT IN ('구','현','전','내','본점');
$_$;


--
-- Name: admin_eval_names_compatible(text, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_names_compatible(origin text, candidate text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE a text:=pipeline_control.admin_eval_name_key(origin); b text:=pipeline_control.admin_eval_name_key(candidate);
BEGIN
 IF a='' OR b='' OR a=b OR (length(a)>=3 AND strpos(b,a)>0) OR (length(b)>=3 AND strpos(a,b)>0) THEN RETURN true; END IF;
 RETURN EXISTS(SELECT 1 FROM unnest(pipeline_control.admin_eval_name_tokens(origin)) left_token
   CROSS JOIN unnest(pipeline_control.admin_eval_name_tokens(candidate)) right_token
   WHERE left_token<>'' AND right_token<>'' AND (left_token=right_token
     OR (length(left_token)>=3 AND strpos(right_token,left_token)>0)
     OR (length(right_token)>=3 AND strpos(left_token,right_token)>0)));
END;
$$;


