--
-- Name: admin_eval_valid_meta(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_valid_meta(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT coalesce(jsonb_typeof(value)='object'
  AND jsonb_typeof(value->'title')='string' AND jsonb_typeof(value->'publishedAt')='string'
  AND jsonb_typeof(value->'is_shorts')='boolean' AND jsonb_typeof(value->'duration')='number',false);
$$;


--
-- Name: admin_eval_video_id(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_eval_video_id(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT coalesce(
  substring(value COLLATE "C" FROM '[?&]v=([A-Za-z0-9_-]{6,128})(?![A-Za-z0-9_-])'),
  substring(value COLLATE "C" FROM 'youtu\.be/([A-Za-z0-9_-]{6,128})(?![A-Za-z0-9_-])'),
  substring(value COLLATE "C" FROM 'youtube\.com/shorts/([A-Za-z0-9_-]{6,128})(?![A-Za-z0-9_-])'),
  substring(value COLLATE "C" FROM 'youtube\.com/embed/([A-Za-z0-9_-]{6,128})(?![A-Za-z0-9_-])'),
  substring(value COLLATE "C" FROM 'youtube\.com/live/([A-Za-z0-9_-]{6,128})(?![A-Za-z0-9_-])'));
$$;


--
-- Name: admin_record_assert_operator(uuid); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_assert_operator(actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF actor IS NULL OR NOT EXISTS (
  SELECT 1 FROM public.user_roles role JOIN public.user_account_status account ON account.user_id=role.user_id
  WHERE role.user_id=actor AND role.role='admin' AND account.account_status='active' AND account.disabled_at IS NULL
 ) THEN RAISE EXCEPTION 'RECORD_ACTION_FORBIDDEN' USING ERRCODE='42501'; END IF;
END $$;


--
-- Name: admin_record_compose(jsonb, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_compose(row_value jsonb, changes jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE k text; meta jsonb; ads jsonb; incoming_meta jsonb;
BEGIN
 IF jsonb_typeof(changes) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(changes) x WHERE x<>ALL(ARRAY[
  'approved_name','phone','categories','youtube_link','tzuyang_review','road_address','jibun_address','english_address','address_elements','lat','lng','geocoding_success','youtube_meta']))
 THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
 FOREACH k IN ARRAY ARRAY['approved_name','phone','youtube_link','tzuyang_review','road_address','jibun_address','english_address'] LOOP
  IF changes ? k AND (jsonb_typeof(changes->k) NOT IN ('string','null') OR length(changes->>k)>4000) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
 END LOOP;
 IF (changes ? 'approved_name' AND (nullif(btrim(changes->>'approved_name'),'') IS NULL OR length(changes->>'approved_name')>160))
  OR (changes ? 'phone' AND length(changes->>'phone')>80)
  OR (changes ? 'youtube_link' AND changes->'youtube_link'<>'null'::jsonb AND changes->>'youtube_link' !~ '^https://(www\.)?youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$')
  OR (changes ? 'geocoding_success' AND jsonb_typeof(changes->'geocoding_success')<>'boolean')
  OR (changes ? 'youtube_meta' AND jsonb_typeof(changes->'youtube_meta')<>'object')
  OR (changes ? 'address_elements' AND jsonb_typeof(changes->'address_elements') NOT IN ('array','object','null'))
 THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_RESTAURANT'; END IF;
 FOREACH k IN ARRAY ARRAY['lat','lng'] LOOP
  IF changes ? k THEN
   IF jsonb_typeof(changes->k)<>'number' THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_RESTAURANT'; END IF;
   IF (changes->>k)::numeric NOT BETWEEN (CASE k WHEN 'lat' THEN -90 ELSE -180 END) AND (CASE k WHEN 'lat' THEN 90 ELSE 180 END) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_RESTAURANT'; END IF;
  END IF;
 END LOOP;
 IF changes ? 'categories' THEN
  IF jsonb_typeof(changes->'categories')<>'array' THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_RESTAURANT'; END IF;
  IF jsonb_array_length(changes->'categories') NOT BETWEEN 1 AND 15 OR EXISTS(SELECT 1 FROM jsonb_array_elements(changes->'categories') x WHERE jsonb_typeof(x)<>'string' OR x#>>'{}'<>ALL(ARRAY['치킨','중식','돈까스·회','피자','패스트푸드','찜·탕','족발·보쌈','분식','카페·디저트','한식','고기','양식','아시안','야식','도시락'])) OR (SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements(changes->'categories') x) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_RESTAURANT'; END IF;
 END IF;
 IF changes ? 'youtube_meta' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(changes->'youtube_meta') meta_key WHERE meta_key<>ALL(ARRAY['title','published_at','duration','is_shorts','is_ads','what_ads','sponsorship_confirmation'])) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
  incoming_meta:=changes->'youtube_meta';
  FOREACH k IN ARRAY ARRAY['title','published_at'] LOOP
   IF incoming_meta ? k AND (jsonb_typeof(incoming_meta->k)<>'string' OR length(incoming_meta->>k)>4000) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
  END LOOP;
  IF incoming_meta ? 'duration' THEN
   IF jsonb_typeof(incoming_meta->'duration')<>'number' THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   IF (incoming_meta->>'duration')::numeric<0 THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
  END IF;
  IF (incoming_meta ? 'is_shorts' AND jsonb_typeof(incoming_meta->'is_shorts')<>'boolean')
   OR (incoming_meta ? 'is_ads' AND jsonb_typeof(incoming_meta->'is_ads')<>'boolean') THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
  IF incoming_meta ? 'what_ads' AND incoming_meta->'what_ads'<>'null'::jsonb THEN
   IF jsonb_typeof(incoming_meta->'what_ads')<>'array' THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   IF jsonb_array_length(incoming_meta->'what_ads')>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(incoming_meta->'what_ads') x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}')>4000) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
  END IF;
  -- An explicit manual decision is distinct from an automatic/legacy field projection.
  -- The caller cannot supply provenance or actor identity; the existing guarded
  -- operation binds actor/targets/payload/fingerprint and commits the audit.
  IF incoming_meta ? 'sponsorship_confirmation' THEN
   IF incoming_meta->>'sponsorship_confirmation' IS NULL
    OR incoming_meta->>'sponsorship_confirmation' NOT IN ('detected','confirmed_none')
    OR NOT (incoming_meta ? 'is_ads' AND incoming_meta ? 'what_ads')
    OR incoming_meta->'is_ads' IS DISTINCT FROM to_jsonb(incoming_meta->>'sponsorship_confirmation'='detected')
   THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   IF incoming_meta->>'sponsorship_confirmation'='confirmed_none' THEN
    IF incoming_meta->'what_ads' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   ELSE
    IF jsonb_typeof(incoming_meta->'what_ads') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
    IF jsonb_array_length(incoming_meta->'what_ads')=0 OR EXISTS(
     SELECT 1 FROM jsonb_array_elements_text(incoming_meta->'what_ads') x
     WHERE pipeline_control.admin_eval_js_trim(x)=''
    ) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   END IF;
  END IF;
  meta:=CASE WHEN jsonb_typeof(row_value->'youtube_meta')='object' THEN row_value->'youtube_meta' ELSE '{}'::jsonb END;
  ads:=CASE WHEN jsonb_typeof(meta->'ads_info')='object' THEN meta->'ads_info' ELSE '{}'::jsonb END;
  FOREACH k IN ARRAY ARRAY['title','duration','is_shorts'] LOOP
   IF incoming_meta ? k THEN meta:=meta||jsonb_build_object(k,incoming_meta->k); END IF;
  END LOOP;
  IF incoming_meta ? 'published_at' THEN meta:=meta||jsonb_build_object('publishedAt',incoming_meta->'published_at'); END IF;
  IF incoming_meta ? 'is_ads' THEN ads:=ads||jsonb_build_object('is_ads',incoming_meta->'is_ads'); END IF;
  IF incoming_meta ? 'what_ads' THEN
   -- Canonical consumers use nullable advertising text. A single wrapped text
   -- round-trips exactly; ordered names retain their text in a readable list.
   ads:=ads||jsonb_build_object('what_ads',CASE WHEN incoming_meta->'what_ads'='null'::jsonb THEN NULL::text ELSE
    (SELECT string_agg(value,', ' ORDER BY ordinal) FROM jsonb_array_elements_text(incoming_meta->'what_ads') WITH ORDINALITY a(value,ordinal)) END);
  END IF;
  IF incoming_meta ? 'sponsorship_confirmation' THEN
   -- Replace only stale sponsorship analysis. Other metadata and ads keys survive.
   ads:=ads||jsonb_build_object('sponsor_analysis',jsonb_build_object(
    'status','completed','outcome',incoming_meta->>'sponsorship_confirmation',
    'source','manual_admin','version','manual-sponsorship-v1',
    'reason','explicit_admin_confirmation','source_sha256',NULL));
  END IF;
  IF incoming_meta ? 'is_ads' OR incoming_meta ? 'what_ads' OR meta ? 'ads_info' THEN meta:=meta||jsonb_build_object('ads_info',ads); END IF;
  changes:=changes||jsonb_build_object('youtube_meta',meta);
 END IF;
 RETURN row_value||changes;
END $_$;


--
-- Name: admin_record_create(jsonb, uuid); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_create(changes jsonb, actor uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE created uuid:=gen_random_uuid();
BEGIN
 changes:=pipeline_control.admin_record_compose('{}'::jsonb,changes);
 PERFORM pipeline_control.admin_record_validate_restaurant(changes,'{}'::uuid[]);
 IF nullif(btrim(changes->>'tzuyang_review'),'') IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_EVIDENCE_REQUIRED'; END IF;
 INSERT INTO public.restaurants(id,approved_name,source_type,status,trace_id,youtube_link,lat,lng,jibun_address,categories,geocoding_success,updated_by_admin_id)
 VALUES(created,changes->>'approved_name','admin','pending',encode(sha256(convert_to('admin-record:'||created::text,'UTF8')),'hex'),changes->>'youtube_link',(changes->>'lat')::numeric,(changes->>'lng')::numeric,
  changes->>'jibun_address',ARRAY(SELECT jsonb_array_elements_text(changes->'categories')),true,actor);
 -- changes is already canonical and validated; do not parse it as the flat DTO twice.
 PERFORM pipeline_control.admin_record_write(created,changes,actor,true);
 RETURN created;
END $$;


--
-- Name: admin_record_hash(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_hash(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ SELECT encode(sha256(convert_to(value::text,'UTF8')),'hex') $$;


--
-- Name: admin_record_identity_check(jsonb, uuid[]); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_identity_check(row_value jsonb, exclude_ids uuid[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.restaurants r WHERE NOT(id=ANY(array_remove(exclude_ids,NULL))) AND status<>'deleted'
  AND public.extract_youtube_video_id(r.youtube_link)=public.extract_youtube_video_id(row_value->>'youtube_link')
  AND public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(r.approved_name,r.origin_name,r.naver_name,r.google_name))=
      public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(row_value->>'approved_name',row_value->>'origin_name',row_value->>'naver_name',row_value->>'google_name')))
 THEN RAISE EXCEPTION 'RECORD_ACTION_DUPLICATE'; END IF;
END $$;


--
-- Name: admin_record_object_fence(); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_object_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE media record;
BEGIN
  -- A read-access timestamp update does not replace object content.
  IF TG_OP = 'UPDATE'
    AND (to_jsonb(NEW) - 'last_accessed_at') = (to_jsonb(OLD) - 'last_accessed_at') THEN
    RETURN NEW;
  END IF;
  FOR media IN
    SELECT DISTINCT candidate.bucket, candidate.object_name
    FROM (VALUES
      (CASE WHEN TG_OP = 'UPDATE' THEN OLD.bucket_id END,
       CASE WHEN TG_OP = 'UPDATE' THEN OLD.name END),
      (NEW.bucket_id, NEW.name)
    ) candidate(bucket, object_name)
    WHERE candidate.bucket IN ('review-photos', 'review-verifications')
      AND candidate.object_name IS NOT NULL
    ORDER BY candidate.bucket, candidate.object_name
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'review-media:' || media.bucket || ':' || media.object_name, 0));
    IF EXISTS (
      SELECT 1 FROM pipeline_control.admin_record_media_cleanup cleanup
      WHERE cleanup.bucket = media.bucket AND cleanup.object_name = media.object_name
        AND cleanup.state IN ('pending', 'inflight', 'uncertain', 'done')
    ) THEN
      -- Storage v1.33.0 TUS DELETE performs a rollback-only version='1'
      -- permission probe. The deferred trigger still rejects any commit.
      IF TG_WHEN = 'BEFORE' AND NEW.version = '1'
        AND current_setting('request.method', true) = 'DELETE'
        AND current_setting('storage.operation', true) = 'storage.tus.upload.delete'
        AND current_setting('request.path', true) ~ '^/upload/resumable/[A-Za-z0-9_-]+$'
      THEN CONTINUE; END IF;
      RAISE EXCEPTION 'RECORD_ACTION_MEDIA_RETIRED';
    END IF;
  END LOOP;
  RETURN NEW;
END $_$;


--
-- Name: admin_record_patch(uuid, jsonb, uuid, boolean); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_patch(id_value uuid, changes jsonb, actor uuid, approve boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE row_value jsonb;
BEGIN
 SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE id=id_value;
 IF row_value IS NULL OR row_value->>'status'='deleted' THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
 row_value:=pipeline_control.admin_record_compose(row_value,changes);
 IF approve THEN PERFORM pipeline_control.admin_record_validate_restaurant(row_value,ARRAY[id_value]);
 ELSE PERFORM pipeline_control.admin_record_identity_check(row_value,ARRAY[id_value]); END IF;
 PERFORM pipeline_control.admin_record_write(id_value,row_value,actor,approve);
END $$;


--
-- Name: admin_record_readback(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_readback(snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE entry record; result jsonb:='[]'; kind text; target uuid; status_value text;
BEGIN
 FOR entry IN SELECT key,value FROM jsonb_each(snapshot) ORDER BY key LOOP
  kind:=split_part(entry.key,':',1);target:=split_part(entry.key,':',2)::uuid;status_value:=NULL;
  IF entry.value='null'::jsonb THEN status_value:='deleted';
  ELSIF kind='restaurant' THEN SELECT status INTO status_value FROM public.restaurants WHERE id=target;
  ELSIF kind='submission' THEN SELECT status::text INTO status_value FROM public.restaurant_submissions WHERE id=target;
  ELSIF kind='item' THEN SELECT item_status INTO status_value FROM public.restaurant_submission_items WHERE id=target;
  ELSIF kind='recommendation' THEN SELECT status INTO status_value FROM public.restaurant_requests WHERE id=target;
  ELSIF kind='review' THEN SELECT CASE WHEN is_verified THEN 'approved' WHEN admin_note LIKE '거부: %' THEN 'rejected' ELSE 'pending' END INTO status_value FROM public.reviews WHERE id=target;
  END IF;
  IF status_value IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_READBACK_MISMATCH'; END IF;
  result:=result||jsonb_build_array(jsonb_build_object('id',target,'kind',kind,'status',status_value,'fingerprint',entry.value));
 END LOOP;
 RETURN result;
END $$;


--
-- Name: admin_record_reference_fence(); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_reference_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE media record;
BEGIN
  -- New references serialize with the exact bucket/object retirement claim.
  FOR media IN SELECT * FROM pipeline_control.admin_record_review_media(to_jsonb(NEW)) LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'review-media:' || media.bucket || ':' || media.object_name, 0));
    IF EXISTS (
      SELECT 1 FROM pipeline_control.admin_record_media_cleanup cleanup
      WHERE cleanup.bucket = media.bucket AND cleanup.object_name = media.object_name
        AND cleanup.state IN ('pending', 'inflight', 'uncertain', 'done')
    ) THEN
      RAISE EXCEPTION 'RECORD_ACTION_MEDIA_RETIRED';
    END IF;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: admin_record_review_media(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_review_media(row_value jsonb) RETURNS TABLE(bucket text, object_name text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  WITH food AS (
    SELECT 'review-photos'::text AS bucket, item.value AS object_name
    FROM jsonb_array_elements_text(
      coalesce(nullif(row_value->'food_photos', 'null'::jsonb), '[]'::jsonb)
    ) item(value)
    WHERE nullif(item.value, '') IS NOT NULL
  ), verification AS (
    SELECT candidate.bucket, nullif(row_value->>'verification_photo', '') AS object_name
    FROM (VALUES ('review-verifications'::text), ('review-photos'::text)) candidate(bucket)
    WHERE nullif(row_value->>'verification_photo', '') IS NOT NULL
  )
  SELECT DISTINCT media.bucket, media.object_name
  FROM (
    SELECT * FROM food
    UNION ALL SELECT * FROM verification
  ) media
  ORDER BY media.bucket, media.object_name
$$;


--
-- Name: admin_record_snapshot(text, uuid[]); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_snapshot(action text, ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE result jsonb:='{}'; row_value jsonb; related uuid[]:=ids; n integer;
BEGIN
 IF action LIKE 'restaurant.%' THEN
   IF action='restaurant.merge' THEN
    SELECT array_agg(DISTINCT r.id ORDER BY r.id) INTO related FROM public.restaurants r JOIN public.restaurants seed ON seed.id=ANY(ids)
     AND (r.id=seed.id OR (r.status<>'deleted' AND public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(r.approved_name,r.origin_name,r.naver_name,r.google_name))=public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(seed.approved_name,seed.origin_name,seed.naver_name,seed.google_name))
      AND nullif(coalesce(nullif(r.jibun_address,''),r.road_address),'')=nullif(coalesce(nullif(seed.jibun_address,''),seed.road_address),'')));
    IF cardinality(related)>25 THEN RAISE EXCEPTION 'RECORD_ACTION_LIMIT'; END IF;
   END IF;
   IF (SELECT count(*) FROM public.restaurants WHERE id=ANY(ids))<>cardinality(ids) THEN RAISE EXCEPTION 'RECORD_ACTION_NOT_FOUND'; END IF;
   FOR row_value IN SELECT to_jsonb(r) FROM public.restaurants r WHERE id=ANY(related) ORDER BY id LOOP
    result:=result||jsonb_build_object('restaurant:'||(row_value->>'id'),pipeline_control.admin_record_hash(row_value));
   END LOOP;

 ELSIF action LIKE 'submission.%' THEN
   SELECT to_jsonb(s) INTO row_value FROM public.restaurant_submissions s WHERE id=ids[1];
   IF row_value IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_NOT_FOUND'; END IF;
   result:=jsonb_build_object('submission:'||ids[1],pipeline_control.admin_record_hash(row_value));
   SELECT count(*) INTO n FROM public.restaurant_submission_items WHERE submission_id=ids[1];
   IF n>25 THEN RAISE EXCEPTION 'RECORD_ACTION_LIMIT'; END IF;
   FOR row_value IN SELECT to_jsonb(i) FROM public.restaurant_submission_items i WHERE submission_id=ids[1] ORDER BY id LOOP
    result:=result||jsonb_build_object('item:'||(row_value->>'id'),pipeline_control.admin_record_hash(row_value));
   END LOOP;
   SELECT array_agg(target_restaurant_id) INTO related FROM public.restaurant_submission_items WHERE submission_id=ids[1] AND target_restaurant_id IS NOT NULL;
 ELSIF action LIKE 'review.%' THEN
   SELECT to_jsonb(r) INTO row_value FROM public.reviews r WHERE id=ids[1];
   IF row_value IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_NOT_FOUND'; END IF;
   result:=jsonb_build_object('review:'||ids[1],pipeline_control.admin_record_hash(row_value||jsonb_build_object('__media_fingerprints',
    (SELECT jsonb_object_agg(bucket||':'||object_name,
      pipeline_control.admin_record_storage_snapshot(bucket,object_name))
     FROM pipeline_control.admin_record_review_media(row_value)))));
   related:=ARRAY[(row_value->>'restaurant_id')::uuid];
 ELSIF action LIKE 'recommendation.%' THEN
   SELECT to_jsonb(r) INTO row_value FROM public.restaurant_requests r WHERE id=ids[1];
   IF row_value IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_NOT_FOUND'; END IF;
   result:=jsonb_build_object('recommendation:'||ids[1],pipeline_control.admin_record_hash(row_value));
 END IF;
 IF action LIKE 'submission.%' OR action LIKE 'review.%' THEN
   FOR row_value IN SELECT to_jsonb(r) FROM public.restaurants r WHERE id=ANY(related) ORDER BY id LOOP
    result:=result||jsonb_build_object('restaurant:'||(row_value->>'id'),pipeline_control.admin_record_hash(row_value));
   END LOOP;
 END IF;
 RETURN result;
END $$;


--
-- Name: admin_record_storage_snapshot(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_storage_snapshot(path text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 SELECT pipeline_control.admin_record_hash(to_jsonb(o)-'last_accessed_at') FROM storage.objects o WHERE bucket_id='review-photos' AND name=path
$$;


--
-- Name: admin_record_storage_snapshot(text, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_storage_snapshot(p_bucket text, p_path text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT pipeline_control.admin_record_hash(to_jsonb(o) - 'last_accessed_at')
  FROM storage.objects o
  WHERE p_bucket IN ('review-photos', 'review-verifications')
    AND o.bucket_id = p_bucket AND o.name = p_path
$$;


--
-- Name: admin_record_validate_restaurant(jsonb, uuid[]); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_validate_restaurant(row_value jsonb, exclude_ids uuid[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE categories jsonb:=row_value->'categories';
BEGIN
 IF nullif(btrim(row_value->>'approved_name'),'') IS NULL OR length(row_value->>'approved_name')>160
  OR jsonb_typeof(categories) IS DISTINCT FROM 'array' OR jsonb_array_length(categories) NOT BETWEEN 1 AND 15
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(categories) x WHERE jsonb_typeof(x)<>'string' OR x#>>'{}' <> ALL(ARRAY['치킨','중식','돈까스·회','피자','패스트푸드','찜·탕','족발·보쌈','분식','카페·디저트','한식','고기','양식','아시안','야식','도시락']))
  OR (SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements(categories) x)
  OR jsonb_typeof(row_value->'lat') IS DISTINCT FROM 'number' OR jsonb_typeof(row_value->'lng') IS DISTINCT FROM 'number'
  OR (row_value->>'lat')::numeric NOT BETWEEN -90 AND 90 OR (row_value->>'lng')::numeric NOT BETWEEN -180 AND 180
  OR nullif(btrim(coalesce(row_value->>'jibun_address',row_value->>'road_address')),'') IS NULL
  OR row_value->'geocoding_success' IS DISTINCT FROM 'true'::jsonb
  OR coalesce(row_value->>'youtube_link','') !~ '^https://(www\.)?youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
 THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_RESTAURANT'; END IF;
 IF EXISTS(SELECT 1 FROM public.restaurants r WHERE NOT (id=ANY(array_remove(exclude_ids,NULL))) AND status<>'deleted'
  AND public.extract_youtube_video_id(r.youtube_link)=public.extract_youtube_video_id(row_value->>'youtube_link')
  AND public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(r.approved_name,r.origin_name,r.naver_name,r.google_name))=
      public.normalize_restaurant_identity_name(row_value->>'approved_name')) THEN RAISE EXCEPTION 'RECORD_ACTION_DUPLICATE'; END IF;
END $_$;


--
-- Name: admin_record_write(uuid, jsonb, uuid, boolean); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_record_write(id_value uuid, row_value jsonb, actor uuid, approve boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE patched public.restaurants:=jsonb_populate_record(NULL::public.restaurants,row_value);
BEGIN
 UPDATE public.restaurants SET approved_name=patched.approved_name,phone=patched.phone,categories=patched.categories,
  youtube_link=patched.youtube_link,tzuyang_review=patched.tzuyang_review,road_address=patched.road_address,jibun_address=patched.jibun_address,
  english_address=patched.english_address,address_elements=patched.address_elements,lat=patched.lat,lng=patched.lng,
  geocoding_success=patched.geocoding_success,youtube_meta=patched.youtube_meta,updated_by_admin_id=actor,updated_at=clock_timestamp(),
  status=CASE WHEN approve THEN 'approved' ELSE status END,is_missing=CASE WHEN approve THEN false ELSE is_missing END WHERE id=id_value;
END $$;


--
-- Name: admin_warning_budget(bigint, bigint); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_budget(pair_count bigint, edit_cells bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
 IF pair_count>25000 OR edit_cells>2000000 THEN RAISE EXCEPTION 'EVALUATION_WARNING_CAPACITY_EXCEEDED';END IF;
 RETURN true;
END;
$$;


--
-- Name: admin_warning_cell(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_cell(shape jsonb) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE lat double precision:=(shape->>'lat')::double precision;lng double precision:=(shape->>'lng')::double precision;
BEGIN
 IF lat IS NULL OR lng IS NULL THEN RETURN NULL;END IF;
 IF lat NOT BETWEEN -90 AND 90 OR lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'EVALUATION_WARNING_COORDINATE_UNSUPPORTED';END IF;
 RETURN ARRAY[floor(cos(lat*pi()/180)*cos(lng*pi()/180)/0.000004)::integer,
  floor(cos(lat*pi()/180)*sin(lng*pi()/180)/0.000004)::integer,floor(sin(lat*pi()/180)/0.000004)::integer];
END;
$$;


--
-- Name: admin_warning_display(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_display(value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE name text;location jsonb:=value#>'{evaluation_results,location_match_TF}';
BEGIN
 name:=pipeline_control.admin_eval_js_trim(value->>'approved_name');IF coalesce(name,'')<>'' THEN RETURN name;END IF;
 IF location->'eval_value'='true'::jsonb OR location->>'match_status'='matched' THEN
  FOREACH name IN ARRAY ARRAY[value->>'naver_name',CASE WHEN jsonb_typeof(location->'naver_name')='string' THEN location->>'naver_name' END,
    CASE WHEN location->>'matched_provider'='naver' AND jsonb_typeof(location->'matched_name')='string' THEN location->>'matched_name' END] LOOP
   name:=pipeline_control.admin_eval_js_trim(name);
   IF coalesce(name,'')<>'' AND pipeline_control.admin_warning_names_compatible(value->>'origin_name',name) THEN RETURN name;END IF;
  END LOOP;
 END IF;
 FOREACH name IN ARRAY ARRAY[value->>'restaurant_name',value->>'name',value->>'origin_name'] LOOP
  name:=pipeline_control.admin_eval_js_trim(name);IF coalesce(name,'')<>'' THEN RETURN name;END IF;
 END LOOP;RETURN '이름 없음';
END;
$$;


--
-- Name: admin_warning_distance(jsonb, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_distance(a jsonb, b jsonb) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE lat1 double precision;lat2 double precision;lng1 double precision;lng2 double precision;x double precision;dlat double precision;dlng double precision;
BEGIN
 IF a->'lat'='null'::jsonb OR a->'lng'='null'::jsonb OR b->'lat'='null'::jsonb OR b->'lng'='null'::jsonb THEN RETURN NULL;END IF;
 lat1:=(a->>'lat')::double precision;lat2:=(b->>'lat')::double precision;lng1:=(a->>'lng')::double precision;lng2:=(b->>'lng')::double precision;
 dlat:=(lat2-lat1)*pi()/180;dlng:=(lng2-lng1)*pi()/180;
 x:=sin(dlat/2)^2+cos(lat1*pi()/180)*cos(lat2*pi()/180)*sin(dlng/2)^2;
 IF x>1 OR x<0 THEN RETURN NULL;END IF;RETURN 2*6371000*asin(sqrt(x));
EXCEPTION WHEN numeric_value_out_of_range OR invalid_parameter_value THEN RETURN NULL;
END;
$$;


--
-- Name: admin_warning_evidence(jsonb, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_evidence(a jsonb, b jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE same_phone boolean:=coalesce(length(a->>'phone')>=7 AND a->>'phone'=b->>'phone',false);
 same_address boolean:=coalesce(a->>'address'<>'' AND a->>'address'=b->>'address',false);
 distance double precision;similarity double precision;
BEGIN
 IF a->>'identity'<>'' AND a->>'identity'=b->>'identity' THEN RETURN jsonb_build_object('rule','exact_identity','confidence',1);END IF;
 IF NOT same_phone AND NOT same_address THEN
  distance:=pipeline_control.admin_warning_distance(a,b);IF distance IS NULL OR distance>20 THEN RETURN NULL;END IF;
 END IF;
 similarity:=pipeline_control.admin_warning_similarity(a->>'identity',b->>'identity',CASE WHEN same_phone THEN 0.72 WHEN same_address THEN 0.82 ELSE 0.86 END);
 IF same_phone AND similarity>=0.72 THEN RETURN jsonb_build_object('rule','same_phone_similar_name','confidence',0.98);END IF;
 IF same_address AND similarity>=0.82 THEN RETURN jsonb_build_object('rule','same_address_similar_name','confidence',0.97);END IF;
 distance:=coalesce(distance,pipeline_control.admin_warning_distance(a,b));
 IF distance<=20 AND similarity>=0.86 THEN RETURN jsonb_build_object('rule','near_coordinate_similar_name','confidence',0.96);END IF;
 RETURN NULL;
END;
$$;


--
-- Name: admin_warning_info(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_info(value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE display text:=pipeline_control.admin_warning_display(value);candidate text;
 identity text:=coalesce(nullif(pipeline_control.admin_eval_js_trim(value->>'approved_name'),''),display);
 address text:=coalesce(nullif(value->>'jibun_address',''),nullif(value->>'road_address',''));
BEGIN
 candidate:=coalesce(nullif(pipeline_control.admin_eval_js_trim(value->>'approved_name'),''),nullif(pipeline_control.admin_eval_js_trim(value->>'naver_name'),''),
  nullif(pipeline_control.admin_eval_js_trim(value->>'google_name'),''),display,'이름 없음');
 RETURN jsonb_build_object('id',value->>'id','name',candidate,'status',CASE WHEN value->>'status' IN ('pending','approved','rejected','hold','deleted','missing','db_conflict','geocoding_failed','address_review_geocode_recovered','not_selected') THEN value->>'status' ELSE 'pending' END,
  'address',address,'adminTouched',coalesce(nullif(value->>'updated_by_admin_id','') IS NOT NULL,false),
  'origin_name',value->>'origin_name','candidate_name',candidate,
  'originKey',pipeline_control.admin_warning_key(value->>'origin_name',true),'candidateKey',pipeline_control.admin_warning_key(candidate,true),
  'shape',jsonb_build_object('identity',pipeline_control.admin_warning_key(identity),'address',pipeline_control.admin_warning_key(address),
   'phone',regexp_replace(coalesce(value->>'phone',''),'[^0-9]','','g'),
   'lat',CASE WHEN jsonb_typeof(value->'lat')='number' THEN value->'lat' END,'lng',CASE WHEN jsonb_typeof(value->'lng')='number' THEN value->'lng' END));
END;
$$;


--
-- Name: admin_warning_key(text, boolean); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_key(value text, identity boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE s text:=lower(pipeline_control.admin_warning_nfkc(value) COLLATE pipeline_control.admin_warning_case);
 spaces text:=E' \t\n\r\f'||chr(11)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279);
BEGIN
 IF identity THEN
  s:=regexp_replace(s,'\([^)]*\)|\[[^\]]*\]|（[^）]*）',' ','g');
  s:=regexp_replace(s,'(^|['||spaces||'])(구|현|전)(['||spaces||']|$)',' ','g');
 ELSE s:=regexp_replace(s,'\[[^\]]+\]|\([^)]*추정[^)]*\)|\([^)]*또는[^)]*\)',' ','g');END IF;
 s:=translate(s,spaces||'·・ㆍ._-–—,，()（）[]{}<>《》"''`´’‘“”'||CASE WHEN identity THEN ':：' ELSE '' END,'');
 IF NOT identity THEN s:=regexp_replace(s,'본점$|점$|입구$','','g');END IF;
 IF length(s)>256 OR cardinality(pipeline_control.admin_warning_utf16(s))>256 THEN RAISE EXCEPTION 'EVALUATION_WARNING_CAPACITY_EXCEEDED';END IF;
 RETURN pipeline_control.admin_eval_js_trim(s);
END;
$_$;


--
-- Name: admin_warning_names_compatible(text, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_names_compatible(origin text, candidate text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE a text:=pipeline_control.admin_warning_key(origin,true);b text:=pipeline_control.admin_warning_key(candidate,true);
BEGIN
 IF a='' OR b='' OR a=b OR (cardinality(pipeline_control.admin_warning_utf16(a))>=3 AND strpos(b,a)>0)
  OR (cardinality(pipeline_control.admin_warning_utf16(b))>=3 AND strpos(a,b)>0) THEN RETURN true;END IF;
 RETURN EXISTS(SELECT 1 FROM unnest(pipeline_control.admin_warning_tokens(origin)) l CROSS JOIN unnest(pipeline_control.admin_warning_tokens(candidate)) r
  WHERE l=r OR (cardinality(pipeline_control.admin_warning_utf16(l))>=3 AND strpos(r,l)>0)
  OR (cardinality(pipeline_control.admin_warning_utf16(r))>=3 AND strpos(l,r)>0));
END;
$$;


--
-- Name: admin_warning_nfkc(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_nfkc(value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE s text:=coalesce(value,'');
BEGIN
 IF octet_length(s)>8192 THEN RAISE EXCEPTION 'EVALUATION_WARNING_CAPACITY_EXCEEDED';END IF;
 s:=translate(s,'꟱𜳖𜳗𜳘𜳙𜳚𜳛𜳜𜳝𜳞𜳟𜳠𜳡𜳢𜳣𜳤𜳥𜳦𜳧𜳨𜳩𜳪𜳫𜳬𜳭𜳮𜳯𜳰𜳱𜳲𜳳𜳴𜳵𜳶𜳷𜳸𜳹','SABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');
 IF NOT unicode_assigned(s) THEN RAISE EXCEPTION 'EVALUATION_WARNING_UNICODE_UNSUPPORTED';END IF;
 RETURN normalize(s,NFKC);
END;
$$;


--
-- Name: admin_warning_similarity(text, text, double precision); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_similarity(a text, b text, minimum_score double precision DEFAULT 0) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE l integer[]:=pipeline_control.admin_warning_utf16(a);r integer[]:=pipeline_control.admin_warning_utf16(b);
 previous integer[];current integer[];i integer;j integer;n integer:=cardinality(l);m integer:=cardinality(r);
 cutoff integer;row_min integer;lo integer;hi integer;
BEGIN
 IF n>256 OR m>256 THEN RAISE EXCEPTION 'EVALUATION_WARNING_CAPACITY_EXCEEDED';END IF;
 IF n=0 OR m=0 THEN RETURN 0;END IF;IF a=b THEN RETURN 1;END IF;
 IF (n>=4 AND strpos(b,a)>0) OR (m>=4 AND strpos(a,b)>0) THEN RETURN 0.96;END IF;
 cutoff:=floor((1-minimum_score)*greatest(n,m));
 WHILE 1-(cutoff+1)::double precision/greatest(n,m)>=minimum_score LOOP cutoff:=cutoff+1;END LOOP;
 WHILE 1-cutoff::double precision/greatest(n,m)<minimum_score LOOP cutoff:=cutoff-1;END LOOP;
 IF abs(n-m)>cutoff THEN RETURN 0;END IF;
 SELECT array_agg(least(v,cutoff+1)) INTO previous FROM generate_series(0,m) v;
 FOR i IN 1..n LOOP
  current:=array_fill(cutoff+1,ARRAY[m+1]);current[1]:=i;row_min:=cutoff+1;
  lo:=greatest(1,i-cutoff);hi:=least(m,i+cutoff);
  FOR j IN lo..hi LOOP
   current[j+1]:=least(previous[j+1]+1,current[j]+1,previous[j]+CASE WHEN l[i]=r[j] THEN 0 ELSE 1 END);
   row_min:=least(row_min,current[j+1]);
  END LOOP;
  IF row_min>cutoff THEN RETURN 0;END IF;
  previous:=current;
 END LOOP;
 IF previous[m+1]>cutoff THEN RETURN 0;END IF;
 RETURN 1-previous[m+1]/greatest(n,m)::double precision;
END;
$$;


--
-- Name: admin_warning_tokens(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_tokens(value text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE token text;result text[]:='{}';s text:=pipeline_control.admin_warning_nfkc(value);
 spaces text:=E' \t\n\r\f'||chr(11)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279);
BEGIN
 s:=regexp_replace(s,'\(([^)]*)\)|（([^）]*)）',' \1 \2 ','g');
 s:=regexp_replace(s,'[·・ㆍ._\-–—,，\[\]{}<>《》"''`´’‘“”:：]',' ','g');
 FOR token IN SELECT pipeline_control.admin_eval_js_trim(v) FROM regexp_split_to_table(s,'['||spaces||']+') v LOOP
  IF cardinality(pipeline_control.admin_warning_utf16(token))>=2 AND token NOT IN ('구','현','전','내','본점') THEN
   token:=pipeline_control.admin_warning_key(regexp_replace(token,'점$',''),true);
   IF token<>'' AND NOT token=ANY(result) THEN result:=array_append(result,token);END IF;
  END IF;
 END LOOP;RETURN result;
END;
$_$;


--
-- Name: admin_warning_utf16(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.admin_warning_utf16(value text) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE units integer[]:='{}';position integer;point integer;
BEGIN
 FOR position IN 1..length(coalesce(value,'')) LOOP
  point:=ascii(substr(value,position,1));
  IF point>65535 THEN units:=units||ARRAY[55296+(point-65536)/1024,56320+(point-65536)%1024];
  ELSE units:=array_append(units,point);END IF;
 END LOOP;
 RETURN units;
END;
$$;


--
-- Name: assert_restaurant_review_operator(uuid); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.assert_restaurant_review_operator(actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.user_roles role JOIN public.user_account_status account ON account.user_id=role.user_id
    WHERE role.user_id=actor AND role.role='admin' AND account.account_status='active'
  ) THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_OPERATOR_INVALID' USING ERRCODE='42501'; END IF;
END;
$$;


--
-- Name: batch_upsert_restaurants(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.batch_upsert_restaurants(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_count integer;
    v_item jsonb;
    v_payload jsonb;
    v_expected jsonb;
    v_op text;
    v_id uuid;
    v_inserted integer := 0;
    v_updated integer := 0;
    v_ids uuid[] := ARRAY[]::uuid[];
    v_insert_cols text;
    v_insert_select text;
    v_set text;
    v_expected_id uuid;
    v_expected_trace text;
    v_expected_updated timestamptz;
    v_readback jsonb;
BEGIN
    IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
        RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
    END IF;

    v_count := jsonb_array_length(p_rows);
    IF v_count > 200 THEN
        RAISE EXCEPTION 'batch_upsert_limit' USING ERRCODE = '22023';
    END IF;

    IF v_count = 0 THEN
        RETURN jsonb_build_object(
            'inserted_count', 0,
            'updated_count', 0,
            'readback', '[]'::jsonb
        );
    END IF;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_rows) AS t(value)
    LOOP
        IF jsonb_typeof(v_item) <> 'object' THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        v_op := v_item->>'op';
        v_payload := v_item->'payload';
        v_expected := v_item->'expected';

        IF v_payload IS NULL OR jsonb_typeof(v_payload) <> 'object' THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        IF v_op = 'insert' THEN
            SELECT
                string_agg(format('%I', attribute.attname), ',' ORDER BY attribute.attnum),
                string_agg(format('populated.%I', attribute.attname), ',' ORDER BY attribute.attnum)
            INTO v_insert_cols, v_insert_select
            FROM pg_catalog.pg_attribute AS attribute
            WHERE attribute.attrelid = 'public.restaurants'::regclass
              AND attribute.attnum > 0
              AND NOT attribute.attisdropped
              AND attribute.attname IN (SELECT jsonb_object_keys(v_payload))
              AND attribute.attname <> 'id';

            IF v_insert_cols IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            EXECUTE format(
                'INSERT INTO public.restaurants (%s) SELECT %s FROM jsonb_populate_record(null::public.restaurants, $1) AS populated RETURNING id',
                v_insert_cols,
                v_insert_select
            ) INTO STRICT v_id USING v_payload;

            v_inserted := v_inserted + 1;
            v_ids := array_append(v_ids, v_id);

        ELSIF v_op = 'update' THEN
            IF v_expected IS NULL OR jsonb_typeof(v_expected) <> 'object' THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            BEGIN
                v_expected_id := (v_expected->>'id')::uuid;
                v_expected_updated := (v_expected->>'updated_at')::timestamptz;
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END;

            IF v_expected_id IS NULL OR v_expected->>'trace_id' IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            v_expected_trace := v_expected->>'trace_id';

            SELECT string_agg(
                format('%I = populated.%I', attribute.attname, attribute.attname),
                ',' ORDER BY attribute.attnum
            )
            INTO v_set
            FROM pg_catalog.pg_attribute AS attribute
            WHERE attribute.attrelid = 'public.restaurants'::regclass
              AND attribute.attnum > 0
              AND NOT attribute.attisdropped
              AND attribute.attname IN (SELECT jsonb_object_keys(v_payload))
              AND attribute.attname NOT IN ('id', 'updated_at');

            IF v_set IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            EXECUTE format(
                'UPDATE public.restaurants AS target SET %s, updated_at = now() '
                'FROM jsonb_populate_record(null::public.restaurants, $1) AS populated '
                'WHERE target.id = $2 '
                'AND target.trace_id IS NOT DISTINCT FROM $3 '
                'AND target.updated_at IS NOT DISTINCT FROM $4 '
                'RETURNING target.id',
                v_set
            ) INTO v_id USING v_payload, v_expected_id, v_expected_trace, v_expected_updated;

            IF v_id IS NULL THEN
                RAISE EXCEPTION 'compare_and_set_conflict' USING ERRCODE = '40001';
            END IF;

            v_updated := v_updated + 1;
            v_ids := array_append(v_ids, v_id);
        ELSE
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;
    END LOOP;

    SELECT COALESCE(jsonb_agg(to_jsonb(restaurant) ORDER BY ordinality.ord), '[]'::jsonb)
    INTO v_readback
    FROM unnest(v_ids) WITH ORDINALITY AS ordinality(id, ord)
    JOIN public.restaurants AS restaurant ON restaurant.id = ordinality.id;

    RETURN jsonb_build_object(
        'inserted_count', v_inserted,
        'updated_count', v_updated,
        'readback', v_readback
    );
END;
$_$;


