--
-- Name: checkpoint_job(uuid, integer, text, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.checkpoint_job(p_job_id uuid, p_adapter_index integer DEFAULT NULL::integer, p_worker_id text DEFAULT NULL::text, p_checkpoint jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    current pipeline_control.jobs%ROWTYPE;
    lock_name text;
    step_idx integer;
BEGIN
    SELECT * INTO current FROM pipeline_control.jobs WHERE id = p_job_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0001';
    END IF;
    lock_name := current.target || ':' || current.profile;
    step_idx := COALESCE(p_adapter_index, current.adapter_index);

    IF current.status NOT IN ('Queued', 'Fetching', 'Inserting', 'Paused') THEN
        RAISE EXCEPTION 'illegal_transition' USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO pipeline_control.job_steps (
        job_id, step_index, status, ended_at
    ) VALUES (
        current.id, step_idx, current.status, now()
    )
    ON CONFLICT (job_id, step_index) DO UPDATE SET
        status = EXCLUDED.status,
        ended_at = EXCLUDED.ended_at;

    IF current.cancel_requested THEN
        UPDATE pipeline_control.jobs SET
            adapter_index = step_idx,
            next_step = step_idx,
            checkpoint = COALESCE(p_checkpoint, '{}'::jsonb),
            heartbeat_at = now(),
            lease_until = now() + interval '30 seconds',
            worker_id = COALESCE(p_worker_id, worker_id),
            status = 'Cancelled',
            approved_at = now(),
            updated_at = now()
        WHERE id = current.id;
        DELETE FROM pipeline_control.locks WHERE lock_key = lock_name AND job_id = current.id;
        UPDATE pipeline_control.control_requests
        SET status = 'approved', approved_at = now()
        WHERE job_id = current.id AND action = 'cancel' AND status = 'requested';
        INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
        VALUES (COALESCE(p_worker_id, 'worker'), current.id, 'cancel_approved', current.request_id);
    ELSIF current.pause_requested AND current.status IN ('Fetching', 'Inserting', 'Queued') THEN
        UPDATE pipeline_control.jobs SET
            adapter_index = step_idx,
            next_step = step_idx,
            checkpoint = COALESCE(p_checkpoint, '{}'::jsonb),
            heartbeat_at = now(),
            lease_until = now() + interval '30 seconds',
            worker_id = COALESCE(p_worker_id, worker_id),
            status = 'Paused',
            approved_at = now(),
            updated_at = now()
        WHERE id = current.id;
        UPDATE pipeline_control.control_requests
        SET status = 'approved', approved_at = now()
        WHERE job_id = current.id AND action = 'pause' AND status = 'requested';
        INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
        VALUES (COALESCE(p_worker_id, 'worker'), current.id, 'pause_approved', current.request_id);
    ELSE
        UPDATE pipeline_control.jobs SET
            adapter_index = step_idx,
            next_step = step_idx,
            checkpoint = COALESCE(p_checkpoint, '{}'::jsonb),
            heartbeat_at = now(),
            lease_until = now() + interval '30 seconds',
            worker_id = COALESCE(p_worker_id, worker_id),
            updated_at = now()
        WHERE id = current.id;
    END IF;

    INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
    VALUES (COALESCE(p_worker_id, current.claimed_by, 'worker'), current.id, 'checkpoint', current.request_id);

    SELECT * INTO current FROM pipeline_control.jobs WHERE id = p_job_id;
    RETURN pipeline_control._job_json(current);
END;
$$;


--
-- Name: claim_job(text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.claim_job(p_worker_id text DEFAULT 'worker'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    picked uuid;
    claimed pipeline_control.jobs%ROWTYPE;
BEGIN
    SELECT j.id INTO picked
    FROM pipeline_control.jobs j
    WHERE j.status = 'Queued'
      AND j.pause_requested = false
      AND j.cancel_requested = false
    ORDER BY j.created_at ASC, j.id ASC
    FOR UPDATE SKIP LOCKED
    LIMIT 1;

    IF picked IS NULL THEN
        RETURN NULL;
    END IF;

    UPDATE pipeline_control.jobs
    SET status = 'Fetching',
        claimed_by = p_worker_id,
        worker_id = p_worker_id,
        claim_token = COALESCE(claim_token, gen_random_uuid()),
        attempt = attempt + 1,
        lease_until = now() + interval '30 seconds',
        heartbeat_at = now(),
        updated_at = now()
    WHERE id = picked
    RETURNING * INTO claimed;

    INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
    VALUES (p_worker_id, claimed.id, 'claim', claimed.request_id);

    RETURN pipeline_control._job_json(claimed);
END;
$$;


--
-- Name: claim_outbox(integer, uuid); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.claim_outbox(p_limit integer, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_limit integer := COALESCE(p_limit, 50);
    v_rows jsonb;
BEGIN
    IF p_claim_token IS NULL THEN
        RAISE EXCEPTION 'outbox_claim_token_required' USING ERRCODE = '22023';
    END IF;
    IF v_limit < 1 THEN
        RAISE EXCEPTION 'outbox_claim_limit' USING ERRCODE = '22023';
    END IF;
    IF v_limit > 50 THEN
        v_limit := 50;
    END IF;

    WITH picked AS (
        SELECT id
        FROM pipeline_control.outbox
        WHERE published_at IS NULL
          AND (claimed_at IS NULL OR claimed_at < now() - interval '30 seconds')
        ORDER BY id
        FOR UPDATE SKIP LOCKED
        LIMIT v_limit
    )
    UPDATE pipeline_control.outbox AS target
    SET
        claimed_at = now(),
        claim_token = p_claim_token,
        attempts = target.attempts + 1
    FROM picked
    WHERE target.id = picked.id;

    SELECT COALESCE(jsonb_agg(row_payload ORDER BY (row_payload->>'id')::bigint), '[]'::jsonb)
    INTO v_rows
    FROM (
        SELECT jsonb_build_object(
            'id', target.id,
            'event_id', target.event_id,
            'job_id', target.job_id,
            'event_type', target.event_type,
            'topic', target.topic,
            'payload', target.payload,
            'document_id', target.document_id,
            'created_at', target.created_at,
            'attempts', target.attempts
        ) AS row_payload
        FROM pipeline_control.outbox AS target
        WHERE target.claim_token = p_claim_token
          AND target.published_at IS NULL
        ORDER BY target.id
    ) claimed;

    RETURN COALESCE(v_rows, '[]'::jsonb);
END;
$$;


