--
-- Name: control_job(uuid, text, text, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.control_job(p_job_id uuid, p_action text, p_actor text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    current pipeline_control.jobs%ROWTYPE;
    lock_name text;
BEGIN
    SELECT * INTO current FROM pipeline_control.jobs WHERE id = p_job_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'run_not_found' USING ERRCODE = 'P0001';
    END IF;
    lock_name := current.target || ':' || current.profile;

    IF p_action = 'pause' THEN
        IF current.status NOT IN ('Queued', 'Fetching', 'Inserting') THEN
            RAISE EXCEPTION 'illegal_transition' USING ERRCODE = 'P0001';
        END IF;
        INSERT INTO pipeline_control.control_requests (
            job_id, action, actor, request_id, desired_action, status
        ) VALUES (current.id, 'pause', p_actor, p_request_id, 'pause', 'requested');
        IF current.status = 'Queued' THEN
            UPDATE pipeline_control.jobs SET
                pause_requested = true,
                desired_action = 'pause',
                requested_at = now(),
                approved_at = now(),
                control_version = control_version + 1,
                status = 'Paused',
                lease_until = now() + interval '30 seconds',
                heartbeat_at = now(),
                updated_at = now()
            WHERE id = current.id;
            UPDATE pipeline_control.control_requests
            SET status = 'approved', approved_at = now()
            WHERE id = (
                SELECT cr.id FROM pipeline_control.control_requests cr
                WHERE cr.job_id = current.id AND cr.action = 'pause'
                ORDER BY cr.id DESC LIMIT 1
            );
        ELSE
            UPDATE pipeline_control.jobs SET
                pause_requested = true,
                desired_action = 'pause',
                requested_at = now(),
                control_version = control_version + 1,
                lease_until = now() + interval '30 seconds',
                heartbeat_at = now(),
                updated_at = now()
            WHERE id = current.id;
        END IF;
        INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
        VALUES (p_actor, current.id, 'pause_requested', p_request_id);
        SELECT * INTO current FROM pipeline_control.jobs WHERE id = p_job_id;
        RETURN pipeline_control._job_json(current);
    END IF;

    IF p_action = 'cancel' THEN
        IF current.status NOT IN ('Queued', 'Fetching', 'Inserting', 'Paused') THEN
            RAISE EXCEPTION 'illegal_transition' USING ERRCODE = 'P0001';
        END IF;
        INSERT INTO pipeline_control.control_requests (
            job_id, action, actor, request_id, desired_action, status
        ) VALUES (current.id, 'cancel', p_actor, p_request_id, 'cancel', 'requested');
        IF current.status IN ('Queued', 'Paused') THEN
            UPDATE pipeline_control.jobs SET
                cancel_requested = true,
                desired_action = 'cancel',
                requested_at = now(),
                approved_at = now(),
                control_version = control_version + 1,
                status = 'Cancelled',
                updated_at = now()
            WHERE id = current.id;
            DELETE FROM pipeline_control.locks WHERE lock_key = lock_name AND job_id = current.id;
            UPDATE pipeline_control.control_requests
            SET status = 'approved', approved_at = now()
            WHERE id = (
                SELECT cr.id FROM pipeline_control.control_requests cr
                WHERE cr.job_id = current.id AND cr.action = 'cancel'
                ORDER BY cr.id DESC LIMIT 1
            );
        ELSE
            UPDATE pipeline_control.jobs SET
                cancel_requested = true,
                desired_action = 'cancel',
                requested_at = now(),
                control_version = control_version + 1,
                updated_at = now()
            WHERE id = current.id;
        END IF;
        INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
        VALUES (p_actor, current.id, 'cancel_requested', p_request_id);
        SELECT * INTO current FROM pipeline_control.jobs WHERE id = p_job_id;
        RETURN pipeline_control._job_json(current);
    END IF;

    IF p_action = 'resume' THEN
        IF current.status <> 'Paused' AND NOT current.pause_requested THEN
            RAISE EXCEPTION 'illegal_transition' USING ERRCODE = 'P0001';
        END IF;
        UPDATE pipeline_control.jobs SET
            pause_requested = false,
            desired_action = 'none',
            status = CASE WHEN status = 'Paused' THEN 'Queued' ELSE status END,
            lease_until = now() + interval '30 seconds',
            heartbeat_at = now(),
            control_version = control_version + 1,
            updated_at = now()
        WHERE id = current.id;
        INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
        VALUES (p_actor, current.id, 'resume', p_request_id);
        SELECT * INTO current FROM pipeline_control.jobs WHERE id = p_job_id;
        RETURN pipeline_control._job_json(current);
    END IF;

    RAISE EXCEPTION 'illegal_transition' USING ERRCODE = 'P0001';
END;
$$;


--
-- Name: enqueue_job(text, text, text, text, text, text, boolean, text, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.enqueue_job(p_target text, p_profile text, p_idempotency_key text, p_payload_hash text, p_actor text, p_request_id text, p_dry_run boolean DEFAULT true, p_execution_mode text DEFAULT 'dry_run'::text, p_data_sink text DEFAULT 'local'::text) RETURNS TABLE(run jsonb, created boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    existing pipeline_control.jobs%ROWTYPE;
    holder uuid;
    holder_status text;
    new_job pipeline_control.jobs%ROWTYPE;
    lock_name text := p_target || ':' || p_profile;
BEGIN
    SELECT * INTO existing
    FROM pipeline_control.jobs
    WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN
        IF existing.payload_hash <> p_payload_hash THEN
            RAISE EXCEPTION 'idempotency_payload_conflict' USING ERRCODE = 'P0001';
        END IF;
        run := pipeline_control._job_json(existing);
        created := false;
        RETURN NEXT;
        RETURN;
    END IF;

    SELECT l.job_id, j.status
    INTO holder, holder_status
    FROM pipeline_control.locks l
    JOIN pipeline_control.jobs j ON j.id = l.job_id
    WHERE l.lock_key = lock_name;
    IF holder IS NOT NULL AND holder_status IN ('Queued', 'Fetching', 'Inserting', 'Paused') THEN
        RAISE EXCEPTION 'lock_held' USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO pipeline_control.jobs (
        target, profile, status, idempotency_key, payload_hash, actor, request_id,
        lease_until, heartbeat_at, dry_run, execution_mode, data_sink
    ) VALUES (
        p_target, p_profile, 'Queued', p_idempotency_key, p_payload_hash, p_actor, p_request_id,
        now() + interval '30 seconds', now(), p_dry_run, p_execution_mode, p_data_sink
    ) RETURNING * INTO new_job;

    INSERT INTO pipeline_control.locks (lock_key, job_id)
    VALUES (lock_name, new_job.id)
    ON CONFLICT (lock_key) DO UPDATE SET job_id = EXCLUDED.job_id, held_since = now();

    INSERT INTO pipeline_control.audit (actor, job_id, transition, request_id)
    VALUES (p_actor, new_job.id, 'enqueue', p_request_id);

    run := pipeline_control._job_json(new_job);
    created := true;
    RETURN NEXT;
END;
$$;


--
-- Name: enqueue_outbox(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.enqueue_outbox(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_type text;
    v_topic text;
    v_event_id text;
    v_document_id text;
    v_job uuid;
    v_row pipeline_control.outbox%ROWTYPE;
BEGIN
    IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
        RAISE EXCEPTION 'outbox_payload_invalid' USING ERRCODE = '22023';
    END IF;

    v_type := p_payload->>'type';
    IF v_type IS NULL OR v_type NOT IN ('run.lifecycle', 'step.progress', 'record.upserted') THEN
        RAISE EXCEPTION 'outbox_event_type_unknown' USING ERRCODE = '22023';
    END IF;

    v_event_id := NULLIF(p_payload->>'event_id', '');
    v_document_id := NULLIF(p_payload->>'document_id', '');
    v_topic := NULLIF(p_payload->>'topic', '');
    IF v_event_id IS NULL OR v_document_id IS NULL OR v_topic IS NULL THEN
        RAISE EXCEPTION 'outbox_payload_invalid' USING ERRCODE = '22023';
    END IF;

    BEGIN
        v_job := NULLIF(p_payload->>'job_id', '')::uuid;
    EXCEPTION
        WHEN invalid_text_representation THEN
            v_job := NULL;
    END;

    INSERT INTO pipeline_control.outbox (
        event_id, job_id, event_type, topic, payload, document_id
    ) VALUES (
        v_event_id,
        v_job,
        v_type,
        v_topic,
        COALESCE(p_payload->'payload', p_payload),
        v_document_id
    )
    ON CONFLICT (event_id) DO NOTHING
    RETURNING * INTO v_row;

    IF NOT FOUND THEN
        SELECT * INTO v_row
        FROM pipeline_control.outbox
        WHERE event_id = v_event_id;
        RETURN jsonb_build_object(
            'id', v_row.id,
            'event_id', v_row.event_id,
            'document_id', v_row.document_id,
            'topic', v_row.topic,
            'created', false
        );
    END IF;

    RETURN jsonb_build_object(
        'id', v_row.id,
        'event_id', v_row.event_id,
        'document_id', v_row.document_id,
        'topic', v_row.topic,
        'created', true
    );
END;
$$;


--
-- Name: evidence_recovery_guard(uuid, uuid, bigint, text, text, uuid); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.evidence_recovery_guard(actor uuid, target uuid, policy_version bigint, row_sha text, input_sha text, own_job uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE policy pipeline_control.restaurant_review_policy; row_value jsonb;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton;
 IF NOT FOUND OR NOT policy.enabled OR policy.operator_id IS DISTINCT FROM actor
   OR policy.version IS DISTINCT FROM policy_version THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_POLICY_CHANGED'; END IF;
 PERFORM pipeline_control.assert_restaurant_review_operator(actor);
 SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE r.id=target;
 IF row_value IS NULL THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_NOT_FOUND'; END IF;
 IF row_value->>'status' IS DISTINCT FROM 'hold'
   OR nullif(row_value->>'created_by','') IS NOT NULL OR nullif(row_value->>'updated_by_admin_id','') IS NOT NULL
   OR row_value->>'source_type' IN ('admin','manual','user') OR row_value->'is_not_selected'='true'::jsonb
   OR row_value#>>'{db_error_details,error_type}'='duplicate'
   OR nullif(row_value#>>'{db_error_details,conflicting_restaurant,id}','') IS NOT NULL
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_PROTECTED'; END IF;
 IF coalesce(row_value->>'youtube_link','') !~ '^https://(www\.)?youtube\.com/watch\?v=[A-Za-z0-9_-]{11}$'
   OR nullif(btrim(row_value->>'origin_name'),'') IS NULL OR nullif(btrim(row_value->>'trace_id'),'') IS NULL
   OR length(row_value->>'origin_name')>160 OR row_value->>'updated_at' IS NULL
   OR coalesce(row_value->>'channel_name','') NOT IN ('','tzuyang')
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_SOURCE_REQUIRED'; END IF;
 IF pipeline_control.admin_record_hash(row_value) IS DISTINCT FROM row_sha
   OR pipeline_control.evidence_recovery_input_sha(row_value) IS DISTINCT FROM input_sha
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_STALE'; END IF;
 IF EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items i WHERE i.restaurant_id=target AND
   (i.state IN ('queued','running') OR (i.state='failed' AND i.reason NOT IN ('source_unavailable','gemini_configuration_invalid'))))
   OR EXISTS(SELECT 1 FROM pipeline_control.restaurant_evidence_recovery_jobs j WHERE j.restaurant_id=target
     AND j.id IS DISTINCT FROM own_job AND j.state IN ('queued','running','draft','uncertain'))
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_WORK_OUTSTANDING'; END IF;
 RETURN row_value;
END $_$;


--
-- Name: evidence_recovery_input_sha(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.evidence_recovery_input_sha(row_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT pipeline_control.admin_record_hash(row_value-ARRAY['search_count','weekly_search_count','review_count','updated_at'])
$$;


--
-- Name: restaurant_evidence_recovery_jobs; Type: TABLE; Schema: pipeline_control; Owner: -
--

CREATE TABLE pipeline_control.restaurant_evidence_recovery_jobs (
    id uuid NOT NULL,
    restaurant_id uuid NOT NULL,
    actor uuid NOT NULL,
    policy_version bigint NOT NULL,
    row_sha256 text NOT NULL,
    input_sha256 text NOT NULL,
    video_id text NOT NULL,
    original_row jsonb NOT NULL,
    request_operation_id uuid NOT NULL,
    state text NOT NULL,
    reason text NOT NULL,
    worker_token uuid,
    lease_until timestamp with time zone,
    result jsonb,
    result_sha256 text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT restaurant_evidence_recovery_jobs_input_sha256_check CHECK ((input_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT restaurant_evidence_recovery_jobs_original_row_check CHECK ((jsonb_typeof(original_row) = 'object'::text)),
    CONSTRAINT restaurant_evidence_recovery_jobs_reason_check CHECK ((reason = ANY (ARRAY['queued'::text, 'claimed'::text, 'evidence_ready'::text, 'evidence_applied'::text, 'source_unavailable'::text, 'gemini_configuration_invalid'::text, 'evaluation_incomplete'::text, 'result_invalid'::text, 'evaluation_failed'::text, 'gemini_result_uncertain'::text, 'gemini_decision_invalid'::text, 'gemini_decision_incomplete'::text, 'worker_timeout'::text, 'source_incomplete'::text, 'source_local_missing'::text, 'source_input_invalid'::text, 'source_identity_mismatch'::text, 'source_recollect_mismatch'::text, 'source_channel_unverified'::text, 'source_original_evidence_missing'::text, 'source_provider_transient'::text, 'source_provider_unavailable'::text, 'result_unconfirmed'::text, 'source_changed'::text, 'policy_changed'::text]))),
    CONSTRAINT restaurant_evidence_recovery_jobs_result_sha256_check CHECK ((result_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT restaurant_evidence_recovery_jobs_row_sha256_check CHECK ((row_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT restaurant_evidence_recovery_jobs_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'running'::text, 'draft'::text, 'applied'::text, 'failed'::text, 'uncertain'::text]))),
    CONSTRAINT restaurant_evidence_recovery_jobs_video_id_check CHECK ((video_id ~ '^[A-Za-z0-9_-]{11}$'::text))
);


--
-- Name: evidence_recovery_metadata(pipeline_control.restaurant_evidence_recovery_jobs, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.evidence_recovery_metadata(job pipeline_control.restaurant_evidence_recovery_jobs, receipt jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object('schemaVersion',1,'jobId',job.id,'state',job.state,'reason',job.reason,
  'restaurantId',job.restaurant_id,'policyVersion',job.policy_version,'rowSha256',job.row_sha256,
  'inputSha256',job.input_sha256,'videoId',job.video_id,'resultSha256',job.result_sha256,'receipt',receipt)
$$;


--
-- Name: evidence_recovery_validate_result(jsonb, jsonb, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.evidence_recovery_validate_result(result jsonb, original jsonb, input_sha text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE evaluation jsonb; metric text; value jsonb; location jsonb; field text;
 allowed text[]:=ARRAY['evaluation_results','geocoding_success','geocoding_false_stage','lat','lng',
   'road_address','jibun_address','english_address','address_elements','naver_name','google_name','categories','gemini_decision'];
BEGIN
 IF jsonb_typeof(result) IS DISTINCT FROM 'object' OR octet_length(result::text)>131072
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(result) k WHERE NOT k=ANY(allowed))
   OR NOT pipeline_control.restaurant_review_gemini_valid(result->'gemini_decision',input_sha)
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 evaluation:=result->'evaluation_results';
 IF jsonb_typeof(evaluation) IS DISTINCT FROM 'object' OR
   EXISTS(SELECT 1 FROM jsonb_object_keys(evaluation) k WHERE NOT k=ANY(ARRAY[
    'visit_authenticity','rb_inference_score','rb_grounding_TF','review_faithfulness_score',
    'category_validity_TF','category_TF','location_match_TF']))
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 FOREACH metric IN ARRAY ARRAY['visit_authenticity','rb_inference_score','rb_grounding_TF',
   'review_faithfulness_score','category_validity_TF','category_TF'] LOOP
  value:=evaluation->metric;
  IF jsonb_typeof(value) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(value) k
    WHERE k NOT IN ('name','eval_value','eval_basis','category_revision')) THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
  IF metric IN ('visit_authenticity','rb_inference_score','review_faithfulness_score') THEN
   IF jsonb_typeof(value->'eval_value') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
   IF (value->>'eval_value')::numeric<0 OR (value->>'eval_value')::numeric>
     (CASE metric WHEN 'visit_authenticity' THEN 4 WHEN 'rb_inference_score' THEN 2 ELSE 1 END)
     OR (metric<>'review_faithfulness_score' AND trunc((value->>'eval_value')::numeric)<>(value->>'eval_value')::numeric)
   THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
  ELSIF jsonb_typeof(value->'eval_value') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
  IF metric NOT IN ('category_validity_TF','category_TF') AND
    (jsonb_typeof(value->'eval_basis') IS DISTINCT FROM 'string'
     OR btrim(value->>'eval_basis') IN ('','-','근거 내용 없음','평가 근거 없음','평가근거없음'))
  THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 END LOOP;
 location:=evaluation->'location_match_TF';
 IF jsonb_typeof(location) IS DISTINCT FROM 'object'
   OR jsonb_typeof(location->'eval_value') IS DISTINCT FROM 'boolean'
   OR lower(btrim(location->>'origin_name')) IS DISTINCT FROM lower(btrim(original->>'origin_name'))
   OR coalesce(location->>'match_status','') NOT IN ('matched','pending','failed','unmatched')
   OR jsonb_typeof(location->'evidence_families') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(location) k WHERE k NOT IN (
   'name','origin_name','eval_value','match_status','matched_provider','matched_name','naver_name','google_name',
   'origin_address','matched_address','naver_address','evidence_summary','evidence_families','pending_reason',
   'second_pass','falseMessage','identity_state','auto_closed_store','auto_relocated'))
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(location->'evidence_families') f WHERE jsonb_typeof(f)<>'string'
   OR f#>>'{}' NOT IN ('provider_candidate','source_geo','cross_provider','browser_verification','geocode_provider','llm_verification'))
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF location->'eval_value'='true'::jsonb AND (location->>'match_status'<>'matched'
   OR nullif(location->>'pending_reason','') IS NOT NULL OR nullif(location->>'falseMessage','') IS NOT NULL
   OR (SELECT count(DISTINCT f) FROM jsonb_array_elements_text(location->'evidence_families') f WHERE f<>'llm_verification')<2)
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF location->'eval_value'='false'::jsonb AND (location->>'match_status'='matched'
   OR (coalesce(location->>'pending_reason','') NOT IN
     ('insufficient_evidence','cross_country_mismatch','ambiguous_chain','multi_candidate','timeout','rate_limited')
     AND nullif(btrim(location->>'falseMessage'),'') IS NULL))
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF jsonb_typeof(result->'geocoding_success') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 FOREACH field IN ARRAY ARRAY['lat','lng'] LOOP
  IF result ? field AND result->field<>'null'::jsonb THEN
   IF jsonb_typeof(result->field)<>'number' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
   IF (result->>field)::numeric NOT BETWEEN (CASE field WHEN 'lat' THEN -90 ELSE -180 END) AND
     (CASE field WHEN 'lat' THEN 90 ELSE 180 END) THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
  END IF;
 END LOOP;
 IF result->'geocoding_success'='true'::jsonb AND
   (jsonb_typeof(result->'lat') IS DISTINCT FROM 'number' OR jsonb_typeof(result->'lng') IS DISTINCT FROM 'number'
    OR nullif(btrim(result->>'jibun_address'),'') IS NULL) THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 FOREACH field IN ARRAY ARRAY['road_address','jibun_address','english_address','naver_name','google_name'] LOOP
  IF result ? field AND (jsonb_typeof(result->field) NOT IN ('null','string') OR length(result->>field)>4000)
  THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 END LOOP;
 IF result ? 'address_elements' AND jsonb_typeof(result->'address_elements') NOT IN ('object','array','null')
   OR (result ? 'geocoding_false_stage' AND result->'geocoding_false_stage'<>'null'::jsonb AND
     (jsonb_typeof(result->'geocoding_false_stage')<>'number' OR result->>'geocoding_false_stage' !~ '^[0-9]+$'))
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF result ? 'geocoding_false_stage' AND result->'geocoding_false_stage'<>'null'::jsonb
   AND (result->>'geocoding_false_stage')::numeric>2147483647 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF jsonb_typeof(result->'categories') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
 IF jsonb_array_length(result->'categories') NOT BETWEEN 1 AND 15 OR
   EXISTS(SELECT 1 FROM jsonb_array_elements(result->'categories') x WHERE jsonb_typeof(x)<>'string' OR
    x#>>'{}' NOT IN ('치킨','중식','돈까스·회','피자','패스트푸드','찜·탕','족발·보쌈','분식','카페·디저트','한식','고기','양식','아시안','야식','도시락'))
   OR (SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements(result->'categories') x)
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_INVALID'; END IF;
END $_$;


--
-- Name: hosted_pending_apply(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.hosted_pending_apply(request_id uuid, sender_id uuid, binding_sha text, rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
DECLARE operation pipeline_control.hosted_pending_operations; items jsonb; item jsonb; current_item jsonb;
  original_item jsonb; payload jsonb; result_value jsonb:='[]'; row_id uuid; blocked boolean:=false;
BEGIN
 items:=pipeline_control.pending_items(rows);
 LOCK TABLE public.restaurants IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE pipeline_control.hosted_pending_legacy_holds IN SHARE MODE;
 SELECT * INTO operation FROM pipeline_control.hosted_pending_operations o WHERE o.request_id=hosted_pending_apply.request_id FOR UPDATE;
 IF NOT FOUND OR binding_sha IS DISTINCT FROM operation.binding_sha
   OR operation.sender_id IS DISTINCT FROM sender_id
   OR pipeline_control.pending_digest(jsonb_build_array(operation.source_revision,operation.freshness,items))<>operation.binding_sha
 THEN RAISE EXCEPTION 'PENDING_REQUEST_DRIFT' USING ERRCODE='22023'; END IF;
 IF operation.state='committed' THEN RETURN jsonb_build_object('state','committed','replayed',true,'rows',operation.result); END IF;
 IF operation.state<>'claimed' THEN RAISE EXCEPTION 'PENDING_STATE_HELD' USING ERRCODE='55000'; END IF;
 -- Preflight ALL members before any restaurant insert. Admin edits are preserved.
 FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
  current_item:=pipeline_control.pending_current(item);
  IF EXISTS(SELECT 1 FROM pipeline_control.hosted_pending_legacy_holds h WHERE h.video=item->>'video') THEN
   current_item:=jsonb_build_object('action','unresolved');
  END IF;
  SELECT value INTO original_item FROM jsonb_array_elements(operation.items) WHERE value->>'video'=item->>'video' AND value->>'name'=item->>'name';
  IF current_item->>'action'='absent' AND (
    original_item#>>'{atPrepare,action}'<>'absent' OR NOT EXISTS(SELECT 1 FROM pipeline_control.hosted_pending_identity_custody c
      WHERE c.video=item->>'video' AND c.name=item->>'name' AND c.request_id=hosted_pending_apply.request_id))
  THEN current_item:=jsonb_build_object('action','unresolved'); END IF;
  blocked:=blocked OR current_item->>'action'='unresolved';
  result_value:=result_value||jsonb_build_array(jsonb_build_object('identitySha',pipeline_control.pending_digest(jsonb_build_array(item->>'video',item->>'name')),
    'video',item->>'video')||current_item);
 END LOOP;
 IF blocked THEN
  UPDATE pipeline_control.hosted_pending_operations o SET state='held',result=result_value WHERE o.request_id=hosted_pending_apply.request_id;
  RETURN jsonb_build_object('state','held','replayed',false,'rows',result_value);
 END IF;
 result_value:='[]';
 FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
  current_item:=pipeline_control.pending_current(item);
  IF EXISTS(SELECT 1 FROM pipeline_control.hosted_pending_legacy_holds h WHERE h.video=item->>'video') THEN
   current_item:=jsonb_build_object('action','unresolved');
  END IF;
  IF current_item->>'action'='absent' THEN
   SELECT value INTO payload FROM jsonb_array_elements(rows) WHERE pipeline_control.pending_digest(value)=item->>'payloadSha' LIMIT 1;
   INSERT INTO public.restaurants(trace_id,youtube_link,channel_name,recollect_version,status,origin_name,reasoning_basis,
     naver_name,google_name,categories,tzuyang_review,origin_address,road_address,jibun_address,english_address,lat,lng,
     geocoding_success,is_missing,is_not_selected,youtube_meta,evaluation_results,source_type,review_count)
   SELECT p.trace_id,p.youtube_link,p.channel_name,p.recollect_version,'pending',p.origin_name,p.reasoning_basis,
     p.naver_name,p.google_name,p.categories,p.tzuyang_review,p.origin_address,p.road_address,p.jibun_address,p.english_address,p.lat,p.lng,
     p.geocoding_success,p.is_missing,p.is_not_selected,p.youtube_meta,p.evaluation_results,p.source_type,0
   FROM jsonb_populate_record(NULL::public.restaurants,payload) p RETURNING id INTO row_id;
   current_item:=jsonb_build_object('action','inserted','id',row_id);
  END IF;
  result_value:=result_value||jsonb_build_array(jsonb_build_object('identitySha',pipeline_control.pending_digest(jsonb_build_array(item->>'video',item->>'name')),
    'video',item->>'video')||current_item);
 END LOOP;
 UPDATE pipeline_control.hosted_pending_operations o SET state='committed',result=result_value WHERE o.request_id=hosted_pending_apply.request_id;
 RETURN jsonb_build_object('state','committed','replayed',false,'rows',result_value);
EXCEPTION WHEN OTHERS THEN
 RAISE EXCEPTION 'PENDING_APPLY_FAILED' USING ERRCODE=SQLSTATE;
END $$;


--
-- Name: hosted_pending_claim(uuid, uuid, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.hosted_pending_claim(request_id uuid, sender_id uuid, binding_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
DECLARE operation pipeline_control.hosted_pending_operations;
BEGIN
 IF sender_id IS NULL THEN RAISE EXCEPTION 'PENDING_SENDER_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO operation FROM pipeline_control.hosted_pending_operations o WHERE o.request_id=hosted_pending_claim.request_id FOR UPDATE;
 IF NOT FOUND OR binding_sha IS DISTINCT FROM operation.binding_sha THEN RAISE EXCEPTION 'PENDING_REQUEST_DRIFT' USING ERRCODE='22023'; END IF;
 IF operation.state<>'prepared' THEN RETURN jsonb_build_object('claimed',false,'state',operation.state); END IF;
 UPDATE pipeline_control.hosted_pending_operations o SET state='claimed',sender_id=hosted_pending_claim.sender_id WHERE o.request_id=hosted_pending_claim.request_id;
 RETURN jsonb_build_object('claimed',true,'state','claimed');
END $$;


--
-- Name: hosted_pending_prepare(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.hosted_pending_prepare(request_id uuid, source_revision text, freshness jsonb, rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $_$
DECLARE items jsonb; binding text; operation pipeline_control.hosted_pending_operations;
  item jsonb; current_item jsonb; augmented jsonb:='[]'; owner_id uuid; blocked boolean:=false;
BEGIN
 IF request_id IS NULL OR source_revision IS NULL OR source_revision !~ '^[0-9a-f]{40}$'
   OR freshness IS NULL OR jsonb_typeof(freshness)<>'object'
   OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(freshness) k) IS DISTINCT FROM ARRAY['complete','contract','inputSha256','sourceSha256']::text[]
   OR freshness->>'contract' IS DISTINCT FROM 'local-pipeline-candidate-set-v1'
   OR freshness->'complete' IS DISTINCT FROM 'true'::jsonb
   OR coalesce(freshness->>'inputSha256','') !~ '^[0-9a-f]{64}$'
   OR coalesce(freshness->>'sourceSha256','') !~ '^[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PENDING_FRESHNESS_INVALID' USING ERRCODE='22023'; END IF;
 items:=pipeline_control.pending_items(rows);
 binding:=pipeline_control.pending_digest(jsonb_build_array(source_revision,freshness,items));
 -- Universal table lock also blocks noncooperating ordinary restaurant DML.
 -- Consistent order: restaurant table, then custody/operation row locks.
 LOCK TABLE public.restaurants IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE pipeline_control.hosted_pending_legacy_holds IN SHARE MODE;
 SELECT * INTO operation FROM pipeline_control.hosted_pending_operations o WHERE o.request_id=hosted_pending_prepare.request_id;
 IF FOUND AND operation.binding_sha<>binding THEN RAISE EXCEPTION 'PENDING_REQUEST_DRIFT' USING ERRCODE='22023'; END IF;
 SELECT * INTO operation FROM pipeline_control.hosted_pending_operations o WHERE o.binding_sha=binding;
 IF FOUND THEN RETURN jsonb_build_object('requestId',operation.request_id,'state',operation.state,'created',false,'bindingSha',binding); END IF;
 INSERT INTO pipeline_control.hosted_pending_operations VALUES(request_id,binding,source_revision,freshness,items,'prepared',NULL,NULL,clock_timestamp());
 FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
  current_item:=pipeline_control.pending_current(item);
  IF EXISTS(SELECT 1 FROM pipeline_control.hosted_pending_legacy_holds h WHERE h.video=item->>'video') THEN
   current_item:=jsonb_build_object('action','unresolved');
  END IF;
  IF EXISTS(SELECT 1 FROM pipeline_control.hosted_pending_operations prior
    WHERE prior.request_id<>hosted_pending_prepare.request_id AND prior.state<>'committed'
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(prior.items) other WHERE other->>'video'=item->>'video'))
  THEN current_item:=jsonb_build_object('action','unresolved'); END IF;
  IF current_item->>'action'='absent' THEN
   SELECT c.request_id INTO owner_id FROM pipeline_control.hosted_pending_identity_custody c WHERE c.video=item->>'video' AND c.name=item->>'name';
   IF owner_id IS NOT NULL AND owner_id<>request_id THEN current_item:=jsonb_build_object('action','unresolved'); END IF;
  END IF;
  blocked:=blocked OR current_item->>'action'='unresolved';
  augmented:=augmented||jsonb_build_array(item||jsonb_build_object('atPrepare',current_item));
 END LOOP;
 IF NOT blocked THEN
  FOR item IN SELECT value FROM jsonb_array_elements(augmented) WHERE value#>>'{atPrepare,action}'='absent' LOOP
   INSERT INTO pipeline_control.hosted_pending_identity_custody VALUES(item->>'video',item->>'name',request_id);
  END LOOP;
 END IF;
 UPDATE pipeline_control.hosted_pending_operations o SET items=augmented,state=CASE WHEN blocked THEN 'held' ELSE 'prepared' END WHERE o.request_id=hosted_pending_prepare.request_id;
 RETURN jsonb_build_object('requestId',request_id,'state',CASE WHEN blocked THEN 'held' ELSE 'prepared' END,'created',true,'bindingSha',binding);
END $_$;


--
-- Name: hosted_pending_read(uuid, text[]); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.hosted_pending_read(request_id uuid DEFAULT NULL::uuid, video_ids text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE answer jsonb; n integer;
BEGIN
 IF request_id IS NOT NULL AND video_ids IS NULL THEN
  RETURN pipeline_control.pending_request_read(request_id);
 ELSIF request_id IS NULL AND cardinality(video_ids) BETWEEN 1 AND 100 AND NOT EXISTS(SELECT 1 FROM unnest(video_ids) v WHERE v IS NULL OR v !~ '^[A-Za-z0-9_-]{11}$') THEN
  SELECT count(*) INTO n FROM (SELECT 1 FROM pipeline_control.hosted_pending_operations o
   WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(o.items) i WHERE i->>'video'=ANY(video_ids)) LIMIT 101) bounded;
  IF n>100 THEN RAISE EXCEPTION 'PENDING_DISCOVERY_UNBOUNDED' USING ERRCODE='54000'; END IF;
  SELECT coalesce(jsonb_agg(pipeline_control.pending_request_read(o.request_id) ORDER BY o.created_at,o.request_id),'[]')
   INTO answer FROM pipeline_control.hosted_pending_operations o
   WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(o.items) i WHERE i->>'video'=ANY(video_ids));
  RETURN jsonb_build_object('videos',to_jsonb(video_ids),'legacyHeld',coalesce((SELECT jsonb_agg(h.video ORDER BY h.video) FROM pipeline_control.hosted_pending_legacy_holds h WHERE h.video=ANY(video_ids)),'[]'),
    'operations',answer,'replayAllowed',false);
 END IF;
 RAISE EXCEPTION 'PENDING_READ_INVALID' USING ERRCODE='22023';
END $_$;


--
-- Name: lock_restaurant_review_catalog_revision(); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.lock_restaurant_review_catalog_revision() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
BEGIN
  PERFORM 1 FROM pipeline_control.admin_evaluation_catalog_revision WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_STALE'; END IF;
END;
$$;


--
-- Name: pending_current(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.pending_current(item jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE active_ids uuid[]; conflict boolean; deleted boolean;
BEGIN
 SELECT array_agg(r.id ORDER BY r.id) FILTER(WHERE r.status<>'deleted' AND
   public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(r.approved_name,r.origin_name,r.naver_name,r.google_name))=item->>'name'),
   coalesce(bool_or(
    (r.trace_id=item->>'trace' AND (public.extract_youtube_video_id(r.youtube_link) IS DISTINCT FROM item->>'video'
      OR public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(r.approved_name,r.origin_name,r.naver_name,r.google_name)) IS DISTINCT FROM item->>'name'))
    OR (public.extract_youtube_video_id(r.youtube_link)=item->>'video' AND item->>'name'=ANY(ARRAY[
       public.normalize_restaurant_identity_name(r.approved_name),public.normalize_restaurant_identity_name(r.origin_name),
       public.normalize_restaurant_identity_name(r.naver_name),public.normalize_restaurant_identity_name(r.google_name)])
      AND public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(r.approved_name,r.origin_name,r.naver_name,r.google_name)) IS DISTINCT FROM item->>'name')
   ),false),
   coalesce(bool_or(r.status='deleted' AND (r.trace_id=item->>'trace' OR
      (public.extract_youtube_video_id(r.youtube_link)=item->>'video' AND
       public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(r.approved_name,r.origin_name,r.naver_name,r.google_name))=item->>'name'))),false)
 INTO active_ids,conflict,deleted FROM public.restaurants r
 WHERE public.extract_youtube_video_id(r.youtube_link)=item->>'video' OR r.trace_id=item->>'trace';
 IF conflict OR coalesce(cardinality(active_ids),0)>1 THEN RETURN jsonb_build_object('action','unresolved'); END IF;
 IF cardinality(active_ids)=1 THEN RETURN jsonb_build_object('action','present','id',active_ids[1]); END IF;
 IF deleted THEN RETURN jsonb_build_object('action','unresolved'); END IF;
 RETURN jsonb_build_object('action','absent');
END $$;


--
-- Name: pending_digest(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.pending_digest(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT encode(sha256(convert_to(value::text,'UTF8')),'hex');
$$;


--
-- Name: pending_items(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.pending_items(rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE row_value jsonb; items jsonb:='[]'; video text; name text; item jsonb;
  allowed text[]:=ARRAY['trace_id','youtube_link','channel_name','recollect_version','status',
   'origin_name','reasoning_basis','naver_name','google_name','categories','tzuyang_review',
   'origin_address','road_address','jibun_address','english_address','lat','lng',
   'geocoding_success','is_missing','is_not_selected','youtube_meta','evaluation_results',
   'source_type','review_count'];
BEGIN
 IF rows IS NULL OR jsonb_typeof(rows)<>'array' OR jsonb_array_length(rows) NOT BETWEEN 1 AND 200
   OR octet_length(rows::text)>2097152
 THEN RAISE EXCEPTION 'PENDING_INPUT_INVALID' USING ERRCODE='22023'; END IF;
 FOR row_value IN SELECT value FROM jsonb_array_elements(rows) LOOP
  IF jsonb_typeof(row_value)<>'object'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(row_value) k WHERE NOT(k=ANY(allowed)))
    OR NOT(row_value ?& allowed)
    OR row_value->>'status' IS DISTINCT FROM 'pending'
    OR row_value->'review_count' IS DISTINCT FROM '0'::jsonb
    OR row_value->'is_missing' IS DISTINCT FROM 'false'::jsonb
    OR row_value->'is_not_selected' IS DISTINCT FROM 'false'::jsonb
    OR jsonb_typeof(row_value->'trace_id') IS DISTINCT FROM 'string'
    OR row_value->>'trace_id' !~ '^[A-Za-z0-9_-]{1,128}$'
    OR (
      (row_value->'geocoding_success'='true' AND jsonb_typeof(row_value->'lat')='number' AND jsonb_typeof(row_value->'lng')='number')
      OR (row_value#>>'{evaluation_results,location_match_TF,pending_reason}' IN ('ambiguous_chain','multi_candidate','insufficient_evidence')
       AND coalesce(row_value#>>'{evaluation_results,location_match_TF,match_status}','')<>'confirmed_from_video')
    ) IS NOT TRUE
  THEN RAISE EXCEPTION 'PENDING_INPUT_INVALID' USING ERRCODE='22023'; END IF;
  video:=public.extract_youtube_video_id(row_value->>'youtube_link');
  name:=public.normalize_restaurant_identity_name(public.resolve_restaurant_identity_name(NULL,
    row_value->>'origin_name',row_value->>'naver_name',row_value->>'google_name'));
  IF coalesce(video,'') !~ '^[A-Za-z0-9_-]{11}$' OR name IS NULL THEN
    RAISE EXCEPTION 'PENDING_IDENTITY_INVALID' USING ERRCODE='22023'; END IF;
  item:=jsonb_build_object('video',video,'name',name,'trace',row_value->>'trace_id',
    'payloadSha',pipeline_control.pending_digest(row_value));
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(items) x WHERE x->>'video'=video AND x->>'name'=name AND x<>item)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(items) x WHERE x->>'trace'=item->>'trace' AND x<>item)
  THEN RAISE EXCEPTION 'PENDING_SET_AMBIGUOUS' USING ERRCODE='22023'; END IF;
  IF NOT items @> jsonb_build_array(item) THEN items:=items||jsonb_build_array(item); END IF;
 END LOOP;
 RETURN (SELECT jsonb_agg(x ORDER BY x->>'video',x->>'name') FROM jsonb_array_elements(items) x);
END $_$;


--
-- Name: pending_request_read(uuid); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.pending_request_read(request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 WITH operation AS MATERIALIZED (
  SELECT * FROM pipeline_control.hosted_pending_operations o WHERE o.request_id=pending_request_read.request_id
 ), current_rows AS MATERIALIZED (
  SELECT i,pipeline_control.pending_current(i) AS observed
  FROM operation o CROSS JOIN LATERAL jsonb_array_elements(o.items) i
 )
 SELECT jsonb_build_object('requestId',o.request_id,'bindingSha',o.binding_sha,'state',o.state,
   'rows',o.result,'replayAllowed',false,'sourceRevision',o.source_revision,'freshness',o.freshness,
   'currentRows',coalesce((SELECT jsonb_agg(jsonb_build_object('identitySha',pipeline_control.pending_digest(jsonb_build_array(i->>'video',i->>'name')),
      'video',i->>'video')||observed ORDER BY i->>'video',i->>'name') FROM current_rows),'[]'::jsonb),
   'currentSetPresent',NOT EXISTS(SELECT 1 FROM current_rows WHERE observed->>'action'<>'present'),
   'originalRowsStillPresent',o.state='committed' AND NOT EXISTS(
     SELECT 1 FROM jsonb_array_elements(o.result) r WHERE NOT EXISTS(
       SELECT 1 FROM current_rows c WHERE c.observed->>'action'='present' AND c.observed->>'id'=r->>'id')),
   'relatedRequestIds',coalesce((SELECT jsonb_agg(DISTINCT prior.request_id ORDER BY prior.request_id)
     FROM pipeline_control.hosted_pending_operations prior
     WHERE prior.request_id<>o.request_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(prior.items) pi JOIN current_rows r ON pi->>'video'=r.i->>'video')),'[]'::jsonb))
 FROM operation o;
$$;


--
-- Name: publish_upsert_restaurants(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.publish_upsert_restaurants(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_count integer;
    v_item jsonb;
    v_payload jsonb;
    v_expected jsonb;
    v_op text;
    v_id uuid;
    v_inserted integer := 0;
    v_updated integer := 0;
    v_ids uuid[] := ARRAY[]::uuid[];
    v_insert_cols text;
    v_insert_select text;
    v_set text;
    v_expected_id uuid;
    v_expected_trace text;
    v_expected_updated timestamptz;
    v_readback jsonb;
    v_bad_key text;
    -- Publication_Set allowlist for public.restaurants (design.md C6 / D5,
    -- backend/deploy/publication-set.v1.json). No column outside this set may be
    -- written server-side. Any other payload key is rejected fail-closed.
    v_allowed_columns constant text[] := ARRAY[
        -- publishedColumns (29)
        'approved_name', 'origin_name', 'naver_name', 'google_name',
        'trace_id_name_source', 'trace_id', 'phone', 'categories', 'status',
        'source_type', 'channel_name', 'youtube_link', 'youtube_meta',
        'description_map_url', 'evaluation_results', 'reasoning_basis',
        'tzuyang_review', 'origin_address', 'road_address', 'jibun_address',
        'english_address', 'address_elements', 'lat', 'lng',
        'geocoding_success', 'geocoding_false_stage', 'is_missing',
        'is_not_selected', 'recollect_version',
        -- identity / CAS keys admissible in the payload per insert/update logic
        'id', 'updated_at'
    ];
BEGIN
    IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
        RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
    END IF;

    v_count := jsonb_array_length(p_rows);
    IF v_count > 200 THEN
        RAISE EXCEPTION 'batch_upsert_limit' USING ERRCODE = '22023';
    END IF;

    IF v_count = 0 THEN
        RETURN jsonb_build_object(
            'inserted_count', 0,
            'updated_count', 0,
            'readback', '[]'::jsonb
        );
    END IF;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_rows) AS t(value)
    LOOP
        IF jsonb_typeof(v_item) <> 'object' THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        v_op := v_item->>'op';
        v_payload := v_item->'payload';
        v_expected := v_item->'expected';

        IF v_payload IS NULL OR jsonb_typeof(v_payload) <> 'object' THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        -- Server-side Publication_Set column allowlist. A non-admitted column
        -- can never be written: reject the whole batch fail-closed and apply no
        -- row. Diagnostics are not exposed; only the bounded code is raised.
        SELECT payload_key
        INTO v_bad_key
        FROM jsonb_object_keys(v_payload) AS payload_keys(payload_key)
        WHERE NOT (payload_key = ANY (v_allowed_columns))
        LIMIT 1;

        IF v_bad_key IS NOT NULL THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        IF v_op = 'insert' THEN
            IF v_payload->>'id' IS NULL THEN
                RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
            END IF;

            SELECT
                string_agg(format('%I', attribute.attname), ',' ORDER BY attribute.attnum),
                string_agg(format('populated.%I', attribute.attname), ',' ORDER BY attribute.attnum)
            INTO v_insert_cols, v_insert_select
            FROM pg_catalog.pg_attribute AS attribute
            WHERE attribute.attrelid = 'public.restaurants'::regclass
              AND attribute.attnum > 0
              AND NOT attribute.attisdropped
              AND attribute.attname IN (SELECT jsonb_object_keys(v_payload))
              AND attribute.attname = ANY (v_allowed_columns);

            IF v_insert_cols IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            EXECUTE format(
                'INSERT INTO public.restaurants (%s) SELECT %s FROM jsonb_populate_record(null::public.restaurants, $1) AS populated RETURNING id',
                v_insert_cols,
                v_insert_select
            ) INTO STRICT v_id USING v_payload;

            v_inserted := v_inserted + 1;
            v_ids := array_append(v_ids, v_id);

        ELSIF v_op = 'update' THEN
            IF v_expected IS NULL OR jsonb_typeof(v_expected) <> 'object' THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            BEGIN
                v_expected_id := (v_expected->>'id')::uuid;
                v_expected_updated := (v_expected->>'updated_at')::timestamptz;
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END;

            -- A present JSON null is a valid expectation for nullable trace_id.
            -- Missing fields and null identities/timestamps remain invalid.
            IF v_expected_id IS NULL OR v_expected_updated IS NULL
               OR NOT (v_expected ? 'trace_id')
               OR jsonb_typeof(v_expected->'trace_id') NOT IN ('string', 'null') THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            v_expected_trace := v_expected->>'trace_id';

            SELECT string_agg(
                format('%I = populated.%I', attribute.attname, attribute.attname),
                ',' ORDER BY attribute.attnum
            )
            INTO v_set
            FROM pg_catalog.pg_attribute AS attribute
            WHERE attribute.attrelid = 'public.restaurants'::regclass
              AND attribute.attnum > 0
              AND NOT attribute.attisdropped
              AND attribute.attname IN (SELECT jsonb_object_keys(v_payload))
              AND attribute.attname = ANY (v_allowed_columns)
              AND attribute.attname NOT IN ('id', 'updated_at');

            IF v_set IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            EXECUTE format(
                'UPDATE public.restaurants AS target SET %s, updated_at = now() '
                'FROM jsonb_populate_record(null::public.restaurants, $1) AS populated '
                'WHERE target.id = $2 '
                'AND target.trace_id IS NOT DISTINCT FROM $3 '
                'AND target.updated_at IS NOT DISTINCT FROM $4 '
                'RETURNING target.id',
                v_set
            ) INTO v_id USING v_payload, v_expected_id, v_expected_trace, v_expected_updated;

            IF v_id IS NULL THEN
                RAISE EXCEPTION 'compare_and_set_conflict' USING ERRCODE = '40001';
            END IF;

            v_updated := v_updated + 1;
            v_ids := array_append(v_ids, v_id);
        ELSE
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;
    END LOOP;

    SELECT COALESCE(jsonb_agg(to_jsonb(restaurant) ORDER BY ordinality.ord), '[]'::jsonb)
    INTO v_readback
    FROM unnest(v_ids) WITH ORDINALITY AS ordinality(id, ord)
    JOIN public.restaurants AS restaurant ON restaurant.id = ordinality.id;

    RETURN jsonb_build_object(
        'inserted_count', v_inserted,
        'updated_count', v_updated,
        'readback', v_readback
    );
END;
$_$;


--
-- Name: publish_upsert_videos(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.publish_upsert_videos(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_count integer;
    v_item jsonb;
    v_payload jsonb;
    v_expected jsonb;
    v_op text;
    v_id text;
    v_inserted integer := 0;
    v_updated integer := 0;
    v_ids text[] := ARRAY[]::text[];
    v_insert_cols text;
    v_insert_select text;
    v_set text;
    v_expected_id text;
    v_expected_updated timestamptz;
    v_readback jsonb;
    v_bad_key text;
    v_allowed_columns constant text[] := ARRAY[
        'id', 'youtube_link', 'channel_name', 'title', 'published_at',
        'duration', 'category', 'meta_history', 'view_count', 'like_count',
        'comment_count'
    ];
BEGIN
    IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
        RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
    END IF;

    v_count := jsonb_array_length(p_rows);
    IF v_count > 200 THEN
        RAISE EXCEPTION 'batch_upsert_limit' USING ERRCODE = '22023';
    END IF;

    IF v_count = 0 THEN
        RETURN jsonb_build_object(
            'inserted_count', 0,
            'updated_count', 0,
            'readback', '[]'::jsonb
        );
    END IF;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_rows) AS t(value)
    LOOP
        IF jsonb_typeof(v_item) <> 'object' THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        v_op := v_item->>'op';
        v_payload := v_item->'payload';
        v_expected := v_item->'expected';

        IF v_payload IS NULL OR jsonb_typeof(v_payload) <> 'object' THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        SELECT payload_key
        INTO v_bad_key
        FROM jsonb_object_keys(v_payload) AS payload_keys(payload_key)
        WHERE NOT (payload_key = ANY (v_allowed_columns))
        LIMIT 1;

        IF v_bad_key IS NOT NULL THEN
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;

        IF v_op = 'insert' THEN
            IF v_payload->>'id' IS NULL
               OR v_payload->>'youtube_link' IS NULL
               OR v_payload->>'channel_name' IS NULL THEN
                RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
            END IF;

            SELECT
                string_agg(format('%I', attribute.attname), ',' ORDER BY attribute.attnum),
                string_agg(format('populated.%I', attribute.attname), ',' ORDER BY attribute.attnum)
            INTO v_insert_cols, v_insert_select
            FROM pg_catalog.pg_attribute AS attribute
            WHERE attribute.attrelid = 'public.videos'::regclass
              AND attribute.attnum > 0
              AND NOT attribute.attisdropped
              AND attribute.attname IN (SELECT jsonb_object_keys(v_payload))
              AND attribute.attname = ANY (v_allowed_columns);

            IF v_insert_cols IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            EXECUTE format(
                'INSERT INTO public.videos (%s) SELECT %s FROM jsonb_populate_record(null::public.videos, $1) AS populated RETURNING id',
                v_insert_cols,
                v_insert_select
            ) INTO STRICT v_id USING v_payload;

            v_inserted := v_inserted + 1;
            v_ids := array_append(v_ids, v_id);

        ELSIF v_op = 'update' THEN
            IF v_expected IS NULL OR jsonb_typeof(v_expected) <> 'object' THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            BEGIN
                v_expected_id := v_expected->>'id';
                v_expected_updated := (v_expected->>'updated_at')::timestamptz;
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END;

            IF v_expected_id IS NULL OR v_expected_updated IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            SELECT string_agg(
                format('%I = populated.%I', attribute.attname, attribute.attname),
                ',' ORDER BY attribute.attnum
            )
            INTO v_set
            FROM pg_catalog.pg_attribute AS attribute
            WHERE attribute.attrelid = 'public.videos'::regclass
              AND attribute.attnum > 0
              AND NOT attribute.attisdropped
              AND attribute.attname IN (SELECT jsonb_object_keys(v_payload))
              AND attribute.attname = ANY (v_allowed_columns)
              AND attribute.attname <> 'id';

            IF v_set IS NULL THEN
                RAISE EXCEPTION 'conditional_write_failed' USING ERRCODE = '40001';
            END IF;

            EXECUTE format(
                'UPDATE public.videos AS target SET %s, updated_at = now() '
                'FROM jsonb_populate_record(null::public.videos, $1) AS populated '
                'WHERE target.id = $2 '
                'AND target.updated_at IS NOT DISTINCT FROM $3 '
                'RETURNING target.id',
                v_set
            ) INTO v_id USING v_payload, v_expected_id, v_expected_updated;

            IF v_id IS NULL THEN
                RAISE EXCEPTION 'compare_and_set_conflict' USING ERRCODE = '40001';
            END IF;

            v_updated := v_updated + 1;
            v_ids := array_append(v_ids, v_id);
        ELSE
            RAISE EXCEPTION 'batch_upsert_invalid' USING ERRCODE = '22023';
        END IF;
    END LOOP;

    SELECT COALESCE(jsonb_agg(to_jsonb(video) ORDER BY ordinality.ord), '[]'::jsonb)
    INTO v_readback
    FROM unnest(v_ids) WITH ORDINALITY AS ordinality(id, ord)
    JOIN public.videos AS video ON video.id = ordinality.id;

    RETURN jsonb_build_object(
        'inserted_count', v_inserted,
        'updated_count', v_updated,
        'readback', v_readback
    );
END;
$_$;


--
-- Name: restaurant_review_classify(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.restaurant_review_classify(row_data jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE evaluation jsonb := row_data->'evaluation_results'; metric text; value jsonb;
  candidate text := nullif(btrim(coalesce(row_data->>'approved_name',row_data->>'naver_name',row_data->>'google_name',row_data->>'origin_name')),'');
BEGIN
  IF row_data->>'status' IS DISTINCT FROM 'pending' OR nullif(row_data->>'updated_by_admin_id','') IS NOT NULL
    OR nullif(row_data->>'created_by','') IS NOT NULL THEN RETURN 'protected:admin_or_terminal'; END IF;
  IF row_data->'is_missing'='true'::jsonb OR row_data->'is_not_selected'='true'::jsonb THEN RETURN 'hold:not_a_target'; END IF;
  IF nullif(row_data->>'db_error_message','') IS NOT NULL OR coalesce(row_data->'db_error_details','null'::jsonb) NOT IN ('null'::jsonb,'{}'::jsonb)
    THEN RETURN 'hold:database_or_identity_conflict'; END IF;
  IF candidate IS NULL OR nullif(btrim(row_data->>'origin_name'),'') IS NULL
    OR lower(btrim(row_data->>'origin_name'))<>lower(candidate) THEN RETURN 'hold:name_requires_review'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[row_data->>'naver_name',row_data->>'google_name',evaluation#>>'{location_match_TF,matched_name}']) name
    WHERE nullif(btrim(name),'') IS NOT NULL AND lower(btrim(name))<>lower(candidate)) THEN RETURN 'hold:name_requires_review'; END IF;
  IF row_data->'geocoding_success' IS DISTINCT FROM 'true'::jsonb
    OR jsonb_typeof(row_data->'lat') IS DISTINCT FROM 'number' OR jsonb_typeof(row_data->'lng') IS DISTINCT FROM 'number'
    OR (row_data->>'lat')::numeric NOT BETWEEN -90 AND 90 OR (row_data->>'lng')::numeric NOT BETWEEN -180 AND 180
    OR nullif(btrim(row_data->>'jibun_address'),'') IS NULL THEN RETURN 'hold:location_requires_review'; END IF;
  IF evaluation#>'{location_match_TF,eval_value}' IS DISTINCT FROM 'true'::jsonb
    OR evaluation#>>'{location_match_TF,match_status}' IS DISTINCT FROM 'matched'
    OR nullif(evaluation#>>'{location_match_TF,pending_reason}','') IS NOT NULL
    OR nullif(evaluation#>>'{location_match_TF,falseMessage}','') IS NOT NULL
    OR coalesce(jsonb_typeof(evaluation#>'{location_match_TF,evidence_families}'),'null')<>'array'
    THEN RETURN 'hold:location_evidence_incomplete'; END IF;
  IF jsonb_typeof(evaluation#>'{location_match_TF,origin_name}') IS DISTINCT FROM 'string'
    OR lower(btrim(evaluation#>>'{location_match_TF,origin_name}')) IS DISTINCT FROM lower(btrim(row_data->>'origin_name'))
    THEN RETURN 'hold:location_identity_mismatch'; END IF;
  IF (SELECT count(DISTINCT family) FROM jsonb_array_elements_text(evaluation#>'{location_match_TF,evidence_families}') family
      WHERE family IN ('provider_candidate','source_geo','cross_provider','browser_verification','geocode_provider'))<2
    THEN RETURN 'hold:independent_location_evidence_required'; END IF;
  FOREACH metric IN ARRAY ARRAY['visit_authenticity','rb_inference_score','rb_grounding_TF','review_faithfulness_score','category_validity_TF','category_TF'] LOOP
    value:=evaluation#>ARRAY[metric,'eval_value'];
    IF value IS NULL OR value='null'::jsonb OR
      (metric IN ('visit_authenticity','rb_inference_score','review_faithfulness_score') AND jsonb_typeof(value)<>'number') OR
      (metric IN ('rb_grounding_TF','category_validity_TF','category_TF') AND jsonb_typeof(value)<>'boolean')
      THEN RETURN 'recheck:missing_evaluation'; END IF;
    IF metric NOT IN ('category_validity_TF','category_TF') AND
      (jsonb_typeof(evaluation#>ARRAY[metric,'eval_basis']) IS DISTINCT FROM 'string' OR
       coalesce(btrim(evaluation#>>ARRAY[metric,'eval_basis']),'') IN ('','-','근거 내용 없음','평가 근거 없음'))
      THEN RETURN 'recheck:missing_basis'; END IF;
  END LOOP;
  IF evaluation#>'{visit_authenticity,eval_value}'<>'1'::jsonb OR evaluation#>'{rb_inference_score,eval_value}'<>'1'::jsonb
    OR evaluation#>'{review_faithfulness_score,eval_value}'<>'1'::jsonb OR evaluation#>'{rb_grounding_TF,eval_value}'<>'true'::jsonb
    OR evaluation#>'{category_validity_TF,eval_value}'<>'true'::jsonb OR evaluation#>'{category_TF,eval_value}'<>'true'::jsonb
    THEN RETURN 'hold:evaluation_failed'; END IF;
  IF jsonb_typeof(row_data->'categories') IS DISTINCT FROM 'array' THEN RETURN 'hold:source_incomplete'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(row_data->'categories') category
    WHERE jsonb_typeof(category) IS DISTINCT FROM 'string'
      OR NOT ((category#>>'{}')=ANY(ARRAY['치킨','중식','돈까스·회','피자','패스트푸드','찜·탕','족발·보쌈','분식','카페·디저트','한식','고기','양식','아시안','야식','도시락']::text[])))
    THEN RETURN 'hold:source_incomplete'; END IF;
  IF jsonb_typeof(row_data->'categories') IS DISTINCT FROM 'array' OR jsonb_array_length(row_data->'categories')=0
    OR nullif(btrim(row_data->>'tzuyang_review'),'') IS NULL OR nullif(btrim(row_data->>'trace_id'),'') IS NULL
    OR public.extract_youtube_video_id(row_data->>'youtube_link') IS NULL THEN RETURN 'hold:source_incomplete'; END IF;
  RETURN 'approve:all_checks_passed';
END;
$$;


--
-- Name: restaurant_review_decision(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.restaurant_review_decision(row_data jsonb) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE result text := pipeline_control.restaurant_review_classify(row_data);
BEGIN
  IF result NOT LIKE 'protected:%' AND EXISTS (
    SELECT 1 FROM public.restaurants other WHERE other.id::text<>row_data->>'id' AND other.status IS DISTINCT FROM 'deleted' AND (
      (public.extract_youtube_video_id(other.youtube_link)=public.extract_youtube_video_id(row_data->>'youtube_link')
       AND public.normalize_restaurant_identity_name(coalesce(other.origin_name,other.approved_name,other.naver_name,''))=
           public.normalize_restaurant_identity_name(coalesce(row_data->>'origin_name',row_data->>'approved_name','')))
      OR (other.status<>'deleted' AND (
        (nullif(btrim(other.jibun_address),'')=nullif(btrim(row_data->>'jibun_address'),'') AND
         public.normalize_restaurant_identity_name(coalesce(other.approved_name,other.origin_name,other.naver_name,''))=
         public.normalize_restaurant_identity_name(coalesce(row_data->>'approved_name',row_data->>'origin_name','')))
        OR (nullif(regexp_replace(other.phone,'[^0-9]','','g'),'')=nullif(regexp_replace(row_data->>'phone','[^0-9]','','g'),''))
      ))
    )
  ) THEN RETURN 'hold:duplicate_requires_review'; END IF;
  RETURN result;
END;
$$;


--
-- Name: restaurant_review_fingerprint(jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.restaurant_review_fingerprint(row_data jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT md5((row_data - ARRAY['search_count','weekly_search_count','review_count','updated_at'])::text);
$$;


--
-- Name: restaurant_review_gemini_valid(jsonb, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.restaurant_review_gemini_valid(value jsonb, input_sha text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE codes text[]; approval text[]:=ARRAY['visit_supported','identity_supported','review_grounded','category_supported','location_corroborated','source_consistent'];
BEGIN
 IF jsonb_typeof(value) IS DISTINCT FROM 'object' OR value->'schemaVersion' IS DISTINCT FROM '1'::jsonb
   OR value->>'model' IS DISTINCT FROM 'gemini-3.8-flash' OR value->>'modelVersion' IS DISTINCT FROM 'gemini-3.8-flash'
   OR value->>'promptVersion' IS DISTINCT FROM 'restaurant-review-v1'
   OR input_sha IS NULL OR input_sha !~ '^[a-f0-9]{64}$' OR value->>'inputSha256' IS DISTINCT FROM input_sha
   OR coalesce(value->>'promptSha256','') !~ '^[a-f0-9]{64}$'
   OR coalesce(value->>'recommendation','') NOT IN ('approve','hold','recheck')
   OR jsonb_typeof(value->'evidenceCodes') IS DISTINCT FROM 'array'
   OR (SELECT count(*) FROM jsonb_object_keys(value))<>8
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(value) k WHERE k NOT IN
     ('schemaVersion','model','modelVersion','promptVersion','inputSha256','promptSha256','recommendation','evidenceCodes'))
 THEN RETURN false; END IF;
 IF jsonb_array_length(value->'evidenceCodes') NOT BETWEEN 1 AND 12
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(value->'evidenceCodes') code WHERE jsonb_typeof(code)<>'string') THEN RETURN false; END IF;
 SELECT array_agg(code) INTO codes FROM jsonb_array_elements_text(value->'evidenceCodes') code;
 IF cardinality(codes)<>(SELECT count(DISTINCT code) FROM unnest(codes) code)
   OR NOT codes <@ (approval||ARRAY['insufficient_evidence','identity_conflict','location_conflict','review_unfaithful','category_conflict','source_conflict'])
 THEN RETURN false; END IF;
 IF value->>'recommendation'='approve' THEN RETURN codes @> approval AND codes <@ approval; END IF;
 RETURN NOT codes <@ approval;
END; $_$;


--
-- Name: restaurant_review_manual_preview(uuid, text); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.restaurant_review_manual_preview(actor uuid, action text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE policy pipeline_control.restaurant_review_policy; remaining integer; counts jsonb; queued integer; running integer; queue_digest text;
BEGIN
  PERFORM pipeline_control.assert_restaurant_review_operator(actor);
  IF action NOT IN ('run','stop') OR action IS NULL THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_ACTION_INVALID'; END IF;
  SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton;
  IF NOT policy.enabled THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_STALE'; END IF;
  IF action='run' AND (SELECT count(*) FROM (SELECT 1 FROM public.restaurants LIMIT 50001) bounded)>50000
    THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_CAPACITY_EXCEEDED'; END IF;
  SELECT greatest(0,policy.daily_limit-count(*)) INTO remaining FROM pipeline_control.restaurant_review_items
    WHERE restaurant_review_items.decision='approve' AND state='applied'
      AND finished_at>=date_trunc('day',now() AT TIME ZONE 'Asia/Seoul') AT TIME ZONE 'Asia/Seoul';
  SELECT count(*) FILTER(WHERE state='queued'),count(*) FILTER(WHERE state='running'),
    md5(coalesce(string_agg(id::text||':'||state,',' ORDER BY id),''))
    INTO queued,running,queue_digest FROM pipeline_control.restaurant_review_items WHERE state IN ('queued','running');
  counts:='{}'::jsonb;
  IF action='run' THEN
  SELECT coalesce(jsonb_object_agg(decision,total),'{}'::jsonb) INTO counts FROM (
    SELECT decision,count(*) total FROM (
      SELECT split_part(pipeline_control.restaurant_review_decision(to_jsonb(candidate)),':',1) decision
      FROM public.restaurants candidate WHERE candidate.status='pending' AND (
        NOT EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items prior WHERE prior.restaurant_id=candidate.id
          AND (prior.fingerprint=pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate)) OR prior.applied_fingerprint=pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate))))
        OR EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items prior JOIN pipeline_control.restaurant_review_runs r ON r.id=prior.run_id
          WHERE prior.restaurant_id=candidate.id AND prior.applied_fingerprint=pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate))
            AND prior.state='succeeded' AND prior.reason='daily_limit' AND r.policy_version=policy.version))
        AND (remaining>0 OR pipeline_control.restaurant_review_decision(to_jsonb(candidate)) NOT LIKE 'approve:%')
      ORDER BY candidate.created_at,candidate.id LIMIT policy.batch_size
    ) bounded GROUP BY decision
  ) grouped;
  END IF;
  IF counts ? 'approve' THEN counts:=jsonb_set(counts,'{approve}',to_jsonb(least((counts->>'approve')::integer,remaining))); END IF;
  RETURN jsonb_build_object('action',action,'version',policy.version::text,'counts',counts,
    'batchSize',policy.batch_size,'dailyLimit',policy.daily_limit,'remainingApprovals',remaining,
    'queue',jsonb_build_object('queued',queued,'running',running),
    'previewHash',md5(actor::text||':'||action||':'||policy.version::text||':'||public.admin_evaluation_revision()
      ||':'||coalesce(policy.last_run_at::text,'')||':'||remaining::text||':'||counts::text||':'||queue_digest));
END;
$$;


--
-- Name: submit_restaurant_edit_request(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.submit_restaurant_edit_request(p_user_id uuid, p_client_request_key text, p_target_restaurant_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $_$
DECLARE
  v_id uuid;
  v_kind text;
  v_name text;
  v_address text;
  v_phone text;
  v_normal_phone text;
  v_public_phone text;
  v_phone_requires_public_match boolean := false;
  v_categories text[];
  v_items jsonb;
  v_item jsonb;
  v_count integer;
  v_request_sha text;
  v_expected_sha text;
  v_persisted_sha text;
  v_binding record;
  v_parent public.restaurant_submissions%ROWTYPE;
  v_note text;
BEGIN
  IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user <> 'service_role' THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_UNAUTHORIZED');
  END IF;
  IF p_user_id IS NULL OR p_target_restaurant_id IS NULL
     OR p_client_request_key IS NULL OR p_client_request_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     OR p_payload IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
     OR octet_length(p_payload::text)>65536 THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
  END IF;
  IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_payload) k)
       IS DISTINCT FROM ARRAY['address','category','name','phone','requestKind','youtube_reviews']::text[]
     OR jsonb_typeof(p_payload->'requestKind') IS DISTINCT FROM 'string'
     OR p_payload->>'requestKind' NOT IN ('edit','closure')
     OR jsonb_typeof(p_payload->'name') IS DISTINCT FROM 'string' OR length(p_payload->>'name')>160
     OR jsonb_typeof(p_payload->'address') IS DISTINCT FROM 'string' OR length(p_payload->>'address')>500
     OR jsonb_typeof(p_payload->'phone') IS DISTINCT FROM 'string' OR length(p_payload->>'phone')>40
     OR jsonb_typeof(p_payload->'category') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_payload->'youtube_reviews') IS DISTINCT FROM 'array' THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
  END IF;
  IF jsonb_array_length(p_payload->'category')>10 OR jsonb_array_length(p_payload->'youtube_reviews') NOT BETWEEN 1 AND 100
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'category') c
       WHERE jsonb_typeof(c) IS DISTINCT FROM 'string' OR length(c#>>'{}')>50 OR btrim(c#>>'{}')='') THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
  END IF;
  v_kind:=p_payload->>'requestKind'; v_name:=btrim(p_payload->>'name');
  v_address:=btrim(p_payload->>'address'); v_phone:=nullif(btrim(p_payload->>'phone'),'');
  SELECT coalesce(array_agg(btrim(c) ORDER BY btrim(c) COLLATE "C"),ARRAY[]::text[]) INTO v_categories
    FROM jsonb_array_elements_text(p_payload->'category') c;
  IF cardinality(v_categories)<>(SELECT count(DISTINCT c) FROM unnest(v_categories) c)
     OR (v_kind='edit' AND (v_name='' OR v_address='' OR cardinality(v_categories)=0)) THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
  END IF;
  -- Syntax is bounded independently of mutable business provenance. Existing
  -- confirmed keys reconcile below without a fresh public-phone requirement.
  IF v_phone IS NOT NULL THEN
    IF octet_length(v_phone)<>length(v_phone) OR v_phone !~ '^[+]?[0-9().[:space:]-]+$' THEN
      RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
    END IF;
    v_normal_phone:=regexp_replace(v_phone,'[^0-9+]','','g');
    IF v_normal_phone ~ '^(02[0-9]{7,8}|0[3-6][0-9]{7,8}|1[5-8][0-9]{6,7})$' THEN
      NULL; -- Preserve the existing Korean business-number contract.
    ELSIF v_normal_phone ~ '^[+][1-9][0-9]{6,14}$'
      AND (v_normal_phone !~ '^[+]82' OR v_normal_phone ~ '^[+]82(2[0-9]{7,8}|[3-6][0-9]{7,8})$') THEN
      v_phone_requires_public_match:=true;
    ELSE
      RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
    END IF;
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_payload->'youtube_reviews') LOOP
    IF jsonb_typeof(v_item) IS DISTINCT FROM 'object' THEN
      RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
    END IF;
    IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(v_item) k)
         IS DISTINCT FROM ARRAY['restaurant_id','tzuyang_review','youtube_link']::text[]
       OR jsonb_typeof(v_item->'youtube_link') IS DISTINCT FROM 'string'
       OR length(v_item->>'youtube_link')>2048 OR btrim(v_item->>'youtube_link') !~ '^https?://'
       OR jsonb_typeof(v_item->'tzuyang_review') IS DISTINCT FROM 'string' OR length(v_item->>'tzuyang_review')>4000
       OR jsonb_typeof(v_item->'restaurant_id') IS DISTINCT FROM 'string'
       OR v_item->>'restaurant_id' !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN
      RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
    END IF;
  END LOOP;
  SELECT jsonb_agg(jsonb_build_object('youtube_link',btrim(i->>'youtube_link'),
      'tzuyang_review',nullif(btrim(i->>'tzuyang_review'),''),'restaurant_id',(i->>'restaurant_id')::uuid)
      ORDER BY (i->>'restaurant_id')::uuid,btrim(i->>'youtube_link') COLLATE "C",nullif(btrim(i->>'tzuyang_review'),'') COLLATE "C")
    INTO v_items FROM jsonb_array_elements(p_payload->'youtube_reviews') i;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) i WHERE (i->>'restaurant_id')::uuid=p_target_restaurant_id) THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
  END IF;
  v_count:=jsonb_array_length(v_items);
  v_note:=CASE WHEN v_kind='closure' THEN '폐업 제보: 사용자가 이 맛집이 폐업했거나 더 이상 영업하지 않는다고 알려왔습니다. 관리자 검토 후 상태/노출 여부를 결정하세요.' ELSE NULL END;
  v_request_sha:=encode(sha256(convert_to(jsonb_build_object('target',p_target_restaurant_id,'requestKind',v_kind,
    'name',v_name,'address',v_address,'phone',v_phone,'category',v_categories,'items',v_items)::text,'UTF8')),'hex');

  -- Serialize existing-key reconciliation on the ORIGINAL parent. Never adopt
  -- an old incomplete REST parent or repair/re-dispatch a mismatched request.
  SELECT * INTO v_parent FROM public.restaurant_submissions s WHERE s.user_id=p_user_id
    AND s.submission_type='edit' AND s.client_submission_key=p_client_request_key FOR UPDATE;
  IF NOT FOUND THEN
    -- Only a fresh request must prove the international number is already this
    -- target's approved public business phone. SHARE keeps that source stable
    -- through the atomic parent/items/binding write. Never change display text.
    IF v_phone_requires_public_match THEN
      SELECT r.phone INTO v_public_phone FROM public.restaurants r
        WHERE r.id=p_target_restaurant_id AND r.status='approved' FOR SHARE;
      IF v_public_phone IS NULL
         OR regexp_replace(v_public_phone,'[^0-9+]','','g') IS DISTINCT FROM v_normal_phone THEN
        RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
      END IF;
    END IF;
    IF v_kind='closure' AND v_name='' THEN
      SELECT coalesce(nullif(btrim(r.approved_name),''),nullif(btrim(r.naver_name),''),
        nullif(btrim(r.origin_name),''),nullif(btrim(r.google_name),''),nullif(btrim(r.channel_name),''))
        INTO v_name FROM public.restaurants r WHERE r.id=p_target_restaurant_id;
    END IF;
    -- Existing parent CHECKs are intentionally preserved (name<=100/categories<=5).
    IF v_name IS NULL OR length(v_name) NOT BETWEEN 1 AND 100 OR cardinality(v_categories)>5 THEN
      RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
    END IF;
    INSERT INTO public.restaurant_submissions(user_id,submission_type,client_submission_key,status,
      restaurant_name,restaurant_address,restaurant_phone,restaurant_categories,admin_notes)
    VALUES(p_user_id,'edit',p_client_request_key,'pending',v_name,v_address,v_phone,v_categories,v_note)
    ON CONFLICT(user_id,submission_type,client_submission_key) WHERE client_submission_key IS NOT NULL DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.restaurant_submission_items(submission_id,youtube_link,tzuyang_review,target_restaurant_id,item_status)
        SELECT v_id,i->>'youtube_link',i->>'tzuyang_review',(i->>'restaurant_id')::uuid,'pending'
        FROM jsonb_array_elements(v_items) i;
      v_expected_sha:=encode(sha256(convert_to(jsonb_build_object('name',v_name,'address',v_address,
        'phone',v_phone,'category',v_categories,'note',v_note,'items',v_items)::text,'UTF8')),'hex');
      -- INSERT completion/RETURNING alone is not a stored-set proof: a trigger
      -- may silently suppress or mutate rows. Any mismatch must RAISE so this
      -- block rolls back every write rather than return a partially saved set.
      SELECT * INTO v_parent FROM public.restaurant_submissions s WHERE s.id=v_id
        AND s.user_id=p_user_id AND s.submission_type='edit' AND s.client_submission_key=p_client_request_key FOR UPDATE;
      IF v_parent.id IS NULL OR v_parent.status<>'pending'
         OR (SELECT count(*) FROM public.restaurant_submission_items i WHERE i.submission_id=v_id)<>v_count
         OR EXISTS(SELECT 1 FROM public.restaurant_submission_items i WHERE i.submission_id=v_id AND i.item_status<>'pending') THEN
        RAISE EXCEPTION 'edit_request_persisted_set_mismatch';
      END IF;
      PERFORM 1 FROM public.restaurant_submission_items i WHERE i.submission_id=v_id FOR UPDATE;
      SELECT encode(sha256(convert_to(jsonb_build_object('name',v_parent.restaurant_name,'address',v_parent.restaurant_address,
        'phone',v_parent.restaurant_phone,'category',v_parent.restaurant_categories,'note',v_parent.admin_notes,
        'items',(SELECT jsonb_agg(jsonb_build_object('youtube_link',i.youtube_link,'tzuyang_review',i.tzuyang_review,
          'restaurant_id',i.target_restaurant_id) ORDER BY i.target_restaurant_id,i.youtube_link COLLATE "C",i.tzuyang_review COLLATE "C")
          FROM public.restaurant_submission_items i WHERE i.submission_id=v_id))::text,'UTF8')),'hex') INTO v_persisted_sha;
      IF v_persisted_sha IS DISTINCT FROM v_expected_sha THEN
        RAISE EXCEPTION 'edit_request_persisted_set_mismatch';
      END IF;
      INSERT INTO pipeline_control.restaurant_edit_request_bindings VALUES(v_id,v_request_sha,v_persisted_sha);
      SELECT * INTO v_binding FROM pipeline_control.restaurant_edit_request_bindings WHERE submission_id=v_id;
      IF v_binding.submission_id IS NULL OR v_binding.request_sha256 IS DISTINCT FROM v_request_sha
         OR v_binding.persisted_sha256 IS DISTINCT FROM v_persisted_sha THEN
        RAISE EXCEPTION 'edit_request_persisted_binding_mismatch';
      END IF;
      RETURN jsonb_build_object('ok',true,'code','EDIT_SUBMISSION_SAVED','id',v_id,'status','pending','itemCount',v_count);
    END IF;
    SELECT * INTO v_parent FROM public.restaurant_submissions s WHERE s.user_id=p_user_id
      AND s.submission_type='edit' AND s.client_submission_key=p_client_request_key FOR UPDATE;
  END IF;
  IF v_parent.id IS NULL OR v_parent.status<>'pending' THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_CONFLICT');
  END IF;
  PERFORM 1 FROM public.restaurant_submission_items i WHERE i.submission_id=v_parent.id FOR UPDATE;
  IF (SELECT count(*) FROM public.restaurant_submission_items i WHERE i.submission_id=v_parent.id)<>v_count
     OR EXISTS(SELECT 1 FROM public.restaurant_submission_items i WHERE i.submission_id=v_parent.id AND i.item_status<>'pending') THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_CONFLICT');
  END IF;
  SELECT * INTO v_binding FROM pipeline_control.restaurant_edit_request_bindings WHERE submission_id=v_parent.id;
  SELECT encode(sha256(convert_to(jsonb_build_object('name',v_parent.restaurant_name,'address',v_parent.restaurant_address,
    'phone',v_parent.restaurant_phone,'category',v_parent.restaurant_categories,'note',v_parent.admin_notes,
    'items',(SELECT jsonb_agg(jsonb_build_object('youtube_link',i.youtube_link,'tzuyang_review',i.tzuyang_review,
       'restaurant_id',i.target_restaurant_id) ORDER BY i.target_restaurant_id,i.youtube_link COLLATE "C",i.tzuyang_review COLLATE "C")
      FROM public.restaurant_submission_items i WHERE i.submission_id=v_parent.id))::text,'UTF8')),'hex') INTO v_persisted_sha;
  IF v_binding.submission_id IS NULL OR v_binding.request_sha256 IS DISTINCT FROM v_request_sha
     OR v_binding.persisted_sha256 IS DISTINCT FROM v_persisted_sha THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_CONFLICT');
  END IF;
  RETURN jsonb_build_object('ok',true,'code','EDIT_SUBMISSION_SAVED','id',v_parent.id,'status','pending','itemCount',v_count);
EXCEPTION
  -- This block covers ALL three writes. Any item/binding failure rolls back the
  -- parent and every prior item before the fixed failure JSON is returned.
  WHEN check_violation OR foreign_key_violation OR not_null_violation OR invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_INVALID');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'code','EDIT_SUBMISSION_FAILED');
END $_$;


--
-- Name: update_admin_eval_read_index(); Type: FUNCTION; Schema: pipeline_control; Owner: -
--

CREATE FUNCTION pipeline_control.update_admin_eval_read_index() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE d jsonb;
BEGIN
 IF TG_OP='DELETE' THEN DELETE FROM pipeline_control.admin_evaluation_read_index WHERE id=OLD.id;RETURN NULL; END IF;
 IF TG_OP='UPDATE' AND OLD.id IS DISTINCT FROM NEW.id THEN DELETE FROM pipeline_control.admin_evaluation_read_index WHERE id=OLD.id; END IF;
 d:=pipeline_control.admin_eval_descriptor(to_jsonb(NEW)||jsonb_build_object('name',NEW.approved_name));
 INSERT INTO pipeline_control.admin_evaluation_read_index(id,descriptor,latest,created,video)
 VALUES(NEW.id,d,(d->>'latest')::numeric,(d->>'created')::numeric,d->>'video')
 ON CONFLICT(id) DO UPDATE SET descriptor=EXCLUDED.descriptor,latest=EXCLUDED.latest,created=EXCLUDED.created,video=EXCLUDED.video;
 RETURN NULL;
END;
$$;


--
-- Name: active_hold_exists(text, text, timestamp with time zone); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.active_hold_exists(p_subject_ref_hash text, p_data_class text, p_as_of timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_subject_ref_hash is not null and exists (
    select 1
    from privacy_retention.privacy_legal_holds hold
    where hold.subject_ref_hash = p_subject_ref_hash
      and hold.data_class = p_data_class
      and hold.status = 'active'
      and (hold.expires_at is null or hold.expires_at > p_as_of)
  );
$$;


--
-- Name: append_privacy_audit_event_internal(text, uuid, uuid, uuid, uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.append_privacy_audit_event_internal(p_event_type text, p_actor_user_id uuid, p_subject_user_id uuid, p_operation_id uuid, p_correlation_id uuid, p_status text, p_reason_code text, p_count_summary jsonb, p_request_metadata jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_audit_id uuid;
  v_occurred_at timestamptz := pg_catalog.clock_timestamp();
  v_class_code text;
  v_retention_until timestamptz;
BEGIN
  IF p_event_type IS NULL
     OR p_operation_id IS NULL
     OR p_correlation_id IS NULL
     OR p_status IS NULL
     OR p_status NOT IN ('previewed', 'confirmed', 'applied', 'partial', 'failed', 'readback_passed', 'readback_failed', 'held')
     OR p_reason_code IS NULL
     OR p_reason_code !~ '^[A-Z][A-Z0-9_]{0,63}$'
     OR NOT public.privacy_audit_count_summary_is_safe(COALESCE(p_count_summary, '{}'::jsonb))
     OR NOT public.privacy_audit_metadata_is_safe(COALESCE(p_request_metadata, '{}'::jsonb)) THEN
    RAISE EXCEPTION 'privacy_audit_request_invalid' USING ERRCODE = '22023';
  END IF;

  v_class_code := CASE
    WHEN p_event_type IN (
      'onboarding_challenge_created',
      'onboarding_confirmed',
      'consent_recorded',
      'guardian_verification_recorded',
      'policy_published',
      'onboarding_challenge_transition',
      'onboarding_compensation_held'
    ) THEN 'privacy_identity_audit'
    WHEN p_event_type = 'account_deletion' THEN 'privacy_account_deletion_audit'
    ELSE NULL
  END;
  IF v_class_code IS NULL THEN
    RAISE EXCEPTION 'privacy_audit_event_type_not_supported' USING ERRCODE = '22023';
  END IF;

  v_retention_until := public.privacy_resolve_audit_retention_until(v_class_code, v_occurred_at);

  INSERT INTO privacy_retention.privacy_audit_events (
    event_type,
    actor_user_id,
    subject_ref_hash,
    operation_id,
    correlation_id,
    status,
    reason_code,
    count_summary,
    request_metadata,
    occurred_at,
    retention_until
  ) VALUES (
    p_event_type,
    p_actor_user_id,
    CASE
      WHEN p_subject_user_id IS NULL THEN NULL
      ELSE pg_catalog.encode(
        extensions.digest('privacy-subject:v1:' || p_subject_user_id::text, 'sha256'),
        'hex'
      )
    END,
    p_operation_id,
    p_correlation_id,
    p_status,
    p_reason_code,
    COALESCE(p_count_summary, '{}'::jsonb),
    COALESCE(p_request_metadata, '{}'::jsonb),
    v_occurred_at,
    v_retention_until
  )
  RETURNING id INTO v_audit_id;

  RETURN v_audit_id;
END;
$_$;


--
-- Name: assert_g014_catalog_contract(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_catalog_contract() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_expected record;
  v_procedure oid;
  v_search_path text;
  v_is_definer boolean;
  v_auth_users_oid oid;
  v_auth_users_count integer;
  v_auth_dependency_missing text;
  v_auth_dependency_unexpected text;
BEGIN
  PERFORM privacy_retention.assert_g014_workflow_owner_contract();
  PERFORM privacy_retention.assert_g014_public_rpc_allowlist();
  PERFORM privacy_retention.assert_g014_definer_contract();

  IF pg_catalog.has_schema_privilege('anon', 'public', 'CREATE')
     OR pg_catalog.has_schema_privilege('authenticated', 'public', 'CREATE') THEN
    RAISE EXCEPTION 'G014 browser/public CREATE privilege remains';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (VALUES ('anon'::name), ('authenticated'::name), ('service_role'::name))
      AS role_matrix(grantee)
    WHERE pg_catalog.has_schema_privilege(role_matrix.grantee, 'privacy_retention', 'USAGE')
       OR pg_catalog.has_schema_privilege(role_matrix.grantee, 'privacy_retention', 'CREATE')
  ) THEN
    RAISE EXCEPTION 'G014 private schema privilege remains';
  END IF;

  PERFORM privacy_retention.assert_g014_catalog_manifest();
  PERFORM privacy_retention.assert_g014_catalog_security_baseline();

  IF EXISTS (
    SELECT 1
    FROM public.account_deletion_requests AS request_row
    WHERE request_row.status = 'applied'
      AND (
        request_row.db_readback_passed IS DISTINCT FROM true
        OR request_row.session_readback_passed IS DISTINCT FROM true
        OR request_row.storage_readback_passed IS DISTINCT FROM true
        OR request_row.auth_readback_passed IS DISTINCT FROM true
        OR request_row.auth_receipt_ref IS NULL
        OR request_row.auth_receipt_ref !~ '^auth:[0-9a-f]{64}$'
        OR request_row.applied_at IS NULL
      )
  ) THEN
    RAISE EXCEPTION 'G014 applied account deletion receipt/readback invariant drifted';
  END IF;
  -- Freeze the final G014-facing RPC matrix explicitly. The persisted allowlist
  -- still covers pre-G014 application RPCs; this subset prevents a later
  -- migration from retaining an obsolete privacy, notification, deletion, or
  -- retention overload under the same public name.
  IF EXISTS (
    WITH expected(source_signature, grantee) AS (
      VALUES
        ('public.update_current_profile_nickname(text)', 'authenticated'::name),
        ('public.compare_and_set_current_profile_avatar(text,uuid)', 'authenticated'::name),
        ('public.read_signup_profile_state(uuid,text)', 'service_role'::name),
        ('public.get_current_privacy_policy_version()', 'authenticated'::name),
        ('public.get_current_privacy_policy_version()', 'service_role'::name),
        ('public.create_privacy_onboarding_challenge(text,uuid,text,jsonb,text,timestamptz)', 'service_role'::name),
        (
          CASE
            WHEN pg_catalog.to_regprocedure(
              'public.confirm_privacy_onboarding(uuid,text,uuid,text,uuid,text)'
            ) IS NOT NULL
              THEN 'public.confirm_privacy_onboarding(uuid,text,uuid,text,uuid,text)'
            ELSE 'public.confirm_privacy_onboarding(uuid,text,uuid,text,uuid)'
          END,
          'service_role'::name
        ),
        ('public.submit_privacy_consent(text,text,text,uuid,text,text,uuid,text,uuid)', 'authenticated'::name),
        ('public.record_privacy_guardian_verification(uuid,uuid,text,text,text,timestamptz,timestamptz)', 'service_role'::name),
        ('public.read_privacy_guardian_status(uuid)', 'service_role'::name),
        ('public.append_privacy_audit_event(text,uuid,uuid,uuid,uuid,text,text,jsonb,jsonb)', 'service_role'::name),
        ('public.publish_privacy_policy_version(text,text,text,timestamptz,uuid,text,text)', 'service_role'::name),
        ('public.transition_privacy_onboarding_challenge(uuid,text,text,uuid,text)', 'service_role'::name),
        ('public.submit_guardian_privacy_consent(text,text,text,uuid,text,uuid,text,uuid)', 'service_role'::name),
        ('public.hold_privacy_onboarding_compensation(uuid,uuid,text,text)', 'service_role'::name),
        ('public.get_current_privacy_eligibility()', 'authenticated'::name),
        ('public.get_privacy_eligibility_for_user(uuid)', 'service_role'::name),
        ('public.create_user_notification(uuid,text,text,text,jsonb)', 'authenticated'::name),
        ('public.mark_notification_read(uuid)', 'authenticated'::name),
        ('public.mark_all_notifications_read()', 'authenticated'::name),
        ('public.delete_notification(uuid)', 'authenticated'::name),
        ('public.create_admin_transactional_notification(uuid,uuid,text,text,text,jsonb)', 'service_role'::name),
        ('public.create_review_like_notification(uuid,uuid,uuid)', 'service_role'::name),
        ('public.evaluate_notification_marketing_permission(uuid,text,timestamptz,text)', 'service_role'::name),
        ('public.marketing_campaign_receipt(uuid)', 'service_role'::name),
        ('public.preview_marketing_campaign(uuid,text,uuid[],text,text,jsonb,text,timestamptz)', 'service_role'::name),
        ('public.prepare_marketing_campaign_batch(uuid,uuid,text,text,integer,text)', 'service_role'::name),
        ('public.claim_marketing_campaign_dispatch(uuid,uuid,uuid,text,text,text)', 'service_role'::name),
        ('public.fail_marketing_campaign_batch(uuid,uuid,uuid,text,text)', 'service_role'::name),
        ('public.fail_marketing_campaign_provider_attempt(uuid,uuid,uuid,text,uuid,uuid,text,text,text,text)', 'service_role'::name),
        ('public.finalize_marketing_campaign_batch(uuid,uuid,uuid,text,uuid,uuid,text,text,text,uuid[],text)', 'service_role'::name),
        ('public.preview_account_deletion(uuid,uuid,timestamptz)', 'service_role'::name),
        ('public.begin_account_deletion_apply(uuid,uuid,uuid,text,text,text,timestamptz,text)', 'service_role'::name),
        ('public.apply_account_deletion_database_cleanup(uuid,uuid,uuid,text,text,text)', 'service_role'::name),
        ('public.claim_account_deletion_external_job(uuid,uuid,uuid,text,text,text,text,uuid)', 'service_role'::name),
        ('public.prepare_account_deletion_external_egress(uuid,uuid,uuid,text,text,text,text,uuid)', 'service_role'::name),
        ('public.read_account_deletion_external_job(uuid,uuid,uuid,text,text,text,text,uuid)', 'service_role'::name),
        ('public.run_account_deletion_session_family_cleanup(uuid,uuid,uuid,text,text,text,uuid)', 'service_role'::name),
        ('public.get_account_deletion_storage_work(uuid,uuid,uuid,text,text,text,uuid)', 'service_role'::name),
        ('public.record_account_deletion_external_provider_proof(uuid,uuid,uuid,text,text,text,text,uuid,text,text,text,text)', 'service_role'::name),
        ('public.reconcile_account_deletion_storage_job(uuid,uuid,uuid,text,text,text,uuid)', 'service_role'::name),
        ('public.reconcile_account_deletion_auth_job(uuid,uuid,uuid,text,text,text,uuid)', 'service_role'::name),
        ('public.claim_next_account_deletion_external_job()', 'service_role'::name),
        ('public.read_current_account_deletion_status(uuid,text,text)', 'authenticated'::name),
        ('public.fail_account_deletion(uuid,uuid,uuid,text,text,text,text)', 'service_role'::name),
        ('public.preview_privacy_retention_run(text,timestamptz,integer,integer)', 'service_role'::name),
        ('public.confirm_privacy_retention_run(uuid,text,text,text)', 'service_role'::name),
        ('public.apply_privacy_retention_run(uuid,text,text,integer)', 'service_role'::name),
        ('public.claim_privacy_retention_storage_items(uuid,text,text,integer)', 'service_role'::name),
        ('public.resolve_privacy_retention_provider_effect(uuid,text,text,uuid,uuid,text,text,text,text,text,text)', 'service_role'::name),
        ('public.get_privacy_retention_provider_reconciliation_work(uuid,text,text,text,integer)', 'service_role'::name),
        ('public.record_privacy_retention_storage_provider_receipts(uuid,text,text,jsonb)', 'service_role'::name),
        ('public.fail_privacy_retention_storage_claims(uuid,text,text,uuid[],text)', 'service_role'::name),
        ('public.finalize_privacy_retention_run(uuid,text,text)', 'service_role'::name)
    )
    SELECT 1
    FROM expected
    LEFT JOIN privacy_retention.g014_public_rpc_allowlist AS allowed
      ON allowed.source_signature = expected.source_signature
     AND allowed.grantee = expected.grantee
    WHERE allowed.source_signature IS NULL
  ) THEN
    RAISE EXCEPTION 'G014 final public RPC allowlist is missing an exact required identity';
  END IF;
  -- Every G014 implementation/helper has the same trusted owner and an empty
  -- lookup path. SECURITY INVOKER trigger helpers are intentionally permitted,
  -- but may not regain an ambient search_path.
  FOR v_expected IN
    SELECT procedure.oid, namespace.nspname, procedure.proname
    FROM pg_catalog.pg_proc AS procedure
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
    WHERE namespace.nspname IN ('public', 'privacy_retention')
      AND procedure.proname LIKE 'g014\_%' ESCAPE '\'
  LOOP
    SELECT setting.value INTO v_search_path
    FROM pg_catalog.unnest((
      SELECT procedure.proconfig FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = v_expected.oid
    )) AS setting(value)
    WHERE setting.value LIKE 'search_path=%';
    IF pg_catalog.pg_get_userbyid((
         SELECT procedure.proowner FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = v_expected.oid
       )) IS DISTINCT FROM (CASE
         WHEN v_expected.oid = ANY (ARRAY[
           pg_catalog.to_regprocedure('privacy_retention.g014_account_deletion_reconcile_expired_attempt(uuid,text,uuid)'),
           pg_catalog.to_regprocedure('privacy_retention.g014_retention_append_audit(privacy_retention.privacy_retention_runs,text,text)'),
           pg_catalog.to_regprocedure('privacy_retention.g014_account_deletion_apply_adapter(text,uuid,uuid)')
         ]) THEN 'privacy_auth_bridge'
         ELSE 'privacy_workflow_owner'
       END)
       OR (v_search_path IS DISTINCT FROM 'search_path=' AND v_search_path IS DISTINCT FROM 'search_path=""') THEN
      RAISE EXCEPTION 'G014 helper owner/search_path mismatch: %.%',
        v_expected.nspname, v_expected.proname;
    END IF;
  END LOOP;

  -- All exposed public overloads are exact allowlist identities. This catches an
  -- added overload even when its ACL is otherwise empty; callers must never gain
  -- a silent alias due to PostgREST overload resolution.
  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS procedure
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
    WHERE namespace.nspname = 'public'
      AND EXISTS (
        SELECT 1
        FROM privacy_retention.g014_public_rpc_allowlist AS allowed
        WHERE allowed.function_schema = namespace.nspname
          AND allowed.function_name = procedure.proname
      )
      AND NOT EXISTS (
        SELECT 1
        FROM privacy_retention.g014_public_rpc_allowlist AS allowed
        WHERE allowed.function_schema = namespace.nspname
          AND allowed.function_name = procedure.proname
          AND allowed.identity_arguments = procedure.proargtypes::text
      )
  ) THEN
    RAISE EXCEPTION 'G014 public RPC has an unexpected overload';
  END IF;

  FOR v_expected IN
    SELECT allowed.source_signature, allowed.grantee
    FROM privacy_retention.g014_public_rpc_allowlist AS allowed
    ORDER BY allowed.source_signature, allowed.grantee
  LOOP
    v_procedure := pg_catalog.to_regprocedure(v_expected.source_signature);
    IF v_procedure IS NULL THEN
      RAISE EXCEPTION 'G014 allowlisted public RPC identity is missing: %', v_expected.source_signature;
    END IF;
    SELECT procedure.prosecdef
    INTO v_is_definer
    FROM pg_catalog.pg_proc AS procedure
    WHERE procedure.oid = v_procedure;
    IF v_expected.source_signature IN (
      'public.read_public_profile_summaries(uuid[])',
      'public.read_public_profile_leaderboard(text,integer)',
      'public.read_public_profile_leaderboard_page(text,integer,numeric,uuid)',
      'public.update_current_profile_nickname(text)',
      'public.compare_and_set_current_profile_avatar(text,uuid)',
      'public.read_signup_profile_state(uuid,text)'
    ) AND NOT v_is_definer THEN
      RAISE EXCEPTION 'G014 profile boundary became SECURITY INVOKER: %',
        v_expected.source_signature;
    END IF;
    IF v_expected.source_signature IN (
      'public.extract_youtube_video_id(text)',
      'public.normalize_restaurant_identity_name(text)',
      'public.admin_evaluation_revision()',
      'public.admin_evaluation_catalog_snapshot()',
      'public.storyboard_production_error_allowed(text)',
      'public.storyboard_production_final_status(jsonb,jsonb)',
      'public.storyboard_production_project_json(public.admin_storyboard_production_projects)',
      'public.storyboard_production_job_json(public.admin_storyboard_production_jobs)',
      'public.storyboard_production_snapshot(uuid,uuid)',
      'public.storyboard_production_auth_worker(text)',
      'public.storyboard_production_model_available(jsonb,text,text)',
      'public.storyboard_production_admin(uuid,text,uuid,integer,jsonb)',
      'public.storyboard_production_worker(uuid,text,uuid,uuid,jsonb)',
      'public.record_app_web_vitals(text,text,text,text,smallint)',
      'public.record_app_web_vitals_bounded(text,text,text,text,smallint)',
      'public.restaurant_review_automation_manual(uuid,text,text,text,uuid)',
      'public.admin_evaluation_page(jsonb,integer,uuid,text)',
      'public.admin_evaluation_warning_groups(uuid[],text)',
      'public.admin_record_action(uuid,text,uuid,text,uuid[],jsonb,text)',
      'public.admin_evaluation_raw_warning_groups(uuid[],text,jsonb,integer)',
      'public.restaurant_review_automation_status()',
      'public.restaurant_review_automation_preview(uuid,integer,integer)',
      'public.restaurant_review_automation_configure(uuid,text,text,text,integer,integer)',
      'public.restaurant_review_automation_tick(uuid)',
      'public.restaurant_review_automation_worker(text,uuid,uuid,jsonb)',
      'public.resolve_restaurant_identity_name(text,text,text,text)'
    ) THEN
      IF v_is_definer OR NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_proc AS p
        WHERE p.oid = v_procedure
          AND pg_catalog.pg_get_userbyid(p.proowner) = 'postgres'
          AND p.proconfig IS NOT DISTINCT FROM CASE
            WHEN v_expected.source_signature IN (
              'public.extract_youtube_video_id(text)',
              'public.normalize_restaurant_identity_name(text)',
              'public.resolve_restaurant_identity_name(text,text,text,text)'
            ) THEN ARRAY['search_path=pg_catalog, public, extensions']::text[]
            WHEN v_expected.source_signature IN (
              'public.restaurant_review_automation_manual(uuid,text,text,text,uuid)',
              'public.restaurant_review_automation_tick(uuid)',
              'public.restaurant_review_automation_worker(text,uuid,uuid,jsonb)'
            ) THEN ARRAY['search_path=""','lock_timeout=2s']::text[]
            ELSE ARRAY['search_path=""']::text[]
          END
          AND pg_catalog.has_function_privilege('service_role', p.oid, 'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('anon', p.oid, 'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('authenticated', p.oid, 'EXECUTE')
          AND NOT EXISTS (
            SELECT 1 FROM pg_catalog.aclexplode(
              COALESCE(p.proacl, pg_catalog.acldefault('f', p.proowner))
            ) AS acl
            WHERE acl.grantee NOT IN (p.proowner, 'service_role'::pg_catalog.regrole)
              OR acl.is_grantable
          )
      ) OR NOT EXISTS (
        SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
        WHERE allowed.source_signature = v_expected.source_signature AND allowed.grantee = 'service_role'
      ) OR EXISTS (
        SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
        WHERE allowed.source_signature = v_expected.source_signature AND allowed.grantee <> 'service_role'
      ) THEN
        RAISE EXCEPTION 'G014 service-only SECURITY INVOKER contract mismatch: %', v_expected.source_signature;
      END IF;
      CONTINUE;
    END IF;
    IF v_expected.source_signature IN (
      'public.restaurant_evidence_recovery_context(uuid,uuid)',
      'public.restaurant_evidence_recovery_status(uuid,uuid)',
      'public.restaurant_evidence_recovery_admin(uuid,text,uuid,uuid,uuid,bigint,text,text,text,text)',
      'public.restaurant_evidence_recovery_worker(text,uuid,uuid,jsonb)'
    ) THEN
      IF v_is_definer OR NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_proc p WHERE p.oid=v_procedure
          AND p.proowner='postgres'::pg_catalog.regrole AND p.prokind='f' AND NOT p.proretset
          AND p.prorettype='jsonb'::pg_catalog.regtype AND NOT p.proisstrict AND NOT p.proleakproof
          AND p.prolang=(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql')
          AND p.provolatile=(CASE WHEN v_expected.source_signature='public.restaurant_evidence_recovery_status(uuid,uuid)' THEN 's' ELSE 'v' END)::"char"
          AND p.proconfig IS NOT DISTINCT FROM CASE WHEN v_expected.source_signature='public.restaurant_evidence_recovery_status(uuid,uuid)'
            THEN ARRAY['search_path=""']::text[] ELSE ARRAY['search_path=""','lock_timeout=2s']::text[] END
          AND pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE')
          AND NOT EXISTS(SELECT 1 FROM pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) acl
            WHERE acl.grantee NOT IN (p.proowner,'service_role'::pg_catalog.regrole) OR acl.is_grantable)
      ) OR (SELECT count(*) FROM privacy_retention.g014_public_rpc_allowlist
        WHERE source_signature=v_expected.source_signature AND grantee='service_role')<>1
        OR EXISTS(SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist
          WHERE source_signature=v_expected.source_signature AND grantee<>'service_role')
      THEN RAISE EXCEPTION 'G014 evidence recovery SECURITY INVOKER contract mismatch: %',v_expected.source_signature;
      END IF;
      CONTINUE;
    END IF;
    IF v_expected.source_signature IN (
      'public.match_storyboard_documents_hybrid(uuid,extensions.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.match_storyboard_documents_hybrid(uuid,public.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.match_storyboard_documents_hybrid_v2(uuid,extensions.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.match_storyboard_documents_hybrid_v2(uuid,public.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.ocr_log_metadata_is_safe(jsonb)',
      'public.is_current_user_active_admin()',
      'public.publish_youtube_thumbnail_release(uuid,text,text,text,text,text,text,text,text,numeric,jsonb,jsonb,jsonb,jsonb,uuid,timestamp with time zone)'
    ) THEN
      IF v_is_definer THEN
        RAISE EXCEPTION 'G014 declared SECURITY INVOKER public RPC became SECURITY DEFINER: %',
          v_expected.source_signature;
      END IF;
      IF v_expected.source_signature IN (
        'public.is_current_user_active_admin()',
        'public.publish_youtube_thumbnail_release(uuid,text,text,text,text,text,text,text,text,numeric,jsonb,jsonb,jsonb,jsonb,uuid,timestamp with time zone)'
      ) THEN
        v_search_path := NULL;
        SELECT setting.value INTO v_search_path
        FROM pg_catalog.unnest((
          SELECT procedure.proconfig
          FROM pg_catalog.pg_proc AS procedure
          WHERE procedure.oid = v_procedure
        )) AS setting(value)
        WHERE setting.value LIKE 'search_path=%';
        IF pg_catalog.pg_get_userbyid((
             SELECT procedure.proowner
             FROM pg_catalog.pg_proc AS procedure
             WHERE procedure.oid = v_procedure
           )) IS DISTINCT FROM 'privacy_workflow_owner'
           OR (v_search_path IS DISTINCT FROM 'search_path='
               AND v_search_path IS DISTINCT FROM 'search_path=""') THEN
          RAISE EXCEPTION 'G014 post-contract SECURITY INVOKER public RPC owner/path mismatch: %',
            v_expected.source_signature;
        END IF;
      END IF;
    ELSIF NOT v_is_definer THEN
      RAISE EXCEPTION 'G014 undeclared SECURITY INVOKER allowlisted public RPC: %',
        v_expected.source_signature;
    ELSE
      SELECT setting.value INTO v_search_path
      FROM pg_catalog.unnest((SELECT procedure.proconfig FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = v_procedure))
        AS setting(value)
      WHERE setting.value LIKE 'search_path=%';
      IF pg_catalog.pg_get_userbyid((SELECT procedure.proowner FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = v_procedure))
            IS DISTINCT FROM (CASE
              WHEN v_expected.source_signature = ANY (ARRAY[
                'public.begin_account_deletion_apply(uuid,uuid,uuid,text,text,text,timestamptz,text)',
                'public.create_admin_transactional_notification(uuid,uuid,text,text,text,jsonb)',
                'public.create_review_like_notification(uuid,uuid,uuid)',
                'public.finalize_account_deletion_auth(uuid,uuid,uuid,text,text,text,uuid,text)',
                'public.hold_privacy_onboarding_compensation(uuid,uuid,text,text)',
                'public.make_user_admin(text)',
                'public.preflight_release_auth_session_family(uuid,uuid,uuid,text,bigint)',
                'public.prepare_account_deletion_external_egress(uuid,uuid,uuid,text,text,text,text,uuid)',
                'public.preview_account_deletion(uuid,uuid,timestamptz)',
                'public.read_account_deletion_external_job(uuid,uuid,uuid,text,text,text,text,uuid)',
                'public.read_release_auth_revocation(uuid,uuid,uuid)',
                'public.read_release_auth_revocation_by_operation(uuid)',
                'public.reconcile_account_deletion_auth_job(uuid,uuid,uuid,text,text,text,uuid)',
                'public.revoke_release_auth_session_family(uuid,uuid,uuid,text)',
                'public.run_account_deletion_session_family_cleanup(uuid,uuid,uuid,text,text,text,uuid)',
                'public.apply_account_deletion_database_cleanup(uuid,uuid,uuid,text,text,text)',
                'public.activate_account_deletion_policy(text,text)',
                'public.evaluate_notification_marketing_permission(uuid,text,timestamptz,text)'
              ]) THEN 'privacy_auth_bridge'
              ELSE 'privacy_workflow_owner'
            END)
         OR (v_search_path IS DISTINCT FROM 'search_path=' AND v_search_path IS DISTINCT FROM 'search_path=""') THEN
        RAISE EXCEPTION 'G014 allowlisted public RPC owner/definer/path mismatch: %', v_expected.source_signature;
      END IF;
    END IF;
    IF NOT pg_catalog.has_function_privilege(v_expected.grantee, v_procedure, 'EXECUTE') THEN
      RAISE EXCEPTION 'G014 allowlisted public RPC grant missing: %', v_expected.source_signature;
    END IF;
  END LOOP;

  -- No PUBLIC, anon, or authenticated effective EXECUTE survives outside its
  -- checked-in matrix. Service-role access is equally exact for every G014 RPC.
  FOR v_expected IN
    SELECT procedure.oid, namespace.nspname, procedure.proname,
           procedure.proargtypes::text AS identity_arguments
    FROM pg_catalog.pg_proc AS procedure
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
    WHERE namespace.nspname = 'public'
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.pg_depend AS dependency
        JOIN pg_catalog.pg_extension AS extension
          ON extension.oid = dependency.refobjid
        WHERE dependency.classid = 'pg_catalog.pg_proc'::pg_catalog.regclass
          AND dependency.objid = procedure.oid
          AND dependency.refclassid = 'pg_catalog.pg_extension'::pg_catalog.regclass
          AND dependency.deptype = 'e'
      )
  LOOP
    IF EXISTS (
      SELECT 1
      FROM (VALUES ('anon'::name), ('authenticated'::name), ('service_role'::name)) AS role_matrix(grantee)
      WHERE pg_catalog.has_function_privilege(role_matrix.grantee, v_expected.oid, 'EXECUTE')
        IS DISTINCT FROM EXISTS (
          SELECT 1
          FROM privacy_retention.g014_public_rpc_allowlist AS allowed
          WHERE allowed.function_schema = v_expected.nspname
            AND allowed.function_name = v_expected.proname
            AND allowed.identity_arguments = v_expected.identity_arguments
            AND allowed.grantee = role_matrix.grantee
        )
    ) OR EXISTS (
      SELECT 1
      FROM pg_catalog.aclexplode(COALESCE(
        (SELECT procedure.proacl FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = v_expected.oid),
        pg_catalog.acldefault('f', (SELECT procedure.proowner FROM pg_catalog.pg_proc AS procedure WHERE procedure.oid = v_expected.oid))
      )) AS acl
      WHERE acl.grantee = 0 AND acl.privilege_type = 'EXECUTE'
    ) THEN
      RAISE EXCEPTION 'G014 effective public RPC privilege drifted: %.%(%)',
        v_expected.nspname, v_expected.proname, v_expected.identity_arguments;
    END IF;
  END LOOP;
  -- Resolve the Auth relation solely through pg_catalog. A SECURITY DEFINER
  -- assertion must not require USAGE on the platform-owned auth schema.
  SELECT relation_row.oid
    INTO v_auth_users_oid
    FROM pg_catalog.pg_class AS relation_row
    JOIN pg_catalog.pg_namespace AS namespace
      ON namespace.oid = relation_row.relnamespace
   WHERE namespace.nspname = 'auth'
     AND relation_row.relname = 'users'
     AND relation_row.relkind = 'r';
  GET DIAGNOSTICS v_auth_users_count = ROW_COUNT;
  IF v_auth_users_count <> 1 THEN
    RAISE EXCEPTION 'G014 auth.users catalog identity is missing or ambiguous';
  END IF;

  -- The moved G010 identities retain exactly four live Auth FKs. The retained
  -- privacy audit actor UUID is deliberately detached from auth.users so
  -- historical append-only audit identity does not couple to active Auth
  -- deletion. Any additional private Auth dependency would make
  -- retention/deletion coupling implicit and therefore blocks promotion.
  -- Diagnostics contain catalog identities only, never table data, and are
  -- ordered for stable replay output.
  WITH expected(schema_name, relation_name, column_name, constraint_name, delete_action) AS (
    VALUES
      ('privacy_retention'::name, 'privacy_onboarding_challenges'::name, 'consumed_by_user_id'::name, 'privacy_onboarding_challenges_consumed_by_user_id_fkey'::name, 'RESTRICT'::text),
      ('privacy_retention'::name, 'privacy_guardian_verifications'::name, 'child_user_id'::name, 'privacy_guardian_verifications_child_user_id_fkey'::name, 'RESTRICT'::text),
      ('privacy_retention'::name, 'privacy_age_profiles'::name, 'user_id'::name, 'privacy_age_profiles_user_id_fkey'::name, 'RESTRICT'::text),
      ('privacy_retention'::name, 'privacy_consent_events'::name, 'user_id'::name, 'privacy_consent_events_user_id_fkey'::name, 'RESTRICT'::text)
  ),
  actual AS (
    SELECT
      namespace.nspname::name AS schema_name,
      relation_row.relname::name AS relation_name,
      attribute.attname::name AS column_name,
      constraint_row.conname AS constraint_name,
      CASE constraint_row.confdeltype
        WHEN 'a' THEN 'NO ACTION'
        WHEN 'r' THEN 'RESTRICT'
        WHEN 'c' THEN 'CASCADE'
        WHEN 'n' THEN 'SET NULL'
        WHEN 'd' THEN 'SET DEFAULT'
      END AS delete_action
    FROM pg_catalog.pg_constraint AS constraint_row
    JOIN pg_catalog.pg_class AS relation_row ON relation_row.oid = constraint_row.conrelid
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation_row.relnamespace
    JOIN LATERAL pg_catalog.unnest(constraint_row.conkey) AS key_column(attnum) ON true
    JOIN pg_catalog.pg_attribute AS attribute
      ON attribute.attrelid = relation_row.oid AND attribute.attnum = key_column.attnum
    WHERE constraint_row.contype = 'f'
      AND constraint_row.confrelid = v_auth_users_oid
      AND namespace.nspname = 'privacy_retention'
  ),
  missing AS (
    SELECT * FROM expected
    EXCEPT
    SELECT * FROM actual
  ),
  unexpected AS (
    SELECT * FROM actual
    EXCEPT
    SELECT * FROM expected
  )
  SELECT
    COALESCE((
      SELECT pg_catalog.string_agg(
        pg_catalog.format(
          '%I.%I.%I constraint=%I on_delete=%s',
          schema_name, relation_name, column_name, constraint_name, delete_action
        ),
        '; ' ORDER BY schema_name, relation_name, column_name, constraint_name, delete_action
      )
      FROM missing
    ), ''),
    COALESCE((
      SELECT pg_catalog.string_agg(
        pg_catalog.format(
          '%I.%I.%I constraint=%I on_delete=%s',
          schema_name, relation_name, column_name, constraint_name, delete_action
        ),
        '; ' ORDER BY schema_name, relation_name, column_name, constraint_name, delete_action
      )
      FROM unexpected
    ), '')
  INTO v_auth_dependency_missing, v_auth_dependency_unexpected;

  IF v_auth_dependency_missing <> '' OR v_auth_dependency_unexpected <> '' THEN
    RAISE EXCEPTION
      'G014 private auth.users dependency contract drifted; missing=[%]; unexpected=[%]',
      v_auth_dependency_missing,
      v_auth_dependency_unexpected;
  END IF;
END;
$_$;


--
-- Name: assert_g014_catalog_manifest(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_catalog_manifest() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    WITH expected AS (
      SELECT * FROM privacy_retention.g014_catalog_protected_relations()
    ),
    actual AS (
      SELECT namespace.nspname::name AS schema_name, relation_row.relname::name AS relation_name
      FROM pg_catalog.pg_class AS relation_row
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation_row.relnamespace
      WHERE relation_row.relkind IN ('r', 'p')
        AND (
          (namespace.nspname = 'privacy_retention'
            AND relation_row.relname <> 'g014_catalog_contract_manifest')
          OR EXISTS (
            SELECT 1
            FROM expected
            WHERE expected.schema_name = namespace.nspname
              AND expected.relation_name = relation_row.relname
          )
        )
    )
    SELECT 1
    FROM (
      (SELECT * FROM expected EXCEPT SELECT * FROM actual)
      UNION ALL
      (SELECT * FROM actual EXCEPT SELECT * FROM expected)
    ) AS relation_drift
  ) THEN
    RAISE EXCEPTION 'G014 protected relation catalog drifted';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM privacy_retention.g014_catalog_contract_manifest
  ) THEN
    RAISE EXCEPTION 'G014 catalog manifest is missing';
  END IF;

  IF EXISTS (
    (
      SELECT manifest_kind, manifest_key, manifest_value
      FROM privacy_retention.g014_catalog_contract_manifest
      EXCEPT
      SELECT manifest_kind, manifest_key, manifest_value
      FROM privacy_retention.g014_catalog_manifest_rows()
    )
    UNION ALL
    (
      SELECT manifest_kind, manifest_key, manifest_value
      FROM privacy_retention.g014_catalog_manifest_rows()
      EXCEPT
      SELECT manifest_kind, manifest_key, manifest_value
      FROM privacy_retention.g014_catalog_contract_manifest
    )
  ) THEN
    RAISE EXCEPTION 'G014 exact catalog manifest drifted';
  END IF;
END;
$$;


--
-- Name: assert_g014_catalog_security_baseline(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_catalog_security_baseline() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_attribute AS attribute
    WHERE attribute.attrelid = 'public.account_deletion_requests'::regclass
      AND attribute.attname = 'source_manifest_hash'
      AND attribute.attnum > 0
      AND NOT attribute.attisdropped
      AND attribute.attnotnull
      AND attribute.atttypid = 'text'::regtype
  ) THEN
    RAISE EXCEPTION 'G014 source_manifest_hash must be NOT NULL';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_constraint AS constraint_row
    WHERE constraint_row.conrelid = 'public.account_deletion_requests'::regclass
      AND constraint_row.conname = 'g014_account_deletion_applied_receipt_check'
      AND constraint_row.contype = 'c'
      AND constraint_row.convalidated
  ) THEN
    RAISE EXCEPTION 'G014 applied deletion receipt CHECK is missing or unvalidated';
  END IF;

  -- G014 grants no column privileges on protected relations. This source-declared
  -- zero-row contract runs before a first manifest can be persisted, so an
  -- inherited browser/service-role column grant cannot become its own baseline.
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.g014_catalog_protected_relations() AS expected
    JOIN pg_catalog.pg_namespace AS namespace
      ON namespace.nspname = expected.schema_name
    JOIN pg_catalog.pg_class AS relation_row
      ON relation_row.relnamespace = namespace.oid
     AND relation_row.relname = expected.relation_name
    JOIN pg_catalog.pg_attribute AS attribute
      ON attribute.attrelid = relation_row.oid
     AND attribute.attnum > 0
     AND NOT attribute.attisdropped
    CROSS JOIN LATERAL pg_catalog.aclexplode(attribute.attacl) AS acl
  ) THEN
    RAISE EXCEPTION 'G014 protected column ACL baseline drifted';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.g014_catalog_protected_relations() AS expected
    JOIN pg_catalog.pg_namespace AS namespace
      ON namespace.nspname = expected.schema_name
    JOIN pg_catalog.pg_class AS relation_row
      ON relation_row.relnamespace = namespace.oid
     AND relation_row.relname = expected.relation_name
    WHERE expected.schema_name = 'privacy_retention'
      AND (
        pg_catalog.pg_get_userbyid(relation_row.relowner) IS DISTINCT FROM 'privacy_workflow_owner'
        OR NOT relation_row.relrowsecurity
        OR NOT relation_row.relforcerowsecurity
        OR NOT EXISTS (
          SELECT 1
          FROM pg_catalog.pg_policy AS policy_row
          JOIN pg_catalog.unnest(policy_row.polroles) AS policy_role(role_oid) ON true
          JOIN pg_catalog.pg_roles AS role_row ON role_row.oid = policy_role.role_oid
          WHERE policy_row.polrelid = relation_row.oid
            AND role_row.rolname = 'privacy_workflow_owner'
        )
      )
  ) THEN
    RAISE EXCEPTION 'G014 private catalog security baseline drifted';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM privacy_retention.g014_catalog_protected_relations() AS expected
    JOIN pg_catalog.pg_namespace AS namespace
      ON namespace.nspname = expected.schema_name
    JOIN pg_catalog.pg_class AS relation_row
      ON relation_row.relnamespace = namespace.oid
     AND relation_row.relname = expected.relation_name
    WHERE expected.schema_name = 'public'
      AND (
        pg_catalog.pg_get_userbyid(relation_row.relowner) IS DISTINCT FROM 'privacy_workflow_owner'
        OR NOT relation_row.relrowsecurity
        OR NOT relation_row.relforcerowsecurity
        OR NOT EXISTS (
          SELECT 1
          FROM pg_catalog.pg_policy AS policy_row
          JOIN pg_catalog.unnest(policy_row.polroles) AS policy_role(role_oid) ON true
          JOIN pg_catalog.pg_roles AS role_row ON role_row.oid = policy_role.role_oid
          WHERE policy_row.polrelid = relation_row.oid
            AND role_row.rolname = 'privacy_workflow_owner'
        )
        OR pg_catalog.has_table_privilege('service_role', relation_row.oid, 'INSERT')
        OR pg_catalog.has_table_privilege('service_role', relation_row.oid, 'UPDATE')
        OR pg_catalog.has_table_privilege('service_role', relation_row.oid, 'DELETE')
      )
  ) THEN
    RAISE EXCEPTION 'G014 public catalog security baseline drifted';
  END IF;
END;
$$;


--
-- Name: assert_g014_cross_schema_contract(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_cross_schema_contract() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_signature text;
  v_oid oid;
  v_procedure record;
  v_search_path text;
  v_stale_private_relation_prefix text := pg_catalog.replace(
    'privacy_retention.',
    'privacy_retention',
    'public'
  );
  v_doubled_extensions_qualification text := 'extensions.' || 'extensions.';
  v_doubled_pg_catalog_qualification text := 'pg_catalog.' || 'pg_catalog.';
  v_doubled_public_qualification text := 'public.' || 'public.';
  v_unqualified_gen_random_uuid text := 'gen_random_' || 'uuid()';
  v_extensions_gen_random_uuid text := 'extensions.' || 'gen_random_' || 'uuid()';
  v_unqualified_encode_digest text := ' encode(' || 'digest(';
  v_unqualified_digest text := ' dig' || 'est(';
BEGIN
  FOR v_signature IN
    SELECT expected.source_signature
    FROM (VALUES
      ('public.account_deletion_require_service_role()'),
      ('public.account_deletion_is_active_admin(uuid)'),
      ('public.account_deletion_write_audit(public.account_deletion_requests,text,text)'),
      ('public.preview_account_deletion(uuid,uuid,timestamptz)'),
      ('public.begin_account_deletion_apply(uuid,uuid,uuid,text,text,text,timestamptz)'),
      ('public.apply_account_deletion_database_cleanup(uuid,uuid)'),
      ('public.list_account_deletion_storage_objects(uuid,uuid)'),
      ('public.finalize_account_deletion_storage(uuid,uuid,boolean)'),
      ('public.finalize_account_deletion_auth(uuid,uuid,boolean)'),
      ('public.fail_account_deletion(uuid,uuid,text)'),
      ('privacy_retention.require_service_role()'),
      ('privacy_retention.write_run_audit(privacy_retention.privacy_retention_runs,text,text)')
    ) AS expected(source_signature)
  LOOP
    v_oid := pg_catalog.to_regprocedure(v_signature);
    IF v_oid IS NULL THEN
      RAISE EXCEPTION 'G014 required cross-schema function is missing: %', v_signature;
    END IF;

    SELECT procedure.prosecdef,
           pg_catalog.pg_get_userbyid(procedure.proowner) AS owner_name,
           procedure.proconfig
    INTO v_procedure
    FROM pg_catalog.pg_proc AS procedure
    WHERE procedure.oid = v_oid;

    IF NOT v_procedure.prosecdef THEN
      RAISE EXCEPTION 'G014 cross-schema function is SECURITY INVOKER: %', v_signature;
    END IF;
    IF v_procedure.owner_name <> 'postgres' THEN
      RAISE EXCEPTION 'G014 cross-schema function owner mismatch: %', v_signature;
    END IF;

    SELECT setting.value INTO v_search_path
    FROM pg_catalog.unnest(v_procedure.proconfig) AS setting(value)
    WHERE setting.value LIKE 'search_path=%';

    IF v_search_path IS DISTINCT FROM 'search_path='
       AND v_search_path IS DISTINCT FROM 'search_path=""' THEN
      RAISE EXCEPTION 'G014 cross-schema function search_path is not empty: %', v_signature;
    END IF;
    IF position(v_stale_private_relation_prefix || 'privacy_policy_versions' IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_stale_private_relation_prefix || 'privacy_onboarding_challenges' IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_stale_private_relation_prefix || 'privacy_guardian_verifications' IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_stale_private_relation_prefix || 'privacy_age_profiles' IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_stale_private_relation_prefix || 'privacy_consent_events' IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_stale_private_relation_prefix || 'privacy_audit_events' IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_doubled_extensions_qualification IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_doubled_pg_catalog_qualification IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_doubled_public_qualification IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR (
         position(v_unqualified_gen_random_uuid IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
         AND position(v_extensions_gen_random_uuid IN pg_catalog.pg_get_functiondef(v_oid)) = 0
       )
       OR position(v_unqualified_encode_digest IN pg_catalog.pg_get_functiondef(v_oid)) <> 0
       OR position(v_unqualified_digest IN pg_catalog.pg_get_functiondef(v_oid)) <> 0 THEN
      RAISE EXCEPTION 'G014 cross-schema function qualification mismatch: %', v_signature;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM (VALUES ('anon'::name), ('authenticated'::name), ('service_role'::name)) AS roles(role_name)
      WHERE pg_catalog.has_function_privilege(roles.role_name, v_oid, 'EXECUTE')
        IS DISTINCT FROM EXISTS (
          SELECT 1
          FROM privacy_retention.g014_public_rpc_allowlist AS allowed
          WHERE allowed.source_signature = v_signature
            AND allowed.grantee = roles.role_name
        )
    ) THEN
      RAISE EXCEPTION 'G014 cross-schema function Data API EXECUTE mismatch: %', v_signature;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: assert_g014_definer_contract(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_definer_contract() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_signature text;
  v_oid oid;
  v_owner text;
  v_search_path text;
  v_is_definer boolean;
BEGIN
  FOR v_signature IN
    SELECT source_signature FROM privacy_retention.g014_public_rpc_allowlist
    UNION ALL VALUES
      ('privacy_retention.g014_retention_storage_receipt_set_hash(uuid)'),
      ('privacy_retention.g014_retention_source_absent(text,text,text,text)'),
      ('privacy_retention.g014_retention_no_active_hold_mutated(uuid)'),
      ('privacy_retention.g014_retention_catalog_fingerprint(text,text)'),
      ('privacy_retention.g014_retention_require_activation_operator()'),
      ('privacy_retention.g014_retention_active_adapter_version(text)'),
      ('privacy_retention.g014_retention_active_source_mapping_version(text)'),
      ('privacy_retention.g014_retention_assert_class_bindings(text)'),
      ('privacy_retention.g014_retention_assert_run_bindings(text,text,text)'),
      ('privacy_retention.g014_retention_append_audit(privacy_retention.privacy_retention_runs,text,text)')
  LOOP
    v_oid := pg_catalog.to_regprocedure(v_signature);
    IF v_oid IS NULL THEN
      RAISE EXCEPTION 'G014 required RPC identity is missing: %', v_signature;
    END IF;
    SELECT procedure.prosecdef
    INTO v_is_definer
    FROM pg_catalog.pg_proc AS procedure
    WHERE procedure.oid = v_oid;
    IF v_signature IN (
      'public.extract_youtube_video_id(text)',
      'public.normalize_restaurant_identity_name(text)',
      'public.admin_evaluation_revision()',
      'public.admin_evaluation_catalog_snapshot()',
      'public.storyboard_production_error_allowed(text)',
      'public.storyboard_production_final_status(jsonb,jsonb)',
      'public.storyboard_production_project_json(public.admin_storyboard_production_projects)',
      'public.storyboard_production_job_json(public.admin_storyboard_production_jobs)',
      'public.storyboard_production_snapshot(uuid,uuid)',
      'public.storyboard_production_auth_worker(text)',
      'public.storyboard_production_model_available(jsonb,text,text)',
      'public.storyboard_production_admin(uuid,text,uuid,integer,jsonb)',
      'public.storyboard_production_worker(uuid,text,uuid,uuid,jsonb)',
      'public.record_app_web_vitals(text,text,text,text,smallint)',
      'public.record_app_web_vitals_bounded(text,text,text,text,smallint)',
      'public.restaurant_review_automation_manual(uuid,text,text,text,uuid)',
      'public.admin_evaluation_page(jsonb,integer,uuid,text)',
      'public.admin_evaluation_warning_groups(uuid[],text)',
      'public.admin_record_action(uuid,text,uuid,text,uuid[],jsonb,text)',
      'public.admin_evaluation_raw_warning_groups(uuid[],text,jsonb,integer)',
      'public.restaurant_review_automation_status()',
      'public.restaurant_review_automation_preview(uuid,integer,integer)',
      'public.restaurant_review_automation_configure(uuid,text,text,text,integer,integer)',
      'public.restaurant_review_automation_tick(uuid)',
      'public.restaurant_review_automation_worker(text,uuid,uuid,jsonb)',
      'public.resolve_restaurant_identity_name(text,text,text,text)'
    ) THEN
      IF v_is_definer OR NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_proc AS p
        WHERE p.oid = v_oid
          AND pg_catalog.pg_get_userbyid(p.proowner) = 'postgres'
          AND p.proconfig IS NOT DISTINCT FROM CASE
            WHEN v_signature IN (
              'public.extract_youtube_video_id(text)',
              'public.normalize_restaurant_identity_name(text)',
              'public.resolve_restaurant_identity_name(text,text,text,text)'
            ) THEN ARRAY['search_path=pg_catalog, public, extensions']::text[]
            WHEN v_signature IN (
              'public.restaurant_review_automation_manual(uuid,text,text,text,uuid)',
              'public.restaurant_review_automation_tick(uuid)',
              'public.restaurant_review_automation_worker(text,uuid,uuid,jsonb)'
            ) THEN ARRAY['search_path=""','lock_timeout=2s']::text[]
            ELSE ARRAY['search_path=""']::text[]
          END
          AND pg_catalog.has_function_privilege('service_role', p.oid, 'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('anon', p.oid, 'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('authenticated', p.oid, 'EXECUTE')
          AND NOT EXISTS (
            SELECT 1 FROM pg_catalog.aclexplode(
              COALESCE(p.proacl, pg_catalog.acldefault('f', p.proowner))
            ) AS acl
            WHERE acl.grantee NOT IN (p.proowner, 'service_role'::pg_catalog.regrole)
              OR acl.is_grantable
          )
      ) OR NOT EXISTS (
        SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
        WHERE allowed.source_signature = v_signature AND allowed.grantee = 'service_role'
      ) OR EXISTS (
        SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist AS allowed
        WHERE allowed.source_signature = v_signature AND allowed.grantee <> 'service_role'
      ) THEN
        RAISE EXCEPTION 'G014 service-only SECURITY INVOKER contract mismatch: %', v_signature;
      END IF;
      CONTINUE;
    END IF;
    IF v_signature IN (
      'public.restaurant_evidence_recovery_context(uuid,uuid)',
      'public.restaurant_evidence_recovery_status(uuid,uuid)',
      'public.restaurant_evidence_recovery_admin(uuid,text,uuid,uuid,uuid,bigint,text,text,text,text)',
      'public.restaurant_evidence_recovery_worker(text,uuid,uuid,jsonb)'
    ) THEN
      IF v_is_definer OR NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_proc p WHERE p.oid=v_oid
          AND p.proowner='postgres'::pg_catalog.regrole AND p.prokind='f' AND NOT p.proretset
          AND p.prorettype='jsonb'::pg_catalog.regtype AND NOT p.proisstrict AND NOT p.proleakproof
          AND p.prolang=(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql')
          AND p.provolatile=(CASE WHEN v_signature='public.restaurant_evidence_recovery_status(uuid,uuid)' THEN 's' ELSE 'v' END)::"char"
          AND p.proconfig IS NOT DISTINCT FROM CASE WHEN v_signature='public.restaurant_evidence_recovery_status(uuid,uuid)'
            THEN ARRAY['search_path=""']::text[] ELSE ARRAY['search_path=""','lock_timeout=2s']::text[] END
          AND pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE')
          AND NOT pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE')
          AND NOT EXISTS(SELECT 1 FROM pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) acl
            WHERE acl.grantee NOT IN (p.proowner,'service_role'::pg_catalog.regrole) OR acl.is_grantable)
      ) OR (SELECT count(*) FROM privacy_retention.g014_public_rpc_allowlist
        WHERE source_signature=v_signature AND grantee='service_role')<>1
        OR EXISTS(SELECT 1 FROM privacy_retention.g014_public_rpc_allowlist
          WHERE source_signature=v_signature AND grantee<>'service_role')
      THEN RAISE EXCEPTION 'G014 evidence recovery SECURITY INVOKER contract mismatch: %',v_signature;
      END IF;
      CONTINUE;
    END IF;
    IF v_signature IN (
      'public.match_storyboard_documents_hybrid(uuid,extensions.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.match_storyboard_documents_hybrid(uuid,public.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.match_storyboard_documents_hybrid_v2(uuid,extensions.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.match_storyboard_documents_hybrid_v2(uuid,public.vector,jsonb,double precision,integer,integer,jsonb)',
      'public.ocr_log_metadata_is_safe(jsonb)',
      'public.is_current_user_active_admin()',
      'public.publish_youtube_thumbnail_release(uuid,text,text,text,text,text,text,text,text,numeric,jsonb,jsonb,jsonb,jsonb,uuid,timestamp with time zone)'
    ) THEN
      IF v_is_definer THEN
        RAISE EXCEPTION 'G014 declared SECURITY INVOKER RPC became SECURITY DEFINER: %', v_signature;
      END IF;
      IF v_signature IN (
        'public.is_current_user_active_admin()',
        'public.publish_youtube_thumbnail_release(uuid,text,text,text,text,text,text,text,text,numeric,jsonb,jsonb,jsonb,jsonb,uuid,timestamp with time zone)'
      ) THEN
        SELECT pg_catalog.pg_get_userbyid(procedure.proowner), setting.value
        INTO v_owner, v_search_path
        FROM pg_catalog.pg_proc AS procedure
        LEFT JOIN LATERAL pg_catalog.unnest(procedure.proconfig) AS setting(value)
          ON setting.value LIKE 'search_path=%'
        WHERE procedure.oid = v_oid;
        IF v_owner IS DISTINCT FROM 'privacy_workflow_owner'
           OR (v_search_path IS DISTINCT FROM 'search_path='
               AND v_search_path IS DISTINCT FROM 'search_path=""') THEN
          RAISE EXCEPTION 'G014 post-contract SECURITY INVOKER RPC owner/path mismatch: %',
            v_signature;
        END IF;
      END IF;
      CONTINUE;
    END IF;
    IF v_signature IN (
      'public.read_public_profile_summaries(uuid[])',
      'public.read_public_profile_leaderboard(text,integer)',
      'public.read_public_profile_leaderboard_page(text,integer,numeric,uuid)',
      'public.update_current_profile_nickname(text)',
      'public.compare_and_set_current_profile_avatar(text,uuid)',
      'public.read_signup_profile_state(uuid,text)'
    ) AND NOT v_is_definer THEN
      RAISE EXCEPTION 'G014 profile boundary became SECURITY INVOKER: %',
        v_signature;
    END IF;
    IF NOT v_is_definer THEN
      RAISE EXCEPTION 'G014 required SECURITY DEFINER identity is SECURITY INVOKER: %', v_signature;
    END IF;

    SELECT pg_catalog.pg_get_userbyid(procedure.proowner), setting.value
    INTO v_owner, v_search_path
    FROM pg_catalog.pg_proc AS procedure
    LEFT JOIN LATERAL pg_catalog.unnest(procedure.proconfig) AS setting(value)
      ON setting.value LIKE 'search_path=%'
    WHERE procedure.oid = v_oid;

    IF v_owner IS DISTINCT FROM (CASE
      WHEN v_signature = ANY (ARRAY[
        'public.begin_account_deletion_apply(uuid,uuid,uuid,text,text,text,timestamptz,text)',
        'public.create_admin_transactional_notification(uuid,uuid,text,text,text,jsonb)',
        'public.create_review_like_notification(uuid,uuid,uuid)',
        'public.finalize_account_deletion_auth(uuid,uuid,uuid,text,text,text,uuid,text)',
        'public.hold_privacy_onboarding_compensation(uuid,uuid,text,text)',
        'public.make_user_admin(text)',
        'public.preflight_release_auth_session_family(uuid,uuid,uuid,text,bigint)',
        'public.prepare_account_deletion_external_egress(uuid,uuid,uuid,text,text,text,text,uuid)',
        'public.preview_account_deletion(uuid,uuid,timestamptz)',
        'privacy_retention.g014_account_deletion_reconcile_expired_attempt(uuid,text,uuid)',
        'privacy_retention.g014_retention_append_audit(privacy_retention.privacy_retention_runs,text,text)',
        'public.read_account_deletion_external_job(uuid,uuid,uuid,text,text,text,text,uuid)',
        'public.read_release_auth_revocation(uuid,uuid,uuid)',
        'public.read_release_auth_revocation_by_operation(uuid)',
        'public.reconcile_account_deletion_auth_job(uuid,uuid,uuid,text,text,text,uuid)',
        'public.revoke_release_auth_session_family(uuid,uuid,uuid,text)',
        'public.run_account_deletion_session_family_cleanup(uuid,uuid,uuid,text,text,text,uuid)',
        'privacy_retention.g014_account_deletion_apply_adapter(text,uuid,uuid)',
        'public.apply_account_deletion_database_cleanup(uuid,uuid,uuid,text,text,text)',
        'public.activate_account_deletion_policy(text,text)',
        'public.evaluate_notification_marketing_permission(uuid,text,timestamptz,text)'
      ]) THEN 'privacy_auth_bridge'
      ELSE 'privacy_workflow_owner'
    END) THEN
      RAISE EXCEPTION 'G014 SECURITY DEFINER owner mismatch: %', v_signature;
    END IF;
    IF v_search_path IS DISTINCT FROM 'search_path='
       AND v_search_path IS DISTINCT FROM 'search_path=""' THEN
      RAISE EXCEPTION 'G014 SECURITY DEFINER search_path is not empty: %', v_signature;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: assert_g014_invoker_contract(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_invoker_contract() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_procedure record;
  v_search_path text;
BEGIN
  SELECT procedure.prosecdef,
         pg_catalog.pg_get_userbyid(procedure.proowner) AS owner_name,
         procedure.proconfig
  INTO v_procedure
  FROM pg_catalog.pg_proc AS procedure
  WHERE procedure.oid = 'privacy_retention.g014_reject_audit_mutation()'::regprocedure;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'G014 required SECURITY INVOKER audit trigger function is missing';
  END IF;
  IF v_procedure.prosecdef THEN
    RAISE EXCEPTION 'G014 audit trigger function must remain SECURITY INVOKER';
  END IF;
  IF v_procedure.owner_name <> 'privacy_workflow_owner' THEN
    RAISE EXCEPTION 'G014 SECURITY INVOKER audit trigger owner mismatch';
  END IF;

  SELECT setting.value INTO v_search_path
  FROM pg_catalog.unnest(v_procedure.proconfig) AS setting(value)
  WHERE setting.value LIKE 'search_path=%';

  IF v_search_path IS DISTINCT FROM 'search_path='
     AND v_search_path IS DISTINCT FROM 'search_path=""' THEN
    RAISE EXCEPTION 'G014 SECURITY INVOKER audit trigger search_path is not empty';
  END IF;
END;
$$;


--
-- Name: assert_g014_public_rpc_allowlist(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_public_rpc_allowlist() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_unexpected_identity text;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.g014_public_rpc_allowlist AS allowed
    WHERE pg_catalog.to_regprocedure(allowed.source_signature) IS NULL
  ) THEN
    RAISE EXCEPTION 'G014 required public RPC identity is missing';
  END IF;

  SELECT format(
           '%I.%I(%s)',
           namespace.nspname,
           procedure.proname,
           pg_catalog.pg_get_function_identity_arguments(procedure.oid)
         )
  INTO v_unexpected_identity
  FROM pg_catalog.pg_proc AS procedure
  JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
  JOIN (
    SELECT DISTINCT function_schema, function_name
    FROM privacy_retention.g014_public_rpc_allowlist
  ) AS expected_name
    ON expected_name.function_schema = namespace.nspname
   AND expected_name.function_name = procedure.proname
  WHERE namespace.nspname = 'public'
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.g014_public_rpc_allowlist AS allowed
      WHERE allowed.function_schema = namespace.nspname
        AND allowed.function_name = procedure.proname
        AND allowed.identity_arguments = procedure.proargtypes::text
    )
  ORDER BY
    namespace.nspname,
    procedure.proname,
    pg_catalog.pg_get_function_identity_arguments(procedure.oid)
  LIMIT 1;

  IF v_unexpected_identity IS NOT NULL THEN
    RAISE EXCEPTION 'G014 found an unexpected overload of an allowlisted RPC: %',
      v_unexpected_identity;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS procedure
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
    WHERE namespace.nspname = 'public'
      AND pg_catalog.pg_get_userbyid(procedure.proowner) NOT IN ('postgres', 'privacy_workflow_owner', 'privacy_auth_bridge')
  ) THEN
    RAISE EXCEPTION 'G014 found a public function owned by an unverified creator';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS bridge_procedure
    JOIN pg_catalog.pg_namespace AS bridge_namespace
      ON bridge_namespace.oid = bridge_procedure.pronamespace
    WHERE bridge_namespace.nspname = 'public'
      AND bridge_procedure.proowner = 'privacy_auth_bridge'::pg_catalog.regrole
      AND NOT EXISTS (
        SELECT 1
        FROM unnest(ARRAY[
          'public.begin_account_deletion_apply(uuid,uuid,uuid,text,text,text,timestamptz,text)',
          'public.create_admin_transactional_notification(uuid,uuid,text,text,text,jsonb)',
          'public.create_review_like_notification(uuid,uuid,uuid)',
          'public.finalize_account_deletion_auth(uuid,uuid,uuid,text,text,text,uuid,text)',
          'public.hold_privacy_onboarding_compensation(uuid,uuid,text,text)',
          'public.make_user_admin(text)',
          'public.preflight_release_auth_session_family(uuid,uuid,uuid,text,bigint)',
          'public.prepare_account_deletion_external_egress(uuid,uuid,uuid,text,text,text,text,uuid)',
          'public.preview_account_deletion(uuid,uuid,timestamptz)',
          'public.read_account_deletion_external_job(uuid,uuid,uuid,text,text,text,text,uuid)',
          'public.read_release_auth_revocation(uuid,uuid,uuid)',
          'public.read_release_auth_revocation_by_operation(uuid)',
          'public.reconcile_account_deletion_auth_job(uuid,uuid,uuid,text,text,text,uuid)',
          'public.revoke_release_auth_session_family(uuid,uuid,uuid,text)',
          'public.run_account_deletion_session_family_cleanup(uuid,uuid,uuid,text,text,text,uuid)',
          'public.apply_account_deletion_database_cleanup(uuid,uuid,uuid,text,text,text)',
          'public.activate_account_deletion_policy(text,text)',
          'public.evaluate_notification_marketing_permission(uuid,text,timestamptz,text)'
        ]) AS expected(signature)
        WHERE pg_catalog.to_regprocedure(expected.signature) = bridge_procedure.oid
      )
  ) THEN
    RAISE EXCEPTION 'G041 found a public function unexpectedly owned by privacy_auth_bridge';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS procedure
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
    CROSS JOIN (VALUES ('anon'::name), ('authenticated'::name), ('service_role'::name)) AS role_matrix(grantee)
    WHERE namespace.nspname = 'public'
      AND pg_catalog.has_function_privilege(role_matrix.grantee, procedure.oid, 'EXECUTE')
        IS DISTINCT FROM EXISTS (
          SELECT 1
          FROM privacy_retention.g014_public_rpc_allowlist AS allowed
          WHERE allowed.function_schema = namespace.nspname
            AND allowed.function_name = procedure.proname
            AND allowed.identity_arguments = procedure.proargtypes::text
            AND allowed.grantee = role_matrix.grantee
        )
  ) THEN
    RAISE EXCEPTION 'G014 public RPC effective grantee matrix does not match the allowlist';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS procedure
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
    CROSS JOIN LATERAL pg_catalog.aclexplode(
      COALESCE(procedure.proacl, pg_catalog.acldefault('f', procedure.proowner))
    ) AS acl
    WHERE namespace.nspname = 'public'
      AND acl.grantee = 0
      AND acl.privilege_type = 'EXECUTE'
  ) THEN
    RAISE EXCEPTION 'G014 found PUBLIC EXECUTE on a public function';
  END IF;
END;
$$;


--
-- Name: assert_g014_workflow_owner_contract(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.assert_g014_workflow_owner_contract() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_owner pg_catalog.pg_roles%ROWTYPE;
  v_bridge pg_catalog.pg_roles%ROWTYPE;
BEGIN
  SELECT * INTO v_owner
  FROM pg_catalog.pg_roles
  WHERE rolname = 'privacy_workflow_owner';
  SELECT * INTO v_bridge
  FROM pg_catalog.pg_roles
  WHERE rolname = 'privacy_auth_bridge';

  IF v_owner.oid IS NULL OR v_bridge.oid IS NULL THEN
    RAISE EXCEPTION 'privacy workflow bridge roles are missing';
  END IF;
  IF v_owner.rolsuper OR v_owner.rolinherit OR v_owner.rolcreaterole
     OR v_owner.rolcreatedb OR v_owner.rolreplication
     OR v_owner.rolbypassrls OR v_owner.rolcanlogin
     OR v_bridge.rolsuper OR NOT v_bridge.rolinherit OR v_bridge.rolcreaterole
     OR v_bridge.rolcreatedb OR v_bridge.rolreplication
     OR v_bridge.rolbypassrls OR v_bridge.rolcanlogin THEN
    RAISE EXCEPTION 'privacy workflow bridge role attributes are incompatible';
  END IF;
  IF (SELECT count(*)
      FROM pg_catalog.pg_auth_members AS membership
      WHERE membership.member = v_owner.oid OR membership.roleid = v_owner.oid) <> 1
     OR NOT EXISTS (
       SELECT 1
       FROM pg_catalog.pg_auth_members AS membership
       WHERE membership.roleid = v_owner.oid
         AND membership.member = v_bridge.oid
         AND NOT membership.admin_option
     )
     OR NOT pg_catalog.pg_has_role(v_bridge.oid, v_owner.oid, 'USAGE') THEN
    RAISE EXCEPTION 'privacy_workflow_owner has unexpected role membership or effective access';
  END IF;
END;
$$;


--
-- Name: g014_account_deletion_admin_removal_fence(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_admin_removal_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_target_user_id uuid;
  v_available_active_admins integer;
BEGIN
  IF TG_TABLE_NAME = 'user_roles' THEN
    IF TG_OP = 'DELETE' THEN
      IF OLD.role IS DISTINCT FROM 'admin' THEN
        RETURN OLD;
      END IF;
      v_target_user_id := OLD.user_id;
    ELSIF OLD.role = 'admin' AND NEW.role IS DISTINCT FROM 'admin' THEN
      v_target_user_id := OLD.user_id;
    ELSE
      RETURN NEW;
    END IF;
  ELSIF TG_TABLE_NAME = 'user_account_status' THEN
    IF NEW.account_status = 'active'
       OR (TG_OP = 'UPDATE' AND OLD.account_status IS DISTINCT FROM 'active') THEN
      RETURN NEW;
    END IF;
    v_target_user_id := NEW.user_id;
    IF NOT EXISTS (
      SELECT 1
      FROM public.user_roles AS role_row
      WHERE role_row.user_id = v_target_user_id
        AND role_row.role = 'admin'
    ) THEN
      RETURN NEW;
    END IF;
  ELSE
    RAISE EXCEPTION 'account_deletion_admin_removal_fence_unexpected_relation' USING ERRCODE = '55000';
  END IF;

  -- Share both G014 and legacy role/status locks so every removal, demotion,
  -- reservation, and final Auth cascade sees one available-admin snapshot.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-account-deletion-active-admin-guard', 0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('tzudong-admin-role-delete')
  );
  PERFORM 1
  FROM privacy_retention.account_deletion_admin_guard
  WHERE singleton
  FOR UPDATE;
  PERFORM 1 FROM public.user_roles AS role_row WHERE role_row.role = 'admin' FOR UPDATE;
  PERFORM 1
  FROM public.user_account_status AS status_row
  WHERE EXISTS (
    SELECT 1
    FROM public.user_roles AS role_row
    WHERE role_row.user_id = status_row.user_id
      AND role_row.role = 'admin'
  )
  FOR UPDATE;

  SELECT count(*) INTO v_available_active_admins
  FROM public.user_roles AS role_row
  LEFT JOIN public.user_account_status AS status_row
    ON status_row.user_id = role_row.user_id
  WHERE role_row.role = 'admin'
    AND role_row.user_id IS DISTINCT FROM v_target_user_id
    AND COALESCE(status_row.account_status, 'active') = 'active'
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.account_deletion_admin_reservations AS reservation
      WHERE reservation.target_user_id = role_row.user_id
        AND reservation.status = 'active'
    );
  IF v_available_active_admins < 1 THEN
    RAISE EXCEPTION 'account_deletion_admin_removal_available_admin_required' USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: account_deletion_reason_code_is_safe(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_reason_code_is_safe(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT p_value = ANY (ARRAY[
    'ACTOR_NOT_ALLOWED', 'ACTOR_OR_TARGET_REQUIRED', 'APPLIED', 'APPLY_NOT_STARTED',
    'APPLY_STARTED', 'AUTH_CLEANUP_FAILED', 'AUTH_READBACK_PASSED',
    'CONFIRMATION_REQUIRED', 'DB_AND_SESSION_READBACK_PASSED', 'DB_CLEANUP_FAILED',
    'DB_OR_SESSION_CLEANUP_FAILED', 'DB_READBACK_PASSED', 'IDEMPOTENCY_KEY_MISMATCH',
    'INVALID_APPLY_REQUEST', 'LAST_ADMIN_PROTECTED', 'LEGAL_HOLD_ACTIVE',
    'POLICY_CHANGED', 'POLICY_UNAVAILABLE', 'PREVIEW_CANCELLED', 'PREVIEW_EXPIRED',
    'PREVIEW_NOT_FOUND', 'PREVIEW_READY', 'REAUTH_REQUIRED', 'REPLAYED_PREVIEW',
    'RETENTION_POLICY_UNAVAILABLE', 'SESSION_READBACK_REQUIRED',
    'STORAGE_CLEANUP_FAILED', 'STORAGE_READBACK_PASSED'
  ]::text[]);
$$;


--
-- Name: privacy_audit_count_summary_is_safe(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_audit_count_summary_is_safe(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT pg_catalog.jsonb_typeof(p_value) = 'object'
    AND NOT EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_each(p_value) AS entry(key, value)
      WHERE entry.key NOT IN (
        'requested', 'created', 'updated', 'suppressed', 'failed', 'eligible',
        'guardianVerified', 'consentEvents', 'requiredConsent', 'retryCount',
        'transportAccepted', 'notificationSuppressedAfterAcceptance'
      )
         OR (
           pg_catalog.jsonb_typeof(entry.value) <> 'boolean'
           AND (
             pg_catalog.jsonb_typeof(entry.value) <> 'number'
             OR (entry.value #>> '{}') !~ '^(0|[1-9][0-9]{0,9})$'
           )
         )
    );
$_$;


--
-- Name: account_deletion_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_deletion_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_user_id uuid NOT NULL,
    target_user_id uuid NOT NULL,
    policy_version text NOT NULL,
    preview_hash text NOT NULL,
    preview_expires_at timestamp with time zone NOT NULL,
    reauthenticated_at timestamp with time zone NOT NULL,
    status text NOT NULL,
    idempotency_key text,
    reason_code text NOT NULL,
    count_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    db_readback_passed boolean DEFAULT false NOT NULL,
    storage_readback_passed boolean DEFAULT false NOT NULL,
    session_readback_passed boolean DEFAULT false NOT NULL,
    auth_readback_passed boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    applied_at timestamp with time zone,
    source_manifest_hash text NOT NULL,
    storage_receipts_hash text,
    auth_receipt_ref text,
    CONSTRAINT account_deletion_requests_auth_receipt_ref_check CHECK (((auth_receipt_ref IS NULL) OR (auth_receipt_ref ~ '^[A-Za-z0-9._:-]{8,256}$'::text))),
    CONSTRAINT account_deletion_requests_check CHECK (((actor_user_id <> target_user_id) OR (actor_user_id = target_user_id))),
    CONSTRAINT account_deletion_requests_check1 CHECK ((preview_expires_at > reauthenticated_at)),
    CONSTRAINT account_deletion_requests_check2 CHECK (((status <> 'applied'::text) OR (db_readback_passed AND storage_readback_passed AND session_readback_passed AND auth_readback_passed AND (applied_at IS NOT NULL)))),
    CONSTRAINT account_deletion_requests_count_summary_safe CHECK (public.privacy_audit_count_summary_is_safe(count_summary)),
    CONSTRAINT account_deletion_requests_idempotency_key_check CHECK (((idempotency_key IS NULL) OR (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'::text))),
    CONSTRAINT account_deletion_requests_preview_hash_check CHECK ((preview_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT account_deletion_requests_reason_code_allowed CHECK (public.account_deletion_reason_code_is_safe(reason_code)),
    CONSTRAINT account_deletion_requests_reason_code_check CHECK ((reason_code ~ '^[A-Z][A-Z0-9_]{0,63}$'::text)),
    CONSTRAINT account_deletion_requests_source_manifest_hash_check CHECK ((source_manifest_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT account_deletion_requests_storage_receipts_hash_check CHECK (((storage_receipts_hash IS NULL) OR (storage_receipts_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT g014_account_deletion_applied_receipt_check CHECK (((status <> 'applied'::text) OR ((db_readback_passed IS TRUE) AND (session_readback_passed IS TRUE) AND (storage_readback_passed IS TRUE) AND (auth_readback_passed IS TRUE) AND (applied_at IS NOT NULL) AND (auth_receipt_ref IS NOT NULL) AND (auth_receipt_ref ~ '^auth:[0-9a-f]{64}$'::text)))),
    CONSTRAINT g014_account_deletion_request_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'previewed'::text, 'applying'::text, 'applied'::text, 'partial'::text, 'failed'::text, 'expired'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.account_deletion_requests FORCE ROW LEVEL SECURITY;


--
-- Name: g014_account_deletion_append_audit(public.account_deletion_requests, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_append_audit(p_request public.account_deletion_requests, p_status text, p_reason_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_requested integer;
BEGIN
  SELECT COALESCE(sum(item.planned_count), 0)::integer INTO v_requested
  FROM public.account_deletion_request_items AS item
  WHERE item.request_id = p_request.id;
  -- The request binds actor/target immutably.  The retained audit is deliberately
  -- minimized: it stores only the subject hash produced by its trusted appender.
  RETURN privacy_retention.append_privacy_audit_event_internal(
    'account_deletion',
    NULL,
    p_request.target_user_id,
    p_request.id,
    p_request.id,
    p_status,
    p_reason_code,
    pg_catalog.jsonb_build_object('requested', v_requested),
    pg_catalog.jsonb_build_object('route', '/api/account/delete')
  );
END;
$$;


--
-- Name: g014_account_deletion_append_only(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME USING ERRCODE = '55000';
  RETURN OLD;
END;
$$;


--
-- Name: g014_account_deletion_apply_adapter(text, uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_apply_adapter(p_adapter_name text, p_request_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_registry privacy_retention.account_deletion_adapter_registry%ROWTYPE;
  v_evidence_count integer;
BEGIN
  IF p_adapter_name IS NULL OR p_request_id IS NULL OR p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'account_deletion_adapter_arguments_required' USING ERRCODE = '22004';
  END IF;
  SELECT * INTO v_registry
  FROM privacy_retention.account_deletion_adapter_registry
  WHERE adapter_name = p_adapter_name;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_unregistered_adapter: %', p_adapter_name USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);

  CASE p_adapter_name
    WHEN 'marketing_campaign_recipients_adapter' THEN
      PERFORM privacy_retention.g014_account_deletion_enable_evidence_cleanup(p_request_id, p_target_user_id);
      SELECT count(*) INTO v_evidence_count
      FROM privacy_retention.marketing_campaign_consent_evidence_keys
      WHERE user_id = p_target_user_id;
      INSERT INTO privacy_retention.account_deletion_evidence_separations (
        request_id, data_class_code, source_count, source_snapshot_hash
      ) VALUES (
        p_request_id, 'marketing_campaign_recipients', v_evidence_count,
        pg_catalog.encode(extensions.digest(
          pg_catalog.jsonb_build_object('class', 'marketing_campaign_recipients', 'count', v_evidence_count)::text,
          'sha256'
        ), 'hex')
      ) ON CONFLICT (request_id, data_class_code) DO NOTHING;
      DELETE FROM privacy_retention.marketing_campaign_consent_evidence_keys
      WHERE user_id = p_target_user_id;
      DELETE FROM privacy_retention.marketing_campaign_batch_recipients
      WHERE user_id = p_target_user_id;
      DELETE FROM public.notifications
      WHERE user_id = p_target_user_id;
      DELETE FROM public.marketing_campaign_recipients
      WHERE user_id = p_target_user_id;
      UPDATE public.marketing_campaign_operations
      SET actor_user_id = NULL
      WHERE actor_user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM privacy_retention.marketing_campaign_consent_evidence_keys WHERE user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM privacy_retention.marketing_campaign_batch_recipients WHERE user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM public.notifications WHERE user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM public.marketing_campaign_recipients WHERE user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM public.marketing_campaign_operations WHERE actor_user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_marketing_source_readback_failed' USING ERRCODE = '55000';
      END IF;

    WHEN 'notifications_adapter' THEN
      DELETE FROM public.notifications WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.notifications WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_notifications_source_readback_failed' USING ERRCODE = '55000';
      END IF;

    WHEN 'privacy_identity_adapter' THEN
      PERFORM privacy_retention.g014_account_deletion_enable_evidence_cleanup(p_request_id, p_target_user_id);
      SELECT count(*) INTO v_evidence_count
      FROM privacy_retention.privacy_consent_events
      WHERE user_id = p_target_user_id;
      INSERT INTO privacy_retention.account_deletion_evidence_separations (
        request_id, data_class_code, source_count, source_snapshot_hash
      ) VALUES (
        p_request_id, 'privacy_identity_records', v_evidence_count,
        pg_catalog.encode(extensions.digest(
          pg_catalog.jsonb_build_object('class', 'privacy_identity_records', 'count', v_evidence_count)::text,
          'sha256'
        ), 'hex')
      ) ON CONFLICT (request_id, data_class_code) DO NOTHING;
      DELETE FROM public.notifications AS notification
      USING privacy_retention.privacy_consent_events AS consent
      WHERE notification.consent_event_id = consent.id
        AND consent.user_id = p_target_user_id;
      DELETE FROM privacy_retention.marketing_campaign_consent_evidence_keys
      WHERE user_id = p_target_user_id;
      DELETE FROM privacy_retention.marketing_campaign_batch_recipients
      WHERE user_id = p_target_user_id;
      DELETE FROM privacy_retention.privacy_consent_events
      WHERE user_id = p_target_user_id;
      DELETE FROM privacy_retention.privacy_age_profiles
      WHERE user_id = p_target_user_id;
      DELETE FROM privacy_retention.privacy_guardian_verifications
      WHERE child_user_id = p_target_user_id;
      DELETE FROM privacy_retention.privacy_onboarding_challenges
      WHERE consumed_by_user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM privacy_retention.marketing_campaign_consent_evidence_keys WHERE user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM privacy_retention.privacy_consent_events WHERE user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM privacy_retention.privacy_age_profiles WHERE user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM privacy_retention.privacy_guardian_verifications WHERE child_user_id = p_target_user_id)
         OR EXISTS (SELECT 1 FROM privacy_retention.privacy_onboarding_challenges WHERE consumed_by_user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_privacy_source_readback_failed' USING ERRCODE = '55000';
      END IF;

    WHEN 'privacy_audit_adapter' THEN
      SELECT count(*) INTO v_evidence_count
      FROM privacy_retention.privacy_audit_events
      WHERE actor_user_id = p_target_user_id;
      INSERT INTO privacy_retention.account_deletion_evidence_separations (
        request_id, data_class_code, source_count, source_snapshot_hash
      ) VALUES (
        p_request_id, 'privacy_audit_actor_references', v_evidence_count,
        pg_catalog.encode(extensions.digest(
          pg_catalog.jsonb_build_object(
            'class', 'privacy_audit_actor_references',
            'count', v_evidence_count,
            'subjectHash', privacy_retention.g014_account_deletion_subject_hash(p_target_user_id)
          )::text,
          'sha256'
        ), 'hex')
      ) ON CONFLICT (request_id, data_class_code) DO NOTHING;
      -- Audit rows are append-only detached history.  Their immutable actor
      -- UUID is not live Auth attribution and must never be rewritten.
      IF EXISTS (
        SELECT 1
        FROM pg_catalog.pg_constraint AS constraint_row
        JOIN pg_catalog.pg_attribute AS attribute
          ON attribute.attrelid = constraint_row.conrelid
         AND attribute.attnum = ANY (constraint_row.conkey)
        WHERE constraint_row.conrelid = 'privacy_retention.privacy_audit_events'::regclass
          AND constraint_row.contype = 'f'
          AND constraint_row.confrelid = 'privacy_retention.g041_auth_users'::regclass
          AND attribute.attname = 'actor_user_id'
      ) OR (SELECT count(*)
            FROM privacy_retention.privacy_audit_events
            WHERE actor_user_id = p_target_user_id) IS DISTINCT FROM v_evidence_count THEN
        RAISE EXCEPTION 'account_deletion_audit_separation_readback_failed' USING ERRCODE = '55000';
      END IF;
      PERFORM privacy_retention.g014_account_deletion_append_audit(
        (SELECT request_row FROM public.account_deletion_requests AS request_row WHERE id = p_request_id),
        'readback_passed',
        'AUDIT_ACTOR_REFERENCE_SEPARATED'
      );

    WHEN 'approved_audit_adapter' THEN
      -- Retained approved history accepts detached immutable actor UUIDs.  Its
      -- readback is the absence of an Auth FK, not absence of historical rows.
      IF EXISTS (
        SELECT 1
        FROM pg_catalog.pg_constraint AS constraint_row
        JOIN pg_catalog.pg_attribute AS attribute
          ON attribute.attrelid = constraint_row.conrelid
         AND attribute.attnum = ANY (constraint_row.conkey)
        WHERE constraint_row.conrelid = 'privacy_retention.privacy_audit_events'::regclass
          AND constraint_row.contype = 'f'
          AND constraint_row.confrelid = 'privacy_retention.g041_auth_users'::regclass
          AND attribute.attname = 'actor_user_id'
      ) THEN
        RAISE EXCEPTION 'account_deletion_approved_audit_auth_fk_retained' USING ERRCODE = '55000';
      END IF;

    WHEN 'profile_identity_adapter' THEN
      UPDATE public.profiles
      SET nickname = '탈퇴한 사용자', username = NULL, avatar_url = NULL
      WHERE user_id = p_target_user_id;
      IF EXISTS (
        SELECT 1 FROM public.profiles
        WHERE user_id = p_target_user_id
          AND (nickname IS DISTINCT FROM '탈퇴한 사용자' OR username IS NOT NULL OR avatar_url IS NOT NULL)
      ) THEN
        RAISE EXCEPTION 'account_deletion_profile_source_readback_failed' USING ERRCODE = '55000';
      END IF;

    WHEN 'user_statistics_adapter' THEN
      DELETE FROM public.user_stats WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.user_stats WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_user_statistics_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'user_bookmarks_adapter' THEN
      DELETE FROM public.user_bookmarks WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.user_bookmarks WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_user_bookmarks_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'user_preferences_adapter' THEN
      DELETE FROM public.admin_user_preferences WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.admin_user_preferences WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_preferences_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'storyboard_documents_adapter' THEN
      DELETE FROM public.documents WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.documents WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_documents_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'review_likes_adapter' THEN
      DELETE FROM public.review_likes AS review_like
      WHERE review_like.user_id = p_target_user_id
         OR review_like.review_id IN (
           SELECT review.id FROM public.reviews AS review WHERE review.user_id = p_target_user_id
         );
      IF EXISTS (
        SELECT 1 FROM public.review_likes AS review_like
        WHERE review_like.user_id = p_target_user_id
           OR review_like.review_id IN (
             SELECT review.id FROM public.reviews AS review WHERE review.user_id = p_target_user_id
           )
      ) THEN
        RAISE EXCEPTION 'account_deletion_review_likes_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'reviews_adapter' THEN
      DELETE FROM public.reviews WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.reviews WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_reviews_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'submission_drafts_adapter', 'restaurant_submissions_adapter' THEN
      IF pg_catalog.to_regclass('public.restaurant_submission_items') IS NULL THEN
        RAISE EXCEPTION 'account_deletion_submission_child_relation_missing' USING ERRCODE = '55000';
      END IF;
      EXECUTE
        'DELETE FROM public.restaurant_submission_items AS item
           USING public.restaurant_submissions AS submission
         WHERE item.submission_id = submission.id
           AND submission.user_id = $1'
        USING p_target_user_id;
      DELETE FROM public.restaurant_submissions WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.restaurant_submissions WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_restaurant_submissions_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'restaurant_requests_adapter' THEN
      DELETE FROM public.restaurant_requests WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.restaurant_requests WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_restaurant_requests_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'ocr_logs_adapter' THEN
      DELETE FROM public.ocr_logs WHERE user_id = p_target_user_id;
      IF EXISTS (SELECT 1 FROM public.ocr_logs WHERE user_id = p_target_user_id) THEN
        RAISE EXCEPTION 'account_deletion_ocr_logs_source_readback_failed' USING ERRCODE = '55000';
      END IF;
    WHEN 'retention_work_items_adapter' THEN
      IF EXISTS (
        SELECT 1 FROM privacy_retention.privacy_retention_work_items
        WHERE subject_ref_hash = p_target_user_id::text
      ) THEN
        RAISE EXCEPTION 'account_deletion_retention_work_item_raw_subject_found' USING ERRCODE = '55000';
      END IF;
    WHEN 'storage_objects_adapter', 'auth_identity_adapter' THEN
      NULL;
    ELSE
      RAISE EXCEPTION 'account_deletion_unregistered_adapter: %', p_adapter_name USING ERRCODE = '55000';
  END CASE;
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
END;
$_$;


--
-- Name: g014_account_deletion_assert_actor_allowed(uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_assert_actor_allowed(p_actor_user_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_other_active_admins integer;
BEGIN
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'account_deletion_actor_and_target_required' USING ERRCODE = '22004';
  END IF;
  IF p_actor_user_id IS DISTINCT FROM p_target_user_id
     AND NOT privacy_retention.g014_account_deletion_is_active_admin(p_actor_user_id) THEN
    RAISE EXCEPTION 'account_deletion_actor_not_allowed' USING ERRCODE = '42501';
  END IF;

  -- The singleton serializes the final-admin calculation.  The row locks fence
  -- concurrent role/status changes even when different targets are deleted.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-account-deletion-active-admin-guard', 0)
  );
  PERFORM 1 FROM privacy_retention.account_deletion_admin_guard WHERE singleton FOR UPDATE;
  PERFORM 1 FROM public.user_roles AS role_row WHERE role_row.role = 'admin' FOR UPDATE;
  PERFORM 1
  FROM public.user_account_status AS status_row
  WHERE EXISTS (
    SELECT 1 FROM public.user_roles AS role_row
    WHERE role_row.user_id = status_row.user_id AND role_row.role = 'admin'
  )
  FOR UPDATE;

  IF privacy_retention.g014_account_deletion_is_active_admin(p_target_user_id) THEN
    SELECT count(*) INTO v_other_active_admins
    FROM public.user_roles AS role_row
    LEFT JOIN public.user_account_status AS status_row
      ON status_row.user_id = role_row.user_id
    WHERE role_row.role = 'admin'
      AND role_row.user_id IS DISTINCT FROM p_target_user_id
      AND COALESCE(status_row.account_status, 'active') = 'active'
      AND NOT EXISTS (
        SELECT 1
        FROM privacy_retention.account_deletion_admin_reservations AS reservation
        WHERE reservation.target_user_id = role_row.user_id
          AND reservation.status = 'active'
      );
    IF v_other_active_admins = 0 THEN
      RAISE EXCEPTION 'account_deletion_last_admin_protected' USING ERRCODE = '55000';
    END IF;
  END IF;
END;
$$;


--
-- Name: g014_account_deletion_assert_external_job_binding(uuid, uuid, uuid, text, text, text, text, uuid, boolean); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_assert_external_job_binding(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_phase text, p_attempt_token uuid, p_require_live_lease boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_attempt privacy_retention.account_deletion_external_job_attempts%ROWTYPE;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL OR p_phase IS NULL OR p_attempt_token IS NULL THEN
    RAISE EXCEPTION 'account_deletion_external_job_binding_arguments_required'
      USING ERRCODE = '22004';
  END IF;

  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);

  SELECT attempt.* INTO v_attempt
  FROM privacy_retention.account_deletion_external_job_attempts AS attempt
  JOIN privacy_retention.account_deletion_external_jobs AS job
    ON job.request_id = attempt.request_id AND job.phase = attempt.phase
  JOIN public.account_deletion_requests AS request_row
    ON request_row.id = job.request_id
  WHERE attempt.attempt_token = p_attempt_token
    AND job.request_id = p_request_id
    AND job.phase = p_phase
    AND job.actor_user_id = p_actor_user_id
    AND job.target_user_id = p_target_user_id
    AND job.preview_hash = p_preview_hash
    AND job.idempotency_key = p_idempotency_key
    AND job.source_manifest_hash = p_source_manifest_hash
    AND request_row.actor_user_id = p_actor_user_id
    AND request_row.target_user_id = p_target_user_id
    AND request_row.preview_hash = p_preview_hash
    AND request_row.idempotency_key = p_idempotency_key
    AND request_row.source_manifest_hash = p_source_manifest_hash
  FOR UPDATE OF attempt;

  IF NOT FOUND
     OR (
       p_require_live_lease
       AND v_attempt.state NOT IN ('leased', 'egress_unknown')
     )
     OR (
       NOT p_require_live_lease
       AND v_attempt.state NOT IN ('leased', 'egress_unknown', 'reconciliation_required', 'completed')
     ) THEN
    RAISE EXCEPTION 'account_deletion_external_job_attempt_binding_mismatch'
      USING ERRCODE = '55000';
  END IF;
  IF p_require_live_lease AND v_attempt.lease_expires_at <= pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_external_job_attempt_expired'
      USING ERRCODE = '55000';
  END IF;
END;
$$;


--
-- Name: g014_account_deletion_assert_external_job_predecessor(public.account_deletion_requests, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_assert_external_job_predecessor(p_request public.account_deletion_requests, p_phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_request.status NOT IN ('applying', 'partial')
     OR p_request.source_manifest_hash IS DISTINCT FROM
        privacy_retention.g014_account_deletion_validate_manifest(p_request.policy_version)
     OR (
       p_phase = 'session'
       AND (NOT p_request.db_readback_passed OR p_request.session_readback_passed)
     )
     OR (
       p_phase = 'storage'
       AND (
         NOT p_request.db_readback_passed
         OR NOT p_request.session_readback_passed
         OR p_request.storage_readback_passed
       )
     )
     OR (
       p_phase = 'auth'
       AND (
         NOT p_request.db_readback_passed
         OR NOT p_request.session_readback_passed
         OR NOT p_request.storage_readback_passed
         OR p_request.auth_readback_passed
       )
     ) THEN
    RAISE EXCEPTION 'account_deletion_external_job_predecessor_invalid'
      USING ERRCODE = '55000';
  END IF;
END;
$$;


--
-- Name: g014_account_deletion_assert_external_lease(uuid, uuid, text, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_assert_external_lease(p_request_id uuid, p_target_user_id uuid, p_phase text, p_lease_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_request_id IS NULL OR p_target_user_id IS NULL OR p_phase IS NULL OR p_lease_token IS NULL THEN
    RAISE EXCEPTION 'account_deletion_external_lease_arguments_required' USING ERRCODE = '22004';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  IF NOT EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_external_phase_leases AS lease_row
    WHERE lease_row.request_id = p_request_id
      AND lease_row.target_user_id = p_target_user_id
      AND lease_row.phase = p_phase
      AND lease_row.lease_token = p_lease_token
      AND lease_row.status = 'active'
      AND lease_row.lease_expires_at > pg_catalog.clock_timestamp()
  ) THEN
    RAISE EXCEPTION 'account_deletion_external_lease_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
END;
$$;


--
-- Name: g014_account_deletion_assert_final_items(uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_assert_final_items(p_request_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
  IF p_request_id IS NULL OR p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'account_deletion_final_item_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.account_deletion_request_items AS item
    WHERE item.request_id = p_request_id
      AND item.mandatory
      AND (
        (item.disposition IN ('delete', 'anonymize') AND item.status IS DISTINCT FROM 'applied')
        OR (item.disposition = 'separate' AND item.status IS DISTINCT FROM 'separated')
        OR (item.disposition = 'retain' AND item.status IS DISTINCT FROM 'retained')
      )
  ) THEN
    RAISE EXCEPTION 'account_deletion_final_item_state_invalid' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.account_deletion_request_items AS item
    JOIN public.account_deletion_requests AS request_row ON request_row.id = item.request_id
    JOIN privacy_retention.account_deletion_source_manifest AS manifest
      ON manifest.policy_version = request_row.policy_version
     AND manifest.code = item.data_class_code
    JOIN privacy_retention.account_deletion_adapter_registry AS registry
      ON registry.adapter_name = manifest.adapter_name
    WHERE item.request_id = p_request_id
      AND item.mandatory
      AND item.disposition = 'delete'
      AND item.data_class_code NOT IN ('storage_objects', 'auth_identity')
      AND privacy_retention.g014_account_deletion_source_count(
        manifest.relation_name,
        manifest.subject_column,
        CASE WHEN registry.subject_type = 'text'::regtype
          THEN privacy_retention.g014_account_deletion_subject_hash(p_target_user_id)
          ELSE p_target_user_id::text
        END
      ) <> 0
  ) THEN
    RAISE EXCEPTION 'account_deletion_final_source_readback_failed' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.profiles AS profile_row
    WHERE profile_row.user_id = p_target_user_id
      AND (
        profile_row.nickname IS DISTINCT FROM '탈퇴한 사용자'
        OR profile_row.username IS NOT NULL
        OR profile_row.avatar_url IS NOT NULL
      )
  ) THEN
    RAISE EXCEPTION 'account_deletion_final_anonymization_readback_failed' USING ERRCODE = '55000';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.account_deletion_requests AS request_row
    WHERE request_row.id = p_request_id
      AND request_row.storage_receipts_hash ~ '^[0-9a-f]{64}$'
      AND (
        SELECT count(*)
        FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
        WHERE proof.request_id = request_row.id AND proof.phase = 'storage'
      ) = (
        SELECT count(*)
        FROM privacy_retention.account_deletion_storage_objects
        WHERE request_id = request_row.id
      )
  ) THEN
    RAISE EXCEPTION 'account_deletion_final_storage_receipt_readback_failed' USING ERRCODE = '55000';
  END IF;
END;
$_$;


--
-- Name: g014_account_deletion_assert_no_hold(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_subject_hash text;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  v_subject_hash := privacy_retention.g014_account_deletion_subject_hash(p_target_user_id);
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_legal_holds AS hold_row
    JOIN privacy_retention.account_deletion_hold_class_map AS map_row
      ON map_row.hold_data_class = hold_row.data_class
    WHERE map_row.deletion_class = 'account_deletion'
      AND hold_row.subject_ref_hash = v_subject_hash
      AND hold_row.status = 'active'
      AND (hold_row.expires_at IS NULL OR hold_row.expires_at > pg_catalog.clock_timestamp())
  ) THEN
    RAISE EXCEPTION 'account_deletion_legal_hold_active' USING ERRCODE = '55000';
  END IF;
END;
$$;


--
-- Name: account_deletion_storage_objects; Type: TABLE; Schema: privacy_retention; Owner: -
--

CREATE TABLE privacy_retention.account_deletion_storage_objects (
    request_id uuid NOT NULL,
    object_locator_hash text NOT NULL,
    object_version_hash text NOT NULL,
    object_id uuid NOT NULL,
    object_version text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT account_deletion_storage_objects_object_locator_hash_check CHECK ((object_locator_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT account_deletion_storage_objects_object_version_check CHECK ((object_version ~ '^[A-Za-z0-9._:-]{1,256}$'::text)),
    CONSTRAINT account_deletion_storage_objects_object_version_hash_check CHECK ((object_version_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT g014_account_deletion_storage_object_identity_binding CHECK (((object_id IS NOT NULL) AND (object_version ~ '^[A-Za-z0-9._:-]{1,256}$'::text)))
);

ALTER TABLE ONLY privacy_retention.account_deletion_storage_objects FORCE ROW LEVEL SECURITY;


--
-- Name: g014_account_deletion_claim_storage_object(uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_claim_storage_object(p_request_id uuid, p_target_user_id uuid) RETURNS privacy_retention.account_deletion_storage_objects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_object storage.objects%ROWTYPE;
  v_captured privacy_retention.account_deletion_storage_objects%ROWTYPE;
  v_version text;
  v_version_hash text;
BEGIN
  SELECT object_row.* INTO v_object
  FROM storage.objects AS object_row
  WHERE object_row.owner_id::text = p_target_user_id::text
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.account_deletion_storage_objects AS captured
      JOIN privacy_retention.account_deletion_external_job_provider_proofs AS proof
        ON proof.request_id = captured.request_id
       AND proof.phase = 'storage'
       AND proof.object_locator_hash = captured.object_locator_hash
       AND proof.object_version_hash = captured.object_version_hash
       AND proof.object_id = captured.object_id
       AND proof.object_version = captured.object_version
      WHERE captured.request_id = p_request_id
        AND captured.object_id = object_row.id
        AND captured.object_version = pg_catalog.to_jsonb(object_row) ->> 'version'
    )
  ORDER BY object_row.id
  LIMIT 1
  FOR UPDATE OF object_row;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_version := pg_catalog.to_jsonb(v_object) ->> 'version';
  IF v_object.id IS NULL
     OR v_version !~ '^[A-Za-z0-9._:-]{1,256}$' THEN
    RAISE EXCEPTION 'account_deletion_storage_exact_identity_missing'
      USING ERRCODE = '55000';
  END IF;
  v_version_hash := pg_catalog.encode(
    extensions.digest(v_version, 'sha256'),
    'hex'
  );

  INSERT INTO privacy_retention.account_deletion_storage_objects (
    request_id, object_locator_hash, object_version_hash, object_id, object_version
  ) VALUES (
    p_request_id,
    pg_catalog.encode(
      extensions.digest(v_object.bucket_id::text || E'\n' || v_object.name::text, 'sha256'),
      'hex'
    ),
    v_version_hash,
    v_object.id,
    v_version
  )
  ON CONFLICT (request_id, object_id, object_version) DO NOTHING;

  SELECT * INTO v_captured
  FROM privacy_retention.account_deletion_storage_objects
  WHERE request_id = p_request_id
    AND object_id = v_object.id
    AND object_version = v_version
  FOR SHARE;

  IF NOT FOUND
     OR v_captured.object_version_hash IS DISTINCT FROM v_version_hash THEN
    RAISE EXCEPTION 'account_deletion_storage_manifest_version_mismatch'
      USING ERRCODE = '55000';
  END IF;

  RETURN v_captured;
END;
$_$;


--
-- Name: g014_account_deletion_complete_external_job_phase(uuid, text, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_complete_external_job_phase(p_request_id uuid, p_phase text, p_attempt_token uuid) RETURNS public.account_deletion_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_attempt privacy_retention.account_deletion_external_job_attempts%ROWTYPE;
  v_storage_receipts_hash text;
  v_auth_receipt_ref text;
  v_object_absent boolean;
  v_object_proved boolean;
  v_storage_absent boolean;
  v_missing_proof_count integer;
  v_storage_phase_complete boolean := false;
BEGIN
  SELECT * INTO v_request
  FROM public.account_deletion_requests
  WHERE id = p_request_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_external_job_request_missing' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_attempt
  FROM privacy_retention.account_deletion_external_job_attempts
  WHERE attempt_token = p_attempt_token
    AND request_id = p_request_id
    AND phase = p_phase
  FOR UPDATE;
  IF NOT FOUND
     OR v_attempt.state NOT IN ('leased', 'egress_unknown', 'reconciliation_required') THEN
    RAISE EXCEPTION 'account_deletion_external_job_attempt_completion_invalid'
      USING ERRCODE = '55000';
  END IF;

  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(v_request.target_user_id);

  IF p_phase = 'session' THEN
    UPDATE public.account_deletion_requests
    SET status = 'applying',
        reason_code = 'DB_AND_SESSION_READBACK_PASSED',
        session_readback_passed = true
    WHERE id = v_request.id
    RETURNING * INTO v_request;
    UPDATE privacy_retention.account_deletion_external_job_attempts
    SET state = 'completed', completed_at = pg_catalog.clock_timestamp()
    WHERE attempt_token = p_attempt_token
      AND state IN ('leased', 'egress_unknown', 'reconciliation_required');
    UPDATE privacy_retention.account_deletion_external_jobs
    SET state = 'completed',
        current_attempt_token = p_attempt_token,
        completed_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    WHERE request_id = v_request.id AND phase = p_phase;
  ELSIF p_phase = 'storage' THEN
    IF v_attempt.storage_object_locator_hash IS NOT NULL THEN
      SELECT NOT EXISTS (
        SELECT 1
        FROM storage.objects AS object_row
        WHERE object_row.owner_id::text = v_request.target_user_id::text
          AND object_row.id = v_attempt.storage_object_id
          AND pg_catalog.to_jsonb(object_row) ->> 'version'
              = v_attempt.storage_object_version
      ) INTO v_object_absent;
      SELECT EXISTS (
        SELECT 1
        FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
        WHERE proof.request_id = p_request_id
          AND proof.phase = 'storage'
          AND proof.attempt_token = p_attempt_token
          AND proof.object_locator_hash = v_attempt.storage_object_locator_hash
          AND proof.object_version_hash = v_attempt.storage_object_version_hash
          AND proof.object_id = v_attempt.storage_object_id
          AND proof.object_version = v_attempt.storage_object_version
      ) INTO v_object_proved;
      IF NOT v_object_absent OR NOT v_object_proved THEN
        RAISE EXCEPTION 'account_deletion_storage_subattempt_not_reconciled'
          USING ERRCODE = '55000';
      END IF;
    END IF;

    SELECT NOT EXISTS (
      SELECT 1 FROM storage.objects
      WHERE owner_id::text = v_request.target_user_id::text
    ) INTO v_storage_absent;
    SELECT count(*) INTO v_missing_proof_count
    FROM privacy_retention.account_deletion_storage_objects AS captured
    WHERE captured.request_id = p_request_id
      AND NOT EXISTS (
        SELECT 1
        FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
        WHERE proof.request_id = p_request_id
          AND proof.phase = 'storage'
          AND proof.object_locator_hash = captured.object_locator_hash
          AND proof.object_version_hash = captured.object_version_hash
          AND proof.object_id = captured.object_id
          AND proof.object_version = captured.object_version
      );

    IF NOT v_storage_absent OR v_missing_proof_count <> 0 THEN
      UPDATE privacy_retention.account_deletion_external_job_attempts
      SET state = 'completed', completed_at = pg_catalog.clock_timestamp()
      WHERE attempt_token = p_attempt_token
        AND state IN ('leased', 'egress_unknown', 'reconciliation_required');
      UPDATE privacy_retention.account_deletion_external_jobs
      SET state = 'pending',
          current_attempt_token = NULL,
          updated_at = pg_catalog.clock_timestamp()
      WHERE request_id = p_request_id
        AND phase = 'storage'
        AND current_attempt_token = p_attempt_token;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_deletion_storage_subattempt_completion_failed'
          USING ERRCODE = '55000';
      END IF;
    ELSE
      SELECT pg_catalog.encode(
        extensions.digest(
          COALESCE((
            SELECT pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object(
                'objectLocatorHash', proof.object_locator_hash,
                'objectVersionHash', proof.object_version_hash,
                'objectId', proof.object_id,
                'objectVersion', proof.object_version,
                'providerReceiptRef', proof.provider_receipt_ref,
                'providerReceiptHash', proof.provider_receipt_hash
              )
              ORDER BY proof.object_locator_hash, proof.object_version_hash
            )::text
            FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
            WHERE proof.request_id = v_request.id AND proof.phase = 'storage'
          ), '[]'),
          'sha256'
        ),
        'hex'
      ) INTO v_storage_receipts_hash;
      UPDATE public.account_deletion_request_items
      SET status = 'applied', reason_code = 'STORAGE_READBACK_PASSED'
      WHERE request_id = v_request.id AND data_class_code = 'storage_objects';
      UPDATE public.account_deletion_requests
      SET status = 'applying',
          reason_code = 'STORAGE_READBACK_PASSED',
          storage_readback_passed = true,
          storage_receipts_hash = v_storage_receipts_hash
      WHERE id = v_request.id
      RETURNING * INTO v_request;
      UPDATE privacy_retention.account_deletion_external_job_attempts
      SET state = 'completed', completed_at = pg_catalog.clock_timestamp()
      WHERE attempt_token = p_attempt_token
        AND state IN ('leased', 'egress_unknown', 'reconciliation_required');
      UPDATE privacy_retention.account_deletion_external_jobs
      SET state = 'completed',
          current_attempt_token = p_attempt_token,
          completed_at = pg_catalog.clock_timestamp(),
          updated_at = pg_catalog.clock_timestamp()
      WHERE request_id = v_request.id AND phase = p_phase;
      v_storage_phase_complete := true;
    END IF;
  ELSIF p_phase = 'auth' THEN
    SELECT NOT EXISTS (
      SELECT 1
      FROM storage.objects
      WHERE owner_id::text = v_request.target_user_id::text
    ) INTO v_storage_absent;
    IF NOT v_storage_absent THEN
      RAISE EXCEPTION 'account_deletion_auth_storage_authoritative_absence_failed'
        USING ERRCODE = '55000';
    END IF;
    UPDATE public.account_deletion_request_items
    SET status = 'applied', reason_code = 'AUTH_READBACK_PASSED'
    WHERE request_id = v_request.id AND data_class_code = 'auth_identity';
    PERFORM privacy_retention.g014_account_deletion_assert_final_items(
      v_request.id, v_request.target_user_id
    );
    v_auth_receipt_ref := 'auth:' || pg_catalog.encode(
      extensions.digest(
        pg_catalog.concat_ws(
          E'\n',
          v_request.id::text,
          v_request.target_user_id::text,
          v_request.source_manifest_hash,
          p_attempt_token::text,
          'authoritative_absent'
        ),
        'sha256'
      ),
      'hex'
    );
    UPDATE public.account_deletion_requests
    SET status = 'applied',
        reason_code = 'APPLIED',
        auth_readback_passed = true,
        auth_receipt_ref = v_auth_receipt_ref,
        applied_at = pg_catalog.clock_timestamp()
    WHERE id = v_request.id
    RETURNING * INTO v_request;
    UPDATE privacy_retention.account_deletion_admin_reservations
    SET status = 'completed', reconciled_at = pg_catalog.clock_timestamp()
    WHERE request_id = v_request.id AND status = 'active';
    UPDATE privacy_retention.account_deletion_external_job_attempts
    SET state = 'completed', completed_at = pg_catalog.clock_timestamp()
    WHERE attempt_token = p_attempt_token
      AND state IN ('leased', 'egress_unknown', 'reconciliation_required');
    UPDATE privacy_retention.account_deletion_external_jobs
    SET state = 'completed',
        current_attempt_token = p_attempt_token,
        completed_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    WHERE request_id = v_request.id AND phase = p_phase;
  ELSE
    RAISE EXCEPTION 'account_deletion_external_job_phase_invalid' USING ERRCODE = '22023';
  END IF;

  INSERT INTO privacy_retention.account_deletion_external_job_checkpoints (
    request_id, phase, attempt_token, checkpoint_kind, checkpoint_state, proof_hash
  ) VALUES (
    v_request.id, p_phase, p_attempt_token, 'authoritative_absent', 'confirmed',
    pg_catalog.encode(
      extensions.digest(
        pg_catalog.concat_ws(
          ':',
          'g014-authoritative-absent:v4',
          v_request.id::text,
          p_phase,
          p_attempt_token::text,
          COALESCE(v_attempt.storage_object_locator_hash, '<none>'),
          COALESCE(v_attempt.storage_object_version_hash, '<none>'),
          COALESCE(v_attempt.storage_object_id::text, '<none>'),
          COALESCE(v_attempt.storage_object_version, '<none>')
        ),
        'sha256'
      ),
      'hex'
    )
  )
  ON CONFLICT (request_id, phase, attempt_token, checkpoint_kind) DO NOTHING;

  IF p_phase <> 'storage' OR v_storage_phase_complete THEN
    PERFORM privacy_retention.g014_account_deletion_append_audit(
      v_request,
      CASE WHEN p_phase = 'auth' THEN 'applied' ELSE 'readback_passed' END,
      v_request.reason_code
    );
  END IF;
  RETURN v_request;
END;
$$;


--
-- Name: g014_account_deletion_enable_evidence_cleanup(uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_enable_evidence_cleanup(p_request_id uuid, p_target_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_lease privacy_retention.account_deletion_evidence_cleanup_leases%ROWTYPE;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
  IF NOT EXISTS (
    SELECT 1
    FROM public.account_deletion_requests AS request_row
    WHERE request_row.id = p_request_id
      AND request_row.target_user_id = p_target_user_id
      AND request_row.status IN ('applying', 'partial')
  ) THEN
    RAISE EXCEPTION 'account_deletion_evidence_cleanup_request_invalid' USING ERRCODE = '55000';
  END IF;
  UPDATE privacy_retention.account_deletion_evidence_cleanup_leases
  SET status = 'released', released_at = v_now
  WHERE request_id = p_request_id
    AND status = 'active'
    AND lease_expires_at <= v_now;
  INSERT INTO privacy_retention.account_deletion_evidence_cleanup_leases (
    request_id, target_user_id, lease_token, status, claimed_at, lease_expires_at
  ) VALUES (
    p_request_id, p_target_user_id, extensions.gen_random_uuid(),
    'active', v_now, v_now + interval '5 minutes'
  ) ON CONFLICT (request_id) DO UPDATE
    SET target_user_id = EXCLUDED.target_user_id,
        lease_token = EXCLUDED.lease_token,
        status = EXCLUDED.status,
        claimed_at = EXCLUDED.claimed_at,
        lease_expires_at = EXCLUDED.lease_expires_at,
        released_at = NULL
    WHERE privacy_retention.account_deletion_evidence_cleanup_leases.status = 'released';
  SELECT * INTO v_lease
  FROM privacy_retention.account_deletion_evidence_cleanup_leases
  WHERE request_id = p_request_id
    AND target_user_id = p_target_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_lease.status IS DISTINCT FROM 'active'
     OR v_lease.lease_expires_at <= pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_evidence_cleanup_lease_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM pg_catalog.set_config('app.account_deletion_request_id', p_request_id::text, true);
  PERFORM pg_catalog.set_config('app.account_deletion_target_user_id', p_target_user_id::text, true);
  PERFORM pg_catalog.set_config('app.account_deletion_evidence_cleanup', 'g014-v1', true);
  PERFORM pg_catalog.set_config('app.account_deletion_evidence_lease_token', v_lease.lease_token::text, true);
  RETURN v_lease.lease_token;
END;
$$;


--
-- Name: g014_account_deletion_evidence_cleanup_allowed(uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_evidence_cleanup_allowed(p_request_id uuid, p_target_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_request_id IS NULL
     OR p_target_user_id IS NULL
     OR pg_catalog.current_setting('app.account_deletion_request_id', true) IS DISTINCT FROM p_request_id::text
     OR pg_catalog.current_setting('app.account_deletion_target_user_id', true) IS DISTINCT FROM p_target_user_id::text
     OR pg_catalog.current_setting('app.account_deletion_evidence_cleanup', true) IS DISTINCT FROM 'g014-v1'
     OR pg_catalog.current_setting('app.account_deletion_evidence_lease_token', true) IS NULL THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1
    FROM public.account_deletion_requests AS request_row
    JOIN privacy_retention.account_deletion_evidence_cleanup_leases AS lease_row
      ON lease_row.request_id = request_row.id
     AND lease_row.target_user_id = request_row.target_user_id
    WHERE request_row.id = p_request_id
      AND request_row.target_user_id = p_target_user_id
      AND request_row.status IN ('applying', 'partial')
      AND lease_row.lease_token::text =
          pg_catalog.current_setting('app.account_deletion_evidence_lease_token', true)
      AND lease_row.status = 'active'
      AND lease_row.lease_expires_at > pg_catalog.clock_timestamp()
  ) AND NOT EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_legal_holds AS hold_row
    JOIN privacy_retention.account_deletion_hold_class_map AS map_row
      ON map_row.hold_data_class = hold_row.data_class
    WHERE map_row.deletion_class = 'account_deletion'
      AND hold_row.subject_ref_hash = privacy_retention.g014_account_deletion_subject_hash(p_target_user_id)
      AND hold_row.status = 'active'
      AND (hold_row.expires_at IS NULL OR hold_row.expires_at > pg_catalog.clock_timestamp())
  );
END;
$$;


--
-- Name: g014_account_deletion_external_attempt_binding_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_external_attempt_binding_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.attempt_token IS DISTINCT FROM OLD.attempt_token
     OR NEW.request_id IS DISTINCT FROM OLD.request_id
     OR NEW.phase IS DISTINCT FROM OLD.phase
     OR NEW.claimed_at IS DISTINCT FROM OLD.claimed_at
     OR NEW.lease_expires_at IS DISTINCT FROM OLD.lease_expires_at
     OR NEW.storage_object_locator_hash IS DISTINCT FROM OLD.storage_object_locator_hash
     OR NEW.storage_object_version_hash IS DISTINCT FROM OLD.storage_object_version_hash
     OR NEW.storage_object_id IS DISTINCT FROM OLD.storage_object_id
     OR NEW.storage_object_version IS DISTINCT FROM OLD.storage_object_version THEN
    RAISE EXCEPTION 'account_deletion_external_attempt_binding_immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_account_deletion_external_job_binding_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_external_job_binding_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.request_id IS DISTINCT FROM OLD.request_id
     OR NEW.phase IS DISTINCT FROM OLD.phase
     OR NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id
     OR NEW.target_user_id IS DISTINCT FROM OLD.target_user_id
     OR NEW.preview_hash IS DISTINCT FROM OLD.preview_hash
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.source_manifest_hash IS DISTINCT FROM OLD.source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_external_job_binding_immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_account_deletion_hold_subject_lock(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_hold_subject_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-account-deletion-target-hash:' || NEW.subject_ref_hash, 0)
  );

  IF NEW.status = 'active'
     AND (NEW.expires_at IS NULL OR NEW.expires_at > pg_catalog.clock_timestamp())
     AND EXISTS (
       SELECT 1
       FROM privacy_retention.account_deletion_hold_class_map AS hold_map
       WHERE hold_map.deletion_class = 'account_deletion'
         AND hold_map.hold_data_class = NEW.data_class
     )
     AND EXISTS (
       SELECT 1
       FROM privacy_retention.account_deletion_external_job_attempts AS attempt
       JOIN privacy_retention.account_deletion_external_jobs AS job
         ON job.request_id = attempt.request_id AND job.phase = attempt.phase
       WHERE attempt.state IN ('leased', 'egress_unknown', 'reconciliation_required')
         AND privacy_retention.g014_account_deletion_subject_hash(job.target_user_id)
             = NEW.subject_ref_hash
     ) THEN
    RAISE EXCEPTION 'account_deletion_external_job_blocks_hold_activation'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_account_deletion_is_active_admin(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_is_active_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles AS role_row
    LEFT JOIN public.user_account_status AS status_row
      ON status_row.user_id = role_row.user_id
    WHERE role_row.user_id = p_user_id
      AND role_row.role = 'admin'
      AND COALESCE(status_row.account_status, 'active') = 'active'
  );
$$;


--
-- Name: g014_account_deletion_item_binding_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_item_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.request_id IS DISTINCT FROM OLD.request_id
     OR NEW.data_class_code IS DISTINCT FROM OLD.data_class_code
     OR NEW.disposition IS DISTINCT FROM OLD.disposition
     OR NEW.mandatory IS DISTINCT FROM OLD.mandatory
     OR NEW.planned_count IS DISTINCT FROM OLD.planned_count THEN
    RAISE EXCEPTION 'account_deletion_item_binding_is_immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    (OLD.status = 'planned' AND NEW.status IN ('planned', 'applied', 'retained', 'separated', 'failed'))
    OR (OLD.status IN ('applied', 'retained', 'separated', 'failed') AND NEW.status = OLD.status)
  ) THEN
    RAISE EXCEPTION 'account_deletion_item_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_account_deletion_lock_target(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_lock_target(p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'account_deletion_target_required' USING ERRCODE = '22004';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'g014-account-deletion-target-hash:' ||
      privacy_retention.g014_account_deletion_subject_hash(p_target_user_id),
      0
    )
  );
END;
$$;


--
-- Name: g014_account_deletion_manifest_contract_hash(text, text, text, text, text, boolean, integer); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_manifest_contract_hash(p_policy_version text, p_code text, p_relation_name text, p_subject_column text, p_adapter_name text, p_required boolean, p_ordinal integer) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        ':',
        'g014-account-deletion-source-v2',
        p_policy_version,
        p_code,
        p_relation_name,
        p_subject_column,
        p_adapter_name,
        p_required::text,
        p_ordinal::text,
        COALESCE(registry.subject_type::text, '<missing>'),
        COALESCE(registry.expected_fk_relation, '<none>'),
        COALESCE(registry.expected_fk_column, '<none>'),
        COALESCE(registry.disposition, '<missing>'),
        COALESCE(registry.ordinal::text, '<missing>')
      ),
      'sha256'
    ),
    'hex'
  )
  FROM (SELECT 1) AS singleton
  LEFT JOIN privacy_retention.account_deletion_adapter_registry AS registry
    ON registry.adapter_name = p_adapter_name;
$$;


--
-- Name: g014_account_deletion_manifest_hash(text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_manifest_hash(p_policy_version text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      COALESCE(
        (
          SELECT pg_catalog.string_agg(
            pg_catalog.concat_ws(
              ':', manifest.policy_version, manifest.code, manifest.relation_name,
              manifest.subject_column, manifest.adapter_name, manifest.required::text,
              manifest.ordinal::text, manifest.contract_hash
            ),
            E'\n' ORDER BY manifest.ordinal, manifest.code
          )
          FROM privacy_retention.account_deletion_source_manifest AS manifest
          WHERE manifest.policy_version = p_policy_version
        ),
        ''
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_account_deletion_prevent_activated_class_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_prevent_activated_class_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_policy_activation_history AS history
    WHERE history.policy_version = CASE WHEN TG_OP = 'INSERT' THEN NEW.policy_version ELSE OLD.policy_version END
  ) THEN
    RAISE EXCEPTION 'ever_activated_account_deletion_class_is_immutable' USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: g014_account_deletion_prevent_activated_policy_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_prevent_activated_policy_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND EXISTS (
    SELECT 1 FROM privacy_retention.account_deletion_policy_activation_history
    WHERE policy_version = OLD.version
  ) THEN
    RAISE EXCEPTION 'ever_activated_account_deletion_policy_is_immutable' USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND EXISTS (
    SELECT 1 FROM privacy_retention.account_deletion_policy_activation_history
    WHERE policy_version = OLD.version
  ) AND NOT (
    OLD.status = 'active'
    AND NEW.status = 'disabled'
    AND NEW.version IS NOT DISTINCT FROM OLD.version
    AND NEW.preview_ttl IS NOT DISTINCT FROM OLD.preview_ttl
    AND NEW.reauth_max_age IS NOT DISTINCT FROM OLD.reauth_max_age
    AND NEW.confirmation_text IS NOT DISTINCT FROM OLD.confirmation_text
  ) THEN
    RAISE EXCEPTION 'ever_activated_account_deletion_policy_is_immutable' USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: g014_account_deletion_prevent_manifest_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_prevent_manifest_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_policy_activation_history AS history
    WHERE history.policy_version = CASE WHEN TG_OP = 'INSERT' THEN NEW.policy_version ELSE OLD.policy_version END
  ) THEN
    RAISE EXCEPTION 'ever_activated_account_deletion_manifest_is_immutable' USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: g014_account_deletion_provider_proof_lease_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_provider_proof_lease_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_external_phase_leases AS lease_row
    WHERE lease_row.request_id = NEW.request_id
      AND lease_row.target_user_id = NEW.target_user_id
      AND lease_row.phase = NEW.phase
      AND lease_row.lease_token = NEW.lease_token
      AND lease_row.status = 'active'
      AND lease_row.lease_expires_at > pg_catalog.clock_timestamp()
      AND NEW.verified_at >= lease_row.claimed_at
      AND NEW.verified_at <= lease_row.lease_expires_at
  ) THEN
    RAISE EXCEPTION 'account_deletion_provider_proof_lease_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_account_deletion_receipt_payload_hash(text, uuid, uuid, uuid, text, text, text, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_receipt_payload_hash(p_phase text, p_request_id uuid, p_actor_user_id uuid, p_target_user_id uuid, p_manifest_hash text, p_idempotency_key text, p_preview_hash text, p_lease_token uuid, p_provider_kind text, p_provider_receipt_ref text, p_provider_receipt_hash text, p_object_locator_hash text, p_object_version_hash text, p_predecessor_receipts_hash text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.jsonb_build_object(
        'phase', p_phase,
        'requestId', p_request_id,
        'actorUserId', p_actor_user_id,
        'targetUserId', p_target_user_id,
        'manifestHash', p_manifest_hash,
        'idempotencyKey', p_idempotency_key,
        'previewHash', p_preview_hash,
        'leaseToken', p_lease_token,
        'providerKind', p_provider_kind,
        'providerReceiptRef', p_provider_receipt_ref,
        'providerReceiptHash', p_provider_receipt_hash,
        'objectLocatorHash', p_object_locator_hash,
        'objectVersionHash', p_object_version_hash,
        'predecessorReceiptsHash', p_predecessor_receipts_hash
      )::text,
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_account_deletion_reconcile_expired_attempt(uuid, text, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_reconcile_expired_attempt(p_request_id uuid, p_phase text, p_attempt_token uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job privacy_retention.account_deletion_external_jobs%ROWTYPE;
  v_attempt privacy_retention.account_deletion_external_job_attempts%ROWTYPE;
  v_absent boolean;
  v_object_proved boolean;
  v_has_egress_unknown_checkpoint boolean;
  v_job_state text;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  SELECT * INTO v_job
  FROM privacy_retention.account_deletion_external_jobs
  WHERE request_id = p_request_id AND phase = p_phase
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_external_job_missing' USING ERRCODE = '55000';
  END IF;
  SELECT * INTO v_attempt
  FROM privacy_retention.account_deletion_external_job_attempts
  WHERE attempt_token = p_attempt_token
    AND request_id = p_request_id
    AND phase = p_phase
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_external_job_attempt_missing' USING ERRCODE = '55000';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_external_job_checkpoints AS checkpoint
    WHERE checkpoint.request_id = p_request_id
      AND checkpoint.phase = p_phase
      AND checkpoint.attempt_token = p_attempt_token
      AND checkpoint.checkpoint_kind = 'egress_unknown'
      AND checkpoint.checkpoint_state = 'unknown'
  ) INTO v_has_egress_unknown_checkpoint;

  IF v_attempt.state = 'leased' AND NOT v_has_egress_unknown_checkpoint THEN
    IF v_attempt.lease_expires_at > v_now THEN
      RAISE EXCEPTION 'account_deletion_external_job_attempt_not_expired'
        USING ERRCODE = '55000';
    END IF;
    UPDATE privacy_retention.account_deletion_external_job_attempts
    SET state = 'released', reconciled_at = v_now
    WHERE attempt_token = p_attempt_token
      AND state = 'leased';
    UPDATE privacy_retention.account_deletion_external_jobs
    SET state = 'pending',
        current_attempt_token = NULL,
        updated_at = v_now
    WHERE request_id = p_request_id
      AND phase = p_phase
      AND state = 'leased'
      AND current_attempt_token = p_attempt_token;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'account_deletion_external_job_release_failed'
        USING ERRCODE = '55000';
    END IF;
    RETURN 'released';
  END IF;

  IF v_attempt.state = 'egress_unknown' AND NOT v_has_egress_unknown_checkpoint THEN
    RAISE EXCEPTION 'account_deletion_external_job_egress_checkpoint_missing'
      USING ERRCODE = '55000';
  END IF;

  IF p_phase = 'storage' THEN
    IF v_attempt.storage_object_locator_hash IS NULL THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM storage.objects
        WHERE owner_id::text = v_job.target_user_id::text
      ) INTO v_absent;
      SELECT NOT EXISTS (
        SELECT 1
        FROM privacy_retention.account_deletion_storage_objects AS captured
        WHERE captured.request_id = p_request_id
          AND NOT EXISTS (
            SELECT 1
            FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
            WHERE proof.request_id = p_request_id
              AND proof.phase = 'storage'
              AND proof.object_locator_hash = captured.object_locator_hash
              AND proof.object_version_hash = captured.object_version_hash
              AND proof.object_id = captured.object_id
              AND proof.object_version = captured.object_version
          )
      ) INTO v_object_proved;
    ELSE
      SELECT NOT EXISTS (
        SELECT 1
        FROM storage.objects AS object_row
        WHERE object_row.owner_id::text = v_job.target_user_id::text
          AND object_row.id = v_attempt.storage_object_id
          AND pg_catalog.to_jsonb(object_row) ->> 'version'
              = v_attempt.storage_object_version
      ) INTO v_absent;
      SELECT EXISTS (
        SELECT 1
        FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
        WHERE proof.request_id = p_request_id
          AND proof.phase = 'storage'
          AND proof.attempt_token = p_attempt_token
          AND proof.object_locator_hash = v_attempt.storage_object_locator_hash
          AND proof.object_version_hash = v_attempt.storage_object_version_hash
          AND proof.object_id = v_attempt.storage_object_id
          AND proof.object_version = v_attempt.storage_object_version
      ) INTO v_object_proved;
    END IF;
    IF v_absent AND v_object_proved THEN
      PERFORM privacy_retention.g014_account_deletion_complete_external_job_phase(
        p_request_id, p_phase, p_attempt_token
      );
      SELECT state INTO v_job_state
      FROM privacy_retention.account_deletion_external_jobs
      WHERE request_id = p_request_id AND phase = p_phase;
      RETURN CASE WHEN v_job_state = 'completed' THEN 'completed' ELSE 'released' END;
    END IF;
  ELSIF p_phase = 'session' THEN
    SELECT NOT EXISTS (
      SELECT 1 FROM privacy_retention.g041_auth_sessions WHERE user_id = v_job.target_user_id
      UNION ALL
      SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens WHERE user_id = v_job.target_user_id
    ) INTO v_absent;
    IF v_absent THEN
      PERFORM privacy_retention.g014_account_deletion_complete_external_job_phase(
        p_request_id, p_phase, p_attempt_token
      );
      RETURN 'completed';
    END IF;
  ELSIF p_phase = 'auth' THEN
    SELECT NOT EXISTS (
      SELECT 1 FROM privacy_retention.g041_auth_users WHERE id = v_job.target_user_id
      UNION ALL SELECT 1 FROM privacy_retention.g041_auth_sessions WHERE user_id = v_job.target_user_id
      UNION ALL SELECT 1 FROM privacy_retention.g041_auth_identities WHERE user_id = v_job.target_user_id
      UNION ALL SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens WHERE user_id = v_job.target_user_id
    ) INTO v_absent;
    IF v_absent THEN
      PERFORM privacy_retention.g014_account_deletion_complete_external_job_phase(
        p_request_id, p_phase, p_attempt_token
      );
      RETURN 'completed';
    END IF;
  ELSE
    RAISE EXCEPTION 'account_deletion_external_job_phase_invalid' USING ERRCODE = '22023';
  END IF;

  UPDATE privacy_retention.account_deletion_external_job_attempts
  SET state = 'reconciliation_required', reconciled_at = v_now
  WHERE attempt_token = p_attempt_token
    AND state IN ('leased', 'egress_unknown');
  UPDATE privacy_retention.account_deletion_external_jobs
  SET state = 'reconciliation_required',
      current_attempt_token = p_attempt_token,
      updated_at = v_now
  WHERE request_id = p_request_id AND phase = p_phase;
  RETURN 'reconciliation_required';
END;
$$;


--
-- Name: g014_account_deletion_release_evidence_cleanup(uuid, uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_release_evidence_cleanup(p_request_id uuid, p_target_user_id uuid, p_lease_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_request_id IS NULL OR p_target_user_id IS NULL OR p_lease_token IS NULL THEN
    RAISE EXCEPTION 'account_deletion_evidence_cleanup_release_arguments_required' USING ERRCODE = '22004';
  END IF;
  UPDATE privacy_retention.account_deletion_evidence_cleanup_leases
  SET status = 'released', released_at = pg_catalog.clock_timestamp()
  WHERE request_id = p_request_id
    AND target_user_id = p_target_user_id
    AND lease_token = p_lease_token
    AND status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_evidence_cleanup_release_invalid' USING ERRCODE = '55000';
  END IF;
END;
$$;


--
-- Name: g014_account_deletion_request_binding_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_request_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
BEGIN
  IF NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id
     OR NEW.target_user_id IS DISTINCT FROM OLD.target_user_id
     OR NEW.policy_version IS DISTINCT FROM OLD.policy_version
     OR NEW.preview_hash IS DISTINCT FROM OLD.preview_hash
     OR NEW.preview_expires_at IS DISTINCT FROM OLD.preview_expires_at
     OR NEW.reauthenticated_at IS DISTINCT FROM OLD.reauthenticated_at
     OR NEW.source_manifest_hash IS DISTINCT FROM OLD.source_manifest_hash
     OR (OLD.idempotency_key IS NOT NULL AND NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key)
     OR (OLD.storage_receipts_hash IS NOT NULL AND NEW.storage_receipts_hash IS DISTINCT FROM OLD.storage_receipts_hash)
     OR (OLD.auth_receipt_ref IS NOT NULL AND NEW.auth_receipt_ref IS DISTINCT FROM OLD.auth_receipt_ref) THEN
    RAISE EXCEPTION 'account_deletion_request_binding_is_immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    (OLD.status = 'previewed' AND NEW.status IN ('previewed', 'applying', 'partial', 'expired', 'cancelled'))
    OR (OLD.status = 'applying' AND NEW.status IN ('applying', 'partial', 'applied'))
    OR (OLD.status = 'partial' AND NEW.status IN ('partial', 'applying', 'applied'))
    OR (OLD.status IN ('applied', 'expired', 'cancelled') AND NEW.status = OLD.status)
  ) THEN
    RAISE EXCEPTION 'account_deletion_predecessor_state_invalid' USING ERRCODE = '55000';
  END IF;
  IF NEW.status = 'applied' AND NOT (
    NEW.db_readback_passed AND NEW.session_readback_passed
    AND NEW.storage_readback_passed AND NEW.auth_readback_passed
    AND NEW.applied_at IS NOT NULL
    AND NEW.auth_receipt_ref IS NOT NULL
    AND NEW.auth_receipt_ref ~ '^auth:[0-9a-f]{64}$'
  ) THEN
    RAISE EXCEPTION 'account_deletion_applied_receipt_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: g014_account_deletion_require_service_role(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_require_service_role() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'account_deletion_service_role_required' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: g014_account_deletion_reserve_admin_slot(uuid, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_reserve_admin_slot(p_request_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_other_available_admins integer;
BEGIN
  IF p_request_id IS NULL OR p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'account_deletion_admin_reservation_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF NOT privacy_retention.g014_account_deletion_is_active_admin(p_target_user_id) THEN
    RETURN;
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-account-deletion-active-admin-guard', 0)
  );
  PERFORM 1 FROM privacy_retention.account_deletion_admin_guard WHERE singleton FOR UPDATE;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_admin_reservations AS reservation
    WHERE reservation.target_user_id = p_target_user_id
      AND reservation.status = 'active'
      AND reservation.request_id IS DISTINCT FROM p_request_id
  ) THEN
    RAISE EXCEPTION 'account_deletion_admin_reservation_conflict' USING ERRCODE = '55000';
  END IF;
  SELECT count(*) INTO v_other_available_admins
  FROM public.user_roles AS role_row
  LEFT JOIN public.user_account_status AS status_row ON status_row.user_id = role_row.user_id
  WHERE role_row.role = 'admin'
    AND role_row.user_id IS DISTINCT FROM p_target_user_id
    AND COALESCE(status_row.account_status, 'active') = 'active'
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.account_deletion_admin_reservations AS reservation
      WHERE reservation.target_user_id = role_row.user_id
        AND reservation.status = 'active'
    );
  IF v_other_available_admins = 0 THEN
    RAISE EXCEPTION 'account_deletion_last_admin_reservation_protected' USING ERRCODE = '55000';
  END IF;
  INSERT INTO privacy_retention.account_deletion_admin_reservations (
    request_id, target_user_id, status
  ) VALUES (
    p_request_id, p_target_user_id, 'active'
  ) ON CONFLICT (request_id) DO NOTHING;
END;
$$;


--
-- Name: g014_account_deletion_seed_external_jobs(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_seed_external_jobs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_phase text;
BEGIN
  IF NEW.status NOT IN ('applying', 'partial')
     OR NEW.actor_user_id IS NULL
     OR NEW.target_user_id IS NULL
     OR NEW.preview_hash IS NULL
     OR NEW.idempotency_key IS NULL
     OR NEW.source_manifest_hash IS NULL THEN
    RETURN NEW;
  END IF;

  FOREACH v_phase IN ARRAY ARRAY['session', 'storage', 'auth'] LOOP
    INSERT INTO privacy_retention.account_deletion_external_jobs (
      request_id, phase, actor_user_id, target_user_id, preview_hash,
      idempotency_key, source_manifest_hash
    ) VALUES (
      NEW.id, v_phase, NEW.actor_user_id, NEW.target_user_id, NEW.preview_hash,
      NEW.idempotency_key, NEW.source_manifest_hash
    )
    ON CONFLICT (request_id, phase) DO NOTHING;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: g014_account_deletion_source_count(text, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_source_count(p_relation_name text, p_subject_column text, p_subject_value text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_count integer;
  v_relation regclass;
BEGIN
  v_relation := pg_catalog.to_regclass(p_relation_name);
  IF v_relation IS NULL THEN
    RAISE EXCEPTION 'account_deletion_source_relation_missing: %', p_relation_name USING ERRCODE = '55000';
  END IF;
  EXECUTE pg_catalog.format(
    'SELECT count(*)::integer FROM %s WHERE %I::text = $1',
    v_relation,
    p_subject_column
  ) INTO v_count USING p_subject_value;
  RETURN v_count;
END;
$_$;


--
-- Name: g014_account_deletion_storage_receipt_refs(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_storage_receipt_refs(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT COALESCE(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'object_locator_hash', proof.object_locator_hash,
        'object_version_hash', proof.object_version_hash,
        'provider_receipt_ref', proof.provider_receipt_ref,
        'provider_receipt_hash', proof.provider_receipt_hash
      )
      ORDER BY proof.object_locator_hash
    ),
    '[]'::jsonb
  )
  FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
  WHERE proof.request_id = p_request_id
    AND proof.phase = 'storage';
$$;


--
-- Name: g014_account_deletion_storage_write_fence(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_storage_write_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_new_owner_id text := NEW.owner_id::text;
  v_old_owner_id text;
  v_object_id uuid := NEW.id;
  v_owner_id text;
  v_owner_uuid uuid;
  v_lifecycle_seen boolean;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_old_owner_id := OLD.owner_id::text;
    v_object_id := COALESCE(NEW.id, OLD.id);
  END IF;

  FOR v_owner_id IN
    SELECT DISTINCT owner_row.owner_id
    FROM (VALUES (v_new_owner_id), (v_old_owner_id)) AS owner_row(owner_id)
    WHERE owner_row.owner_id IS NOT NULL
      AND owner_row.owner_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ORDER BY owner_row.owner_id
  LOOP
    v_owner_uuid := v_owner_id::uuid;
    SELECT EXISTS (
      SELECT 1
      FROM public.account_deletion_requests AS request_row
      WHERE request_row.target_user_id = v_owner_uuid
        AND request_row.status IN ('previewed', 'applying', 'partial')
    ) INTO v_lifecycle_seen;

    PERFORM privacy_retention.g014_account_deletion_lock_target(v_owner_uuid);

    IF v_lifecycle_seen OR EXISTS (
      SELECT 1
      FROM public.account_deletion_requests AS request_row
      WHERE request_row.target_user_id = v_owner_uuid
        AND request_row.status IN ('previewed', 'applying', 'partial')
    ) THEN
      RAISE EXCEPTION 'account_deletion_storage_owner_write_fenced'
        USING ERRCODE = '55000';
    END IF;
  END LOOP;

  IF v_object_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_storage_objects AS captured
    JOIN privacy_retention.account_deletion_external_jobs AS job
      ON job.request_id = captured.request_id
     AND job.phase = 'storage'
    WHERE job.state IN ('pending', 'leased', 'egress_unknown', 'reconciliation_required')
      AND captured.object_id = v_object_id
  ) THEN
    RAISE EXCEPTION 'account_deletion_storage_object_write_fenced'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: g014_account_deletion_subject_hash(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_subject_hash(p_user_id uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest('privacy-subject:v1:' || p_user_id::text, 'sha256'),
    'hex'
  );
$$;


--
-- Name: g014_account_deletion_transition_preview_terminal(uuid, uuid, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_transition_preview_terminal(p_target_user_id uuid, p_request_id uuid, p_terminal_status text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_reason_code text;
BEGIN
  IF p_target_user_id IS NULL
     OR p_request_id IS NULL
     OR p_terminal_status NOT IN ('expired', 'cancelled') THEN
    RAISE EXCEPTION 'account_deletion_preview_terminal_arguments_invalid'
      USING ERRCODE = '22004';
  END IF;

  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  SELECT * INTO v_request
  FROM public.account_deletion_requests
  WHERE id = p_request_id
    AND target_user_id = p_target_user_id
  FOR UPDATE;
  IF NOT FOUND OR v_request.status <> 'previewed' THEN
    RETURN false;
  END IF;
  IF p_terminal_status = 'expired'
     AND v_request.preview_expires_at > pg_catalog.clock_timestamp() THEN
    RETURN false;
  END IF;

  v_reason_code := CASE p_terminal_status
    WHEN 'expired' THEN 'PREVIEW_EXPIRED'
    ELSE 'PREVIEW_CANCELLED'
  END;
  UPDATE public.account_deletion_requests
  SET status = p_terminal_status,
      reason_code = v_reason_code
  WHERE id = v_request.id
  RETURNING * INTO v_request;
  PERFORM privacy_retention.g014_account_deletion_append_audit(
    v_request, p_terminal_status, v_reason_code
  );
  RETURN true;
END;
$$;


--
-- Name: g014_account_deletion_validate_manifest(text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_account_deletion_validate_manifest(p_policy_version text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_manifest privacy_retention.account_deletion_source_manifest%ROWTYPE;
  v_registry privacy_retention.account_deletion_adapter_registry%ROWTYPE;
  v_class public.account_deletion_data_classes%ROWTYPE;
  v_relation regclass;
  v_attnum smallint;
  v_actual_type oid;
  v_expected_fk regclass;
  v_expected_fk_attnum smallint;
BEGIN
  IF p_policy_version IS NULL THEN
    RAISE EXCEPTION 'account_deletion_policy_version_required' USING ERRCODE = '22004';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.account_deletion_data_classes AS data_class
    FULL JOIN privacy_retention.account_deletion_source_manifest AS manifest
      ON manifest.policy_version = data_class.policy_version
     AND manifest.code = data_class.code
    WHERE COALESCE(data_class.policy_version, manifest.policy_version) = p_policy_version
      AND (
        data_class.code IS NULL
        OR manifest.code IS NULL
        OR manifest.required IS DISTINCT FROM data_class.mandatory
      )
  ) THEN
    RAISE EXCEPTION 'account_deletion_source_manifest_class_coverage_invalid' USING ERRCODE = '55000';
  END IF;

  FOR v_manifest IN
    SELECT *
    FROM privacy_retention.account_deletion_source_manifest
    WHERE policy_version = p_policy_version
    ORDER BY ordinal, code
  LOOP
    SELECT * INTO v_registry
    FROM privacy_retention.account_deletion_adapter_registry
    WHERE adapter_name = v_manifest.adapter_name;

    SELECT * INTO v_class
    FROM public.account_deletion_data_classes
    WHERE policy_version = p_policy_version
      AND code = v_manifest.code;

    IF NOT FOUND
       OR v_registry.code IS DISTINCT FROM v_manifest.code
       OR v_registry.relation_name IS DISTINCT FROM v_manifest.relation_name
       OR v_registry.subject_column IS DISTINCT FROM v_manifest.subject_column
       OR v_registry.disposition IS DISTINCT FROM v_class.disposition
       OR v_registry.ordinal IS DISTINCT FROM v_manifest.ordinal
       OR v_manifest.contract_hash IS DISTINCT FROM
          privacy_retention.g014_account_deletion_manifest_contract_hash(
            v_manifest.policy_version, v_manifest.code, v_manifest.relation_name,
            v_manifest.subject_column, v_manifest.adapter_name, v_manifest.required,
            v_manifest.ordinal
          ) THEN
      RAISE EXCEPTION 'account_deletion_source_manifest_adapter_contract_invalid: %',
        v_manifest.code USING ERRCODE = '55000';
    END IF;

    v_relation := pg_catalog.to_regclass(v_manifest.relation_name);
    IF v_relation IS NULL THEN
      RAISE EXCEPTION 'account_deletion_source_relation_missing: %',
        v_manifest.relation_name USING ERRCODE = '55000';
    END IF;
    SELECT attribute.attnum, attribute.atttypid
    INTO v_attnum, v_actual_type
    FROM pg_catalog.pg_attribute AS attribute
    WHERE attribute.attrelid = v_relation
      AND attribute.attname = v_manifest.subject_column
      AND attribute.attnum > 0
      AND NOT attribute.attisdropped;
    IF NOT FOUND OR v_actual_type IS DISTINCT FROM v_registry.subject_type::oid THEN
      RAISE EXCEPTION 'account_deletion_source_column_or_type_invalid: %.%',
        v_manifest.relation_name, v_manifest.subject_column USING ERRCODE = '55000';
    END IF;

    IF v_registry.expected_fk_relation IS NULL THEN
      IF EXISTS (
        SELECT 1
        FROM pg_catalog.pg_constraint AS constraint_row
        WHERE constraint_row.conrelid = v_relation
          AND constraint_row.contype = 'f'
          AND v_attnum = ANY (constraint_row.conkey)
      ) THEN
        RAISE EXCEPTION 'account_deletion_source_unexpected_fk: %.%',
          v_manifest.relation_name, v_manifest.subject_column USING ERRCODE = '55000';
      END IF;
    ELSE
      v_expected_fk := pg_catalog.to_regclass(v_registry.expected_fk_relation);
      IF v_expected_fk IS NULL THEN
        RAISE EXCEPTION 'account_deletion_source_fk_invalid: %.%',
          v_manifest.relation_name, v_manifest.subject_column USING ERRCODE = '55000';
      END IF;
      SELECT attribute.attnum INTO v_expected_fk_attnum
      FROM pg_catalog.pg_attribute AS attribute
      WHERE attribute.attrelid = v_expected_fk
        AND attribute.attname = v_registry.expected_fk_column
        AND attribute.attnum > 0
        AND NOT attribute.attisdropped;
      IF NOT FOUND
         OR (SELECT count(*)
             FROM pg_catalog.pg_constraint AS constraint_row
             WHERE constraint_row.conrelid = v_relation
               AND constraint_row.contype = 'f'
               AND v_attnum = ANY (constraint_row.conkey)) <> 1
         OR NOT EXISTS (
           SELECT 1
           FROM pg_catalog.pg_constraint AS constraint_row
           WHERE constraint_row.conrelid = v_relation
             AND constraint_row.contype = 'f'
             AND constraint_row.confrelid = v_expected_fk
             AND constraint_row.conkey = ARRAY[v_attnum]
             AND constraint_row.confkey = ARRAY[v_expected_fk_attnum]
         ) THEN
        RAISE EXCEPTION 'account_deletion_source_fk_invalid: %.%',
          v_manifest.relation_name, v_manifest.subject_column USING ERRCODE = '55000';
      END IF;
    END IF;
  END LOOP;

  IF NOT EXISTS (
    SELECT 1 FROM privacy_retention.account_deletion_source_manifest
    WHERE policy_version = p_policy_version
  ) THEN
    RAISE EXCEPTION 'account_deletion_source_manifest_missing' USING ERRCODE = '55000';
  END IF;
  RETURN privacy_retention.g014_account_deletion_manifest_hash(p_policy_version);
END;
$$;


--
-- Name: g014_catalog_manifest_rows(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_catalog_manifest_rows() RETURNS TABLE(manifest_kind text, manifest_key jsonb, manifest_value jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH protected_relation AS (
    SELECT * FROM privacy_retention.g014_catalog_protected_relations()
  ),
  relation_row AS (
    SELECT
      protected_relation.schema_name,
      protected_relation.relation_name,
      class_row.oid,
      class_row.relkind,
      class_row.relowner,
      class_row.relrowsecurity,
      class_row.relforcerowsecurity,
      class_row.relacl
    FROM protected_relation
    JOIN pg_catalog.pg_namespace AS namespace
      ON namespace.nspname = protected_relation.schema_name
    JOIN pg_catalog.pg_class AS class_row
      ON class_row.relnamespace = namespace.oid
     AND class_row.relname = protected_relation.relation_name
     AND class_row.relkind IN ('r', 'p')
  )
  SELECT
    'relation',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name
    ),
    pg_catalog.jsonb_build_object(
      'kind', relation_row.relkind,
      'owner', pg_catalog.pg_get_userbyid(relation_row.relowner),
      'rls_enabled', relation_row.relrowsecurity,
      'rls_forced', relation_row.relforcerowsecurity
    )
  FROM relation_row

  UNION ALL

  SELECT
    'column',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'column', attribute.attname
    ),
    pg_catalog.jsonb_build_object(
      'position', attribute.attnum,
      'type', pg_catalog.format_type(attribute.atttypid, attribute.atttypmod),
      'not_null', attribute.attnotnull,
      'default', COALESCE(
        pg_catalog.pg_get_expr(attribute_default.adbin, attribute_default.adrelid, false),
        ''
      ),
      'identity', attribute.attidentity,
      'generated', attribute.attgenerated
    )
  FROM relation_row
  JOIN pg_catalog.pg_attribute AS attribute
    ON attribute.attrelid = relation_row.oid
   AND attribute.attnum > 0
   AND NOT attribute.attisdropped
  LEFT JOIN pg_catalog.pg_attrdef AS attribute_default
    ON attribute_default.adrelid = attribute.attrelid
   AND attribute_default.adnum = attribute.attnum

  UNION ALL

  SELECT
    'column_grant',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'column', attribute.attname,
      'grantee', CASE
        WHEN acl.grantee = 0 THEN 'PUBLIC'
        ELSE pg_catalog.pg_get_userbyid(acl.grantee)
      END,
      'grantor', CASE
        WHEN acl.grantor = 0 THEN 'PUBLIC'
        ELSE pg_catalog.pg_get_userbyid(acl.grantor)
      END,
      'privilege', acl.privilege_type
    ),
    pg_catalog.jsonb_build_object('grantable', acl.is_grantable)
  FROM relation_row
  JOIN pg_catalog.pg_attribute AS attribute
    ON attribute.attrelid = relation_row.oid
   AND attribute.attnum > 0
   AND NOT attribute.attisdropped
  CROSS JOIN LATERAL pg_catalog.aclexplode(attribute.attacl) AS acl

  UNION ALL

  SELECT
    'policy',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'policy', policy_row.polname
    ),
    pg_catalog.jsonb_build_object(
      'command', policy_row.polcmd::text,
      'permissive', policy_row.polpermissive,
      'roles', COALESCE((
        SELECT pg_catalog.jsonb_agg(
          CASE
            WHEN policy_role.role_oid = 0 THEN 'PUBLIC'
            ELSE role_row.rolname
          END
          ORDER BY CASE
            WHEN policy_role.role_oid = 0 THEN 'PUBLIC'
            ELSE role_row.rolname
          END
        )
        FROM pg_catalog.unnest(policy_row.polroles) AS policy_role(role_oid)
        LEFT JOIN pg_catalog.pg_roles AS role_row ON role_row.oid = policy_role.role_oid
      ), '[]'::jsonb),
      'using', COALESCE(
        pg_catalog.pg_get_expr(policy_row.polqual, policy_row.polrelid, false),
        ''
      ),
      'with_check', COALESCE(
        pg_catalog.pg_get_expr(policy_row.polwithcheck, policy_row.polrelid, false),
        ''
      )
    )
  FROM relation_row
  JOIN pg_catalog.pg_policy AS policy_row ON policy_row.polrelid = relation_row.oid

  UNION ALL

  SELECT
    'grant',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'grantee', CASE
        WHEN acl.grantee = 0 THEN 'PUBLIC'
        ELSE pg_catalog.pg_get_userbyid(acl.grantee)
      END,
      'grantor', CASE
        WHEN acl.grantor = 0 THEN 'PUBLIC'
        ELSE pg_catalog.pg_get_userbyid(acl.grantor)
      END,
      'privilege', acl.privilege_type
    ),
    pg_catalog.jsonb_build_object('grantable', acl.is_grantable)
  FROM relation_row
  CROSS JOIN LATERAL pg_catalog.aclexplode(
    COALESCE(relation_row.relacl, pg_catalog.acldefault('r', relation_row.relowner))
  ) AS acl

  UNION ALL

  SELECT
    'constraint',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'constraint', constraint_row.conname
    ),
    pg_catalog.jsonb_build_object(
      'type', constraint_row.contype::text,
      'definition', pg_catalog.pg_get_constraintdef(constraint_row.oid, false),
      'validated', constraint_row.convalidated,
      'deferrable', constraint_row.condeferrable,
      'deferred', constraint_row.condeferred
    )
  FROM relation_row
  JOIN pg_catalog.pg_constraint AS constraint_row
    ON constraint_row.conrelid = relation_row.oid
   AND constraint_row.contype IN ('c', 'p', 'u', 'x')

  UNION ALL

  SELECT
    'foreign_key',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'constraint', foreign_key.conname
    ),
    pg_catalog.jsonb_build_object(
      'referenced_schema', referenced_namespace.nspname,
      'referenced_relation', referenced_relation.relname,
      'columns', COALESCE((
        SELECT pg_catalog.jsonb_agg(local_attribute.attname ORDER BY local_key.ordinality)
        FROM pg_catalog.unnest(foreign_key.conkey) WITH ORDINALITY
          AS local_key(attnum, ordinality)
        JOIN pg_catalog.pg_attribute AS local_attribute
          ON local_attribute.attrelid = foreign_key.conrelid
         AND local_attribute.attnum = local_key.attnum
      ), '[]'::jsonb),
      'referenced_columns', COALESCE((
        SELECT pg_catalog.jsonb_agg(referenced_attribute.attname ORDER BY referenced_key.ordinality)
        FROM pg_catalog.unnest(foreign_key.confkey) WITH ORDINALITY
          AS referenced_key(attnum, ordinality)
        JOIN pg_catalog.pg_attribute AS referenced_attribute
          ON referenced_attribute.attrelid = foreign_key.confrelid
         AND referenced_attribute.attnum = referenced_key.attnum
      ), '[]'::jsonb),
      'on_update', foreign_key.confupdtype::text,
      'on_delete', foreign_key.confdeltype::text,
      'match', foreign_key.confmatchtype::text,
      'validated', foreign_key.convalidated,
      'deferrable', foreign_key.condeferrable,
      'deferred', foreign_key.condeferred
    )
  FROM relation_row
  JOIN pg_catalog.pg_constraint AS foreign_key
    ON foreign_key.conrelid = relation_row.oid
   AND foreign_key.contype = 'f'
  JOIN pg_catalog.pg_class AS referenced_relation
    ON referenced_relation.oid = foreign_key.confrelid
  JOIN pg_catalog.pg_namespace AS referenced_namespace
    ON referenced_namespace.oid = referenced_relation.relnamespace

  UNION ALL

  SELECT
    'index',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'index', index_relation.relname,
      'index_schema', index_namespace.nspname
    ),
    pg_catalog.jsonb_build_object(
      'access_method', access_method.amname,
      'keys', COALESCE((
        SELECT pg_catalog.jsonb_agg(
          pg_catalog.pg_get_indexdef(index_relation.oid, key_position.key_number, false)
          ORDER BY key_position.ordinality
        )
        FROM pg_catalog.generate_series(1, index_row.indnkeyatts::integer)
          WITH ORDINALITY AS key_position(key_number, ordinality)
      ), '[]'::jsonb),
      'included_columns', COALESCE((
        SELECT pg_catalog.jsonb_agg(
          pg_catalog.pg_get_indexdef(index_relation.oid, include_position.key_number, false)
          ORDER BY include_position.ordinality
        )
        FROM pg_catalog.generate_series(
          index_row.indnkeyatts::integer + 1,
          index_row.indnatts::integer
        ) WITH ORDINALITY AS include_position(key_number, ordinality)
      ), '[]'::jsonb),
      'unique', index_row.indisunique,
      'primary', index_row.indisprimary,
      'valid', index_row.indisvalid,
      'predicate', COALESCE(
        pg_catalog.pg_get_expr(index_row.indpred, index_row.indrelid, false),
        ''
      )
    )
  FROM relation_row
  JOIN pg_catalog.pg_index AS index_row ON index_row.indrelid = relation_row.oid
  JOIN pg_catalog.pg_class AS index_relation ON index_relation.oid = index_row.indexrelid
  JOIN pg_catalog.pg_namespace AS index_namespace ON index_namespace.oid = index_relation.relnamespace
  JOIN pg_catalog.pg_am AS access_method ON access_method.oid = index_relation.relam

  UNION ALL

  SELECT
    'trigger',
    pg_catalog.jsonb_build_object(
      'schema', relation_row.schema_name,
      'relation', relation_row.relation_name,
      'trigger', trigger_row.tgname
    ),
    pg_catalog.jsonb_build_object(
      'timing', CASE
        WHEN trigger_row.tgtype & 2 <> 0 THEN 'BEFORE'
        WHEN trigger_row.tgtype & 64 <> 0 THEN 'INSTEAD OF'
        ELSE 'AFTER'
      END,
      'events', (
        SELECT COALESCE(
          pg_catalog.jsonb_agg(event_matrix.event_name ORDER BY event_matrix.sort_order),
          '[]'::jsonb
        )
        FROM (VALUES
          (1, 'INSERT', trigger_row.tgtype & 4 <> 0),
          (2, 'DELETE', trigger_row.tgtype & 8 <> 0),
          (3, 'UPDATE', trigger_row.tgtype & 16 <> 0),
          (4, 'TRUNCATE', trigger_row.tgtype & 32 <> 0)
        ) AS event_matrix(sort_order, event_name, enabled)
        WHERE event_matrix.enabled
      ),
      'level', CASE WHEN trigger_row.tgtype & 1 <> 0 THEN 'ROW' ELSE 'STATEMENT' END,
      'enabled', trigger_row.tgenabled::text,
      'function', pg_catalog.format(
        '%I.%I(%s)',
        function_namespace.nspname,
        function_row.proname,
        pg_catalog.pg_get_function_identity_arguments(function_row.oid)
      ),
      'definition', pg_catalog.pg_get_triggerdef(trigger_row.oid, false)
    )
  FROM relation_row
  JOIN pg_catalog.pg_trigger AS trigger_row
    ON trigger_row.tgrelid = relation_row.oid
   AND NOT trigger_row.tgisinternal
  JOIN pg_catalog.pg_proc AS function_row ON function_row.oid = trigger_row.tgfoid
  JOIN pg_catalog.pg_namespace AS function_namespace
    ON function_namespace.oid = function_row.pronamespace;
$$;


