--
-- Name: g014_confirm_privacy_onboarding_legacy(uuid, text, uuid, text, uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_confirm_privacy_onboarding_legacy(p_challenge_id uuid, p_challenge_token text, p_user_id uuid, p_source text, p_guardian_verification_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_challenge privacy_retention.privacy_onboarding_challenges%ROWTYPE;
  v_policy privacy_retention.privacy_policy_versions%ROWTYPE;
  v_audit_id uuid;
  v_existing_audit privacy_retention.privacy_audit_events%ROWTYPE;
  v_event_count integer := 0;
  v_status text;
  v_receipt_status text;
  v_error_code text;
  v_idempotency_prefix text;
  v_guardian privacy_retention.privacy_guardian_verifications%ROWTYPE;
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_challenge_id IS NULL
     OR p_user_id IS NULL
     OR p_challenge_token IS NULL
     OR pg_catalog.length(p_challenge_token) NOT BETWEEN 16 AND 512
     OR p_source IS NULL
     OR p_source NOT IN ('password_signup', 'oauth') THEN
    RAISE EXCEPTION 'privacy_onboarding_confirmation_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_challenge
  FROM privacy_retention.privacy_onboarding_challenges AS challenge
  WHERE challenge.id = p_challenge_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_challenge.token_hash IS DISTINCT FROM pg_catalog.encode(extensions.digest(p_challenge_token, 'sha256'), 'hex') THEN
    RAISE EXCEPTION 'privacy_onboarding_challenge_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_challenge.consumed_at IS NOT NULL THEN
    IF v_challenge.consumed_by_user_id IS DISTINCT FROM p_user_id THEN
      RAISE EXCEPTION 'privacy_onboarding_challenge_already_consumed' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_existing_audit
    FROM privacy_retention.privacy_audit_events AS audit
    WHERE audit.operation_id = p_challenge_id
      AND audit.event_type = 'onboarding_confirmed'
      AND audit.correlation_id = p_challenge_id
      AND audit.actor_user_id = p_user_id
    ORDER BY audit.created_at DESC, audit.id DESC
    LIMIT 1
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'privacy_onboarding_confirmation_audit_missing' USING ERRCODE = '55000';
    END IF;

    v_status := CASE v_challenge.age_band
      WHEN 'age_14_plus' THEN 'eligible'
      WHEN 'under_14' THEN 'guardian_pending'
      ELSE 'pending'
    END;
    v_receipt_status := CASE WHEN v_status = 'eligible' THEN 'applied' ELSE 'held' END;
    v_error_code := CASE
      WHEN v_status = 'guardian_pending' THEN 'PRIVACY_GUARDIAN_REQUIRED'
      WHEN v_status = 'pending' THEN 'PRIVACY_AGE_ATTESTATION_REQUIRED'
      ELSE NULL
    END;
    v_event_count := COALESCE((v_existing_audit.count_summary ->> 'consentEvents')::integer, -1);
    IF v_existing_audit.status IS DISTINCT FROM v_receipt_status
       OR v_existing_audit.reason_code IS DISTINCT FROM (
         CASE
           WHEN v_receipt_status = 'applied' THEN 'ONBOARDING_CONFIRMED'
           ELSE 'ONBOARDING_HELD'
         END
       )
       OR (v_challenge.age_band = 'age_14_plus' AND v_event_count < 1)
       OR (v_challenge.age_band <> 'age_14_plus' AND v_event_count <> 0) THEN
      RAISE EXCEPTION 'privacy_onboarding_confirmation_audit_invalid' USING ERRCODE = '55000';
    END IF;

    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'operationId', p_challenge_id::text,
      'challengeId', p_challenge_id::text,
      'userId', p_user_id::text,
      'policyVersionId', v_challenge.policy_version_id::text,
      'eligible', v_receipt_status = 'applied',
      'status', v_receipt_status,
      'readback', pg_catalog.jsonb_build_object(
        'passed', true,
        'checks', pg_catalog.jsonb_build_object(
          'challengeConsumed', true,
          'ageProfileRecorded', true,
          'requiredConsentRecorded', v_event_count > 0,
          'eligible', v_status = 'eligible'
        )
      ),
      'auditId', v_existing_audit.id::text,
      'errorCode', v_error_code,
      'ageStatus', v_status
    );
  END IF;
  IF v_challenge.expires_at <= pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'privacy_onboarding_challenge_expired' USING ERRCODE = 'P0002';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-policy-publication-state', 0)
  );

  SELECT * INTO v_policy
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.status = 'published'
    AND policy.effective_at <= pg_catalog.clock_timestamp()
  ORDER BY policy.effective_at DESC, policy.id DESC
  LIMIT 1;
  IF NOT FOUND OR v_policy.id IS DISTINCT FROM v_challenge.policy_version_id THEN
    RAISE EXCEPTION 'privacy_current_policy_required' USING ERRCODE = '23514';
  END IF;
  IF p_guardian_verification_id IS NOT NULL THEN
    IF v_challenge.age_band <> 'under_14' THEN
      RAISE EXCEPTION 'privacy_guardian_verification_not_applicable' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_guardian
    FROM privacy_retention.privacy_guardian_verifications AS guardian
    WHERE guardian.id = p_guardian_verification_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_guardian.child_user_id IS DISTINCT FROM p_user_id
       OR v_guardian.status <> 'verified'
       OR v_guardian.verified_at IS NULL
       OR v_guardian.verified_at > pg_catalog.clock_timestamp()
       OR v_guardian.expires_at IS NULL
       OR v_guardian.expires_at <= pg_catalog.clock_timestamp()
       OR v_guardian.withdrawn_at IS NOT NULL THEN
      RAISE EXCEPTION 'privacy_guardian_verification_required' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_age_profiles AS profile
    WHERE profile.user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'privacy_onboarding_already_confirmed' USING ERRCODE = '23505';
  END IF;

  v_status := CASE v_challenge.age_band
    WHEN 'age_14_plus' THEN 'eligible'
    WHEN 'under_14' THEN 'guardian_pending'
    ELSE 'pending'
  END;
  INSERT INTO privacy_retention.privacy_age_profiles (
    user_id,
    age_band,
    attested_at,
    method,
    status,
    policy_version_id
  ) VALUES (
    p_user_id,
    v_challenge.age_band,
    pg_catalog.clock_timestamp(),
    'self_attestation',
    v_status,
    v_challenge.policy_version_id
  );

  v_idempotency_prefix := 'onb' || pg_catalog.replace(p_challenge_id::text, '-', '');
  IF v_challenge.age_band = 'age_14_plus' THEN
    INSERT INTO privacy_retention.privacy_consent_events (
      user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
      source, correlation_id, idempotency_key
    ) VALUES (
      p_user_id, 'self', 'privacy_required', 'none', 'granted', v_policy.id, v_policy.content_sha256,
      p_source, p_challenge_id, v_idempotency_prefix || 'required'
    );
    v_event_count := v_event_count + 1;
    IF COALESCE((v_challenge.requested_consents ->> 'email')::boolean, false) THEN
      INSERT INTO privacy_retention.privacy_consent_events (
        user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
        source, correlation_id, idempotency_key
      ) VALUES (
        p_user_id, 'self', 'email_marketing', 'email', 'granted', v_policy.id, v_policy.content_sha256,
        p_source, p_challenge_id, v_idempotency_prefix || 'email'
      );
      v_event_count := v_event_count + 1;
    END IF;
    IF COALESCE((v_challenge.requested_consents ->> 'sms')::boolean, false) THEN
      INSERT INTO privacy_retention.privacy_consent_events (
        user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
        source, correlation_id, idempotency_key
      ) VALUES (
        p_user_id, 'self', 'sms_marketing', 'sms', 'granted', v_policy.id, v_policy.content_sha256,
        p_source, p_challenge_id, v_idempotency_prefix || 'sms'
      );
      v_event_count := v_event_count + 1;
    END IF;
    IF COALESCE((v_challenge.requested_consents ->> 'push')::boolean, false) THEN
      INSERT INTO privacy_retention.privacy_consent_events (
        user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
        source, correlation_id, idempotency_key
      ) VALUES (
        p_user_id, 'self', 'push_marketing', 'push', 'granted', v_policy.id, v_policy.content_sha256,
        p_source, p_challenge_id, v_idempotency_prefix || 'push'
      );
      v_event_count := v_event_count + 1;
    END IF;
    IF COALESCE((v_challenge.requested_consents ->> 'night_email')::boolean, false) THEN
      INSERT INTO privacy_retention.privacy_consent_events (
        user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
        source, correlation_id, idempotency_key
      ) VALUES (
        p_user_id, 'self', 'night_marketing', 'email', 'granted', v_policy.id, v_policy.content_sha256,
        p_source, p_challenge_id, v_idempotency_prefix || 'nightemail'
      );
      v_event_count := v_event_count + 1;
    END IF;
    IF COALESCE((v_challenge.requested_consents ->> 'night_sms')::boolean, false) THEN
      INSERT INTO privacy_retention.privacy_consent_events (
        user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
        source, correlation_id, idempotency_key
      ) VALUES (
        p_user_id, 'self', 'night_marketing', 'sms', 'granted', v_policy.id, v_policy.content_sha256,
        p_source, p_challenge_id, v_idempotency_prefix || 'nightsms'
      );
      v_event_count := v_event_count + 1;
    END IF;
    IF COALESCE((v_challenge.requested_consents ->> 'night_push')::boolean, false) THEN
      INSERT INTO privacy_retention.privacy_consent_events (
        user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
        source, correlation_id, idempotency_key
      ) VALUES (
        p_user_id, 'self', 'night_marketing', 'push', 'granted', v_policy.id, v_policy.content_sha256,
        p_source, p_challenge_id, v_idempotency_prefix || 'nightpush'
      );
      v_event_count := v_event_count + 1;
    END IF;
  END IF;

  UPDATE privacy_retention.privacy_onboarding_challenges AS challenge
  SET consumed_at = pg_catalog.clock_timestamp(),
      consumed_by_user_id = p_user_id
  WHERE challenge.id = p_challenge_id
    AND challenge.consumed_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'privacy_onboarding_transition_invalid' USING ERRCODE = '55000';
  END IF;

  SELECT profile.status INTO v_status
  FROM privacy_retention.privacy_age_profiles AS profile
  WHERE profile.user_id = p_user_id;
  v_receipt_status := CASE WHEN v_status IN ('eligible', 'guardian_verified') THEN 'applied' ELSE 'held' END;
  v_error_code := CASE
    WHEN v_status IN ('guardian_pending', 'guardian_withdrawn') THEN 'PRIVACY_GUARDIAN_REQUIRED'
    WHEN v_status IN ('pending', 'blocked') THEN 'PRIVACY_AGE_ATTESTATION_REQUIRED'
    ELSE NULL
  END;
  v_audit_id := privacy_retention.append_privacy_audit_event_internal(
    'onboarding_confirmed',
    p_user_id,
    p_user_id,
    p_challenge_id,
    p_challenge_id,
    v_receipt_status,
    CASE WHEN v_receipt_status = 'applied' THEN 'ONBOARDING_CONFIRMED' ELSE 'ONBOARDING_HELD' END,
    pg_catalog.jsonb_build_object('consentEvents', v_event_count, 'eligible', v_receipt_status = 'applied'),
    pg_catalog.jsonb_build_object('route', '/api/privacy/onboarding')
  );
  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'operationId', p_challenge_id::text,
    'challengeId', p_challenge_id::text,
    'userId', p_user_id::text,
    'policyVersionId', v_challenge.policy_version_id::text,
    'eligible', v_receipt_status = 'applied',
    'status', v_receipt_status,
    'readback', pg_catalog.jsonb_build_object(
      'passed', true,
      'checks', pg_catalog.jsonb_build_object(
        'challengeConsumed', true,
        'ageProfileRecorded', true,
        'requiredConsentRecorded', v_event_count > 0,
        'eligible', v_status IN ('eligible', 'guardian_verified')
      )
    ),
    'auditId', v_audit_id::text,
    'errorCode', v_error_code,
    'ageStatus', v_status
  );
END;
$$;


--
-- Name: g014_marketing_accepted_recipient_digest(uuid[]); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_accepted_recipient_digest(p_user_ids uuid[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      COALESCE(
        pg_catalog.array_to_string(
          privacy_retention.g014_marketing_canonical_recipient_ids(p_user_ids),
          ','
        ),
        ''
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_marketing_batch_recipient_transition(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_batch_recipient_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('eligible', 'suppressed')
       OR NEW.provider_accepted_at IS NOT NULL
       OR NEW.notification_eligibility_outcome IS DISTINCT FROM 'not_applicable' THEN
      RAISE EXCEPTION 'marketing_batch_recipient_initial_state_invalid' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.batch_id IS DISTINCT FROM OLD.batch_id
     OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR (
       OLD.provider_accepted_at IS NOT NULL
       AND NEW.provider_accepted_at IS DISTINCT FROM OLD.provider_accepted_at
     )
     OR (
       OLD.notification_eligibility_outcome IS DISTINCT FROM 'not_applicable'
       AND NEW.notification_eligibility_outcome IS DISTINCT FROM OLD.notification_eligibility_outcome
     )
     OR (
       OLD.provider_accepted_at IS NULL
       AND NEW.provider_accepted_at IS NOT NULL
       AND OLD.status IS DISTINCT FROM 'claimed'
     )
     OR NOT (
       (OLD.status = 'eligible' AND NEW.status IN ('claimed', 'suppressed', 'failed'))
       OR (OLD.status = 'claimed' AND NEW.status IN ('sent', 'suppressed', 'failed'))
       OR NEW.status IS NOT DISTINCT FROM OLD.status
     ) THEN
    RAISE EXCEPTION 'marketing_batch_recipient_transition_invalid' USING ERRCODE = '23514';
  END IF;
  IF NEW.provider_accepted_at IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM privacy_retention.marketing_campaign_provider_attempts AS attempt
       WHERE attempt.operation_id = NEW.operation_id
         AND attempt.batch_id = NEW.batch_id
         AND attempt.claim_token = NEW.claim_token
         AND attempt.status = 'accepted'
         AND NEW.user_id = ANY (attempt.accepted_recipient_ids)
     ) THEN
    RAISE EXCEPTION 'marketing_batch_recipient_transport_binding_invalid' USING ERRCODE = '23514';
  END IF;
  IF NEW.ordinary_consent_event_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM privacy_retention.privacy_consent_events AS event
       WHERE event.id = NEW.ordinary_consent_event_id
         AND event.user_id = NEW.user_id
         AND event.subject_kind IS NOT DISTINCT FROM NEW.ordinary_subject_kind
         AND event.guardian_verification_id IS NOT DISTINCT FROM NEW.ordinary_guardian_verification_id
         AND event.purpose IS NOT DISTINCT FROM NEW.ordinary_purpose
         AND event.channel IS NOT DISTINCT FROM NEW.ordinary_channel
         AND event.decision IS NOT DISTINCT FROM NEW.ordinary_decision
         AND event.policy_version_id IS NOT DISTINCT FROM NEW.ordinary_policy_version_id
         AND event.notice_sha256 IS NOT DISTINCT FROM NEW.ordinary_notice_sha256
         AND event.decision = 'granted'
     ) THEN
    RAISE EXCEPTION 'marketing_ordinary_consent_binding_invalid' USING ERRCODE = '23514';
  END IF;
  IF NEW.night_consent_event_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM privacy_retention.privacy_consent_events AS event
       WHERE event.id = NEW.night_consent_event_id
         AND event.user_id = NEW.user_id
         AND event.subject_kind IS NOT DISTINCT FROM NEW.night_subject_kind
         AND event.guardian_verification_id IS NOT DISTINCT FROM NEW.night_guardian_verification_id
         AND event.purpose IS NOT DISTINCT FROM NEW.night_purpose
         AND event.channel IS NOT DISTINCT FROM NEW.night_channel
         AND event.decision IS NOT DISTINCT FROM NEW.night_decision
         AND event.policy_version_id IS NOT DISTINCT FROM NEW.night_policy_version_id
         AND event.notice_sha256 IS NOT DISTINCT FROM NEW.night_notice_sha256
         AND event.decision = 'granted'
     ) THEN
    RAISE EXCEPTION 'marketing_night_consent_binding_invalid' USING ERRCODE = '23514';
  END IF;
  NEW.updated_at := pg_catalog.clock_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: g014_marketing_canonical_recipient_ids(uuid[]); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_canonical_recipient_ids(p_user_ids uuid[]) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT COALESCE(
    pg_catalog.array_agg(DISTINCT recipient.user_id ORDER BY recipient.user_id),
    ARRAY[]::uuid[]
  )
  FROM pg_catalog.unnest(p_user_ids) AS recipient(user_id);
$$;


--
-- Name: g014_marketing_consent_evidence_binding(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_consent_evidence_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.decision IS DISTINCT FROM 'granted'
     OR NOT EXISTS (
       SELECT 1
       FROM privacy_retention.privacy_consent_events AS event
       WHERE event.id = NEW.consent_event_id
         AND event.user_id = NEW.user_id
         AND event.subject_kind IS NOT DISTINCT FROM NEW.subject_kind
         AND event.guardian_verification_id IS NOT DISTINCT FROM NEW.guardian_verification_id
         AND event.purpose IS NOT DISTINCT FROM NEW.purpose
         AND event.channel IS NOT DISTINCT FROM NEW.channel
         AND event.decision IS NOT DISTINCT FROM NEW.decision
         AND event.policy_version_id IS NOT DISTINCT FROM NEW.policy_version_id
         AND event.notice_sha256 IS NOT DISTINCT FROM NEW.notice_sha256
         AND event.decision = 'granted'
     ) THEN
    RAISE EXCEPTION 'marketing_consent_evidence_binding_invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_marketing_permission_evidence(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_permission_evidence(p_user_id uuid, p_channel text, p_scheduled_at timestamp with time zone, p_timezone text) RETURNS TABLE(allowed boolean, reason_code text, ordinary_consent_event_id uuid, night_consent_event_id uuid, subject_kind text, guardian_verification_id uuid, policy_version_id uuid, policy_content_sha256 text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_policy privacy_retention.privacy_policy_versions%ROWTYPE;
  v_profile privacy_retention.privacy_age_profiles%ROWTYPE;
  v_ordinary privacy_retention.privacy_consent_events%ROWTYPE;
  v_night privacy_retention.privacy_consent_events%ROWTYPE;
  v_guardian_id uuid;
  v_eligibility jsonb;
  v_subject_kind text;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  IF p_user_id IS NULL
     OR p_channel IS NULL
     OR p_channel NOT IN ('email', 'sms', 'push')
     OR p_scheduled_at IS NULL
     OR p_timezone IS DISTINCT FROM 'Asia/Seoul' THEN
    RAISE EXCEPTION 'marketing_permission_input_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_policy
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.status = 'published'
    AND policy.effective_at <= v_now
  ORDER BY policy.effective_at DESC, policy.id DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'privacy_policy_unavailable'::text, NULL::uuid, NULL::uuid,
      NULL::text, NULL::uuid, NULL::uuid, NULL::text;
    RETURN;
  END IF;

  v_eligibility := privacy_retention.g014_privacy_eligibility_receipt(p_user_id);
  IF COALESCE((v_eligibility ->> 'eligible')::boolean, false) IS DISTINCT FROM true
     OR (v_eligibility ->> 'policyVersionId') IS DISTINCT FROM v_policy.id::text
     OR (v_eligibility ->> 'contentSha256') IS DISTINCT FROM v_policy.content_sha256 THEN
    RETURN QUERY SELECT false, 'privacy_eligibility_required'::text, NULL::uuid, NULL::uuid,
      NULL::text, NULL::uuid, v_policy.id, v_policy.content_sha256;
    RETURN;
  END IF;

  SELECT * INTO v_profile
  FROM privacy_retention.privacy_age_profiles AS profile
  WHERE profile.user_id = p_user_id;
  IF NOT FOUND OR v_profile.policy_version_id IS DISTINCT FROM v_policy.id THEN
    RETURN QUERY SELECT false, 'privacy_eligibility_required'::text, NULL::uuid, NULL::uuid,
      NULL::text, NULL::uuid, v_policy.id, v_policy.content_sha256;
    RETURN;
  END IF;

  IF v_profile.age_band = 'under_14' THEN
    v_subject_kind := 'child';
    SELECT guardian.id INTO v_guardian_id
    FROM privacy_retention.privacy_guardian_verifications AS guardian
    WHERE guardian.child_user_id = p_user_id
      AND guardian.status = 'verified'
      AND guardian.verified_at IS NOT NULL
      AND guardian.verified_at <= v_now
      AND guardian.expires_at IS NOT NULL
      AND guardian.expires_at > v_now
      AND guardian.withdrawn_at IS NULL
    ORDER BY guardian.updated_at DESC, guardian.id DESC
    LIMIT 1;
    IF v_guardian_id IS NULL THEN
      RETURN QUERY SELECT false, 'guardian_eligibility_required'::text, NULL::uuid, NULL::uuid,
        v_subject_kind, NULL::uuid, v_policy.id, v_policy.content_sha256;
      RETURN;
    END IF;
  ELSIF v_profile.age_band = 'age_14_plus' AND v_profile.status = 'eligible' THEN
    v_subject_kind := 'self';
    v_guardian_id := NULL;
  ELSE
    RETURN QUERY SELECT false, 'privacy_eligibility_required'::text, NULL::uuid, NULL::uuid,
      NULL::text, NULL::uuid, v_policy.id, v_policy.content_sha256;
    RETURN;
  END IF;

  SELECT * INTO v_ordinary
  FROM privacy_retention.privacy_consent_events AS event
  WHERE event.user_id = p_user_id
    AND event.subject_kind = v_subject_kind
    AND event.guardian_verification_id IS NOT DISTINCT FROM v_guardian_id
    AND event.purpose = p_channel || '_marketing'
    AND event.channel = p_channel
    AND event.occurred_at <= v_now
  ORDER BY event.occurred_at DESC, event.id DESC
  LIMIT 1;
  IF NOT FOUND OR v_ordinary.decision IS DISTINCT FROM 'granted' THEN
    RETURN QUERY SELECT false, 'ordinary_consent_missing'::text, NULL::uuid, NULL::uuid,
      v_subject_kind, v_guardian_id, v_policy.id, v_policy.content_sha256;
    RETURN;
  END IF;
  IF v_ordinary.policy_version_id IS DISTINCT FROM v_policy.id
     OR v_ordinary.notice_sha256 IS DISTINCT FROM v_policy.content_sha256 THEN
    RETURN QUERY SELECT false, 'ordinary_consent_stale'::text, NULL::uuid, NULL::uuid,
      v_subject_kind, v_guardian_id, v_policy.id, v_policy.content_sha256;
    RETURN;
  END IF;

  IF p_channel <> 'email'
     AND public.is_marketing_night_window(p_scheduled_at, p_timezone) THEN
    SELECT * INTO v_night
    FROM privacy_retention.privacy_consent_events AS event
    WHERE event.user_id = p_user_id
      AND event.subject_kind = v_subject_kind
      AND event.guardian_verification_id IS NOT DISTINCT FROM v_guardian_id
      AND event.purpose = 'night_marketing'
      AND event.channel = p_channel
      AND event.occurred_at <= v_now
    ORDER BY event.occurred_at DESC, event.id DESC
    LIMIT 1;
    IF NOT FOUND OR v_night.decision IS DISTINCT FROM 'granted' THEN
      RETURN QUERY SELECT false, 'night_consent_missing'::text, NULL::uuid, NULL::uuid,
        v_subject_kind, v_guardian_id, v_policy.id, v_policy.content_sha256;
      RETURN;
    END IF;
    IF v_night.policy_version_id IS DISTINCT FROM v_policy.id
       OR v_night.notice_sha256 IS DISTINCT FROM v_policy.content_sha256 THEN
      RETURN QUERY SELECT false, 'night_consent_stale'::text, NULL::uuid, NULL::uuid,
        v_subject_kind, v_guardian_id, v_policy.id, v_policy.content_sha256;
      RETURN;
    END IF;
  END IF;

  RETURN QUERY SELECT true, 'allowed'::text, v_ordinary.id, v_night.id,
    v_subject_kind, v_guardian_id, v_policy.id, v_policy.content_sha256;
END;
$$;


--
-- Name: g014_marketing_provider_attempt_transition(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_provider_attempt_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'unknown'
       OR NEW.provider_receipt_id IS NOT NULL
       OR NEW.provider_receipt_hash IS NOT NULL
       OR NEW.accepted_recipient_ids IS NOT NULL
       OR NEW.accepted_recipient_digest IS NOT NULL
       OR NEW.provider_error_code IS NOT NULL
       OR NEW.outcome_recorded_at IS NOT NULL THEN
      RAISE EXCEPTION 'marketing_provider_attempt_initial_state_invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
     OR NEW.batch_id IS DISTINCT FROM OLD.batch_id
     OR NEW.claim_token IS DISTINCT FROM OLD.claim_token
     OR NEW.provider_identity IS DISTINCT FROM OLD.provider_identity
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.payload_digest IS DISTINCT FROM OLD.payload_digest
     OR OLD.status IS DISTINCT FROM 'unknown'
     OR NEW.status NOT IN ('accepted', 'failed') THEN
    RAISE EXCEPTION 'marketing_provider_attempt_transition_invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_marketing_reject_evidence_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_reject_evidence_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request_id uuid;
  v_target_user_id uuid;
BEGIN
  BEGIN
    v_request_id := pg_catalog.current_setting('app.account_deletion_request_id', true)::uuid;
    v_target_user_id := pg_catalog.current_setting('app.account_deletion_target_user_id', true)::uuid;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'marketing_consent_evidence_is_append_only' USING ERRCODE = '55000';
  END;
  IF TG_OP = 'DELETE'
     AND OLD.user_id = v_target_user_id
     AND privacy_retention.g014_account_deletion_evidence_cleanup_allowed(v_request_id, v_target_user_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'marketing_consent_evidence_is_append_only' USING ERRCODE = '55000';
END;
$$;


--
-- Name: g014_marketing_reject_provider_attempt_delete(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_reject_provider_attempt_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'marketing_provider_attempt_is_append_only' USING ERRCODE = '55000';
END;
$$;


--
-- Name: g014_marketing_write_audit(uuid, text, text, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_marketing_write_audit(p_operation_id uuid, p_preview_hash text, p_status text, p_reason_code text, p_error_code text, p_requested integer, p_eligible integer, p_suppressed integer, p_failed integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_audit_id uuid;
  v_transport_accepted integer := 0;
  v_notification_suppressed_after_acceptance integer := 0;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  SELECT count(*)::integer
    INTO v_transport_accepted
    FROM (
      SELECT DISTINCT accepted.user_id
      FROM privacy_retention.marketing_campaign_provider_attempts AS attempt
      CROSS JOIN LATERAL pg_catalog.unnest(
        COALESCE(attempt.accepted_recipient_ids, ARRAY[]::uuid[])
      ) AS accepted(user_id)
      WHERE attempt.operation_id = p_operation_id
        AND attempt.status = 'accepted'
    ) AS accepted;
  SELECT count(*)::integer
    INTO v_notification_suppressed_after_acceptance
    FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id
      AND recipient.notification_eligibility_outcome = 'notification_suppressed_after_acceptance';
  INSERT INTO privacy_retention.privacy_audit_events (
    event_type, actor_user_id, subject_ref_hash, operation_id, correlation_id,
    preview_hash, status, reason_code, error_code, count_summary,
    request_metadata, occurred_at, retention_until
  ) VALUES (
    'g014_marketing_campaign', NULL, NULL, p_operation_id, p_operation_id,
    p_preview_hash, p_status, p_reason_code, p_error_code,
    pg_catalog.jsonb_build_object(
      'requested', pg_catalog.greatest(COALESCE(p_requested, 0), 0),
      'eligible', pg_catalog.greatest(COALESCE(p_eligible, 0), 0),
      'suppressed', pg_catalog.greatest(COALESCE(p_suppressed, 0), 0),
      'failed', pg_catalog.greatest(COALESCE(p_failed, 0), 0),
      'transportAccepted', pg_catalog.greatest(COALESCE(v_transport_accepted, 0), 0),
      'notificationSuppressedAfterAcceptance',
        pg_catalog.greatest(COALESCE(v_notification_suppressed_after_acceptance, 0), 0)
    ),
    pg_catalog.jsonb_build_object('route', '/api/admin/marketing-campaigns'),
    v_now,
    public.privacy_resolve_audit_retention_until('privacy_marketing_audit', v_now)
  ) RETURNING id INTO v_audit_id;
  RETURN v_audit_id;
END;
$$;


--
-- Name: g014_privacy_eligibility_receipt(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_privacy_eligibility_receipt(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_policy privacy_retention.privacy_policy_versions%ROWTYPE;
  v_profile privacy_retention.privacy_age_profiles%ROWTYPE;
  v_guardian_id uuid;
  v_guardian_decision text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'privacy_eligibility_user_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_policy
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.status = 'published'
    AND policy.effective_at <= pg_catalog.clock_timestamp()
  ORDER BY policy.effective_at DESC, policy.id DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', false,
      'reasonCode', 'PRIVACY_POLICY_UNAVAILABLE',
      'policyVersionId', NULL,
      'contentSha256', NULL
    );
  END IF;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_onboarding_compensation_holds AS hold
    WHERE hold.user_id = p_user_id
      AND hold.operation_code = 'onboarding_compensation_hold'
      AND hold.state = 'active'
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', false,
      'reasonCode', 'PRIVACY_AGE_BLOCKED',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  SELECT * INTO v_profile
  FROM privacy_retention.privacy_age_profiles AS profile
  WHERE profile.user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', false,
      'reasonCode', 'PRIVACY_AGE_ATTESTATION_REQUIRED',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  IF v_profile.policy_version_id IS DISTINCT FROM v_policy.id THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', false,
      'reasonCode', 'PRIVACY_POLICY_REATTESTATION_REQUIRED',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  IF v_profile.status = 'blocked' THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', false,
      'reasonCode', 'PRIVACY_AGE_BLOCKED',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  IF v_profile.age_band = 'age_14_plus' AND v_profile.status = 'eligible' THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', true,
      'reasonCode', 'PRIVACY_ELIGIBLE',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  IF v_profile.age_band <> 'under_14' THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', false,
      'reasonCode', 'PRIVACY_AGE_ATTESTATION_REQUIRED',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  SELECT guardian.id INTO v_guardian_id
  FROM privacy_retention.privacy_guardian_verifications AS guardian
  WHERE guardian.child_user_id = p_user_id
    AND guardian.status = 'verified'
    AND guardian.verified_at IS NOT NULL
    AND guardian.verified_at <= pg_catalog.clock_timestamp()
    AND guardian.expires_at > pg_catalog.clock_timestamp()
    AND guardian.withdrawn_at IS NULL
  ORDER BY guardian.updated_at DESC, guardian.id DESC
  LIMIT 1;

  IF v_guardian_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', false,
      'reasonCode', 'PRIVACY_GUARDIAN_REQUIRED',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  SELECT event.decision INTO v_guardian_decision
  FROM privacy_retention.privacy_consent_events AS event
  WHERE event.user_id = p_user_id
    AND event.subject_kind = 'child'
    AND event.guardian_verification_id = v_guardian_id
    AND event.purpose = 'privacy_required'
    AND event.channel = 'none'
    AND event.policy_version_id = v_policy.id
    AND event.notice_sha256 = v_policy.content_sha256
    AND event.source = 'guardian'
  ORDER BY event.occurred_at DESC, event.id DESC
  LIMIT 1;

  IF v_guardian_decision = 'granted' THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'eligible', true,
      'reasonCode', 'PRIVACY_ELIGIBLE',
      'policyVersionId', v_policy.id::text,
      'contentSha256', v_policy.content_sha256
    );
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'eligible', false,
    'reasonCode', 'PRIVACY_GUARDIAN_CONSENT_REQUIRED',
    'policyVersionId', v_policy.id::text,
    'contentSha256', v_policy.content_sha256
  );
END;
$$;


