--
-- Name: g014_require_active_admin_actor(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_require_active_admin_actor(p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_user_id uuid;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'marketing_admin_actor_forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT role_row.user_id
    INTO v_actor_user_id
    FROM public.user_roles AS role_row
    JOIN public.user_account_status AS status_row
      ON status_row.user_id = role_row.user_id
   WHERE role_row.user_id = p_actor_user_id
     AND role_row.role = 'admin'
     AND status_row.account_status = 'active'
   FOR UPDATE OF role_row, status_row;

  IF NOT FOUND OR v_actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION 'marketing_admin_actor_forbidden' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: g014_require_service_role(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_require_service_role() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
BEGIN
  v_role := COALESCE(
    NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    pg_catalog.current_setting('request.jwt.claim.role', true),
    ''
  );
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'privacy_service_role_required' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: g014_retention_active_adapter_version(text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_active_adapter_version(p_class_code text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      COALESCE((
        SELECT pg_catalog.string_agg(
          pg_catalog.concat_ws(':', binding.adapter_code, binding.adapter_version),
          E'\n' ORDER BY binding.adapter_code, binding.adapter_version
        )
        FROM privacy_retention.retention_class_adapter_bindings AS binding
        JOIN privacy_retention.retention_adapter_versions AS version_row
          ON version_row.adapter_code = binding.adapter_code
         AND version_row.adapter_version = binding.adapter_version
         AND version_row.status = 'active'
         AND binding.source_type IS NOT DISTINCT FROM version_row.source_type
         AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
        WHERE binding.class_code = p_class_code
          AND binding.status = 'active'
      ), ''),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_active_hold_exists(text, text, timestamp with time zone); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_active_hold_exists(p_subject_ref_hash text, p_data_class text, p_as_of timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_subject_ref_hash IS NOT NULL AND EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_legal_holds AS hold_row
    WHERE hold_row.subject_ref_hash = p_subject_ref_hash
      AND hold_row.data_class = p_data_class
      AND hold_row.status = 'active'
      AND (hold_row.expires_at IS NULL OR hold_row.expires_at > p_as_of)
  );
$$;


--
-- Name: g014_retention_active_source_mapping_version(text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_active_source_mapping_version(p_class_code text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      COALESCE((
        SELECT pg_catalog.string_agg(
          pg_catalog.concat_ws(':', binding.class_code, binding.source_type, binding.mapping_contract_hash),
          E'\n' ORDER BY binding.class_code, binding.source_type, binding.mapping_contract_hash
        )
        FROM privacy_retention.retention_class_adapter_bindings AS binding
        JOIN privacy_retention.retention_adapter_versions AS version_row
          ON version_row.adapter_code = binding.adapter_code
         AND version_row.adapter_version = binding.adapter_version
         AND version_row.status = 'active'
         AND binding.source_type IS NOT DISTINCT FROM version_row.source_type
         AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
        WHERE binding.class_code = p_class_code
          AND binding.status = 'active'
      ), ''),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_adapter_contract_hash(text, text, text, text, text, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_adapter_contract_hash(p_adapter_code text, p_adapter_version text, p_source_relation text, p_source_identifier_column text, p_source_type text, p_removal_mode text, p_provider_verifier_ref text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        ':', 'g014-retention-adapter-v1', p_adapter_code, p_adapter_version,
        p_source_relation, p_source_identifier_column, p_source_type,
        p_removal_mode, COALESCE(p_provider_verifier_ref, '<none>')
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_adapter_version_transition(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_adapter_version_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.adapter_code IS DISTINCT FROM NEW.adapter_code
     OR OLD.adapter_version IS DISTINCT FROM NEW.adapter_version
     OR OLD.source_relation IS DISTINCT FROM NEW.source_relation
     OR OLD.source_identifier_column IS DISTINCT FROM NEW.source_identifier_column
     OR OLD.source_type IS DISTINCT FROM NEW.source_type
     OR OLD.removal_mode IS DISTINCT FROM NEW.removal_mode
     OR OLD.provider_verifier_ref IS DISTINCT FROM NEW.provider_verifier_ref
     OR OLD.contract_hash IS DISTINCT FROM NEW.contract_hash
     OR OLD.created_at IS DISTINCT FROM NEW.created_at
     OR (
       OLD.physical_catalog_fingerprint IS NOT NULL
       AND OLD.physical_catalog_fingerprint IS DISTINCT FROM NEW.physical_catalog_fingerprint
     ) THEN
    RAISE EXCEPTION 'retention_adapter_version_binding_is_immutable' USING ERRCODE = '55000';
  END IF;

  IF OLD.status = 'active' AND (
    OLD.operator_approval_ref IS DISTINCT FROM NEW.operator_approval_ref
    OR OLD.legal_approval_ref IS DISTINCT FROM NEW.legal_approval_ref
    OR OLD.activated_at IS DISTINCT FROM NEW.activated_at
    OR OLD.physical_catalog_fingerprint IS DISTINCT FROM NEW.physical_catalog_fingerprint
  ) THEN
    RAISE EXCEPTION 'retention_adapter_activation_evidence_is_immutable' USING ERRCODE = '55000';
  END IF;

  IF NOT (
    (OLD.status = 'disabled' AND NEW.status IN ('draft', 'active'))
    OR (OLD.status = 'draft' AND NEW.status = 'active')
    OR (OLD.status = 'active' AND NEW.status = 'disabled')
  ) THEN
    RAISE EXCEPTION 'retention_adapter_version_predecessor_invalid' USING ERRCODE = '55000';
  END IF;

  IF NEW.status = 'active'
     AND NEW.physical_catalog_fingerprint IS DISTINCT FROM
         privacy_retention.g014_retention_catalog_fingerprint(
           NEW.source_relation, NEW.source_identifier_column
         ) THEN
    RAISE EXCEPTION 'retention_adapter_physical_catalog_drift' USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: privacy_retention_runs; Type: TABLE; Schema: privacy_retention; Owner: -
--

CREATE TABLE privacy_retention.privacy_retention_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    class_code text NOT NULL,
    cutoff timestamp with time zone NOT NULL,
    status text NOT NULL,
    preview_hash text NOT NULL,
    preview_expires_at timestamp with time zone NOT NULL,
    idempotency_key text,
    scanned_count integer DEFAULT 0 NOT NULL,
    planned_count integer DEFAULT 0 NOT NULL,
    held_count integer DEFAULT 0 NOT NULL,
    separated_count integer DEFAULT 0 NOT NULL,
    storage_deleted_count integer DEFAULT 0 NOT NULL,
    failure_count integer DEFAULT 0 NOT NULL,
    readback_passed boolean DEFAULT false NOT NULL,
    audit_id uuid,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    database_readback_passed boolean DEFAULT false NOT NULL,
    storage_readback_passed boolean DEFAULT false NOT NULL,
    no_active_hold_mutated boolean DEFAULT false NOT NULL,
    storage_receipts_hash text,
    adapter_version text NOT NULL,
    source_mapping_version text NOT NULL,
    CONSTRAINT privacy_retention_runs_adapter_version_check CHECK (((adapter_version IS NULL) OR (adapter_version ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT privacy_retention_runs_completed_readback_check CHECK (((status <> 'completed'::text) OR (readback_passed AND (completed_at IS NOT NULL)))),
    CONSTRAINT privacy_retention_runs_completion_order_check CHECK (((completed_at IS NULL) OR (started_at IS NULL) OR (completed_at >= started_at))),
    CONSTRAINT privacy_retention_runs_failure_count_check CHECK ((failure_count >= 0)),
    CONSTRAINT privacy_retention_runs_held_count_check CHECK ((held_count >= 0)),
    CONSTRAINT privacy_retention_runs_idempotency_key_check CHECK (((idempotency_key IS NULL) OR (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'::text))),
    CONSTRAINT privacy_retention_runs_planned_count_check CHECK ((planned_count >= 0)),
    CONSTRAINT privacy_retention_runs_preview_hash_check CHECK ((preview_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT privacy_retention_runs_scanned_count_check CHECK ((scanned_count >= 0)),
    CONSTRAINT privacy_retention_runs_separated_count_check CHECK ((separated_count >= 0)),
    CONSTRAINT privacy_retention_runs_source_mapping_version_check CHECK (((source_mapping_version IS NULL) OR (source_mapping_version ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT privacy_retention_runs_status_check CHECK ((status = ANY (ARRAY['previewed'::text, 'confirmed'::text, 'running'::text, 'completed'::text, 'partial'::text, 'failed'::text, 'held'::text]))),
    CONSTRAINT privacy_retention_runs_storage_deleted_count_check CHECK ((storage_deleted_count >= 0)),
    CONSTRAINT privacy_retention_runs_storage_receipts_hash_check CHECK (((storage_receipts_hash IS NULL) OR (storage_receipts_hash ~ '^[0-9a-f]{64}$'::text)))
);

ALTER TABLE ONLY privacy_retention.privacy_retention_runs FORCE ROW LEVEL SECURITY;


--
-- Name: g014_retention_append_audit(privacy_retention.privacy_retention_runs, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_append_audit(p_run privacy_retention.privacy_retention_runs, p_status text, p_reason_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_audit_id uuid;
  v_occurred_at timestamptz := pg_catalog.clock_timestamp();
  v_retention_until timestamptz;
BEGIN
  v_retention_until := public.privacy_resolve_audit_retention_until(
    'privacy_retention_run_audit',
    v_occurred_at
  );

  INSERT INTO privacy_retention.privacy_audit_events (
    event_type, actor_user_id, operation_id, correlation_id, preview_hash, status,
    reason_code, count_summary, request_metadata, occurred_at, retention_until
  ) VALUES (
    'privacy_retention_run',
    CASE WHEN privacy_retention.g041_current_claim_user_id() IS NOT NULL AND EXISTS (SELECT 1 FROM privacy_retention.g041_auth_users AS user_row WHERE user_row.id = privacy_retention.g041_current_claim_user_id())
      THEN privacy_retention.g041_current_claim_user_id() ELSE NULL END,
    p_run.id,
    p_run.id,
    p_run.preview_hash,
    p_status,
    p_reason_code,
    pg_catalog.jsonb_build_object(
      'requested', p_run.scanned_count,
      'eligible', p_run.planned_count,
      'suppressed', p_run.held_count,
      'created', p_run.separated_count,
      'updated', p_run.storage_deleted_count,
      'failed', p_run.failure_count
    ),
    pg_catalog.jsonb_build_object('route', '/api/internal/privacy-retention'),
    v_occurred_at,
    v_retention_until
  ) RETURNING id INTO v_audit_id;

  RETURN v_audit_id;
END;
$$;


--
-- Name: g014_retention_approval_insert_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_approval_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.approved_by_principal IS NULL
     OR NEW.approved_by_principal IS DISTINCT FROM session_user::name
     OR NEW.approved_by_principal = ANY (ARRAY[
       'service_role'::name,
       'privacy_retention_operator_approver'::name,
       'privacy_retention_legal_approver'::name,
       'privacy_retention_activation_operator'::name
     ])
     OR NEW.approved_at > pg_catalog.clock_timestamp()
     OR NEW.signed_payload_hash IS DISTINCT FROM
        privacy_retention.g014_retention_approval_payload_hash(
          NEW.approval_kind, NEW.class_code, NEW.adapter_code, NEW.adapter_version,
          NEW.retention_period, NEW.mapping_contract_hash, NEW.approval_ref
        )
     OR (NEW.approval_kind = 'operator' AND current_user IS DISTINCT FROM 'privacy_retention_operator_approver')
     OR (NEW.approval_kind = 'legal' AND current_user IS DISTINCT FROM 'privacy_retention_legal_approver')
     OR NEW.approved_by_role IS DISTINCT FROM current_user::name THEN
    RAISE EXCEPTION 'retention_approval_identity_or_binding_invalid' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_approval_payload_hash(text, text, text, text, interval, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_approval_payload_hash(p_approval_kind text, p_class_code text, p_adapter_code text, p_adapter_version text, p_retention_period interval, p_mapping_contract_hash text, p_approval_ref text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        ':', 'g014-retention-approval-v1', p_approval_kind, p_class_code,
        p_adapter_code, p_adapter_version, p_retention_period::text,
        p_mapping_contract_hash, p_approval_ref
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_assert_class_bindings(text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_assert_class_bindings(p_class_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_active_count integer;
  v_valid_count integer;
BEGIN
  IF p_class_code IS NULL THEN
    RAISE EXCEPTION 'privacy_retention_class_binding_required' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-retention-class:' || p_class_code, 0)
  );
  PERFORM 1
  FROM privacy_retention.retention_class_adapter_bindings AS binding
  WHERE binding.class_code = p_class_code
    AND binding.status = 'active'
  FOR SHARE;

  PERFORM 1
  FROM privacy_retention.retention_adapter_versions AS version_row
  JOIN privacy_retention.retention_class_adapter_bindings AS binding
    ON binding.adapter_code = version_row.adapter_code
   AND binding.adapter_version = version_row.adapter_version
  WHERE binding.class_code = p_class_code
    AND binding.status = 'active'
  FOR SHARE OF version_row;
  SELECT count(*), count(version_row.adapter_code)
  INTO v_active_count, v_valid_count
  FROM privacy_retention.retention_class_adapter_bindings AS binding
  LEFT JOIN privacy_retention.retention_adapter_versions AS version_row
    ON version_row.adapter_code = binding.adapter_code
   AND version_row.adapter_version = binding.adapter_version
   AND version_row.status = 'active'
   AND binding.source_type IS NOT DISTINCT FROM version_row.source_type
   AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
   AND version_row.physical_catalog_fingerprint IS NOT DISTINCT FROM
       privacy_retention.g014_retention_catalog_fingerprint(
         version_row.source_relation, version_row.source_identifier_column
       )
  WHERE binding.class_code = p_class_code
    AND binding.status = 'active';

  IF v_active_count = 0 OR v_active_count IS DISTINCT FROM v_valid_count THEN
    RAISE EXCEPTION 'privacy_retention_active_binding_invalid' USING ERRCODE = '55000';
  END IF;
END;
$$;


--
-- Name: g014_retention_assert_run_bindings(text, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_assert_run_bindings(p_class_code text, p_adapter_version text, p_source_mapping_version text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM privacy_retention.g014_retention_assert_class_bindings(p_class_code);
  IF p_adapter_version IS NULL
     OR p_source_mapping_version IS NULL
     OR p_adapter_version IS DISTINCT FROM
        privacy_retention.g014_retention_active_adapter_version(p_class_code)
     OR p_source_mapping_version IS DISTINCT FROM
        privacy_retention.g014_retention_active_source_mapping_version(p_class_code) THEN
    RAISE EXCEPTION 'privacy_retention_binding_drift' USING ERRCODE = '55000';
  END IF;
END;
$$;


--
-- Name: g014_retention_binding_transition(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_binding_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-retention-class:' || OLD.class_code, 0)
  );
  IF OLD.class_code IS DISTINCT FROM NEW.class_code
     OR OLD.adapter_code IS DISTINCT FROM NEW.adapter_code
     OR OLD.adapter_version IS DISTINCT FROM NEW.adapter_version
     OR OLD.source_type IS DISTINCT FROM NEW.source_type
     OR OLD.mapping_contract_hash IS DISTINCT FROM NEW.mapping_contract_hash
     OR OLD.operator_approval_ref IS DISTINCT FROM NEW.operator_approval_ref
     OR OLD.legal_approval_ref IS DISTINCT FROM NEW.legal_approval_ref
     OR OLD.activated_at IS DISTINCT FROM NEW.activated_at
     OR OLD.created_at IS DISTINCT FROM NEW.created_at
     OR NOT (OLD.status = 'active' AND NEW.status = 'disabled') THEN
    RAISE EXCEPTION 'retention_adapter_binding_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_catalog_fingerprint(text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_catalog_fingerprint(p_source_relation text, p_source_identifier_column text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_relation regclass;
  v_relation_oid oid;
  v_relkind "char";
  v_attnum smallint;
  v_atttypid oid;
  v_atttypmod integer;
  v_attnotnull boolean;
  v_constraint_identity text;
BEGIN
  v_relation := pg_catalog.to_regclass(p_source_relation);
  IF v_relation IS NULL THEN
    RAISE EXCEPTION 'retention_adapter_source_relation_missing' USING ERRCODE = '55000';
  END IF;

  SELECT relation_row.oid, relation_row.relkind, attribute.attnum, attribute.atttypid,
         attribute.atttypmod, attribute.attnotnull,
         (
           SELECT pg_catalog.string_agg(
             pg_catalog.concat_ws(':', constraint_row.oid::text, constraint_row.conname,
               pg_catalog.pg_get_constraintdef(constraint_row.oid, true)),
             E'\n' ORDER BY constraint_row.oid
           )
           FROM pg_catalog.pg_constraint AS constraint_row
           WHERE constraint_row.conrelid = relation_row.oid
             AND constraint_row.contype IN ('p', 'u')
             AND attribute.attnum = ANY (constraint_row.conkey)
         )
  INTO v_relation_oid, v_relkind, v_attnum, v_atttypid, v_atttypmod, v_attnotnull, v_constraint_identity
  FROM pg_catalog.pg_class AS relation_row
  JOIN pg_catalog.pg_attribute AS attribute
    ON attribute.attrelid = relation_row.oid
   AND attribute.attname = p_source_identifier_column
   AND attribute.attnum > 0
   AND NOT attribute.attisdropped
  WHERE relation_row.oid = v_relation;

  IF v_relation_oid IS NULL
     OR v_relkind IS DISTINCT FROM 'r'
     OR v_attnum IS NULL
     OR v_constraint_identity IS NULL THEN
    RAISE EXCEPTION 'retention_adapter_physical_catalog_invalid' USING ERRCODE = '55000';
  END IF;

  RETURN pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        ':', 'g014-retention-catalog-v1', v_relation_oid::text, v_relkind::text,
        v_attnum::text, v_atttypid::regtype::text, v_atttypmod::text,
        v_attnotnull::text, v_constraint_identity
      ),
      'sha256'
    ),
    'hex'
  );
END;
$$;


--
-- Name: g014_retention_claim_storage_items_internal(uuid, text, text, integer); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_claim_storage_items_internal(p_run_id uuid, p_preview_hash text, p_idempotency_key text, p_limit integer) RETURNS TABLE(work_item_id uuid, claim_token uuid, object_locator_hash text, object_version_hash text, claim_hash text, adapter_version text, source_mapping_version text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_run privacy_retention.privacy_retention_runs%ROWTYPE;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'privacy_retention_storage_limit_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_run FROM privacy_retention.privacy_retention_runs
  WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND OR v_run.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_run.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_run.status NOT IN ('running', 'partial', 'held') THEN
    RAISE EXCEPTION 'privacy_retention_storage_claim_binding_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    v_run.class_code, v_run.adapter_version, v_run.source_mapping_version
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-retention-run:' || v_run.id::text, 0)
  );

  UPDATE privacy_retention.g014_retention_storage_claims AS claim_row
  SET status = 'expired', resolved_at = v_now
  WHERE claim_row.run_id = v_run.id
    AND claim_row.status = 'active'
    AND claim_row.claim_expires_at <= v_now
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.g014_retention_provider_effects AS effect_row
      WHERE effect_row.claim_token = claim_row.claim_token
    );
  UPDATE privacy_retention.privacy_retention_work_items AS item
  SET status = 'failed', storage_claim_token = NULL, storage_claimed_at = NULL,
      last_error_code = 'retention_storage_claim_expired'
  FROM privacy_retention.g014_retention_storage_claims AS claim_row
  WHERE claim_row.run_id = v_run.id
    AND claim_row.status = 'expired'
    AND item.id = claim_row.work_item_id
    AND item.status = 'claimed'
    AND item.storage_claim_token IS NOT DISTINCT FROM claim_row.claim_token;
  UPDATE privacy_retention.privacy_retention_run_items AS run_item
  SET status = 'failed', error_code = 'retention_storage_claim_expired'
  FROM privacy_retention.g014_retention_storage_claims AS claim_row
  WHERE claim_row.run_id = v_run.id
    AND claim_row.status = 'expired'
    AND run_item.run_id = v_run.id
    AND run_item.work_item_id = claim_row.work_item_id
    AND run_item.status = 'storage_claimed';
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.g014_retention_storage_claims AS claim_row
    WHERE claim_row.run_id = v_run.id
      AND claim_row.status = 'active'
  ) THEN
    RAISE EXCEPTION 'retention_storage_claim_batch_pending' USING ERRCODE = '55000';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT run_item.work_item_id, item.source_ref_hash, item.storage_version_hash,
           item.subject_ref_hash, item.data_class,
           binding.adapter_code, binding.adapter_version,
           COALESCE((
             SELECT max(previous.attempt_number)
             FROM privacy_retention.g014_retention_storage_claims AS previous
             WHERE previous.run_id = v_run.id AND previous.work_item_id = run_item.work_item_id
           ), 0) + 1 AS attempt_number
    FROM privacy_retention.privacy_retention_run_items AS run_item
    JOIN privacy_retention.privacy_retention_work_items AS item ON item.id = run_item.work_item_id
    JOIN privacy_retention.retention_class_adapter_bindings AS binding
      ON binding.class_code = item.class_code
     AND binding.source_type = item.source_type
     AND binding.status = 'active'
    JOIN privacy_retention.retention_adapter_versions AS version_row
      ON version_row.adapter_code = binding.adapter_code
     AND version_row.adapter_version = binding.adapter_version
     AND version_row.status = 'active'
     AND version_row.removal_mode = 'external_delete'
     AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
    WHERE run_item.run_id = v_run.id
      AND run_item.status IN ('planned', 'failed')
      AND item.status IN ('pending', 'failed')
      AND item.source_type IN ('storage_object', 'ocr_artifact')
      AND item.storage_version_hash IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM privacy_retention.g014_retention_provider_effects AS effect_row
        WHERE effect_row.work_item_id = run_item.work_item_id
      )
    ORDER BY item.subject_ref_hash NULLS FIRST, item.trigger_at, item.id
    LIMIT p_limit
    FOR UPDATE OF run_item, item SKIP LOCKED
  ), locked AS MATERIALIZED (
    SELECT candidates.*,
           privacy_retention.g014_retention_lock_subject_hash(candidates.subject_ref_hash) AS subject_lock
    FROM candidates
    ORDER BY candidates.subject_ref_hash NULLS FIRST, candidates.work_item_id
  ), eligible AS (
    SELECT locked.*
    FROM locked
    WHERE NOT privacy_retention.g014_retention_active_hold_exists(
      locked.subject_ref_hash, locked.data_class, v_now
    )
  ), selected AS (
    SELECT eligible.*
    FROM eligible
    WHERE (adapter_code, adapter_version) = (
      SELECT adapter_code, adapter_version
      FROM eligible
      ORDER BY work_item_id
      LIMIT 1
    )
  ), inserted AS (
    INSERT INTO privacy_retention.g014_retention_storage_claims (
      run_id, work_item_id, adapter_code, adapter_version, object_locator_hash,
      object_version_hash, claim_hash, attempt_number, claim_expires_at
    )
    SELECT v_run.id, work_item_id, adapter_code, adapter_version, source_ref_hash,
           storage_version_hash, NULL, attempt_number, v_now + interval '5 minutes'
    FROM selected
    WHERE attempt_number <= 3
    RETURNING work_item_id, claim_token, object_locator_hash, object_version_hash, claim_hash
  ), claimed AS (
    UPDATE privacy_retention.privacy_retention_work_items AS item
    SET status = 'claimed', storage_claim_token = inserted.claim_token,
        storage_claimed_at = v_now, last_error_code = NULL
    FROM inserted
    WHERE item.id = inserted.work_item_id
    RETURNING item.id
  ), marked AS (
    UPDATE privacy_retention.privacy_retention_run_items AS run_item
    SET status = 'storage_claimed', error_code = NULL
    FROM claimed
    WHERE run_item.run_id = v_run.id AND run_item.work_item_id = claimed.id
    RETURNING run_item.work_item_id
  )
  SELECT inserted.work_item_id, inserted.claim_token, inserted.object_locator_hash,
         inserted.object_version_hash, inserted.claim_hash,
         v_run.adapter_version, v_run.source_mapping_version
  FROM inserted
  JOIN marked ON marked.work_item_id = inserted.work_item_id;
END;
$$;


--
-- Name: g014_retention_database_absence_hash(text, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_database_absence_hash(p_adapter_code text, p_adapter_version text, p_source_ref_hash text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        ':', 'g014-retention-database-absence-v1', p_adapter_code,
        p_adapter_version, p_source_ref_hash, 'absent'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_hold_subject_lock(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_hold_subject_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM privacy_retention.g014_retention_lock_subject_hash(NEW.subject_ref_hash);
  IF TG_OP = 'INSERT' AND EXISTS (
    SELECT 1
    FROM privacy_retention.g014_retention_provider_effects AS effect_row
    WHERE effect_row.subject_ref_hash = NEW.subject_ref_hash
      AND effect_row.data_class = NEW.data_class
      AND effect_row.effect_state IN ('provider_effect_in_flight', 'reconciliation_required')
  ) THEN
    RAISE EXCEPTION 'retention_provider_effect_in_flight' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_hold_transition_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_hold_transition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'legal_hold_delete_denied' USING ERRCODE = '55000';
  END IF;
  IF OLD.status IS DISTINCT FROM 'active' OR NEW.status IS DISTINCT FROM 'released'
     OR OLD.subject_ref_hash IS DISTINCT FROM NEW.subject_ref_hash
     OR OLD.data_class IS DISTINCT FROM NEW.data_class
     OR OLD.reason_code IS DISTINCT FROM NEW.reason_code
     OR OLD.approved_by IS DISTINCT FROM NEW.approved_by
     OR OLD.approved_evidence_ref IS DISTINCT FROM NEW.approved_evidence_ref
     OR OLD.expires_at IS DISTINCT FROM NEW.expires_at
     OR OLD.created_at IS DISTINCT FROM NEW.created_at
     OR NEW.released_at IS NULL
     OR NEW.released_at < OLD.created_at THEN
    RAISE EXCEPTION 'legal_hold_transition_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_lock_subject_hash(text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_lock_subject_hash(p_subject_ref_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_subject_ref_hash IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('g014-retention-subject:' || p_subject_ref_hash, 0)
    );
  END IF;
END;
$$;


--
-- Name: g014_retention_no_active_hold_mutated(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_no_active_hold_mutated(p_run_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_item record;
BEGIN
  IF p_run_id IS NULL THEN
    RAISE EXCEPTION 'privacy_retention_run_required' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN
    SELECT run_item.work_item_id, item.source_ref_hash, item.subject_ref_hash,
           item.data_class, item.source_type, binding.adapter_code,
           version_row.source_relation, version_row.source_identifier_column
    FROM privacy_retention.privacy_retention_run_items AS run_item
    JOIN privacy_retention.privacy_retention_work_items AS item
      ON item.id = run_item.work_item_id
    JOIN privacy_retention.retention_class_adapter_bindings AS binding
      ON binding.class_code = item.class_code
     AND binding.source_type = item.source_type
     AND binding.status = 'active'
    JOIN privacy_retention.retention_adapter_versions AS version_row
      ON version_row.adapter_code = binding.adapter_code
     AND version_row.adapter_version = binding.adapter_version
     AND version_row.status = 'active'
     AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
    WHERE run_item.run_id = p_run_id
    ORDER BY item.subject_ref_hash NULLS FIRST, run_item.work_item_id
  LOOP
    PERFORM privacy_retention.g014_retention_lock_subject_hash(v_item.subject_ref_hash);
    IF privacy_retention.g014_retention_active_hold_exists(
         v_item.subject_ref_hash, v_item.data_class, pg_catalog.clock_timestamp()
       ) THEN
      IF EXISTS (
           SELECT 1
           FROM privacy_retention.g014_retention_receipts AS receipt
           WHERE receipt.run_id = p_run_id
             AND receipt.work_item_id = v_item.work_item_id
             AND receipt.receipt_kind IN ('database_source_absence', 'storage_provider_absence')
         ) THEN
        RETURN false;
      END IF;
      IF v_item.source_type NOT IN ('storage_object', 'ocr_artifact')
         AND privacy_retention.g014_retention_source_absent(
           v_item.adapter_code, v_item.source_relation,
           v_item.source_identifier_column, v_item.source_ref_hash
         ) THEN
        RETURN false;
      END IF;
    END IF;
  END LOOP;
  RETURN true;
END;
$$;


--
-- Name: g014_retention_provider_effect_transition(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_provider_effect_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.run_id IS DISTINCT FROM NEW.run_id
     OR OLD.work_item_id IS DISTINCT FROM NEW.work_item_id
     OR OLD.claim_token IS DISTINCT FROM NEW.claim_token
     OR OLD.claim_hash IS DISTINCT FROM NEW.claim_hash
     OR OLD.object_locator_hash IS DISTINCT FROM NEW.object_locator_hash
     OR OLD.object_version_hash IS DISTINCT FROM NEW.object_version_hash
     OR OLD.adapter_version IS DISTINCT FROM NEW.adapter_version
     OR OLD.source_mapping_version IS DISTINCT FROM NEW.source_mapping_version
     OR OLD.provider_verifier_ref IS DISTINCT FROM NEW.provider_verifier_ref
     OR OLD.subject_ref_hash IS DISTINCT FROM NEW.subject_ref_hash
     OR OLD.data_class IS DISTINCT FROM NEW.data_class
     OR OLD.provider_effect_token IS DISTINCT FROM NEW.provider_effect_token
     OR OLD.authorized_at IS DISTINCT FROM NEW.authorized_at
     OR OLD.lease_expires_at IS DISTINCT FROM NEW.lease_expires_at
     OR OLD.created_at IS DISTINCT FROM NEW.created_at
     OR NOT (
       (OLD.effect_state = 'provider_effect_in_flight'
         AND NEW.effect_state IN ('reconciliation_required', 'verified_absent', 'failed'))
       OR (OLD.effect_state = 'reconciliation_required'
         AND NEW.effect_state IN ('verified_absent', 'failed'))
     )
     OR (
       NEW.effect_state = 'reconciliation_required'
       AND (NEW.verified_at IS NOT NULL OR NEW.failure_code IS NOT NULL)
     )
     OR (
       NEW.effect_state IN ('verified_absent', 'failed')
       AND (NEW.verified_at IS NULL OR NEW.verified_at < OLD.authorized_at)
     ) THEN
    RAISE EXCEPTION 'retention_provider_effect_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_reject_evidence_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_reject_evidence_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION '% is immutable', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME USING ERRCODE = '55000';
END;
$$;


--
-- Name: g014_retention_require_activation_operator(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_require_activation_operator() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS NOT DISTINCT FROM 'service_role'
     OR session_user::name = ANY (ARRAY[
       'service_role'::name,
       'privacy_retention_operator_approver'::name,
       'privacy_retention_legal_approver'::name,
       'privacy_retention_activation_operator'::name
     ])
     OR NOT pg_catalog.pg_has_role(session_user, 'privacy_retention_activation_operator', 'member') THEN
    RAISE EXCEPTION 'retention_activation_operator_required' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: g014_retention_require_service_role(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_require_service_role() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'privacy_retention_service_role_required' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: g014_retention_run_item_transition_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_run_item_transition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    run_row.class_code, run_row.adapter_version, run_row.source_mapping_version
  )
  FROM privacy_retention.privacy_retention_runs AS run_row
  WHERE run_row.id = NEW.run_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'retention_run_item_run_missing' USING ERRCODE = '55000';
  END IF;
  IF OLD.run_id IS DISTINCT FROM NEW.run_id
     OR OLD.work_item_id IS DISTINCT FROM NEW.work_item_id
     OR OLD.source_type IS DISTINCT FROM NEW.source_type THEN
    RAISE EXCEPTION 'privacy_retention_run_item_binding_is_immutable' USING ERRCODE = '55000';
  END IF;
  IF OLD.status IS DISTINCT FROM NEW.status AND NOT (
    (OLD.status = 'planned' AND NEW.status IN ('held', 'separated', 'storage_claimed', 'failed'))
    OR (OLD.status = 'held' AND NEW.status = 'planned')
    OR (OLD.status = 'storage_claimed' AND NEW.status IN ('planned', 'storage_deleted', 'failed', 'held'))
    OR (OLD.status = 'failed' AND NEW.status IN ('planned', 'storage_claimed', 'held'))
  ) THEN
    RAISE EXCEPTION 'privacy_retention_run_item_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_run_transition_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_run_transition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.cutoff IS NULL
     OR NEW.adapter_version IS NULL
     OR NEW.source_mapping_version IS NULL THEN
    RAISE EXCEPTION 'privacy_retention_run_binding_required' USING ERRCODE = '22023';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    NEW.class_code, NEW.adapter_version, NEW.source_mapping_version
  );
  IF TG_OP = 'INSERT' THEN
    IF NEW.cutoff > pg_catalog.clock_timestamp() THEN
      RAISE EXCEPTION 'privacy_retention_cutoff_future' USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.class_code IS DISTINCT FROM NEW.class_code
     OR OLD.cutoff IS DISTINCT FROM NEW.cutoff
     OR OLD.preview_hash IS DISTINCT FROM NEW.preview_hash
     OR OLD.preview_expires_at IS DISTINCT FROM NEW.preview_expires_at
     OR OLD.created_at IS DISTINCT FROM NEW.created_at
     OR OLD.adapter_version IS DISTINCT FROM NEW.adapter_version
     OR OLD.source_mapping_version IS DISTINCT FROM NEW.source_mapping_version
     OR (OLD.idempotency_key IS NOT NULL AND NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key)
     OR (OLD.storage_receipts_hash IS NOT NULL AND NEW.storage_receipts_hash IS DISTINCT FROM OLD.storage_receipts_hash)
     OR (OLD.database_readback_passed AND NOT NEW.database_readback_passed)
     OR (OLD.storage_readback_passed AND NOT NEW.storage_readback_passed)
     OR (OLD.no_active_hold_mutated AND NOT NEW.no_active_hold_mutated)
     OR (OLD.readback_passed AND NOT NEW.readback_passed) THEN
    RAISE EXCEPTION 'privacy_retention_run_binding_is_immutable' USING ERRCODE = '55000';
  END IF;

  IF OLD.status IS DISTINCT FROM NEW.status AND NOT (
    (OLD.status = 'previewed' AND NEW.status IN ('confirmed', 'failed'))
    OR (OLD.status = 'confirmed' AND NEW.status IN ('running', 'failed'))
    OR (OLD.status = 'running' AND NEW.status IN ('completed', 'partial', 'held', 'failed'))
    OR (OLD.status = 'partial' AND NEW.status IN ('running', 'completed', 'held', 'failed'))
    OR (OLD.status = 'held' AND NEW.status IN ('running', 'completed', 'partial', 'failed'))
  ) THEN
    RAISE EXCEPTION 'privacy_retention_run_predecessor_invalid' USING ERRCODE = '55000';
  END IF;

  IF NEW.cutoff > pg_catalog.clock_timestamp()
     OR (NEW.status = 'completed' AND NOT NEW.readback_passed)
     OR (NEW.readback_passed AND NEW.status IS DISTINCT FROM 'completed') THEN
    RAISE EXCEPTION 'privacy_retention_run_state_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_source_absent(text, text, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_source_absent(p_adapter_code text, p_source_relation text, p_source_identifier_column text, p_source_ref_hash text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_relation regclass;
  v_count bigint;
BEGIN
  v_relation := pg_catalog.to_regclass(p_source_relation);
  IF v_relation IS NULL THEN
    RAISE EXCEPTION 'retention_adapter_source_relation_missing' USING ERRCODE = '55000';
  END IF;

  EXECUTE pg_catalog.format(
    'SELECT count(*) FROM %s WHERE privacy_retention.g014_retention_source_hash($1, %I::text) = $2',
    v_relation,
    p_source_identifier_column
  ) INTO v_count USING p_adapter_code, p_source_ref_hash;

  RETURN v_count = 0;
END;
$_$;


--
-- Name: g014_retention_source_hash(text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_source_hash(p_adapter_code text, p_source_identifier text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(':', 'g014-retention-source-v1', p_adapter_code, p_source_identifier),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_storage_claim_binding(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_storage_claim_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_item privacy_retention.privacy_retention_work_items%ROWTYPE;
BEGIN
  SELECT * INTO v_item
  FROM privacy_retention.privacy_retention_work_items AS item
  WHERE item.id = NEW.work_item_id;

  IF NOT FOUND
     OR v_item.source_ref_hash IS DISTINCT FROM NEW.object_locator_hash
     OR v_item.storage_version_hash IS DISTINCT FROM NEW.object_version_hash
     OR NEW.claim_expires_at <= NEW.claimed_at
     OR NEW.claim_hash IS NOT NULL AND NEW.claim_hash IS DISTINCT FROM
        privacy_retention.g014_retention_storage_claim_hash(
          NEW.run_id, NEW.work_item_id, NEW.claim_token,
          NEW.object_locator_hash, NEW.object_version_hash
        ) THEN
    RAISE EXCEPTION 'retention_storage_claim_binding_invalid' USING ERRCODE = '55000';
  END IF;

  NEW.claim_hash := privacy_retention.g014_retention_storage_claim_hash(
    NEW.run_id, NEW.work_item_id, NEW.claim_token,
    NEW.object_locator_hash, NEW.object_version_hash
  );
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_storage_claim_hash(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_storage_claim_hash(p_run_id uuid, p_work_item_id uuid, p_claim_token uuid, p_object_locator_hash text, p_object_version_hash text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        ':', 'g014-retention-storage-claim-v1', p_run_id::text, p_work_item_id::text,
        p_claim_token::text, p_object_locator_hash, p_object_version_hash
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_storage_claim_transition(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_storage_claim_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    run_row.class_code, run_row.adapter_version, run_row.source_mapping_version
  )
  FROM privacy_retention.privacy_retention_runs AS run_row
  WHERE run_row.id = OLD.run_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'retention_storage_claim_run_missing' USING ERRCODE = '55000';
  END IF;
  IF OLD.run_id IS DISTINCT FROM NEW.run_id
     OR OLD.work_item_id IS DISTINCT FROM NEW.work_item_id
     OR OLD.adapter_code IS DISTINCT FROM NEW.adapter_code
     OR OLD.adapter_version IS DISTINCT FROM NEW.adapter_version
     OR OLD.claim_token IS DISTINCT FROM NEW.claim_token
     OR OLD.object_locator_hash IS DISTINCT FROM NEW.object_locator_hash
     OR OLD.object_version_hash IS DISTINCT FROM NEW.object_version_hash
     OR OLD.claim_hash IS DISTINCT FROM NEW.claim_hash
     OR OLD.attempt_number IS DISTINCT FROM NEW.attempt_number
     OR OLD.claimed_at IS DISTINCT FROM NEW.claimed_at
     OR OLD.claim_expires_at IS DISTINCT FROM NEW.claim_expires_at
     OR OLD.created_at IS DISTINCT FROM NEW.created_at
     OR NOT (
       (OLD.status = 'active' AND NEW.status IN ('acknowledged', 'failed', 'expired'))
     ) THEN
    RAISE EXCEPTION 'retention_storage_claim_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  IF NEW.resolved_at IS NULL OR NEW.resolved_at < OLD.claimed_at THEN
    RAISE EXCEPTION 'retention_storage_claim_resolution_invalid' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_retention_storage_locator_hash(text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_storage_locator_hash(p_bucket_name text, p_object_name text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(p_bucket_name || E'\n' || p_object_name, 'sha256'),
    'hex'
  );
$$;


--
-- Name: g014_retention_storage_receipt_set_hash(uuid); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_storage_receipt_set_hash(p_run_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(
    extensions.digest(
      COALESCE((
        SELECT pg_catalog.string_agg(
          pg_catalog.concat_ws(
            ':', receipt.work_item_id::text, receipt.claim_token::text, receipt.claim_hash,
            receipt.object_version_hash, receipt.provider_effect_token::text, receipt.provider_receipt_ref,
            receipt.provider_receipt_hash, receipt.provider_absence_hash, receipt.verifier_ref
          ),
          E'\n' ORDER BY receipt.work_item_id, receipt.claim_hash
        )
        FROM privacy_retention.g014_retention_receipts AS receipt
        WHERE receipt.run_id = p_run_id
          AND receipt.receipt_kind = 'storage_provider_absence'
      ), ''),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: g014_retention_work_item_transition_guard(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g014_retention_work_item_transition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_run record;
BEGIN
  FOR v_run IN
    SELECT run_row.class_code, run_row.adapter_version, run_row.source_mapping_version
    FROM privacy_retention.privacy_retention_runs AS run_row
    JOIN privacy_retention.privacy_retention_run_items AS run_item
      ON run_item.run_id = run_row.id
    WHERE run_item.work_item_id = NEW.id
    ORDER BY run_row.id
  LOOP
    PERFORM privacy_retention.g014_retention_assert_run_bindings(
      v_run.class_code, v_run.adapter_version, v_run.source_mapping_version
    );
  END LOOP;
  IF OLD.class_code IS DISTINCT FROM NEW.class_code
     OR OLD.data_class IS DISTINCT FROM NEW.data_class
     OR OLD.source_type IS DISTINCT FROM NEW.source_type
     OR OLD.source_ref_hash IS DISTINCT FROM NEW.source_ref_hash
     OR OLD.subject_ref_hash IS DISTINCT FROM NEW.subject_ref_hash
     OR OLD.source_metadata_hash IS DISTINCT FROM NEW.source_metadata_hash
     OR OLD.storage_version_hash IS DISTINCT FROM NEW.storage_version_hash
     OR OLD.trigger_at IS DISTINCT FROM NEW.trigger_at
     OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
    RAISE EXCEPTION 'privacy_retention_work_item_binding_is_immutable' USING ERRCODE = '55000';
  END IF;
  IF OLD.status IS DISTINCT FROM NEW.status AND NOT (
    (OLD.status = 'pending' AND NEW.status IN ('claimed', 'separated', 'failed'))
    OR (OLD.status = 'failed' AND NEW.status IN ('pending', 'claimed', 'separated'))
    OR (OLD.status = 'claimed' AND NEW.status IN ('pending', 'purged', 'failed'))
  ) THEN
    RAISE EXCEPTION 'privacy_retention_work_item_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g016_reattest_privacy_onboarding(uuid, uuid, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g016_reattest_privacy_onboarding(p_challenge_id uuid, p_user_id uuid, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_challenge privacy_retention.privacy_onboarding_challenges%ROWTYPE;
  v_policy privacy_retention.privacy_policy_versions%ROWTYPE;
  v_profile privacy_retention.privacy_age_profiles%ROWTYPE;
  v_event_count integer := 0;
  v_audit_id uuid;
  v_idempotency_prefix text := 'onb' || pg_catalog.replace(p_challenge_id::text, '-', '');
BEGIN
  SELECT * INTO v_challenge
  FROM privacy_retention.privacy_onboarding_challenges AS challenge
  WHERE challenge.id = p_challenge_id
  FOR UPDATE;
  SELECT * INTO v_profile
  FROM privacy_retention.privacy_age_profiles AS profile
  WHERE profile.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_challenge.consumed_at IS NOT NULL
     OR v_challenge.expires_at <= pg_catalog.clock_timestamp()
     OR v_challenge.age_band <> 'age_14_plus'
     OR v_profile.age_band IS DISTINCT FROM v_challenge.age_band
     OR v_profile.status <> 'eligible' THEN
    RAISE EXCEPTION 'privacy_onboarding_reattest_invalid' USING ERRCODE = '23514';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-policy-publication-state', 0)
  );
  SELECT * INTO v_policy
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.status = 'published'
    AND policy.effective_at <= pg_catalog.clock_timestamp()
  ORDER BY policy.effective_at DESC, policy.id DESC
  LIMIT 1;
  IF NOT FOUND OR v_policy.id IS DISTINCT FROM v_challenge.policy_version_id THEN
    RAISE EXCEPTION 'privacy_current_policy_required' USING ERRCODE = '23514';
  END IF;

  UPDATE privacy_retention.privacy_age_profiles AS profile
  SET attested_at = pg_catalog.clock_timestamp(),
      method = 'self_attestation',
      status = 'eligible',
      policy_version_id = v_policy.id
  WHERE profile.user_id = p_user_id;

  INSERT INTO privacy_retention.privacy_consent_events (
    user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256,
    source, correlation_id, idempotency_key
  ) VALUES (
    p_user_id, 'self', 'privacy_required', 'none', 'granted', v_policy.id, v_policy.content_sha256,
    p_source, p_challenge_id, v_idempotency_prefix || 'required'
  );
  v_event_count := v_event_count + 1;

  IF COALESCE((v_challenge.requested_consents ->> 'email')::boolean, false) THEN
    INSERT INTO privacy_retention.privacy_consent_events (user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256, source, correlation_id, idempotency_key)
    VALUES (p_user_id, 'self', 'email_marketing', 'email', 'granted', v_policy.id, v_policy.content_sha256, p_source, p_challenge_id, v_idempotency_prefix || 'email');
    v_event_count := v_event_count + 1;
  END IF;
  IF COALESCE((v_challenge.requested_consents ->> 'sms')::boolean, false) THEN
    INSERT INTO privacy_retention.privacy_consent_events (user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256, source, correlation_id, idempotency_key)
    VALUES (p_user_id, 'self', 'sms_marketing', 'sms', 'granted', v_policy.id, v_policy.content_sha256, p_source, p_challenge_id, v_idempotency_prefix || 'sms');
    v_event_count := v_event_count + 1;
  END IF;
  IF COALESCE((v_challenge.requested_consents ->> 'push')::boolean, false) THEN
    INSERT INTO privacy_retention.privacy_consent_events (user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256, source, correlation_id, idempotency_key)
    VALUES (p_user_id, 'self', 'push_marketing', 'push', 'granted', v_policy.id, v_policy.content_sha256, p_source, p_challenge_id, v_idempotency_prefix || 'push');
    v_event_count := v_event_count + 1;
  END IF;
  IF COALESCE((v_challenge.requested_consents ->> 'night_email')::boolean, false) THEN
    INSERT INTO privacy_retention.privacy_consent_events (user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256, source, correlation_id, idempotency_key)
    VALUES (p_user_id, 'self', 'night_marketing', 'email', 'granted', v_policy.id, v_policy.content_sha256, p_source, p_challenge_id, v_idempotency_prefix || 'nightemail');
    v_event_count := v_event_count + 1;
  END IF;
  IF COALESCE((v_challenge.requested_consents ->> 'night_sms')::boolean, false) THEN
    INSERT INTO privacy_retention.privacy_consent_events (user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256, source, correlation_id, idempotency_key)
    VALUES (p_user_id, 'self', 'night_marketing', 'sms', 'granted', v_policy.id, v_policy.content_sha256, p_source, p_challenge_id, v_idempotency_prefix || 'nightsms');
    v_event_count := v_event_count + 1;
  END IF;
  IF COALESCE((v_challenge.requested_consents ->> 'night_push')::boolean, false) THEN
    INSERT INTO privacy_retention.privacy_consent_events (user_id, subject_kind, purpose, channel, decision, policy_version_id, notice_sha256, source, correlation_id, idempotency_key)
    VALUES (p_user_id, 'self', 'night_marketing', 'push', 'granted', v_policy.id, v_policy.content_sha256, p_source, p_challenge_id, v_idempotency_prefix || 'nightpush');
    v_event_count := v_event_count + 1;
  END IF;

  UPDATE privacy_retention.privacy_onboarding_challenges
  SET consumed_at = pg_catalog.clock_timestamp(), consumed_by_user_id = p_user_id
  WHERE id = p_challenge_id AND consumed_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'privacy_onboarding_transition_invalid' USING ERRCODE = '55000';
  END IF;

  v_audit_id := privacy_retention.append_privacy_audit_event_internal(
    'onboarding_confirmed', p_user_id, p_user_id, p_challenge_id, p_challenge_id, 'applied',
    'ONBOARDING_CONFIRMED',
    pg_catalog.jsonb_build_object('consentEvents', v_event_count, 'eligible', true),
    pg_catalog.jsonb_build_object('route', '/api/privacy/onboarding')
  );
  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1, 'operationId', p_challenge_id::text, 'challengeId', p_challenge_id::text,
    'userId', p_user_id::text, 'policyVersionId', v_challenge.policy_version_id::text,
    'eligible', true, 'status', 'applied',
    'readback', pg_catalog.jsonb_build_object('passed', true, 'checks', pg_catalog.jsonb_build_object(
      'challengeConsumed', true, 'ageProfileRecorded', true, 'requiredConsentRecorded', true, 'eligible', true
    )),
    'auditId', v_audit_id::text, 'errorCode', NULL, 'ageStatus', 'eligible'
  );
END;
$$;


--
-- Name: g041_current_claim_user_id(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.g041_current_claim_user_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_claims jsonb; v_role text; v_subject uuid;
BEGIN
  BEGIN
    v_claims := COALESCE(NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
    v_role := COALESCE(NULLIF(v_claims ->> 'role', ''), pg_catalog.current_setting('request.jwt.claim.role', true), '');
    v_subject := NULLIF(COALESCE(NULLIF(v_claims ->> 'sub', ''), pg_catalog.current_setting('request.jwt.claim.sub', true)), '')::uuid;
  EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN
    RETURN NULL;
  END;
  IF v_role <> 'authenticated' THEN RETURN NULL; END IF;
  RETURN v_subject;
END $$;


--
-- Name: prevent_active_class_source_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.prevent_active_class_source_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_class_code text := coalesce(new.class_code, old.class_code);
begin
  if exists (
    select 1
    from privacy_retention.privacy_retention_classes
    where code = target_class_code
      and status = 'active'
  ) then
    raise exception using errcode = '55000', message = 'active_retention_class_sources_are_versioned';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: prevent_legal_hold_history_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.prevent_legal_hold_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if old.status = 'released' then
    raise exception using errcode = '55000', message = 'released_legal_hold_is_immutable';
  end if;

  if old.subject_ref_hash is distinct from new.subject_ref_hash
    or old.data_class is distinct from new.data_class
    or old.reason_code is distinct from new.reason_code
    or old.approved_by is distinct from new.approved_by
    or old.approved_evidence_ref is distinct from new.approved_evidence_ref
    or old.expires_at is distinct from new.expires_at
    or old.created_at is distinct from new.created_at
  then
    raise exception using errcode = '55000', message = 'legal_hold_history_is_immutable';
  end if;

  return new;
end;
$$;


--
-- Name: prevent_retention_class_history_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.prevent_retention_class_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if old.status <> 'active' and new.status = 'active' then
    new.activated_at := coalesce(old.activated_at, pg_catalog.clock_timestamp());
  end if;

  if old.activated_at is not null and (
    new.data_class is distinct from old.data_class
    or new.basis_code is distinct from old.basis_code
    or new.trigger_type is distinct from old.trigger_type
    or new.retention_period is distinct from old.retention_period
    or new.approved_evidence_ref is distinct from old.approved_evidence_ref
    or new.version is distinct from old.version
    or new.activated_at is distinct from old.activated_at
  ) then
    raise exception using errcode = '55000', message = 'active_retention_class_is_versioned';
  end if;

  return new;
end;
$$;


--
-- Name: reject_tzuyang_address_evidence_admin_approval_receipt_mutation(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.reject_tzuyang_address_evidence_admin_approval_receipt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'tzuyang_address_evidence_admin_approval_receipt_immutable'
    USING ERRCODE = '55000';
END;
$$;


--
-- Name: require_service_role(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.require_service_role() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'privacy_retention_service_role_required';
  end if;
end;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  new.updated_at = pg_catalog.clock_timestamp();
  return new;
end;
$$;


--
-- Name: write_run_audit(privacy_retention.privacy_retention_runs, text, text); Type: FUNCTION; Schema: privacy_retention; Owner: -
--

CREATE FUNCTION privacy_retention.write_run_audit(p_run privacy_retention.privacy_retention_runs, p_status text, p_reason_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  audit_event_id uuid;
  v_occurred_at timestamptz := pg_catalog.clock_timestamp();
begin
  insert into privacy_retention.privacy_audit_events (
    event_type,
    actor_user_id,
    operation_id,
    correlation_id,
    preview_hash,
    status,
    reason_code,
    count_summary,
    request_metadata,
    occurred_at,
    retention_until
  ) values (
    'privacy_retention_run',
    case
      when auth.uid() is not null and exists (select 1 from auth.users where id = auth.uid()) then auth.uid()
      else null
    end,
    p_run.id,
    p_run.id,
    p_run.preview_hash,
    p_status,
    upper(p_reason_code),
    jsonb_build_object(
      'requested', p_run.scanned_count,
      'eligible', p_run.planned_count,
      'suppressed', p_run.held_count,
      'created', p_run.separated_count,
      'updated', p_run.storage_deleted_count,
      'failed', p_run.failure_count
    ),
    jsonb_build_object('route', '/api/internal/privacy-retention'),
    v_occurred_at,
    v_occurred_at + (
      select retention_period
      from privacy_retention.privacy_retention_classes
      where code = p_run.class_code
    )
  ) returning id into audit_event_id;

  return audit_event_id;
end;
$$;


--
-- Name: consume_admin_provider_counter(text, text, text, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: provider_budget_private; Owner: -
--

CREATE FUNCTION provider_budget_private.consume_admin_provider_counter(p_provider text, p_scope text, p_bucket_key text, p_max_requests integer, p_now timestamp with time zone, p_expires_at timestamp with time zone) RETURNS TABLE(allowed boolean, retry_after_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_count integer;
  v_expires_at timestamptz;
BEGIN
  IF p_provider IS NULL
     OR p_scope IS NULL
     OR p_scope NOT IN ('actor_minute', 'global_minute', 'global_day')
     OR p_bucket_key IS NULL
     OR char_length(p_bucket_key) NOT BETWEEN 1 AND 80
     OR p_max_requests IS NULL
     OR p_max_requests NOT BETWEEN 1 AND 25000
     OR p_now IS NULL
     OR p_expires_at IS NULL
     OR p_expires_at <= p_now THEN
    RAISE EXCEPTION 'admin_provider_counter_invalid' USING ERRCODE = '22023';
  END IF;

  INSERT INTO provider_budget_private.admin_provider_budget_counters AS counters (
    provider, scope, bucket_key, request_count, window_started_at, expires_at
  ) VALUES (
    p_provider, p_scope, p_bucket_key, 1, p_now, p_expires_at
  )
  ON CONFLICT (provider, scope, bucket_key) DO UPDATE
     SET request_count = CASE WHEN counters.expires_at <= p_now THEN 1 ELSE counters.request_count + 1 END,
         window_started_at = CASE WHEN counters.expires_at <= p_now THEN p_now ELSE counters.window_started_at END,
         expires_at = CASE WHEN counters.expires_at <= p_now THEN p_expires_at ELSE counters.expires_at END
  RETURNING counters.request_count, counters.expires_at
       INTO v_count, v_expires_at;

  allowed := v_count <= p_max_requests;
  retry_after_seconds := CASE
    WHEN allowed THEN 0
    ELSE pg_catalog.greatest(1, pg_catalog.ceil(EXTRACT(EPOCH FROM v_expires_at - p_now))::integer)
  END;
  RETURN NEXT;
END;
$$;


