--
-- Name: activate_account_deletion_policy(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_account_deletion_policy(p_version text, p_idempotency_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_publication privacy_retention.account_deletion_policy_publications%ROWTYPE;
  v_history privacy_retention.account_deletion_policy_activation_history%ROWTYPE;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_version IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'account_deletion_policy_activation_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF p_idempotency_key !~ '^[A-Za-z0-9._:-]{8,128}$' THEN
    RAISE EXCEPTION 'account_deletion_policy_activation_arguments_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-account-deletion-policy-activation-state', 0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-account-deletion-policy-activation:' || p_version || ':' || p_idempotency_key, 0)
  );
  SELECT * INTO v_history
  FROM privacy_retention.account_deletion_policy_activation_history
  WHERE policy_version = p_version
  FOR UPDATE;
  IF FOUND THEN
    IF v_history.activation_idempotency_key IS DISTINCT FROM p_idempotency_key THEN
      RAISE EXCEPTION 'account_deletion_policy_activation_replay_mismatch' USING ERRCODE = '55000';
    END IF;
    RETURN p_version;
  END IF;
  SELECT * INTO v_publication
  FROM privacy_retention.account_deletion_policy_publications
  WHERE policy_version = p_version
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_policy_publication_missing' USING ERRCODE = '55000';
  END IF;
  IF v_publication.source_manifest_hash IS DISTINCT FROM privacy_retention.g014_account_deletion_validate_manifest(p_version) THEN
    RAISE EXCEPTION 'account_deletion_policy_activation_manifest_mismatch' USING ERRCODE = '55000';
  END IF;
  UPDATE public.account_deletion_policies
  SET status = 'disabled'
  WHERE status = 'active' AND version IS DISTINCT FROM p_version;
  UPDATE public.account_deletion_policies
  SET status = 'active'
  WHERE version = p_version AND status = 'disabled';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_policy_activation_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  INSERT INTO privacy_retention.account_deletion_policy_activation_history (
    policy_version, activated_at, activation_idempotency_key, operator_approval_ref
  ) VALUES (
    p_version, pg_catalog.clock_timestamp(), p_idempotency_key, v_publication.operator_approval_ref
  );
  RETURN p_version;
END;
$_$;


--
-- Name: activate_privacy_retention_adapter(text, text, text, text, text, text, interval, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_privacy_retention_adapter(p_class_code text, p_adapter_code text, p_adapter_version text, p_data_class text, p_basis_code text, p_trigger_type text, p_retention_period interval, p_class_version text, p_operator_approval_ref text, p_legal_approval_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_adapter privacy_retention.retention_adapter_registry%ROWTYPE;
  v_version privacy_retention.retention_adapter_versions%ROWTYPE;
  v_class privacy_retention.privacy_retention_classes%ROWTYPE;
  v_relation regclass;
  v_identifier_type regtype;
  v_binding privacy_retention.retention_class_adapter_bindings%ROWTYPE;
  v_operator_approval privacy_retention.retention_adapter_approvals%ROWTYPE;
  v_legal_approval privacy_retention.retention_adapter_approvals%ROWTYPE;
  v_consumption privacy_retention.retention_adapter_approval_consumptions%ROWTYPE;
  v_physical_catalog_fingerprint text;
  v_activation_principal name := session_user::name;
BEGIN
  PERFORM privacy_retention.g014_retention_require_activation_operator();
  IF p_class_code IS NULL OR p_adapter_code IS NULL OR p_adapter_version IS NULL
     OR p_data_class IS NULL OR p_basis_code IS NULL OR p_trigger_type IS NULL
     OR p_retention_period IS NULL OR p_retention_period <= interval '0 seconds'
     OR p_class_version IS NULL OR p_operator_approval_ref IS NULL OR p_legal_approval_ref IS NULL
     OR p_operator_approval_ref !~ '^[A-Za-z0-9._:-]{8,128}$'
     OR p_legal_approval_ref !~ '^[A-Za-z0-9._:-]{8,128}$' THEN
    RAISE EXCEPTION 'retention_adapter_activation_arguments_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-retention-class:' || p_class_code, 0)
  );
  SELECT * INTO v_adapter
  FROM privacy_retention.retention_adapter_registry
  WHERE adapter_code = p_adapter_code;
  SELECT * INTO v_version
  FROM privacy_retention.retention_adapter_versions
  WHERE adapter_code = p_adapter_code AND adapter_version = p_adapter_version
  FOR UPDATE;
  IF NOT FOUND
     OR v_adapter.source_type IS DISTINCT FROM v_version.source_type
     OR v_adapter.removal_mode IS DISTINCT FROM v_version.removal_mode
     OR v_version.removal_mode = 'unsupported'
     OR v_version.contract_hash IS DISTINCT FROM privacy_retention.g014_retention_adapter_contract_hash(
       v_version.adapter_code, v_version.adapter_version, v_version.source_relation,
       v_version.source_identifier_column, v_version.source_type, v_version.removal_mode,
       v_version.provider_verifier_ref
     ) THEN
    RAISE EXCEPTION 'retention_adapter_contract_invalid' USING ERRCODE = '55000';
  END IF;

  v_relation := pg_catalog.to_regclass(v_version.source_relation);
  IF v_relation IS NULL THEN
    RAISE EXCEPTION 'retention_adapter_source_relation_missing' USING ERRCODE = '55000';
  END IF;
  SELECT attribute.atttypid::regtype INTO v_identifier_type
  FROM pg_catalog.pg_attribute AS attribute
  WHERE attribute.attrelid = v_relation
    AND attribute.attname = v_version.source_identifier_column
    AND attribute.attnum > 0
    AND NOT attribute.attisdropped;
  IF v_identifier_type IS NULL OR v_identifier_type NOT IN ('uuid'::regtype, 'text'::regtype) THEN
    RAISE EXCEPTION 'retention_adapter_source_identifier_invalid' USING ERRCODE = '55000';
  END IF;
  v_physical_catalog_fingerprint :=
    privacy_retention.g014_retention_catalog_fingerprint(
      v_version.source_relation, v_version.source_identifier_column
    );

  SELECT * INTO v_class
  FROM privacy_retention.privacy_retention_classes
  WHERE code = p_class_code
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'retention_class_preapproval_required' USING ERRCODE = '55000';
  ELSIF v_class.status = 'active' THEN
    IF v_class.data_class IS DISTINCT FROM p_data_class
       OR v_class.basis_code IS DISTINCT FROM p_basis_code
       OR v_class.trigger_type IS DISTINCT FROM p_trigger_type
       OR v_class.retention_period IS DISTINCT FROM p_retention_period
       OR v_class.version IS DISTINCT FROM p_class_version THEN
      RAISE EXCEPTION 'retention_class_active_version_mismatch' USING ERRCODE = '55000';
    END IF;
  ELSE
    UPDATE privacy_retention.privacy_retention_classes
    SET data_class = p_data_class,
        basis_code = p_basis_code,
        trigger_type = p_trigger_type,
        retention_period = p_retention_period,
        status = 'active',
        approved_evidence_ref = p_legal_approval_ref,
        version = p_class_version
    WHERE code = p_class_code;
  END IF;
  SELECT * INTO v_operator_approval
  FROM privacy_retention.retention_adapter_approvals AS approval_row
  WHERE approval_row.approval_kind = 'operator'
    AND approval_row.class_code = p_class_code
    AND approval_row.adapter_code = p_adapter_code
    AND approval_row.adapter_version = p_adapter_version
    AND approval_row.retention_period = p_retention_period
    AND approval_row.mapping_contract_hash = v_version.contract_hash
    AND approval_row.approval_ref = p_operator_approval_ref
    AND approval_row.signed_payload_hash IS NOT DISTINCT FROM
        privacy_retention.g014_retention_approval_payload_hash(
          'operator', p_class_code, p_adapter_code, p_adapter_version,
          p_retention_period, v_version.contract_hash, p_operator_approval_ref
        )
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'retention_operator_approval_exact_match_required' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_legal_approval
  FROM privacy_retention.retention_adapter_approvals AS approval_row
  WHERE approval_row.approval_kind = 'legal'
    AND approval_row.class_code = p_class_code
    AND approval_row.adapter_code = p_adapter_code
    AND approval_row.adapter_version = p_adapter_version
    AND approval_row.retention_period = p_retention_period
    AND approval_row.mapping_contract_hash = v_version.contract_hash
    AND approval_row.approval_ref = p_legal_approval_ref
    AND approval_row.signed_payload_hash IS NOT DISTINCT FROM
        privacy_retention.g014_retention_approval_payload_hash(
          'legal', p_class_code, p_adapter_code, p_adapter_version,
          p_retention_period, v_version.contract_hash, p_legal_approval_ref
        )
  FOR UPDATE;
  IF NOT FOUND
     OR v_operator_approval.id IS NOT DISTINCT FROM v_legal_approval.id
     OR v_operator_approval.approved_by_principal IS NULL
     OR v_legal_approval.approved_by_principal IS NULL
     OR v_activation_principal IS NULL
     OR v_operator_approval.approved_by_principal IS NOT DISTINCT FROM v_legal_approval.approved_by_principal
     OR v_activation_principal IS NOT DISTINCT FROM v_operator_approval.approved_by_principal
     OR v_activation_principal IS NOT DISTINCT FROM v_legal_approval.approved_by_principal THEN
    RAISE EXCEPTION 'retention_approval_principal_separation_required' USING ERRCODE = '55000';
  END IF;

  IF v_version.status = 'disabled' OR v_version.status = 'draft' THEN
    UPDATE privacy_retention.retention_adapter_versions
    SET status = 'active',
        operator_approval_ref = p_operator_approval_ref,
        legal_approval_ref = p_legal_approval_ref,
        activated_at = pg_catalog.clock_timestamp(),
        physical_catalog_fingerprint = v_physical_catalog_fingerprint
    WHERE adapter_code = p_adapter_code AND adapter_version = p_adapter_version;
  ELSIF v_version.status = 'active' AND (
    v_version.operator_approval_ref IS DISTINCT FROM p_operator_approval_ref
    OR v_version.legal_approval_ref IS DISTINCT FROM p_legal_approval_ref
    OR v_version.physical_catalog_fingerprint IS DISTINCT FROM v_physical_catalog_fingerprint
  ) THEN
    RAISE EXCEPTION 'retention_adapter_approval_replay_mismatch' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_consumption
  FROM privacy_retention.retention_adapter_approval_consumptions AS consumption
  WHERE consumption.class_code = p_class_code
    AND consumption.adapter_code = p_adapter_code
    AND consumption.adapter_version = p_adapter_version
  FOR UPDATE;
  IF FOUND THEN
    IF v_consumption.operator_approval_id IS DISTINCT FROM v_operator_approval.id
       OR v_consumption.legal_approval_id IS DISTINCT FROM v_legal_approval.id
       OR v_consumption.retention_period IS DISTINCT FROM p_retention_period
       OR v_consumption.mapping_contract_hash IS DISTINCT FROM v_version.contract_hash
       OR v_consumption.consumed_by_principal IS DISTINCT FROM v_activation_principal THEN
      RAISE EXCEPTION 'retention_approval_consumption_replay_mismatch' USING ERRCODE = '55000';
    END IF;
  ELSE
    INSERT INTO privacy_retention.retention_adapter_approval_consumptions (
      operator_approval_id, legal_approval_id, class_code, adapter_code,
      adapter_version, retention_period, mapping_contract_hash, consumed_by_role,
      consumed_by_principal
    ) VALUES (
      v_operator_approval.id, v_legal_approval.id, p_class_code, p_adapter_code,
      p_adapter_version, p_retention_period, v_version.contract_hash,
      'privacy_retention_activation_operator'::name, v_activation_principal
    );
  END IF;
  SELECT * INTO v_binding
  FROM privacy_retention.retention_class_adapter_bindings
  WHERE class_code = p_class_code
    AND source_type = v_version.source_type
    AND status = 'active'
  FOR UPDATE;
  IF FOUND AND (
    v_binding.adapter_code IS DISTINCT FROM p_adapter_code
    OR v_binding.adapter_version IS DISTINCT FROM p_adapter_version
    OR v_binding.mapping_contract_hash IS DISTINCT FROM v_version.contract_hash
    OR v_binding.operator_approval_ref IS DISTINCT FROM p_operator_approval_ref
    OR v_binding.legal_approval_ref IS DISTINCT FROM p_legal_approval_ref
  ) THEN
    RAISE EXCEPTION 'retention_class_source_mapping_already_active' USING ERRCODE = '55000';
  ELSIF NOT FOUND THEN
    INSERT INTO privacy_retention.retention_class_adapter_bindings (
      class_code, adapter_code, adapter_version, source_type, mapping_contract_hash,
      operator_approval_ref, legal_approval_ref
    ) VALUES (
      p_class_code, p_adapter_code, p_adapter_version, v_version.source_type,
      v_version.contract_hash, p_operator_approval_ref, p_legal_approval_ref
    );
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'classCode', p_class_code,
    'adapterCode', p_adapter_code,
    'adapterCodeVersion', p_adapter_version,
    'adapterVersion', privacy_retention.g014_retention_active_adapter_version(p_class_code),
    'sourceMappingVersion', privacy_retention.g014_retention_active_source_mapping_version(p_class_code),
    'status', 'active'
  );
END;
$_$;


--
-- Name: admin_evaluation_catalog_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_evaluation_catalog_snapshot() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  payload jsonb;
BEGIN
  IF (SELECT count(*) FROM (SELECT 1 FROM public.restaurants LIMIT 50001) counted) > 50000 THEN
    RAISE EXCEPTION 'EVALUATION_CATALOG_CAPACITY_EXCEEDED' USING ERRCODE = '54000';
  END IF;
  WITH projected AS NOT MATERIALIZED (
      SELECT r.id AS row_id, jsonb_build_object(
          'id', r.id,
          'approved_name', r.approved_name,
          'origin_name', r.origin_name,
          'naver_name', r.naver_name,
          'google_name', r.google_name,
          'status', r.status,
          'lat', r.lat,
          'lng', r.lng,
          'phone', r.phone,
          'road_address', r.road_address,
          'jibun_address', r.jibun_address,
          'english_address', r.english_address,
          'address_elements', r.address_elements,
          'origin_address', r.origin_address,
          'is_missing', r.is_missing,
          'is_not_selected', r.is_not_selected,
          'geocoding_success', r.geocoding_success,
          'geocoding_false_stage', r.geocoding_false_stage,
          'youtube_link', r.youtube_link,
          'youtube_meta', r.youtube_meta,
          'created_at', r.created_at,
          'updated_at', r.updated_at,
          'updated_by_admin_id', r.updated_by_admin_id,
          'created_by', r.created_by,
          'db_error_details', r.db_error_details,
          'db_error_message', r.db_error_message,
          'reasoning_basis', r.reasoning_basis,
          'description_map_url', r.description_map_url,
          'trace_id', r.trace_id,
          'trace_id_name_source', r.trace_id_name_source,
          'evaluation_results', r.evaluation_results,
          'categories', r.categories,
          'source_type', r.source_type,
          'tzuyang_review', r.tzuyang_review,
          'channel_name', r.channel_name,
          'recollect_version', r.recollect_version,
          'review_count', r.review_count,
          'name', r.approved_name
      ) AS record
      FROM public.restaurants r
  ), capacity AS (
    SELECT COALESCE(sum(octet_length(record::text) + 2), 0) + 128 AS bytes FROM projected
  )
  SELECT CASE WHEN bytes <= 33554432 THEN jsonb_build_object(
    'revision', (SELECT revision::text FROM pipeline_control.admin_evaluation_catalog_revision WHERE singleton),
    'records', COALESCE((SELECT jsonb_agg(record ORDER BY row_id) FROM projected), '[]'::jsonb)
  ) ELSE NULL END INTO payload FROM capacity;
  IF payload IS NULL THEN
    RAISE EXCEPTION 'EVALUATION_CATALOG_CAPACITY_EXCEEDED' USING ERRCODE = '54000';
  END IF;
  RETURN payload;
END;
$$;


--
-- Name: FUNCTION admin_evaluation_catalog_snapshot(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_evaluation_catalog_snapshot() IS 'Service-only revision-bound index input. Rejects over 50000 rows or 32MiB before aggregate; no silent truncation.';


--
-- Name: admin_evaluation_page(jsonb, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_evaluation_page(page_query jsonb, page_size integer, after_id uuid, expected_revision text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE revision text; anchor pipeline_control.admin_evaluation_read_index; ids uuid[]; result jsonb; stats jsonb; total bigint; payload_size bigint;
BEGIN
 IF page_size IS NULL OR page_size NOT BETWEEN 1 AND 200 OR jsonb_typeof(page_query) IS DISTINCT FROM 'object'
  OR octet_length(page_query::text)>8192 THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
 IF jsonb_typeof(page_query->'evalFilters') IS DISTINCT FROM 'object'
  OR jsonb_typeof(page_query->'searchQuery') IS DISTINCT FROM 'string'
  OR length(page_query->>'searchQuery')>1024
  OR (page_query->'deepLinkFilter' IS NOT NULL AND page_query->'deepLinkFilter'<>'null'::jsonb AND jsonb_typeof(page_query->'deepLinkFilter') IS DISTINCT FROM 'object')
  THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(page_query) key WHERE key NOT IN ('searchQuery','evalFilters','deepLinkFilter'))
  OR EXISTS(SELECT 1 FROM jsonb_each(page_query->'evalFilters') field WHERE field.key NOT IN
    ('status','visit_authenticity','rb_inference_score','review_faithfulness_score','rb_grounding_TF','category_validity_TF','category_TF','geocoding_success') OR jsonb_typeof(field.value)<>'string')
  THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
 IF jsonb_typeof(page_query->'deepLinkFilter')='object' AND EXISTS(SELECT 1 FROM jsonb_each(page_query->'deepLinkFilter') field
  WHERE field.key NOT IN ('videoId','issue','reason') OR jsonb_typeof(field.value)<>'string') THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
 revision:=public.admin_evaluation_revision();
 IF expected_revision IS NOT NULL AND expected_revision IS DISTINCT FROM revision THEN RAISE EXCEPTION 'EVALUATION_CURSOR_STALE'; END IF;
 IF after_id IS NOT NULL THEN
  SELECT * INTO anchor FROM pipeline_control.admin_evaluation_read_index WHERE id=after_id;
  IF NOT FOUND OR NOT pipeline_control.admin_eval_matches(anchor.descriptor,page_query) THEN RAISE EXCEPTION 'EVALUATION_CURSOR_STALE'; END IF;
 END IF;
 SELECT jsonb_build_object('total',count(*),'pending',count(*) FILTER(WHERE descriptor#>>'{flags,status}'='pending'),
  'approved',count(*) FILTER(WHERE descriptor#>>'{flags,status}'='approved'),'hold',count(*) FILTER(WHERE descriptor#>>'{flags,status}'='hold'),
  'deleted',count(*) FILTER(WHERE descriptor#>>'{flags,status}'='deleted'),'db_conflict',count(*) FILTER(WHERE descriptor#>>'{flags,status}'='db_conflict'),
  'missing',count(*) FILTER(WHERE descriptor#>'{flags,missing}'='true'::jsonb),'not_selected',count(*) FILTER(WHERE descriptor#>'{flags,not_selected}'='true'::jsonb),
  'ready_for_approval',count(*) FILTER(WHERE descriptor#>'{flags,ready_for_approval}'='true'::jsonb),
  'unconfirmed_map',count(*) FILTER(WHERE descriptor#>'{flags,unconfirmed_map}'='true'::jsonb)) INTO stats FROM pipeline_control.admin_evaluation_read_index;
 IF (stats->>'total')::bigint>50000 THEN RAISE EXCEPTION 'EVALUATION_CATALOG_CAPACITY_EXCEEDED'; END IF;
 SELECT count(*) INTO total FROM pipeline_control.admin_evaluation_read_index WHERE pipeline_control.admin_eval_matches(descriptor,page_query);
 SELECT coalesce(array_agg(id ORDER BY latest DESC,created DESC,id DESC),'{}') INTO ids FROM (
  SELECT * FROM pipeline_control.admin_evaluation_read_index WHERE pipeline_control.admin_eval_matches(descriptor,page_query)
    AND (after_id IS NULL OR (latest,created,id)<(anchor.latest,anchor.created,anchor.id))
  ORDER BY latest DESC,created DESC,id DESC LIMIT page_size+1
 ) selected;
 SELECT coalesce(sum(octet_length(pipeline_control.admin_eval_row(r)::text)+2),0)+1024 INTO payload_size FROM public.restaurants r WHERE id=ANY(ids[1:page_size]);
 IF payload_size>33554432 THEN RAISE EXCEPTION 'EVALUATION_CATALOG_CAPACITY_EXCEEDED'; END IF;
 SELECT coalesce(jsonb_agg(pipeline_control.admin_eval_row(r) ORDER BY idx.latest DESC,idx.created DESC,idx.id DESC),'[]') INTO result
  FROM public.restaurants r JOIN pipeline_control.admin_evaluation_read_index idx ON idx.id=r.id WHERE r.id=ANY(ids[1:page_size]);
 RETURN jsonb_build_object('records',result,'revision',revision,'stats',stats,'filteredTotal',total,
  'hasMore',cardinality(ids)>page_size,'afterId',CASE WHEN cardinality(ids)>page_size THEN ids[page_size] END);
END;
$$;


--
-- Name: admin_evaluation_raw_warning_groups(uuid[], text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_evaluation_raw_warning_groups(page_ids uuid[], expected_revision text, after_cursor jsonb DEFAULT NULL::jsonb, batch_size integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
DECLARE
 current_revision text; videos text[]; payload jsonb; input_bytes bigint; largest_row integer;
 total_rows integer; total_groups integer; codec text; sorted_ids jsonb; after_order integer:=0;
 boundary_id uuid; boundary_created timestamptz; actual_offset integer;

BEGIN
 current_revision:=public.admin_evaluation_revision();
 IF expected_revision IS NULL OR expected_revision !~ '^[0-9]{1,20}$'
  OR page_ids IS NULL OR cardinality(page_ids) NOT BETWEEN 1 AND 200
  OR EXISTS(SELECT 1 FROM unnest(page_ids) id WHERE id IS NULL)
  OR (SELECT count(DISTINCT id) FROM unnest(page_ids) id)<>cardinality(page_ids)
  OR batch_size IS NULL OR batch_size NOT BETWEEN 1 AND 1000 THEN
  RAISE EXCEPTION 'EVALUATION_QUERY_INVALID';
 END IF;
 IF current_revision IS DISTINCT FROM expected_revision THEN RAISE EXCEPTION 'EVALUATION_CURSOR_STALE'; END IF;
 IF (SELECT count(*) FROM (SELECT 1 FROM public.restaurants LIMIT 50001) counted)>50000 THEN
  RAISE EXCEPTION 'EVALUATION_WARNING_RAW_CAPACITY_EXCEEDED';
 END IF;
 IF (SELECT count(*) FROM pipeline_control.admin_evaluation_read_index WHERE id=ANY(page_ids))<>cardinality(page_ids) THEN
  RAISE EXCEPTION 'EVALUATION_RECORDS_UNAVAILABLE';
 END IF;
 SELECT array_agg(DISTINCT video) FILTER(WHERE video IS NOT NULL) INTO videos
 FROM pipeline_control.admin_evaluation_read_index WHERE id=ANY(page_ids);
 SELECT jsonb_agg(id ORDER BY id) INTO sorted_ids FROM unnest(page_ids) id;
 SELECT count(*) INTO total_rows FROM pipeline_control.admin_evaluation_read_index WHERE video=ANY(videos);
 IF after_cursor IS NULL THEN
  -- Small catalogs never pay grouping cost. All permitted raw attributes are
  -- retained in positional tuples; field order is versioned by codecVersion.
  IF total_rows<=200 THEN codec:='flat';
  ELSE
   -- Plan only on the first data request. Binary canonical JSON equality is
   -- lossless; this is transport compression, not a warning classifier.
   SELECT count(DISTINCT attrs COLLATE "C"),coalesce(sum(octet_length(attrs)),0),coalesce(max(octet_length(attrs)),0)
   INTO total_groups,input_bytes,largest_row
   FROM (SELECT (to_jsonb(r)-ARRAY['id','created_at','video_id'])::text attrs
    FROM public.admin_evaluation_related_rows r WHERE video_id=ANY(videos)) projected;
   IF input_bytes>67108864 OR largest_row>1048576 THEN
    RAISE EXCEPTION 'EVALUATION_WARNING_RAW_CAPACITY_EXCEEDED';
   END IF;
   -- Conservative admission: at most 1% unique and at most 200 groups.
   -- The flat codec is exact for every other admitted dataset.
   codec:=CASE WHEN total_groups<=200 AND total_groups*100<=total_rows THEN 'grouped' ELSE 'flat' END;
  END IF;
 ELSE
  IF jsonb_typeof(after_cursor)<>'object' OR after_cursor->>'revision' IS DISTINCT FROM current_revision
   OR after_cursor->'pageIds' IS DISTINCT FROM sorted_ids
   OR coalesce(after_cursor->>'mode','') NOT IN ('flat','grouped')
   OR after_cursor->>'totalRows' IS DISTINCT FROM total_rows::text
   OR coalesce(after_cursor->>'offset','') !~ '^[0-9]{1,5}$'
   OR coalesce(after_cursor->>'afterId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR NOT after_cursor ? 'afterCreated' THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
  codec:=after_cursor->>'mode'; after_order:=(after_cursor->>'offset')::integer;
  boundary_id:=(after_cursor->>'afterId')::uuid;
  -- Resolve the boundary from the database; never parse a client timestamp
  -- through Date or trust a cursor's claimed row order/membership.
  SELECT r.created_at INTO boundary_created FROM public.restaurants r
   JOIN pipeline_control.admin_evaluation_read_index i USING(id)
   WHERE r.id=boundary_id AND i.video=ANY(videos);
  IF NOT FOUND OR to_jsonb(boundary_created) IS DISTINCT FROM nullif(after_cursor->'afterCreated','null'::jsonb)
   THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
  SELECT count(*) INTO actual_offset FROM public.restaurants r
   JOIN pipeline_control.admin_evaluation_read_index i USING(id) WHERE i.video=ANY(videos) AND
    (CASE WHEN boundary_created IS NULL THEN r.created_at IS NULL AND r.id<=boundary_id
     ELSE r.created_at IS NULL OR r.created_at>boundary_created OR (r.created_at=boundary_created AND r.id<=boundary_id) END);
  IF after_order<>actual_offset OR after_order NOT BETWEEN 1 AND total_rows
   THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
 END IF;
 IF codec='grouped' AND after_cursor IS NOT NULL THEN
  SELECT coalesce(sum(bytes),0),coalesce(max(bytes),0) INTO input_bytes,largest_row
   FROM (SELECT octet_length((to_jsonb(r)-ARRAY['id','created_at','video_id'])::text) bytes
    FROM public.admin_evaluation_related_rows r WHERE video_id=ANY(videos)) sized;
  IF input_bytes>67108864 OR largest_row>1048576 THEN RAISE EXCEPTION 'EVALUATION_WARNING_RAW_CAPACITY_EXCEEDED'; END IF;
 END IF;
 IF codec='flat' THEN
  -- Bound the candidate materialization even for a fabricated service cursor.
  -- Size aggregation streams; it does not retain 1000 oversized JSON values.
  WITH keys AS MATERIALIZED (
   SELECT r.id FROM public.restaurants r JOIN pipeline_control.admin_evaluation_read_index i USING(id)
    WHERE i.video=ANY(videos) AND (after_cursor IS NULL OR
     CASE WHEN boundary_created IS NULL THEN r.created_at IS NOT NULL OR r.id>boundary_id
      ELSE r.created_at<boundary_created OR (r.created_at=boundary_created AND r.id>boundary_id) END)
    ORDER BY r.created_at DESC NULLS FIRST,r.id ASC LIMIT CASE WHEN total_rows<=200 THEN 200 ELSE batch_size END
  ) SELECT coalesce(sum(bytes),0),coalesce(max(bytes),0) INTO input_bytes,largest_row
   FROM (SELECT octet_length(to_jsonb(r)::text) bytes FROM keys JOIN public.admin_evaluation_related_rows r USING(id)) sized;
  IF input_bytes>67108864 OR largest_row>1048576 THEN RAISE EXCEPTION 'EVALUATION_WARNING_RAW_CAPACITY_EXCEEDED'; END IF;
  WITH keys AS MATERIALIZED (
   SELECT r.id,r.created_at FROM public.restaurants r JOIN pipeline_control.admin_evaluation_read_index i USING(id)
    WHERE i.video=ANY(videos) AND (after_cursor IS NULL OR
     CASE WHEN boundary_created IS NULL THEN r.created_at IS NOT NULL OR r.id>boundary_id
      ELSE r.created_at<boundary_created OR (r.created_at=boundary_created AND r.id>boundary_id) END)
    ORDER BY r.created_at DESC NULLS FIRST,r.id ASC LIMIT CASE WHEN total_rows<=200 THEN 200 ELSE batch_size END
  ), items AS MATERIALIZED (
   SELECT k.id,k.created_at,row_number() OVER(ORDER BY k.created_at DESC NULLS FIRST,k.id ASC)::integer+after_order AS ord,
    jsonb_build_array(r.id,r.created_at,r.video_id,r.approved_name,r.origin_name,r.naver_name,r.google_name,
     r.phone,r.status,r.road_address,r.jibun_address,r.youtube_link,r.updated_by_admin_id,r.lat,r.lng,r.evaluation_results,r.name) AS item
   FROM keys k JOIN public.admin_evaluation_related_rows r USING(id)
  ), packed AS (
   SELECT *,sum(octet_length(item::text)+2) OVER(ORDER BY ord) bytes FROM items
  ), selected AS MATERIALIZED (SELECT * FROM packed WHERE bytes<=2097152-16384)
  SELECT jsonb_build_object('codecVersion',1,'mode','flat','revision',current_revision,'pageIds',sorted_ids,
   'totalRows',total_rows,'rowOffset',after_order,'tuples',coalesce((SELECT jsonb_agg(item ORDER BY ord) FROM selected),'[]'::jsonb),
   'hasMore',coalesce((SELECT max(ord) FROM selected),after_order)<total_rows,
   'cursor',(SELECT jsonb_build_object('revision',current_revision,'pageIds',sorted_ids,'mode','flat','totalRows',total_rows,
    'offset',ord,'afterId',id,'afterCreated',created_at) FROM selected ORDER BY ord DESC LIMIT 1),
   'largestRow',coalesce((SELECT max(octet_length(item::text)) FROM items),0)) INTO payload;
  IF (payload->>'largestRow')::integer>1048576 OR octet_length(payload::text)>2097152
   OR (payload->>'hasMore'='true' AND (payload->'tuples'='[]'::jsonb OR total_rows<=200)) THEN
   RAISE EXCEPTION 'EVALUATION_WARNING_RAW_CAPACITY_EXCEEDED';
  END IF;
  RETURN payload-'largestRow';
 END IF;
 WITH ordered AS MATERIALIZED (
  SELECT id, (to_jsonb(r)-ARRAY['id','created_at','video_id'])::text COLLATE "C" AS attrs_key,
   row_number() OVER(ORDER BY created_at DESC,id ASC)::integer AS source_order
  FROM public.admin_evaluation_related_rows r WHERE video_id=ANY(videos)
 ), ranked AS (
  SELECT *,row_number() OVER(PARTITION BY attrs_key ORDER BY source_order) AS sample_rank FROM ordered
 ), grouped AS MATERIALIZED (
  -- No hash-only identity and no linguistic collation: byte-identical raw JSON.
  SELECT attrs_key,min(source_order) AS first_order,count(*)::integer AS row_count,
   array_agg(id ORDER BY id) FILTER(WHERE id=ANY(page_ids)) AS self_ids,
   array_agg(id ORDER BY source_order) FILTER(WHERE sample_rank<=4) AS sample_ids,
   array_agg(source_order ORDER BY source_order) FILTER(WHERE sample_rank<=4) AS sample_orders
  FROM ranked GROUP BY attrs_key
 ), candidates AS MATERIALIZED (
  SELECT * FROM grouped WHERE first_order>after_order ORDER BY first_order LIMIT batch_size
 ), items AS (
  -- Serialize only the bounded candidate batch, not all G groups on every
  -- request. Counts/offsets use the compact relational aggregate above.
  SELECT first_order,jsonb_build_object('attrs',attrs_key::jsonb,'count',row_count,'firstOrder',first_order,
   'selfIds',coalesce(to_jsonb(self_ids),'[]'::jsonb),
   'samples',(SELECT jsonb_agg(jsonb_build_object('id',id,'sourceOrder',source_order) ORDER BY source_order)
     FROM unnest(sample_ids,sample_orders) AS samples(id,source_order))) AS item FROM candidates
 ), packed AS (
  SELECT *,sum(octet_length(item::text)+2) OVER(ORDER BY first_order) AS bytes FROM items
 ), selected AS MATERIALIZED (
  SELECT * FROM packed WHERE bytes<=2097152-16384
 )
 SELECT jsonb_build_object('codecVersion',1,'mode','grouped','revision',current_revision,
  'pageIds',(SELECT jsonb_agg(id ORDER BY id) FROM unnest(page_ids) id),
  'totalRows',(SELECT count(*) FROM ordered),'totalGroups',(SELECT count(*) FROM grouped),
  'groupOffset',(SELECT count(*) FROM grouped WHERE first_order<=after_order),
  'rowOffset',coalesce((SELECT sum(row_count) FROM grouped WHERE first_order<=after_order),0),
  'cursorValid',after_order=0 OR EXISTS(SELECT 1 FROM grouped WHERE first_order=after_order),
  'groups',coalesce((SELECT jsonb_agg(item ORDER BY first_order) FROM selected),'[]'::jsonb),
  'hasMore',EXISTS(SELECT 1 FROM grouped WHERE first_order>coalesce((SELECT max(first_order) FROM selected),after_order)),
  'nextAfterOrder',coalesce((SELECT max(first_order) FROM selected),after_order)) INTO payload;
 IF (payload->>'totalGroups')::integer>200 OR (payload->>'totalGroups')::integer*100>total_rows THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
 IF payload->>'cursorValid'<>'true' THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID'; END IF;
 payload:=payload-'cursorValid';
 SELECT payload||jsonb_build_object('cursor',jsonb_build_object('revision',current_revision,'pageIds',sorted_ids,'mode','grouped',
  'totalRows',total_rows,'offset',payload->'nextAfterOrder','afterId',r.id,'afterCreated',r.created_at)) INTO payload
 FROM public.restaurants r JOIN pipeline_control.admin_evaluation_read_index i USING(id) WHERE i.video=ANY(videos)
 ORDER BY r.created_at DESC NULLS FIRST,r.id ASC OFFSET ((payload->>'nextAfterOrder')::integer-1) LIMIT 1;
 IF octet_length(payload::text)>2097152 OR (payload->>'hasMore'='true' AND payload->'groups'='[]'::jsonb) THEN
  RAISE EXCEPTION 'EVALUATION_WARNING_RAW_CAPACITY_EXCEEDED';
 END IF;
 RETURN payload;
END;
$_$;


--
-- Name: admin_evaluation_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_evaluation_revision() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT revision::text FROM pipeline_control.admin_evaluation_catalog_revision WHERE singleton;
$$;


--
-- Name: admin_evaluation_warning_groups(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_evaluation_warning_groups(page_ids uuid[], expected_revision text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
DECLARE revision text;result jsonb;groups jsonb;source_bytes bigint;largest_row integer;
BEGIN
 IF page_ids IS NULL OR cardinality(page_ids)>200 OR cardinality(page_ids)<>(SELECT count(DISTINCT id) FROM unnest(page_ids) id)
  OR expected_revision IS NULL OR expected_revision!~'^[0-9]{1,20}$' THEN RAISE EXCEPTION 'EVALUATION_QUERY_INVALID';END IF;
 revision:=public.admin_evaluation_revision();
 IF revision IS DISTINCT FROM expected_revision THEN RAISE EXCEPTION 'EVALUATION_CURSOR_STALE';END IF;
 -- Check the server family before resolving version-specific Unicode helpers.
 -- An explicit opt-in on another family can then use the JS admission fallback.
 IF current_setting('server_version_num')::integer/10000<>17 THEN RAISE EXCEPTION 'EVALUATION_WARNING_UNICODE_UNSUPPORTED';END IF;
 IF unicode_version()<>'15.1' OR EXISTS(SELECT 1 FROM pg_collation WHERE oid IN
  ('pipeline_control.admin_warning_order'::regcollation,'pipeline_control.admin_warning_case'::regcollation)
  AND pg_collation_actual_version(oid) IS DISTINCT FROM '153.136') THEN RAISE EXCEPTION 'EVALUATION_WARNING_UNICODE_UNSUPPORTED';END IF;
 IF (SELECT count(*) FROM pipeline_control.admin_evaluation_read_index)>50000 THEN RAISE EXCEPTION 'EVALUATION_RECORDS_UNAVAILABLE';END IF;
 IF (SELECT count(*) FROM public.restaurants WHERE id=ANY(page_ids))<>cardinality(page_ids) THEN RAISE EXCEPTION 'EVALUATION_CURSOR_STALE';END IF;
 -- Bound materialization before normalization/sorting, not only the final JSON.
 SELECT coalesce(sum(octet_length(to_jsonb(r)::text)),0),coalesce(max(octet_length(to_jsonb(r)::text)),0)
 INTO source_bytes,largest_row FROM public.admin_evaluation_related_rows r
 WHERE r.id=ANY(page_ids) OR r.video_id IN (SELECT video FROM pipeline_control.admin_evaluation_read_index WHERE id=ANY(page_ids));
 IF source_bytes>33554432 OR largest_row>8192 THEN RAISE EXCEPTION 'EVALUATION_WARNING_CAPACITY_EXCEEDED';END IF;
 WITH targets AS MATERIALIZED (
  SELECT r.id,r.video_id AS video,pipeline_control.admin_warning_info(to_jsonb(r)) AS info
  FROM public.admin_evaluation_related_rows r WHERE r.id=ANY(page_ids)
 ), related AS MATERIALIZED (
  SELECT r.id,r.created_at,r.video_id AS video,pipeline_control.admin_warning_info(to_jsonb(r)) AS info
  FROM public.admin_evaluation_related_rows r WHERE r.video_id IN (SELECT video FROM targets WHERE video IS NOT NULL)
 ), ranked AS MATERIALIZED (
  SELECT id,created_at,video,info->'shape' AS shape,info->>'name' AS name,row_number() OVER(PARTITION BY video,info->'shape' ORDER BY (info->>'name') COLLATE pipeline_control.admin_warning_order,created_at DESC,id ASC) AS position,
   row_number() OVER(PARTITION BY video,info#>>'{shape,identity}' ORDER BY (info->>'name') COLLATE pipeline_control.admin_warning_order,created_at DESC,id ASC) AS identity_position
  FROM related WHERE info->>'status'<>'deleted'
 ), related_groups AS MATERIALIZED (
  SELECT row_number() OVER() AS gid,video,shape,count(*) AS total,
   array_agg(id ORDER BY position) FILTER(WHERE position<=4) AS candidates
  FROM ranked GROUP BY video,shape
 ), identity_groups AS MATERIALIZED (
  SELECT video,shape->>'identity' AS identity,count(*) AS total,
   array_agg(id ORDER BY identity_position) FILTER(WHERE identity_position<=4) AS candidates
  FROM ranked WHERE shape->>'identity'<>'' GROUP BY video,shape->>'identity'
 ), target_shapes AS MATERIALIZED (
  SELECT row_number() OVER() AS tid,video,shape FROM
   (SELECT DISTINCT video,info->'shape' AS shape FROM targets WHERE video IS NOT NULL AND info->>'status'<>'deleted') d
 ), t_keys AS MATERIALIZED (
  SELECT *,shape->>'identity' AS identity,shape->>'phone' AS phone,shape->>'address' AS address,cardinality(pipeline_control.admin_warning_utf16(shape->>'identity')) AS name_length,pipeline_control.admin_warning_cell(shape) AS cell FROM target_shapes
 ), r_keys AS MATERIALIZED (
  SELECT *,shape->>'identity' AS identity,shape->>'phone' AS phone,shape->>'address' AS address,cardinality(pipeline_control.admin_warning_utf16(shape->>'identity')) AS name_length,pipeline_control.admin_warning_cell(shape) AS cell FROM related_groups
 ), t_cells AS MATERIALIZED (
  SELECT t.tid,t.video,t.identity,ARRAY[t.cell[1]+x,t.cell[2]+y,t.cell[3]+z] AS cell
  FROM t_keys t CROSS JOIN generate_series(-1,1) x CROSS JOIN generate_series(-1,1) y CROSS JOIN generate_series(-1,1) z WHERE t.cell IS NOT NULL
 ), t_gates AS MATERIALIZED (
  SELECT video,'phone' AS kind,phone AS key,identity,array_agg(tid) AS ids FROM t_keys
   WHERE length(phone)>=7 AND identity<>'' GROUP BY video,phone,identity
  UNION ALL
  SELECT video,'address',address,identity,array_agg(tid) FROM t_keys
   WHERE address<>'' AND identity<>'' GROUP BY video,address,identity
  UNION ALL
  SELECT video,'cell',cell::text,identity,array_agg(tid) FROM t_cells WHERE identity<>'' GROUP BY video,cell,identity
 ), r_gates AS MATERIALIZED (
  SELECT video,'phone' AS kind,phone AS key,identity,array_agg(gid) AS ids FROM r_keys
   WHERE length(phone)>=7 AND identity<>'' GROUP BY video,phone,identity
  UNION ALL
  SELECT video,'address',address,identity,array_agg(gid) FROM r_keys
   WHERE address<>'' AND identity<>'' GROUP BY video,address,identity
  UNION ALL
  SELECT video,'cell',cell::text,identity,array_agg(gid) FROM r_keys WHERE cell IS NOT NULL AND identity<>'' GROUP BY video,cell,identity
 ), gate_pairs AS MATERIALIZED (
  -- Coalesce each gate AND identity before comparing. Otherwise 200 different
  -- physical shapes sharing one name/phone still scan 10m equal-name pairs.
  SELECT t.ids AS tids,r.ids AS gids FROM t_gates t JOIN r_gates r ON r.video=t.video AND r.kind=t.kind AND r.key=t.key
  WHERE t.identity<>r.identity LIMIT 25001
 ), raw_pairs AS MATERIALIZED (
  -- Stop at limit+1 before deduplication; never construct the full dense pair set.
  SELECT tid,gid FROM gate_pairs p CROSS JOIN LATERAL unnest(p.tids) tid CROSS JOIN LATERAL unnest(p.gids) gid LIMIT 25001
 ), pairs AS MATERIALIZED (SELECT DISTINCT tid,gid FROM raw_pairs),
 budget AS MATERIALIZED (
  SELECT pipeline_control.admin_warning_budget((SELECT count(*) FROM raw_pairs),coalesce(sum(
   t.name_length*r.name_length),0)::bigint) AS admitted
  FROM pairs p JOIN t_keys t ON t.tid=p.tid JOIN r_keys r ON r.gid=p.gid
 ), matches AS MATERIALIZED (
  SELECT t.video,t.shape,r.total,r.candidates,pipeline_control.admin_warning_evidence(t.shape,r.shape) AS evidence
  FROM pairs p JOIN t_keys t ON t.tid=p.tid JOIN r_keys r ON r.gid=p.gid WHERE (SELECT admitted FROM budget)
 ), matched AS MATERIALIZED (
  SELECT * FROM matches WHERE evidence IS NOT NULL
  UNION ALL
  SELECT t.video,t.shape,r.total,r.candidates,jsonb_build_object('rule','exact_identity','confidence',1)
  FROM t_keys t JOIN identity_groups r ON r.video=t.video AND r.identity=t.identity WHERE (SELECT admitted FROM budget)
 ), counts AS (SELECT video,shape,sum(total) AS total FROM matched GROUP BY video,shape),
 candidate_pool AS MATERIALIZED (
  SELECT m.video,m.shape,id,m.evidence FROM matched m CROSS JOIN LATERAL unnest(m.candidates) id
 ), tops AS MATERIALIZED (
  SELECT p.*,row_number() OVER(PARTITION BY p.video,p.shape ORDER BY (p.evidence->>'confidence')::double precision DESC,
   (r.info->>'name') COLLATE pipeline_control.admin_warning_order,r.created_at DESC,r.id ASC) AS position
  FROM candidate_pool p JOIN related r ON r.id=p.id
 ), top_groups AS (
  SELECT t.video,t.shape,jsonb_agg((r.info-ARRAY['origin_name','candidate_name','originKey','candidateKey','shape'])||t.evidence ORDER BY t.position) AS candidates
  FROM tops t JOIN related r ON r.id=t.id WHERE t.position<=4 GROUP BY t.video,t.shape
 ), deleted_shapes AS MATERIALIZED (
  SELECT row_number() OVER() AS did,video,origin_key,candidate_key FROM (
   SELECT DISTINCT video,info->>'originKey' AS origin_key,info->>'candidateKey' AS candidate_key FROM targets
   WHERE video IS NOT NULL AND info->>'status'<>'deleted') d
 ), deleted_ranked AS MATERIALIZED (
  SELECT id,created_at,video,info->>'originKey' AS origin_key,info->>'candidateKey' AS candidate_key,row_number() OVER(PARTITION BY video,info->>'originKey' ORDER BY created_at DESC,id ASC) AS origin_position,
   row_number() OVER(PARTITION BY video,info->>'candidateKey' ORDER BY created_at DESC,id ASC) AS candidate_position
  FROM related WHERE info->>'status'='deleted'
 ), deleted_origin AS MATERIALIZED (
  SELECT video,origin_key AS key,count(*) AS total,array_agg(id ORDER BY origin_position) FILTER(WHERE origin_position<=3) AS samples
  FROM deleted_ranked WHERE origin_key<>'' GROUP BY video,origin_key
 ), deleted_candidate AS MATERIALIZED (
  SELECT video,candidate_key AS key,count(*) AS total,array_agg(id ORDER BY candidate_position) FILTER(WHERE candidate_position<=3) AS samples
  FROM deleted_ranked WHERE candidate_key<>'' GROUP BY video,candidate_key
 ), deleted_overlap AS MATERIALIZED (
  SELECT video,origin_key,candidate_key,count(*) AS total
  FROM deleted_ranked GROUP BY video,origin_key,candidate_key
 ), deleted_groups AS (
  -- Inclusion/exclusion counts each deleted row once. Only six sample IDs per
  -- target survive; 200 different names sharing one deleted-name group do not
  -- materialize 200 x 50,000 deleted rows.
  SELECT d.video,d.origin_key,d.candidate_key,
   coalesce(o.total,0)+coalesce(c.total,0)-CASE WHEN d.origin_key<>'' AND d.candidate_key<>'' THEN coalesce(b.total,0) ELSE 0 END AS total,
   (SELECT jsonb_agg(jsonb_build_object('id',r.info->>'id','origin_name',r.info->>'origin_name','candidate_name',r.info->>'candidate_name') ORDER BY r.created_at DESC,r.id)
    FROM (SELECT item.id FROM (SELECT DISTINCT unnest(coalesce(o.samples,'{}'::uuid[])||coalesce(c.samples,'{}'::uuid[])) AS id) item
     JOIN related x ON x.id=item.id ORDER BY x.created_at DESC,x.id LIMIT 3) samples JOIN related r ON r.id=samples.id) AS samples
  FROM deleted_shapes d LEFT JOIN deleted_origin o ON o.video=d.video AND o.key=d.origin_key
   LEFT JOIN deleted_candidate c ON c.video=d.video AND c.key=d.candidate_key
   LEFT JOIN deleted_overlap b ON b.video=d.video AND b.origin_key=d.origin_key AND b.candidate_key=d.candidate_key
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,
   'sameVideo',jsonb_build_object('count',greatest(0,coalesce(c.total,0)-CASE WHEN own.info->>'status'<>'deleted' AND pipeline_control.admin_warning_evidence(t.info->'shape',own.info->'shape') IS NOT NULL THEN 1 ELSE 0 END),
    'candidates',coalesce((SELECT jsonb_agg(item.value ORDER BY item.ordinality) FROM (
      SELECT value,ordinality FROM jsonb_array_elements(coalesce(g.candidates,'[]')) WITH ORDINALITY
       WHERE value->>'id'<>t.id::text ORDER BY ordinality LIMIT 3) item),'[]')),
   'deleted',jsonb_build_object('count',coalesce(d.total,0),'samples',coalesce(d.samples,'[]'))
  ) ORDER BY t.id),'[]') INTO groups
 FROM targets t LEFT JOIN counts c ON t.info->>'status'<>'deleted' AND c.video=t.video AND c.shape=t.info->'shape'
 LEFT JOIN top_groups g ON t.info->>'status'<>'deleted' AND g.video=t.video AND g.shape=t.info->'shape'
 LEFT JOIN related own ON own.id=t.id
 LEFT JOIN deleted_groups d ON t.info->>'status'<>'deleted' AND d.video=t.video AND d.origin_key=t.info->>'originKey' AND d.candidate_key=t.info->>'candidateKey';
 result:=jsonb_build_object('revision',revision,'groups',groups);
 IF octet_length(result::text)>8*1024*1024 THEN RAISE EXCEPTION 'EVALUATION_RECORDS_UNAVAILABLE';END IF;
 RETURN result;
END;
$_$;


--
-- Name: admin_record_action(uuid, text, uuid, text, uuid[], jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_record_action(p_actor uuid, p_phase text, p_operation_id uuid, p_action text DEFAULT NULL::text, p_target_ids uuid[] DEFAULT '{}'::uuid[], p_payload jsonb DEFAULT '{}'::jsonb, p_preview_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
<<work>>
DECLARE op pipeline_control.admin_record_operations; ids uuid[]; fingerprint jsonb; after_state jsonb; digest text;
 receipt jsonb; audit uuid; row_value jsonb; changed jsonb; item jsonb; target uuid; created uuid; source_id uuid;
 classification text; conflict_constraint text; photo text; media record; job pipeline_control.admin_record_media_cleanup; expected_count integer; pending_count integer; final_rows jsonb; final_row jsonb; key_name text; related_ids uuid[];
BEGIN
 PERFORM pipeline_control.admin_record_assert_operator(p_actor);
 IF current_user NOT IN ('service_role','postgres') OR p_operation_id IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_FORBIDDEN'; END IF;
 PERFORM set_config('lock_timeout','2s',true);
 PERFORM pg_advisory_xact_lock(hashtextextended('admin-record:'||p_operation_id,0));
 SELECT * INTO op FROM pipeline_control.admin_record_operations WHERE id=p_operation_id FOR UPDATE;
 IF FOUND AND op.actor<>p_actor THEN RAISE EXCEPTION 'RECORD_ACTION_FORBIDDEN'; END IF;
 IF p_phase='readback' THEN
  IF op.id IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_NOT_FOUND'; END IF;
  IF op.state='preview' AND op.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'RECORD_ACTION_PREVIEW_EXPIRED'; END IF;
  RETURN op.receipt||jsonb_build_object('mediaCleanupUnmanaged',op.cleanup_blocked,'mediaCleanupPending',EXISTS(SELECT 1 FROM pipeline_control.admin_record_media_cleanup WHERE operation_id=op.id AND state<>'done'));
 END IF;
 IF p_phase LIKE 'cleanup_%' THEN
  PERFORM pg_advisory_xact_lock(741093, 1);
  IF op.id IS NULL OR op.state<>'applied' OR op.action<>'review.delete' THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
  IF p_phase='cleanup_read' THEN
   RETURN jsonb_build_object('jobs',coalesce((SELECT jsonb_agg(jsonb_build_object('id',page.id,'bucket',page.bucket,'objectName',page.object_name,'state',page.state) ORDER BY page.id)
     FROM (SELECT id,bucket,object_name,state FROM pipeline_control.admin_record_media_cleanup
       WHERE operation_id=op.id AND state<>'done' ORDER BY id LIMIT 25) page),'[]'::jsonb));
  END IF;
  SELECT * INTO job FROM pipeline_control.admin_record_media_cleanup WHERE operation_id=op.id AND id=(p_payload->>'jobId')::uuid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'RECORD_ACTION_NOT_FOUND'; END IF;
  IF p_phase='cleanup_claim' AND job.state='pending' THEN
   PERFORM pg_advisory_xact_lock(hashtextextended('review-media:'||job.bucket||':'||job.object_name,0));
   IF EXISTS(SELECT 1 FROM public.reviews WHERE verification_photo=job.object_name OR job.object_name=ANY(food_photos))
     OR job.object_fingerprint IS DISTINCT FROM pipeline_control.admin_record_storage_snapshot(job.bucket,job.object_name) THEN
    -- A new reference or changed object is protected, not a failed database moderation.
    DELETE FROM pipeline_control.admin_record_media_cleanup WHERE id=job.id;
    UPDATE pipeline_control.admin_record_operations SET cleanup_blocked=true WHERE id=op.id;
    RETURN jsonb_build_object('ok',true,'claimed',false);
   END IF;
   UPDATE pipeline_control.admin_record_media_cleanup SET state='inflight' WHERE id=job.id;
   RETURN jsonb_build_object('ok',true,'claimed',true);
  ELSIF p_phase='cleanup_absent' THEN
   PERFORM pg_advisory_xact_lock(hashtextextended('review-media:'||job.bucket||':'||job.object_name,0));
   IF pipeline_control.admin_record_storage_snapshot(job.bucket,job.object_name) IS NOT NULL THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
   UPDATE pipeline_control.admin_record_media_cleanup SET state='done' WHERE id=job.id;
  ELSIF p_phase='cleanup_uncertain' AND job.state='inflight' THEN
   UPDATE pipeline_control.admin_record_media_cleanup SET state='uncertain' WHERE id=job.id;
  ELSE RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
  RETURN jsonb_build_object('ok',true);
 END IF;
 IF p_phase NOT IN ('preview','apply') OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>65536
  OR p_action NOT IN ('restaurant.approve','restaurant.edit','restaurant.create','restaurant.delete','restaurant.restore','restaurant.register_missing','restaurant.merge','restaurant.hold',
    'submission.approve','submission.reject','submission.delete','submission.edit','review.approve','review.reject','review.delete','recommendation.approve','recommendation.reject')
  THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
 SELECT coalesce(array_agg(x ORDER BY x),'{}'::uuid[]) INTO ids FROM unnest(p_target_ids) x;
 IF cardinality(ids)<>(CASE WHEN p_action='restaurant.create' THEN 0 WHEN p_action='restaurant.merge' THEN 2 WHEN p_action='restaurant.edit' THEN cardinality(ids) ELSE 1 END)
  OR (p_action='restaurant.edit' AND cardinality(ids) NOT BETWEEN 1 AND 25)
  OR array_position(ids,NULL) IS NOT NULL OR (SELECT count(*)<>count(DISTINCT x) FROM unnest(ids) x)
  THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
 IF (p_action IN ('restaurant.delete','restaurant.hold','submission.reject','submission.delete','review.reject','review.delete','recommendation.reject') AND (nullif(btrim(p_payload->>'reason'),'') IS NULL OR length(p_payload->>'reason')>500)) OR length(p_payload->>'note')>500 THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
 digest:=pipeline_control.admin_record_hash(p_payload);
 IF op.id IS NOT NULL THEN
  IF op.action IS DISTINCT FROM p_action OR op.target_ids IS DISTINCT FROM ids OR op.payload_sha IS DISTINCT FROM digest THEN RAISE EXCEPTION 'RECORD_ACTION_IDEMPOTENCY_CONFLICT'; END IF;
  IF p_phase='apply' AND p_preview_hash IS DISTINCT FROM op.preview_hash THEN RAISE EXCEPTION 'RECORD_ACTION_PREVIEW_MISMATCH'; END IF;
  IF op.state='applied' THEN RETURN op.receipt; END IF;
  IF op.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'RECORD_ACTION_PREVIEW_EXPIRED'; END IF;
 ELSIF p_phase='apply' THEN RAISE EXCEPTION 'RECORD_ACTION_PREVIEW_REQUIRED'; END IF;
 -- One deterministic lock order also excludes new duplicate inserts and review counter races.
 -- These short bounded transactions never contain a provider/storage call.
 LOCK TABLE public.reviews,public.restaurants,public.restaurant_submissions,public.restaurant_submission_items,public.restaurant_requests IN SHARE ROW EXCLUSIVE MODE;
 IF p_action='review.delete' THEN
  PERFORM pg_advisory_xact_lock(741093, 1);
  FOR media IN SELECT candidate.bucket,candidate.object_name FROM public.reviews r
   CROSS JOIN LATERAL pipeline_control.admin_record_review_media(to_jsonb(r)) candidate
   WHERE r.id=ids[1] ORDER BY candidate.bucket,candidate.object_name LOOP
   PERFORM pg_advisory_xact_lock(hashtextextended('review-media:'||media.bucket||':'||media.object_name,0));
  END LOOP;
 END IF;
 fingerprint:=pipeline_control.admin_record_snapshot(p_action,ids);
 IF op.id IS NOT NULL AND fingerprint IS DISTINCT FROM op.expected THEN RAISE EXCEPTION 'RECORD_ACTION_STALE'; END IF;
 IF p_phase='preview' THEN
  IF op.id IS NOT NULL THEN RETURN op.receipt; END IF;
  receipt:=jsonb_build_object('operationId',p_operation_id,'action',p_action,'state','preview','targetIds',ids,'auditId',NULL,
    'previewHash',pipeline_control.admin_record_hash(jsonb_build_array(p_actor,p_operation_id,p_action,ids,digest,fingerprint)),
    'expiresAt',clock_timestamp()+interval '15 minutes','readback',pipeline_control.admin_record_readback(fingerprint),'mediaCleanupPending',false);
  INSERT INTO pipeline_control.admin_record_operations(id,actor,action,target_ids,payload_sha,expected,preview_hash,expires_at,state,receipt)
   VALUES(p_operation_id,p_actor,p_action,ids,digest,fingerprint,receipt->>'previewHash',(receipt->>'expiresAt')::timestamptz,'preview',receipt);
  RETURN receipt;
 END IF;
 audit:=gen_random_uuid(); target:=ids[1];
 IF p_action LIKE 'restaurant.%' THEN
  SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE id=target;
  IF p_action='restaurant.create' THEN
   IF jsonb_typeof(coalesce(p_payload->'additions','[]'::jsonb))<>'array' OR jsonb_array_length(coalesce(p_payload->'additions','[]'::jsonb))>24 THEN RAISE EXCEPTION 'RECORD_ACTION_LIMIT'; END IF;
   created:=pipeline_control.admin_record_create(p_payload->'changes',p_actor); ids:=ARRAY[created];
   FOR changed IN SELECT value FROM jsonb_array_elements(coalesce(p_payload->'additions','[]'::jsonb)) LOOP
    created:=pipeline_control.admin_record_create(changed,p_actor); ids:=array_append(ids,created);
   END LOOP;
  ELSIF p_action='restaurant.edit' THEN
   IF jsonb_typeof(coalesce(p_payload->'perTargetChanges','[]'::jsonb))<>'array'
    OR jsonb_typeof(coalesce(p_payload->'removeIds','[]'::jsonb))<>'array' OR jsonb_typeof(coalesce(p_payload->'additions','[]'::jsonb))<>'array'
    OR cardinality(ids)+jsonb_array_length(coalesce(p_payload->'additions','[]'::jsonb))>25
    OR cardinality(ids)-jsonb_array_length(coalesce(p_payload->'removeIds','[]'::jsonb))+jsonb_array_length(coalesce(p_payload->'additions','[]'::jsonb))<1
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_payload->'perTargetChanges','[]'::jsonb)) x WHERE NOT ((x->>'id')::uuid=ANY(ids)))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_payload->'perTargetChanges','[]'::jsonb)) x GROUP BY x->>'id' HAVING count(*)>1)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p_payload->'removeIds','[]'::jsonb)) x WHERE NOT (x::uuid=ANY(ids)))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p_payload->'removeIds','[]'::jsonb)) x GROUP BY x HAVING count(*)>1)
    THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   final_rows:='{}'::jsonb;
   FOREACH target IN ARRAY ids LOOP
    SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE id=target;
    IF row_value->>'status'='deleted' THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
    IF coalesce(p_payload->'removeIds','[]'::jsonb) ? target::text THEN
     IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_payload->'perTargetChanges','[]'::jsonb)) x WHERE x->>'id'=target::text) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
    ELSE
     SELECT value->'changes' INTO changed FROM jsonb_array_elements(coalesce(p_payload->'perTargetChanges','[]'::jsonb)) WHERE value->>'id'=target::text;
     final_row:=pipeline_control.admin_record_compose(row_value,(p_payload->'changes')||coalesce(changed,'{}'::jsonb));
     PERFORM pipeline_control.admin_record_identity_check(final_row,ids);
     final_rows:=final_rows||jsonb_build_object(target::text,final_row);
    END IF;
   END LOOP;
   -- The canonical unique index is immediate. Vacate claimed video identities only inside this transaction,
   -- then write saved final rows; any final collision rolls the entire transaction back.
   UPDATE public.restaurants SET youtube_link=NULL WHERE id=ANY(ids) AND final_rows ? id::text;
   UPDATE public.restaurants SET status='deleted',updated_by_admin_id=p_actor,updated_at=clock_timestamp()
    WHERE id=ANY(ids) AND NOT(final_rows ? id::text);
   FOR key_name,final_row IN SELECT key,value FROM jsonb_each(final_rows) ORDER BY key LOOP
    PERFORM pipeline_control.admin_record_identity_check(final_row,ARRAY[key_name::uuid]);
    PERFORM pipeline_control.admin_record_write(key_name::uuid,final_row,p_actor,false);
   END LOOP;
   FOR changed IN SELECT value FROM jsonb_array_elements(coalesce(p_payload->'additions','[]'::jsonb)) LOOP
    created:=pipeline_control.admin_record_create(changed,p_actor);ids:=array_append(ids,created);
   END LOOP;
  ELSIF p_action='restaurant.register_missing' THEN
   IF p_action='restaurant.register_missing' AND row_value->'is_missing' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
   PERFORM pipeline_control.admin_record_patch(target,p_payload->'changes',p_actor,p_action='restaurant.register_missing');
  ELSIF p_action='restaurant.approve' THEN
   IF row_value->>'status' NOT IN ('pending','hold') THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
   row_value:=pipeline_control.admin_record_compose(row_value,coalesce(p_payload->'changes','{}'::jsonb));
   IF nullif(btrim(row_value->>'approved_name'),'') IS NULL THEN
    row_value:=row_value||jsonb_build_object('approved_name',public.resolve_restaurant_identity_name(row_value->>'approved_name',row_value->>'origin_name',row_value->>'naver_name',row_value->>'google_name'));
   END IF;
   -- Explicit human approval may revisit a held/admin-owned row, but cannot invent evaluation evidence.
   classification:=pipeline_control.restaurant_review_decision(row_value||jsonb_build_object('status','pending','updated_by_admin_id',NULL,'created_by',NULL,'source_type','crawler'));
   IF classification<>'approve:all_checks_passed' THEN RAISE EXCEPTION 'RECORD_ACTION_EVIDENCE_REQUIRED'; END IF;
   PERFORM pipeline_control.admin_record_validate_restaurant(row_value,ARRAY[target]);
   PERFORM pipeline_control.admin_record_write(target,row_value,p_actor,true);
  ELSIF p_action='restaurant.merge' THEN
   target:=(p_payload->>'mergeTargetId')::uuid;
   IF NOT target=ANY(ids) THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   SELECT x INTO source_id FROM unnest(ids) x WHERE x<>target;
   SELECT to_jsonb(r) INTO changed FROM public.restaurants r WHERE id=target;
   SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE id=source_id;
   IF row_value->>'status'='deleted' OR changed->>'status'='deleted' THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
   row_value:=pipeline_control.admin_record_compose(row_value,coalesce(p_payload->'incomingChanges','{}'::jsonb));
   -- Fill missing target business information; preserve populated administrator fields and all evaluation JSON.
   FOREACH key_name IN ARRAY ARRAY['approved_name','phone','road_address','jibun_address','english_address','address_elements','lat','lng','geocoding_success'] LOOP
    IF changed->key_name IS NULL OR changed->key_name IN ('null'::jsonb,'""'::jsonb,'{}'::jsonb,'false'::jsonb) THEN changed:=changed||jsonb_build_object(key_name,row_value->key_name); END IF;
   END LOOP;
   changed:=changed||jsonb_build_object('categories',(SELECT coalesce(jsonb_agg(x ORDER BY x),'[]'::jsonb) FROM (SELECT DISTINCT value x FROM jsonb_array_elements(coalesce(nullif(changed->'categories','null'::jsonb),'[]'::jsonb)||coalesce(nullif(row_value->'categories','null'::jsonb),'[]'::jsonb))) c));
   IF nullif(changed->>'youtube_link','') IS NULL OR public.extract_youtube_video_id(changed->>'youtube_link')=public.extract_youtube_video_id(row_value->>'youtube_link') THEN
    changed:=changed||jsonb_build_object('youtube_link',coalesce(nullif(changed->>'youtube_link',''),row_value->>'youtube_link'),
     'youtube_meta',coalesce(nullif(row_value->'youtube_meta','null'::jsonb),'{}'::jsonb)||coalesce(nullif(changed->'youtube_meta','null'::jsonb),'{}'::jsonb),
     'tzuyang_review',coalesce(nullif(changed->>'tzuyang_review',''),row_value->>'tzuyang_review'));
    UPDATE public.restaurants SET status='deleted',updated_by_admin_id=p_actor,updated_at=clock_timestamp(),db_error_message=NULL,db_error_details=NULL WHERE id=source_id;
   ELSE
    -- A different video remains a separate active link row; retain its own video metadata, review and evaluation.
    FOREACH key_name IN ARRAY ARRAY['approved_name','phone','categories','road_address','jibun_address','english_address','address_elements','lat','lng','geocoding_success'] LOOP
     row_value:=row_value||jsonb_build_object(key_name,changed->key_name);
    END LOOP;
    PERFORM pipeline_control.admin_record_identity_check(row_value,ARRAY[source_id]);
    PERFORM pipeline_control.admin_record_write(source_id,row_value,p_actor,false);
    UPDATE public.restaurants SET db_error_message=NULL,db_error_details=NULL WHERE id=source_id;
   END IF;
   PERFORM pipeline_control.admin_record_identity_check(changed,ARRAY[target]);
   PERFORM pipeline_control.admin_record_write(target,changed,p_actor,false);
  ELSE
   IF p_action='restaurant.restore' THEN
    IF row_value->>'status'<>'deleted' THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
    IF EXISTS(SELECT 1 FROM public.restaurants r WHERE id<>target AND status<>'deleted' AND public.extract_youtube_video_id(r.youtube_link)=public.extract_youtube_video_id(row_value->>'youtube_link') AND public.normalize_restaurant_identity_name(r.approved_name)=public.normalize_restaurant_identity_name(row_value->>'approved_name')) THEN RAISE EXCEPTION 'RECORD_ACTION_DUPLICATE'; END IF;
   ELSIF row_value->>'status'='deleted' THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
   UPDATE public.restaurants SET status=CASE p_action WHEN 'restaurant.delete' THEN 'deleted' WHEN 'restaurant.restore' THEN 'pending' ELSE 'hold' END,
     updated_by_admin_id=p_actor,updated_at=clock_timestamp() WHERE id=target;
  END IF;
 ELSIF p_action LIKE 'submission.%' THEN
  SELECT to_jsonb(s) INTO row_value FROM public.restaurant_submissions s WHERE id=target;
  IF row_value->>'status' NOT IN ('pending','partially_approved') THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
  IF p_action='submission.edit' THEN
   changed:=p_payload->'changes';
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'itemChanges') x GROUP BY x->>'id' HAVING count(*)>1)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'itemChanges') x WHERE NOT EXISTS(SELECT 1 FROM public.restaurant_submission_items WHERE id=(x->>'id')::uuid AND submission_id=target AND item_status='pending'))
    THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   UPDATE public.restaurant_submissions SET restaurant_name=changed->>'restaurant_name',restaurant_address=CASE WHEN changed ? 'restaurant_address' THEN changed->>'restaurant_address' ELSE restaurant_address END,
    restaurant_phone=CASE WHEN changed ? 'restaurant_phone' THEN changed->>'restaurant_phone' ELSE restaurant_phone END,restaurant_categories=ARRAY(SELECT jsonb_array_elements_text(changed->'restaurant_categories')),updated_at=clock_timestamp() WHERE id=target;
   FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'itemChanges') LOOP
    UPDATE public.restaurant_submission_items SET youtube_link=item->>'youtube_link',tzuyang_review=CASE WHEN item ? 'tzuyang_review' THEN item->>'tzuyang_review' ELSE tzuyang_review END WHERE id=(item->>'id')::uuid;
   END LOOP;
  ELSIF p_action='submission.approve' THEN
   IF row_value->>'submission_type' IS NULL OR row_value->>'submission_type' NOT IN ('new','edit') THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
   SELECT count(*) INTO pending_count FROM public.restaurant_submission_items WHERE submission_id=target AND item_status='pending';
   IF jsonb_typeof(p_payload->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'items')<>pending_count OR pending_count=0
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'items') x GROUP BY x->>'id' HAVING count(*)>1)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'items') x WHERE x->>'decision' IS NULL OR x->>'decision' NOT IN ('approve','reject') OR NOT EXISTS(SELECT 1 FROM public.restaurant_submission_items WHERE id=(x->>'id')::uuid AND submission_id=target AND item_status='pending'))
    THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'items') ORDER BY value->>'id' LOOP
    IF item->>'decision'='approve' THEN
     SELECT target_restaurant_id INTO source_id FROM public.restaurant_submission_items WHERE id=(item->>'id')::uuid;
     IF row_value->>'submission_type'='new' AND source_id IS NOT NULL THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
     IF row_value->>'submission_type'='edit' THEN
      SELECT to_jsonb(r) INTO final_row FROM public.restaurants r WHERE id=source_id AND status<>'deleted';
      IF final_row IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
     ELSE final_row:='{}'::jsonb; END IF;
     final_row:=pipeline_control.admin_record_compose(final_row,item->'changes');
     -- Preserve the existing submission URL canonicalization without a privileged helper call.
     final_row:=final_row||jsonb_build_object('youtube_link',CASE
      WHEN public.extract_youtube_video_id(final_row->>'youtube_link')<>'' THEN 'https://www.youtube.com/watch?v='||public.extract_youtube_video_id(final_row->>'youtube_link')
      ELSE nullif(btrim(final_row->>'youtube_link'),'') END);
     PERFORM pipeline_control.admin_record_validate_restaurant(final_row||jsonb_build_object('geocoding_success',true),ARRAY[source_id]);
     IF nullif(btrim(final_row->>'tzuyang_review'),'') IS NULL OR jsonb_typeof(final_row->'youtube_meta') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'RECORD_ACTION_EVIDENCE_REQUIRED'; END IF;
     -- Preserve the inherited fuzzy admission policy, but expose its actual domain reason rather than claiming stale CAS.
     IF EXISTS(SELECT 1 FROM public.restaurants r WHERE r.status<>'deleted' AND r.id IS DISTINCT FROM source_id AND
      ((public.extract_youtube_video_id(r.youtube_link)=public.extract_youtube_video_id(final_row->>'youtube_link') AND extensions.similarity(coalesce(r.approved_name,r.origin_name,''),final_row->>'approved_name')>0.8)
       OR extensions.similarity(coalesce(r.jibun_address,''),final_row->>'jibun_address')>0.9
       OR extensions.similarity(coalesce(r.road_address,''),coalesce(final_row->>'road_address',''))>0.9)) THEN RAISE EXCEPTION 'RECORD_ACTION_DUPLICATE_REVIEW'; END IF;
     -- Use the current-schema service invoker path in the same locked/audited operation.
     -- Edit approval retains existing status, missing marker, evaluation and provenance.
     IF row_value->>'submission_type'='edit' THEN
      PERFORM pipeline_control.admin_record_write(source_id,final_row||jsonb_build_object('geocoding_success',true),p_actor,false);
     ELSE
      -- Create parses a DTO; final_row already contains canonical metadata.
      source_id:=pipeline_control.admin_record_create((item->'changes')||jsonb_build_object('geocoding_success',true,'youtube_link',final_row->>'youtube_link'),p_actor);
      UPDATE public.restaurants SET source_type='user_submission_new',created_by=(row_value->>'user_id')::uuid WHERE id=source_id;
     END IF;
     UPDATE public.restaurant_submission_items SET item_status='approved',target_restaurant_id=source_id,rejection_reason=NULL
      WHERE id=(item->>'id')::uuid AND submission_id=target AND item_status='pending';
     IF NOT FOUND THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
    ELSE
     IF nullif(btrim(item->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'RECORD_ACTION_INVALID_PAYLOAD'; END IF;
     UPDATE public.restaurant_submission_items SET item_status='rejected',rejection_reason=item->>'reason'
      WHERE id=(item->>'id')::uuid AND submission_id=target AND item_status='pending';
     IF NOT FOUND THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
    END IF;
   END LOOP;
  ELSE
   UPDATE public.restaurant_submission_items SET item_status='rejected',rejection_reason=p_payload->>'reason' WHERE submission_id=target AND item_status='pending';
  END IF;
  IF p_action<>'submission.edit' THEN
   UPDATE public.restaurant_submissions SET status=(CASE
    WHEN EXISTS(SELECT 1 FROM public.restaurant_submission_items WHERE submission_id=target AND item_status='pending') THEN 'pending'
    WHEN NOT EXISTS(SELECT 1 FROM public.restaurant_submission_items WHERE submission_id=target AND item_status='approved') THEN 'rejected'
    WHEN EXISTS(SELECT 1 FROM public.restaurant_submission_items WHERE submission_id=target AND item_status='rejected') THEN 'partially_approved' ELSE 'approved' END)::public.submission_status,
    resolved_by_admin_id=p_actor,reviewed_at=clock_timestamp(),admin_notes=coalesce(p_payload->>'note',admin_notes),
    rejection_reason=CASE WHEN p_action IN ('submission.reject','submission.delete') THEN p_payload->>'reason' ELSE rejection_reason END,updated_at=clock_timestamp() WHERE id=target;
  END IF;
 ELSIF p_action LIKE 'review.%' THEN
  SELECT to_jsonb(r) INTO row_value FROM public.reviews r WHERE id=target;
  IF p_action='review.delete' THEN
   FOR media IN SELECT * FROM pipeline_control.admin_record_review_media(row_value) LOOP
    photo:=media.object_name;
    IF coalesce(photo,'')<>'' THEN
     -- Only the existing owner's immutable upload prefix, never URLs or traversal.
     IF photo !~ ('^'||(row_value->>'user_id')||'/reviews/'||target||'/(verification|food)/[A-Za-z0-9][A-Za-z0-9._-]{0,239}\.(avif|jpe?g|png|webp)$') OR length(photo)>1024 THEN
      UPDATE pipeline_control.admin_record_operations SET cleanup_blocked=true WHERE id=op.id; op.cleanup_blocked:=true; CONTINUE;
     END IF;
     IF EXISTS(SELECT 1 FROM public.reviews r WHERE id<>target AND (verification_photo=photo OR photo=ANY(food_photos))) THEN
      UPDATE pipeline_control.admin_record_operations SET cleanup_blocked=true WHERE id=op.id; op.cleanup_blocked:=true; CONTINUE; END IF;
     PERFORM pg_advisory_xact_lock(hashtextextended('review-media:'||media.bucket||':'||photo,0));
     INSERT INTO pipeline_control.admin_record_media_cleanup(operation_id,bucket,object_name,object_fingerprint)
      VALUES(op.id,media.bucket,photo,pipeline_control.admin_record_storage_snapshot(media.bucket,photo)) ON CONFLICT DO NOTHING;
    END IF;
   END LOOP;
   DELETE FROM public.reviews WHERE id=target;
  ELSE
   UPDATE public.reviews SET is_verified=p_action='review.approve',admin_note=CASE WHEN p_action='review.reject' THEN '거부: '||(p_payload->>'reason') ELSE p_payload->>'note' END,
    is_edited_by_admin=true,edited_by_admin_id=p_actor,edited_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=target;
  END IF;
  UPDATE public.restaurants SET review_count=(SELECT count(*) FROM public.reviews WHERE restaurant_id=(row_value->>'restaurant_id')::uuid),updated_at=clock_timestamp() WHERE id=(row_value->>'restaurant_id')::uuid;
 ELSIF p_action LIKE 'recommendation.%' THEN
  SELECT to_jsonb(r) INTO row_value FROM public.restaurant_requests r WHERE id=target;
  IF row_value->>'status'<>'pending' THEN RAISE EXCEPTION 'RECORD_ACTION_STATE_CONFLICT'; END IF;
  -- Keep the existing domain audit identity but do not duplicate free text into audit.
  INSERT INTO public.restaurant_request_review_audit(id,request_id,admin_user_id,action,before_status,after_status)
   VALUES(audit,target,p_actor,split_part(p_action,'.',2),'pending',CASE WHEN p_action='recommendation.approve' THEN 'approved' ELSE 'rejected' END);
  UPDATE public.restaurant_requests SET status=CASE WHEN p_action='recommendation.approve' THEN 'approved' ELSE 'rejected' END,
   reviewed_by_admin_id=p_actor,reviewed_at=clock_timestamp(),admin_note=p_payload->>'note',
   rejection_reason=CASE WHEN p_action='recommendation.reject' THEN p_payload->>'reason' ELSE NULL END,review_audit_id=audit,updated_at=clock_timestamp() WHERE id=target;
 END IF;
 IF p_action='review.delete' THEN
  after_state:=fingerprint-('review:'||target);
  SELECT pipeline_control.admin_record_hash(to_jsonb(r)) INTO classification FROM public.restaurants r WHERE id=(row_value->>'restaurant_id')::uuid;
  after_state:=after_state||jsonb_build_object('restaurant:'||(row_value->>'restaurant_id'),classification,'review:'||target,NULL);
 ELSIF p_action='restaurant.merge' THEN
  SELECT array_agg(split_part(key,':',2)::uuid) INTO related_ids FROM jsonb_object_keys(fingerprint) key;
  after_state:=pipeline_control.admin_record_snapshot('restaurant.edit',related_ids);
 ELSE after_state:=pipeline_control.admin_record_snapshot(p_action,ids); END IF;
 INSERT INTO pipeline_control.admin_record_audit(id,operation_id,actor,action,target_ids,payload_sha,before_fingerprints,after_fingerprints)
  VALUES(audit,op.id,p_actor,p_action,ids,digest,fingerprint,after_state);
 receipt:=op.receipt||jsonb_build_object('state','applied','auditId',audit,'targetIds',ids,
  'readback',pipeline_control.admin_record_readback(after_state),
  'mediaCleanupUnmanaged',op.cleanup_blocked,'mediaCleanupPending',EXISTS(SELECT 1 FROM pipeline_control.admin_record_media_cleanup WHERE operation_id=op.id AND state<>'done'));
 UPDATE pipeline_control.admin_record_operations SET state='applied',receipt=work.receipt WHERE id=op.id;
 RETURN receipt;
EXCEPTION WHEN unique_violation THEN
 GET STACKED DIAGNOSTICS conflict_constraint=CONSTRAINT_NAME;
 -- Only reviewed restaurant identity constraints become a definite conflict.
 -- Other 23505 failures retain their original error and never claim success.
 IF conflict_constraint=ANY(ARRAY['idx_restaurants_active_candidate_identity','idx_restaurants_active_video_identity','restaurants_trace_id_key','restaurants_duplicate_duplicate_trace_id_key']) THEN
  RAISE EXCEPTION 'RECORD_ACTION_DUPLICATE' USING ERRCODE='P0001';
 END IF;
 RAISE;
END $_$;


--
-- Name: admin_review_verification_cleanup(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_verification_cleanup(p_review_id uuid, p_phase text, p_paths text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE items jsonb; owner uuid;
BEGIN
  IF p_review_id IS NULL OR p_phase IS NULL OR p_phase NOT IN ('prepare','finish','stage')
     OR current_setting('transaction_isolation') <> 'read committed'
     OR (p_phase = 'prepare' AND p_paths IS NOT NULL)
     OR (p_phase IN ('finish','stage') AND (p_paths IS NULL OR cardinality(p_paths) > 20
       OR EXISTS (SELECT 1 FROM unnest(p_paths) x WHERE x IS NULL OR octet_length(x) > 8192)
       OR cardinality(p_paths) <> (SELECT count(DISTINCT x) FROM unnest(p_paths) x))) THEN
    RAISE EXCEPTION 'REVIEW_ADMIN_CLEANUP_INVALID';
  END IF;
  PERFORM pg_advisory_xact_lock(741093, 1);
  IF p_phase = 'stage' THEN
    SELECT user_id INTO owner FROM public.reviews WHERE id=p_review_id;
    IF owner IS NULL OR cardinality(p_paths)<>1
      OR NOT review_media_private.canonical(p_paths[1],owner,p_review_id,'verification')
      THEN RAISE EXCEPTION 'REVIEW_ADMIN_CLEANUP_INVALID'; END IF;
    INSERT INTO review_media_private.cleanup(path,owner_id,review_id,purpose,retired)
      VALUES(p_paths[1],owner,p_review_id,'verification',false) ON CONFLICT DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM review_media_private.cleanup WHERE path=p_paths[1]
      AND owner_id=owner AND review_id=p_review_id AND purpose='verification'
      AND NOT retired AND NOT complete) THEN RAISE EXCEPTION 'REVIEW_ADMIN_UPLOAD_RETIRED'; END IF;
    RETURN jsonb_build_object('status','STAGED');
  END IF;
  IF p_phase = 'prepare' THEN
    UPDATE review_media_private.cleanup c SET retired = true
      WHERE c.review_id = p_review_id AND c.purpose = 'verification'
        AND NOT c.retired AND NOT c.complete AND NOT review_media_private.referenced(c.path);
    SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.path),'[]'::jsonb) INTO items
      FROM (SELECT c.path,c.owner_id,c.review_id,c.purpose FROM review_media_private.cleanup c
        WHERE c.review_id = p_review_id AND c.purpose = 'verification' AND c.retired AND NOT c.complete
          AND NOT review_media_private.referenced(c.path)
          AND (review_media_private.canonical(c.path,c.owner_id,c.review_id,c.purpose)
            OR review_media_private.owned_legacy(c.path,c.owner_id,c.purpose))
        ORDER BY c.path LIMIT 20) x;
    RETURN jsonb_build_object('status','READY','items',items);
  END IF;
  UPDATE review_media_private.cleanup c SET complete = true
    WHERE c.review_id = p_review_id AND c.purpose = 'verification' AND c.retired AND NOT c.complete
      AND c.path = ANY(p_paths)
      AND (review_media_private.canonical(c.path,c.owner_id,c.review_id,c.purpose)
        OR review_media_private.owned_legacy(c.path,c.owner_id,c.purpose))
      AND NOT review_media_private.referenced(c.path)
      AND NOT EXISTS (SELECT 1 FROM storage.objects o
        WHERE o.bucket_id IN ('review-photos','review-verifications') AND o.name = c.path);
  RETURN jsonb_build_object('remaining',(SELECT count(*) FROM review_media_private.cleanup c
    WHERE c.review_id = p_review_id AND c.purpose = 'verification' AND c.retired AND NOT c.complete
      AND NOT review_media_private.referenced(c.path)));
END
$$;


--
-- Name: admin_user_audit_counts_are_safe(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_user_audit_counts_are_safe(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT pg_catalog.jsonb_typeof(p_value) = 'object'
    AND NOT EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_each(p_value) AS entry(key, value)
      WHERE entry.key NOT IN ('requested', 'created', 'updated', 'failed')
        OR pg_catalog.jsonb_typeof(entry.value) <> 'number'
        OR (entry.value #>> '{}') !~ '^(0|[1-9][0-9]{0,9})$'
    );
$_$;


--
-- Name: admin_user_audit_event_is_safe(text, text, text, text, jsonb, jsonb, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_user_audit_event_is_safe(p_action text, p_status text, p_reason text, p_error_code text, p_before_state jsonb, p_after_state jsonb, p_counts jsonb, p_flags jsonb, p_request_id text, p_ip_hash text, p_user_agent_hash text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT public.admin_user_audit_reason_code(p_action, p_status) IS NOT NULL
    AND p_reason = public.admin_user_audit_reason_code(p_action, p_status)
    AND (
      (p_status = 'failed' AND p_error_code = p_reason)
      OR (p_status <> 'failed' AND p_error_code IS NULL)
    )
    AND p_before_state = '{}'::jsonb
    AND p_after_state = '{}'::jsonb
    AND public.admin_user_audit_counts_are_safe(p_counts)
    AND public.admin_user_audit_flags_are_safe(p_flags)
    AND (p_request_id IS NULL OR p_request_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    AND (p_ip_hash IS NULL OR p_ip_hash ~ '^[0-9a-f]{64}$')
    AND (p_user_agent_hash IS NULL OR p_user_agent_hash ~ '^[0-9a-f]{64}$');
$_$;


--
-- Name: admin_user_audit_flags_are_safe(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_user_audit_flags_are_safe(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT pg_catalog.jsonb_typeof(p_value) = 'object'
    AND NOT EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_each(p_value) AS entry(key, value)
      WHERE entry.key NOT IN ('profileChanged', 'roleAdmin', 'accountDisabled')
        OR pg_catalog.jsonb_typeof(entry.value) <> 'boolean'
    );
$$;


--
-- Name: admin_user_audit_reason_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_user_audit_reason_code(p_action text, p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE p_action || ':' || p_status
    WHEN 'admin_user_created:intent' THEN 'ADMIN_USER_CREATE_INTENT'
    WHEN 'admin_user_created:applied' THEN 'ADMIN_USER_CREATE_APPLIED'
    WHEN 'admin_user_created:failed' THEN 'ADMIN_USER_CREATE_FAILED'
    WHEN 'admin_user_profile_updated:intent' THEN 'ADMIN_USER_PROFILE_UPDATE_INTENT'
    WHEN 'admin_user_profile_updated:applied' THEN 'ADMIN_USER_PROFILE_UPDATE_APPLIED'
    WHEN 'admin_user_profile_updated:failed' THEN 'ADMIN_USER_PROFILE_UPDATE_FAILED'
    WHEN 'admin_user_role_granted:intent' THEN 'ADMIN_USER_ROLE_GRANT_INTENT'
    WHEN 'admin_user_role_granted:applied' THEN 'ADMIN_USER_ROLE_GRANT_APPLIED'
    WHEN 'admin_user_role_granted:failed' THEN 'ADMIN_USER_ROLE_GRANT_FAILED'
    WHEN 'admin_user_role_revoked:intent' THEN 'ADMIN_USER_ROLE_REVOKE_INTENT'
    WHEN 'admin_user_role_revoked:applied' THEN 'ADMIN_USER_ROLE_REVOKE_APPLIED'
    WHEN 'admin_user_role_revoked:failed' THEN 'ADMIN_USER_ROLE_REVOKE_FAILED'
    WHEN 'admin_user_disabled:intent' THEN 'ADMIN_USER_DISABLE_INTENT'
    WHEN 'admin_user_disabled:applied' THEN 'ADMIN_USER_DISABLE_APPLIED'
    WHEN 'admin_user_disabled:failed' THEN 'ADMIN_USER_DISABLE_FAILED'
    WHEN 'admin_user_reactivated:intent' THEN 'ADMIN_USER_REACTIVATE_INTENT'
    WHEN 'admin_user_reactivated:applied' THEN 'ADMIN_USER_REACTIVATE_APPLIED'
    WHEN 'admin_user_reactivated:failed' THEN 'ADMIN_USER_REACTIVATE_FAILED'
    ELSE NULL
  END;
$$;


--
-- Name: allocate_short_url(text, uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_short_url(p_target_url text, p_restaurant_id uuid, p_review_id uuid, p_client_bucket text, p_candidate_codes text[]) RETURNS TABLE(code text, is_existing boolean, rate_limited boolean, retry_after_seconds integer, allocation_failed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_ip_allowed boolean;
  v_ip_retry_after integer;
  v_global_allowed boolean;
  v_global_retry_after integer;
  v_review_allowed boolean;
  v_review_retry_after integer;
  v_candidate_code text;
  v_existing_code text;
  v_inserted_code text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'short_url_allocation_service_role_required';
  END IF;

  IF p_target_url IS NULL
     OR p_restaurant_id IS NULL
     OR p_review_id IS NULL
     OR p_client_bucket IS NULL
     OR (p_client_bucket <> 'unknown' AND p_client_bucket !~ '^ip:[0-9a-f]{64}$')
     OR p_target_url !~ E'^/\\?review=[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR p_target_url <> ('/?review=' || p_review_id::text)
     OR p_candidate_codes IS NULL
     OR array_ndims(p_candidate_codes) <> 1
     OR COALESCE(array_length(p_candidate_codes, 1), 0) <> 5 THEN
    RAISE EXCEPTION 'invalid_short_url_allocation_request';
  END IF;

  FOREACH v_candidate_code IN ARRAY p_candidate_codes LOOP
    IF v_candidate_code IS NULL OR v_candidate_code !~ '^[A-Za-z0-9]{6}$' THEN
      RAISE EXCEPTION 'invalid_short_url_allocation_request';
    END IF;
  END LOOP;

  IF NOT EXISTS (
    SELECT 1
      FROM public.reviews AS reviews
     WHERE reviews.id = p_review_id
       AND reviews.restaurant_id = p_restaurant_id
       AND reviews.is_verified IS TRUE
  ) THEN
    RAISE EXCEPTION 'short_url_review_not_verified';
  END IF;

  PERFORM shortener_private.cleanup_expired_short_url_rate_limits(v_now);

  SELECT limits.allowed, limits.retry_after_seconds
    INTO v_ip_allowed, v_ip_retry_after
    FROM shortener_private.consume_short_url_rate_limit('ip', p_client_bucket, v_now) AS limits;
  SELECT limits.allowed, limits.retry_after_seconds
    INTO v_global_allowed, v_global_retry_after
    FROM shortener_private.consume_short_url_rate_limit('global', 'global', v_now) AS limits;
  SELECT limits.allowed, limits.retry_after_seconds
    INTO v_review_allowed, v_review_retry_after
    FROM shortener_private.consume_short_url_rate_limit('review', p_review_id::text, v_now) AS limits;

  IF NOT v_ip_allowed OR NOT v_global_allowed OR NOT v_review_allowed THEN
    code := NULL;
    is_existing := false;
    rate_limited := true;
    retry_after_seconds := GREATEST(v_ip_retry_after, v_global_retry_after, v_review_retry_after);
    allocation_failed := false;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT short_urls.code
    INTO v_existing_code
    FROM public.short_urls AS short_urls
   WHERE short_urls.target_url = p_target_url;

  IF FOUND THEN
    code := v_existing_code;
    is_existing := true;
    rate_limited := false;
    retry_after_seconds := 0;
    allocation_failed := false;
    RETURN NEXT;
    RETURN;
  END IF;

  FOREACH v_candidate_code IN ARRAY p_candidate_codes LOOP
    INSERT INTO public.short_urls AS short_urls (
      code,
      target_url,
      restaurant_id,
      restaurant_name
    ) VALUES (
      v_candidate_code,
      p_target_url,
      p_restaurant_id,
      NULL
    )
    ON CONFLICT DO NOTHING
    RETURNING short_urls.code INTO v_inserted_code;

    IF FOUND THEN
      code := v_inserted_code;
      is_existing := false;
      rate_limited := false;
      retry_after_seconds := 0;
      allocation_failed := false;
      RETURN NEXT;
      RETURN;
    END IF;

    SELECT short_urls.code
      INTO v_existing_code
      FROM public.short_urls AS short_urls
     WHERE short_urls.target_url = p_target_url;

    IF FOUND THEN
      code := v_existing_code;
      is_existing := true;
      rate_limited := false;
      retry_after_seconds := 0;
      allocation_failed := false;
      RETURN NEXT;
      RETURN;
    END IF;
  END LOOP;

  code := NULL;
  is_existing := false;
  rate_limited := false;
  retry_after_seconds := 0;
  allocation_failed := true;
  RETURN NEXT;
END;
$_$;


--
-- Name: append_admin_user_audit_event(uuid, uuid, text, text, text, uuid, jsonb, jsonb, timestamp with time zone, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_admin_user_audit_event(p_actor_user_id uuid, p_target_user_id uuid, p_action text, p_reason text, p_status text, p_correlation_id uuid, p_audit_counts jsonb, p_audit_flags jsonb, p_applied_at timestamp with time zone, p_error_code text, p_request_id uuid, p_ip_hash text, p_user_agent_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  audit_id uuid;
BEGIN
  IF p_actor_user_id IS NULL
     OR p_request_id IS NULL
     OR p_audit_counts IS NULL
     OR p_audit_flags IS NULL
     OR NOT EXISTS (
       SELECT 1
         FROM public.user_roles AS role_row
         JOIN public.user_account_status AS status_row
           ON status_row.user_id = role_row.user_id
        WHERE role_row.user_id = p_actor_user_id
          AND role_row.role::text = 'admin'
          AND status_row.account_status = 'active'
          AND status_row.disabled_at IS NULL
     )
     OR (p_status = 'applied') IS DISTINCT FROM (p_applied_at IS NOT NULL)
     OR NOT public.admin_user_audit_event_is_safe(
       p_action,
       p_status,
       p_reason,
       p_error_code,
       '{}'::jsonb,
       '{}'::jsonb,
       p_audit_counts,
       p_audit_flags,
       p_request_id::text,
       p_ip_hash,
       p_user_agent_hash
     ) THEN
    RAISE EXCEPTION 'admin_user_audit_event_invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.admin_audit_events (
    actor_user_id,
    target_user_id,
    action,
    reason,
    before_state,
    after_state,
    audit_counts,
    audit_flags,
    status,
    correlation_id,
    applied_at,
    error_code,
    request_id,
    ip_hash,
    user_agent_hash
  ) VALUES (
    p_actor_user_id,
    p_target_user_id,
    p_action,
    p_reason,
    '{}'::jsonb,
    '{}'::jsonb,
    p_audit_counts,
    p_audit_flags,
    p_status,
    p_correlation_id,
    p_applied_at,
    p_error_code,
    p_request_id::text,
    p_ip_hash,
    p_user_agent_hash
  )
  RETURNING admin_audit_events.id INTO audit_id;

  RETURN audit_id;
END
$$;


--
-- Name: append_privacy_audit_event(text, uuid, uuid, uuid, uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_privacy_audit_event(p_event_type text, p_actor_user_id uuid, p_subject_user_id uuid, p_operation_id uuid, p_correlation_id uuid, p_status text, p_reason_code text, p_count_summary jsonb, p_request_metadata jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  RETURN privacy_retention.append_privacy_audit_event_internal(
    p_event_type,
    p_actor_user_id,
    p_subject_user_id,
    p_operation_id,
    p_correlation_id,
    p_status,
    p_reason_code,
    p_count_summary,
    p_request_metadata
  );
END;
$$;


--
-- Name: apply_account_deletion_database_cleanup(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_account_deletion_database_cleanup(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text) RETURNS TABLE(request_id uuid, status text, reason_code text, db_readback_passed boolean, session_readback_passed boolean, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_manifest privacy_retention.account_deletion_source_manifest%ROWTYPE;
  v_evidence_cleanup_lease_token uuid;
  v_storage_object_count bigint;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL OR p_source_manifest_hash IS NULL THEN
    RAISE EXCEPTION 'account_deletion_database_arguments_required' USING ERRCODE = '22004';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  SELECT * INTO v_request FROM public.account_deletion_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_database_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(p_actor_user_id, p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
  IF v_request.status NOT IN ('applying', 'partial')
     OR v_request.source_manifest_hash IS DISTINCT FROM
        privacy_retention.g014_account_deletion_validate_manifest(v_request.policy_version) THEN
    RAISE EXCEPTION 'account_deletion_database_predecessor_invalid' USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_storage_object_count
  FROM storage.objects AS object_row
  WHERE object_row.owner_id::text = p_target_user_id::text;
  IF v_storage_object_count > 100 THEN
    RAISE EXCEPTION 'account_deletion_storage_receipt_limit_exceeded' USING ERRCODE = '54000';
  END IF;

  FOR v_manifest IN
    SELECT manifest.*
    FROM privacy_retention.account_deletion_source_manifest AS manifest
    WHERE manifest.policy_version = v_request.policy_version
      AND manifest.code NOT IN ('storage_objects', 'auth_identity')
    ORDER BY manifest.ordinal, manifest.code
  LOOP
    PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
    PERFORM privacy_retention.g014_account_deletion_apply_adapter(
      v_manifest.adapter_name, v_request.id, p_target_user_id
    );
    UPDATE public.account_deletion_request_items AS item
    SET status = CASE item.disposition
      WHEN 'retain' THEN 'retained'
      WHEN 'separate' THEN 'separated'
      ELSE 'applied'
    END,
    reason_code = 'DB_READBACK_PASSED'
    WHERE item.request_id = v_request.id AND item.data_class_code = v_manifest.code;
  END LOOP;

  v_evidence_cleanup_lease_token := pg_catalog.nullif(
    pg_catalog.current_setting('app.account_deletion_evidence_lease_token', true), ''
  )::uuid;
  IF v_evidence_cleanup_lease_token IS NOT NULL THEN
    PERFORM privacy_retention.g014_account_deletion_release_evidence_cleanup(
      v_request.id, p_target_user_id, v_evidence_cleanup_lease_token
    );
  END IF;

  UPDATE public.account_deletion_requests
  SET status = 'applying',
      reason_code = 'DB_READBACK_PASSED',
      db_readback_passed = true,
      session_readback_passed = false
  WHERE id = v_request.id
  RETURNING * INTO v_request;
  PERFORM privacy_retention.g014_account_deletion_append_audit(
    v_request, 'readback_passed', 'DB_READBACK_PASSED'
  );
  RETURN QUERY SELECT v_request.id, v_request.status, v_request.reason_code,
    v_request.db_readback_passed, v_request.session_readback_passed,
    v_request.source_manifest_hash;
END;
$$;


--
-- Name: apply_admin_restaurant_map_overlay_action(uuid, text, uuid, text, text, text, timestamp with time zone, timestamp with time zone, jsonb, text, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_admin_restaurant_map_overlay_action(p_actor_user_id uuid, p_action text, p_restaurant_id uuid, p_overlay_type text, p_label text, p_description text, p_active_from timestamp with time zone, p_active_until timestamp with time zone, p_evidence jsonb, p_reason text, p_preview_hash text, p_payload_hash text, p_correlation_id uuid, p_idempotency_key text, p_request_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_claims jsonb;
  v_claims_role text;
  v_legacy_role text;
  v_restaurant public.restaurants%ROWTYPE;
  v_overlay_before public.admin_restaurant_map_overlays%ROWTYPE;
  v_overlay_after public.admin_restaurant_map_overlays%ROWTYPE;
  v_audit public.admin_restaurant_map_overlay_audit_events%ROWTYPE;
  v_before_snapshot jsonb := '{}'::jsonb;
  v_after_snapshot jsonb := '{}'::jsonb;
  v_request_metadata jsonb := '{}'::jsonb;
  v_now timestamptz := pg_catalog.timezone(
    'utc'::text,
    pg_catalog.now()
  );
BEGIN
  BEGIN
    v_claims := COALESCE(
      NULLIF(
        pg_catalog.current_setting('request.jwt.claims', true),
        ''
      )::jsonb,
      '{}'::jsonb
    );
    v_claims_role := NULLIF(v_claims ->> 'role', '');
    v_legacy_role := NULLIF(
      pg_catalog.current_setting('request.jwt.claim.role', true),
      ''
    );
  EXCEPTION
    WHEN invalid_text_representation OR invalid_parameter_value THEN
      RAISE EXCEPTION 'overlay_service_role_required'
        USING ERRCODE = '42501';
  END;

  IF COALESCE(v_claims_role, v_legacy_role, '') <>
       'service_role'
     OR (
       v_claims_role IS NOT NULL
       AND v_legacy_role IS NOT NULL
       AND v_claims_role <> v_legacy_role
     ) THEN
    RAISE EXCEPTION 'overlay_service_role_required'
      USING ERRCODE = '42501';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'overlay_actor_required';
  END IF;

  IF p_action IS NULL
     OR p_action NOT IN ('upsert_overlay', 'deactivate_overlay') THEN
    RAISE EXCEPTION 'overlay_action_invalid';
  END IF;

  IF p_restaurant_id IS NULL THEN
    RAISE EXCEPTION 'overlay_restaurant_not_found';
  END IF;

  IF p_overlay_type IS NULL
     OR p_overlay_type NOT IN ('trend', 'seasonal') THEN
    RAISE EXCEPTION 'overlay_type_invalid';
  END IF;

  IF p_action = 'upsert_overlay'
     AND (
       p_label IS NULL
       OR pg_catalog.char_length(pg_catalog.btrim(p_label)) < 1
       OR pg_catalog.char_length(pg_catalog.btrim(p_label)) > 80
     ) THEN
    RAISE EXCEPTION 'overlay_label_invalid';
  END IF;

  IF p_description IS NOT NULL
     AND pg_catalog.char_length(p_description) > 500 THEN
    RAISE EXCEPTION 'overlay_description_invalid';
  END IF;

  IF p_active_from IS NOT NULL
     AND p_active_until IS NOT NULL
     AND p_active_from > p_active_until THEN
    RAISE EXCEPTION 'overlay_active_window_invalid';
  END IF;

  IF p_reason IS NULL
     OR pg_catalog.char_length(pg_catalog.btrim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'overlay_reason_required';
  END IF;

  IF p_preview_hash IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_payload_hash IS NULL
     OR p_payload_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'overlay_hash_invalid';
  END IF;

  IF p_correlation_id IS NULL
     OR p_idempotency_key IS NULL
     OR pg_catalog.char_length(pg_catalog.btrim(p_idempotency_key)) < 1 THEN
    RAISE EXCEPTION 'overlay_idempotency_invalid';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_actor_user_id::text || ':' || p_idempotency_key,
      0
    )
  );

  SELECT *
    INTO v_audit
    FROM public.admin_restaurant_map_overlay_audit_events AS audit_row
   WHERE audit_row.actor_user_id = p_actor_user_id
     AND audit_row.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_audit.payload_hash = p_payload_hash
       AND v_audit.correlation_id = p_correlation_id
       AND v_audit.restaurant_id = p_restaurant_id
       AND v_audit.overlay_type = p_overlay_type
       AND v_audit.action = p_action THEN
      RETURN pg_catalog.jsonb_build_object(
        'status', v_audit.status,
        'replayed', true,
        'overlay', v_audit.after_snapshot,
        'audit', pg_catalog.to_jsonb(v_audit),
        'readback', pg_catalog.jsonb_build_object(
          'matchedPayloadHash', true,
          'matchedPreviewHash',
            COALESCE(
              v_audit.request_metadata ->> 'previewHash',
              ''
            ) = p_preview_hash,
          'restaurantId', v_audit.restaurant_id,
          'overlayType', v_audit.overlay_type
        )
      );
    END IF;

    RAISE EXCEPTION 'overlay_idempotency_conflict';
  END IF;

  -- A row lock on restaurants required UPDATE privilege for the definer even
  -- though this RPC never changes restaurants. Existence is sufficient here;
  -- the overlay row and actor/idempotency advisory lock serialize writes.
  SELECT *
    INTO v_restaurant
    FROM public.restaurants AS restaurant_row
   WHERE restaurant_row.id = p_restaurant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'overlay_restaurant_not_found';
  END IF;

  SELECT *
    INTO v_overlay_before
    FROM public.admin_restaurant_map_overlays AS overlay_row
   WHERE overlay_row.restaurant_id = p_restaurant_id
     AND overlay_row.overlay_type = p_overlay_type
   FOR UPDATE;

  IF FOUND THEN
    v_before_snapshot := pg_catalog.to_jsonb(v_overlay_before);
  ELSIF p_action = 'deactivate_overlay' THEN
    RAISE EXCEPTION 'overlay_not_found_for_deactivate';
  END IF;

  IF p_action = 'upsert_overlay' THEN
    IF v_before_snapshot = '{}'::jsonb THEN
      INSERT INTO public.admin_restaurant_map_overlays (
        restaurant_id,
        overlay_type,
        label,
        description,
        active_from,
        active_until,
        evidence,
        is_active,
        created_by_admin_id,
        updated_by_admin_id
      ) VALUES (
        p_restaurant_id,
        p_overlay_type,
        pg_catalog.btrim(p_label),
        p_description,
        p_active_from,
        p_active_until,
        COALESCE(p_evidence, '{}'::jsonb),
        true,
        p_actor_user_id,
        p_actor_user_id
      )
      RETURNING * INTO v_overlay_after;
    ELSE
      UPDATE public.admin_restaurant_map_overlays AS overlay_row
         SET label = pg_catalog.btrim(p_label),
             description = p_description,
             active_from = p_active_from,
             active_until = p_active_until,
             evidence = COALESCE(p_evidence, '{}'::jsonb),
             is_active = true,
             updated_by_admin_id = p_actor_user_id
       WHERE overlay_row.restaurant_id = p_restaurant_id
         AND overlay_row.overlay_type = p_overlay_type
      RETURNING * INTO v_overlay_after;
    END IF;
  ELSE
    UPDATE public.admin_restaurant_map_overlays AS overlay_row
       SET is_active = false,
           evidence = COALESCE(
             overlay_row.evidence,
             '{}'::jsonb
           ) || pg_catalog.jsonb_build_object(
             'deactivatedAt', v_now,
             'deactivationReason', pg_catalog.btrim(p_reason),
             'deactivationPreviewHash', p_preview_hash,
             'deactivationPayloadHash', p_payload_hash
           ),
           updated_by_admin_id = p_actor_user_id
     WHERE overlay_row.restaurant_id = p_restaurant_id
       AND overlay_row.overlay_type = p_overlay_type
    RETURNING * INTO v_overlay_after;
  END IF;

  v_after_snapshot := pg_catalog.to_jsonb(v_overlay_after);
  v_request_metadata := COALESCE(
    p_request_metadata,
    '{}'::jsonb
  ) || pg_catalog.jsonb_build_object('previewHash', p_preview_hash);

  INSERT INTO public.admin_restaurant_map_overlay_audit_events (
    actor_user_id,
    action,
    restaurant_id,
    overlay_type,
    reason,
    before_snapshot,
    after_snapshot,
    correlation_id,
    idempotency_key,
    payload_hash,
    request_metadata,
    status
  ) VALUES (
    p_actor_user_id,
    p_action,
    p_restaurant_id,
    p_overlay_type,
    pg_catalog.btrim(p_reason),
    v_before_snapshot,
    v_after_snapshot,
    p_correlation_id,
    p_idempotency_key,
    p_payload_hash,
    v_request_metadata,
    'applied'
  )
  RETURNING * INTO v_audit;

  RETURN pg_catalog.jsonb_build_object(
    'status', 'applied',
    'replayed', false,
    'overlay', v_after_snapshot,
    'audit', pg_catalog.to_jsonb(v_audit),
    'readback', pg_catalog.jsonb_build_object(
      'matchedPayloadHash', v_audit.payload_hash = p_payload_hash,
      'matchedPreviewHash',
        COALESCE(
          v_audit.request_metadata ->> 'previewHash',
          ''
        ) = p_preview_hash,
      'restaurantId', v_overlay_after.restaurant_id,
      'overlayType', v_overlay_after.overlay_type
    )
  );
END
$_$;


--
-- Name: apply_admin_user_db_mutation(uuid, uuid, text, text, jsonb, jsonb, uuid, jsonb, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_admin_user_db_mutation(p_actor_user_id uuid, p_target_user_id uuid, p_action text, p_reason text, p_before_state jsonb, p_after_state jsonb, p_correlation_id uuid, p_profile jsonb DEFAULT NULL::jsonb, p_next_role text DEFAULT NULL::text, p_next_account_status text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_ip_hash text DEFAULT NULL::text, p_user_agent_hash text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  applied_audit_id uuid;
  v_flags jsonb := '{}'::jsonb;
BEGIN
  IF p_action NOT IN (
    'admin_user_profile_updated',
    'admin_user_role_granted',
    'admin_user_role_revoked',
    'admin_user_disabled',
    'admin_user_reactivated'
  ) THEN
    RAISE EXCEPTION 'admin_user_audit_action_invalid' USING ERRCODE = '22023';
  END IF;

  IF p_before_state IS DISTINCT FROM '{}'::jsonb
    OR p_after_state IS DISTINCT FROM '{}'::jsonb
    OR NOT public.admin_user_audit_event_is_safe(
      p_action,
      'applied',
      p_reason,
      NULL,
      '{}'::jsonb,
      '{}'::jsonb,
      pg_catalog.jsonb_build_object('updated', 1),
      '{}'::jsonb,
      p_request_id,
      p_ip_hash,
      p_user_agent_hash
    )
  THEN
    RAISE EXCEPTION 'admin_user_audit_contract_invalid' USING ERRCODE = '22023';
  END IF;

  IF p_profile IS NOT NULL THEN
    INSERT INTO public.profiles (
      user_id,
      username,
      nickname,
      avatar_url,
      role,
      updated_at
    )
    VALUES (
      p_target_user_id,
      NULLIF(BTRIM(p_profile->>'username'), ''),
      NULLIF(BTRIM(p_profile->>'nickname'), ''),
      NULLIF(BTRIM(p_profile->>'avatar_url'), ''),
      COALESCE(
        (SELECT profile.role FROM public.profiles AS profile WHERE profile.user_id = p_target_user_id),
        CASE
          WHEN EXISTS (
          SELECT 1 FROM public.user_roles AS role_row WHERE role_row.user_id = p_target_user_id AND role_row.role = 'admin'
          )
          THEN 'admin'
          ELSE 'user'
        END
      ),
      now()
    )
    ON CONFLICT (user_id) DO UPDATE
    SET username = EXCLUDED.username,
        nickname = EXCLUDED.nickname,
        avatar_url = EXCLUDED.avatar_url,
        updated_at = now();
  END IF;

  IF p_next_role IS NOT NULL THEN
    IF p_next_role NOT IN ('admin', 'user') THEN
      RAISE EXCEPTION 'admin_user_role_invalid' USING ERRCODE = '22023';
    END IF;

    IF p_next_role = 'admin' THEN
      INSERT INTO public.user_roles (user_id, role)
      VALUES (p_target_user_id, 'admin')
      ON CONFLICT (user_id, role) DO NOTHING;
    ELSE
      DELETE FROM public.user_roles AS role_row
      WHERE role_row.user_id = p_target_user_id
        AND role_row.role = 'admin';
    END IF;

    INSERT INTO public.profiles (
      user_id,
      username,
      nickname,
      avatar_url,
      role,
      updated_at
    )
    VALUES (
      p_target_user_id,
      COALESCE((SELECT profile.username FROM public.profiles AS profile WHERE profile.user_id = p_target_user_id), 'unknown'),
      COALESCE((SELECT profile.nickname FROM public.profiles AS profile WHERE profile.user_id = p_target_user_id), '닉네임 없음'),
      (SELECT profile.avatar_url FROM public.profiles AS profile WHERE profile.user_id = p_target_user_id),
      p_next_role,
      now()
    )
    ON CONFLICT (user_id) DO UPDATE
    SET role = EXCLUDED.role,
        updated_at = now();
  END IF;

  IF p_next_account_status IS NOT NULL THEN
    IF p_next_account_status NOT IN ('active', 'disabled') THEN
      RAISE EXCEPTION 'admin_user_account_status_invalid' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.user_account_status (
      user_id,
      account_status,
      disabled_at,
      updated_at
    )
    VALUES (
      p_target_user_id,
      p_next_account_status,
      CASE WHEN p_next_account_status = 'disabled' THEN now() ELSE NULL END,
      now()
    )
    ON CONFLICT (user_id) DO UPDATE
    SET account_status = EXCLUDED.account_status,
        disabled_at = EXCLUDED.disabled_at,
        updated_at = now();
  END IF;

  v_flags := CASE p_action
    WHEN 'admin_user_profile_updated' THEN pg_catalog.jsonb_build_object('profileChanged', true)
    WHEN 'admin_user_role_granted' THEN pg_catalog.jsonb_build_object('roleAdmin', true)
    WHEN 'admin_user_role_revoked' THEN pg_catalog.jsonb_build_object('roleAdmin', false)
    WHEN 'admin_user_disabled' THEN pg_catalog.jsonb_build_object('accountDisabled', true)
    WHEN 'admin_user_reactivated' THEN pg_catalog.jsonb_build_object('accountDisabled', false)
    ELSE '{}'::jsonb
  END;

  INSERT INTO public.admin_audit_events (
    actor_user_id,
    target_user_id,
    action,
    reason,
    before_state,
    after_state,
    audit_counts,
    audit_flags,
    status,
    correlation_id,
    applied_at,
    request_id,
    ip_hash,
    user_agent_hash
  )
  VALUES (
    p_actor_user_id,
    p_target_user_id,
    p_action,
    p_reason,
    '{}'::jsonb,
    '{}'::jsonb,
    pg_catalog.jsonb_build_object('updated', 1),
    v_flags,
    'applied',
    p_correlation_id,
    now(),
    p_request_id,
    p_ip_hash,
    p_user_agent_hash
  )
  RETURNING id INTO applied_audit_id;

  RETURN applied_audit_id;
END;
$$;


--
-- Name: apply_privacy_incident_transition(uuid, uuid, uuid, public.privacy_incident_status, timestamp with time zone, text, text, text, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_privacy_incident_transition(p_actor_user_id uuid, p_operation_id uuid, p_incident_id uuid, p_to_status public.privacy_incident_status, p_expected_updated_at timestamp with time zone, p_preview_hash text, p_confirmation_text text, p_reason_code text, p_transition_input jsonb, p_correlation_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_preview public.privacy_incident_transition_previews%rowtype;
  v_action public.privacy_incident_actions%rowtype;
  v_incident public.privacy_incidents%rowtype;
  v_readback_incident public.privacy_incidents%rowtype;
  v_notice public.privacy_incident_notices%rowtype;
  v_readback_notice public.privacy_incident_notices%rowtype;
  v_audit_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_audit_retention_until timestamptz;
  v_input_hash text;
  v_readback_passed boolean := false;
  v_readback_checks jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.privacy_incident_require_admin(p_actor_user_id);

  IF p_operation_id IS NULL OR p_incident_id IS NULL OR p_to_status IS NULL OR p_expected_updated_at IS NULL
     OR p_correlation_id IS NULL OR p_preview_hash IS NULL OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_reason_code IS NULL OR p_reason_code !~ '^[a-z][a-z0-9_]{2,63}$'
     OR p_idempotency_key IS NULL OR char_length(trim(p_idempotency_key)) NOT BETWEEN 8 AND 128 THEN
    RAISE EXCEPTION 'invalid_privacy_incident_apply_request';
  END IF;

  IF p_confirmation_text <> '개인정보 사고 조치 적용' THEN
    RAISE EXCEPTION 'privacy_incident_confirmation_required';
  END IF;

  PERFORM public.privacy_incident_validate_input(p_to_status, coalesce(p_transition_input, '{}'::jsonb));
  v_input_hash := public.privacy_incident_input_hash(coalesce(p_transition_input, '{}'::jsonb));

  PERFORM pg_advisory_xact_lock(hashtextextended(p_actor_user_id::text || ':' || trim(p_idempotency_key), 0));

  SELECT *
    INTO v_action
    FROM public.privacy_incident_actions
   WHERE actor_user_id = p_actor_user_id
     AND idempotency_key = trim(p_idempotency_key);

  IF FOUND THEN
    IF v_action.id = p_operation_id
       AND v_action.incident_id = p_incident_id
       AND v_action.to_status = p_to_status
       AND v_action.preview_hash = p_preview_hash
       AND v_action.expected_updated_at = p_expected_updated_at
       AND v_action.reason_code = p_reason_code
       AND v_action.input_hash = v_input_hash
       AND v_action.correlation_id = p_correlation_id
       AND v_action.readback_status = 'passed' THEN
      RETURN jsonb_build_object(
        'ok', true,
        'operationId', p_operation_id,
        'status', 'applied',
        'replayed', true,
        'auditId', v_action.audit_id,
        'readback', jsonb_build_object(
          'passed', v_action.readback_status = 'passed',
          'checks', jsonb_build_object('statusMatched', v_action.readback_status = 'passed', 'actionImmutable', true, 'replayed', true)
        )
      );
    END IF;
    RAISE EXCEPTION 'privacy_incident_idempotency_conflict';
  END IF;

  SELECT *
    INTO v_preview
    FROM public.privacy_incident_transition_previews
   WHERE operation_id = p_operation_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'privacy_incident_preview_not_found';
  END IF;

  IF v_preview.consumed_at IS NOT NULL OR v_preview.expires_at <= v_now THEN
    RAISE EXCEPTION 'privacy_incident_preview_stale';
  END IF;

  IF v_preview.incident_id <> p_incident_id
     OR v_preview.actor_user_id <> p_actor_user_id
     OR v_preview.to_status <> p_to_status
     OR v_preview.expected_updated_at <> p_expected_updated_at
     OR v_preview.preview_hash <> p_preview_hash
     OR v_preview.input_hash <> v_input_hash
     OR v_preview.reason_code <> p_reason_code
     OR v_preview.correlation_id <> p_correlation_id THEN
    RAISE EXCEPTION 'privacy_incident_preview_stale';
  END IF;

  SELECT *
    INTO v_incident
    FROM public.privacy_incidents
   WHERE id = p_incident_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'privacy_incident_not_found';
  END IF;

  IF v_incident.updated_at <> p_expected_updated_at THEN
    RAISE EXCEPTION 'privacy_incident_version_stale';
  END IF;

  IF v_incident.status <> v_preview.from_status
     OR NOT public.privacy_incident_transition_is_allowed(v_incident.status, p_to_status) THEN
    RAISE EXCEPTION 'privacy_incident_transition_forbidden';
  END IF;
  v_audit_retention_until := public.privacy_incident_audit_retention_until(v_now);
  INSERT INTO privacy_retention.privacy_audit_events (
    event_type,
    actor_user_id,
    operation_id,
    correlation_id,
    preview_hash,
    status,
    reason_code,
    count_summary,
    request_metadata,
    occurred_at,
    retention_until
  ) VALUES (
    'privacy_incident_transition',
    p_actor_user_id,
    p_operation_id,
    p_correlation_id,
    p_preview_hash,
    'confirmed',
    upper(p_reason_code),
    public.privacy_incident_audit_count_summary(
      coalesce(v_incident.affected_count_estimate, 0),
      cardinality(v_incident.data_categories)
    ),
    jsonb_build_object('route', '/api/admin/privacy-incidents'),
    v_now,
    v_audit_retention_until
  );


  IF p_to_status = 'triaged' THEN
    UPDATE public.privacy_incidents
       SET status = 'triaged',
           awareness_at = (p_transition_input ->> 'awarenessAt')::timestamptz,
           deadline_at = (p_transition_input ->> 'awarenessAt')::timestamptz + interval '72 hours'
     WHERE id = p_incident_id;
  ELSIF p_to_status = 'contained' THEN
    UPDATE public.privacy_incidents SET status = 'contained' WHERE id = p_incident_id;
  ELSIF p_to_status = 'assessed' THEN
    UPDATE public.privacy_incidents
       SET status = 'assessed',
           affected_count_estimate = (p_transition_input ->> 'affectedCountEstimate')::integer,
           data_categories = ARRAY(SELECT jsonb_array_elements_text(p_transition_input -> 'dataCategories')::public.privacy_incident_data_category),
           sensitive_or_unique_id = (p_transition_input ->> 'sensitiveOrUniqueId')::boolean,
           external_intrusion = (p_transition_input ->> 'externalIntrusion')::boolean,
           decision_code = p_transition_input ->> 'decisionCode'
     WHERE id = p_incident_id;
  ELSIF p_to_status = 'notice_drafted' THEN
    INSERT INTO public.privacy_incident_notices (
      incident_id,
      audience,
      status,
      template_version,
      content_sha256
    ) VALUES (
      p_incident_id,
      (p_transition_input ->> 'noticeAudience')::public.privacy_incident_notice_audience,
      'draft',
      p_transition_input ->> 'templateVersion',
      p_transition_input ->> 'contentSha256'
    ) RETURNING * INTO v_notice;

    UPDATE public.privacy_incidents SET status = 'notice_drafted' WHERE id = p_incident_id;
  ELSIF p_to_status = 'notice_approved' THEN
    SELECT *
      INTO v_notice
      FROM public.privacy_incident_notices
     WHERE id = (p_transition_input ->> 'noticeId')::uuid
       AND incident_id = p_incident_id
     FOR UPDATE;

    IF NOT FOUND OR v_notice.status <> 'draft' THEN
      RAISE EXCEPTION 'privacy_incident_notice_approval_required';
    END IF;

    UPDATE public.privacy_incident_notices
       SET status = 'approved',
           approved_by = p_actor_user_id,
           approved_at = v_now
     WHERE id = v_notice.id
     RETURNING * INTO v_notice;

    UPDATE public.privacy_incidents SET status = 'notice_approved' WHERE id = p_incident_id;
  ELSIF p_to_status = 'notified' THEN
    SELECT *
      INTO v_notice
      FROM public.privacy_incident_notices
     WHERE id = (p_transition_input ->> 'noticeId')::uuid
       AND incident_id = p_incident_id
     FOR UPDATE;

    IF NOT FOUND OR v_notice.status <> 'approved' OR v_notice.approved_by IS NULL OR v_notice.approved_at IS NULL THEN
      RAISE EXCEPTION 'privacy_incident_notice_approval_required';
    END IF;

    UPDATE public.privacy_incident_notices
       SET status = 'submitted',
           submitted_by = p_actor_user_id,
           submitted_at = v_now,
           external_receipt_ref = p_transition_input ->> 'externalReceiptRef'
     WHERE id = v_notice.id
     RETURNING * INTO v_notice;

    UPDATE public.privacy_incidents SET status = 'notified' WHERE id = p_incident_id;
  ELSIF p_to_status = 'closed' THEN
    IF v_incident.assessment_readback_at IS NULL
       OR v_incident.affected_count_estimate IS NULL
       OR cardinality(v_incident.data_categories) = 0
       OR v_incident.sensitive_or_unique_id IS NULL
       OR v_incident.external_intrusion IS NULL
       OR v_incident.decision_code IS NULL
       OR NOT EXISTS (
         SELECT 1
           FROM public.privacy_incident_actions
          WHERE incident_id = p_incident_id
            AND to_status = 'notified'
            AND readback_status = 'passed'
       ) THEN
      RAISE EXCEPTION 'privacy_incident_closure_readback_required';
    END IF;

    UPDATE public.privacy_incidents SET status = 'closed' WHERE id = p_incident_id;
  ELSE
    RAISE EXCEPTION 'privacy_incident_transition_forbidden';
  END IF;

  SELECT *
    INTO v_readback_incident
    FROM public.privacy_incidents
   WHERE id = p_incident_id;

  v_readback_passed := v_readback_incident.status = p_to_status;
  v_readback_checks := jsonb_build_object(
    'statusMatched', v_readback_incident.status = p_to_status,
    'expectedVersionWasMatched', true,
    'previewWasBound', true
  );

  IF p_to_status = 'triaged' THEN
    v_readback_passed := v_readback_passed
      AND v_readback_incident.awareness_at = (p_transition_input ->> 'awarenessAt')::timestamptz
      AND v_readback_incident.deadline_at = (p_transition_input ->> 'awarenessAt')::timestamptz + interval '72 hours';
    v_readback_checks := v_readback_checks || jsonb_build_object(
      'awarenessMatched', v_readback_incident.awareness_at = (p_transition_input ->> 'awarenessAt')::timestamptz,
      'deadlineDerivedFromAwareness', v_readback_incident.deadline_at = (p_transition_input ->> 'awarenessAt')::timestamptz + interval '72 hours'
    );
  ELSIF p_to_status = 'assessed' THEN
    v_readback_passed := v_readback_passed
      AND v_readback_incident.affected_count_estimate = (p_transition_input ->> 'affectedCountEstimate')::integer
      AND v_readback_incident.data_categories = ARRAY(SELECT jsonb_array_elements_text(p_transition_input -> 'dataCategories')::public.privacy_incident_data_category)
      AND v_readback_incident.sensitive_or_unique_id = (p_transition_input ->> 'sensitiveOrUniqueId')::boolean
      AND v_readback_incident.external_intrusion = (p_transition_input ->> 'externalIntrusion')::boolean
      AND v_readback_incident.decision_code = p_transition_input ->> 'decisionCode';
    IF v_readback_passed THEN
      UPDATE public.privacy_incidents
         SET assessment_readback_at = v_now
       WHERE id = p_incident_id
       RETURNING * INTO v_readback_incident;
    END IF;
    v_readback_passed := v_readback_passed AND v_readback_incident.assessment_readback_at IS NOT NULL;
    v_readback_checks := v_readback_checks || jsonb_build_object(
      'assessmentRecorded', v_readback_incident.assessment_readback_at IS NOT NULL,
      'affectedCountMatched', v_readback_incident.affected_count_estimate = (p_transition_input ->> 'affectedCountEstimate')::integer,
      'dataCategoriesMatched', v_readback_incident.data_categories = ARRAY(SELECT jsonb_array_elements_text(p_transition_input -> 'dataCategories')::public.privacy_incident_data_category),
      'sensitivityDecisionMatched', v_readback_incident.sensitive_or_unique_id = (p_transition_input ->> 'sensitiveOrUniqueId')::boolean,
      'intrusionDecisionMatched', v_readback_incident.external_intrusion = (p_transition_input ->> 'externalIntrusion')::boolean
    );
  ELSIF p_to_status IN ('notice_drafted', 'notice_approved', 'notified') THEN
    IF p_to_status = 'notice_drafted' THEN
      SELECT *
        INTO v_readback_notice
        FROM public.privacy_incident_notices
       WHERE incident_id = p_incident_id
         AND status = 'draft'
         AND audience = (p_transition_input ->> 'noticeAudience')::public.privacy_incident_notice_audience
         AND template_version = p_transition_input ->> 'templateVersion'
         AND content_sha256 = p_transition_input ->> 'contentSha256'
       ORDER BY created_at DESC
       LIMIT 1;
    ELSE
      SELECT *
        INTO v_readback_notice
        FROM public.privacy_incident_notices
       WHERE id = (p_transition_input ->> 'noticeId')::uuid
         AND incident_id = p_incident_id;
    END IF;

    v_readback_passed := v_readback_passed AND FOUND;
    IF p_to_status = 'notice_approved' THEN
      v_readback_passed := v_readback_passed AND v_readback_notice.status = 'approved' AND v_readback_notice.approved_by = p_actor_user_id AND v_readback_notice.approved_at IS NOT NULL;
    ELSIF p_to_status = 'notified' THEN
      v_readback_passed := v_readback_passed AND v_readback_notice.status = 'submitted' AND v_readback_notice.approved_by IS NOT NULL AND v_readback_notice.submitted_by = p_actor_user_id AND v_readback_notice.submitted_at IS NOT NULL AND v_readback_notice.external_receipt_ref = p_transition_input ->> 'externalReceiptRef';
    END IF;
    v_readback_checks := v_readback_checks || jsonb_build_object(
      'noticeMatched', FOUND,
      'namedApproverPresent', CASE WHEN FOUND THEN v_readback_notice.approved_by IS NOT NULL ELSE false END,
      'namedSubmitterPresent', CASE WHEN FOUND THEN v_readback_notice.submitted_by IS NOT NULL ELSE false END,
      'externalReceiptPresent', CASE WHEN FOUND THEN v_readback_notice.external_receipt_ref IS NOT NULL ELSE false END
    );
  ELSIF p_to_status = 'closed' THEN
    v_readback_passed := v_readback_passed
      AND v_readback_incident.assessment_readback_at IS NOT NULL
      AND EXISTS (
        SELECT 1
          FROM public.privacy_incident_actions
         WHERE incident_id = p_incident_id
           AND to_status = 'notified'
           AND readback_status = 'passed'
      );
    v_readback_checks := v_readback_checks || jsonb_build_object(
      'assessmentReadbackPresent', v_readback_incident.assessment_readback_at IS NOT NULL,
      'notificationReadbackPresent', EXISTS (
        SELECT 1
          FROM public.privacy_incident_actions
         WHERE incident_id = p_incident_id
           AND to_status = 'notified'
           AND readback_status = 'passed'
      )
    );
  END IF;

  IF NOT v_readback_passed THEN
    RAISE EXCEPTION 'privacy_incident_readback_failed';
  END IF;

  INSERT INTO privacy_retention.privacy_audit_events (
    event_type,
    actor_user_id,
    operation_id,
    correlation_id,
    preview_hash,
    status,
    reason_code,
    count_summary,
    request_metadata,
    occurred_at,
    retention_until
  ) VALUES (
    'privacy_incident_transition',
    p_actor_user_id,
    p_operation_id,
    p_correlation_id,
    p_preview_hash,
    'applied',
    upper(p_reason_code),
    public.privacy_incident_audit_count_summary(
      coalesce(v_readback_incident.affected_count_estimate, 0),
      cardinality(v_readback_incident.data_categories)
    ),
    jsonb_build_object('route', '/api/admin/privacy-incidents'),
    v_now,
    v_audit_retention_until
  );

  INSERT INTO privacy_retention.privacy_audit_events (
    event_type,
    actor_user_id,
    operation_id,
    correlation_id,
    preview_hash,
    status,
    reason_code,
    count_summary,
    request_metadata,
    occurred_at,
    retention_until
  ) VALUES (
    'privacy_incident_transition',
    p_actor_user_id,
    p_operation_id,
    p_correlation_id,
    p_preview_hash,
    'readback_passed',
    upper(p_reason_code),
    public.privacy_incident_audit_count_summary(
      coalesce(v_readback_incident.affected_count_estimate, 0),
      cardinality(v_readback_incident.data_categories)
    ),
    jsonb_build_object('route', '/api/admin/privacy-incidents'),
    v_now,
    v_audit_retention_until
  ) RETURNING id INTO v_audit_id;

  INSERT INTO public.privacy_incident_actions (
    id,
    incident_id,
    from_status,
    to_status,
    actor_user_id,
    reason_code,
    preview_hash,
    input_hash,
    correlation_id,
    expected_updated_at,
    idempotency_key,
    result_status,
    readback_status,
    audit_id
  ) VALUES (
    p_operation_id,
    p_incident_id,
    v_preview.from_status,
    p_to_status,
    p_actor_user_id,
    p_reason_code,
    p_preview_hash,
    v_input_hash,
    p_correlation_id,
    p_expected_updated_at,
    trim(p_idempotency_key),
    'applied',
    'passed',
    v_audit_id
  );

  UPDATE public.privacy_incident_transition_previews
     SET consumed_at = v_now
   WHERE operation_id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operationId', p_operation_id,
    'status', 'applied',
    'replayed', false,
    'auditId', v_audit_id,
    'readback', jsonb_build_object('passed', true, 'checks', v_readback_checks)
  );
END;
$_$;


--
-- Name: apply_privacy_retention_run(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_privacy_retention_run(p_run_id uuid, p_preview_hash text, p_idempotency_key text, p_max_duration_ms integer DEFAULT 10000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_run privacy_retention.privacy_retention_runs%ROWTYPE;
  v_item record;
  v_deleted integer;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_separated integer := 0;
  v_held integer := 0;
  v_failed integer := 0;
  v_audit_id uuid;
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  IF p_max_duration_ms IS NULL OR p_max_duration_ms NOT BETWEEN 1000 AND 10000 THEN
    RAISE EXCEPTION 'privacy_retention_timeout_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.set_config('statement_timeout', p_max_duration_ms::text, true);

  SELECT * INTO v_run FROM privacy_retention.privacy_retention_runs
  WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND OR v_run.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_run.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
    RAISE EXCEPTION 'privacy_retention_apply_binding_invalid' USING ERRCODE = '22023';
  END IF;
  IF v_run.status NOT IN ('confirmed', 'running', 'partial', 'held') THEN
    RAISE EXCEPTION 'privacy_retention_apply_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    v_run.class_code, v_run.adapter_version, v_run.source_mapping_version
  );

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-retention-run:' || v_run.id::text, 0)
  );
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_retention_run_items AS run_item
    LEFT JOIN privacy_retention.retention_class_adapter_bindings AS binding
      ON binding.class_code = v_run.class_code
     AND binding.source_type = run_item.source_type
     AND binding.status = 'active'
    LEFT JOIN privacy_retention.retention_adapter_versions AS version_row
      ON version_row.adapter_code = binding.adapter_code
     AND version_row.adapter_version = binding.adapter_version
     AND version_row.status = 'active'
     AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
    WHERE run_item.run_id = v_run.id AND version_row.adapter_code IS NULL
  ) THEN
    RAISE EXCEPTION 'privacy_retention_run_adapter_not_active' USING ERRCODE = '55000';
  END IF;

  UPDATE privacy_retention.privacy_retention_runs
  SET status = 'running', started_at = COALESCE(started_at, v_now)
  WHERE id = v_run.id;

  UPDATE privacy_retention.privacy_retention_run_items AS run_item
  SET status = 'held', error_code = NULL
  FROM privacy_retention.privacy_retention_work_items AS item
  WHERE run_item.run_id = v_run.id
    AND run_item.work_item_id = item.id
    AND run_item.status IN ('planned', 'failed')
    AND privacy_retention.g014_retention_active_hold_exists(item.subject_ref_hash, item.data_class, v_now);
  GET DIAGNOSTICS v_held = ROW_COUNT;

  FOR v_item IN
    SELECT run_item.work_item_id, item.source_ref_hash, item.subject_ref_hash, item.data_class,
           item.class_code, binding.adapter_code, binding.adapter_version,
           version_row.source_relation, version_row.source_identifier_column,
           version_row.removal_mode
    FROM privacy_retention.privacy_retention_run_items AS run_item
    JOIN privacy_retention.privacy_retention_work_items AS item ON item.id = run_item.work_item_id
    JOIN privacy_retention.retention_class_adapter_bindings AS binding
      ON binding.class_code = item.class_code
     AND binding.source_type = item.source_type
     AND binding.status = 'active'
    JOIN privacy_retention.retention_adapter_versions AS version_row
      ON version_row.adapter_code = binding.adapter_code
     AND version_row.adapter_version = binding.adapter_version
     AND version_row.status = 'active'
     AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
    WHERE run_item.run_id = v_run.id
      AND run_item.status = 'planned'
      AND item.status IN ('pending', 'failed')
      AND item.source_type NOT IN ('storage_object', 'ocr_artifact')
    ORDER BY item.trigger_at, item.id
    FOR UPDATE OF run_item, item SKIP LOCKED
  LOOP
    PERFORM privacy_retention.g014_retention_lock_subject_hash(v_item.subject_ref_hash);
    IF privacy_retention.g014_retention_active_hold_exists(v_item.subject_ref_hash, v_item.data_class, v_now) THEN
      UPDATE privacy_retention.privacy_retention_run_items
      SET status = 'held', error_code = NULL
      WHERE run_id = v_run.id AND work_item_id = v_item.work_item_id;
      v_held := v_held + 1;
      CONTINUE;
    END IF;

    IF v_item.removal_mode IS DISTINCT FROM 'delete' THEN
      UPDATE privacy_retention.privacy_retention_work_items
      SET status = 'failed', last_error_code = 'retention_adapter_removal_unsupported'
      WHERE id = v_item.work_item_id;
      UPDATE privacy_retention.privacy_retention_run_items
      SET status = 'failed', error_code = 'retention_adapter_removal_unsupported'
      WHERE run_id = v_run.id AND work_item_id = v_item.work_item_id;
      v_failed := v_failed + 1;
      CONTINUE;
    END IF;

    INSERT INTO privacy_retention.privacy_retained_records (
      work_item_id, class_code, data_class, subject_ref_hash, source_ref_hash,
      source_metadata_hash, retained_at, expires_at
    )
    SELECT item.id, item.class_code, item.data_class, item.subject_ref_hash,
           item.source_ref_hash, item.source_metadata_hash, v_now,
           item.trigger_at + class_row.retention_period
    FROM privacy_retention.privacy_retention_work_items AS item
    JOIN privacy_retention.privacy_retention_classes AS class_row ON class_row.code = item.class_code
    WHERE item.id = v_item.work_item_id
      AND class_row.status = 'active'
    ON CONFLICT (work_item_id) DO NOTHING;

    EXECUTE pg_catalog.format(
      'DELETE FROM %s WHERE privacy_retention.g014_retention_source_hash($1, %I::text) = $2',
      v_item.source_relation::regclass,
      v_item.source_identifier_column
    ) USING v_item.adapter_code, v_item.source_ref_hash;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    IF v_deleted = 1 AND privacy_retention.g014_retention_source_absent(
      v_item.adapter_code, v_item.source_relation, v_item.source_identifier_column, v_item.source_ref_hash
    ) THEN
      INSERT INTO privacy_retention.g014_retention_receipts (
        run_id, work_item_id, adapter_code, adapter_version, receipt_kind,
        source_ref_hash, source_absence_hash
      ) VALUES (
        v_run.id, v_item.work_item_id, v_item.adapter_code, v_item.adapter_version,
        'database_source_absence', v_item.source_ref_hash,
        privacy_retention.g014_retention_database_absence_hash(
          v_item.adapter_code, v_item.adapter_version, v_item.source_ref_hash
        )
      ) ON CONFLICT DO NOTHING;
      UPDATE privacy_retention.privacy_retention_work_items
      SET status = 'separated', last_error_code = NULL
      WHERE id = v_item.work_item_id;
      UPDATE privacy_retention.privacy_retention_run_items
      SET status = 'separated', error_code = NULL
      WHERE run_id = v_run.id AND work_item_id = v_item.work_item_id;
      v_separated := v_separated + 1;
    ELSE
      UPDATE privacy_retention.privacy_retention_work_items
      SET status = 'failed', last_error_code = 'retention_source_absence_not_proven'
      WHERE id = v_item.work_item_id;
      UPDATE privacy_retention.privacy_retention_run_items
      SET status = 'failed', error_code = 'retention_source_absence_not_proven'
      WHERE run_id = v_run.id AND work_item_id = v_item.work_item_id;
      v_failed := v_failed + 1;
    END IF;
  END LOOP;

  UPDATE privacy_retention.privacy_retention_run_items AS run_item
  SET status = 'failed', error_code = 'retention_source_busy'
  FROM privacy_retention.privacy_retention_work_items AS item
  WHERE run_item.run_id = v_run.id
    AND run_item.work_item_id = item.id
    AND run_item.status = 'planned'
    AND item.source_type NOT IN ('storage_object', 'ocr_artifact');

  UPDATE privacy_retention.privacy_retention_runs AS current_run
  SET separated_count = (
        SELECT count(*) FROM privacy_retention.privacy_retention_run_items
        WHERE run_id = current_run.id AND status = 'separated'
      ),
      held_count = (
        SELECT count(*) FROM privacy_retention.privacy_retention_run_items
        WHERE run_id = current_run.id AND status = 'held'
      ),
      failure_count = (
        SELECT count(*) FROM privacy_retention.privacy_retention_run_items
        WHERE run_id = current_run.id AND status = 'failed'
      ),
      no_active_hold_mutated =
        privacy_retention.g014_retention_no_active_hold_mutated(current_run.id)
  WHERE current_run.id = v_run.id
  RETURNING * INTO v_run;

  v_audit_id := privacy_retention.g014_retention_append_audit(v_run, 'applied', 'RETENTION_DATABASE_APPLY');
  UPDATE privacy_retention.privacy_retention_runs SET audit_id = v_audit_id WHERE id = v_run.id;

  RETURN pg_catalog.jsonb_build_object(
    'operationId', v_run.id,
    'status', 'partial',
    'readback', pg_catalog.jsonb_build_object(
      'passed', false,
      'checks', pg_catalog.jsonb_build_object(
        'expectedCountMatched', false,
        'databaseSourceAbsent', false,
        'storageProviderAbsent', false,
        'noActiveHoldMutated', v_run.no_active_hold_mutated
      )
    ),
    'auditId', v_audit_id,
    'adapterVersion', v_run.adapter_version,
    'sourceMappingVersion', v_run.source_mapping_version,
    'errorCode', NULL
  );
END;
$_$;


--
-- Name: apply_restaurant_admin_destructive_action(uuid, text, text, uuid[], uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_restaurant_admin_destructive_action(p_actor_user_id uuid, p_action text, p_reason text, p_target_restaurant_ids uuid[], p_correlation_id uuid, p_request_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_target_ids uuid[];
  v_before_snapshot jsonb;
  v_after_snapshot jsonb;
  v_audit_id uuid;
  v_locked_count integer;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required' USING ERRCODE = '42501';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor user id is required' USING ERRCODE = '22023';
  END IF;

  IF p_action NOT IN ('soft_delete_restaurant') THEN
    RAISE EXCEPTION 'unsupported restaurant destructive action' USING ERRCODE = '22023';
  END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason is required' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(DISTINCT target_id ORDER BY target_id)
  INTO v_target_ids
  FROM unnest(p_target_restaurant_ids) AS target_id
  WHERE target_id IS NOT NULL;

  IF v_target_ids IS NULL OR array_length(v_target_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'target restaurant ids are required' USING ERRCODE = '22023';
  END IF;

  WITH locked_targets AS (
    SELECT r.*
    FROM public.restaurants r
    WHERE r.id = ANY(v_target_ids)
    ORDER BY r.id
    FOR UPDATE
  )
  SELECT count(*), COALESCE(jsonb_agg(to_jsonb(locked_targets) ORDER BY locked_targets.id), '[]'::jsonb)
  INTO v_locked_count, v_before_snapshot
  FROM locked_targets;

  IF v_locked_count <> array_length(v_target_ids, 1) THEN
    RAISE EXCEPTION 'one or more target restaurants were not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.restaurants
  SET status = 'deleted',
      updated_at = now(),
      updated_by_admin_id = p_actor_user_id
  WHERE id = ANY(v_target_ids);

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.id), '[]'::jsonb)
  INTO v_after_snapshot
  FROM public.restaurants r
  WHERE r.id = ANY(v_target_ids);

  INSERT INTO public.restaurant_admin_destructive_audit_events (
    actor_user_id,
    action,
    reason,
    target_restaurant_ids,
    before_snapshot,
    after_snapshot,
    correlation_id,
    request_metadata,
    status,
    applied_at
  )
  VALUES (
    p_actor_user_id,
    p_action,
    btrim(p_reason),
    v_target_ids,
    v_before_snapshot,
    v_after_snapshot,
    p_correlation_id,
    COALESCE(p_request_metadata, '{}'::jsonb),
    'applied',
    now()
  )
  RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'audit_id', v_audit_id,
    'correlation_id', p_correlation_id,
    'target_restaurant_ids', v_target_ids,
    'deleted_target_ids', v_target_ids,
    'status', 'applied'
  );
EXCEPTION
  WHEN OTHERS THEN
    RAISE;
END;
$$;


--
-- Name: approve_admin_restaurant_map_overlay_proposal(uuid, uuid, text, text, text, text, jsonb, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_admin_restaurant_map_overlay_proposal(p_actor_user_id uuid, p_proposal_id uuid, p_expected_proposal_hash text, p_confirmation_text text, p_required_confirmation_text text, p_reason text, p_overlay_payload jsonb, p_preview_hash text, p_payload_hash text, p_correlation_id uuid, p_idempotency_key text, p_request_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_existing_audit public.admin_restaurant_map_overlay_audit_events%rowtype;
  v_proposal public.admin_restaurant_map_overlay_proposals%rowtype;
  v_overlay_before public.admin_restaurant_map_overlays%rowtype;
  v_overlay_after public.admin_restaurant_map_overlays%rowtype;
  v_audit public.admin_restaurant_map_overlay_audit_events%rowtype;
  v_now timestamptz := timezone('utc'::text, now());
  v_payload jsonb := coalesce(p_overlay_payload, '{}'::jsonb);
  v_request_metadata jsonb := coalesce(p_request_metadata, '{}'::jsonb);
  v_route_action text := v_payload ->> 'action';
  v_restaurant_id uuid;
  v_overlay_type text := v_payload ->> 'overlayType';
  v_label text := v_payload ->> 'label';
  v_description text := v_payload ->> 'description';
  v_active_from timestamptz;
  v_active_until timestamptz;
  v_evidence jsonb := coalesce(v_payload -> 'evidence', '{}'::jsonb);
  v_before_snapshot jsonb := '{}'::jsonb;
  v_after_snapshot jsonb := '{}'::jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception 'trend_proposal_approval_service_role_required';
  end if;

  if p_actor_user_id is null or p_proposal_id is null then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if p_confirmation_text is null or p_required_confirmation_text is null or p_confirmation_text <> p_required_confirmation_text then
    raise exception 'trend_proposal_confirmation_required';
  end if;

  if p_expected_proposal_hash is null or p_expected_proposal_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if p_preview_hash is null or p_preview_hash !~ '^[0-9a-f]{64}$' or p_payload_hash is null or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if p_correlation_id is null or p_idempotency_key is null or char_length(trim(p_idempotency_key)) < 8 or char_length(trim(p_idempotency_key)) > 128 then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if v_route_action <> 'upsert' then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if v_overlay_type not in ('trend', 'seasonal') then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  begin
    v_restaurant_id := (v_payload ->> 'restaurantId')::uuid;
  exception
    when invalid_text_representation then
      raise exception 'invalid_trend_proposal_approval_request';
  end;

  if v_restaurant_id is null then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if v_label is null or char_length(trim(v_label)) < 1 or char_length(trim(v_label)) > 80 then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if v_description is not null and char_length(v_description) > 500 then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  if nullif(v_payload ->> 'activeFrom', '') is not null then
    v_active_from := (v_payload ->> 'activeFrom')::timestamptz;
  end if;
  if nullif(v_payload ->> 'activeUntil', '') is not null then
    v_active_until := (v_payload ->> 'activeUntil')::timestamptz;
  end if;
  if v_active_from is not null and v_active_until is not null and v_active_from > v_active_until then
    raise exception 'trend_proposal_preview_stale';
  end if;

  if p_reason is null or char_length(trim(p_reason)) < 1 then
    raise exception 'invalid_trend_proposal_approval_request';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_actor_user_id::text || ':' || p_idempotency_key, 0));

  select *
    into v_existing_audit
    from public.admin_restaurant_map_overlay_audit_events
   where actor_user_id = p_actor_user_id
     and idempotency_key = p_idempotency_key;

  if found then
    if v_existing_audit.action = 'approve_proposal_overlay'
       and v_existing_audit.payload_hash = p_payload_hash
       and v_existing_audit.correlation_id = p_correlation_id
       and v_existing_audit.request_metadata ->> 'proposalId' = p_proposal_id::text
       and v_existing_audit.request_metadata ->> 'expectedProposalHash' = p_expected_proposal_hash
       and v_existing_audit.request_metadata ->> 'previewHash' = p_preview_hash
       and v_existing_audit.request_metadata ->> 'overlayType' = v_overlay_type
       and v_existing_audit.request_metadata ->> 'restaurantId' = v_restaurant_id::text
       and v_existing_audit.request_metadata ->> 'routeAction' = v_route_action
       and v_existing_audit.request_metadata ->> 'rpcAction' = 'approve_proposal_overlay' then
      select *
        into v_proposal
        from public.admin_restaurant_map_overlay_proposals
       where id = p_proposal_id;

      return jsonb_build_object(
        'ok', true,
        'status', 'approved',
        'replayed', true,
        'overlay', v_existing_audit.after_snapshot,
        'audit', jsonb_build_object(
          'domain', 'admin_restaurant_map_overlays',
          'source', 'admin_restaurant_map_overlay_audit_events',
          'auditId', v_existing_audit.id,
          'correlationId', v_existing_audit.correlation_id,
          'idempotencyKey', v_existing_audit.idempotency_key,
          'payloadHash', v_existing_audit.payload_hash,
          'appliedAt', v_existing_audit.applied_at
        ),
        'proposal', jsonb_build_object(
          'id', p_proposal_id,
          'proposalStatus', coalesce(v_proposal.proposal_status, 'approved'),
          'proposalHash', p_expected_proposal_hash,
          'overlayAuditId', v_existing_audit.id,
          'reviewedByAdminId', v_existing_audit.actor_user_id,
          'reviewedAt', v_existing_audit.applied_at,
          'reviewReason', v_existing_audit.reason
        ),
        'readback', jsonb_build_object(
          'matchedPayloadHash', true,
          'matchedPreviewHash', true,
          'matchedExpectedProposalHash', true,
          'replayed', true
        )
      );
    end if;

    raise exception 'trend_proposal_idempotency_conflict';
  end if;

  select *
    into v_proposal
    from public.admin_restaurant_map_overlay_proposals
   where id = p_proposal_id
   for update;

  if not found then
    raise exception 'trend_proposal_not_found';
  end if;

  if v_proposal.proposal_hash <> p_expected_proposal_hash then
    raise exception 'trend_proposal_hash_stale';
  end if;

  if v_proposal.restaurant_id <> v_restaurant_id or v_proposal.overlay_type <> v_overlay_type then
    raise exception 'trend_proposal_preview_stale';
  end if;

  if v_proposal.proposal_status <> 'pending' then
    raise exception 'trend_proposal_not_pending';
  end if;

  select *
    into v_overlay_before
    from public.admin_restaurant_map_overlays
   where restaurant_id = v_restaurant_id
     and overlay_type = v_overlay_type
   for update;

  if found then
    v_before_snapshot := to_jsonb(v_overlay_before);
    update public.admin_restaurant_map_overlays
       set label = trim(v_label),
           description = v_description,
           active_from = v_active_from,
           active_until = v_active_until,
           evidence = v_evidence,
           is_active = true,
           updated_by_admin_id = p_actor_user_id
     where restaurant_id = v_restaurant_id
       and overlay_type = v_overlay_type
     returning * into v_overlay_after;
  else
    insert into public.admin_restaurant_map_overlays (
      restaurant_id,
      overlay_type,
      label,
      description,
      active_from,
      active_until,
      evidence,
      is_active,
      created_by_admin_id,
      updated_by_admin_id
    ) values (
      v_restaurant_id,
      v_overlay_type,
      trim(v_label),
      v_description,
      v_active_from,
      v_active_until,
      v_evidence,
      true,
      p_actor_user_id,
      p_actor_user_id
    )
    returning * into v_overlay_after;
  end if;

  v_after_snapshot := to_jsonb(v_overlay_after);
  v_request_metadata := jsonb_build_object(
    'route', '/api/admin/trend-proposals/[proposalId]/approve',
    'proposalId', p_proposal_id,
    'expectedProposalHash', p_expected_proposal_hash,
    'previewHash', p_preview_hash,
    'payloadHash', p_payload_hash,
    'payloadVersion', 1,
    'overlayType', v_overlay_type,
    'restaurantId', v_restaurant_id,
    'routeAction', v_route_action,
    'rpcAction', 'approve_proposal_overlay',
    'correlationId', p_correlation_id,
    'idempotencyKey', trim(p_idempotency_key),
    'actorUserId', p_actor_user_id,
    'requestId', v_request_metadata ->> 'requestId',
    'ipHash', v_request_metadata ->> 'ipHash',
    'userAgentHash', v_request_metadata ->> 'userAgentHash'
  );

  insert into public.admin_restaurant_map_overlay_audit_events (
    actor_user_id,
    action,
    restaurant_id,
    overlay_type,
    reason,
    before_snapshot,
    after_snapshot,
    correlation_id,
    idempotency_key,
    payload_hash,
    request_metadata,
    status,
    applied_at
  ) values (
    p_actor_user_id,
    'approve_proposal_overlay',
    v_restaurant_id,
    v_overlay_type,
    trim(p_reason),
    v_before_snapshot,
    v_after_snapshot,
    p_correlation_id,
    trim(p_idempotency_key),
    p_payload_hash,
    v_request_metadata,
    'applied',
    v_now
  )
  returning * into v_audit;

  update public.admin_restaurant_map_overlay_proposals
     set proposal_status = 'approved',
         reviewed_by_admin_id = p_actor_user_id,
         reviewed_at = v_now,
         review_reason = trim(p_reason),
         overlay_audit_id = v_audit.id
   where id = p_proposal_id
   returning * into v_proposal;

  return jsonb_build_object(
    'ok', true,
    'status', 'approved',
    'replayed', false,
    'overlay', v_after_snapshot,
    'audit', jsonb_build_object(
      'domain', 'admin_restaurant_map_overlays',
      'source', 'admin_restaurant_map_overlay_audit_events',
      'auditId', v_audit.id,
      'correlationId', v_audit.correlation_id,
      'idempotencyKey', v_audit.idempotency_key,
      'payloadHash', v_audit.payload_hash,
      'appliedAt', v_audit.applied_at
    ),
    'proposal', jsonb_build_object(
      'id', v_proposal.id,
      'proposalStatus', v_proposal.proposal_status,
      'proposalHash', v_proposal.proposal_hash,
      'overlayAuditId', v_proposal.overlay_audit_id,
      'reviewedByAdminId', v_proposal.reviewed_by_admin_id,
      'reviewedAt', v_proposal.reviewed_at,
      'reviewReason', v_proposal.review_reason
    ),
    'readback', jsonb_build_object(
      'matchedPayloadHash', v_audit.payload_hash = p_payload_hash,
      'matchedPreviewHash', v_audit.request_metadata ->> 'previewHash' = p_preview_hash,
      'matchedExpectedProposalHash', v_audit.request_metadata ->> 'expectedProposalHash' = p_expected_proposal_hash,
      'replayed', false
    )
  );
exception
  when unique_violation then
    raise exception 'trend_proposal_idempotency_conflict';
  when invalid_datetime_format or datetime_field_overflow then
    raise exception 'trend_proposal_preview_stale';
end;
$_$;


--
-- Name: approve_edit_restaurant_submission(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_edit_restaurant_submission(p_submission_id uuid, p_admin_user_id uuid, p_approved_unique_ids uuid[]) RETURNS TABLE(success boolean, message text, updated_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_is_admin BOOLEAN;
    v_submission_record public.restaurant_submissions;
    v_restaurant_item JSONB;
    v_updated_count INTEGER := 0;
    v_total_count INTEGER := 0;
BEGIN
    -- 1. 관리자 권한 확인
    SELECT public.is_user_admin(p_admin_user_id) INTO v_is_admin;
    IF NOT v_is_admin THEN
        RETURN QUERY SELECT FALSE, '관리자 권한이 필요합니다.'::TEXT, 0;
        RETURN;
    END IF;

    -- 2. 제보 조회
    SELECT * INTO v_submission_record
    FROM public.restaurant_submissions
    WHERE id = p_submission_id 
      AND submission_type = 'edit'
      AND status = 'pending';

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, '처리할 수정 요청이 없거나 이미 처리되었습니다.'::TEXT, 0;
        RETURN;
    END IF;

    -- 3. user_restaurants_submission 배열의 각 항목 처리
    SELECT jsonb_array_length(v_submission_record.user_restaurants_submission) INTO v_total_count;

    FOR v_restaurant_item IN SELECT * FROM jsonb_array_elements(v_submission_record.user_restaurants_submission)
    LOOP
        -- 관리자가 승인한 항목만 처리
        IF (v_restaurant_item->>'unique_id')::UUID = ANY(p_approved_unique_ids) THEN
            -- restaurants 테이블 업데이트
            UPDATE public.restaurants
            SET
                name = COALESCE(v_restaurant_item->>'name', name),
                categories = COALESCE(
                    ARRAY(SELECT jsonb_array_elements_text(v_restaurant_item->'categories')),
                    categories
                ),
                phone = COALESCE(v_restaurant_item->>'phone', phone),
                road_address = COALESCE(v_restaurant_item->>'address', road_address),
                youtube_link = COALESCE(v_restaurant_item->>'youtube_link', youtube_link),
                tzuyang_review = COALESCE(v_restaurant_item->>'tzuyang_review', tzuyang_review),
                resource_type = 'user_submission_edit',
                updated_by_admin_id = p_admin_user_id,
                updated_at = now()
            WHERE unique_id = v_restaurant_item->>'unique_id';

            IF FOUND THEN
                v_updated_count := v_updated_count + 1;
            END IF;
        END IF;
    END LOOP;

    -- 4. 제보 상태 업데이트
    IF v_updated_count = v_total_count THEN
        -- 모두 승인
        UPDATE public.restaurant_submissions
        SET
            status = 'all_approved',
            resolved_by_admin_id = p_admin_user_id,
            reviewed_at = now(),
            updated_at = now()
        WHERE id = p_submission_id;
    ELSIF v_updated_count > 0 THEN
        -- 부분 승인
        UPDATE public.restaurant_submissions
        SET
            status = 'partially_approved',
            resolved_by_admin_id = p_admin_user_id,
            reviewed_at = now(),
            updated_at = now()
        WHERE id = p_submission_id;
    ELSE
        -- 모두 거부
        UPDATE public.restaurant_submissions
        SET
            status = 'all_deleted',
            resolved_by_admin_id = p_admin_user_id,
            reviewed_at = now(),
            updated_at = now()
        WHERE id = p_submission_id;
    END IF;

    RETURN QUERY SELECT TRUE, format('수정 요청이 처리되었습니다. (승인: %s/%s)', v_updated_count, v_total_count)::TEXT, v_updated_count;
END;
$$;


--
-- Name: FUNCTION approve_edit_restaurant_submission(p_submission_id uuid, p_admin_user_id uuid, p_approved_unique_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_edit_restaurant_submission(p_submission_id uuid, p_admin_user_id uuid, p_approved_unique_ids uuid[]) IS '기존 맛집 수정 요청 승인 (관리자 전용, 부분 승인 가능)';


--
-- Name: approve_edit_submission_item(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_edit_submission_item(p_item_id uuid, p_admin_user_id uuid, p_updated_data jsonb) RETURNS TABLE(success boolean, message text, restaurant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_admin boolean;
  v_item record;
  v_submission record;
  v_target_restaurant record;
  v_role text;
  v_constraint_name text;

  v_name text;
  v_phone text;
  v_categories text[];
  v_tzuyang_review text;
  v_youtube_link text;
  v_youtube_video_id text;
  v_identity_name text;
  v_jibun_address text;
  v_road_address text;
  v_english_address text;
  v_address_elements jsonb;
  v_lat numeric;
  v_lng numeric;
  v_youtube_meta jsonb;
begin
  v_role := current_setting('request.jwt.claim.role', true);
  if v_role is distinct from 'service_role' then
    if privacy_retention.g041_current_claim_user_id() is null or privacy_retention.g041_current_claim_user_id() <> p_admin_user_id then
      return query select false, '관리자 인증 정보가 일치하지 않습니다.'::text, null::uuid;
      return;
    end if;
  end if;

  select public.is_user_admin(p_admin_user_id) into v_is_admin;
  if not v_is_admin then
    return query select false, '관리자 권한이 필요합니다.'::text, null::uuid;
    return;
  end if;

  select * into v_item
  from public.restaurant_submission_items
  where id = p_item_id and item_status = 'pending';

  if not found then
    return query select false, '처리할 항목이 없거나 이미 처리되었습니다.'::text, null::uuid;
    return;
  end if;

  select * into v_submission
  from public.restaurant_submissions
  where id = v_item.submission_id;

  if v_item.target_restaurant_id is null then
    return query select false, '수정 대상 레스토랑 정보가 없습니다.'::text, null::uuid;
    return;
  end if;

  select * into v_target_restaurant
  from public.restaurants
  where id = v_item.target_restaurant_id;

  if not found then
    return query select false, '대상 레스토랑이 존재하지 않습니다.'::text, null::uuid;
    return;
  end if;

  v_name := nullif(p_updated_data->>'name', '');
  v_phone := nullif(p_updated_data->>'phone', '');
  v_tzuyang_review := nullif(p_updated_data->>'tzuyang_review', '');
  v_youtube_link := public.canonicalize_youtube_link(
    coalesce(nullif(p_updated_data->>'youtube_link', ''), v_target_restaurant.youtube_link)
  );
  v_youtube_video_id := public.extract_youtube_video_id(v_youtube_link);
  v_identity_name := public.normalize_restaurant_identity_name(
    public.resolve_restaurant_identity_name(
      coalesce(v_name, v_target_restaurant.approved_name),
      v_target_restaurant.origin_name,
      v_target_restaurant.naver_name,
      v_target_restaurant.google_name
    )
  );
  v_jibun_address := p_updated_data->>'jibun_address';
  v_road_address := p_updated_data->>'road_address';
  v_english_address := p_updated_data->>'english_address';
  v_address_elements := p_updated_data->'address_elements';
  v_lat := (p_updated_data->>'lat')::numeric;
  v_lng := (p_updated_data->>'lng')::numeric;
  v_youtube_meta := coalesce(p_updated_data->'youtube_meta', v_target_restaurant.youtube_meta);

  if p_updated_data->'categories' is not null and jsonb_typeof(p_updated_data->'categories') = 'array' then
    v_categories := array(select jsonb_array_elements_text(p_updated_data->'categories'));
    if cardinality(v_categories) = 0 then
      v_categories := null;
    end if;
  else
    v_categories := null;
  end if;

  if v_jibun_address is null or v_lat is null or v_lng is null then
    return query select false, '지오코딩 데이터가 필요합니다 (jibun_address, lat, lng).'::text, null::uuid;
    return;
  end if;

  if v_youtube_video_id <> '' and v_identity_name is not null and exists (
    select 1
    from public.restaurants r
    where r.id != v_item.target_restaurant_id
      and r.status <> 'deleted'
      and public.extract_youtube_video_id(r.youtube_link) = v_youtube_video_id
      and public.normalize_restaurant_identity_name(
        public.resolve_restaurant_identity_name(r.approved_name, r.origin_name, r.naver_name, r.google_name)
      ) = v_identity_name
  ) then
    return query select false, '이미 동일 영상/식당 조합의 active 레코드가 존재합니다.'::text, null::uuid;
    return;
  end if;

  if exists (
    select 1
    from public.restaurants r
    where r.id != v_item.target_restaurant_id
      and r.status <> 'deleted'
      and (
        (v_youtube_video_id <> ''
          and public.extract_youtube_video_id(r.youtube_link) = v_youtube_video_id
          and extensions.similarity(coalesce(r.approved_name, r.origin_name, ''), coalesce(v_name, v_target_restaurant.approved_name)) > 0.8)
        or extensions.similarity(coalesce(r.jibun_address, ''), v_jibun_address) > 0.9
        or extensions.similarity(coalesce(r.road_address, ''), coalesce(v_road_address, '')) > 0.9
      )
  ) then
    return query select false, '유사한 맛집이 이미 존재합니다. 중복 확인이 필요합니다.'::text, null::uuid;
    return;
  end if;

  begin
    update public.restaurants
    set
      phone = v_phone,
      categories = coalesce(v_categories, categories),
      road_address = coalesce(v_road_address, road_address),
      jibun_address = coalesce(v_jibun_address, jibun_address),
      english_address = coalesce(v_english_address, english_address),
      address_elements = coalesce(v_address_elements, address_elements),
      lat = v_lat,
      lng = v_lng,
      youtube_link = v_youtube_link,
      youtube_meta = coalesce(v_youtube_meta, youtube_meta),
      tzuyang_review = coalesce(v_tzuyang_review, tzuyang_review),
      geocoding_success = true,
      updated_by_admin_id = p_admin_user_id,
      updated_at = now(),
      approved_name = coalesce(v_name, approved_name)
    where id = v_item.target_restaurant_id;
  exception
    when unique_violation then
      get stacked diagnostics v_constraint_name = constraint_name;
      if v_constraint_name = 'idx_restaurants_active_video_identity' then
        return query select false, '이미 동일 영상/식당 조합의 active 레코드가 존재합니다.'::text, null::uuid;
        return;
      elsif v_constraint_name = 'restaurants_trace_id_key' then
        return query select false, '이미 동일 trace_id의 맛집이 존재합니다.'::text, null::uuid;
        return;
      end if;

      return query select false, '이미 동일 영상/식당 조합 또는 trace_id가 존재합니다.'::text, null::uuid;
      return;
  end;

  update public.restaurant_submission_items
  set item_status = 'approved'
  where id = p_item_id;

  update public.restaurant_submissions
  set
    resolved_by_admin_id = p_admin_user_id,
    reviewed_at = now()
  where id = v_item.submission_id;

  return query select true, '수정 승인이 완료되었습니다.'::text, v_item.target_restaurant_id;
end;
$$;


--
-- Name: FUNCTION approve_edit_submission_item(p_item_id uuid, p_admin_user_id uuid, p_updated_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_edit_submission_item(p_item_id uuid, p_admin_user_id uuid, p_updated_data jsonb) IS '수정 제보 항목 승인 - 관리자가 수정한 모든 값(youtube_link 포함) 사용';


--
-- Name: approve_new_restaurant_submission(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_new_restaurant_submission(p_submission_id uuid, p_admin_user_id uuid, p_geocoded_data jsonb) RETURNS TABLE(success boolean, message text, created_restaurant_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_is_admin BOOLEAN;
    v_submission_record public.restaurant_submissions;
    v_restaurant_item JSONB;
    v_generated_unique_id TEXT;
    v_new_restaurant_id UUID;
    v_created_ids UUID[] := ARRAY[]::UUID[];
    v_jibun_address TEXT;
    v_youtube_meta JSONB;
BEGIN
    -- 1. 관리자 권한 확인
    SELECT public.is_user_admin(p_admin_user_id) INTO v_is_admin;
    IF NOT v_is_admin THEN
        RETURN QUERY SELECT FALSE, '관리자 권한이 필요합니다.'::TEXT, ARRAY[]::UUID[];
        RETURN;
    END IF;

    -- 2. 제보 조회
    SELECT * INTO v_submission_record
    FROM public.restaurant_submissions
    WHERE id = p_submission_id 
      AND submission_type = 'new'
      AND status = 'pending';

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, '처리할 신규 제보가 없거나 이미 처리되었습니다.'::TEXT, ARRAY[]::UUID[];
        RETURN;
    END IF;

    -- 3. user_restaurants_submission 배열의 각 항목 처리
    FOR v_restaurant_item IN SELECT * FROM jsonb_array_elements(v_submission_record.user_restaurants_submission)
    LOOP
        -- 재지오코딩된 데이터에서 jibun_address 추출 (관리자가 승인 전 재지오코딩 필수)
        v_jibun_address := p_geocoded_data->>(v_restaurant_item->>'name')::TEXT;
        
        IF v_jibun_address IS NULL THEN
            RAISE NOTICE '경고: % 맛집의 지오코딩 데이터가 없습니다. 건너뜁니다.', v_restaurant_item->>'name';
            CONTINUE;
        END IF;

        -- unique_id 생성
        v_generated_unique_id := public.generate_unique_id(
            v_restaurant_item->>'name',
            v_jibun_address,
            v_restaurant_item->>'tzuyang_review'
        );

        -- 중복 검사
        IF EXISTS (
            SELECT 1 FROM public.restaurants 
            WHERE unique_id = v_generated_unique_id
        ) THEN
            RAISE NOTICE '경고: % 맛집은 이미 존재합니다. 건너뜁니다.', v_restaurant_item->>'name';
            CONTINUE;
        END IF;

        -- youtube_meta 가져오기 (실제로는 외부 API 호출 필요, 여기서는 placeholder)
        v_youtube_meta := jsonb_build_object(
            'title', '제목 없음',
            'ads_info', jsonb_build_object('is_ads', false, 'what_ads', null),
            'duration', 0,
            'is_shorts', false,
            'publishedAt', now()
        );

        -- restaurants 테이블에 INSERT
        INSERT INTO public.restaurants (
            unique_id,
            -- name, -- [삭제]
            categories,
            phone,
            road_address,
            jibun_address,
            lat,
            lng,
            youtube_link,
            youtube_meta,
            tzuyang_review,
            status,
            source_type,
            created_by,
            updated_by_admin_id,
            approved_name -- [수정] approved_name 추가
        )
        VALUES (
            v_generated_unique_id,
            -- v_restaurant_item->>'name', -- [삭제]
            ARRAY(SELECT jsonb_array_elements_text(v_restaurant_item->'categories')),
            v_restaurant_item->>'phone',
            p_geocoded_data->>(v_restaurant_item->>'name' || '_road'),
            v_jibun_address,
            (p_geocoded_data->>(v_restaurant_item->>'name' || '_lat'))::NUMERIC,
            (p_geocoded_data->>(v_restaurant_item->>'name' || '_lng'))::NUMERIC,
            v_restaurant_item->>'youtube_link',
            v_youtube_meta,
            v_restaurant_item->>'tzuyang_review',
            'approved',
            'user_submission_new',
            v_submission_record.user_id,
            p_admin_user_id,
            v_restaurant_item->>'name' -- [수정] approved_name 값 설정
        )
        RETURNING id INTO v_new_restaurant_id;

        v_created_ids := array_append(v_created_ids, v_new_restaurant_id);
    END LOOP;

    -- 4. 제보 상태 업데이트
    IF array_length(v_created_ids, 1) > 0 THEN
        UPDATE public.restaurant_submissions
        SET
            status = 'all_approved',
            resolved_by_admin_id = p_admin_user_id,
            reviewed_at = now(),
            updated_at = now()
        WHERE id = p_submission_id;

        RETURN QUERY SELECT TRUE, '신규 맛집 제보가 승인되었습니다.'::TEXT, v_created_ids;
    ELSE
        RETURN QUERY SELECT FALSE, '승인할 수 있는 맛집이 없습니다.'::TEXT, ARRAY[]::UUID[];
    END IF;
END;
$$;


--
-- Name: FUNCTION approve_new_restaurant_submission(p_submission_id uuid, p_admin_user_id uuid, p_geocoded_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_new_restaurant_submission(p_submission_id uuid, p_admin_user_id uuid, p_geocoded_data jsonb) IS '신규 맛집 제보 승인 (관리자 전용, 재지오코딩 필수)';


--
-- Name: approve_restaurant(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_restaurant(restaurant_id uuid, admin_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    is_admin BOOLEAN;
BEGIN
    -- 관리자 권한 확인
    SELECT EXISTS(
        SELECT 1 FROM public.user_roles 
        WHERE user_id = admin_user_id AND role = 'admin'
    ) INTO is_admin;
    
    IF NOT is_admin THEN
        RAISE EXCEPTION '관리자 권한이 필요합니다.';
    END IF;
    
    -- 맛집 승인 처리
    UPDATE public.restaurants
    SET 
        status = 'approved',
        updated_at = now(),
        updated_by_admin_id = admin_user_id
        -- approved_name = COALESCE(approved_name, name) -- [삭제] name이 없으므로 approved_name만 유지 혹은 origin_name 등 활용 필요. 일단 유지하되 name 참조 제거
        -- 만약 approved_name이 NULL이라면 origin_name 등으로 채워야 할 수도 있음.
        -- 여기서는 일단 추가 로직 없이 상태만 변경하거나, 필요한 경우 다른 컬럼 참조
    WHERE id = restaurant_id
    AND status = 'pending';
    
    RETURN FOUND;
END;
$$;


--
-- Name: FUNCTION approve_restaurant(restaurant_id uuid, admin_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_restaurant(restaurant_id uuid, admin_user_id uuid) IS '맛집 승인 처리 (관리자 전용)';


--
-- Name: approve_restaurant_submission(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_restaurant_submission(submission_id uuid, admin_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    submission_record public.restaurant_submissions;
    is_admin BOOLEAN;
BEGIN
    -- 1. 관리자 권한 확인
    SELECT public.is_user_admin(admin_user_id) INTO is_admin;
    IF NOT is_admin THEN
        RAISE EXCEPTION '관리자 권한이 필요합니다.';
    END IF;

    -- 2. 처리할 제보 조회 (pending 상태, 관리자가 입력한 최종 데이터 기준)
    SELECT * INTO submission_record
    FROM public.restaurant_submissions
    WHERE id = submission_id AND status = 'pending';

    IF NOT FOUND THEN
        RAISE EXCEPTION '처리할 제보가 없거나 이미 처리된 제보입니다.';
    END IF;

    -- 3. [관리자 검증] 필수 항목이 채워졌는지 확인 (지오코딩/수동입력 완료 여부)
    IF submission_record.name IS NULL OR
       submission_record.lat IS NULL OR
       submission_record.lng IS NULL OR
       submission_record.categories IS NULL OR
       (submission_record.road_address IS NULL AND submission_record.jibun_address IS NULL)
    THEN
        RAISE EXCEPTION '승인 실패: 필수 항목(이름, 좌표, 카테고리, 주소)이 누락되었습니다. 지오코딩 또는 수동 입력 후 승인하세요.';
    END IF;

    -- 4. 제보 유형에 따라 분기
    IF submission_record.submission_type = 'new' THEN
        
        -- 4-1. 신규 제보 승인 (INSERT into restaurants)
        INSERT INTO public.restaurants (
            name, phone, categories,
            lat, lng, road_address, jibun_address, english_address, address_elements,
            status, -- 'approved'로 즉시 승인
            source_type, -- 'user_submission_new'
            created_by, -- 제보한 사용자 ID
            updated_by_admin_id -- 승인한 관리자 ID
        )
        VALUES (
            submission_record.name, submission_record.phone, submission_record.categories,
            submission_record.lat, submission_record.lng, submission_record.road_address, 
            submission_record.jibun_address, submission_record.english_address, submission_record.address_elements,
            'approved',
            'user_submission_new', -- 요청하신 source_type
            submission_record.user_id,
            admin_user_id
        );

    ELSIF submission_record.submission_type = 'edit' THEN
    
        -- 4-2. 수정 제보 승인 (UPDATE restaurants)
        
        IF submission_record.restaurant_id IS NULL THEN
            RAISE EXCEPTION '승인 실패: 수정할 대상 맛집(restaurant_id)이 지정되지 않았습니다.';
        END IF;

        UPDATE public.restaurants r
        SET
            -- 관리자가 제보 테이블에 수정한 값으로 덮어쓰기
            -- (COALESCE 사용: 제보에 값이 있으면 그 값으로, 없으면(NULL) 기존 값 유지)
            name = COALESCE(submission_record.name, r.name),
            phone = COALESCE(submission_record.phone, r.phone),
            categories = COALESCE(submission_record.categories, r.categories),
            lat = COALESCE(submission_record.lat, r.lat),
            lng = COALESCE(submission_record.lng, r.lng),
            road_address = COALESCE(submission_record.road_address, r.road_address),
            jibun_address = COALESCE(submission_record.jibun_address, r.jibun_address),
            english_address = COALESCE(submission_record.english_address, r.english_address),
            address_elements = COALESCE(submission_record.address_elements, r.address_elements),
            
            status = 'approved', -- 'approved' 상태 보장
            source_type = 'user_submission_edit', -- 'modifying' 대신 'edit' 사용 (수정 가능)
            updated_by_admin_id = admin_user_id,
            updated_at = now()
        WHERE
            r.id = submission_record.restaurant_id;

        IF NOT FOUND THEN
             RAISE EXCEPTION '승인 실패: 수정할 대상 맛집(ID: %)을 찾을 수 없습니다.', submission_record.restaurant_id;
        END IF;

    END IF;

    -- 5. 제보 테이블 상태 'approved'로 변경
    UPDATE public.restaurant_submissions
    SET
        status = 'approved',
        resolved_by_admin_id = admin_user_id,
        updated_at = now()
    WHERE
        id = submission_id;

    RETURN TRUE;
END;
$$;


--
-- Name: FUNCTION approve_restaurant_submission(submission_id uuid, admin_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_restaurant_submission(submission_id uuid, admin_user_id uuid) IS '사용자 제보(신규/수정)를 승인하고 restaurants 테이블에 status=approved로 즉시 반영합니다. (관리자 전용)';


--
-- Name: approve_submission_item(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_submission_item(p_item_id uuid, p_admin_user_id uuid, p_restaurant_data jsonb) RETURNS TABLE(success boolean, message text, created_restaurant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_admin boolean;
  v_item record;
  v_submission record;
  v_generated_unique_id text;
  v_new_restaurant_id uuid;
  v_role text;
  v_constraint_name text;

  v_name text;
  v_phone text;
  v_categories text[];
  v_tzuyang_review text;
  v_youtube_link text;
  v_youtube_video_id text;
  v_identity_name text;
  v_jibun_address text;
  v_road_address text;
  v_english_address text;
  v_address_elements jsonb;
  v_lat numeric;
  v_lng numeric;
  v_youtube_meta jsonb;
begin
  v_role := current_setting('request.jwt.claim.role', true);
  if v_role is distinct from 'service_role' then
    if privacy_retention.g041_current_claim_user_id() is null or privacy_retention.g041_current_claim_user_id() <> p_admin_user_id then
      return query select false, '관리자 인증 정보가 일치하지 않습니다.'::text, null::uuid;
      return;
    end if;
  end if;

  select public.is_user_admin(p_admin_user_id) into v_is_admin;
  if not v_is_admin then
    return query select false, '관리자 권한이 필요합니다.'::text, null::uuid;
    return;
  end if;

  select * into v_item
  from public.restaurant_submission_items
  where id = p_item_id and item_status = 'pending';

  if not found then
    return query select false, '처리할 항목이 없거나 이미 처리되었습니다.'::text, null::uuid;
    return;
  end if;

  select * into v_submission
  from public.restaurant_submissions
  where id = v_item.submission_id;

  v_name := nullif(p_restaurant_data->>'name', '');
  v_phone := nullif(p_restaurant_data->>'phone', '');
  v_tzuyang_review := nullif(p_restaurant_data->>'tzuyang_review', '');
  v_youtube_link := public.canonicalize_youtube_link(
    coalesce(nullif(p_restaurant_data->>'youtube_link', ''), v_item.youtube_link)
  );
  v_youtube_video_id := public.extract_youtube_video_id(v_youtube_link);
  v_identity_name := public.normalize_restaurant_identity_name(
    public.resolve_restaurant_identity_name(v_name, null, null, null)
  );
  v_jibun_address := p_restaurant_data->>'jibun_address';
  v_road_address := p_restaurant_data->>'road_address';
  v_english_address := p_restaurant_data->>'english_address';
  v_address_elements := p_restaurant_data->'address_elements';
  v_lat := (p_restaurant_data->>'lat')::numeric;
  v_lng := (p_restaurant_data->>'lng')::numeric;
  v_youtube_meta := coalesce(p_restaurant_data->'youtube_meta', '{}'::jsonb);

  if p_restaurant_data->'categories' is not null and jsonb_typeof(p_restaurant_data->'categories') = 'array' then
    v_categories := array(select jsonb_array_elements_text(p_restaurant_data->'categories'));
    if cardinality(v_categories) = 0 then
      v_categories := null;
    end if;
  else
    v_categories := null;
  end if;

  if v_jibun_address is null or v_lat is null or v_lng is null then
    return query select false, '지오코딩 데이터가 필요합니다 (jibun_address, lat, lng).'::text, null::uuid;
    return;
  end if;

  if v_name is null then
    return query select false, '이름이 없습니다. trace_id 생성 불가'::text, null::uuid;
    return;
  end if;

  if v_youtube_video_id <> '' and v_identity_name is not null and exists (
    select 1
    from public.restaurants r
    where r.status <> 'deleted'
      and public.extract_youtube_video_id(r.youtube_link) = v_youtube_video_id
      and public.normalize_restaurant_identity_name(
        public.resolve_restaurant_identity_name(r.approved_name, r.origin_name, r.naver_name, r.google_name)
      ) = v_identity_name
  ) then
    return query select false, '이미 동일 영상/식당 조합의 active 레코드가 존재합니다.'::text, null::uuid;
    return;
  end if;

  if exists (
    select 1
    from public.restaurants r
    where r.status <> 'deleted'
      and (
        (v_youtube_video_id <> ''
          and public.extract_youtube_video_id(r.youtube_link) = v_youtube_video_id
          and extensions.similarity(coalesce(r.approved_name, r.origin_name, ''), v_name) > 0.8)
        or extensions.similarity(coalesce(r.jibun_address, ''), v_jibun_address) > 0.9
        or extensions.similarity(coalesce(r.road_address, ''), coalesce(v_road_address, '')) > 0.9
      )
  ) then
    return query select false, '이미 등록된 맛집/리뷰입니다 (링크 및 정보 유사).'::text, null::uuid;
    return;
  end if;

  v_generated_unique_id := public.generate_unique_id(
    v_youtube_link,
    v_name,
    v_tzuyang_review
  );

  if v_generated_unique_id is null or v_generated_unique_id = '' then
    return query select false, 'trace_id 생성에 실패했습니다.'::text, null::uuid;
    return;
  end if;

  begin
    insert into public.restaurants (
      trace_id,
      categories,
      phone,
      road_address,
      jibun_address,
      english_address,
      address_elements,
      lat,
      lng,
      youtube_link,
      youtube_meta,
      tzuyang_review,
      status,
      source_type,
      geocoding_success,
      created_by,
      updated_by_admin_id,
      approved_name
    )
    values (
      v_generated_unique_id,
      v_categories,
      v_phone,
      v_road_address,
      v_jibun_address,
      v_english_address,
      coalesce(v_address_elements, '{}'::jsonb),
      v_lat,
      v_lng,
      v_youtube_link,
      coalesce(v_youtube_meta, '{}'::jsonb),
      v_tzuyang_review,
      'approved',
      'user_submission_new',
      true,
      v_submission.user_id,
      p_admin_user_id,
      v_name
    )
    returning id into v_new_restaurant_id;
  exception
    when unique_violation then
      get stacked diagnostics v_constraint_name = constraint_name;
      if v_constraint_name = 'idx_restaurants_active_video_identity' then
        return query select false, '이미 동일 영상/식당 조합의 active 레코드가 존재합니다.'::text, null::uuid;
        return;
      elsif v_constraint_name = 'restaurants_trace_id_key' then
        return query select false, '이미 동일 trace_id의 맛집이 존재합니다.'::text, null::uuid;
        return;
      end if;

      return query select false, '이미 동일 영상/식당 조합 또는 trace_id가 존재합니다.'::text, null::uuid;
      return;
  end;

  if v_new_restaurant_id is null then
    return query select false, '음식점 생성/재사용에 실패했습니다.'::text, null::uuid;
    return;
  end if;

  update public.restaurant_submission_items
  set
    item_status = 'approved',
    target_restaurant_id = v_new_restaurant_id
  where id = p_item_id;

  if not found then
    return query select false, 'submission item 업데이트 실패'::text, null::uuid;
    return;
  end if;

  update public.restaurant_submissions
  set
    resolved_by_admin_id = p_admin_user_id,
    reviewed_at = now()
  where id = v_item.submission_id;

  return query select true, '승인이 완료되었습니다.'::text, v_new_restaurant_id;
end;
$$;


