--
-- Name: batch_insert_restaurants_from_jsonl(jsonb[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_insert_restaurants_from_jsonl(jsonl_array jsonb[]) RETURNS TABLE(inserted_count integer, updated_count integer, failed_count integer, failed_records jsonb[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    record JSONB;
    inserted INTEGER := 0;
    updated INTEGER := 0;
    failed INTEGER := 0;
    failed_list JSONB[] := ARRAY[]::JSONB[];
    result_id UUID;
BEGIN
    FOREACH record IN ARRAY jsonl_array
    LOOP
        BEGIN
            -- unique_id 존재 여부 확인
            IF EXISTS (SELECT 1 FROM public.restaurants WHERE unique_id = record->>'unique_id') THEN
                result_id := public.insert_restaurant_from_jsonl(record);
                updated := updated + 1;
            ELSE
                result_id := public.insert_restaurant_from_jsonl(record);
                inserted := inserted + 1;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                failed := failed + 1;
                failed_list := array_append(failed_list, jsonb_build_object(
                    'data', record,
                    'error', SQLERRM
                ));
        END;
    END LOOP;
    
    RETURN QUERY SELECT inserted, updated, failed, failed_list;
END;
$$;


--
-- Name: FUNCTION batch_insert_restaurants_from_jsonl(jsonl_array jsonb[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.batch_insert_restaurants_from_jsonl(jsonl_array jsonb[]) IS 'JSONL 배열을 한 번에 처리하여 restaurants 테이블에 삽입/업데이트';


--
-- Name: begin_account_deletion_apply(uuid, uuid, uuid, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_account_deletion_apply(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_confirmation_text text, p_idempotency_key text, p_reauthenticated_at timestamp with time zone, p_source_manifest_hash text) RETURNS TABLE(request_id uuid, status text, reason_code text, delete_count integer, anonymize_count integer, separate_count integer, retain_count integer, db_readback_passed boolean, storage_readback_passed boolean, session_readback_passed boolean, auth_readback_passed boolean, storage_receipt_refs jsonb, auth_receipt_ref text, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_policy public.account_deletion_policies%ROWTYPE;
  v_last_sign_in_at timestamptz;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_confirmation_text IS NULL OR p_idempotency_key IS NULL
     OR p_reauthenticated_at IS NULL OR p_source_manifest_hash IS NULL THEN
    RAISE EXCEPTION 'account_deletion_begin_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_source_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$' THEN
    RAISE EXCEPTION 'account_deletion_begin_arguments_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  SELECT * INTO v_request
  FROM public.account_deletion_requests
  WHERE id = p_request_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.reauthenticated_at IS DISTINCT FROM p_reauthenticated_at
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_begin_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  IF v_request.idempotency_key IS NOT NULL
     AND v_request.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
    RAISE EXCEPTION 'account_deletion_idempotency_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  IF v_request.status NOT IN ('previewed', 'applying', 'partial') THEN
    RAISE EXCEPTION 'account_deletion_begin_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(p_actor_user_id, p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
  IF v_request.source_manifest_hash IS DISTINCT FROM
       privacy_retention.g014_account_deletion_validate_manifest(v_request.policy_version) THEN
    RAISE EXCEPTION 'account_deletion_source_manifest_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  SELECT * INTO v_policy
  FROM public.account_deletion_policies
  WHERE version = v_request.policy_version
    AND status = 'active'
  FOR SHARE;
  IF NOT FOUND
     OR p_confirmation_text IS DISTINCT FROM v_policy.confirmation_text
     OR v_request.preview_expires_at <= pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_preview_or_policy_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  SELECT user_row.last_sign_in_at INTO v_last_sign_in_at
  FROM privacy_retention.g041_auth_users AS user_row
  WHERE user_row.id = p_actor_user_id;
  IF v_last_sign_in_at IS NULL
     OR v_last_sign_in_at < pg_catalog.clock_timestamp() - v_policy.reauth_max_age
     OR abs(EXTRACT(EPOCH FROM (p_reauthenticated_at - v_last_sign_in_at))) > 1 THEN
    RAISE EXCEPTION 'account_deletion_reauthentication_required' USING ERRCODE = '42501';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_reserve_admin_slot(p_request_id, p_target_user_id);
  UPDATE public.account_deletion_requests
  SET status = 'applying',
      idempotency_key = p_idempotency_key,
      reason_code = 'APPLY_STARTED'
  WHERE id = v_request.id
  RETURNING * INTO v_request;
  RETURN QUERY SELECT
    v_request.id,
    v_request.status,
    v_request.reason_code,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'delete') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'anonymize') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'separate') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'retain') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    v_request.db_readback_passed,
    v_request.storage_readback_passed,
    v_request.session_readback_passed,
    v_request.auth_readback_passed,
    CASE WHEN v_request.storage_readback_passed THEN privacy_retention.g014_account_deletion_storage_receipt_refs(v_request.id) ELSE NULL END,
    CASE WHEN v_request.auth_readback_passed THEN v_request.auth_receipt_ref ELSE NULL END,
    v_request.source_manifest_hash;
END;
$_$;


--
-- Name: begin_account_deletion_apply_with_reauth(uuid, uuid, uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_account_deletion_apply_with_reauth(p_proof_id uuid, p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_confirmation_text text, p_idempotency_key text, p_source_manifest_hash text) RETURNS TABLE(request_id uuid, status text, reason_code text, delete_count integer, anonymize_count integer, separate_count integer, retain_count integer, db_readback_passed boolean, storage_readback_passed boolean, session_readback_passed boolean, auth_readback_passed boolean, storage_receipt_refs jsonb, auth_receipt_ref text, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb := nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb;
  v_actor_user_id uuid := nullif(v_claims ->> 'sub', '')::uuid;
  v_reauthenticated_at timestamptz;
  v_original_role_claim text := current_setting('request.jwt.claim.role', true);
  v_result record;
BEGIN
  IF v_claims ->> 'role' IS DISTINCT FROM 'authenticated' OR v_actor_user_id IS NULL OR p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_actor_user_id <> v_actor_user_id OR p_target_user_id <> v_actor_user_id THEN RAISE EXCEPTION 'account_deletion_reauth_proof_invalid_actor'; END IF;
  PERFORM public.consume_account_deletion_reauth_proof(p_proof_id,p_target_user_id,p_request_id,p_idempotency_key);
  SELECT proofs.password_reauthenticated_at
  INTO STRICT v_reauthenticated_at
  FROM account_deletion_private.reauth_proofs AS proofs
  WHERE proofs.proof_id = p_proof_id
    AND proofs.actor_user_id = v_actor_user_id
    AND proofs.target_user_id = p_target_user_id
    AND proofs.request_id = p_request_id
    AND proofs.idempotency_key = btrim(p_idempotency_key)
    AND proofs.consumed_at IS NOT NULL;
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  SELECT * INTO STRICT v_result
  FROM public.begin_account_deletion_apply(p_actor_user_id,p_target_user_id,p_request_id,p_preview_hash,p_confirmation_text,p_idempotency_key,v_reauthenticated_at,p_source_manifest_hash);
  IF v_result.request_id IS DISTINCT FROM p_request_id
    OR v_result.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash
  THEN
    RAISE EXCEPTION 'account_deletion_reauth_begin_receipt_invalid';
  END IF;
  IF v_result.reason_code IS DISTINCT FROM 'APPLY_STARTED' THEN
    UPDATE account_deletion_private.reauth_proofs AS proofs
    SET consumed_at = NULL, request_id = NULL, idempotency_key = NULL
    WHERE proofs.proof_id = p_proof_id
      AND proofs.actor_user_id = v_actor_user_id
      AND proofs.target_user_id = p_target_user_id
      AND proofs.request_id = p_request_id
      AND proofs.idempotency_key = btrim(p_idempotency_key);
    v_result.reason_code := 'APPLY_NOT_STARTED';
    PERFORM set_config('request.jwt.claim.role',COALESCE(v_original_role_claim,''),true);
    RETURN QUERY SELECT v_result.request_id,v_result.status,v_result.reason_code,v_result.delete_count,v_result.anonymize_count,v_result.separate_count,v_result.retain_count,v_result.db_readback_passed,v_result.storage_readback_passed,v_result.session_readback_passed,v_result.auth_readback_passed,v_result.storage_receipt_refs,v_result.auth_receipt_ref,v_result.source_manifest_hash;
    RETURN;
  END IF;
  IF v_result.status IS DISTINCT FROM 'applying'
    OR v_result.delete_count IS NULL OR v_result.delete_count < 0
    OR v_result.anonymize_count IS NULL OR v_result.anonymize_count < 0
    OR v_result.separate_count IS NULL OR v_result.separate_count < 0
    OR v_result.retain_count IS NULL OR v_result.retain_count < 0
    OR v_result.db_readback_passed IS DISTINCT FROM false
    OR v_result.storage_readback_passed IS DISTINCT FROM false
    OR v_result.session_readback_passed IS DISTINCT FROM false
    OR v_result.auth_readback_passed IS DISTINCT FROM false
    OR v_result.storage_receipt_refs IS NOT NULL
    OR v_result.auth_receipt_ref IS NOT NULL
  THEN
    RAISE EXCEPTION 'account_deletion_reauth_begin_receipt_invalid';
  END IF;
  PERFORM set_config('request.jwt.claim.role',COALESCE(v_original_role_claim,''),true);
  DELETE FROM account_deletion_private.reauth_proofs AS proofs WHERE proofs.proof_id = p_proof_id;
  RETURN QUERY SELECT v_result.request_id,v_result.status,v_result.reason_code,v_result.delete_count,v_result.anonymize_count,v_result.separate_count,v_result.retain_count,v_result.db_readback_passed,v_result.storage_readback_passed,v_result.session_readback_passed,v_result.auth_readback_passed,v_result.storage_receipt_refs,v_result.auth_receipt_ref,v_result.source_manifest_hash;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('request.jwt.claim.role',COALESCE(v_original_role_claim,''),true);
  RAISE;
END; $$;


--
-- Name: calculate_submission_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_submission_status(p_submission_id uuid) RETURNS public.submission_status
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_total_count INTEGER;
    v_approved_count INTEGER;
    v_rejected_count INTEGER;
    v_pending_count INTEGER;
BEGIN
    SELECT 
        COUNT(*),
        COUNT(*) FILTER (WHERE item_status = 'approved'),
        COUNT(*) FILTER (WHERE item_status = 'rejected'),
        COUNT(*) FILTER (WHERE item_status = 'pending')
    INTO v_total_count, v_approved_count, v_rejected_count, v_pending_count
    FROM public.restaurant_submission_items
    WHERE submission_id = p_submission_id;

    -- 아직 처리 안 된 항목이 있으면 pending
    IF v_pending_count > 0 THEN
        RETURN 'pending';
    -- 모두 승인
    ELSIF v_approved_count = v_total_count THEN
        RETURN 'approved';
    -- 모두 거부
    ELSIF v_rejected_count = v_total_count THEN
        RETURN 'rejected';
    -- 일부만 승인 (나머지는 거부)
    ELSE
        RETURN 'partially_approved';
    END IF;
END;
$$;


--
-- Name: FUNCTION calculate_submission_status(p_submission_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_submission_status(p_submission_id uuid) IS 'items 상태 기반으로 submission 전체 상태 계산';


--
-- Name: calculate_word_match_score(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_word_match_score(restaurant_name text, search_query text) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    clean_name TEXT;
    clean_query TEXT;
    search_words TEXT[];
    matched_count INT := 0;
    total_words INT;
    word TEXT;
BEGIN
    -- 소문자 변환 (띄어쓰기는 유지)
    clean_name := LOWER(restaurant_name);
    clean_query := LOWER(search_query);
    
    -- 검색어를 띄어쓰기 기준으로 단어 배열로 변환
    search_words := string_to_array(clean_query, ' ');
    total_words := array_length(search_words, 1);
    
    -- 빈 문자열 처리
    IF total_words IS NULL OR total_words = 0 THEN
        RETURN 0.0;
    END IF;
    
    -- 각 단어가 맛집명에 포함되는지 확인
    FOREACH word IN ARRAY search_words LOOP
        IF word != '' AND clean_name LIKE '%' || word || '%' THEN
            matched_count := matched_count + 1;
        END IF;
    END LOOP;
    
    -- 일치 비율 반환 (0~1)
    RETURN matched_count::DOUBLE PRECISION / total_words;
END;
$$;


--
-- Name: FUNCTION calculate_word_match_score(restaurant_name text, search_query text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_word_match_score(restaurant_name text, search_query text) IS '검색어의 단어(띄어쓰기 기준)가 맛집명에 얼마나 포함되는지 0~1 사이의 점수 반환';


--
-- Name: canonicalize_youtube_link(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonicalize_youtube_link(raw_url text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select case
    when public.extract_youtube_video_id(raw_url) <> ''
      then 'https://www.youtube.com/watch?v=' || public.extract_youtube_video_id(raw_url)
    else nullif(btrim(raw_url), '')
  end;
$$;


--
-- Name: check_restaurant_duplicate(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_restaurant_duplicate(p_name text, p_jibun_address text, p_unique_id text DEFAULT NULL::text) RETURNS TABLE(is_duplicate boolean, duplicate_type text, existing_restaurant_id uuid, existing_name text, existing_address text, similarity_score numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- 1. unique_id 정확 일치 검사
    IF p_unique_id IS NOT NULL THEN
        RETURN QUERY
        SELECT 
            TRUE,
            'exact_unique_id'::TEXT,
            r.id,
            r.name,
            COALESCE(r.jibun_address, r.road_address),
            100.0::NUMERIC
        FROM public.restaurants r
        WHERE r.unique_id = p_unique_id
          AND r.status IN ('approved', 'pending')
        LIMIT 1;
        
        IF FOUND THEN
            RETURN;
        END IF;
    END IF;

    -- 2. 이름 + 주소 유사도 검사 (85% 이상)
    RETURN QUERY
    SELECT 
        TRUE,
        'similar_name_address'::TEXT,
        r.id,
        r.name,
        COALESCE(r.jibun_address, r.road_address),
        (
            extensions.similarity(LOWER(p_name), LOWER(r.name)) * 0.5 +
            extensions.similarity(LOWER(COALESCE(p_jibun_address, '')), LOWER(COALESCE(r.jibun_address, r.road_address, ''))) * 0.5
        ) * 100
    FROM public.restaurants r
    WHERE r.status IN ('approved', 'pending')
      AND r.jibun_address IS NOT NULL
      AND (
          extensions.similarity(LOWER(p_name), LOWER(r.name)) >= 0.7 OR
          extensions.similarity(LOWER(COALESCE(p_jibun_address, '')), LOWER(COALESCE(r.jibun_address, ''))) >= 0.8
      )
    ORDER BY (
        extensions.similarity(LOWER(p_name), LOWER(r.name)) * 0.5 +
        extensions.similarity(LOWER(COALESCE(p_jibun_address, '')), LOWER(COALESCE(r.jibun_address, r.road_address, ''))) * 0.5
    ) DESC
    LIMIT 5;

    -- 중복 없으면 빈 결과
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'none'::TEXT, NULL::UUID, NULL::TEXT, NULL::TEXT, 0.0::NUMERIC;
    END IF;
END;
$$;


--
-- Name: FUNCTION check_restaurant_duplicate(p_name text, p_jibun_address text, p_unique_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_restaurant_duplicate(p_name text, p_jibun_address text, p_unique_id text) IS '음식점 중복 검사 (unique_id 정확 일치 + 이름/주소 유사도 85%)';


--
-- Name: claim_account_deletion_external_job(uuid, uuid, uuid, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_account_deletion_external_job(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_phase text, p_attempt_token uuid) RETURNS TABLE(request_id uuid, phase text, claim_status text, attempt_token uuid, lease_expires_at timestamp with time zone, job_state text, checkpoint_state text, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_job privacy_retention.account_deletion_external_jobs%ROWTYPE;
  v_attempt privacy_retention.account_deletion_external_job_attempts%ROWTYPE;
  v_storage_object privacy_retention.account_deletion_storage_objects%ROWTYPE;
  v_storage_absent boolean;
  v_missing_proof_count integer;
  v_storage_verifier_only boolean := false;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_reconcile_status text;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL OR p_phase NOT IN ('session', 'storage', 'auth') THEN
    RAISE EXCEPTION 'account_deletion_external_job_claim_arguments_invalid'
      USING ERRCODE = '22004';
  END IF;

  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  SELECT * INTO v_request
  FROM public.account_deletion_requests
  WHERE id = p_request_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_external_job_claim_binding_mismatch'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_job
  FROM privacy_retention.account_deletion_external_jobs
  WHERE request_id = p_request_id AND phase = p_phase
  FOR UPDATE;
  IF FOUND THEN
    IF v_job.actor_user_id IS DISTINCT FROM p_actor_user_id
       OR v_job.target_user_id IS DISTINCT FROM p_target_user_id
       OR v_job.preview_hash IS DISTINCT FROM p_preview_hash
       OR v_job.idempotency_key IS DISTINCT FROM p_idempotency_key
       OR v_job.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
      RAISE EXCEPTION 'account_deletion_external_job_claim_binding_mismatch'
        USING ERRCODE = '55000';
    END IF;
    IF v_job.state = 'completed' THEN
      SELECT * INTO v_attempt
      FROM privacy_retention.account_deletion_external_job_attempts
      WHERE attempt_token = v_job.current_attempt_token
        AND request_id = p_request_id
        AND phase = p_phase
        AND state = 'completed'
      FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'account_deletion_external_job_completed_receipt_invalid'
          USING ERRCODE = '55000';
      END IF;
      IF p_attempt_token IS NOT NULL
         AND p_attempt_token IS DISTINCT FROM v_attempt.attempt_token THEN
        RAISE EXCEPTION 'account_deletion_external_job_completed_receipt_binding_mismatch'
          USING ERRCODE = '55000';
      END IF;
      RETURN QUERY SELECT p_request_id, p_phase, 'completed', v_attempt.attempt_token,
        NULL::timestamptz, 'completed', 'authoritative_absent', p_source_manifest_hash;
      RETURN;
    END IF;
  END IF;

  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_external_job_predecessor(v_request, p_phase);

  IF v_job.request_id IS NULL THEN
    INSERT INTO privacy_retention.account_deletion_external_jobs (
      request_id, phase, actor_user_id, target_user_id, preview_hash,
      idempotency_key, source_manifest_hash
    ) VALUES (
      p_request_id, p_phase, p_actor_user_id, p_target_user_id, p_preview_hash,
      p_idempotency_key, p_source_manifest_hash
    );
    SELECT * INTO v_job
    FROM privacy_retention.account_deletion_external_jobs
    WHERE request_id = p_request_id AND phase = p_phase
    FOR UPDATE;
  END IF;

  SELECT * INTO v_attempt
  FROM privacy_retention.account_deletion_external_job_attempts
  WHERE request_id = p_request_id
    AND phase = p_phase
    AND state IN ('leased', 'egress_unknown', 'reconciliation_required')
  ORDER BY claimed_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND
     AND p_attempt_token IS NOT NULL
     AND p_attempt_token IS DISTINCT FROM v_attempt.attempt_token THEN
    RETURN QUERY SELECT p_request_id, p_phase, 'busy', NULL::uuid, NULL::timestamptz,
      v_job.state, v_attempt.state, p_source_manifest_hash;
    RETURN;
  END IF;
  IF FOUND AND v_attempt.state = 'egress_unknown' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM privacy_retention.account_deletion_external_job_checkpoints AS checkpoint
      WHERE checkpoint.request_id = p_request_id
        AND checkpoint.phase = p_phase
        AND checkpoint.attempt_token = v_attempt.attempt_token
        AND checkpoint.checkpoint_kind = 'egress_unknown'
        AND checkpoint.checkpoint_state = 'unknown'
    ) THEN
      RAISE EXCEPTION 'account_deletion_external_job_egress_checkpoint_missing'
        USING ERRCODE = '55000';
    END IF;
    RETURN QUERY SELECT p_request_id, p_phase, 'replayed', v_attempt.attempt_token,
      NULL::timestamptz, 'egress_unknown', 'verify_absence_only', p_source_manifest_hash;
    RETURN;
  END IF;
  IF FOUND AND v_attempt.state = 'reconciliation_required' THEN
    RETURN QUERY SELECT p_request_id, p_phase, 'replayed', v_attempt.attempt_token,
      NULL::timestamptz, v_job.state, 'verify_absence_only', p_source_manifest_hash;
    RETURN;
  END IF;
  IF FOUND AND v_attempt.state = 'leased' AND v_attempt.lease_expires_at > v_now THEN
    IF p_attempt_token IS NOT NULL AND p_attempt_token = v_attempt.attempt_token THEN
      RETURN QUERY SELECT p_request_id, p_phase, 'replayed', v_attempt.attempt_token,
        v_attempt.lease_expires_at, v_job.state, 'delete_then_verify', p_source_manifest_hash;
    ELSE
      RETURN QUERY SELECT p_request_id, p_phase, 'busy', NULL::uuid, NULL::timestamptz,
        v_job.state, v_attempt.state, p_source_manifest_hash;
    END IF;
    RETURN;
  END IF;
  IF FOUND THEN
    v_reconcile_status := privacy_retention.g014_account_deletion_reconcile_expired_attempt(
      p_request_id, p_phase, v_attempt.attempt_token
    );
    SELECT * INTO v_job
    FROM privacy_retention.account_deletion_external_jobs
    WHERE request_id = p_request_id AND phase = p_phase
    FOR UPDATE;
    IF v_reconcile_status = 'completed' THEN
      RETURN QUERY SELECT p_request_id, p_phase, 'completed', v_job.current_attempt_token,
        NULL::timestamptz, 'completed', 'authoritative_absent', p_source_manifest_hash;
      RETURN;
    ELSIF v_reconcile_status = 'reconciliation_required' THEN
      RETURN QUERY SELECT p_request_id, p_phase, 'replayed', v_attempt.attempt_token,
        NULL::timestamptz, v_job.state, 'verify_absence_only', p_source_manifest_hash;
      RETURN;
    ELSIF v_reconcile_status <> 'released' THEN
      RAISE EXCEPTION 'account_deletion_external_job_reconciliation_result_invalid'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF v_job.state IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'account_deletion_external_job_attempt_state_invalid'
      USING ERRCODE = '55000';
  END IF;

  IF p_phase = 'storage' THEN
    v_storage_object := privacy_retention.g014_account_deletion_claim_storage_object(
      p_request_id, p_target_user_id
    );
    IF v_storage_object.request_id IS NULL THEN
      SELECT * INTO v_storage_object
      FROM privacy_retention.account_deletion_storage_objects AS captured
      WHERE captured.request_id = p_request_id
        AND NOT EXISTS (
          SELECT 1
          FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
          WHERE proof.request_id = p_request_id
            AND proof.phase = 'storage'
            AND proof.object_locator_hash = captured.object_locator_hash
            AND proof.object_version_hash = captured.object_version_hash
            AND proof.object_id = captured.object_id
            AND proof.object_version = captured.object_version
        )
        AND NOT EXISTS (
          SELECT 1
          FROM storage.objects AS object_row
          WHERE object_row.owner_id::text = p_target_user_id::text
            AND object_row.id = captured.object_id
            AND pg_catalog.to_jsonb(object_row) ->> 'version' = captured.object_version
        )
      ORDER BY captured.object_locator_hash, captured.object_version_hash
      LIMIT 1
      FOR SHARE;
      IF FOUND THEN
        v_storage_verifier_only := true;
      ELSE
        SELECT NOT EXISTS (
          SELECT 1 FROM storage.objects
          WHERE owner_id::text = p_target_user_id::text
        ) INTO v_storage_absent;
        SELECT count(*) INTO v_missing_proof_count
        FROM privacy_retention.account_deletion_storage_objects AS captured
        WHERE captured.request_id = p_request_id
          AND NOT EXISTS (
            SELECT 1
            FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
            WHERE proof.request_id = p_request_id
              AND proof.phase = 'storage'
              AND proof.object_locator_hash = captured.object_locator_hash
              AND proof.object_version_hash = captured.object_version_hash
              AND proof.object_id = captured.object_id
              AND proof.object_version = captured.object_version
          );
        IF NOT v_storage_absent OR v_missing_proof_count <> 0 THEN
          RAISE EXCEPTION 'account_deletion_storage_manifest_reconciliation_required'
            USING ERRCODE = '55000';
        END IF;
      END IF;
    END IF;
  END IF;

  INSERT INTO privacy_retention.account_deletion_external_job_attempts (
    request_id, phase, state, claimed_at, lease_expires_at, reconciled_at,
    storage_object_locator_hash, storage_object_version_hash,
    storage_object_id, storage_object_version
  ) VALUES (
    p_request_id, p_phase,
    CASE WHEN v_storage_verifier_only THEN 'reconciliation_required' ELSE 'leased' END,
    v_now, v_now + interval '5 minutes',
    CASE WHEN v_storage_verifier_only THEN v_now ELSE NULL END,
    v_storage_object.object_locator_hash, v_storage_object.object_version_hash,
    v_storage_object.object_id, v_storage_object.object_version
  )
  RETURNING * INTO v_attempt;

  UPDATE privacy_retention.account_deletion_external_jobs
  SET state = CASE WHEN v_storage_verifier_only THEN 'reconciliation_required' ELSE 'leased' END,
      current_attempt_token = v_attempt.attempt_token,
      updated_at = v_now
  WHERE request_id = p_request_id AND phase = p_phase;

  RETURN QUERY SELECT p_request_id, p_phase,
    CASE WHEN v_storage_verifier_only THEN 'replayed' ELSE 'claimed' END,
    v_attempt.attempt_token, v_attempt.lease_expires_at,
    CASE WHEN v_storage_verifier_only THEN 'reconciliation_required' ELSE 'leased' END,
    CASE WHEN v_storage_verifier_only THEN 'verify_absence_only' ELSE 'delete_then_verify' END,
    p_source_manifest_hash;
END;
$$;


--
-- Name: claim_account_deletion_external_phase(uuid, uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_account_deletion_external_phase(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_phase text) RETURNS TABLE(request_id uuid, phase text, lease_token uuid, lease_expires_at timestamp with time zone, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_lease privacy_retention.account_deletion_external_phase_leases%ROWTYPE;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL OR p_phase IS NULL THEN
    RAISE EXCEPTION 'account_deletion_external_claim_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF p_phase NOT IN ('storage', 'auth') THEN
    RAISE EXCEPTION 'account_deletion_external_claim_phase_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_request FROM public.account_deletion_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_external_claim_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(p_actor_user_id, p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
  IF v_request.status NOT IN ('applying', 'partial')
     OR (p_phase = 'storage' AND (NOT v_request.db_readback_passed OR NOT v_request.session_readback_passed OR v_request.storage_readback_passed))
     OR (p_phase = 'auth' AND (NOT v_request.storage_readback_passed OR v_request.auth_readback_passed)) THEN
    RAISE EXCEPTION 'account_deletion_external_claim_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  UPDATE privacy_retention.account_deletion_external_phase_leases
  SET status = 'released', consumed_at = v_now
  WHERE target_user_id = p_target_user_id
    AND phase = p_phase
    AND status = 'active'
    AND lease_expires_at <= v_now;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_external_phase_leases
    WHERE target_user_id = p_target_user_id
      AND phase = p_phase
      AND status = 'active'
      AND request_id IS DISTINCT FROM p_request_id
  ) THEN
    RAISE EXCEPTION 'account_deletion_external_claim_target_busy' USING ERRCODE = '55000';
  END IF;
  INSERT INTO privacy_retention.account_deletion_external_phase_leases (
    request_id, phase, target_user_id, lease_token, status, claimed_at, lease_expires_at
  ) VALUES (
    p_request_id, p_phase, p_target_user_id, extensions.gen_random_uuid(),
    'active', v_now, v_now + interval '5 minutes'
  ) ON CONFLICT (request_id, phase) DO UPDATE
    SET target_user_id = EXCLUDED.target_user_id,
        lease_token = EXCLUDED.lease_token,
        status = EXCLUDED.status,
        claimed_at = EXCLUDED.claimed_at,
        lease_expires_at = EXCLUDED.lease_expires_at,
        consumed_at = NULL
    WHERE privacy_retention.account_deletion_external_phase_leases.status = 'released';
  SELECT * INTO v_lease
  FROM privacy_retention.account_deletion_external_phase_leases
  WHERE request_id = p_request_id AND phase = p_phase
  FOR UPDATE;
  IF v_lease.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_lease.status IS DISTINCT FROM 'active'
     OR v_lease.lease_expires_at <= pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_external_claim_replay_invalid' USING ERRCODE = '55000';
  END IF;
  RETURN QUERY SELECT
    v_request.id, p_phase, v_lease.lease_token, v_lease.lease_expires_at, v_request.source_manifest_hash;
END;
$$;


--
-- Name: claim_admin_trend_job_request(text, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_admin_trend_job_request(p_claimed_by text, p_stale_after interval DEFAULT '00:30:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request public.admin_trend_job_requests%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'trend_job_request_service_role_required';
  end if;

  if p_claimed_by is null or btrim(p_claimed_by) = '' then
    raise exception 'trend_job_request_claimant_required';
  end if;

  with candidate as (
    select id
      from public.admin_trend_job_requests
     where status = 'queued'
        or (status = 'claimed' and claimed_at < timezone('utc'::text, now()) - p_stale_after and completed_at is null)
     order by created_at asc, id asc
     for update skip locked
     limit 1
  )
  update public.admin_trend_job_requests r
     set status = 'claimed',
         claimed_by = p_claimed_by,
         claimed_at = timezone('utc'::text, now()),
         updated_at = timezone('utc'::text, now())
    from candidate
   where r.id = candidate.id
  returning r.* into v_request;

  if not found then
    return jsonb_build_object('claimed', false, 'request', null);
  end if;

  return jsonb_build_object('claimed', true, 'request', to_jsonb(v_request));
end;
$$;


--
-- Name: claim_marketing_campaign_dispatch(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_marketing_campaign_dispatch(p_operation_id uuid, p_batch_id uuid, p_actor_user_id uuid, p_preview_hash text, p_idempotency_key text, p_timezone text DEFAULT 'Asia/Seoul'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_operation public.marketing_campaign_operations%ROWTYPE;
  v_batch public.marketing_campaign_batches%ROWTYPE;
  v_recipient privacy_retention.marketing_campaign_batch_recipients%ROWTYPE;
  v_permission record;
  v_claim_token uuid := extensions.gen_random_uuid();
  v_attempt_id uuid := extensions.gen_random_uuid();
  v_payload jsonb;
  v_payload_digest text;
  v_claimed integer := 0;
  v_suppressed integer := 0;
  v_requested integer := 0;
  v_pending integer := 0;
  v_audit_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_operation_id IS NULL
     OR p_batch_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_preview_hash IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9_-]{8,128}$'
     OR p_timezone IS DISTINCT FROM 'Asia/Seoul' THEN
    RAISE EXCEPTION 'marketing_claim_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_operation
  FROM public.marketing_campaign_operations AS operation
  WHERE operation.id = p_operation_id
  FOR UPDATE;
  SELECT * INTO v_batch
  FROM public.marketing_campaign_batches AS batch
  WHERE batch.id = p_batch_id
    AND batch.operation_id = p_operation_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_operation.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_operation.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_batch.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
    RAISE EXCEPTION 'marketing_batch_not_found' USING ERRCODE = '42501';
  END IF;
  IF v_operation.expires_at <= v_now THEN
    RAISE EXCEPTION 'marketing_preview_expired' USING ERRCODE = '22023';
  END IF;
  IF v_batch.status = 'completed' THEN
    RETURN pg_catalog.jsonb_build_object('status', 'completed', 'receipt', public.marketing_campaign_receipt(p_operation_id));
  END IF;
  IF v_batch.status IS DISTINCT FROM 'prepared' THEN
    RAISE EXCEPTION 'marketing_provider_outcome_unknown' USING ERRCODE = '55000';
  END IF;

  FOR v_recipient IN
    SELECT *
    FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
    WHERE recipient.batch_id = p_batch_id
      AND recipient.operation_id = p_operation_id
      AND recipient.status = 'eligible'
    ORDER BY recipient.user_id
    FOR UPDATE
  LOOP
    SELECT * INTO v_permission
    FROM privacy_retention.g014_marketing_permission_evidence(
      v_recipient.user_id, v_operation.channel, v_now, p_timezone
    );
    IF v_permission.allowed IS TRUE THEN
      UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
      SET status = 'claimed',
          ordinary_consent_event_id = v_permission.ordinary_consent_event_id,
          ordinary_subject_kind = v_permission.subject_kind,
          ordinary_guardian_verification_id = v_permission.guardian_verification_id,
          ordinary_purpose = v_operation.channel || '_marketing',
          ordinary_channel = v_operation.channel,
          ordinary_decision = 'granted',
          ordinary_policy_version_id = v_permission.policy_version_id,
          ordinary_notice_sha256 = v_permission.policy_content_sha256,
          night_consent_event_id = v_permission.night_consent_event_id,
          night_subject_kind = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.subject_kind END,
          night_guardian_verification_id = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.guardian_verification_id END,
          night_purpose = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE 'night_marketing' END,
          night_channel = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_operation.channel END,
          night_decision = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE 'granted' END,
          night_policy_version_id = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.policy_version_id END,
          night_notice_sha256 = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.policy_content_sha256 END,
          claim_token = v_claim_token,
          claimed_at = v_now
      WHERE recipient.batch_id = p_batch_id AND recipient.user_id = v_recipient.user_id;
      INSERT INTO privacy_retention.marketing_campaign_consent_evidence_keys (
        batch_id, operation_id, user_id, evidence_kind, consent_event_id, subject_kind,
        guardian_verification_id, purpose, channel, decision, policy_version_id, notice_sha256
      ) VALUES (
        p_batch_id, p_operation_id, v_recipient.user_id, 'claim_ordinary',
        v_permission.ordinary_consent_event_id, v_permission.subject_kind,
        v_permission.guardian_verification_id, v_operation.channel || '_marketing',
        v_operation.channel, 'granted', v_permission.policy_version_id, v_permission.policy_content_sha256
      );
      IF v_permission.night_consent_event_id IS NOT NULL THEN
        INSERT INTO privacy_retention.marketing_campaign_consent_evidence_keys (
          batch_id, operation_id, user_id, evidence_kind, consent_event_id, subject_kind,
          guardian_verification_id, purpose, channel, decision, policy_version_id, notice_sha256
        ) VALUES (
          p_batch_id, p_operation_id, v_recipient.user_id, 'claim_night',
          v_permission.night_consent_event_id, v_permission.subject_kind,
          v_permission.guardian_verification_id, 'night_marketing',
          v_operation.channel, 'granted', v_permission.policy_version_id, v_permission.policy_content_sha256
        );
      END IF;
      UPDATE public.marketing_campaign_recipients AS recipient
      SET consent_event_id = v_permission.ordinary_consent_event_id,
          night_consent_event_id = v_permission.night_consent_event_id,
          updated_at = v_now
      WHERE recipient.operation_id = p_operation_id AND recipient.user_id = v_recipient.user_id;
      v_claimed := v_claimed + 1;
    ELSE
      UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
      SET status = 'suppressed', finalized_at = v_now
      WHERE recipient.batch_id = p_batch_id AND recipient.user_id = v_recipient.user_id;
      UPDATE public.marketing_campaign_recipients AS recipient
      SET status = 'suppressed', consent_event_id = NULL, night_consent_event_id = NULL, updated_at = v_now
      WHERE recipient.operation_id = p_operation_id AND recipient.user_id = v_recipient.user_id;
      v_suppressed := v_suppressed + 1;
    END IF;
  END LOOP;

  SELECT count(*)::integer INTO v_requested
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id;
  SELECT count(*)::integer INTO v_pending
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id
    AND recipient.status IN ('pending', 'eligible');

  IF v_claimed = 0 THEN
    PERFORM privacy_retention.g014_require_active_admin_actor(p_actor_user_id);
    UPDATE public.marketing_campaign_batches AS batch
    SET status = 'completed', completed_at = v_now
    WHERE batch.id = p_batch_id;
    IF v_pending = 0 THEN
      v_audit_id := privacy_retention.g014_marketing_write_audit(
        p_operation_id, p_preview_hash, 'applied', 'MARKETING_CLAIM_SUPPRESSED', NULL,
        v_requested, 0, v_suppressed, 0
      );
      UPDATE public.marketing_campaign_operations AS operation
      SET status = 'applied', audit_id = v_audit_id, updated_at = v_now
      WHERE operation.id = p_operation_id;
      RETURN pg_catalog.jsonb_build_object('status', 'completed', 'receipt', public.marketing_campaign_receipt(p_operation_id));
    END IF;
    RETURN pg_catalog.jsonb_build_object('status', 'suppressed', 'operationId', p_operation_id::text, 'batchId', p_batch_id::text);
  END IF;

  SELECT pg_catalog.jsonb_build_object(
    'operationId', p_operation_id::text,
    'batchId', p_batch_id::text,
    'claimToken', v_claim_token::text,
    'providerAttemptId', v_attempt_id::text,
    'idempotencyKey', v_batch.idempotency_key,
    'channel', v_operation.channel,
    'title', v_operation.title,
    'message', v_operation.message,
    'data', v_operation.data,
    'recipientUserIds', pg_catalog.jsonb_agg(recipient.user_id::text ORDER BY recipient.user_id)
  ) INTO v_payload
  FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
  WHERE recipient.batch_id = p_batch_id
    AND recipient.operation_id = p_operation_id
    AND recipient.status = 'claimed'
    AND recipient.claim_token = v_claim_token;
  v_payload_digest := pg_catalog.encode(extensions.digest(v_payload::text, 'sha256'), 'hex');
  -- This second authority check is intentionally adjacent to the durable unknown
  -- attempt. Its row locks fence admin-role/account revocation through egress.
  PERFORM privacy_retention.g014_require_active_admin_actor(p_actor_user_id);
  INSERT INTO privacy_retention.marketing_campaign_provider_attempts (
    id, operation_id, batch_id, claim_token, provider_identity, idempotency_key,
    payload_digest, status
  ) VALUES (
    v_attempt_id, p_operation_id, p_batch_id, v_claim_token, 'g014_https_provider_v1',
    v_batch.idempotency_key, v_payload_digest, 'unknown'
  );
  UPDATE public.marketing_campaign_batches AS batch
  SET status = 'claimed', claim_token = v_claim_token, claimed_at = v_now
  WHERE batch.id = p_batch_id;
  v_audit_id := privacy_retention.g014_marketing_write_audit(
    p_operation_id, p_preview_hash, 'confirmed', 'MARKETING_DISPATCH_CLAIMED', NULL,
    v_requested, v_claimed, v_suppressed, 0
  );
  UPDATE public.marketing_campaign_operations AS operation
  SET status = 'applying', audit_id = v_audit_id, updated_at = v_now
  WHERE operation.id = p_operation_id;

  RETURN pg_catalog.jsonb_build_object(
    'status', 'claimed',
    'operationId', p_operation_id::text,
    'batchId', p_batch_id::text,
    'claimToken', v_claim_token::text,
    'providerAttemptId', v_attempt_id::text,
    'providerIdentity', 'g014_https_provider_v1',
    'idempotencyKey', v_batch.idempotency_key,
    'payloadDigest', v_payload_digest,
    'payload', v_payload
  );
END;
$_$;


--
-- Name: claim_next_account_deletion_external_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_next_account_deletion_external_job() RETURNS TABLE(actor_user_id uuid, target_user_id uuid, request_id uuid, preview_hash text, idempotency_key text, source_manifest_hash text, phase text, attempt_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job record;
  v_claim record;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();

  -- Discovery deliberately does not lock a job first: the exact claim RPC takes
  -- the target lock before its job lock, so concurrent schedulers serialize at
  -- the same durable one-winner boundary without inversion.
  FOR v_job IN
    SELECT
      job.actor_user_id,
      job.target_user_id,
      job.request_id,
      job.preview_hash,
      job.idempotency_key,
      job.source_manifest_hash,
      job.phase,
      job.current_attempt_token
    FROM privacy_retention.account_deletion_external_jobs AS job
    JOIN public.account_deletion_requests AS request_row
      ON request_row.id = job.request_id
    WHERE job.state IN ('pending', 'leased', 'egress_unknown', 'reconciliation_required')
      AND request_row.status IN ('applying', 'partial')
      AND request_row.source_manifest_hash = job.source_manifest_hash
      AND (
        (job.phase = 'session'
          AND request_row.db_readback_passed
          AND NOT request_row.session_readback_passed)
        OR (job.phase = 'storage'
          AND request_row.db_readback_passed
          AND request_row.session_readback_passed
          AND NOT request_row.storage_readback_passed)
        OR (job.phase = 'auth'
          AND request_row.db_readback_passed
          AND request_row.session_readback_passed
          AND request_row.storage_readback_passed
          AND NOT request_row.auth_readback_passed)
      )
      AND (
        job.state <> 'leased'
        OR NOT EXISTS (
          SELECT 1
          FROM privacy_retention.account_deletion_external_job_attempts AS attempt
          WHERE attempt.attempt_token = job.current_attempt_token
            AND attempt.state = 'leased'
            AND attempt.lease_expires_at > pg_catalog.clock_timestamp()
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM privacy_retention.privacy_legal_holds AS hold_row
        JOIN privacy_retention.account_deletion_hold_class_map AS hold_map
          ON hold_map.hold_data_class = hold_row.data_class
        WHERE hold_map.deletion_class = 'account_deletion'
          AND hold_row.subject_ref_hash =
              privacy_retention.g014_account_deletion_subject_hash(job.target_user_id)
          AND hold_row.status = 'active'
          AND (
            hold_row.expires_at IS NULL
            OR hold_row.expires_at > pg_catalog.clock_timestamp()
          )
      )
    ORDER BY
      request_row.created_at,
      CASE job.phase
        WHEN 'session' THEN 1
        WHEN 'storage' THEN 2
        ELSE 3
      END,
      job.request_id
    LIMIT 64
  LOOP
    BEGIN
      SELECT * INTO v_claim
      FROM public.claim_account_deletion_external_job(
        v_job.actor_user_id,
        v_job.target_user_id,
        v_job.request_id,
        v_job.preview_hash,
        v_job.idempotency_key,
        v_job.source_manifest_hash,
        v_job.phase,
        v_job.current_attempt_token
      );
    EXCEPTION WHEN SQLSTATE '55000' THEN
      -- A stale or independently reconciled candidate must not abort dispatch
      -- for later jobs. The owner-scoped claim remains the only authority.
      CONTINUE;
    END;

    -- Another scheduler may have won after our read. The nested claim is the
    -- only ownership boundary, so move on rather than returning a stale lease.
    IF v_claim.claim_status = 'busy' THEN
      CONTINUE;
    END IF;
    IF v_claim.claim_status IN ('claimed', 'replayed')
       AND v_claim.attempt_token IS NOT NULL THEN
      RETURN QUERY SELECT
        v_job.actor_user_id,
        v_job.target_user_id,
        v_job.request_id,
        v_job.preview_hash,
        v_job.idempotency_key,
        v_job.source_manifest_hash,
        v_job.phase,
        v_claim.attempt_token;
      RETURN;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: claim_privacy_retention_storage_items(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_privacy_retention_storage_items(p_run_id uuid, p_preview_hash text, p_idempotency_key text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb;
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'privacy_retention_storage_limit_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'workItemId', claim_row.work_item_id,
        'claimToken', claim_row.claim_token,
        'objectLocatorHash', claim_row.object_locator_hash,
        'objectVersionHash', claim_row.object_version_hash,
        'claimHash', claim_row.claim_hash,
        'adapterVersion', claim_row.adapter_version,
        'sourceMappingVersion', claim_row.source_mapping_version
      )
      ORDER BY claim_row.work_item_id
    ),
    '[]'::jsonb
  ) INTO v_claims
  FROM privacy_retention.g014_retention_claim_storage_items_internal(
    p_run_id, p_preview_hash, p_idempotency_key, p_limit
  ) AS claim_row;

  RETURN v_claims;
END;
$$;


