  );
$_$;


--
-- Name: cleanup_old_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_notifications(days_to_keep integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM public.notifications
    WHERE created_at < now() - (days_to_keep || ' days')::INTERVAL
    AND is_read = true;
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


--
-- Name: FUNCTION cleanup_old_notifications(days_to_keep integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_old_notifications(days_to_keep integer) IS '오래된 읽은 알림 삭제 (기본: 90일)';


--
-- Name: cleanup_old_search_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_search_logs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.search_logs
  WHERE searched_at < NOW() - INTERVAL '90 days';
  
  RAISE NOTICE 'Old search logs have been cleaned up at %', NOW();
END;
$$;


--
-- Name: compare_and_set_current_profile_avatar(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compare_and_set_current_profile_avatar(p_expected_avatar_reference text, p_next_avatar_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid;
  v_nickname text;
  v_current_reference text;
  v_next_reference text;
  v_eligibility jsonb;
  v_status text;
  v_reason_code text;
  v_changed boolean;
  v_rows integer;
BEGIN
  v_user_id := privacy_retention.g041_current_claim_user_id();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'profile_authentication_required'
      USING ERRCODE = '42501';
  END IF;

  PERFORM status_row.user_id
    FROM public.user_account_status AS status_row
   WHERE status_row.user_id = v_user_id
     AND status_row.account_status = 'active'
     AND status_row.disabled_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_account_inactive'
      USING ERRCODE = '42501';
  END IF;

  v_eligibility :=
    privacy_retention.g014_privacy_eligibility_receipt(v_user_id);
  IF COALESCE((v_eligibility ->> 'eligible')::boolean, false)
     IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'profile_privacy_ineligible'
      USING ERRCODE = '42501';
  END IF;

  IF p_expected_avatar_reference IS NOT NULL
     AND pg_catalog.octet_length(p_expected_avatar_reference) > 4096 THEN
    RAISE EXCEPTION 'profile_avatar_expected_reference_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT profile.nickname, profile.avatar_url
    INTO v_nickname, v_current_reference
    FROM public.profiles AS profile
   WHERE profile.user_id = v_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found'
      USING ERRCODE = 'P0002';
  END IF;
  IF v_nickname = '탈퇴한 사용자' THEN
    RAISE EXCEPTION 'profile_account_deleted'
      USING ERRCODE = '42501';
  END IF;

  IF v_current_reference IS DISTINCT FROM p_expected_avatar_reference THEN
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'status', 'conflict',
      'reasonCode', 'PROFILE_VERSION_CONFLICT',
      'profile', pg_catalog.jsonb_build_object(
        'userId', v_user_id::text,
        'nickname', v_nickname,
        'avatarReference', v_current_reference
      ),
      'changes', pg_catalog.jsonb_build_object('avatar', false),
      'readback', pg_catalog.jsonb_build_object('passed', true)
    );
  END IF;

  v_next_reference := CASE
    WHEN p_next_avatar_operation_id IS NULL THEN NULL
    ELSE 'profile-avatar://' || v_user_id::text || '/avatar-'
      || pg_catalog.lower(p_next_avatar_operation_id::text) || '.jpg'
  END;

  IF v_current_reference IS NOT DISTINCT FROM v_next_reference THEN
    v_status := 'unchanged';
    v_reason_code := 'PROFILE_AVATAR_UNCHANGED';
    v_changed := false;
  ELSE
    UPDATE public.profiles AS profile
       SET avatar_url = v_next_reference,
           updated_at = pg_catalog.clock_timestamp()
     WHERE profile.user_id = v_user_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'profile_avatar_readback_failed'
        USING ERRCODE = '55000';
    END IF;
    SELECT profile.nickname, profile.avatar_url
      INTO v_nickname, v_current_reference
      FROM public.profiles AS profile
     WHERE profile.user_id = v_user_id;
    IF NOT FOUND
       OR v_nickname = '탈퇴한 사용자'
       OR v_current_reference IS DISTINCT FROM v_next_reference THEN
      RAISE EXCEPTION 'profile_avatar_readback_failed'
        USING ERRCODE = '55000';
    END IF;
    v_status := 'applied';
    v_reason_code := 'PROFILE_AVATAR_UPDATED';
    v_changed := true;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'status', v_status,
    'reasonCode', v_reason_code,
    'profile', pg_catalog.jsonb_build_object(
      'userId', v_user_id::text,
      'nickname', v_nickname,
      'avatarReference', v_current_reference
    ),
    'changes', pg_catalog.jsonb_build_object('avatar', v_changed),
    'readback', pg_catalog.jsonb_build_object('passed', true)
  );
END
$$;


--
-- Name: complete_admin_trend_job_request(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_admin_trend_job_request(p_request_id uuid, p_claimed_by text, p_run_id uuid, p_result_summary jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request public.admin_trend_job_requests%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'trend_job_request_service_role_required';
  end if;

  update public.admin_trend_job_requests
     set status = 'succeeded',
         run_id = p_run_id,
         result_summary = coalesce(p_result_summary, '{}'::jsonb),
         completed_at = timezone('utc'::text, now()),
         updated_at = timezone('utc'::text, now())
   where id = p_request_id
     and status = 'claimed'
     and claimed_by = p_claimed_by
  returning * into v_request;

  if not found then
    raise exception 'trend_job_request_finalize_failed';
  end if;

  return jsonb_build_object('ok', true, 'status', v_request.status, 'requestId', v_request.id, 'runId', v_request.run_id, 'errorCode', v_request.error_code, 'completedAt', v_request.completed_at);
end;
$$;


--
-- Name: complete_receipt_ocr_result(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_receipt_ocr_result(p_result_id uuid, p_claim_token uuid, p_result_payload jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  SELECT ocr_private.complete_receipt_ocr_result($1, $2, $3);
$_$;


--
-- Name: confirm_privacy_onboarding(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_privacy_onboarding(p_challenge_id uuid, p_challenge_token text, p_user_id uuid, p_source text, p_guardian_verification_id uuid, p_oauth_nonce_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_was_consumed boolean := false;
  v_challenge_oauth_nonce_hash text;
  v_challenge_token_hash text;
  v_receipt jsonb;
BEGIN
  PERFORM privacy_retention.g014_require_service_role();

  -- Lock before delegating so a concurrent caller cannot misclassify its result
  -- or substitute an OAuth nonce after the challenge has been issued.
  IF p_challenge_id IS NULL
     OR p_user_id IS NULL
     OR p_challenge_token IS NULL
     OR pg_catalog.length(p_challenge_token) NOT BETWEEN 16 AND 512
     OR p_source NOT IN ('password_signup', 'oauth') THEN
    RAISE EXCEPTION 'privacy_onboarding_confirmation_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT
    challenge.consumed_at IS NOT NULL,
    challenge.oauth_nonce_hash,
    challenge.token_hash
    INTO v_was_consumed, v_challenge_oauth_nonce_hash, v_challenge_token_hash
  FROM privacy_retention.privacy_onboarding_challenges AS challenge
  WHERE challenge.id = p_challenge_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_challenge_token_hash IS DISTINCT FROM pg_catalog.encode(extensions.digest(p_challenge_token, 'sha256'), 'hex') THEN
    RAISE EXCEPTION 'privacy_onboarding_challenge_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_source = 'oauth' THEN
    IF p_oauth_nonce_hash IS NULL
      OR p_oauth_nonce_hash !~ '^[0-9a-f]{64}$'
      OR v_challenge_oauth_nonce_hash IS NULL
      OR p_oauth_nonce_hash IS DISTINCT FROM v_challenge_oauth_nonce_hash THEN
      RAISE EXCEPTION 'privacy_oauth_nonce_mismatch' USING ERRCODE = '22023';
    END IF;
  ELSIF v_challenge_oauth_nonce_hash IS NOT NULL OR p_oauth_nonce_hash IS NOT NULL THEN
    RAISE EXCEPTION 'privacy_oauth_nonce_unexpected' USING ERRCODE = '22023';
  END IF;

  IF NOT v_was_consumed AND EXISTS (
    SELECT 1 FROM privacy_retention.privacy_age_profiles AS profile
    WHERE profile.user_id = p_user_id
  ) THEN
    v_receipt := privacy_retention.g016_reattest_privacy_onboarding(
      p_challenge_id, p_user_id, p_source
    );
  ELSE
    v_receipt := privacy_retention.g014_confirm_privacy_onboarding_legacy(
      p_challenge_id,
      p_challenge_token,
      p_user_id,
      p_source,
      p_guardian_verification_id
    );
  END IF;



  RETURN v_receipt || pg_catalog.jsonb_build_object(
    'disposition', CASE WHEN v_was_consumed THEN 'idempotent_replay' ELSE 'fresh' END
  );
END;
$_$;


--
-- Name: confirm_privacy_retention_run(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_privacy_retention_run(p_run_id uuid, p_preview_hash text, p_confirmation_text text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_run privacy_retention.privacy_retention_runs%ROWTYPE;
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  IF p_run_id IS NULL OR p_preview_hash IS NULL
     OR p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     OR p_confirmation_text IS DISTINCT FROM '보존·분리 적용' THEN
    RAISE EXCEPTION 'privacy_retention_confirmation_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_run FROM privacy_retention.privacy_retention_runs
  WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND OR v_run.preview_hash IS DISTINCT FROM p_preview_hash THEN
    RAISE EXCEPTION 'privacy_retention_confirmation_binding_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    v_run.class_code, v_run.adapter_version, v_run.source_mapping_version
  );
  IF v_run.status IS DISTINCT FROM 'previewed' THEN
    IF v_run.idempotency_key IS NOT DISTINCT FROM p_idempotency_key THEN
      RETURN pg_catalog.jsonb_build_object(
        'operationId', v_run.id,
        'status', CASE
          WHEN v_run.status = 'completed' THEN 'applied'
          WHEN v_run.status = 'running' THEN 'partial'
          ELSE v_run.status
        END,
        'adapterVersion', v_run.adapter_version,
        'sourceMappingVersion', v_run.source_mapping_version
      );
    END IF;
    RAISE EXCEPTION 'privacy_retention_confirmation_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  IF v_run.preview_expires_at <= pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'privacy_retention_preview_expired' USING ERRCODE = '55000';
  END IF;

  UPDATE privacy_retention.privacy_retention_runs
  SET status = 'confirmed', idempotency_key = p_idempotency_key
  WHERE id = v_run.id
  RETURNING * INTO v_run;
  UPDATE privacy_retention.privacy_retention_runs
  SET audit_id = privacy_retention.g014_retention_append_audit(v_run, 'confirmed', 'RETENTION_CONFIRMED')
  WHERE id = v_run.id;

  RETURN pg_catalog.jsonb_build_object(
    'operationId', v_run.id,
    'status', 'confirmed',
    'adapterVersion', v_run.adapter_version,
    'sourceMappingVersion', v_run.source_mapping_version
  );
END;
$_$;


--
-- Name: consume_account_deletion_reauth_proof(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_account_deletion_reauth_proof(p_proof_id uuid, p_target_user_id uuid, p_request_id uuid, p_idempotency_key text) RETURNS TABLE(proof_id uuid, consumed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp(); v_now_epoch numeric := extract(epoch FROM v_now); v_claims jsonb := nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb; v_actor_user_id uuid := nullif(v_claims ->> 'sub', '')::uuid; v_session_id uuid; v_exp numeric; v_iat numeric; v_amr_timestamp numeric; v_proof account_deletion_private.reauth_proofs%ROWTYPE;
BEGIN
  IF v_claims ->> 'role' IS DISTINCT FROM 'authenticated' OR v_actor_user_id IS NULL OR p_proof_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL OR p_idempotency_key IS NULL OR char_length(btrim(p_idempotency_key)) NOT BETWEEN 1 AND 200 OR v_actor_user_id <> p_target_user_id OR v_claims IS NULL OR jsonb_typeof(v_claims) IS DISTINCT FROM 'object' OR jsonb_typeof(v_claims -> 'session_id') IS DISTINCT FROM 'string' OR (v_claims ->> 'session_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR jsonb_typeof(v_claims -> 'exp') IS DISTINCT FROM 'number' OR jsonb_typeof(v_claims -> 'iat') IS DISTINCT FROM 'number' OR (v_claims ->> 'exp') !~ '^[0-9]+$' OR (v_claims ->> 'iat') !~ '^[0-9]+$' OR jsonb_typeof(v_claims -> 'amr') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'account_deletion_reauth_proof_invalid_claims'; END IF;
  v_session_id := (v_claims ->> 'session_id')::uuid; v_exp := (v_claims ->> 'exp')::numeric; v_iat := (v_claims ->> 'iat')::numeric;
  SELECT max((entry ->> 'timestamp')::numeric) INTO v_amr_timestamp FROM jsonb_array_elements(v_claims -> 'amr') AS amr(entry) WHERE jsonb_typeof(entry) = 'object' AND entry ->> 'method' = 'password' AND jsonb_typeof(entry -> 'timestamp') = 'number' AND (entry ->> 'timestamp') ~ '^[0-9]+$';
  IF v_exp <= v_now_epoch OR v_iat > v_now_epoch OR v_iat > v_exp OR v_amr_timestamp IS NULL THEN RAISE EXCEPTION 'account_deletion_reauth_proof_invalid_claims'; END IF;
  IF v_amr_timestamp > v_now_epoch OR v_amr_timestamp < v_now_epoch - 300 THEN RAISE EXCEPTION 'account_deletion_reauth_proof_password_reauthentication_required'; END IF;
  SELECT proofs.* INTO v_proof FROM account_deletion_private.reauth_proofs AS proofs WHERE proofs.proof_id = p_proof_id FOR UPDATE;
  IF NOT FOUND OR v_proof.actor_user_id <> v_actor_user_id OR v_proof.target_user_id <> p_target_user_id OR v_proof.session_id <> v_session_id OR v_proof.password_reauthenticated_at <> pg_catalog.to_timestamp(v_amr_timestamp) OR v_proof.expires_at <= v_now OR v_proof.consumed_at IS NOT NULL THEN RAISE EXCEPTION 'account_deletion_reauth_proof_not_available'; END IF;
  UPDATE account_deletion_private.reauth_proofs AS proofs SET consumed_at=v_now,request_id=p_request_id,idempotency_key=btrim(p_idempotency_key) WHERE proofs.proof_id=v_proof.proof_id RETURNING proofs.proof_id,proofs.consumed_at INTO proof_id,consumed_at;
  RETURN NEXT;
END; $_$;


--
-- Name: consume_tzuyang_address_evidence_admin_approval(uuid, text, text, uuid, text, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_tzuyang_address_evidence_admin_approval(p_operation_id uuid, p_approval_envelope_sha256 text, p_nonce_sha256 text, p_actor_user_id uuid, p_review_manifest_sha256 text, p_signer_id text, p_action text, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone) RETURNS TABLE(consumed boolean, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_request_role text;
  v_now timestamptz := pg_catalog.date_trunc('milliseconds', pg_catalog.clock_timestamp());
  v_existing privacy_retention.tzuyang_address_evidence_admin_approval_receipts%ROWTYPE;
  v_actor_user_id uuid;
BEGIN
  v_request_role := COALESCE(
    NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    pg_catalog.current_setting('request.jwt.claim.role', true),
    ''
  );
  IF v_request_role <> 'service_role' AND SESSION_USER <> 'postgres' THEN
    RAISE EXCEPTION 'tzuyang_address_admin_approval_apply_identity_required'
      USING ERRCODE = '42501';
  END IF;

  IF p_operation_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_approval_envelope_sha256 IS NULL
     OR p_approval_envelope_sha256 !~ '^[0-9a-f]{64}$'
     OR p_nonce_sha256 IS NULL
     OR p_nonce_sha256 !~ '^[0-9a-f]{64}$'
     OR p_review_manifest_sha256 IS NULL
     OR p_review_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR p_signer_id IS NULL
     OR octet_length(p_signer_id) NOT BETWEEN 1 AND 256
     OR p_signer_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$'
     OR p_action IS DISTINCT FROM 'apply_tzuyang_address_evidence_ledger'
     OR p_issued_at IS NULL
     OR p_expires_at IS NULL
     OR p_issued_at <> pg_catalog.date_trunc('milliseconds', p_issued_at)
     OR p_expires_at <> pg_catalog.date_trunc('milliseconds', p_expires_at)
     OR p_issued_at > v_now
     OR p_expires_at <= p_issued_at
     OR p_expires_at <= v_now THEN
    RAISE EXCEPTION 'tzuyang_address_admin_approval_request_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT role_row.user_id
    INTO v_actor_user_id
    FROM public.user_roles AS role_row
    JOIN public.user_account_status AS status_row
      ON status_row.user_id = role_row.user_id
   WHERE role_row.user_id = p_actor_user_id
     AND role_row.role = 'admin'
     AND status_row.account_status = 'active'
   FOR UPDATE OF role_row, status_row;

  IF NOT FOUND OR v_actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION 'tzuyang_address_admin_approval_actor_forbidden'
      USING ERRCODE = '42501';
  END IF;

  -- Lock every unique replay binding in a deterministic order. The uniqueness
  -- constraints remain the final collision fence if an advisory hash collides.
  PERFORM pg_catalog.pg_advisory_xact_lock(lock_row.lock_key)
    FROM (
      SELECT DISTINCT pg_catalog.hashtextextended(binding.value, 0) AS lock_key
        FROM unnest(ARRAY[
          'tzuyang-address-approval-operation:' || p_operation_id::text,
          'tzuyang-address-approval-envelope:' || p_approval_envelope_sha256,
          'tzuyang-address-approval-nonce:' || p_nonce_sha256
        ]) AS binding(value)
       ORDER BY lock_key
    ) AS lock_row;

  SELECT receipt.*
    INTO v_existing
    FROM privacy_retention.tzuyang_address_evidence_admin_approval_receipts AS receipt
   WHERE receipt.operation_id = p_operation_id
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.approval_envelope_sha256 = p_approval_envelope_sha256
       AND v_existing.nonce_sha256 = p_nonce_sha256
       AND v_existing.actor_user_id = p_actor_user_id
       AND v_existing.review_manifest_sha256 = p_review_manifest_sha256
       AND v_existing.signer_id = p_signer_id
       AND v_existing.action = p_action
       AND v_existing.issued_at = p_issued_at
       AND v_existing.expires_at = p_expires_at THEN
      RETURN QUERY SELECT false, 'replayed'::text;
      RETURN;
    END IF;

    RAISE EXCEPTION 'tzuyang_address_admin_approval_binding_conflict'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
    FROM privacy_retention.tzuyang_address_evidence_admin_approval_receipts AS receipt
   WHERE receipt.approval_envelope_sha256 = p_approval_envelope_sha256
      OR receipt.nonce_sha256 = p_nonce_sha256
   FOR UPDATE;

  IF FOUND THEN
    RAISE EXCEPTION 'tzuyang_address_admin_approval_binding_conflict'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO privacy_retention.tzuyang_address_evidence_admin_approval_receipts (
    operation_id,
    approval_envelope_sha256,
    nonce_sha256,
    actor_user_id,
    review_manifest_sha256,
    signer_id,
    action,
    issued_at,
    expires_at,
    consumed_at
  ) VALUES (
    p_operation_id,
    p_approval_envelope_sha256,
    p_nonce_sha256,
    p_actor_user_id,
    p_review_manifest_sha256,
    p_signer_id,
    p_action,
    p_issued_at,
    p_expires_at,
    v_now
  );

  RETURN QUERY SELECT true, 'consumed'::text;
END;
$_$;


--
-- Name: create_admin_announcement_notification(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_admin_announcement_notification(p_title text, p_message text, p_data jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO public.notifications (user_id, type, title, message, data)
    SELECT
        p.user_id,
        'admin_announcement'::notification_type,
        p_title,
        p_message,
        p_data
    FROM public.profiles p;
END;
$$;


--
-- Name: FUNCTION create_admin_announcement_notification(p_title text, p_message text, p_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_admin_announcement_notification(p_title text, p_message text, p_data jsonb) IS '모든 사용자에게 관리자 공지 알림 생성';


--
-- Name: create_admin_transactional_notification(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_admin_transactional_notification(p_actor_user_id uuid, p_recipient_user_id uuid, p_type text, p_title text, p_message text, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor_user_id uuid;
  v_notification public.notifications%ROWTYPE;
  v_data_key_count integer;
BEGIN
  PERFORM privacy_retention.g014_require_service_role();

  IF p_actor_user_id IS NULL
     OR p_recipient_user_id IS NULL
     OR p_type IS NULL
     OR p_type NOT IN (
       'submission_approved',
       'submission_rejected',
       'review_approved',
       'review_rejected',
       'user_ranking'
     )
     OR p_title IS NULL
     OR p_title <> pg_catalog.btrim(p_title)
     OR pg_catalog.char_length(p_title) NOT BETWEEN 1 AND 120
     OR p_title ~ '[[:cntrl:]]'
     OR p_message IS NULL
     OR p_message <> pg_catalog.btrim(p_message)
     OR pg_catalog.char_length(p_message) NOT BETWEEN 1 AND 500
     OR p_message ~ '[[:cntrl:]]'
     OR p_data IS NULL
     OR pg_catalog.jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'admin_transactional_notification_request_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT role_row.user_id
    INTO v_actor_user_id
    FROM public.user_roles AS role_row
    JOIN public.user_account_status AS status_row
      ON status_row.user_id = role_row.user_id
   WHERE role_row.user_id = p_actor_user_id
     AND role_row.role = 'admin'
     AND status_row.account_status = 'active'
   FOR UPDATE OF role_row, status_row;

  IF NOT FOUND OR v_actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION 'admin_transactional_notification_actor_forbidden'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
    FROM privacy_retention.g041_auth_users AS recipient
   WHERE recipient.id = p_recipient_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'admin_transactional_notification_recipient_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::integer
    INTO v_data_key_count
    FROM pg_catalog.jsonb_object_keys(p_data) AS data_key(key);

  IF p_type <> 'user_ranking' AND p_data <> '{}'::jsonb THEN
    RAISE EXCEPTION 'admin_transactional_notification_data_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF p_type = 'user_ranking'
     AND (
       p_data <> '{}'::jsonb
       AND (
         v_data_key_count <> 2
         OR NOT (p_data ? 'ranking' AND p_data ? 'period')
         OR pg_catalog.jsonb_typeof(p_data -> 'ranking') <> 'number'
         OR (p_data ->> 'ranking') !~ '^[1-9][0-9]{0,6}$'
         OR (p_data ->> 'ranking')::integer > 1000000
         OR pg_catalog.jsonb_typeof(p_data -> 'period') <> 'string'
         OR p_data ->> 'period' <> pg_catalog.btrim(p_data ->> 'period')
         OR pg_catalog.char_length(p_data ->> 'period') NOT BETWEEN 1 AND 40
         OR p_data ->> 'period' ~ '[[:cntrl:]]'
       )
     ) THEN
    RAISE EXCEPTION 'admin_transactional_notification_data_invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public.assert_notification_content_safe(p_title, p_message, p_data);

  INSERT INTO public.notifications (
    user_id,
    type,
    title,
    message,
    data,
    classification,
    channel,
    consent_event_id,
    retention_class,
    campaign_operation_id,
    delivered_at,
    is_read
  )
  VALUES (
    p_recipient_user_id,
    p_type,
    p_title,
    p_message,
    p_data,
    'transactional',
    'in_app',
    NULL,
    'notifications_operational',
    NULL,
    NULL,
    false
  )
  RETURNING * INTO v_notification;

  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'status', 'created',
    'notificationId', v_notification.id::text,
    'actorUserId', p_actor_user_id::text,
    'recipientUserId', p_recipient_user_id::text,
    'type', p_type
  );
END;
$_$;


