    SET search_path TO ''
    AS $$
begin
  if privacy_retention.g041_current_claim_user_id() is null or notification_uuid is null then raise exception 'notification_owner_required'; end if;
  delete from public.notifications where id = notification_uuid and user_id = privacy_retention.g041_current_claim_user_id();
end; $$;


