--
-- Name: delete_pending_restaurant_submission(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_pending_restaurant_submission(p_submission_id uuid, p_user_id uuid, p_submission_type text) RETURNS TABLE(success boolean, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_status text;
begin
  if p_submission_type not in ('new', 'edit') then
    return query select false, '삭제할 제보 유형이 올바르지 않습니다.';
    return;
  end if;

  select restaurant_submissions.status
    into current_status
    from public.restaurant_submissions
   where restaurant_submissions.id = p_submission_id
     and restaurant_submissions.user_id = p_user_id
     and restaurant_submissions.submission_type = p_submission_type
   for update;

  if not found then
    return query select false, '삭제할 제보 내역을 찾지 못했습니다.';
    return;
  end if;

  if current_status <> 'pending' then
    return query select false, '이미 검토가 완료된 제보 내역은 삭제할 수 없습니다.';
    return;
  end if;

  delete from public.restaurant_submission_items
   where submission_id = p_submission_id;

  delete from public.restaurant_submissions
   where restaurant_submissions.id = p_submission_id
     and restaurant_submissions.user_id = p_user_id
     and restaurant_submissions.submission_type = p_submission_type
     and restaurant_submissions.status = 'pending';

  if not found then
    return query select false, '이미 검토가 완료된 제보 내역은 삭제할 수 없습니다.';
    return;
  end if;

  return query select true, '제보 내역을 삭제했습니다.';
end;
$$;


--
-- Name: delete_user_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_account(target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- 현재 사용자만 본인 계정 삭제 가능
    IF auth.uid() != target_user_id THEN
        RAISE EXCEPTION 'Unauthorized: You can only delete your own account';
    END IF;

    -- 1. 프로필 익명화
    UPDATE public.profiles
    SET nickname = '탈퇴한 사용자',
        profile_picture = NULL,
        email = 'deleted_' || target_user_id || '@deleted.local'
    WHERE user_id = target_user_id;

    -- 2. 통계 삭제
    DELETE FROM public.user_stats WHERE user_id = target_user_id;

    -- 3. 역할 삭제
    DELETE FROM public.user_roles WHERE user_id = target_user_id;
    
    RAISE NOTICE 'Account anonymized for user: %', target_user_id;
END;
$$;


--
-- Name: evaluate_marketing_permission_state(text, boolean, boolean, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_marketing_permission_state(p_channel text, p_ordinary_granted boolean, p_night_granted boolean, p_scheduled_at timestamp with time zone, p_timezone text DEFAULT 'Asia/Seoul'::text) RETURNS TABLE(allowed boolean, reason_code text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if p_channel not in ('email','sms','push') then raise exception 'marketing_channel_invalid'; end if;
  if coalesce(p_ordinary_granted,false) = false then return query select false,'ordinary_consent_missing'::text; return; end if;
  -- Email remains subject to ordinary consent and alone skips the separate night check.
  if public.is_marketing_night_window(p_scheduled_at,p_timezone) and p_channel <> 'email' and coalesce(p_night_granted,false) = false then
    return query select false,'night_consent_missing'::text; return;
  end if;
  return query select true,'allowed'::text;
end; $$;


--
-- Name: evaluate_notification_marketing_permission(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_notification_marketing_permission(p_user_id uuid, p_channel text, p_scheduled_at timestamp with time zone, p_timezone text DEFAULT 'Asia/Seoul'::text) RETURNS TABLE(allowed boolean, reason_code text, consent_event_id uuid, night_consent_event_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_timezone IS DISTINCT FROM 'Asia/Seoul' THEN
    RAISE EXCEPTION 'marketing_permission_input_invalid' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT evidence.allowed,
         evidence.reason_code,
         CASE WHEN evidence.allowed THEN evidence.ordinary_consent_event_id END,
         CASE WHEN evidence.allowed THEN evidence.night_consent_event_id END
  FROM privacy_retention.g014_marketing_permission_evidence(
    p_user_id, p_channel, p_scheduled_at, p_timezone
  ) AS evidence;
END;
$$;


--
-- Name: extract_youtube_video_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extract_youtube_video_id(raw_url text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select coalesce(
    (regexp_match(coalesce(raw_url, ''), '[?&]v=([A-Za-z0-9_-]{6,})'))[1],
    (regexp_match(coalesce(raw_url, ''), 'youtu\.be/([A-Za-z0-9_-]{6,})'))[1],
    (regexp_match(coalesce(raw_url, ''), 'youtube\.com/shorts/([A-Za-z0-9_-]{6,})'))[1],
    (regexp_match(coalesce(raw_url, ''), 'youtube\.com/embed/([A-Za-z0-9_-]{6,})'))[1],
    ''
  );
$$;


--
-- Name: fail_account_deletion(uuid, uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_account_deletion(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL OR p_reason_code IS NULL THEN
    RAISE EXCEPTION 'account_deletion_failure_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF p_reason_code NOT IN ('DB_OR_SESSION_CLEANUP_FAILED', 'SESSION_READBACK_REQUIRED') THEN
    RAISE EXCEPTION 'account_deletion_failure_reason_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  SELECT * INTO v_request
  FROM public.account_deletion_requests
  WHERE id = p_request_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_failure_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(
    p_actor_user_id, p_target_user_id
  );
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
  IF v_request.status NOT IN ('previewed', 'applying', 'partial') THEN
    RAISE EXCEPTION 'account_deletion_failure_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_external_phase_leases AS lease_row
    WHERE lease_row.request_id = v_request.id
      AND lease_row.target_user_id = p_target_user_id
      AND lease_row.status = 'active'
  ) OR EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_external_job_attempts AS attempt
    WHERE attempt.request_id = v_request.id
      AND attempt.state IN ('leased', 'egress_unknown', 'reconciliation_required')
  ) THEN
    RAISE EXCEPTION 'account_deletion_failure_external_lease_active' USING ERRCODE = '55000';
  END IF;

  UPDATE public.account_deletion_requests
  SET status = 'partial', reason_code = p_reason_code
  WHERE id = v_request.id
  RETURNING * INTO v_request;
  UPDATE privacy_retention.account_deletion_evidence_cleanup_leases
  SET status = 'released', released_at = pg_catalog.clock_timestamp()
  WHERE request_id = v_request.id
    AND target_user_id = p_target_user_id
    AND status = 'active';
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_evidence_cleanup_leases
    WHERE request_id = v_request.id
      AND target_user_id = p_target_user_id
      AND status = 'active'
  ) THEN
    RAISE EXCEPTION 'account_deletion_failure_lease_reconciliation_failed' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_append_audit(
    v_request, 'partial', p_reason_code
  );
END;
$$;


--
-- Name: fail_account_deletion_external_phase(uuid, uuid, uuid, text, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_account_deletion_external_phase(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_phase text, p_lease_token uuid, p_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_lease privacy_retention.account_deletion_external_phase_leases%ROWTYPE;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL OR p_phase IS NULL
     OR p_lease_token IS NULL OR p_reason_code IS NULL THEN
    RAISE EXCEPTION 'account_deletion_external_failure_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF (p_phase = 'storage' AND p_reason_code = 'STORAGE_CLEANUP_FAILED')
     OR (p_phase = 'auth' AND p_reason_code = 'AUTH_CLEANUP_FAILED') THEN
    NULL;
  ELSE
    RAISE EXCEPTION 'account_deletion_external_failure_phase_reason_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  SELECT * INTO v_request
  FROM public.account_deletion_requests
  WHERE id = p_request_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_external_failure_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(
    p_actor_user_id, p_target_user_id
  );
  IF v_request.status NOT IN ('applying', 'partial') THEN
    RAISE EXCEPTION 'account_deletion_external_failure_predecessor_invalid' USING ERRCODE = '55000';
  END IF;

  -- Failure reconciliation intentionally accepts an active lease that just
  -- expired, but only the exact request/target/phase/token can release it.
  SELECT * INTO v_lease
  FROM privacy_retention.account_deletion_external_phase_leases
  WHERE request_id = p_request_id
    AND target_user_id = p_target_user_id
    AND phase = p_phase
    AND lease_token = p_lease_token
    AND status = 'active'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_external_failure_lease_mismatch' USING ERRCODE = '55000';
  END IF;

  UPDATE public.account_deletion_requests
  SET status = 'partial',
      reason_code = p_reason_code
  WHERE id = v_request.id
  RETURNING * INTO v_request;
  UPDATE privacy_retention.account_deletion_external_phase_leases
  SET status = 'released',
      consumed_at = pg_catalog.clock_timestamp()
  WHERE request_id = p_request_id
    AND target_user_id = p_target_user_id
    AND phase = p_phase
    AND lease_token = p_lease_token
    AND status = 'active';
  IF NOT FOUND OR EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_external_phase_leases
    WHERE request_id = p_request_id
      AND target_user_id = p_target_user_id
      AND phase = p_phase
      AND lease_token = p_lease_token
      AND status = 'active'
  ) THEN
    RAISE EXCEPTION 'account_deletion_external_failure_lease_reconciliation_failed' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_append_audit(
    v_request, 'partial', p_reason_code
  );
END;
$$;


--
-- Name: fail_admin_trend_job_request(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_admin_trend_job_request(p_request_id uuid, p_claimed_by text, p_error_code text, p_result_summary jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request public.admin_trend_job_requests%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'trend_job_request_service_role_required';
  end if;

  if p_error_code is null or btrim(p_error_code) = '' then
    raise exception 'trend_job_request_error_code_required';
  end if;

  update public.admin_trend_job_requests
     set status = 'failed',
         error_code = p_error_code,
         result_summary = coalesce(p_result_summary, '{}'::jsonb),
         completed_at = timezone('utc'::text, now()),
         updated_at = timezone('utc'::text, now())
   where id = p_request_id
     and status = 'claimed'
     and claimed_by = p_claimed_by
  returning * into v_request;

  if not found then
    raise exception 'trend_job_request_finalize_failed';
  end if;

  return jsonb_build_object('ok', true, 'status', v_request.status, 'requestId', v_request.id, 'runId', v_request.run_id, 'errorCode', v_request.error_code, 'completedAt', v_request.completed_at);
end;
$$;


--
-- Name: fail_marketing_campaign_batch(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_marketing_campaign_batch(p_operation_id uuid, p_batch_id uuid, p_actor_user_id uuid, p_preview_hash text, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_operation public.marketing_campaign_operations%ROWTYPE;
  v_batch public.marketing_campaign_batches%ROWTYPE;
  v_requested integer := 0;
  v_suppressed integer := 0;
  v_failed integer := 0;
  v_pending integer := 0;
  v_audit_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_operation_id IS NULL
     OR p_batch_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_preview_hash IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_error_code IS NULL
     OR p_error_code NOT IN ('provider_unavailable', 'provider_request_failed', 'provider_response_invalid') THEN
    RAISE EXCEPTION 'marketing_provider_error_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_operation FROM public.marketing_campaign_operations AS operation
  WHERE operation.id = p_operation_id FOR UPDATE;
  SELECT * INTO v_batch FROM public.marketing_campaign_batches AS batch
  WHERE batch.id = p_batch_id AND batch.operation_id = p_operation_id FOR UPDATE;
  IF NOT FOUND
     OR v_operation.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_operation.preview_hash IS DISTINCT FROM p_preview_hash THEN
    RAISE EXCEPTION 'marketing_batch_not_found' USING ERRCODE = '42501';
  END IF;
  -- A claimed row has a durable unknown egress attempt. It must be reconciled,
  -- never converted to failed merely because a caller retried or timed out.
  IF v_batch.status IS DISTINCT FROM 'prepared' THEN
    RAISE EXCEPTION 'marketing_provider_outcome_unknown' USING ERRCODE = '55000';
  END IF;

  UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
  SET status = 'failed', finalized_at = v_now
  WHERE recipient.batch_id = p_batch_id AND recipient.operation_id = p_operation_id
    AND recipient.status = 'eligible';
  UPDATE public.marketing_campaign_recipients AS recipient
  SET status = 'failed', updated_at = v_now
  WHERE recipient.operation_id = p_operation_id AND recipient.status = 'eligible';
  UPDATE public.marketing_campaign_batches AS batch
  SET status = 'provider_failed', completed_at = v_now
  WHERE batch.id = p_batch_id;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE recipient.status = 'suppressed')::integer,
         count(*) FILTER (WHERE recipient.status = 'failed')::integer,
         count(*) FILTER (WHERE recipient.status IN ('pending', 'eligible'))::integer
  INTO v_requested, v_suppressed, v_failed, v_pending
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id;
  IF v_pending = 0 THEN
    v_audit_id := privacy_retention.g014_marketing_write_audit(
      p_operation_id, p_preview_hash, 'failed', 'MARKETING_CAMPAIGN_PROVIDER_FAILED',
      pg_catalog.upper(p_error_code), v_requested, 0, v_suppressed, v_failed
    );
    UPDATE public.marketing_campaign_operations AS operation
    SET status = 'failed', audit_id = v_audit_id, updated_at = v_now
    WHERE operation.id = p_operation_id;
  END IF;
  RETURN public.marketing_campaign_receipt(p_operation_id);
END;
$_$;


--
-- Name: fail_marketing_campaign_provider_attempt(uuid, uuid, uuid, text, uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_marketing_campaign_provider_attempt(p_operation_id uuid, p_batch_id uuid, p_actor_user_id uuid, p_preview_hash text, p_claim_token uuid, p_provider_attempt_id uuid, p_provider_receipt_id text, p_provider_receipt_hash text, p_provider_payload_digest text, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_operation public.marketing_campaign_operations%ROWTYPE;
  v_batch public.marketing_campaign_batches%ROWTYPE;
  v_attempt privacy_retention.marketing_campaign_provider_attempts%ROWTYPE;
  v_requested integer := 0;
  v_suppressed integer := 0;
  v_failed integer := 0;
  v_unresolved integer := 0;
  v_audit_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_operation_id IS NULL
     OR p_batch_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_preview_hash IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_claim_token IS NULL
     OR p_provider_attempt_id IS NULL
     OR p_provider_receipt_id IS NULL
     OR p_provider_receipt_id !~ '^[A-Za-z0-9._:-]{1,256}$'
     OR p_provider_receipt_hash IS NULL
     OR p_provider_receipt_hash !~ '^[0-9a-f]{64}$'
     OR p_provider_payload_digest IS NULL
     OR p_provider_payload_digest !~ '^[0-9a-f]{64}$'
     OR p_error_code IS NULL
     OR p_error_code NOT IN ('provider_rejected', 'provider_invalid_request') THEN
    RAISE EXCEPTION 'marketing_provider_result_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_operation FROM public.marketing_campaign_operations AS operation
  WHERE operation.id = p_operation_id FOR UPDATE;
  SELECT * INTO v_batch FROM public.marketing_campaign_batches AS batch
  WHERE batch.id = p_batch_id AND batch.operation_id = p_operation_id FOR UPDATE;
  SELECT * INTO v_attempt FROM privacy_retention.marketing_campaign_provider_attempts AS attempt
  WHERE attempt.id = p_provider_attempt_id FOR UPDATE;
  IF NOT FOUND
     OR v_operation.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_operation.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_batch.claim_token IS DISTINCT FROM p_claim_token
     OR v_attempt.operation_id IS DISTINCT FROM p_operation_id
     OR v_attempt.batch_id IS DISTINCT FROM p_batch_id
     OR v_attempt.claim_token IS DISTINCT FROM p_claim_token
     OR v_attempt.provider_identity IS DISTINCT FROM 'g014_https_provider_v1'
     OR v_attempt.payload_digest IS DISTINCT FROM p_provider_payload_digest THEN
    RAISE EXCEPTION 'marketing_claim_binding_mismatch' USING ERRCODE = '42501';
  END IF;
  IF v_attempt.status = 'failed'
     AND v_batch.status = 'completed' THEN
    IF v_attempt.provider_receipt_id IS NOT DISTINCT FROM p_provider_receipt_id
       AND v_attempt.provider_receipt_hash IS NOT DISTINCT FROM p_provider_receipt_hash
       AND v_attempt.payload_digest IS NOT DISTINCT FROM p_provider_payload_digest
       AND v_attempt.provider_error_code IS NOT DISTINCT FROM p_error_code THEN
      RETURN public.marketing_campaign_receipt(p_operation_id);
    END IF;
    RAISE EXCEPTION 'marketing_provider_result_binding_mismatch' USING ERRCODE = '42501';
  END IF;
  IF v_batch.status IS DISTINCT FROM 'claimed'
     OR v_attempt.status IS DISTINCT FROM 'unknown' THEN
    RAISE EXCEPTION 'marketing_provider_outcome_unknown' USING ERRCODE = '55000';
  END IF;

  UPDATE privacy_retention.marketing_campaign_provider_attempts AS attempt
  SET status = 'failed',
      provider_receipt_id = p_provider_receipt_id,
      provider_receipt_hash = p_provider_receipt_hash,
      provider_error_code = p_error_code,
      outcome_recorded_at = v_now
  WHERE attempt.id = p_provider_attempt_id;
  UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
  SET status = 'failed', finalized_at = v_now,
      provider_receipt_id = p_provider_receipt_id, provider_receipt_hash = p_provider_receipt_hash
  WHERE recipient.batch_id = p_batch_id
    AND recipient.operation_id = p_operation_id
    AND recipient.status = 'claimed'
    AND recipient.claim_token = p_claim_token;
  UPDATE public.marketing_campaign_recipients AS recipient
  SET status = 'failed', updated_at = v_now
  WHERE recipient.operation_id = p_operation_id
    AND recipient.status = 'eligible';
  UPDATE public.marketing_campaign_batches AS batch
  SET status = 'completed', completed_at = v_now
  WHERE batch.id = p_batch_id;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE recipient.status = 'suppressed')::integer,
         count(*) FILTER (WHERE recipient.status = 'failed')::integer
  INTO v_requested, v_suppressed, v_failed
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id;
  SELECT count(*)::integer INTO v_unresolved
  FROM (
    SELECT recipient.user_id FROM public.marketing_campaign_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id AND recipient.status IN ('pending', 'eligible')
    UNION
    SELECT recipient.user_id FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id AND recipient.status = 'claimed'
  ) AS unresolved;
  IF v_unresolved = 0 THEN
    v_audit_id := privacy_retention.g014_marketing_write_audit(
      p_operation_id, p_preview_hash, 'failed', 'MARKETING_PROVIDER_REJECTED',
      pg_catalog.upper(p_error_code), v_requested, 0, v_suppressed, v_failed
    );
    UPDATE public.marketing_campaign_operations AS operation
    SET status = 'failed', audit_id = v_audit_id, updated_at = v_now
    WHERE operation.id = p_operation_id;
  END IF;
  RETURN public.marketing_campaign_receipt(p_operation_id);
END;
$_$;


--
-- Name: fail_privacy_retention_storage_claims(uuid, text, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_privacy_retention_storage_claims(p_run_id uuid, p_preview_hash text, p_idempotency_key text, p_claim_tokens uuid[], p_failure_code text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_run privacy_retention.privacy_retention_runs%ROWTYPE;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_expected integer;
  v_affected integer;
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  IF cardinality(p_claim_tokens) IS NULL OR cardinality(p_claim_tokens) NOT BETWEEN 1 AND 100
     OR p_failure_code IS NULL OR p_failure_code !~ '^[a-z][a-z0-9_]{2,79}$'
     OR cardinality(ARRAY(SELECT DISTINCT unnest(p_claim_tokens))) IS DISTINCT FROM cardinality(p_claim_tokens) THEN
    RAISE EXCEPTION 'retention_storage_failure_arguments_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_run FROM privacy_retention.privacy_retention_runs
  WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND OR v_run.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_run.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_run.status NOT IN ('running', 'partial', 'held') THEN
    RAISE EXCEPTION 'retention_storage_failure_binding_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    v_run.class_code, v_run.adapter_version, v_run.source_mapping_version
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-retention-run:' || v_run.id::text, 0)
  );
  SELECT count(*) INTO v_expected
  FROM privacy_retention.g014_retention_storage_claims AS claim_row
  WHERE claim_row.run_id = v_run.id
    AND claim_row.claim_token = ANY (p_claim_tokens)
    AND claim_row.status = 'active'
    AND claim_row.claim_expires_at > v_now
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.g014_retention_provider_effects AS effect_row
      WHERE effect_row.claim_token = claim_row.claim_token
    );
  IF v_expected IS DISTINCT FROM cardinality(p_claim_tokens) THEN
    RAISE EXCEPTION 'retention_storage_failure_claim_set_invalid' USING ERRCODE = '55000';
  END IF;

  INSERT INTO privacy_retention.g014_retention_receipts (
    run_id, work_item_id, adapter_code, adapter_version, receipt_kind, source_ref_hash,
    claim_token, claim_hash, object_version_hash, failure_code
  )
  SELECT claim_row.run_id, claim_row.work_item_id, claim_row.adapter_code, claim_row.adapter_version,
         'storage_provider_failure', claim_row.object_locator_hash, claim_row.claim_token,
         claim_row.claim_hash, claim_row.object_version_hash, p_failure_code
  FROM privacy_retention.g014_retention_storage_claims AS claim_row
  WHERE claim_row.run_id = v_run.id AND claim_row.claim_token = ANY (p_claim_tokens)
    AND claim_row.status = 'active'
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.g014_retention_provider_effects AS effect_row
      WHERE effect_row.claim_token = claim_row.claim_token
    );

  UPDATE privacy_retention.g014_retention_storage_claims AS claim_row
  SET status = 'failed', resolved_at = v_now
  WHERE claim_row.run_id = v_run.id
    AND claim_row.claim_token = ANY (p_claim_tokens)
    AND claim_row.status = 'active'
    AND NOT EXISTS (
      SELECT 1
      FROM privacy_retention.g014_retention_provider_effects AS effect_row
      WHERE effect_row.claim_token = claim_row.claim_token
    );
  GET DIAGNOSTICS v_affected = ROW_COUNT;
  UPDATE privacy_retention.privacy_retention_work_items AS item
  SET status = 'failed', storage_claim_token = NULL, storage_claimed_at = NULL,
      last_error_code = p_failure_code
  FROM privacy_retention.g014_retention_storage_claims AS claim_row
  WHERE claim_row.run_id = v_run.id AND claim_row.claim_token = ANY (p_claim_tokens)
    AND claim_row.status = 'failed' AND item.id = claim_row.work_item_id
    AND item.status = 'claimed' AND item.storage_claim_token IS NOT DISTINCT FROM claim_row.claim_token;
  UPDATE privacy_retention.privacy_retention_run_items AS run_item
  SET status = 'failed', error_code = p_failure_code
  FROM privacy_retention.g014_retention_storage_claims AS claim_row
  WHERE claim_row.run_id = v_run.id AND claim_row.claim_token = ANY (p_claim_tokens)
    AND claim_row.status = 'failed' AND run_item.run_id = v_run.id
    AND run_item.work_item_id = claim_row.work_item_id AND run_item.status = 'storage_claimed';
  RETURN v_affected;
END;
$_$;


--
-- Name: finalize_account_deletion_auth(uuid, uuid, uuid, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_account_deletion_auth(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_lease_token uuid, p_auth_receipt_ref text) RETURNS TABLE(request_id uuid, status text, reason_code text, delete_count integer, anonymize_count integer, separate_count integer, retain_count integer, db_readback_passed boolean, storage_readback_passed boolean, session_readback_passed boolean, auth_readback_passed boolean, storage_receipt_refs jsonb, auth_receipt_ref text, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_proof privacy_retention.account_deletion_provider_receipt_proofs%ROWTYPE;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL OR p_lease_token IS NULL
     OR p_auth_receipt_ref IS NULL THEN
    RAISE EXCEPTION 'account_deletion_auth_finalize_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     OR p_source_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_auth_receipt_ref !~ '^[A-Za-z0-9._:-]{8,256}$' THEN
    RAISE EXCEPTION 'account_deletion_auth_finalize_arguments_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_request FROM public.account_deletion_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND
     OR v_request.id IS DISTINCT FROM p_request_id
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_auth_finalize_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_external_lease(
    p_request_id, p_target_user_id, 'auth', p_lease_token
  );
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(p_actor_user_id, p_target_user_id);
  IF v_request.status NOT IN ('applying', 'partial')
     OR NOT v_request.db_readback_passed
     OR NOT v_request.session_readback_passed
     OR NOT v_request.storage_readback_passed
     OR v_request.auth_readback_passed
     OR v_request.source_manifest_hash IS DISTINCT FROM privacy_retention.g014_account_deletion_validate_manifest(v_request.policy_version) THEN
    RAISE EXCEPTION 'account_deletion_auth_finalize_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  IF pg_catalog.to_regclass('privacy_retention.g041_auth_identities') IS NULL
     OR pg_catalog.to_regclass('privacy_retention.g041_auth_refresh_tokens') IS NULL
     OR pg_catalog.to_regclass('privacy_retention.g041_auth_sessions') IS NULL
     OR pg_catalog.to_regclass('privacy_retention.g041_auth_users') IS NULL THEN
    RAISE EXCEPTION 'account_deletion_auth_catalog_contract_missing' USING ERRCODE = '55000';
  END IF;
  SELECT * INTO v_proof
  FROM privacy_retention.account_deletion_provider_receipt_proofs AS proof
  WHERE proof.phase = 'auth'
    AND proof.request_id = v_request.id
    AND proof.actor_user_id = p_actor_user_id
    AND proof.target_user_id = p_target_user_id
    AND proof.lease_token = p_lease_token
    AND proof.manifest_hash = p_source_manifest_hash
    AND proof.idempotency_key IS NOT DISTINCT FROM v_request.idempotency_key
    AND proof.preview_hash IS NOT DISTINCT FROM v_request.preview_hash
    AND proof.provider_kind = 'admin_auth_delete'
    AND proof.provider_receipt_ref = p_auth_receipt_ref
    AND proof.predecessor_receipts_hash IS NOT DISTINCT FROM v_request.storage_receipts_hash
    AND proof.canonical_payload_hash IS NOT DISTINCT FROM privacy_retention.g014_account_deletion_receipt_payload_hash(
      'auth', v_request.id, p_actor_user_id, p_target_user_id,
      p_source_manifest_hash, p_idempotency_key, p_preview_hash, p_lease_token,
      'admin_auth_delete', p_auth_receipt_ref, proof.provider_receipt_hash,
      NULL, NULL, v_request.storage_receipts_hash
    )
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_auth_provider_proof_unavailable' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (SELECT 1 FROM privacy_retention.g041_auth_users WHERE id = v_request.target_user_id)
     OR EXISTS (SELECT 1 FROM privacy_retention.g041_auth_sessions WHERE user_id = v_request.target_user_id)
     OR EXISTS (SELECT 1 FROM privacy_retention.g041_auth_identities WHERE user_id = v_request.target_user_id)
     OR EXISTS (SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens WHERE user_id = v_request.target_user_id) THEN
    RAISE EXCEPTION 'account_deletion_auth_authoritative_absence_failed' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_external_lease(p_request_id, p_target_user_id, 'auth', p_lease_token);
  UPDATE public.account_deletion_request_items
  SET status = 'applied', reason_code = 'AUTH_READBACK_PASSED'
  WHERE request_id = v_request.id AND data_class_code = 'auth_identity';
  PERFORM privacy_retention.g014_account_deletion_assert_final_items(v_request.id, v_request.target_user_id);
  UPDATE public.account_deletion_requests
  SET status = 'applied',
      reason_code = 'APPLIED',
      auth_readback_passed = true,
      auth_receipt_ref = p_auth_receipt_ref,
      applied_at = pg_catalog.clock_timestamp()
  WHERE id = v_request.id
  RETURNING * INTO v_request;
  UPDATE privacy_retention.account_deletion_admin_reservations
  SET status = 'completed', reconciled_at = pg_catalog.clock_timestamp()
  WHERE request_id = v_request.id AND status = 'active';
  UPDATE privacy_retention.account_deletion_external_phase_leases
  SET status = 'consumed', consumed_at = pg_catalog.clock_timestamp()
  WHERE request_id = v_request.id
    AND phase = 'auth'
    AND lease_token = p_lease_token
    AND status = 'active'
    AND lease_expires_at > pg_catalog.clock_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_auth_lease_consumption_failed' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_append_audit(v_request, 'applied', 'APPLIED');
  RETURN QUERY SELECT
    v_request.id,
    v_request.status,
    v_request.reason_code,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'delete') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'anonymize') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'separate') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'retain') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    v_request.db_readback_passed,
    v_request.storage_readback_passed,
    v_request.session_readback_passed,
    v_request.auth_readback_passed,
    privacy_retention.g014_account_deletion_storage_receipt_refs(v_request.id),
    v_request.auth_receipt_ref,
    v_request.source_manifest_hash;
END;
$_$;


--
-- Name: finalize_account_deletion_storage(uuid, uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_account_deletion_storage(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_lease_token uuid, p_receipts_json jsonb) RETURNS TABLE(request_id uuid, status text, reason_code text, db_readback_passed boolean, storage_readback_passed boolean, session_readback_passed boolean, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_receipts_hash text;
  v_receipt_count integer;
  v_object_count integer;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_request_id IS NULL
     OR p_preview_hash IS NULL OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL OR p_lease_token IS NULL
     OR p_receipts_json IS NULL THEN
    RAISE EXCEPTION 'account_deletion_storage_finalize_arguments_required' USING ERRCODE = '22004';
  END IF;
  IF p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     OR p_source_manifest_hash !~ '^[0-9a-f]{64}$'
     OR pg_catalog.jsonb_typeof(p_receipts_json) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'account_deletion_storage_finalize_arguments_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_request FROM public.account_deletion_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND
     OR v_request.id IS DISTINCT FROM p_request_id
     OR v_request.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_request.target_user_id IS DISTINCT FROM p_target_user_id
     OR v_request.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_request.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_request.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash THEN
    RAISE EXCEPTION 'account_deletion_storage_finalize_binding_mismatch' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_assert_external_lease(
    p_request_id, p_target_user_id, 'storage', p_lease_token
  );
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(p_actor_user_id, p_target_user_id);
  IF v_request.status NOT IN ('applying', 'partial')
     OR NOT v_request.db_readback_passed
     OR NOT v_request.session_readback_passed
     OR v_request.storage_readback_passed
     OR v_request.source_manifest_hash IS DISTINCT FROM privacy_retention.g014_account_deletion_validate_manifest(v_request.policy_version) THEN
    RAISE EXCEPTION 'account_deletion_storage_finalize_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
SELECT count(*) INTO v_object_count
FROM privacy_retention.account_deletion_storage_objects
WHERE request_id = v_request.id;
SELECT count(*) INTO v_receipt_count
FROM pg_catalog.jsonb_array_elements(p_receipts_json);
IF EXISTS (
  SELECT 1
  FROM pg_catalog.jsonb_array_elements(p_receipts_json) AS entry(value)
  WHERE pg_catalog.jsonb_typeof(entry.value) IS DISTINCT FROM 'object'
     OR NOT (entry.value ?& ARRAY[
       'objectLocatorHash', 'objectVersionHash', 'providerReceiptRef', 'providerReceiptHash'
     ])
     OR CASE
       WHEN pg_catalog.jsonb_typeof(entry.value) = 'object' THEN EXISTS (
         SELECT 1
         FROM pg_catalog.jsonb_object_keys(entry.value) AS key_row(key_name)
         WHERE key_row.key_name NOT IN (
           'objectLocatorHash', 'objectVersionHash', 'providerReceiptRef', 'providerReceiptHash'
         )
       )
       ELSE false
     END
) THEN
  RAISE EXCEPTION 'account_deletion_storage_receipt_shape_invalid' USING ERRCODE = '22023';
END IF;
IF v_receipt_count IS DISTINCT FROM v_object_count
   OR EXISTS (
     SELECT 1
     FROM privacy_retention.account_deletion_storage_objects AS expected
     FULL JOIN pg_catalog.jsonb_to_recordset(p_receipts_json) AS receipt(
       "objectLocatorHash" text, "objectVersionHash" text,
       "providerReceiptRef" text, "providerReceiptHash" text
     ) ON expected.object_locator_hash = receipt."objectLocatorHash"
     WHERE expected.request_id = v_request.id
       AND (
         expected.object_locator_hash IS NULL OR receipt."objectLocatorHash" IS NULL
         OR expected.object_version_hash IS DISTINCT FROM receipt."objectVersionHash"
         OR receipt."providerReceiptRef" IS NULL OR receipt."providerReceiptHash" IS NULL
         OR receipt."providerReceiptRef" !~ '^[A-Za-z0-9._:-]{8,256}$'
         OR receipt."providerReceiptHash" !~ '^[0-9a-f]{64}$'
       )
   )
   OR EXISTS (
     SELECT 1
     FROM pg_catalog.jsonb_to_recordset(p_receipts_json) AS receipt(
       "objectLocatorHash" text, "objectVersionHash" text,
       "providerReceiptRef" text, "providerReceiptHash" text
     )
     GROUP BY receipt."objectLocatorHash"
     HAVING count(*) <> 1
   ) THEN
  RAISE EXCEPTION 'account_deletion_storage_receipt_set_invalid' USING ERRCODE = '55000';
END IF;
IF EXISTS (
  SELECT 1
  FROM privacy_retention.account_deletion_storage_objects AS expected
  JOIN pg_catalog.jsonb_to_recordset(p_receipts_json) AS receipt(
    "objectLocatorHash" text, "objectVersionHash" text,
    "providerReceiptRef" text, "providerReceiptHash" text
  ) ON expected.object_locator_hash = receipt."objectLocatorHash"
  LEFT JOIN privacy_retention.account_deletion_provider_receipt_proofs AS proof
    ON proof.phase = 'storage'
   AND proof.request_id = v_request.id
   AND proof.actor_user_id = p_actor_user_id
   AND proof.target_user_id = p_target_user_id
   AND proof.lease_token = p_lease_token
   AND proof.manifest_hash = p_source_manifest_hash
   AND proof.idempotency_key IS NOT DISTINCT FROM v_request.idempotency_key
   AND proof.preview_hash IS NOT DISTINCT FROM v_request.preview_hash
   AND proof.provider_kind = 'storage_object_delete'
   AND proof.provider_receipt_ref = receipt."providerReceiptRef"
   AND proof.provider_receipt_hash = receipt."providerReceiptHash"
   AND proof.object_locator_hash = expected.object_locator_hash
   AND proof.object_version_hash = expected.object_version_hash
   AND proof.canonical_payload_hash IS NOT DISTINCT FROM privacy_retention.g014_account_deletion_receipt_payload_hash(
     'storage', v_request.id, p_actor_user_id, p_target_user_id,
     p_source_manifest_hash, p_idempotency_key, p_preview_hash, p_lease_token,
     'storage_object_delete', receipt."providerReceiptRef", receipt."providerReceiptHash",
     expected.object_locator_hash, expected.object_version_hash, NULL
   )
  WHERE expected.request_id = v_request.id
    AND proof.id IS NULL
) THEN
  RAISE EXCEPTION 'account_deletion_storage_provider_proof_unavailable' USING ERRCODE = '55000';
END IF;
IF EXISTS (
  SELECT 1 FROM storage.objects
  WHERE owner_id::text = v_request.target_user_id::text
) THEN
  RAISE EXCEPTION 'account_deletion_storage_authoritative_absence_failed' USING ERRCODE = '55000';
END IF;
PERFORM privacy_retention.g014_account_deletion_assert_external_lease(
  p_request_id, p_target_user_id, 'storage', p_lease_token
);
INSERT INTO privacy_retention.account_deletion_storage_receipts (
  request_id, object_locator_hash, object_version_hash,
  provider_receipt_ref, provider_receipt_hash, proof_hash
)
SELECT
  v_request.id,
  receipt."objectLocatorHash",
  receipt."objectVersionHash",
  receipt."providerReceiptRef",
  receipt."providerReceiptHash",
  proof.proof_hash
FROM pg_catalog.jsonb_to_recordset(p_receipts_json) AS receipt(
  "objectLocatorHash" text, "objectVersionHash" text,
  "providerReceiptRef" text, "providerReceiptHash" text
)
JOIN privacy_retention.account_deletion_storage_objects AS expected
  ON expected.request_id = v_request.id
 AND expected.object_locator_hash = receipt."objectLocatorHash"
JOIN privacy_retention.account_deletion_provider_receipt_proofs AS proof
  ON proof.phase = 'storage'
 AND proof.request_id = v_request.id
 AND proof.actor_user_id = p_actor_user_id
 AND proof.target_user_id = p_target_user_id
 AND proof.lease_token = p_lease_token
 AND proof.manifest_hash = p_source_manifest_hash
 AND proof.idempotency_key IS NOT DISTINCT FROM v_request.idempotency_key
 AND proof.preview_hash IS NOT DISTINCT FROM v_request.preview_hash
 AND proof.provider_kind = 'storage_object_delete'
 AND proof.provider_receipt_ref = receipt."providerReceiptRef"
 AND proof.provider_receipt_hash = receipt."providerReceiptHash"
 AND proof.object_locator_hash = expected.object_locator_hash
 AND proof.object_version_hash = expected.object_version_hash
 AND proof.canonical_payload_hash IS NOT DISTINCT FROM privacy_retention.g014_account_deletion_receipt_payload_hash(
   'storage', v_request.id, p_actor_user_id, p_target_user_id,
   p_source_manifest_hash, p_idempotency_key, p_preview_hash, p_lease_token,
   'storage_object_delete', receipt."providerReceiptRef", receipt."providerReceiptHash",
   expected.object_locator_hash, expected.object_version_hash, NULL
 );
SELECT pg_catalog.encode(
  extensions.digest(
    COALESCE(
      (
        SELECT pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'objectLocatorHash', receipt."objectLocatorHash",
            'objectVersionHash', receipt."objectVersionHash",
            'providerReceiptRef', receipt."providerReceiptRef",
            'providerReceiptHash', receipt."providerReceiptHash"
          )
          ORDER BY receipt."objectLocatorHash"
        )::text
        FROM pg_catalog.jsonb_to_recordset(p_receipts_json) AS receipt(
          "objectLocatorHash" text, "objectVersionHash" text,
          "providerReceiptRef" text, "providerReceiptHash" text
        )
      ),
      '[]'
    ),
    'sha256'
  ),
  'hex'
) INTO v_receipts_hash;
  UPDATE public.account_deletion_request_items
  SET status = 'applied', reason_code = 'STORAGE_READBACK_PASSED'
  WHERE request_id = v_request.id AND data_class_code = 'storage_objects';
  UPDATE public.account_deletion_requests
  SET status = 'applying',
      reason_code = 'STORAGE_READBACK_PASSED',
      storage_readback_passed = true,
      storage_receipts_hash = v_receipts_hash
  WHERE id = v_request.id
  RETURNING * INTO v_request;
  UPDATE privacy_retention.account_deletion_external_phase_leases
  SET status = 'consumed', consumed_at = pg_catalog.clock_timestamp()
  WHERE request_id = v_request.id
    AND phase = 'storage'
    AND lease_token = p_lease_token
    AND status = 'active'
    AND lease_expires_at > pg_catalog.clock_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_storage_lease_consumption_failed' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_append_audit(v_request, 'readback_passed', 'STORAGE_READBACK_PASSED');
  RETURN QUERY SELECT
    v_request.id, v_request.status, v_request.reason_code,
    v_request.db_readback_passed, v_request.storage_readback_passed,
    v_request.session_readback_passed, v_request.source_manifest_hash;
END;
$_$;


--
-- Name: finalize_marketing_campaign_batch(uuid, uuid, uuid, text, uuid, uuid, text, text, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_marketing_campaign_batch(p_operation_id uuid, p_batch_id uuid, p_actor_user_id uuid, p_preview_hash text, p_claim_token uuid, p_provider_attempt_id uuid, p_provider_receipt_id text, p_provider_receipt_hash text, p_provider_payload_digest text, p_accepted_user_ids uuid[], p_timezone text DEFAULT 'Asia/Seoul'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_operation public.marketing_campaign_operations%ROWTYPE;
  v_batch public.marketing_campaign_batches%ROWTYPE;
  v_attempt privacy_retention.marketing_campaign_provider_attempts%ROWTYPE;
  v_recipient privacy_retention.marketing_campaign_batch_recipients%ROWTYPE;
  v_permission record;
  v_accepted_user_ids uuid[];
  v_accepted_recipient_digest text;
  v_requested integer := 0;
  v_sent integer := 0;
  v_suppressed integer := 0;
  v_failed integer := 0;
  v_unresolved integer := 0;
  v_status text;
  v_audit_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_operation_id IS NULL
     OR p_batch_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_preview_hash IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_claim_token IS NULL
     OR p_provider_attempt_id IS NULL
     OR p_provider_receipt_id IS NULL
     OR p_provider_receipt_id !~ '^[A-Za-z0-9._:-]{1,256}$'
     OR p_provider_receipt_hash IS NULL
     OR p_provider_receipt_hash !~ '^[0-9a-f]{64}$'
     OR p_provider_payload_digest IS NULL
     OR p_provider_payload_digest !~ '^[0-9a-f]{64}$'
     OR p_accepted_user_ids IS NULL
     OR pg_catalog.array_length(p_accepted_user_ids, 1) > 100
     OR pg_catalog.array_position(p_accepted_user_ids, NULL) IS NOT NULL
     OR (SELECT count(DISTINCT accepted.user_id) FROM pg_catalog.unnest(p_accepted_user_ids) AS accepted(user_id))
        IS DISTINCT FROM COALESCE(pg_catalog.array_length(p_accepted_user_ids, 1), 0)
     OR p_timezone IS DISTINCT FROM 'Asia/Seoul' THEN
    RAISE EXCEPTION 'marketing_provider_result_invalid' USING ERRCODE = '22023';
  END IF;
  v_accepted_user_ids := privacy_retention.g014_marketing_canonical_recipient_ids(p_accepted_user_ids);
  v_accepted_recipient_digest := privacy_retention.g014_marketing_accepted_recipient_digest(v_accepted_user_ids);

  SELECT * INTO v_operation FROM public.marketing_campaign_operations AS operation
  WHERE operation.id = p_operation_id FOR UPDATE;
  SELECT * INTO v_batch FROM public.marketing_campaign_batches AS batch
  WHERE batch.id = p_batch_id AND batch.operation_id = p_operation_id FOR UPDATE;
  SELECT * INTO v_attempt FROM privacy_retention.marketing_campaign_provider_attempts AS attempt
  WHERE attempt.id = p_provider_attempt_id FOR UPDATE;
  IF NOT FOUND
     OR v_operation.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_operation.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_batch.claim_token IS DISTINCT FROM p_claim_token
     OR v_attempt.operation_id IS DISTINCT FROM p_operation_id
     OR v_attempt.batch_id IS DISTINCT FROM p_batch_id
     OR v_attempt.claim_token IS DISTINCT FROM p_claim_token
     OR v_attempt.provider_identity IS DISTINCT FROM 'g014_https_provider_v1'
     OR v_attempt.payload_digest IS DISTINCT FROM p_provider_payload_digest THEN
    RAISE EXCEPTION 'marketing_claim_binding_mismatch' USING ERRCODE = '42501';
  END IF;
  IF v_attempt.status = 'accepted'
     AND v_batch.status = 'completed' THEN
    IF v_attempt.provider_receipt_id IS NOT DISTINCT FROM p_provider_receipt_id
       AND v_attempt.provider_receipt_hash IS NOT DISTINCT FROM p_provider_receipt_hash
       AND v_attempt.payload_digest IS NOT DISTINCT FROM p_provider_payload_digest
       AND v_attempt.accepted_recipient_ids IS NOT DISTINCT FROM v_accepted_user_ids
       AND v_attempt.accepted_recipient_digest IS NOT DISTINCT FROM v_accepted_recipient_digest THEN
      RETURN public.marketing_campaign_receipt(p_operation_id);
    END IF;
    RAISE EXCEPTION 'marketing_provider_result_binding_mismatch' USING ERRCODE = '42501';
  END IF;
  IF v_batch.status IS DISTINCT FROM 'claimed'
     OR v_attempt.status IS DISTINCT FROM 'unknown' THEN
    RAISE EXCEPTION 'marketing_provider_outcome_unknown' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM pg_catalog.unnest(v_accepted_user_ids) AS accepted(user_id)
    WHERE NOT EXISTS (
      SELECT 1
      FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
      WHERE recipient.batch_id = p_batch_id
        AND recipient.operation_id = p_operation_id
        AND recipient.user_id = accepted.user_id
        AND recipient.status = 'claimed'
        AND recipient.claim_token = p_claim_token
    )
  ) THEN
    RAISE EXCEPTION 'marketing_provider_result_invalid' USING ERRCODE = '22023';
  END IF;
  -- Provider acceptance is durable external transport truth before any mutable
  -- in-app eligibility cleanup is evaluated.
  UPDATE privacy_retention.marketing_campaign_provider_attempts AS attempt
  SET status = 'accepted',
      provider_receipt_id = p_provider_receipt_id,
      provider_receipt_hash = p_provider_receipt_hash,
      accepted_recipient_ids = v_accepted_user_ids,
      accepted_recipient_digest = v_accepted_recipient_digest,
      outcome_recorded_at = v_now
  WHERE attempt.id = p_provider_attempt_id;

  -- Revalidate only the in-app artifact immediately before creation. A later
  -- withdrawal suppresses that artifact without rewriting provider acceptance.
  FOR v_recipient IN
    SELECT *
    FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
    WHERE recipient.batch_id = p_batch_id
      AND recipient.operation_id = p_operation_id
      AND recipient.status = 'claimed'
      AND recipient.claim_token = p_claim_token
    ORDER BY recipient.user_id
    FOR UPDATE
  LOOP
    SELECT * INTO v_permission
    FROM privacy_retention.g014_marketing_permission_evidence(
      v_recipient.user_id, v_operation.channel, v_now, p_timezone
    );
    IF v_permission.allowed IS TRUE
       AND v_recipient.user_id = ANY (v_accepted_user_ids) THEN
      INSERT INTO public.notifications (
        user_id, type, title, message, data, classification, channel,
        consent_event_id, retention_class, campaign_operation_id, delivered_at
      ) VALUES (
        v_recipient.user_id, 'marketing_campaign', v_operation.title, v_operation.message,
        v_operation.data, 'marketing', v_operation.channel, v_permission.ordinary_consent_event_id,
        'notifications_operational', p_operation_id, v_now
      ) ON CONFLICT (campaign_operation_id, user_id)
        WHERE campaign_operation_id IS NOT NULL DO NOTHING;
      UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
      SET status = 'sent',
          provider_accepted_at = v_now,
          notification_eligibility_outcome = 'notification_created',
          ordinary_consent_event_id = v_permission.ordinary_consent_event_id,
          ordinary_subject_kind = v_permission.subject_kind,
          ordinary_guardian_verification_id = v_permission.guardian_verification_id,
          ordinary_purpose = v_operation.channel || '_marketing',
          ordinary_channel = v_operation.channel,
          ordinary_decision = 'granted',
          ordinary_policy_version_id = v_permission.policy_version_id,
          ordinary_notice_sha256 = v_permission.policy_content_sha256,
          night_consent_event_id = v_permission.night_consent_event_id,
          night_subject_kind = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.subject_kind END,
          night_guardian_verification_id = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.guardian_verification_id END,
          night_purpose = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE 'night_marketing' END,
          night_channel = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_operation.channel END,
          night_decision = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE 'granted' END,
          night_policy_version_id = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.policy_version_id END,
          night_notice_sha256 = CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.policy_content_sha256 END,
          finalized_at = v_now,
          provider_receipt_id = p_provider_receipt_id,
          provider_receipt_hash = p_provider_receipt_hash
      WHERE recipient.batch_id = p_batch_id AND recipient.user_id = v_recipient.user_id;
      INSERT INTO privacy_retention.marketing_campaign_consent_evidence_keys (
        batch_id, operation_id, user_id, evidence_kind, consent_event_id, subject_kind,
        guardian_verification_id, purpose, channel, decision, policy_version_id, notice_sha256
      ) VALUES (
        p_batch_id, p_operation_id, v_recipient.user_id, 'finalize_ordinary',
        v_permission.ordinary_consent_event_id, v_permission.subject_kind,
        v_permission.guardian_verification_id, v_operation.channel || '_marketing',
        v_operation.channel, 'granted', v_permission.policy_version_id, v_permission.policy_content_sha256
      );
      IF v_permission.night_consent_event_id IS NOT NULL THEN
        INSERT INTO privacy_retention.marketing_campaign_consent_evidence_keys (
          batch_id, operation_id, user_id, evidence_kind, consent_event_id, subject_kind,
          guardian_verification_id, purpose, channel, decision, policy_version_id, notice_sha256
        ) VALUES (
          p_batch_id, p_operation_id, v_recipient.user_id, 'finalize_night',
          v_permission.night_consent_event_id, v_permission.subject_kind,
          v_permission.guardian_verification_id, 'night_marketing',
          v_operation.channel, 'granted', v_permission.policy_version_id, v_permission.policy_content_sha256
        );
      END IF;
      UPDATE public.marketing_campaign_recipients AS recipient
      SET status = 'sent', consent_event_id = v_permission.ordinary_consent_event_id,
          night_consent_event_id = v_permission.night_consent_event_id, updated_at = v_now
      WHERE recipient.operation_id = p_operation_id AND recipient.user_id = v_recipient.user_id;
    ELSIF v_recipient.user_id = ANY (v_accepted_user_ids) THEN
      DELETE FROM public.notifications AS notification
      WHERE notification.campaign_operation_id = p_operation_id
        AND notification.user_id = v_recipient.user_id
        AND notification.classification = 'marketing';
      UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
      SET status = 'suppressed',
          provider_accepted_at = v_now,
          notification_eligibility_outcome = 'notification_suppressed_after_acceptance',
          finalized_at = v_now,
          provider_receipt_id = p_provider_receipt_id,
          provider_receipt_hash = p_provider_receipt_hash
      WHERE recipient.batch_id = p_batch_id AND recipient.user_id = v_recipient.user_id;
      UPDATE public.marketing_campaign_recipients AS recipient
      SET status = 'sent', updated_at = v_now
      WHERE recipient.operation_id = p_operation_id AND recipient.user_id = v_recipient.user_id;
    ELSIF v_permission.allowed IS TRUE THEN
      UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
      SET status = 'failed', finalized_at = v_now,
          provider_receipt_id = p_provider_receipt_id, provider_receipt_hash = p_provider_receipt_hash
      WHERE recipient.batch_id = p_batch_id AND recipient.user_id = v_recipient.user_id;
      UPDATE public.marketing_campaign_recipients AS recipient
      SET status = 'failed', updated_at = v_now
      WHERE recipient.operation_id = p_operation_id AND recipient.user_id = v_recipient.user_id;
    ELSE
      UPDATE privacy_retention.marketing_campaign_batch_recipients AS recipient
      SET status = 'suppressed', finalized_at = v_now,
          provider_receipt_id = p_provider_receipt_id, provider_receipt_hash = p_provider_receipt_hash
      WHERE recipient.batch_id = p_batch_id AND recipient.user_id = v_recipient.user_id;
      UPDATE public.marketing_campaign_recipients AS recipient
      SET status = 'suppressed', consent_event_id = NULL, night_consent_event_id = NULL, updated_at = v_now
      WHERE recipient.operation_id = p_operation_id AND recipient.user_id = v_recipient.user_id;
    END IF;
  END LOOP;

  UPDATE public.marketing_campaign_batches AS batch
  SET status = 'completed', completed_at = v_now
  WHERE batch.id = p_batch_id;

  SELECT count(*)::integer,
         count(*) FILTER (
           WHERE recipient.status = 'suppressed'
             AND NOT EXISTS (
               SELECT 1
               FROM privacy_retention.marketing_campaign_batch_recipients AS batch_recipient
               WHERE batch_recipient.operation_id = p_operation_id
                 AND batch_recipient.user_id = recipient.user_id
                 AND batch_recipient.provider_accepted_at IS NOT NULL
             )
         )::integer,
         count(*) FILTER (WHERE recipient.status = 'failed')::integer
  INTO v_requested, v_suppressed, v_failed
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id;
  SELECT count(*)::integer
    INTO v_sent
    FROM (
      SELECT DISTINCT accepted.user_id
      FROM privacy_retention.marketing_campaign_provider_attempts AS attempt
      CROSS JOIN LATERAL pg_catalog.unnest(
        COALESCE(attempt.accepted_recipient_ids, ARRAY[]::uuid[])
      ) AS accepted(user_id)
      WHERE attempt.operation_id = p_operation_id
        AND attempt.status = 'accepted'
    ) AS accepted;
  SELECT count(*)::integer INTO v_unresolved
  FROM (
    SELECT recipient.user_id FROM public.marketing_campaign_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id AND recipient.status IN ('pending', 'eligible')
    UNION
    SELECT recipient.user_id FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id AND recipient.status = 'claimed'
  ) AS unresolved;

  IF v_unresolved = 0 THEN
    v_status := CASE WHEN v_failed = 0 THEN 'applied' ELSE 'partial' END;
    v_audit_id := privacy_retention.g014_marketing_write_audit(
      p_operation_id, p_preview_hash, v_status,
      CASE WHEN v_status = 'applied' THEN 'MARKETING_CAMPAIGN_APPLIED' ELSE 'MARKETING_CAMPAIGN_PARTIAL' END,
      NULL, v_requested, v_sent, v_suppressed, v_failed
    );
    UPDATE public.marketing_campaign_operations AS operation
    SET status = v_status, audit_id = v_audit_id, updated_at = v_now
    WHERE operation.id = p_operation_id;
  ELSE
    v_audit_id := privacy_retention.g014_marketing_write_audit(
      p_operation_id, p_preview_hash, 'confirmed', 'MARKETING_BATCH_FINALIZED', NULL,
      v_requested, v_sent, v_suppressed, v_failed
    );
    UPDATE public.marketing_campaign_operations AS operation
    SET status = 'applying', audit_id = v_audit_id, updated_at = v_now
    WHERE operation.id = p_operation_id;
  END IF;
  RETURN public.marketing_campaign_receipt(p_operation_id);
END;
$_$;


--
-- Name: finalize_privacy_retention_run(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_privacy_retention_run(p_run_id uuid, p_preview_hash text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_run privacy_retention.privacy_retention_runs%ROWTYPE;
  v_item record;
  v_expected integer := 0;
  v_pending integer := 0;
  v_held integer := 0;
  v_failed integer := 0;
  v_separated integer := 0;
  v_storage_deleted integer := 0;
  v_database_readback boolean := true;
  v_storage_readback boolean := true;
  v_readback boolean := false;
  v_no_active_hold_mutated boolean := true;
  v_empty_scan_complete boolean := false;
  v_final_status text;
  v_audit_id uuid;
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  SELECT * INTO v_run FROM privacy_retention.privacy_retention_runs
  WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND OR v_run.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_run.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
    RAISE EXCEPTION 'privacy_retention_finalize_binding_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    v_run.class_code, v_run.adapter_version, v_run.source_mapping_version
  );
  IF v_run.status = 'completed' THEN
    RETURN pg_catalog.jsonb_build_object(
      'operationId', v_run.id,
      'status', 'applied',
      'readback', pg_catalog.jsonb_build_object(
        'passed', v_run.readback_passed,
        'checks', pg_catalog.jsonb_build_object(
          'expectedCountMatched', v_run.readback_passed,
          'databaseSourceAbsent', v_run.database_readback_passed,
          'storageProviderAbsent', v_run.storage_readback_passed,
          'noActiveHoldMutated', v_run.no_active_hold_mutated
        )
      ),
      'auditId', v_run.audit_id,
      'adapterVersion', v_run.adapter_version,
      'sourceMappingVersion', v_run.source_mapping_version,
      'errorCode', NULL
    );
  END IF;
  IF v_run.status NOT IN ('running', 'partial', 'held') THEN
    RAISE EXCEPTION 'privacy_retention_finalize_predecessor_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-retention-run:' || v_run.id::text, 0)
  );

  SELECT count(*),
         count(*) FILTER (WHERE status IN ('planned', 'storage_claimed')),
         count(*) FILTER (WHERE status = 'held'),
         count(*) FILTER (WHERE status = 'failed'),
         count(*) FILTER (WHERE status = 'separated'),
         count(*) FILTER (WHERE status = 'storage_deleted')
  INTO v_expected, v_pending, v_held, v_failed, v_separated, v_storage_deleted
  FROM privacy_retention.privacy_retention_run_items
  WHERE run_id = v_run.id;
  -- A zero-item run is complete only when a fresh due-work scan is empty.
  SELECT NOT EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_retention_work_items AS item
    WHERE item.class_code = v_run.class_code
      AND item.trigger_at <= v_run.cutoff
      AND item.status IN ('pending', 'failed', 'claimed')
  ) INTO v_empty_scan_complete;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_retention_run_items AS run_item
    JOIN privacy_retention.privacy_retention_work_items AS item ON item.id = run_item.work_item_id
    LEFT JOIN privacy_retention.retention_class_adapter_bindings AS binding
      ON binding.class_code = item.class_code
     AND binding.source_type = item.source_type
     AND binding.status = 'active'
    LEFT JOIN privacy_retention.retention_adapter_versions AS version_row
      ON version_row.adapter_code = binding.adapter_code
     AND version_row.adapter_version = binding.adapter_version
     AND version_row.status = 'active'
     AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
    WHERE run_item.run_id = v_run.id
      AND version_row.adapter_code IS NULL
  ) THEN
    RAISE EXCEPTION 'privacy_retention_finalize_adapter_not_active' USING ERRCODE = '55000';
  END IF;

  FOR v_item IN
    SELECT run_item.work_item_id, run_item.source_type, run_item.status,
           item.source_ref_hash, binding.adapter_code, binding.adapter_version,
           version_row.source_relation, version_row.source_identifier_column
    FROM privacy_retention.privacy_retention_run_items AS run_item
    JOIN privacy_retention.privacy_retention_work_items AS item ON item.id = run_item.work_item_id
    JOIN privacy_retention.retention_class_adapter_bindings AS binding
      ON binding.class_code = item.class_code AND binding.source_type = item.source_type
     AND binding.status = 'active'
    JOIN privacy_retention.retention_adapter_versions AS version_row
      ON version_row.adapter_code = binding.adapter_code
     AND version_row.adapter_version = binding.adapter_version AND version_row.status = 'active'
     AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
    WHERE run_item.run_id = v_run.id
  LOOP
    IF v_item.source_type IN ('storage_object', 'ocr_artifact') THEN
      IF v_item.status IS DISTINCT FROM 'storage_deleted'
         OR NOT EXISTS (
           SELECT 1 FROM privacy_retention.g014_retention_receipts AS receipt
           WHERE receipt.run_id = v_run.id AND receipt.work_item_id = v_item.work_item_id
             AND receipt.receipt_kind = 'storage_provider_absence'
         ) THEN
        v_storage_readback := false;
      END IF;
    ELSIF v_item.status IS DISTINCT FROM 'separated'
       OR NOT privacy_retention.g014_retention_source_absent(
         v_item.adapter_code, v_item.source_relation,
         v_item.source_identifier_column, v_item.source_ref_hash
       )
       OR NOT EXISTS (
         SELECT 1 FROM privacy_retention.g014_retention_receipts AS receipt
         WHERE receipt.run_id = v_run.id AND receipt.work_item_id = v_item.work_item_id
           AND receipt.receipt_kind = 'database_source_absence'
       ) THEN
      v_database_readback := false;
    END IF;
  END LOOP;
  IF (
    SELECT count(*)
    FROM privacy_retention.g014_retention_receipts AS receipt
    WHERE receipt.run_id = v_run.id
      AND receipt.receipt_kind = 'storage_provider_absence'
  ) IS DISTINCT FROM v_storage_deleted THEN
    v_storage_readback := false;
  END IF;

  v_no_active_hold_mutated :=
    privacy_retention.g014_retention_no_active_hold_mutated(v_run.id);

  v_readback := v_pending = 0 AND v_held = 0 AND v_failed = 0
    AND v_database_readback AND v_storage_readback AND v_no_active_hold_mutated
    AND (
      v_expected > 0
      OR (
        v_empty_scan_complete
        AND v_run.scanned_count = 0
        AND v_run.planned_count = 0
        AND v_run.held_count = 0
      )
    );
  v_final_status := CASE
    WHEN v_readback THEN 'completed'
    WHEN v_held = v_expected AND v_expected > 0 THEN 'held'
    ELSE 'partial'
  END;

  UPDATE privacy_retention.privacy_retention_runs
  SET status = v_final_status,
      separated_count = v_separated,
      storage_deleted_count = v_storage_deleted,
      held_count = v_held,
      failure_count = v_failed,
      database_readback_passed = v_database_readback,
      storage_readback_passed = v_storage_readback,
      no_active_hold_mutated = v_no_active_hold_mutated,
      storage_receipts_hash = CASE
        WHEN v_readback THEN privacy_retention.g014_retention_storage_receipt_set_hash(v_run.id)
        ELSE NULL
      END,
      readback_passed = v_readback,
      completed_at = CASE WHEN v_final_status = 'completed' THEN pg_catalog.clock_timestamp() ELSE NULL END
  WHERE id = v_run.id
  RETURNING * INTO v_run;

  v_audit_id := privacy_retention.g014_retention_append_audit(
    v_run,
    CASE WHEN v_run.readback_passed THEN 'readback_passed' ELSE 'readback_failed' END,
    'RETENTION_READBACK'
  );
  UPDATE privacy_retention.privacy_retention_runs SET audit_id = v_audit_id WHERE id = v_run.id;

  RETURN pg_catalog.jsonb_build_object(
    'operationId', v_run.id,
    'status', CASE
      WHEN v_run.status = 'completed' THEN 'applied'
      WHEN v_run.status = 'held' THEN 'partial'
      ELSE v_run.status
    END,
    'readback', pg_catalog.jsonb_build_object(
      'passed', v_run.readback_passed,
      'checks', pg_catalog.jsonb_build_object(
        'expectedCountMatched', v_run.readback_passed,
        'databaseSourceAbsent', v_run.database_readback_passed,
        'storageProviderAbsent', v_run.storage_readback_passed,
        'noActiveHoldMutated', v_run.no_active_hold_mutated
      )
    ),
    'auditId', v_audit_id,
    'adapterVersion', v_run.adapter_version,
    'sourceMappingVersion', v_run.source_mapping_version,
    'errorCode', CASE WHEN v_run.readback_passed THEN NULL ELSE 'privacy_retention_readback_incomplete' END
  );
END;
$$;


--
-- Name: finish_review_media_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_review_media_cleanup() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF privacy_retention.g041_current_claim_user_id() IS NULL THEN RETURN NULL; END IF;
  UPDATE review_media_private.cleanup c SET complete = true
    WHERE c.owner_id = privacy_retention.g041_current_claim_user_id() AND c.retired AND NOT c.complete
      AND NOT EXISTS (SELECT 1 FROM storage.objects o
        WHERE o.bucket_id = CASE c.purpose WHEN 'verification' THEN 'review-verifications' ELSE 'review-photos' END
          AND o.name = c.path)
      AND NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'review-photos' AND o.name = c.path);
  RETURN (SELECT count(*) FROM review_media_private.cleanup c WHERE c.owner_id = privacy_retention.g041_current_claim_user_id() AND c.retired AND NOT c.complete AND NOT review_media_private.referenced(c.path));
END $$;


--
-- Name: g014_marketing_batch_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.g014_marketing_batch_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NOT (
    (OLD.status = 'prepared' AND NEW.status IN ('claimed', 'provider_failed', 'completed'))
    OR (OLD.status = 'claimed' AND NEW.status = 'completed')
    OR NEW.status IS NOT DISTINCT FROM OLD.status
  ) THEN
    RAISE EXCEPTION 'marketing_batch_transition_invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_marketing_operation_terminal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.g014_marketing_operation_terminal_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status IN ('applied', 'partial', 'failed')
     AND EXISTS (
       SELECT 1
       FROM public.marketing_campaign_recipients AS recipient
       WHERE recipient.operation_id = NEW.id
         AND recipient.status IN ('pending', 'eligible')
       UNION ALL
       SELECT 1
       FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
       WHERE recipient.operation_id = NEW.id
         AND recipient.status = 'claimed'
     ) THEN
    RAISE EXCEPTION 'marketing_operation_has_unresolved_recipients' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g014_marketing_public_recipient_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.g014_marketing_public_recipient_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NOT (
    (OLD.status = 'pending' AND NEW.status IN ('eligible', 'suppressed'))
    OR (OLD.status = 'eligible' AND NEW.status IN ('sent', 'suppressed', 'failed'))
    OR NEW.status IS NOT DISTINCT FROM OLD.status
  ) THEN
    RAISE EXCEPTION 'marketing_recipient_transition_invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: g038_reserve_account_deletion_commitment(text, uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, text, bytea, bytea, bytea, bytea, bytea, uuid, bytea, uuid, uuid, timestamp with time zone, uuid, bytea, uuid, bytea, uuid, bytea, uuid, bytea, smallint, bytea, text, text, text, bytea, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.g038_reserve_account_deletion_commitment(p_phase text, p_assertion_id uuid, p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_session_id uuid, p_proof_id uuid, p_preview_hash text, p_confirmation_text text, p_idempotency_key text, p_source_manifest_hash text, p_confirmation_digest bytea, p_idempotency_key_digest bytea, p_actor_assertion_digest bytea, p_assertion_root_head_sha256 bytea, p_hmac_head_sha256 bytea, p_assertion_nonce uuid, p_request_digest bytea, p_preflight_id uuid, p_commitment_id uuid, p_commitment_expires_at timestamp with time zone, p_poll_route_id uuid, p_poll_secret_digest bytea, p_receipt_route_id uuid, p_receipt_secret_digest bytea, p_recovery_route_id uuid, p_recovery_secret_digest bytea, p_cleanup_route_id uuid, p_cleanup_secret_digest bytea, p_response_status smallint, p_response_body_sha256 bytea, p_ciphertext_schema text, p_key_reference text, p_algorithm text, p_nonce bytea, p_aad bytea, p_aad_sha256 bytea, p_ciphertext bytea, p_auth_tag bytea) RETURNS TABLE(result text, commitment_id uuid, expires_at timestamp with time zone, mode text, response_status smallint, response_body_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_existing   public.g038_deletion_commitment;
  v_route_match integer;
BEGIN
  -- Phase discriminator. Any other or null value rejects with zero writes.
  IF p_phase IS NULL OR p_phase NOT IN ('LOOKUP', 'CREATE') THEN
    RAISE EXCEPTION 'g038_invalid_phase' USING ERRCODE = '22023';
  END IF;

  -- Arguments 01-18 are NOT NULL in both phases.
  IF p_assertion_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_target_user_id IS NULL
     OR p_request_id IS NULL
     OR p_session_id IS NULL
     OR p_proof_id IS NULL
     OR p_preview_hash IS NULL
     OR p_confirmation_text IS NULL
     OR p_idempotency_key IS NULL
     OR p_source_manifest_hash IS NULL
     OR p_confirmation_digest IS NULL
     OR p_idempotency_key_digest IS NULL
     OR p_actor_assertion_digest IS NULL
     OR p_assertion_root_head_sha256 IS NULL
     OR p_hmac_head_sha256 IS NULL
     OR p_assertion_nonce IS NULL
     OR p_request_digest IS NULL THEN
    RAISE EXCEPTION 'g038_required_input_null' USING ERRCODE = '22023';
  END IF;

  -- Every digest-valued bytea among arguments 01-18 is exactly 32 bytes.
  IF pg_catalog.octet_length(p_confirmation_digest) <> 32
     OR pg_catalog.octet_length(p_idempotency_key_digest) <> 32
     OR pg_catalog.octet_length(p_actor_assertion_digest) <> 32
     OR pg_catalog.octet_length(p_assertion_root_head_sha256) <> 32
     OR pg_catalog.octet_length(p_hmac_head_sha256) <> 32
     OR pg_catalog.octet_length(p_request_digest) <> 32 THEN
    RAISE EXCEPTION 'g038_digest_length_invalid' USING ERRCODE = '22023';
  END IF;

  -- LOCK LADDER DIVERGENCE, recorded explicitly so it reads as decided rather
  -- than overlooked.
  --
  -- The G005 source requires LOOKUP to take pg_advisory_xact_lock in the
  -- final-G004 order, then FOR KEY SHARE on immutable heads, then FOR SHARE on
  -- assertion / proof / binding / commitment / replay; and CREATE to take that
  -- same prefix and then FOR UPDATE "as applicable". This file takes no lock at
  -- all, and that needs justifying rather than passing in silence.
  --
  -- Most of the named relations are genuinely out of scope here: this migration
  -- creates exactly two tables (g038_deletion_commitment and
  -- g038_deletion_route). There is no assertion relation, no proof relation, no
  -- binding relation, no immutable-head relation and no separate replay
  -- relation for a lock to be taken on, so for those the ladder is vacuous and
  -- "as applicable" applies straightforwardly.
  --
  -- The two relations that DO exist are read with bare SELECTs. That is the
  -- real divergence. It is deliberate: correctness here is arbitrated by the
  -- partial unique index on the idempotency scope and by
  -- g038_commitment_nonce_unique, not by lock ordering. A concurrent racer
  -- cannot produce a second live commitment in the same scope or reuse a nonce,
  -- because the index rejects it and the unique_violation handler maps the
  -- rejection to a defined result. Taking FOR SHARE on a row the racer has not
  -- inserted yet would not prevent the race either -- there is no row to lock.
  --
  -- Consequence, stated rather than hidden: the loser of a concurrent CREATE
  -- learns this at INSERT time (409) instead of at lock-acquisition time. The
  -- outcome is identical and no durable write occurs on the losing path.
  --
  -- Phase 2b owns confirming this against the full G005 ladder once the
  -- remaining relations exist. Until then the divergence is scoped to the two
  -- relations above and recorded in H5 openForPhase2b.
  IF p_phase = 'LOOKUP' THEN
    -- Arguments 19-39 must each be explicitly SQL NULL. Supplying any
    -- candidate or cryptographic argument rejects with zero writes.
    IF p_preflight_id IS NOT NULL
       OR p_commitment_id IS NOT NULL
       OR p_commitment_expires_at IS NOT NULL
       OR p_poll_route_id IS NOT NULL
       OR p_poll_secret_digest IS NOT NULL
       OR p_receipt_route_id IS NOT NULL
       OR p_receipt_secret_digest IS NOT NULL
       OR p_recovery_route_id IS NOT NULL
       OR p_recovery_secret_digest IS NOT NULL
       OR p_cleanup_route_id IS NOT NULL
       OR p_cleanup_secret_digest IS NOT NULL
       OR p_response_status IS NOT NULL
       OR p_response_body_sha256 IS NOT NULL
       OR p_ciphertext_schema IS NOT NULL
       OR p_key_reference IS NOT NULL
       OR p_algorithm IS NOT NULL
       OR p_nonce IS NOT NULL
       OR p_aad IS NOT NULL
       OR p_aad_sha256 IS NOT NULL
       OR p_ciphertext IS NOT NULL
       OR p_auth_tag IS NOT NULL THEN
      RAISE EXCEPTION 'g038_lookup_forbidden_nonnull' USING ERRCODE = '22023';
    END IF;

    SELECT c.* INTO v_existing
    FROM public.g038_deletion_commitment AS c
    WHERE c.actor_user_id = p_actor_user_id
      AND c.target_user_id = p_target_user_id
      AND c.request_id = p_request_id
      AND c.idempotency_key_digest = p_idempotency_key_digest
      AND c.status = 'AVAILABLE'
      AND c.expires_at > pg_catalog.now();

    IF NOT FOUND THEN
      -- CREATE_REQUIRED: remaining five projection columns are SQL NULL.
      RETURN QUERY
        SELECT 'CREATE_REQUIRED'::text,
               NULL::uuid,
               NULL::timestamptz,
               NULL::text,
               NULL::smallint,
               NULL::bytea;
      RETURN;
    END IF;

    -- REPLAY: the retained AVAILABLE metadata projection, no crypto bytes.
    RETURN QUERY
      SELECT 'REPLAY'::text,
             v_existing.commitment_id,
             v_existing.expires_at,
             v_existing.mode,
             v_existing.response_status,
             v_existing.response_body_sha256;
    RETURN;
  END IF;

  -- p_phase = 'CREATE': arguments 19-39 are each NOT NULL.
  IF p_preflight_id IS NULL
     OR p_commitment_id IS NULL
     OR p_commitment_expires_at IS NULL
     OR p_poll_route_id IS NULL
     OR p_poll_secret_digest IS NULL
     OR p_receipt_route_id IS NULL
     OR p_receipt_secret_digest IS NULL
     OR p_recovery_route_id IS NULL
     OR p_recovery_secret_digest IS NULL
     OR p_cleanup_route_id IS NULL
     OR p_cleanup_secret_digest IS NULL
     OR p_response_status IS NULL
     OR p_response_body_sha256 IS NULL
     OR p_ciphertext_schema IS NULL
     OR p_key_reference IS NULL
     OR p_algorithm IS NULL
     OR p_nonce IS NULL
     OR p_aad IS NULL
     OR p_aad_sha256 IS NULL
     OR p_ciphertext IS NULL
     OR p_auth_tag IS NULL THEN
    RAISE EXCEPTION 'g038_create_required_input_null' USING ERRCODE = '22023';
  END IF;

  -- CREATE-phase byte bounds.
  IF pg_catalog.octet_length(p_poll_secret_digest) <> 32
     OR pg_catalog.octet_length(p_receipt_secret_digest) <> 32
     OR pg_catalog.octet_length(p_recovery_secret_digest) <> 32
     OR pg_catalog.octet_length(p_cleanup_secret_digest) <> 32
     OR pg_catalog.octet_length(p_response_body_sha256) <> 32
     OR pg_catalog.octet_length(p_aad_sha256) <> 32
     OR pg_catalog.octet_length(p_nonce) <> 12
     OR pg_catalog.octet_length(p_auth_tag) <> 16
     OR pg_catalog.octet_length(p_aad) NOT BETWEEN 1 AND 4096
     OR pg_catalog.octet_length(p_ciphertext) NOT BETWEEN 1 AND 8192 THEN
    RAISE EXCEPTION 'g038_create_byte_bounds_invalid' USING ERRCODE = '22023';
  END IF;

  -- Candidate identifier validity: the six candidate UUIDs must be nonnil and
  -- pairwise distinct within the candidate.
  --
  -- G005's CREATE clause requires the candidate identifiers to be nonnil and
  -- pairwise distinct, and clause A carries scoped candidate uniqueness forward
  -- as binding. Neither was checked here before.
  --
  -- Without this guard the failures are real but misclassified. Two equal
  -- supplied route ids trip the route_id primary key INSIDE the sub-block,
  -- enter the unique_violation handler, find no live row for the scope, and
  -- re-raise as 23505 -> 409 -- yet this is a malformed caller input, which
  -- every other input defect in this body reports as 400-class 22023. And a nil
  -- all-zero UUID was accepted outright before this guard existed: it is NOT
  -- NULL, so the nullability checks pass, and nothing else rejected it. The
  -- guard below is what rejects it now.
  --
  -- The six are ordinals 19, 20, 22, 24, 26 and 28: p_preflight_id,
  -- p_commitment_id, and the four route ids. Pairwise distinctness is tested by
  -- comparing the array length against its DISTINCT cardinality, which is
  -- equivalent to all-pairs comparison for six values and does not enumerate
  -- fifteen predicates.
  IF p_preflight_id      = '00000000-0000-0000-0000-000000000000'::uuid
     OR p_commitment_id   = '00000000-0000-0000-0000-000000000000'::uuid
     OR p_poll_route_id   = '00000000-0000-0000-0000-000000000000'::uuid
     OR p_receipt_route_id = '00000000-0000-0000-0000-000000000000'::uuid
     OR p_recovery_route_id = '00000000-0000-0000-0000-000000000000'::uuid
     OR p_cleanup_route_id  = '00000000-0000-0000-0000-000000000000'::uuid
     OR (
       SELECT pg_catalog.count(DISTINCT u)
       FROM pg_catalog.unnest(ARRAY[
         p_preflight_id, p_commitment_id, p_poll_route_id,
         p_receipt_route_id, p_recovery_route_id, p_cleanup_route_id
       ]) AS u
     ) <> 6 THEN
    RAISE EXCEPTION 'g038_candidate_identifier_invalid' USING ERRCODE = '22023';
  END IF;

  -- Fixed literals: status 200, and the three fixed cryptographic strings.
  --
  -- The storage CHECKs added alongside the column declarations are defence in
  -- depth, but they are not sufficient on their own: a wrong value would reach
  -- the INSERT and raise 23514 (check_violation), which is in neither the
  -- accepted 400-class mapping nor the 23505 -> 409 mapping, so it would
  -- surface unmapped. Every other 400-class rejection in this body raises
  -- 22023, so these three are validated here to the same class, before any
  -- durable write. The CHECKs remain as storage invariants.
  IF p_response_status <> 200::smallint THEN
    RAISE EXCEPTION 'g038_response_status_not_200' USING ERRCODE = '22023';
  END IF;

  IF p_ciphertext_schema IS DISTINCT FROM 'G038-PREFLIGHT-REPLAY-CIPHERTEXT-V1'
     OR p_key_reference   IS DISTINCT FROM 'g038_preflight_replay_aead_v1'
     OR p_algorithm       IS DISTINCT FROM 'AES-256-GCM' THEN
    RAISE EXCEPTION 'g038_fixed_string_invalid' USING ERRCODE = '22023';
  END IF;

  -- AAD reconstruction hash must bind.
  IF p_aad_sha256 <> pg_catalog.sha256(p_aad) THEN
    RAISE EXCEPTION 'g038_aad_hash_mismatch' USING ERRCODE = '22023';
  END IF;

  -- Expiry must be in the future at commit time (TTL fencing, no scheduler).
  IF p_commitment_expires_at <= pg_catalog.now() THEN
    RAISE EXCEPTION 'g038_expiry_not_future' USING ERRCODE = '22023';
  END IF;

  -- Replay before insert: an AVAILABLE unexpired commitment wins, but ONLY if
  -- the supplied bytes equal the retained bytes.
  --
  -- G005 source, replay/conflict mapping: "Replay: unequal retained
  -- request/capability/kind/route/bytes 409; equal retained success." and
  -- "Equal replay is no-write; partial/reordered/stale/unequal is zero-write."
  --
  -- Matching the idempotency scope alone is NOT sufficient to return REPLAY. If
  -- a caller reuses the same actor/target/request/key tuple but supplies
  -- different candidate or cryptographic bytes, reporting REPLAY would tell it
  -- its own ciphertext was committed when a different ciphertext is in fact
  -- retained. That is a conflict, not a success.
  SELECT c.* INTO v_existing
  FROM public.g038_deletion_commitment AS c
  WHERE c.actor_user_id = p_actor_user_id
    AND c.target_user_id = p_target_user_id
    AND c.request_id = p_request_id
    AND c.idempotency_key_digest = p_idempotency_key_digest
    AND c.status = 'AVAILABLE'
    AND c.expires_at > pg_catalog.now();

  IF FOUND THEN
    -- Byte equality over the supplied identity, candidate and cryptographic
    -- values that a retained row can carry.
    --
    -- Accounting, so this list is not read as exhaustive by accident. Of the 39
    -- inputs: 1 is p_phase (the discriminator, not stored); 4 are the scope key
    -- itself (actor, target, request, idempotency_key_digest) and are already
    -- equal by the SELECT predicate above; 24 are compared field-by-field
    -- below; 4 are the route secret digests, which live on the ROUTE table
    -- rather than on the commitment row and are therefore compared by the
    -- separate route query after this block; and 6 are deliberately excluded --
    -- p_commitment_id, p_commitment_expires_at and the four route ids -- because
    -- clause A specifies REPLAY returns the RETAINED projection, so a retry may
    -- legitimately supply freshly generated ids and the retained ones remain
    -- authoritative. 1 + 4 + 24 + 4 + 6 = 39.
    IF v_existing.assertion_id            IS DISTINCT FROM p_assertion_id
       OR v_existing.session_id           IS DISTINCT FROM p_session_id
       OR v_existing.proof_id             IS DISTINCT FROM p_proof_id
       OR v_existing.preview_hash         IS DISTINCT FROM p_preview_hash
       OR v_existing.confirmation_text    IS DISTINCT FROM p_confirmation_text
       OR v_existing.idempotency_key      IS DISTINCT FROM p_idempotency_key
       OR v_existing.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash
       OR v_existing.confirmation_digest  IS DISTINCT FROM p_confirmation_digest
       OR v_existing.actor_assertion_digest
            IS DISTINCT FROM p_actor_assertion_digest
       OR v_existing.assertion_root_head_sha256
            IS DISTINCT FROM p_assertion_root_head_sha256
       OR v_existing.hmac_head_sha256     IS DISTINCT FROM p_hmac_head_sha256
       OR v_existing.assertion_nonce      IS DISTINCT FROM p_assertion_nonce
       OR v_existing.request_digest       IS DISTINCT FROM p_request_digest
       OR v_existing.preflight_id         IS DISTINCT FROM p_preflight_id
       OR v_existing.response_status      IS DISTINCT FROM p_response_status
       OR v_existing.response_body_sha256 IS DISTINCT FROM p_response_body_sha256
       OR v_existing.ciphertext_schema    IS DISTINCT FROM p_ciphertext_schema
       OR v_existing.key_reference        IS DISTINCT FROM p_key_reference
       OR v_existing.algorithm            IS DISTINCT FROM p_algorithm
       OR v_existing.nonce                IS DISTINCT FROM p_nonce
       OR v_existing.aad                  IS DISTINCT FROM p_aad
       OR v_existing.aad_sha256           IS DISTINCT FROM p_aad_sha256
       OR v_existing.ciphertext           IS DISTINCT FROM p_ciphertext
       OR v_existing.auth_tag             IS DISTINCT FROM p_auth_tag
    THEN
      -- Conflict class, not invalid-parameter class. ERRCODE 23505 is used
      -- because it is the code the accepted contract already maps to 409, and
      -- clause A directs that existing identifier-free conflict mappings remain
      -- unchanged. No column name or byte value is disclosed in the message.
      RAISE EXCEPTION 'g038_replay_unequal' USING ERRCODE = '23505';
    END IF;

    -- Route capability bytes. G005's conflict mapping names
    -- "request/capability/kind/route/bytes", and the four route secret digests
    -- are exactly those route bytes. They are not columns of v_existing -- the
    -- commitment row carries no secret_digest -- so equality is established by
    -- counting how many of the retained commitment's routes match the supplied
    -- (kind, digest) pairs. Anything other than all four matching is a
    -- conflict, by the same 23505 -> 409 mapping used above.
    SELECT pg_catalog.count(*) INTO v_route_match
    FROM public.g038_deletion_route AS r
    WHERE r.commitment_id = v_existing.commitment_id
      AND (
        (r.route_kind = 'POLL'     AND r.secret_digest = p_poll_secret_digest)
        OR (r.route_kind = 'RECEIPT'  AND r.secret_digest = p_receipt_secret_digest)
        OR (r.route_kind = 'RECOVERY' AND r.secret_digest = p_recovery_secret_digest)
        OR (r.route_kind = 'CLEANUP'  AND r.secret_digest = p_cleanup_secret_digest)
      );

    IF v_route_match IS DISTINCT FROM 4 THEN
      RAISE EXCEPTION 'g038_replay_unequal' USING ERRCODE = '23505';
    END IF;

    RETURN QUERY
      SELECT 'REPLAY'::text,
             v_existing.commitment_id,
             v_existing.expires_at,
             v_existing.mode,
             v_existing.response_status,
             v_existing.response_body_sha256;
    RETURN;
  END IF;

  -- All-or-nothing construction. Any constraint failure aborts the whole
  -- statement, leaving zero durable writes.
  --
  -- The construction is wrapped in a sub-block with a unique_violation handler.
  -- Three distinct collisions can reach it:
  --
  --   1. An AVAILABLE-but-expired row occupying the idempotency scope. The
  --      partial index predicate is status-only because expires_at > now() is
  --      not index-legal, so such a row still occupies the scope while the
  --      replay SELECT (which also requires expires_at > now()) skips it.
  --   2. Two concurrent CREATEs. Both pass the replay SELECT under READ
  --      COMMITTED; the loser hits the index.
  --   3. A nonce collision against g038_commitment_nonce_unique, from any
  --      scope at all.
  --
  -- What the handler actually returns, stated precisely rather than
  -- optimistically. Its REPLAY branch requires the retained row to be
  -- byte-equal across all 24 compared fields AND all four route digests. One of
  -- those 24 is `nonce`. The G005 source requires a freshly generated CSPRNG
  -- nonce per candidate and forbids resubmitting one, and this file enforces
  -- that uniqueness at storage level. So for any conforming caller:
  --
  --   * Collisions 1 and 2 carry a DIFFERENT nonce, fail the equality set, and
  --     re-raise the original 23505 -> 409.
  --   * The REPLAY branch is reachable only if a caller resubmits an identical
  --     nonce, which G005 forbids.
  --
  -- The handler's REPLAY branch is therefore near-unreachable in practice, and
  -- it is retained deliberately: it is the only construction under which
  -- returning REPLAY is safe, so it must stay guarded rather than be widened.
  --
  -- DIVERGENCE, recorded explicitly. G005's CREATE clause resolves a concurrent
  -- equal winner as a metadata-only REPLAY with no candidate writes. Because
  -- nonce equality is required here, this file maps that case to 409 instead.
  -- That is a real divergence, not an oversight. It is fail-closed and lands on
  -- G005's own recovery path -- 409, then LOOKUP, then checkout -- and the
  -- alternative (dropping nonce from the equality set) would reintroduce the
  -- defect where a caller is told its own ciphertext was committed when a
  -- different one is retained. The narrower error is the safer error.
  --
  -- CROSS-SCOPE NONCE COLLISION, mapped deliberately rather than incidentally.
  -- g038_commitment_nonce_unique is table-global, but the handler's replay
  -- SELECT is scope-pinned, so a nonce that collides with a row in a DIFFERENT
  -- idempotency scope yields NOT FOUND and re-raises the original 23505 -> 409.
  -- Arguably that is a malformed input and 22023 would be the more consistent
  -- class. It is left at 409 on purpose: a pre-check would be TOCTOU-racy
  -- (another transaction can insert between the check and the INSERT), so the
  -- constraint must remain the arbiter, and the constraint can only report
  -- 23505. G005 requires a fresh CSPRNG nonce per candidate with collision
  -- retries completed before CREATE, so no conforming caller reaches this path.
  -- The residual disclosure is a global nonce-existence oracle, which is
  -- computationally worthless against 96-bit CSPRNG nonces and reachable only
  -- by the single trusted grantee.
  --
  -- PRECONDITION. This mapping assumes READ COMMITTED, which is the PostgreSQL
  -- default. Under REPEATABLE READ or SERIALIZABLE the concurrent case can
  -- surface 40001 (serialization_failure) instead, which is outside this body's
  -- mapped error set. Phase 2b must pin the isolation level or map 40001.
  --
  -- The sub-block rolls back on failure, so zero-write is preserved on every
  -- path above.
  BEGIN
    INSERT INTO public.g038_deletion_commitment (
      commitment_id, assertion_id, actor_user_id, target_user_id, request_id,
      session_id, proof_id, preview_hash, confirmation_text, idempotency_key,
      source_manifest_hash, confirmation_digest, idempotency_key_digest,
      actor_assertion_digest, assertion_root_head_sha256, hmac_head_sha256,
      assertion_nonce, request_digest, preflight_id, expires_at, status, mode,
      response_status, response_body_sha256, ciphertext_schema, key_reference,
      algorithm, nonce, aad, aad_sha256, ciphertext, auth_tag
    )
    VALUES (
      p_commitment_id, p_assertion_id, p_actor_user_id, p_target_user_id,
      p_request_id, p_session_id, p_proof_id, p_preview_hash,
      p_confirmation_text, p_idempotency_key, p_source_manifest_hash,
      p_confirmation_digest, p_idempotency_key_digest, p_actor_assertion_digest,
      p_assertion_root_head_sha256, p_hmac_head_sha256, p_assertion_nonce,
      p_request_digest, p_preflight_id, p_commitment_expires_at, 'AVAILABLE',
      'V1_COMPAT', p_response_status, p_response_body_sha256,
      p_ciphertext_schema, p_key_reference, p_algorithm, p_nonce, p_aad,
      p_aad_sha256, p_ciphertext, p_auth_tag
    );

    INSERT INTO public.g038_deletion_route (route_id, commitment_id, route_kind, secret_digest)
    VALUES
      (p_poll_route_id,     p_commitment_id, 'POLL',     p_poll_secret_digest),
      (p_receipt_route_id,  p_commitment_id, 'RECEIPT',  p_receipt_secret_digest),
      (p_recovery_route_id, p_commitment_id, 'RECOVERY', p_recovery_secret_digest),
      (p_cleanup_route_id,  p_commitment_id, 'CLEANUP',  p_cleanup_secret_digest);
  EXCEPTION
    WHEN unique_violation THEN
      SELECT c.* INTO v_existing
      FROM public.g038_deletion_commitment AS c
      WHERE c.actor_user_id = p_actor_user_id
        AND c.target_user_id = p_target_user_id
        AND c.request_id = p_request_id
        AND c.idempotency_key_digest = p_idempotency_key_digest
        AND c.status = 'AVAILABLE'
        AND c.expires_at > pg_catalog.now();

      -- Same equality obligation as the main replay path above (G005: "unequal
      -- retained ... 409; equal retained success"). If no live row is visible,
      -- or a live row is visible but its retained bytes differ from the
      -- supplied bytes, this is a genuine conflict and the ORIGINAL
      -- unique_violation is re-raised unchanged -- it is already the 23505 the
      -- accepted contract maps to 409. Only a byte-equal retained row yields
      -- REPLAY.
      IF NOT FOUND
         OR v_existing.assertion_id         IS DISTINCT FROM p_assertion_id
         OR v_existing.session_id           IS DISTINCT FROM p_session_id
         OR v_existing.proof_id             IS DISTINCT FROM p_proof_id
         OR v_existing.preview_hash         IS DISTINCT FROM p_preview_hash
         OR v_existing.confirmation_text    IS DISTINCT FROM p_confirmation_text
         OR v_existing.idempotency_key      IS DISTINCT FROM p_idempotency_key
         OR v_existing.source_manifest_hash IS DISTINCT FROM p_source_manifest_hash
         OR v_existing.confirmation_digest  IS DISTINCT FROM p_confirmation_digest
         OR v_existing.actor_assertion_digest
              IS DISTINCT FROM p_actor_assertion_digest
         OR v_existing.assertion_root_head_sha256
              IS DISTINCT FROM p_assertion_root_head_sha256
         OR v_existing.hmac_head_sha256     IS DISTINCT FROM p_hmac_head_sha256
         OR v_existing.assertion_nonce      IS DISTINCT FROM p_assertion_nonce
         OR v_existing.request_digest       IS DISTINCT FROM p_request_digest
         OR v_existing.preflight_id         IS DISTINCT FROM p_preflight_id
         OR v_existing.response_status      IS DISTINCT FROM p_response_status
         OR v_existing.response_body_sha256 IS DISTINCT FROM p_response_body_sha256
         OR v_existing.ciphertext_schema    IS DISTINCT FROM p_ciphertext_schema
         OR v_existing.key_reference        IS DISTINCT FROM p_key_reference
         OR v_existing.algorithm            IS DISTINCT FROM p_algorithm
         OR v_existing.nonce                IS DISTINCT FROM p_nonce
         OR v_existing.aad                  IS DISTINCT FROM p_aad
         OR v_existing.aad_sha256           IS DISTINCT FROM p_aad_sha256
         OR v_existing.ciphertext           IS DISTINCT FROM p_ciphertext
         OR v_existing.auth_tag             IS DISTINCT FROM p_auth_tag
      THEN
        RAISE;
      END IF;

      -- Route capability bytes, same obligation as the main replay path. The
      -- retained commitment's four routes must match the supplied (kind,
      -- digest) pairs exactly; anything else is a conflict and the original
      -- unique_violation is re-raised unchanged.
      SELECT pg_catalog.count(*) INTO v_route_match
      FROM public.g038_deletion_route AS r
      WHERE r.commitment_id = v_existing.commitment_id
        AND (
          (r.route_kind = 'POLL'     AND r.secret_digest = p_poll_secret_digest)
          OR (r.route_kind = 'RECEIPT'  AND r.secret_digest = p_receipt_secret_digest)
          OR (r.route_kind = 'RECOVERY' AND r.secret_digest = p_recovery_secret_digest)
          OR (r.route_kind = 'CLEANUP'  AND r.secret_digest = p_cleanup_secret_digest)
        );

      IF v_route_match IS DISTINCT FROM 4 THEN
        RAISE;
      END IF;

      RETURN QUERY
        SELECT 'REPLAY'::text,
               v_existing.commitment_id,
               v_existing.expires_at,
               v_existing.mode,
               v_existing.response_status,
               v_existing.response_body_sha256;
      RETURN;
  END;
  -- CREATED: the newly committed-visible projection.
  RETURN QUERY
    SELECT 'CREATED'::text,
           c.commitment_id,
           c.expires_at,
           c.mode,
           c.response_status,
           c.response_body_sha256
    FROM public.g038_deletion_commitment AS c
    WHERE c.commitment_id = p_commitment_id;
END
$$;


--
-- Name: generate_unique_id(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_unique_id(p_youtube_link text, p_name text, p_tzuyang_review text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    combined_string TEXT;
BEGIN
    combined_string := COALESCE(p_youtube_link, '') || '|' ||
                       COALESCE(p_name, '') || '|' ||
                       COALESCE(p_tzuyang_review, '');
    RETURN encode(extensions.digest(combined_string, 'sha256'), 'hex');
END;
$$;


--
-- Name: FUNCTION generate_unique_id(p_youtube_link text, p_name text, p_tzuyang_review text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_unique_id(p_youtube_link text, p_name text, p_tzuyang_review text) IS 'youtube_link + name + tzuyang_review 기반 SHA-256 해시 (search_path 보안 적용)';


--
-- Name: get_account_deletion_storage_work(uuid, uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_account_deletion_storage_work(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_attempt_token uuid) RETURNS TABLE(bucket_id text, object_name text, object_id uuid, object_version text, object_locator_hash text, object_version_hash text, provider_idempotency_key text, work_state text, work_mode text, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_attempt privacy_retention.account_deletion_external_job_attempts%ROWTYPE;
  v_mode text;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_assert_external_job_binding(
    p_actor_user_id, p_target_user_id, p_request_id, p_preview_hash,
    p_idempotency_key, p_source_manifest_hash, 'storage', p_attempt_token, false
  );
  SELECT * INTO v_attempt
  FROM privacy_retention.account_deletion_external_job_attempts
  WHERE attempt_token = p_attempt_token
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_storage_work_not_prepared' USING ERRCODE = '55000';
  END IF;

  IF v_attempt.state IN ('egress_unknown', 'reconciliation_required') THEN
    v_mode := 'verify_absence_only';
  ELSIF v_attempt.state = 'leased' THEN
    PERFORM privacy_retention.g014_account_deletion_assert_external_job_binding(
      p_actor_user_id, p_target_user_id, p_request_id, p_preview_hash,
      p_idempotency_key, p_source_manifest_hash, 'storage', p_attempt_token, true
    );
    v_mode := 'delete_then_verify';
  ELSE
    RAISE EXCEPTION 'account_deletion_storage_work_not_prepared' USING ERRCODE = '55000';
  END IF;

  IF v_attempt.storage_object_locator_hash IS NULL THEN
    RETURN;
  END IF;

  IF v_mode = 'verify_absence_only' THEN
    RETURN QUERY
    SELECT
      NULL::text,
      NULL::text,
      captured.object_id,
      captured.object_version,
      captured.object_locator_hash,
      captured.object_version_hash,
      'g014-storage-' || pg_catalog.substr(p_request_id::text, 1, 8)
        || '-' || p_attempt_token::text
        || '-' || pg_catalog.substr(captured.object_locator_hash, 1, 40),
      v_mode,
      v_mode,
      p_source_manifest_hash
    FROM privacy_retention.account_deletion_storage_objects AS captured
    WHERE captured.request_id = p_request_id
      AND captured.object_locator_hash = v_attempt.storage_object_locator_hash
      AND captured.object_version_hash = v_attempt.storage_object_version_hash
      AND captured.object_id = v_attempt.storage_object_id
      AND captured.object_version = v_attempt.storage_object_version;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    object_row.bucket_id::text,
    object_row.name::text,
    captured.object_id,
    captured.object_version,
    captured.object_locator_hash,
    captured.object_version_hash,
    'g014-storage-' || pg_catalog.substr(p_request_id::text, 1, 8)
      || '-' || p_attempt_token::text
      || '-' || pg_catalog.substr(captured.object_locator_hash, 1, 40),
    v_mode,
    v_mode,
    p_source_manifest_hash
  FROM privacy_retention.account_deletion_storage_objects AS captured
  JOIN storage.objects AS object_row
    ON object_row.id = captured.object_id
   AND pg_catalog.to_jsonb(object_row) ->> 'version' = captured.object_version
  WHERE captured.request_id = p_request_id
    AND captured.object_locator_hash = v_attempt.storage_object_locator_hash
    AND captured.object_version_hash = v_attempt.storage_object_version_hash
    AND captured.object_id = v_attempt.storage_object_id
    AND captured.object_version = v_attempt.storage_object_version
    AND object_row.owner_id::text = p_target_user_id::text;
END;
$$;


--
-- Name: get_all_approved_restaurant_names(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_approved_restaurant_names() RETURNS TABLE(name text, categories text[])
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select
    r.approved_name as name,
    r.categories
  from restaurants r
  where r.status = 'approved'
  order by r.approved_name;
$$;


--
-- Name: get_approved_restaurants(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_approved_restaurants(limit_count integer DEFAULT 100, offset_count integer DEFAULT 0) RETURNS TABLE(id uuid, name text, phone text, lat numeric, lng numeric, categories text[], road_address text, jibun_address text, english_address text, youtube_links text[], tzuyang_reviews jsonb, review_count integer, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        r.id,
        r.name,
        r.phone,
        r.lat,
        r.lng,
        r.categories,
        r.road_address,
        r.jibun_address,
        r.english_address,
        r.youtube_links,
        r.tzuyang_reviews,
        r.review_count,
        r.created_at
    FROM public.restaurants r
    WHERE r.status = 'approved'
    ORDER BY r.created_at DESC
    LIMIT limit_count
    OFFSET offset_count;
END;
$$;


