-- Name: FUNCTION get_approved_restaurants(limit_count integer, offset_count integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_approved_restaurants(limit_count integer, offset_count integer) IS '승인된 맛집만 조회 (일반 사용자용)';


--
-- Name: get_categories_by_restaurant_name_or_youtube_url(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_categories_by_restaurant_name_or_youtube_url(p_restaurant_name text DEFAULT NULL::text, p_video_id text DEFAULT NULL::text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select array_agg(distinct c)
  from restaurants r, unnest(r.categories) as c
  where r.status = 'approved'
    and (p_restaurant_name is null or r.approved_name = p_restaurant_name)
    and (p_video_id is null or substring(r.youtube_link from 'v=([^&]+)') = p_video_id);
$$;


--
-- Name: get_current_auth_session_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_auth_session_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb := COALESCE(NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role text;
  v_user_id uuid;
  v_session_id uuid;
BEGIN
  v_role := COALESCE(NULLIF(v_claims ->> 'role', ''), pg_catalog.current_setting('request.jwt.claim.role', true), '');
  BEGIN
    v_user_id := NULLIF(COALESCE(NULLIF(v_claims ->> 'sub', ''), pg_catalog.current_setting('request.jwt.claim.sub', true)), '')::uuid;
    v_session_id := NULLIF(COALESCE(NULLIF(v_claims ->> 'session_id', ''), pg_catalog.current_setting('request.jwt.claim.session_id', true)), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN NULL;
  END;
  IF v_role <> 'authenticated' OR v_user_id IS NULL OR v_session_id IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN v_session_id;
END;
$$;


--
-- Name: get_current_privacy_eligibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_privacy_eligibility() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb := COALESCE(NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_role text;
  v_user_id uuid;
  v_receipt jsonb;
  v_policy_version text;
BEGIN
  v_role := COALESCE(NULLIF(v_claims ->> 'role', ''), pg_catalog.current_setting('request.jwt.claim.role', true), '');
  BEGIN
    v_user_id := NULLIF(COALESCE(NULLIF(v_claims ->> 'sub', ''), pg_catalog.current_setting('request.jwt.claim.sub', true)), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'privacy_authentication_required' USING ERRCODE = '42501';
  END;
  IF v_role <> 'authenticated' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'privacy_authentication_required' USING ERRCODE = '42501';
  END IF;

  v_receipt := privacy_retention.g014_privacy_eligibility_receipt(v_user_id);
  SELECT policy.version INTO v_policy_version
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.id = NULLIF(v_receipt ->> 'policyVersionId', '')::uuid;
  RETURN v_receipt || pg_catalog.jsonb_build_object('policyVersion', v_policy_version);
END;
$$;


--
-- Name: get_current_privacy_policy_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_privacy_policy_version() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  v_policy privacy_retention.privacy_policy_versions%ROWTYPE;
BEGIN
  v_role := COALESCE(
    NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    pg_catalog.current_setting('request.jwt.claim.role', true),
    ''
  );
  IF v_role NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION 'privacy_authentication_required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_policy
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.status = 'published'
    AND policy.effective_at <= pg_catalog.clock_timestamp()
  ORDER BY policy.effective_at DESC, policy.id DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'privacy_current_policy_unavailable' USING ERRCODE = 'P0002';
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'policyVersionId', v_policy.id::text,
    'version', v_policy.version,
    'locale', v_policy.locale,
    'contentSha256', v_policy.content_sha256,
    'effectiveAt', pg_catalog.to_char(v_policy.effective_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'publishedAt', pg_catalog.to_char(v_policy.published_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'approvalBound', pg_catalog.length(pg_catalog.btrim(v_policy.operator_approval_ref)) > 0
  );
END;
$$;


