--
-- Name: is_current_auth_session_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_current_auth_session_active() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb := COALESCE(NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  v_current_session_id uuid;
  v_current_user_id uuid;
  v_lease public.release_auth_session_leases%ROWTYPE;
BEGIN
  BEGIN
    v_current_user_id := NULLIF(COALESCE(NULLIF(v_claims ->> 'sub', ''), pg_catalog.current_setting('request.jwt.claim.sub', true)), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
  END;
  v_current_session_id := public.get_current_auth_session_id();
  IF v_current_session_id IS NULL OR v_current_user_id IS NULL THEN
    RETURN false;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.release_auth_identities AS identity
    WHERE identity.user_id = v_current_user_id
  ) THEN
    RETURN true;
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_current_session_id::text, 0));
  SELECT * INTO v_lease
  FROM public.release_auth_session_leases AS lease
  WHERE lease.user_id = v_current_user_id
    AND lease.session_id = v_current_session_id
  FOR UPDATE;
  RETURN FOUND AND v_lease.expires_at > pg_catalog.clock_timestamp();
END;
$$;


--
-- Name: is_current_user_active_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_current_user_active_admin() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT (SELECT auth.uid()) IS NOT NULL
     AND EXISTS (
       SELECT 1
         FROM public.user_roles AS role_row
         JOIN public.user_account_status AS status_row
           ON status_row.user_id = role_row.user_id
        WHERE role_row.user_id = (SELECT auth.uid())
          AND role_row.role::text = 'admin'
          AND status_row.account_status = 'active'
          AND status_row.disabled_at IS NULL
     )
$$;


--
-- Name: FUNCTION is_current_user_active_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_current_user_active_admin() IS 'Caller-bound active administrator predicate; accepts no arbitrary user identity.';


--
-- Name: is_marketing_night_window(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_marketing_night_window(p_scheduled_at timestamp with time zone, p_timezone text DEFAULT 'Asia/Seoul'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare v_local_time time;
begin
  if p_scheduled_at is null or p_timezone is null or not exists (select 1 from pg_timezone_names where name = p_timezone) then raise exception 'marketing_timezone_invalid'; end if;
  v_local_time := p_scheduled_at at time zone p_timezone;
  return v_local_time >= time '21:00' or v_local_time < time '08:00';
end; $$;


