--
-- Name: marketing_campaign_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_campaign_receipt(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_operation public.marketing_campaign_operations%ROWTYPE;
  v_requested integer := 0;
  v_sent integer := 0;
  v_suppressed integer := 0;
  v_failed integer := 0;
  v_unresolved integer := 0;
  v_rows integer := 0;
  v_notification_rows_expected integer := 0;
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'marketing_operation_required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_operation
  FROM public.marketing_campaign_operations AS operation
  WHERE operation.id = p_operation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'marketing_operation_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::integer,
         count(*) FILTER (
           WHERE recipient.status = 'suppressed'
             AND NOT EXISTS (
               SELECT 1
               FROM privacy_retention.marketing_campaign_batch_recipients AS batch_recipient
               WHERE batch_recipient.operation_id = p_operation_id
                 AND batch_recipient.user_id = recipient.user_id
                 AND batch_recipient.provider_accepted_at IS NOT NULL
             )
         )::integer,
         count(*) FILTER (WHERE recipient.status = 'failed')::integer,
         count(*) FILTER (WHERE recipient.status IN ('pending', 'eligible'))::integer
  INTO v_requested, v_suppressed, v_failed, v_unresolved
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id;
  SELECT count(*)::integer
    INTO v_sent
    FROM (
      SELECT DISTINCT accepted.user_id
      FROM privacy_retention.marketing_campaign_provider_attempts AS attempt
      CROSS JOIN LATERAL pg_catalog.unnest(
        COALESCE(attempt.accepted_recipient_ids, ARRAY[]::uuid[])
      ) AS accepted(user_id)
      WHERE attempt.operation_id = p_operation_id
        AND attempt.status = 'accepted'
    ) AS accepted;
  SELECT count(*)::integer INTO v_unresolved
  FROM (
    SELECT recipient.user_id
    FROM public.marketing_campaign_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id
      AND recipient.status IN ('pending', 'eligible')
    UNION
    SELECT recipient.user_id
    FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id
      AND recipient.status = 'claimed'
  ) AS unresolved;
  SELECT count(*)::integer INTO v_rows
  FROM public.notifications AS notification
  WHERE notification.campaign_operation_id = p_operation_id
    AND notification.classification = 'marketing';
  SELECT count(*)::integer
    INTO v_notification_rows_expected
    FROM privacy_retention.marketing_campaign_batch_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id
      AND recipient.notification_eligibility_outcome = 'notification_created';

  RETURN pg_catalog.jsonb_build_object(
    'operationId', v_operation.id::text,
    'status', v_operation.status,
    'auditId', CASE WHEN v_operation.audit_id IS NULL THEN NULL ELSE v_operation.audit_id::text END,
    'counts', pg_catalog.jsonb_build_object(
      'requested', COALESCE(v_requested, 0),
      'sent', COALESCE(v_sent, 0),
      'suppressed', COALESCE(v_suppressed, 0),
      'failed', COALESCE(v_failed, 0)
    ),
    'readback', pg_catalog.jsonb_build_object(
      'passed', v_operation.status IN ('applied', 'partial', 'failed')
        AND v_unresolved = 0
        AND v_rows = v_notification_rows_expected
        AND v_rows <= COALESCE(v_sent, 0),
      'notificationRows', COALESCE(v_rows, 0)
    )
  );
END;
$$;


--
-- Name: match_documents_bge(extensions.vector, double precision, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_documents_bge(query_embedding extensions.vector, match_threshold double precision, match_count integer, filter jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id bigint, video_id text, chunk_index integer, recollect_id integer, page_content text, metadata jsonb, embedding extensions.vector, similarity double precision)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
begin
  return query
  select
    t.id,
    t.video_id,
    t.chunk_index,
    t.recollect_id,
    t.page_content,
    t.metadata,
    t.embedding,
    1 - (t.embedding <=> query_embedding) as similarity
  from transcript_embeddings_bge as t
  where 1 - (t.embedding <=> query_embedding) > match_threshold
  order by t.embedding <=> query_embedding
  limit match_count;
end;
$$;


--
-- Name: match_documents_hybrid(extensions.vector, jsonb, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_documents_hybrid(query_embedding extensions.vector, query_sparse jsonb, dense_weight double precision DEFAULT 0.6, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 20) RETURNS TABLE(id bigint, video_id text, chunk_index integer, recollect_id integer, page_content text, metadata jsonb, embedding extensions.vector, dense_score double precision, sparse_score double precision, hybrid_score double precision)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
#variable_conflict use_column
begin
  return query
  with 
  -- [Step 1] 벡터 검색으로 후보군 넉넉하게 추출 (인덱스 활용)
  candidates as (
    select
      teb.id, teb.video_id, teb.chunk_index, teb.recollect_id,
      teb.page_content, teb.metadata, teb.embedding, teb.sparse_embedding,
      1 - (teb.embedding <=> query_embedding) as dense_score
    from transcript_embeddings_bge teb
    where 1 - (teb.embedding <=> query_embedding) > match_threshold
    order by teb.embedding <=> query_embedding
    limit match_count * 5 -- 후보군 여유있게 (중복 및 구버전 필터링 대비)
  ),
  
  -- [Step 2] 최신 버전 필터링 (Subquery)
  -- 1차로 뽑힌 후보군에 대해서만 최신 버전인지 검증
  valid_candidates as (
    select c.*
    from candidates c
    where c.recollect_id = (
        select max(recollect_id) 
        from transcript_embeddings_bge 
        where video_id = c.video_id
    )
  ),

  -- [Step 3] Sparse 점수 계산 및 Hybrid 점수 산출
  scored as (
    select 
      vc.id, vc.video_id, vc.chunk_index, vc.recollect_id,
      vc.page_content, vc.metadata, vc.embedding,
      vc.dense_score,
      coalesce(
        (select sum((vc.sparse_embedding->>k)::float * (query_sparse->>k)::float)
         from jsonb_object_keys(query_sparse) k
         where vc.sparse_embedding ? k), 0
      ) as sparse_score
    from valid_candidates vc
  )
  
  -- [Step 4] 최종 점수 합산 및 반환
  select 
    s.id, s.video_id, s.chunk_index, s.recollect_id,
    s.page_content, s.metadata, s.embedding,
    s.dense_score::float,
    s.sparse_score::float,
    (s.dense_score * dense_weight + s.sparse_score * (1 - dense_weight))::float as hybrid_score
  from scored s
  order by hybrid_score desc
  limit match_count;
end;
$$;


--
-- Name: match_storyboard_documents_hybrid(uuid, extensions.vector, jsonb, double precision, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_storyboard_documents_hybrid(p_user_id uuid, p_query_embedding extensions.vector, p_query_sparse jsonb, p_dense_weight double precision DEFAULT 0.65, p_match_count integer DEFAULT 10, p_candidate_count integer DEFAULT 50, p_metadata_filter jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id uuid, title text, content text, metadata jsonb, dense_score double precision, sparse_score double precision, rrf_score double precision, weighted_score double precision)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
begin
  if p_user_id is null then
    raise exception 'p_user_id is required';
  end if;
  if p_match_count < 1 or p_match_count > 50 then
    raise exception 'p_match_count must be between 1 and 50';
  end if;
  if p_candidate_count < p_match_count or p_candidate_count > 200 then
    raise exception 'p_candidate_count must be between p_match_count and 200';
  end if;
  if jsonb_typeof(p_metadata_filter) is distinct from 'object' then
    raise exception 'p_metadata_filter must be a JSON object';
  end if;

  return query
  with dense_candidates as (
    select
      d.id,
      1 - (d.embedding <=> p_query_embedding) as dense_score,
      row_number() over (order by d.embedding <=> p_query_embedding) as dense_rank
    from public.documents d
    where d.user_id = p_user_id
      and d.metadata @> p_metadata_filter
    order by d.embedding <=> p_query_embedding
    limit p_candidate_count
  ),
  sparse_candidates as (
    select
      d.id,
      public.storyboard_sparse_dot_product(d.sparse_lexical_weights, p_query_sparse) as sparse_score,
      row_number() over (
        order by public.storyboard_sparse_dot_product(d.sparse_lexical_weights, p_query_sparse) desc
      ) as sparse_rank
    from public.documents d
    where d.user_id = p_user_id
      and d.metadata @> p_metadata_filter
      and jsonb_typeof(p_query_sparse) = 'object'
      and p_query_sparse <> '{}'::jsonb
    order by sparse_score desc
    limit p_candidate_count
  ),
  fused as (
    select
      coalesce(dc.id, sc.id) as id,
      coalesce(dc.dense_score, 0.0) as dense_score,
      coalesce(sc.sparse_score, 0.0) as sparse_score,
      (coalesce(1.0 / (60 + dc.dense_rank), 0.0) + coalesce(1.0 / (60 + sc.sparse_rank), 0.0))::double precision as rrf_score
    from dense_candidates dc
    full outer join sparse_candidates sc on sc.id = dc.id
  )
  select
    d.id,
    d.title,
    d.content,
    d.metadata,
    f.dense_score,
    f.sparse_score,
    f.rrf_score,
    ((f.dense_score * p_dense_weight) + (f.sparse_score * (1.0 - p_dense_weight)) + f.rrf_score)::double precision as weighted_score
  from fused f
  join public.documents d on d.id = f.id
  where d.user_id = p_user_id
    and d.metadata @> p_metadata_filter
  order by weighted_score desc
  limit p_match_count;
end;
$$;


--
-- Name: match_storyboard_documents_hybrid_v2(uuid, extensions.vector, jsonb, double precision, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_storyboard_documents_hybrid_v2(p_user_id uuid, p_query_embedding extensions.vector, p_query_sparse jsonb, p_dense_weight double precision DEFAULT 0.65, p_match_count integer DEFAULT 10, p_candidate_count integer DEFAULT 50, p_metadata_filter jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id uuid, title text, content text, metadata jsonb, dense_score double precision, sparse_score double precision, rrf_score double precision, weighted_score double precision)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
begin
  if p_user_id is null then
    raise exception 'p_user_id is required';
  end if;
  if p_match_count < 1 or p_match_count > 50 then
    raise exception 'p_match_count must be between 1 and 50';
  end if;
  if p_candidate_count < p_match_count or p_candidate_count > 200 then
    raise exception 'p_candidate_count must be between p_match_count and 200';
  end if;
  if jsonb_typeof(p_metadata_filter) is distinct from 'object' then
    raise exception 'p_metadata_filter must be a JSON object';
  end if;
  if jsonb_typeof(p_query_sparse) is not null and jsonb_typeof(p_query_sparse) <> 'object' then
    raise exception 'p_query_sparse must be a JSON object';
  end if;

  return query
  with query_terms as (
    select array_agg(key) as keys
    from jsonb_object_keys(coalesce(p_query_sparse, '{}'::jsonb)) as key
  ),
  dense_candidates as (
    select
      d.id,
      1 - (d.embedding <=> p_query_embedding) as dense_score,
      row_number() over (order by d.embedding <=> p_query_embedding) as dense_rank
    from public.documents d
    where d.user_id = p_user_id
      and d.metadata @> p_metadata_filter
    order by d.embedding <=> p_query_embedding
    limit p_candidate_count
  ),
  sparse_candidates as (
    select
      d.id,
      public.storyboard_sparse_dot_product(d.sparse_lexical_weights, p_query_sparse) as sparse_score,
      row_number() over (
        order by public.storyboard_sparse_dot_product(d.sparse_lexical_weights, p_query_sparse) desc
      ) as sparse_rank
    from public.documents d
    cross join query_terms qt
    where d.user_id = p_user_id
      and d.metadata @> p_metadata_filter
      and coalesce(array_length(qt.keys, 1), 0) > 0
      and d.sparse_lexical_weights ?| qt.keys
    order by sparse_score desc
    limit p_candidate_count
  ),
  fused as (
    select
      coalesce(dc.id, sc.id) as id,
      coalesce(dc.dense_score, 0.0) as dense_score,
      coalesce(sc.sparse_score, 0.0) as sparse_score,
      (coalesce(1.0 / (60 + dc.dense_rank), 0.0) + coalesce(1.0 / (60 + sc.sparse_rank), 0.0))::double precision as rrf_score
    from dense_candidates dc
    full outer join sparse_candidates sc on sc.id = dc.id
  )
  select
    d.id,
    d.title,
    d.content,
    d.metadata,
    f.dense_score,
    f.sparse_score,
    f.rrf_score,
    ((f.dense_score * p_dense_weight) + (f.sparse_score * (1.0 - p_dense_weight)) + f.rrf_score)::double precision as weighted_score
  from fused f
  join public.documents d on d.id = f.id
  where d.user_id = p_user_id
    and d.metadata @> p_metadata_filter
  order by weighted_score desc
  limit p_match_count;
end;
$$;


--
-- Name: FUNCTION match_storyboard_documents_hybrid_v2(p_user_id uuid, p_query_embedding extensions.vector, p_query_sparse jsonb, p_dense_weight double precision, p_match_count integer, p_candidate_count integer, p_metadata_filter jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.match_storyboard_documents_hybrid_v2(p_user_id uuid, p_query_embedding extensions.vector, p_query_sparse jsonb, p_dense_weight double precision, p_match_count integer, p_candidate_count integer, p_metadata_filter jsonb) IS 'Storyboard RAG hybrid v2: keeps dense HNSW path and prefilters sparse JSONB candidates with ?| keys before sparse dot product.';


--
-- Name: merge_restaurant_records_for_admin_review(uuid, uuid, uuid, timestamp with time zone, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_restaurant_records_for_admin_review(p_target_restaurant_id uuid, p_source_restaurant_id uuid, p_admin_user_id uuid, p_expected_target_updated_at timestamp with time zone, p_new_youtube_link text DEFAULT NULL::text, p_new_youtube_meta jsonb DEFAULT NULL::jsonb, p_new_tzuyang_review text DEFAULT NULL::text, p_new_category text DEFAULT NULL::text) RETURNS TABLE(success boolean, message text, target_restaurant_id uuid, source_restaurant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_admin boolean;
  v_role text;
  v_now timestamptz := now();
  v_target_restaurant public.restaurants%rowtype;
  v_source_restaurant public.restaurants%rowtype;
  v_target_categories text[];
  v_updated_youtube_link text;
  v_updated_youtube_meta jsonb;
  v_updated_tzuyang_review text;
  v_new_category text := nullif(p_new_category, '');
begin
  v_role := current_setting('request.jwt.claim.role', true);
  if v_role is distinct from 'service_role' then
    if privacy_retention.g041_current_claim_user_id() is null or privacy_retention.g041_current_claim_user_id() <> p_admin_user_id then
      return query select false, '관리자 인증 정보가 일치하지 않습니다.'::text, null::uuid, null::uuid;
      return;
    end if;
  end if;

  select public.is_user_admin(p_admin_user_id) into v_is_admin;
  if not v_is_admin then
    return query select false, '관리자 권한이 필요합니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  if p_target_restaurant_id is null or p_source_restaurant_id is null then
    return query select false, '병합 대상과 원본 레스토랑 정보가 필요합니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  if p_target_restaurant_id = p_source_restaurant_id then
    return query select false, '병합 대상과 원본 레스토랑이 동일합니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  if p_expected_target_updated_at is null then
    return query select false, '병합 대상 레스토랑의 최신 수정 시각이 필요합니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  select *
  into v_target_restaurant
  from public.restaurants
  where id = p_target_restaurant_id
  for update;

  if not found then
    return query select false, '병합 대상 레스토랑을 찾을 수 없습니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  select *
  into v_source_restaurant
  from public.restaurants
  where id = p_source_restaurant_id
  for update;

  if not found then
    return query select false, '병합 원본 레스토랑을 찾을 수 없습니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  if v_source_restaurant.status = 'deleted' then
    return query select false, '이미 처리된 레코드입니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  if v_target_restaurant.updated_at is distinct from p_expected_target_updated_at then
    return query select false, '다른 관리자가 이미 데이터를 수정했습니다. 다시 시도해주세요.'::text, null::uuid, null::uuid;
    return;
  end if;

  v_updated_youtube_link := coalesce(
    nullif(v_target_restaurant.youtube_link, ''),
    nullif(p_new_youtube_link, '')
  );
  v_updated_youtube_meta := coalesce(v_target_restaurant.youtube_meta, p_new_youtube_meta);
  v_updated_tzuyang_review := coalesce(
    nullif(v_target_restaurant.tzuyang_review, ''),
    nullif(p_new_tzuyang_review, '')
  );
  v_target_categories := v_target_restaurant.categories;

  if v_new_category is not null then
    if v_target_categories is null then
      v_target_categories := array[v_new_category];
    elsif not (v_new_category = any(v_target_categories)) then
      v_target_categories := array_append(v_target_categories, v_new_category);
    end if;
  end if;

  update public.restaurants
  set
    youtube_link = v_updated_youtube_link,
    youtube_meta = v_updated_youtube_meta,
    tzuyang_review = v_updated_tzuyang_review,
    categories = v_target_categories,
    updated_by_admin_id = p_admin_user_id,
    updated_at = v_now
  where id = p_target_restaurant_id;

  if not found then
    return query select false, '병합 대상 업데이트에 실패했습니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  update public.restaurants
  set
    status = 'deleted',
    updated_by_admin_id = p_admin_user_id,
    updated_at = v_now,
    db_error_message = null,
    db_error_details = null
  where id = p_source_restaurant_id;

  if not found then
    return query select false, '원본 레코드 상태 업데이트에 실패했습니다.'::text, null::uuid, null::uuid;
    return;
  end if;

  return query select true, '병합이 완료되었습니다.'::text, p_target_restaurant_id, p_source_restaurant_id;
end;
$$;


--
-- Name: mutate_review_with_media(uuid, uuid, text, timestamp with time zone, text, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mutate_review_with_media(p_operation_id uuid, p_review_id uuid, p_kind text, p_expected_updated_at timestamp with time zone, p_content text DEFAULT NULL::text, p_categories text[] DEFAULT NULL::text[], p_food_photos text[] DEFAULT NULL::text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u uuid := privacy_retention.g041_current_claim_user_id(); r public.reviews%ROWTYPE;
  receipt review_media_private.commits%ROWTYPE; h text; p text;
BEGIN
  IF u IS NULL THEN RETURN 'REVIEW_UNAUTHORIZED'; END IF;
  IF p_operation_id IS NULL OR p_review_id IS NULL OR p_kind IS NULL OR p_kind NOT IN ('edit','delete') THEN
    RETURN 'REVIEW_INVALID';
  END IF;
  -- Bound client-controlled work before hashing or acquiring the shared lock.
  -- These generous transport ceilings do not trim stored or submitted text.
  IF p_kind = 'delete' AND (p_content IS NOT NULL OR p_categories IS NOT NULL OR p_food_photos IS NOT NULL) THEN
    RETURN 'REVIEW_INVALID';
  END IF;
  IF p_kind = 'edit' THEN
    IF p_content IS NULL OR octet_length(p_content) > 262144 OR length(btrim(p_content)) < 20
      OR p_categories IS NULL OR cardinality(p_categories) NOT BETWEEN 1 AND 100
      OR p_food_photos IS NULL OR cardinality(p_food_photos) NOT BETWEEN 1 AND 10 THEN
      RETURN 'REVIEW_INVALID';
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(p_categories) value WHERE value IS NULL OR length(value) NOT BETWEEN 1 AND 200)
      OR EXISTS (SELECT 1 FROM unnest(p_food_photos) value WHERE value IS NULL OR octet_length(value) > 8192) THEN
      RETURN 'REVIEW_INVALID';
    END IF;
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN RETURN 'REVIEW_RETRY_REQUIRED'; END IF;
  h := encode(sha256(convert_to(jsonb_build_array(p_review_id, p_kind, p_expected_updated_at,
    p_content, p_categories, p_food_photos)::text, 'UTF8')), 'hex');
  LOCK TABLE public.reviews IN ROW EXCLUSIVE MODE;
  PERFORM pg_advisory_xact_lock(741093, 1);
  SELECT * INTO receipt FROM review_media_private.commits WHERE operation_id = p_operation_id;
  IF FOUND THEN
    IF receipt.owner_id = u AND receipt.review_id = p_review_id AND receipt.kind = p_kind AND receipt.request_hash = h THEN
      RETURN 'REVIEW_COMMITTED';
    END IF;
    RETURN 'REVIEW_CONFLICT';
  END IF;
  SELECT * INTO r FROM public.reviews WHERE id = p_review_id AND user_id = u FOR UPDATE;
  IF NOT FOUND THEN RETURN 'REVIEW_NOT_FOUND'; END IF;
  IF p_expected_updated_at IS NULL OR r.updated_at IS DISTINCT FROM p_expected_updated_at THEN RETURN 'REVIEW_CONFLICT'; END IF;
  IF p_kind = 'edit' THEN
    IF p_content IS NULL OR length(btrim(p_content)) < 20 OR p_categories IS NULL OR cardinality(p_categories) = 0
      OR p_food_photos IS NULL OR cardinality(p_food_photos) NOT BETWEEN 1 AND 10 THEN RETURN 'REVIEW_INVALID'; END IF;
    FOREACH p IN ARRAY p_food_photos LOOP
      -- The submitted list is the complete desired state. Historical display
      -- values can only be kept verbatim from this row or omitted, never added.
      IF p = ANY(COALESCE(r.food_photos, ARRAY[]::text[]))
        AND NOT review_media_private.canonical(p, u, r.id, 'food')
        AND NOT review_media_private.owned_legacy(p, u, 'food') THEN CONTINUE; END IF;
      IF NOT review_media_private.canonical(p, u, r.id, 'food')
        AND NOT (review_media_private.owned_legacy(p, u, 'food') AND p = ANY(COALESCE(r.food_photos, ARRAY[]::text[]))) THEN
        RETURN 'REVIEW_INVALID';
      END IF;
      IF NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id = 'review-photos' AND name = p) THEN
        RETURN 'REVIEW_MEDIA_MISSING';
      END IF;
    END LOOP;
    UPDATE public.reviews SET content = btrim(p_content), categories = p_categories,
      food_photos = p_food_photos,
      is_verified = false, admin_note = NULL, updated_at = clock_timestamp()
      WHERE id = r.id AND user_id = u;
  ELSE
    DELETE FROM public.reviews WHERE id = r.id AND user_id = u;
  END IF;
  -- The AFTER trigger queues the authoritative pre-image in this transaction.
  INSERT INTO review_media_private.commits VALUES (p_operation_id, u, r.id, p_kind, h);
  RETURN 'REVIEW_COMMITTED';
END $$;


--
-- Name: normalize_restaurant_identity_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_restaurant_identity_name(raw_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select nullif(regexp_replace(lower(btrim(coalesce(raw_name, ''))), '\s+', ' ', 'g'), '');
$$;


--
-- Name: ocr_log_metadata_is_safe(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ocr_log_metadata_is_safe(p_metadata jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT
    pg_catalog.jsonb_typeof(p_metadata) = 'object'
    AND NOT EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_object_keys(p_metadata) AS key_name
      WHERE key_name <> ALL (ARRAY[
        'file_size',
        'compressed_size',
        'savings',
        'store_found',
        'provider',
        'model',
        'prompt_version',
        'preprocess_version',
        'extraction_schema_version',
        'routing_mode',
        'normalization_version',
        'fallback_used',
        'force_refresh',
        'attempt_count',
        'confidence',
        'needs_review',
        'restaurant_lookup',
        'error_code'
      ]::text[])
    )
    AND (NOT (p_metadata ? 'file_size') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'file_size') = 'number'
      AND (p_metadata ->> 'file_size')::numeric >= 0
    ))
    AND (NOT (p_metadata ? 'compressed_size') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'compressed_size') = 'number'
      AND (p_metadata ->> 'compressed_size')::numeric >= 0
    ))
    AND (NOT (p_metadata ? 'attempt_count') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'attempt_count') = 'number'
      AND (p_metadata ->> 'attempt_count')::numeric >= 0
      AND (p_metadata ->> 'attempt_count')::numeric <= 100
    ))
    AND (NOT (p_metadata ? 'confidence') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'confidence') = 'number'
      AND (p_metadata ->> 'confidence')::numeric BETWEEN 0 AND 1
    ))
    AND (NOT (p_metadata ? 'store_found') OR pg_catalog.jsonb_typeof(p_metadata -> 'store_found') = 'boolean')
    AND (NOT (p_metadata ? 'fallback_used') OR pg_catalog.jsonb_typeof(p_metadata -> 'fallback_used') = 'boolean')
    AND (NOT (p_metadata ? 'force_refresh') OR pg_catalog.jsonb_typeof(p_metadata -> 'force_refresh') = 'boolean')
    AND (NOT (p_metadata ? 'savings') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'savings') = 'string'
      AND pg_catalog.length(p_metadata ->> 'savings') BETWEEN 1 AND 16
      AND (p_metadata ->> 'savings') ~ '^[0-9]{1,3}%$'
    ))
    AND NOT EXISTS (
      SELECT 1
      FROM pg_catalog.unnest(ARRAY[
        'provider',
        'model',
        'prompt_version',
        'preprocess_version',
        'extraction_schema_version',
        'routing_mode',
        'normalization_version'
      ]::text[]) AS field_name
      WHERE p_metadata ? field_name
        AND (
          pg_catalog.jsonb_typeof(p_metadata -> field_name) <> 'string'
          OR pg_catalog.length(p_metadata ->> field_name) NOT BETWEEN 1 AND 128
          OR (p_metadata ->> field_name) !~ '^[A-Za-z0-9._:/-]+$'
        )
    )
    AND (NOT (p_metadata ? 'error_code') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'error_code') = 'string'
      AND pg_catalog.length(p_metadata ->> 'error_code') BETWEEN 1 AND 64
      AND (p_metadata ->> 'error_code') ~ '^[A-Z0-9_]+$'
    ))
    AND (NOT (p_metadata ? 'needs_review') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'needs_review') = 'array'
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements_text(p_metadata -> 'needs_review') AS review_field
        WHERE review_field <> ALL (ARRAY[
          'store_name',
          'restaurant_id',
          'date',
          'time',
          'total_amount',
          'items',
          'category',
          'review_draft'
        ]::text[])
      )
    ))
    AND (NOT (p_metadata ? 'restaurant_lookup') OR (
      pg_catalog.jsonb_typeof(p_metadata -> 'restaurant_lookup') = 'object'
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_object_keys(p_metadata -> 'restaurant_lookup') AS lookup_key
        WHERE lookup_key <> ALL (ARRAY['lookupCount', 'lookupLimit', 'stoppedByBudget']::text[])
      )
      AND pg_catalog.jsonb_typeof(p_metadata #> '{restaurant_lookup,lookupCount}') = 'number'
      AND pg_catalog.jsonb_typeof(p_metadata #> '{restaurant_lookup,lookupLimit}') = 'number'
      AND pg_catalog.jsonb_typeof(p_metadata #> '{restaurant_lookup,stoppedByBudget}') = 'boolean'
      AND (p_metadata #>> '{restaurant_lookup,lookupCount}')::numeric >= 0
      AND (p_metadata #>> '{restaurant_lookup,lookupLimit}')::numeric >= 0
    ));
$_$;


--
-- Name: FUNCTION ocr_log_metadata_is_safe(p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ocr_log_metadata_is_safe(p_metadata jsonb) IS 'G010 exact allowlist for privacy-minimized OCR usage metadata; rejects raw OCR, provider diagnostics, credential sources, and arbitrary payloads.';


--
-- Name: pending_review_media_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_review_media_cleanup() RETURNS TABLE(path text, owner_id uuid, review_id uuid, purpose text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF privacy_retention.g041_current_claim_user_id() IS NULL OR current_setting('transaction_isolation') <> 'read committed' THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(741093, 1);
  UPDATE review_media_private.cleanup c SET retired = true
    WHERE c.owner_id = privacy_retention.g041_current_claim_user_id() AND NOT c.retired AND NOT review_media_private.referenced(c.path);
  RETURN QUERY SELECT c.path, c.owner_id, c.review_id, c.purpose FROM review_media_private.cleanup c
    WHERE c.owner_id = privacy_retention.g041_current_claim_user_id() AND c.retired AND NOT c.complete
      AND NOT review_media_private.referenced(c.path) ORDER BY c.path LIMIT 20;
END $$;


--
-- Name: preflight_release_auth_session_family(uuid, uuid, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preflight_release_auth_session_family(p_operation_id uuid, p_user_id uuid, p_session_id uuid, p_refresh_sha256 text, p_expires_at bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE enabled_count bigint; enabled_user_id uuid; matching_refresh_count bigint; lease public.release_auth_session_leases%ROWTYPE; lease_expiry timestamptz; now_timestamp timestamptz := pg_catalog.clock_timestamp(); reclaimed_refresh_count bigint := 0; reclaimed_session_count integer := 0; reclaimed_timestamp timestamptz;
BEGIN
  IF COALESCE(NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', pg_catalog.current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE = '42501'; END IF;
  IF p_operation_id IS NULL OR p_user_id IS NULL OR p_session_id IS NULL OR p_refresh_sha256 !~ '^[0-9a-f]{64}$' OR p_expires_at IS NULL OR p_expires_at <= EXTRACT(EPOCH FROM now_timestamp) OR p_expires_at - EXTRACT(EPOCH FROM now_timestamp) > 900 THEN RAISE EXCEPTION 'operation, bound identity, refresh digest, and bounded expiry are required' USING ERRCODE = '22023'; END IF;
  lease_expiry := pg_catalog.to_timestamp(p_expires_at);
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_session_id::text, 0));
  SELECT * INTO lease FROM public.release_auth_session_leases l WHERE l.operation_id = p_operation_id FOR UPDATE;
  IF FOUND THEN
    IF lease.user_id IS DISTINCT FROM p_user_id OR lease.session_id IS DISTINCT FROM p_session_id OR lease.refresh_sha256 IS DISTINCT FROM p_refresh_sha256 OR lease.expires_at IS DISTINCT FROM lease_expiry THEN RAISE EXCEPTION 'operation lease mismatch' USING ERRCODE = '23505'; END IF;
    IF lease.expires_at <= now_timestamp OR NOT EXISTS (SELECT 1 FROM privacy_retention.g041_auth_sessions s WHERE s.id = p_session_id AND s.user_id = p_user_id) OR (SELECT count(*) FROM privacy_retention.g041_auth_refresh_tokens r WHERE r.session_id = p_session_id AND pg_catalog.encode(extensions.digest('tzudong:release-auth-refresh-binding:v1' || pg_catalog.chr(10) || r.token, 'sha256'), 'hex') = p_refresh_sha256) <> 1 THEN RAISE EXCEPTION 'release lease is no longer bound' USING ERRCODE = 'P0002'; END IF;
    RETURN pg_catalog.jsonb_build_object('schemaVersion', 2, 'status', 'compatible_bound', 'dedicatedIdentity', true, 'sessionBound', true, 'refreshBound', true, 'leaseActive', true, 'operationId', p_operation_id::text, 'expiresAt', p_expires_at);
  END IF;
  SELECT * INTO lease FROM public.release_auth_session_leases l WHERE l.user_id = p_user_id AND l.session_id = p_session_id FOR UPDATE;
  IF FOUND THEN
    IF lease.expires_at > now_timestamp THEN RAISE EXCEPTION 'session lease conflict' USING ERRCODE = '23505'; END IF;
    DELETE FROM privacy_retention.g041_auth_refresh_tokens r WHERE r.session_id = p_session_id; GET DIAGNOSTICS reclaimed_refresh_count = ROW_COUNT;
    DELETE FROM privacy_retention.g041_auth_sessions s WHERE s.id = p_session_id AND s.user_id = p_user_id; GET DIAGNOSTICS reclaimed_session_count = ROW_COUNT;
    IF EXISTS (SELECT 1 FROM privacy_retention.g041_auth_sessions s WHERE s.id = p_session_id) OR EXISTS (SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens r WHERE r.session_id = p_session_id) THEN RAISE EXCEPTION 'expired release lease reclamation verification failed' USING ERRCODE = '55000'; END IF;
    reclaimed_timestamp := pg_catalog.date_trunc('milliseconds', pg_catalog.clock_timestamp());
    INSERT INTO public.release_auth_revocation_receipts (operation_id, user_id, session_id, binding_sha256, status, refresh_tokens_deleted, sessions_deleted, revoked_at) VALUES (lease.operation_id, lease.user_id, lease.session_id, lease.refresh_sha256, 'expired_reclaimed', reclaimed_refresh_count, reclaimed_session_count, reclaimed_timestamp);
    DELETE FROM public.release_auth_session_leases l WHERE l.operation_id = lease.operation_id AND l.user_id = lease.user_id AND l.session_id = lease.session_id;
    IF EXISTS (SELECT 1 FROM public.release_auth_session_leases l WHERE l.operation_id = lease.operation_id) THEN RAISE EXCEPTION 'expired release lease reclamation closure failed' USING ERRCODE = '55000'; END IF;
    RETURN pg_catalog.jsonb_build_object('schemaVersion', 2, 'status', 'expired_reclaimed', 'dedicatedIdentity', false, 'sessionBound', false, 'refreshBound', false, 'leaseActive', false, 'operationId', p_operation_id::text, 'expiresAt', p_expires_at);
  END IF;
  SELECT count(*) INTO enabled_count FROM public.release_auth_identities WHERE enabled;
  SELECT user_id INTO enabled_user_id FROM public.release_auth_identities WHERE enabled ORDER BY user_id LIMIT 1;
  IF enabled_count <> 1 OR enabled_user_id IS DISTINCT FROM p_user_id THEN RAISE EXCEPTION 'dedicated release identity mismatch' USING ERRCODE = '42501'; END IF;
  PERFORM 1 FROM privacy_retention.g041_auth_sessions s WHERE s.id = p_session_id AND s.user_id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'release session binding mismatch' USING ERRCODE = 'P0002'; END IF;
  SELECT count(*) INTO matching_refresh_count FROM privacy_retention.g041_auth_refresh_tokens r WHERE r.session_id = p_session_id AND pg_catalog.encode(extensions.digest('tzudong:release-auth-refresh-binding:v1' || pg_catalog.chr(10) || r.token, 'sha256'), 'hex') = p_refresh_sha256;
  IF matching_refresh_count <> 1 THEN RAISE EXCEPTION 'release refresh binding mismatch' USING ERRCODE = 'P0002'; END IF;
  INSERT INTO public.release_auth_session_leases (operation_id, user_id, session_id, refresh_sha256, expires_at) VALUES (p_operation_id, p_user_id, p_session_id, p_refresh_sha256, lease_expiry);
  RETURN pg_catalog.jsonb_build_object('schemaVersion', 2, 'status', 'compatible_bound', 'dedicatedIdentity', true, 'sessionBound', true, 'refreshBound', true, 'leaseActive', true, 'operationId', p_operation_id::text, 'expiresAt', p_expires_at);
END;
$_$;


--
-- Name: prepare_account_deletion_external_egress(uuid, uuid, uuid, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_account_deletion_external_egress(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_phase text, p_attempt_token uuid) RETURNS TABLE(request_id uuid, phase text, attempt_token uuid, egress_state text, provider_idempotency_key text, lease_expires_at timestamp with time zone, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_attempt privacy_retention.account_deletion_external_job_attempts%ROWTYPE;
  v_key text;
  v_absent boolean;
  v_missing_proof_count integer;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_assert_external_job_binding(
    p_actor_user_id, p_target_user_id, p_request_id, p_preview_hash,
    p_idempotency_key, p_source_manifest_hash, p_phase, p_attempt_token, true
  );
  SELECT * INTO v_attempt
  FROM privacy_retention.account_deletion_external_job_attempts
  WHERE attempt_token = p_attempt_token
  FOR UPDATE;
  IF v_attempt.state IS DISTINCT FROM 'leased' THEN
    RAISE EXCEPTION 'account_deletion_external_egress_already_prepared'
      USING ERRCODE = '55000';
  END IF;

  IF p_phase = 'auth' THEN
    SELECT NOT EXISTS (
      SELECT 1 FROM privacy_retention.g041_auth_users WHERE id = p_target_user_id
      UNION ALL SELECT 1 FROM privacy_retention.g041_auth_sessions WHERE user_id = p_target_user_id
      UNION ALL SELECT 1 FROM privacy_retention.g041_auth_identities WHERE user_id = p_target_user_id
      UNION ALL SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens WHERE user_id = p_target_user_id
    ) INTO v_absent;
    IF v_absent THEN
      PERFORM privacy_retention.g014_account_deletion_complete_external_job_phase(
        p_request_id, 'auth', p_attempt_token
      );
      RETURN QUERY SELECT p_request_id, p_phase, p_attempt_token, 'authoritative_absent',
        NULL::text, v_attempt.lease_expires_at, p_source_manifest_hash;
      RETURN;
    END IF;
  ELSIF p_phase = 'storage' AND v_attempt.storage_object_locator_hash IS NULL THEN
    SELECT NOT EXISTS (
      SELECT 1 FROM storage.objects WHERE owner_id::text = p_target_user_id::text
    ) INTO v_absent;
    SELECT count(*) INTO v_missing_proof_count
    FROM privacy_retention.account_deletion_storage_objects AS captured
    WHERE captured.request_id = p_request_id
      AND NOT EXISTS (
        SELECT 1
        FROM privacy_retention.account_deletion_external_job_provider_proofs AS proof
        WHERE proof.request_id = p_request_id
          AND proof.phase = 'storage'
          AND proof.object_locator_hash = captured.object_locator_hash
          AND proof.object_version_hash = captured.object_version_hash
          AND proof.object_id = captured.object_id
          AND proof.object_version = captured.object_version
      );
    IF v_absent AND v_missing_proof_count = 0 THEN
      PERFORM privacy_retention.g014_account_deletion_complete_external_job_phase(
        p_request_id, 'storage', p_attempt_token
      );
      RETURN QUERY SELECT p_request_id, p_phase, p_attempt_token, 'authoritative_absent',
        NULL::text, v_attempt.lease_expires_at, p_source_manifest_hash;
      RETURN;
    END IF;
    RAISE EXCEPTION 'account_deletion_storage_reconciliation_required'
      USING ERRCODE = '55000';
  ELSIF p_phase = 'storage' AND NOT EXISTS (
    SELECT 1
    FROM privacy_retention.account_deletion_storage_objects AS captured
    JOIN storage.objects AS object_row
      ON object_row.id = captured.object_id
     AND pg_catalog.to_jsonb(object_row) ->> 'version' = captured.object_version
    WHERE captured.request_id = p_request_id
      AND captured.object_locator_hash = v_attempt.storage_object_locator_hash
      AND captured.object_version_hash = v_attempt.storage_object_version_hash
      AND captured.object_id = v_attempt.storage_object_id
      AND captured.object_version = v_attempt.storage_object_version
      AND object_row.owner_id::text = p_target_user_id::text
  ) THEN
    RAISE EXCEPTION 'account_deletion_storage_attempt_exact_binding_stale'
      USING ERRCODE = '55000';
  END IF;

  v_key := CASE p_phase
    WHEN 'storage' THEN
      'g014-storage-' || pg_catalog.substr(p_request_id::text, 1, 8)
      || '-' || p_attempt_token::text
      || '-' || pg_catalog.substr(v_attempt.storage_object_locator_hash, 1, 40)
    WHEN 'auth' THEN
      'g014-auth-' || pg_catalog.substr(p_request_id::text, 1, 8) || '-' || p_attempt_token::text
    ELSE 'g014-session-' || pg_catalog.substr(p_request_id::text, 1, 8) || '-' || p_attempt_token::text
  END;

  UPDATE privacy_retention.account_deletion_external_job_attempts
  SET state = 'egress_unknown', unknown_outcome_at = pg_catalog.clock_timestamp()
  WHERE attempt_token = p_attempt_token;
  UPDATE privacy_retention.account_deletion_external_jobs
  SET state = 'egress_unknown', updated_at = pg_catalog.clock_timestamp()
  WHERE request_id = p_request_id AND phase = p_phase;
  INSERT INTO privacy_retention.account_deletion_external_job_checkpoints (
    request_id, phase, attempt_token, checkpoint_kind, checkpoint_state, proof_hash
  ) VALUES (
    p_request_id, p_phase, p_attempt_token, 'egress_unknown', 'unknown',
    pg_catalog.encode(
      extensions.digest(
        pg_catalog.concat_ws(
          ':',
          'g014-egress-unknown:v4',
          p_request_id::text,
          p_phase,
          p_attempt_token::text,
          COALESCE(v_attempt.storage_object_locator_hash, '<none>'),
          COALESCE(v_attempt.storage_object_version_hash, '<none>'),
          COALESCE(v_attempt.storage_object_id::text, '<none>'),
          COALESCE(v_attempt.storage_object_version, '<none>')
        ),
        'sha256'
      ),
      'hex'
    )
  );

  RETURN QUERY SELECT p_request_id, p_phase, p_attempt_token, 'egress_unknown',
    v_key, v_attempt.lease_expires_at, p_source_manifest_hash;
END;
$$;


--
-- Name: prepare_marketing_campaign_batch(uuid, uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_marketing_campaign_batch(p_operation_id uuid, p_actor_user_id uuid, p_preview_hash text, p_idempotency_key text, p_batch_limit integer DEFAULT 100, p_timezone text DEFAULT 'Asia/Seoul'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_operation public.marketing_campaign_operations%ROWTYPE;
  v_batch public.marketing_campaign_batches%ROWTYPE;
  v_recipient public.marketing_campaign_recipients%ROWTYPE;
  v_permission record;
  v_batch_id uuid;
  v_requested integer := 0;
  v_eligible integer := 0;
  v_suppressed integer := 0;
  v_pending integer := 0;
  v_audit_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_operation_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_preview_hash IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9_-]{8,128}$'
     OR p_batch_limit IS NULL
     OR p_batch_limit NOT BETWEEN 1 AND 100
     OR p_timezone IS DISTINCT FROM 'Asia/Seoul' THEN
    RAISE EXCEPTION 'marketing_apply_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM privacy_retention.g014_require_active_admin_actor(p_actor_user_id);

  SELECT * INTO v_operation
  FROM public.marketing_campaign_operations AS operation
  WHERE operation.id = p_operation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'marketing_operation_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_operation.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR v_operation.preview_hash IS DISTINCT FROM p_preview_hash THEN
    RAISE EXCEPTION 'marketing_preview_mismatch' USING ERRCODE = '42501';
  END IF;
  IF v_operation.expires_at <= v_now THEN
    RAISE EXCEPTION 'marketing_preview_expired' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_batch
  FROM public.marketing_campaign_batches AS batch
  WHERE batch.operation_id = p_operation_id
    AND batch.idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_batch.status IN ('completed', 'provider_failed') THEN
      RETURN pg_catalog.jsonb_build_object(
        'status', 'completed', 'replayed', true,
        'receipt', public.marketing_campaign_receipt(p_operation_id)
      );
    END IF;
    IF v_batch.status = 'claimed' THEN
      RAISE EXCEPTION 'marketing_provider_outcome_unknown' USING ERRCODE = '55000';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'status', 'prepared', 'replayed', true,
      'operationId', p_operation_id::text, 'batchId', v_batch.id::text
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.marketing_campaign_batches AS batch
    WHERE batch.operation_id = p_operation_id
      AND batch.status IN ('prepared', 'claimed')
  ) THEN
    RAISE EXCEPTION 'marketing_operation_batch_active' USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.marketing_campaign_batches (
    operation_id, idempotency_key, status, eligible_count
  ) VALUES (p_operation_id, p_idempotency_key, 'prepared', 0)
  RETURNING id INTO v_batch_id;

  FOR v_recipient IN
    SELECT *
    FROM public.marketing_campaign_recipients AS recipient
    WHERE recipient.operation_id = p_operation_id
      AND recipient.status = 'pending'
    ORDER BY recipient.user_id
    LIMIT p_batch_limit
    FOR UPDATE
  LOOP
    SELECT * INTO v_permission
    FROM privacy_retention.g014_marketing_permission_evidence(
      v_recipient.user_id, v_operation.channel, v_now, p_timezone
    );
    IF v_permission.allowed IS TRUE THEN
      UPDATE public.marketing_campaign_recipients AS recipient
      SET status = 'eligible',
          consent_event_id = v_permission.ordinary_consent_event_id,
          night_consent_event_id = v_permission.night_consent_event_id,
          updated_at = v_now
      WHERE recipient.operation_id = p_operation_id
        AND recipient.user_id = v_recipient.user_id;
      INSERT INTO privacy_retention.marketing_campaign_batch_recipients (
        batch_id, operation_id, user_id, status,
        ordinary_consent_event_id, ordinary_subject_kind, ordinary_guardian_verification_id,
        ordinary_purpose, ordinary_channel, ordinary_decision, ordinary_policy_version_id, ordinary_notice_sha256,
        night_consent_event_id, night_subject_kind, night_guardian_verification_id,
        night_purpose, night_channel, night_decision, night_policy_version_id, night_notice_sha256
      ) VALUES (
        v_batch_id, p_operation_id, v_recipient.user_id, 'eligible',
        v_permission.ordinary_consent_event_id, v_permission.subject_kind, v_permission.guardian_verification_id,
        v_operation.channel || '_marketing', v_operation.channel, 'granted', v_permission.policy_version_id, v_permission.policy_content_sha256,
        v_permission.night_consent_event_id,
        CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.subject_kind END,
        CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.guardian_verification_id END,
        CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE 'night_marketing' END,
        CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_operation.channel END,
        CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE 'granted' END,
        CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.policy_version_id END,
        CASE WHEN v_permission.night_consent_event_id IS NULL THEN NULL ELSE v_permission.policy_content_sha256 END
      );
      v_eligible := v_eligible + 1;
    ELSE
      UPDATE public.marketing_campaign_recipients AS recipient
      SET status = 'suppressed', consent_event_id = NULL, night_consent_event_id = NULL, updated_at = v_now
      WHERE recipient.operation_id = p_operation_id
        AND recipient.user_id = v_recipient.user_id;
      INSERT INTO privacy_retention.marketing_campaign_batch_recipients (
        batch_id, operation_id, user_id, status
      ) VALUES (v_batch_id, p_operation_id, v_recipient.user_id, 'suppressed');
      v_suppressed := v_suppressed + 1;
    END IF;
  END LOOP;

  SELECT count(*)::integer INTO v_requested
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id;
  SELECT count(*)::integer INTO v_pending
  FROM public.marketing_campaign_recipients AS recipient
  WHERE recipient.operation_id = p_operation_id
    AND recipient.status IN ('pending', 'eligible');

  IF v_eligible = 0 THEN
    UPDATE public.marketing_campaign_batches AS batch
    SET status = 'completed', completed_at = v_now
    WHERE batch.id = v_batch_id;
    IF v_pending = 0 THEN
      v_audit_id := privacy_retention.g014_marketing_write_audit(
        p_operation_id, p_preview_hash, 'applied', 'MARKETING_CAMPAIGN_SUPPRESSED', NULL,
        v_requested, 0, v_suppressed, 0
      );
      UPDATE public.marketing_campaign_operations AS operation
      SET status = 'applied', audit_id = v_audit_id, updated_at = v_now
      WHERE operation.id = p_operation_id;
      RETURN pg_catalog.jsonb_build_object(
        'status', 'completed', 'replayed', false,
        'receipt', public.marketing_campaign_receipt(p_operation_id)
      );
    END IF;
    v_audit_id := privacy_retention.g014_marketing_write_audit(
      p_operation_id, p_preview_hash, 'confirmed', 'MARKETING_BATCH_SUPPRESSED', NULL,
      v_requested, 0, v_suppressed, 0
    );
    UPDATE public.marketing_campaign_operations AS operation
    SET status = 'applying', audit_id = v_audit_id, updated_at = v_now
    WHERE operation.id = p_operation_id;
    RETURN pg_catalog.jsonb_build_object(
      'status', 'suppressed', 'operationId', p_operation_id::text, 'batchId', v_batch_id::text,
      'remainingRecipients', v_pending
    );
  END IF;

  UPDATE public.marketing_campaign_batches AS batch
  SET eligible_count = v_eligible
  WHERE batch.id = v_batch_id;
  v_audit_id := privacy_retention.g014_marketing_write_audit(
    p_operation_id, p_preview_hash, 'confirmed', 'MARKETING_CAMPAIGN_CONFIRMED', NULL,
    v_requested, v_eligible, v_suppressed, 0
  );
  UPDATE public.marketing_campaign_operations AS operation
  SET status = 'applying', audit_id = v_audit_id, updated_at = v_now
  WHERE operation.id = p_operation_id;
  RETURN pg_catalog.jsonb_build_object(
    'status', 'prepared', 'replayed', false,
    'operationId', p_operation_id::text, 'batchId', v_batch_id::text
  );
END;
$_$;


--
-- Name: prevent_last_active_admin_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_last_active_admin_status_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  remaining_active_admin_count integer;
  target_is_admin boolean;
BEGIN
  IF NEW.account_status <> 'disabled' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.account_status = 'disabled' THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = NEW.user_id
      AND role = 'admin'
  )
  INTO target_is_admin;

  IF NOT target_is_admin THEN
    RETURN NEW;
  END IF;

  -- Same-transaction serialization shared with admin-role removal triggers.
  PERFORM pg_advisory_xact_lock(hashtext('tzudong-admin-role-delete'));

  SELECT count(*)
  INTO remaining_active_admin_count
  FROM public.user_roles role_row
  LEFT JOIN public.user_account_status status_row
    ON status_row.user_id = role_row.user_id
  WHERE role_row.role = 'admin'
    AND role_row.user_id <> NEW.user_id
    AND coalesce(status_row.account_status, 'active') = 'active';

  IF remaining_active_admin_count < 1 THEN
    RAISE EXCEPTION 'last active admin account cannot be disabled';
  END IF;

  NEW.disabled_at = coalesce(NEW.disabled_at, now());
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: prevent_last_admin_role_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_last_admin_role_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  remaining_admin_count integer;
BEGIN
  IF OLD.role <> 'admin' THEN
    RETURN OLD;
  END IF;

  -- This lock is acquired inside the same transaction as the DELETE trigger,
  -- so the remaining-admin count and the role deletion are serialized together.
  PERFORM pg_advisory_xact_lock(hashtext('tzudong-admin-role-delete'));

  SELECT count(*)
  INTO remaining_admin_count
  FROM public.user_roles role_row
  LEFT JOIN public.user_account_status status_row
    ON status_row.user_id = role_row.user_id
  WHERE role_row.role = 'admin'
    AND role_row.user_id <> OLD.user_id
    AND coalesce(status_row.account_status, 'active') = 'active';

  IF remaining_admin_count < 1 THEN
    RAISE EXCEPTION 'last admin role cannot be removed';
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: prevent_last_admin_role_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_last_admin_role_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  remaining_admin_count integer;
BEGIN
  IF OLD.role <> 'admin' OR NEW.role = 'admin' THEN
    RETURN NEW;
  END IF;

  -- Same-transaction serialization for service-role updates that move a row away from admin.
  PERFORM pg_advisory_xact_lock(hashtext('tzudong-admin-role-delete'));

  SELECT count(*)
  INTO remaining_admin_count
  FROM public.user_roles role_row
  LEFT JOIN public.user_account_status status_row
    ON status_row.user_id = role_row.user_id
  WHERE role_row.role = 'admin'
    AND role_row.user_id <> OLD.user_id
    AND coalesce(status_row.account_status, 'active') = 'active';

  IF remaining_admin_count < 1 THEN
    RAISE EXCEPTION 'last admin role cannot be removed';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_profile_role_client_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_profile_role_client_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.role <> 'user' AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'profiles.role can only be elevated by trusted server code';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'profiles.role can only be changed by trusted server code';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: preview_account_deletion(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_account_deletion(p_actor_user_id uuid, p_target_user_id uuid, p_reauthenticated_at timestamp with time zone) RETURNS TABLE(request_id uuid, preview_hash text, preview_expires_at timestamp with time zone, policy_version text, status text, reason_code text, delete_count integer, anonymize_count integer, separate_count integer, retain_count integer, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_policy public.account_deletion_policies%ROWTYPE;
  v_request public.account_deletion_requests%ROWTYPE;
  v_manifest_hash text;
  v_last_sign_in_at timestamptz;
  v_counts jsonb := '{}'::jsonb;
  v_subject_value text;
  v_item record;
  v_count integer;
  v_abandoned_request_id uuid;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_require_service_role();
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL OR p_reauthenticated_at IS NULL THEN
    RAISE EXCEPTION 'account_deletion_preview_arguments_required' USING ERRCODE = '22004';
  END IF;
  PERFORM privacy_retention.g014_account_deletion_lock_target(p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_actor_allowed(p_actor_user_id, p_target_user_id);
  PERFORM privacy_retention.g014_account_deletion_assert_no_hold(p_target_user_id);
  SELECT user_row.last_sign_in_at INTO v_last_sign_in_at
  FROM privacy_retention.g041_auth_users AS user_row WHERE user_row.id = p_actor_user_id;
  IF v_last_sign_in_at IS NULL OR abs(EXTRACT(EPOCH FROM (p_reauthenticated_at - v_last_sign_in_at))) > 1 THEN
    RAISE EXCEPTION 'account_deletion_reauthentication_required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_policy
  FROM public.account_deletion_policies AS policy
  WHERE policy.status = 'active'
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'account_deletion_policy_unavailable' USING ERRCODE = '55000'; END IF;
  IF v_last_sign_in_at < pg_catalog.clock_timestamp() - v_policy.reauth_max_age
     OR NOT EXISTS (SELECT 1 FROM privacy_retention.g041_auth_users WHERE id = p_target_user_id) THEN
    RAISE EXCEPTION 'account_deletion_target_or_reauthentication_invalid' USING ERRCODE = '55000';
  END IF;
  v_manifest_hash := privacy_retention.g014_account_deletion_validate_manifest(v_policy.version);
  FOR v_item IN
    SELECT manifest.*, registry.subject_type
    FROM privacy_retention.account_deletion_source_manifest AS manifest
    JOIN privacy_retention.account_deletion_adapter_registry AS registry ON registry.adapter_name = manifest.adapter_name
    WHERE manifest.policy_version = v_policy.version
    ORDER BY manifest.ordinal, manifest.code
  LOOP
    v_subject_value := CASE WHEN v_item.subject_type = 'text'::regtype
      THEN privacy_retention.g014_account_deletion_subject_hash(p_target_user_id)
      ELSE p_target_user_id::text END;
    v_count := privacy_retention.g014_account_deletion_source_count(
      v_item.relation_name, v_item.subject_column, v_subject_value
    );
    v_counts := pg_catalog.jsonb_set(
      v_counts,
      ARRAY[v_item.code],
      pg_catalog.to_jsonb(COALESCE((v_counts ->> v_item.code)::integer, 0) + v_count),
      true
    );
  END LOOP;
  SELECT request_row.id INTO v_abandoned_request_id
  FROM public.account_deletion_requests AS request_row
  WHERE request_row.target_user_id = p_target_user_id
    AND request_row.status = 'previewed'
    AND request_row.preview_expires_at <= pg_catalog.clock_timestamp()
  FOR UPDATE;

  IF FOUND THEN
    PERFORM privacy_retention.g014_account_deletion_transition_preview_terminal(
      p_target_user_id, v_abandoned_request_id, 'expired'
    );
  END IF;
  INSERT INTO public.account_deletion_requests (
    actor_user_id, target_user_id, policy_version, preview_hash, preview_expires_at,
    reauthenticated_at, status, reason_code, count_summary, source_manifest_hash
  ) VALUES (
    p_actor_user_id, p_target_user_id, v_policy.version,
    pg_catalog.encode(extensions.digest(
      pg_catalog.jsonb_build_object(
        'actor', p_actor_user_id, 'target', p_target_user_id, 'policy', v_policy.version,
        'manifest', v_manifest_hash, 'reauthenticatedAt', p_reauthenticated_at, 'counts', v_counts,
        'nonce', extensions.gen_random_uuid()
      )::text, 'sha256'
    ), 'hex'),
    pg_catalog.clock_timestamp() + v_policy.preview_ttl,
    p_reauthenticated_at, 'previewed', 'PREVIEW_READY',
    pg_catalog.jsonb_build_object('requested', COALESCE((SELECT sum((value #>> '{}')::integer) FROM pg_catalog.jsonb_each(v_counts)), 0)),
    v_manifest_hash
  ) RETURNING * INTO v_request;
  INSERT INTO public.account_deletion_request_items (
    request_id, data_class_code, disposition, mandatory, planned_count, status, reason_code
  )
  SELECT
    v_request.id, data_class.code, data_class.disposition, data_class.mandatory,
    COALESCE((v_counts ->> data_class.code)::integer, 0), 'planned', 'PREVIEW_READY'
  FROM public.account_deletion_data_classes AS data_class
  WHERE data_class.policy_version = v_policy.version;
  PERFORM privacy_retention.g014_account_deletion_append_audit(v_request, 'previewed', 'PREVIEW_READY');
  RETURN QUERY SELECT
    v_request.id, v_request.preview_hash, v_request.preview_expires_at, v_request.policy_version,
    v_request.status, v_request.reason_code,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'delete') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'anonymize') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'separate') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    COALESCE((SELECT sum(planned_count) FILTER (WHERE disposition = 'retain') FROM public.account_deletion_request_items WHERE request_id = v_request.id), 0)::integer,
    v_request.source_manifest_hash;
END;
$$;


--
-- Name: preview_marketing_campaign(uuid, text, uuid[], text, text, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_marketing_campaign(p_actor_user_id uuid, p_channel text, p_recipient_user_ids uuid[], p_title text, p_message text, p_data jsonb, p_preview_hash text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_operation_id uuid := extensions.gen_random_uuid();
  v_requested integer;
  v_audit_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_actor_user_id IS NULL
     OR p_channel IS NULL
     OR p_channel NOT IN ('email', 'sms', 'push')
     OR p_preview_hash IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_expires_at IS NULL
     OR p_expires_at <= v_now
     OR p_expires_at > v_now + interval '15 minutes'
     OR p_recipient_user_ids IS NULL
     OR p_title IS NULL
     OR p_message IS NULL THEN
    RAISE EXCEPTION 'marketing_preview_invalid' USING ERRCODE = '22023';
  END IF;
  v_requested := COALESCE(pg_catalog.array_length(p_recipient_user_ids, 1), 0);
  IF v_requested NOT BETWEEN 1 AND 100
     OR (SELECT count(DISTINCT recipient.user_id) FROM pg_catalog.unnest(p_recipient_user_ids) AS recipient(user_id)) <> v_requested THEN
    RAISE EXCEPTION 'marketing_recipient_batch_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM public.assert_notification_content_safe(p_title, p_message, COALESCE(p_data, '{}'::jsonb));
  PERFORM privacy_retention.g014_require_active_admin_actor(p_actor_user_id);

  INSERT INTO public.marketing_campaign_operations (
    id, actor_user_id, actor_ref_hash, channel, title, message, data, preview_hash, expires_at
  ) VALUES (
    v_operation_id, p_actor_user_id,
    pg_catalog.encode(extensions.digest('marketing-actor:v1:' || p_actor_user_id::text, 'sha256'), 'hex'),
    p_channel, pg_catalog.btrim(p_title), pg_catalog.btrim(p_message), COALESCE(p_data, '{}'::jsonb),
    p_preview_hash, p_expires_at
  );
  INSERT INTO public.marketing_campaign_recipients (operation_id, user_id)
  SELECT v_operation_id, recipient.user_id
  FROM pg_catalog.unnest(p_recipient_user_ids) AS recipient(user_id);
  v_audit_id := privacy_retention.g014_marketing_write_audit(
    v_operation_id, p_preview_hash, 'previewed', 'MARKETING_CAMPAIGN_PREVIEW', NULL,
    v_requested, 0, 0, 0
  );
  UPDATE public.marketing_campaign_operations AS operation
  SET audit_id = v_audit_id, updated_at = v_now
  WHERE operation.id = v_operation_id;

  RETURN pg_catalog.jsonb_build_object(
    'operationId', v_operation_id::text,
    'expiresAt', p_expires_at,
    'requestedCount', v_requested,
    'batchCap', 100
  );
END;
$_$;


--
-- Name: preview_privacy_incident_transition(uuid, uuid, public.privacy_incident_status, timestamp with time zone, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_privacy_incident_transition(p_actor_user_id uuid, p_incident_id uuid, p_to_status public.privacy_incident_status, p_expected_updated_at timestamp with time zone, p_reason_code text, p_transition_input jsonb, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_incident public.privacy_incidents%rowtype;
  v_operation_id uuid := extensions.gen_random_uuid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_audit_retention_until timestamptz;
  v_expires_at timestamptz := v_now + interval '15 minutes';
  v_input_hash text;
  v_preview_hash text;
  v_prompt_count integer;
  v_prompt_sensitive boolean;
  v_prompt_intrusion boolean;
BEGIN
  PERFORM public.privacy_incident_require_admin(p_actor_user_id);

  IF p_incident_id IS NULL OR p_expected_updated_at IS NULL OR p_to_status IS NULL OR p_correlation_id IS NULL
     OR p_reason_code IS NULL OR p_reason_code !~ '^[a-z][a-z0-9_]{2,63}$' THEN
    RAISE EXCEPTION 'invalid_privacy_incident_preview_request';
  END IF;

  PERFORM public.privacy_incident_validate_input(p_to_status, coalesce(p_transition_input, '{}'::jsonb));

  SELECT *
    INTO v_incident
    FROM public.privacy_incidents
   WHERE id = p_incident_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'privacy_incident_not_found';
  END IF;

  IF v_incident.updated_at <> p_expected_updated_at THEN
    RAISE EXCEPTION 'privacy_incident_version_stale';
  END IF;

  IF NOT public.privacy_incident_transition_is_allowed(v_incident.status, p_to_status) THEN
    RAISE EXCEPTION 'privacy_incident_transition_forbidden';
  END IF;
  v_audit_retention_until := public.privacy_incident_audit_retention_until(v_now);


  IF p_to_status = 'assessed' THEN
    v_prompt_count := (p_transition_input ->> 'affectedCountEstimate')::integer;
    v_prompt_sensitive := (p_transition_input ->> 'sensitiveOrUniqueId')::boolean;
    v_prompt_intrusion := (p_transition_input ->> 'externalIntrusion')::boolean;
  ELSE
    v_prompt_count := v_incident.affected_count_estimate;
    v_prompt_sensitive := v_incident.sensitive_or_unique_id;
    v_prompt_intrusion := v_incident.external_intrusion;
  END IF;

  v_input_hash := public.privacy_incident_input_hash(coalesce(p_transition_input, '{}'::jsonb));
  v_preview_hash := pg_catalog.encode(extensions.digest(jsonb_build_object(
    'workflowVersion', 'g010-incident-v1',
    'actorUserId', p_actor_user_id,
    'incidentId', p_incident_id,
    'fromStatus', v_incident.status,
    'toStatus', p_to_status,
    'expectedUpdatedAt', p_expected_updated_at,
    'reasonCode', p_reason_code,
    'inputHash', v_input_hash,
    'correlationId', p_correlation_id,
    'expiresAt', v_expires_at
  )::text, 'sha256'), 'hex');

  INSERT INTO public.privacy_incident_transition_previews (
    operation_id,
    incident_id,
    actor_user_id,
    from_status,
    to_status,
    expected_updated_at,
    preview_hash,
    input_hash,
    reason_code,
    correlation_id,
    expires_at
  ) VALUES (
    v_operation_id,
    p_incident_id,
    p_actor_user_id,
    v_incident.status,
    p_to_status,
    p_expected_updated_at,
    v_preview_hash,
    v_input_hash,
    p_reason_code,
    p_correlation_id,
    v_expires_at
  );

  INSERT INTO privacy_retention.privacy_audit_events (
    event_type,
    actor_user_id,
    operation_id,
    correlation_id,
    preview_hash,
    status,
    reason_code,
    count_summary,
    request_metadata,
    occurred_at,
    retention_until
  ) VALUES (
    'privacy_incident_transition',
    p_actor_user_id,
    v_operation_id,
    p_correlation_id,
    v_preview_hash,
    'previewed',
    upper(p_reason_code),
    public.privacy_incident_audit_count_summary(
      coalesce(v_prompt_count, 0),
      CASE
        WHEN p_to_status = 'assessed' THEN jsonb_array_length(p_transition_input -> 'dataCategories')
        ELSE cardinality(v_incident.data_categories)
      END
    ),
    jsonb_build_object('route', '/api/admin/privacy-incidents'),
    v_now,
    v_audit_retention_until
  );

  RETURN jsonb_build_object(
    'ok', true,
    'operationId', v_operation_id,
    'previewHash', v_preview_hash,
    'expiresAt', v_expires_at,
    'requiredConfirmation', '개인정보 사고 조치 적용',
    'summary', jsonb_build_object(
      'incidentId', p_incident_id,
      'fromStatus', v_incident.status,
      'toStatus', p_to_status,
      'expectedUpdatedAt', p_expected_updated_at,
      'deadlineAt', CASE WHEN p_to_status = 'triaged' THEN ((p_transition_input ->> 'awarenessAt')::timestamptz + interval '72 hours') ELSE v_incident.deadline_at END,
      'decisionPrompts', public.privacy_incident_decision_prompts(v_prompt_count, v_prompt_sensitive, v_prompt_intrusion)
    )
  );
END;
$_$;


--
-- Name: preview_privacy_retention_run(text, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_privacy_retention_run(p_class_code text, p_as_of timestamp with time zone, p_batch_size integer, p_max_duration_ms integer DEFAULT 10000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_class privacy_retention.privacy_retention_classes%ROWTYPE;
  v_run privacy_retention.privacy_retention_runs%ROWTYPE;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_preview_hash text;
  v_adapter_version text;
  v_source_mapping_version text;
  v_planned_count integer := 0;
  v_held_count integer := 0;
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  IF p_as_of IS NULL OR p_as_of > v_now
     OR p_batch_size IS NULL
     OR p_batch_size NOT BETWEEN 1 AND 100
     OR p_max_duration_ms IS NULL
     OR p_max_duration_ms NOT BETWEEN 1000 AND 10000 THEN
    RAISE EXCEPTION 'privacy_retention_batch_cutoff_or_timeout_invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.set_config('statement_timeout', p_max_duration_ms::text, true);

  SELECT * INTO v_class
  FROM privacy_retention.privacy_retention_classes
  WHERE code = p_class_code AND status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'privacy_retention_class_adapter_not_active' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_class_bindings(p_class_code);
  v_adapter_version := privacy_retention.g014_retention_active_adapter_version(p_class_code);
  v_source_mapping_version := privacy_retention.g014_retention_active_source_mapping_version(p_class_code);

  v_preview_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.concat_ws(
        ':', 'g014-retention-preview-v1', p_class_code, p_as_of::text,
        p_batch_size::text, v_class.version, v_adapter_version, v_source_mapping_version
      ),
      'sha256'
    ),
    'hex'
  );

  INSERT INTO privacy_retention.privacy_retention_runs (
    class_code, cutoff, status, preview_hash, preview_expires_at,
    adapter_version, source_mapping_version
  ) VALUES (
    p_class_code, p_as_of, 'previewed', v_preview_hash, v_now + interval '15 minutes',
    v_adapter_version, v_source_mapping_version
  ) RETURNING * INTO v_run;

  WITH candidates AS (
    SELECT item.id, item.source_type,
           privacy_retention.g014_retention_active_hold_exists(item.subject_ref_hash, item.data_class, v_now) AS held
    FROM privacy_retention.privacy_retention_work_items AS item
    JOIN privacy_retention.retention_class_adapter_bindings AS binding
      ON binding.class_code = item.class_code
     AND binding.source_type = item.source_type
     AND binding.status = 'active'
    JOIN privacy_retention.retention_adapter_versions AS version_row
      ON version_row.adapter_code = binding.adapter_code
     AND version_row.adapter_version = binding.adapter_version
     AND version_row.status = 'active'
     AND binding.mapping_contract_hash IS NOT DISTINCT FROM version_row.contract_hash
    WHERE item.class_code = p_class_code
      AND item.data_class = v_class.data_class
      AND item.trigger_at <= p_as_of
      AND item.status IN ('pending', 'failed')
    ORDER BY item.trigger_at, item.id
    LIMIT p_batch_size
  ), inserted AS (
    INSERT INTO privacy_retention.privacy_retention_run_items (run_id, work_item_id, source_type, status)
    SELECT v_run.id, id, source_type, CASE WHEN held THEN 'held' ELSE 'planned' END
    FROM candidates
    RETURNING status
  )
  SELECT count(*) FILTER (WHERE status = 'planned'), count(*) FILTER (WHERE status = 'held')
  INTO v_planned_count, v_held_count
  FROM inserted;

  UPDATE privacy_retention.privacy_retention_runs
  SET scanned_count = v_planned_count + v_held_count,
      planned_count = v_planned_count,
      held_count = v_held_count
  WHERE id = v_run.id
  RETURNING * INTO v_run;

  UPDATE privacy_retention.privacy_retention_runs
  SET audit_id = privacy_retention.g014_retention_append_audit(v_run, 'previewed', 'RETENTION_PREVIEW')
  WHERE id = v_run.id
  RETURNING * INTO v_run;

  RETURN pg_catalog.jsonb_build_object(
    'operationId', v_run.id,
    'previewHash', v_run.preview_hash,
    'expiresAt', v_run.preview_expires_at,
    'adapterVersion', v_run.adapter_version,
    'sourceMappingVersion', v_run.source_mapping_version,
    'summary', pg_catalog.jsonb_build_object(
      'cutoff', v_run.cutoff,
      'eligible', v_run.planned_count,
      'held', v_run.held_count,
      'scanned', v_run.scanned_count
    ),
    'requiredConfirmation', '보존·분리 적용'
  );
END;
$$;


