--
-- Name: privacy_incident_audit_retention_until(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_audit_retention_until(p_now timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_retention_until timestamptz;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'privacy_incident_service_role_required';
  END IF;

  BEGIN
    v_retention_until := public.privacy_resolve_audit_retention_until(
      'privacy_incident_audit',
      p_now
    );
  EXCEPTION
    WHEN SQLSTATE '55000' THEN
      RAISE EXCEPTION 'privacy_incident_audit_retention_class_required';
  END;

  RETURN v_retention_until;
END;
$$;


--
-- Name: privacy_incident_decision_prompts(integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_decision_prompts(p_affected_count integer, p_sensitive_or_unique_id boolean, p_external_intrusion boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_prompts jsonb := jsonb_build_array(
    jsonb_build_object('code', 'human_count_confirmation', 'messageKo', '영향 인원 추정치는 담당자가 사실관계로 확인해야 합니다.')
  );
BEGIN
  IF coalesce(p_affected_count, 0) >= 1000 THEN
    v_prompts := v_prompts || jsonb_build_array(
      jsonb_build_object('code', 'count_1000_or_more_human_review', 'messageKo', '1,000명 이상 추정값입니다. 신고·통지 판단은 담당자와 검토자가 결정해야 합니다.')
    );
  END IF;

  IF p_sensitive_or_unique_id IS TRUE THEN
    v_prompts := v_prompts || jsonb_build_array(
      jsonb_build_object('code', 'sensitive_or_unique_id_human_review', 'messageKo', '민감정보 또는 고유식별정보 여부 입력입니다. 법적 판단은 사람이 확인해야 합니다.')
    );
  END IF;

  IF p_external_intrusion IS TRUE THEN
    v_prompts := v_prompts || jsonb_build_array(
      jsonb_build_object('code', 'external_intrusion_human_review', 'messageKo', '외부 침입 관련 입력입니다. 신고 대상 여부는 사람이 확인해야 합니다.')
    );
  END IF;

  RETURN v_prompts;
END;
$$;


--
-- Name: privacy_incident_enforce_state_invariants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_enforce_state_invariants() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status = 'notified' AND NOT EXISTS (
    SELECT 1
      FROM public.privacy_incident_notices
     WHERE incident_id = NEW.id
       AND status = 'submitted'
       AND approved_by IS NOT NULL
       AND approved_at IS NOT NULL
       AND submitted_by IS NOT NULL
       AND submitted_at IS NOT NULL
       AND external_receipt_ref IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'privacy_incident_external_receipt_required';
  END IF;

  IF NEW.status = 'closed' AND (
    NEW.assessment_readback_at IS NULL
    OR NEW.affected_count_estimate IS NULL
    OR cardinality(NEW.data_categories) = 0
    OR NEW.sensitive_or_unique_id IS NULL
    OR NEW.external_intrusion IS NULL
    OR NEW.decision_code IS NULL
    OR NOT EXISTS (
      SELECT 1
        FROM public.privacy_incident_actions
       WHERE incident_id = NEW.id
         AND to_status = 'notified'
         AND readback_status = 'passed'
    )
  ) THEN
    RAISE EXCEPTION 'privacy_incident_closure_readback_required';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: privacy_incident_input_hash(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_input_hash(p_input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT pg_catalog.encode(extensions.digest(coalesce(p_input, '{}'::jsonb)::text, 'sha256'), 'hex');
$$;


--
-- Name: privacy_incident_require_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_require_admin(p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  claims jsonb;
  caller_role text;
BEGIN
  BEGIN
    claims := COALESCE(
      NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb,
      '{}'::jsonb
    );
    caller_role := COALESCE(
      NULLIF(claims ->> 'role', ''),
      NULLIF(pg_catalog.current_setting('request.jwt.claim.role', true), ''),
      ''
    );
  EXCEPTION
    WHEN invalid_text_representation OR invalid_parameter_value THEN
      RAISE EXCEPTION 'privacy_incident_service_role_required'
        USING ERRCODE = 'P0001';
  END;

  IF caller_role <> 'service_role' THEN
    RAISE EXCEPTION 'privacy_incident_service_role_required'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_actor_user_id IS NULL OR NOT EXISTS (
    SELECT 1
      FROM public.user_roles AS role_row
      JOIN public.user_account_status AS status_row
        ON status_row.user_id = role_row.user_id
     WHERE role_row.user_id = p_actor_user_id
       AND role_row.role::text = 'admin'
       AND status_row.account_status = 'active'
       AND status_row.disabled_at IS NULL
  ) THEN
    RAISE EXCEPTION 'privacy_incident_privacy_admin_required'
      USING ERRCODE = 'P0001';
  END IF;
END
$$;


--
-- Name: privacy_incident_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  NEW.updated_at := pg_catalog.clock_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: privacy_incident_transition_is_allowed(public.privacy_incident_status, public.privacy_incident_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_transition_is_allowed(p_from public.privacy_incident_status, p_to public.privacy_incident_status) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT (p_from, p_to) IN (
    ('detected'::public.privacy_incident_status, 'triaged'::public.privacy_incident_status),
    ('triaged'::public.privacy_incident_status, 'contained'::public.privacy_incident_status),
    ('contained'::public.privacy_incident_status, 'assessed'::public.privacy_incident_status),
    ('assessed'::public.privacy_incident_status, 'notice_drafted'::public.privacy_incident_status),
    ('notice_drafted'::public.privacy_incident_status, 'notice_approved'::public.privacy_incident_status),
    ('notice_approved'::public.privacy_incident_status, 'notified'::public.privacy_incident_status),
    ('notified'::public.privacy_incident_status, 'closed'::public.privacy_incident_status)
  );
$$;


--
-- Name: privacy_incident_validate_input(public.privacy_incident_status, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_incident_validate_input(p_to_status public.privacy_incident_status, p_input jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_category text;
  v_text text;
  v_count numeric;
BEGIN
  IF p_input IS NULL OR jsonb_typeof(p_input) <> 'object' THEN
    RAISE EXCEPTION 'invalid_privacy_incident_transition_input';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM jsonb_object_keys(p_input) AS key
     WHERE key NOT IN (
       'awarenessAt',
       'affectedCountEstimate',
       'dataCategories',
       'sensitiveOrUniqueId',
       'externalIntrusion',
       'decisionCode',
       'noticeAudience',
       'templateVersion',
       'contentSha256',
       'noticeId',
       'externalReceiptRef'
     )
  ) THEN
    RAISE EXCEPTION 'invalid_privacy_incident_transition_input';
  END IF;

  IF p_to_status = 'triaged' THEN
    v_text := p_input ->> 'awarenessAt';
    IF v_text IS NULL OR jsonb_object_length(p_input) <> 1 THEN
      RAISE EXCEPTION 'privacy_incident_awareness_confirmation_required';
    END IF;
    BEGIN
      IF v_text::timestamptz > pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION 'privacy_incident_awareness_confirmation_required';
      END IF;
    EXCEPTION
      WHEN invalid_datetime_format OR datetime_field_overflow THEN
        RAISE EXCEPTION 'privacy_incident_awareness_confirmation_required';
    END;
    RETURN;
  END IF;

  IF p_to_status = 'contained' OR p_to_status = 'closed' THEN
    IF jsonb_object_length(p_input) <> 0 THEN
      RAISE EXCEPTION 'invalid_privacy_incident_transition_input';
    END IF;
    RETURN;
  END IF;

  IF p_to_status = 'assessed' THEN
    IF NOT (p_input ? 'affectedCountEstimate' AND p_input ? 'dataCategories' AND p_input ? 'sensitiveOrUniqueId' AND p_input ? 'externalIntrusion' AND p_input ? 'decisionCode')
       OR jsonb_object_length(p_input) <> 5
       OR jsonb_typeof(p_input -> 'affectedCountEstimate') <> 'number'
       OR jsonb_typeof(p_input -> 'dataCategories') <> 'array'
       OR jsonb_typeof(p_input -> 'sensitiveOrUniqueId') <> 'boolean'
       OR jsonb_typeof(p_input -> 'externalIntrusion') <> 'boolean' THEN
      RAISE EXCEPTION 'privacy_incident_assessment_required';
    END IF;

    v_count := (p_input ->> 'affectedCountEstimate')::numeric;
    IF v_count < 0 OR v_count > 1000000000 OR trunc(v_count) <> v_count OR jsonb_array_length(p_input -> 'dataCategories') < 1 OR jsonb_array_length(p_input -> 'dataCategories') > 10 THEN
      RAISE EXCEPTION 'privacy_incident_assessment_required';
    END IF;

    v_text := p_input ->> 'decisionCode';
    IF v_text IS NULL OR v_text !~ '^[a-z][a-z0-9_]{2,63}$' THEN
      RAISE EXCEPTION 'privacy_incident_assessment_required';
    END IF;

    FOR v_category IN SELECT jsonb_array_elements_text(p_input -> 'dataCategories') LOOP
      IF v_category IS NULL OR v_category NOT IN ('account', 'contact', 'authentication', 'device', 'usage', 'location', 'financial', 'sensitive', 'unique_identifier', 'other') THEN
        RAISE EXCEPTION 'privacy_incident_assessment_required';
      END IF;
    END LOOP;
    RETURN;
  END IF;

  IF p_to_status = 'notice_drafted' THEN
    IF NOT (p_input ? 'noticeAudience' AND p_input ? 'templateVersion' AND p_input ? 'contentSha256')
       OR jsonb_object_length(p_input) <> 3
       OR p_input ->> 'noticeAudience' NOT IN ('data_subjects', 'pipc', 'kisa')
       OR p_input ->> 'templateVersion' !~ '^[a-zA-Z0-9._-]{1,64}$'
       OR p_input ->> 'contentSha256' !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'privacy_incident_notice_draft_required';
    END IF;
    RETURN;
  END IF;

  IF p_to_status = 'notice_approved' THEN
    IF jsonb_object_length(p_input) <> 1 OR p_input ->> 'noticeId' IS NULL THEN
      RAISE EXCEPTION 'privacy_incident_notice_approval_required';
    END IF;
    BEGIN
      PERFORM (p_input ->> 'noticeId')::uuid;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'privacy_incident_notice_approval_required';
    END;
    RETURN;
  END IF;

  IF p_to_status = 'notified' THEN
    IF jsonb_object_length(p_input) <> 2
       OR p_input ->> 'noticeId' IS NULL
       OR p_input ->> 'externalReceiptRef' !~ '^[A-Za-z][A-Za-z0-9._:/-]{5,159}$' THEN
      RAISE EXCEPTION 'privacy_incident_external_receipt_required';
    END IF;
    BEGIN
      PERFORM (p_input ->> 'noticeId')::uuid;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'privacy_incident_external_receipt_required';
    END;
    RETURN;
  END IF;

  RAISE EXCEPTION 'invalid_privacy_incident_transition_input';
END;
$_$;


--
-- Name: privacy_refresh_age_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_refresh_age_profile(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_profile privacy_retention.privacy_age_profiles%ROWTYPE;
  v_status text;
BEGIN
  SELECT * INTO v_profile
  FROM privacy_retention.privacy_age_profiles AS profile
  WHERE profile.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND OR v_profile.age_band <> 'under_14' THEN
    RETURN;
  END IF;

  IF public.privacy_under_14_is_eligible(p_user_id, v_profile.policy_version_id) THEN
    v_status := 'guardian_verified';
  ELSIF EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_guardian_verifications AS guardian
    WHERE guardian.child_user_id = p_user_id
      AND guardian.status = 'verified'
      AND guardian.verified_at IS NOT NULL
      AND guardian.verified_at <= pg_catalog.clock_timestamp()
      AND guardian.expires_at > pg_catalog.clock_timestamp()
      AND guardian.withdrawn_at IS NULL
  ) THEN
    -- A replacement verification recovers a withdrawn profile only to pending;
    -- a required consent bound to that verification remains mandatory.
    v_status := 'guardian_pending';
  ELSIF EXISTS (
    SELECT 1
    FROM privacy_retention.privacy_guardian_verifications AS guardian
    WHERE guardian.child_user_id = p_user_id
      AND guardian.status = 'withdrawn'
  ) THEN
    v_status := 'guardian_withdrawn';
  ELSE
    v_status := 'guardian_pending';
  END IF;

  UPDATE privacy_retention.privacy_age_profiles AS profile
  SET status = v_status,
      updated_at = pg_catalog.clock_timestamp()
  WHERE profile.user_id = p_user_id
    AND profile.status IS DISTINCT FROM v_status;
END;
$$;


--
-- Name: privacy_refresh_age_profile_after_consent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.privacy_refresh_age_profile_after_consent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.subject_kind = 'child' THEN
    PERFORM public.privacy_refresh_age_profile(NEW.user_id);
  END IF;
  RETURN NEW;
END;
$$;


