--
-- Name: resolve_privacy_retention_provider_effect(uuid, text, text, uuid, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_privacy_retention_provider_effect(p_run_id uuid, p_preview_hash text, p_idempotency_key text, p_work_item_id uuid, p_claim_token uuid, p_claim_hash text, p_object_locator_hash text, p_object_version_hash text, p_adapter_version text, p_source_mapping_version text, p_provider_verifier_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_run privacy_retention.privacy_retention_runs%ROWTYPE;
  v_claim privacy_retention.g014_retention_storage_claims%ROWTYPE;
  v_item privacy_retention.privacy_retention_work_items%ROWTYPE;
  v_storage_object storage.objects%ROWTYPE;
  v_storage_version text;
  v_effect privacy_retention.g014_retention_provider_effects%ROWTYPE;
  v_verifier_ref text;
  v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
  PERFORM privacy_retention.g014_retention_require_service_role();
  IF p_run_id IS NULL OR p_work_item_id IS NULL OR p_claim_token IS NULL
     OR p_preview_hash !~ '^[0-9a-f]{64}$'
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     OR p_claim_hash !~ '^[0-9a-f]{64}$'
     OR p_object_locator_hash !~ '^[0-9a-f]{64}$'
     OR p_object_version_hash !~ '^[0-9a-f]{64}$'
     OR p_adapter_version !~ '^[0-9a-f]{64}$'
     OR p_source_mapping_version !~ '^[0-9a-f]{64}$'
     OR p_provider_verifier_ref !~ '^[A-Za-z0-9._:-]{8,128}$' THEN
    RAISE EXCEPTION 'retention_provider_effect_arguments_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_run
  FROM privacy_retention.privacy_retention_runs
  WHERE id = p_run_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_run.preview_hash IS DISTINCT FROM p_preview_hash
     OR v_run.idempotency_key IS DISTINCT FROM p_idempotency_key
     OR v_run.adapter_version IS DISTINCT FROM p_adapter_version
     OR v_run.source_mapping_version IS DISTINCT FROM p_source_mapping_version
     OR v_run.status NOT IN ('running', 'partial', 'held') THEN
    RAISE EXCEPTION 'retention_provider_effect_binding_invalid' USING ERRCODE = '55000';
  END IF;
  PERFORM privacy_retention.g014_retention_assert_run_bindings(
    v_run.class_code, v_run.adapter_version, v_run.source_mapping_version
  );

  SELECT * INTO v_claim
  FROM privacy_retention.g014_retention_storage_claims
  WHERE run_id = v_run.id
    AND work_item_id = p_work_item_id
    AND claim_token = p_claim_token
  FOR UPDATE;
  IF NOT FOUND
     OR v_claim.status IS DISTINCT FROM 'active'
     OR v_claim.claim_expires_at <= v_now
     OR v_claim.claim_hash IS DISTINCT FROM p_claim_hash
     OR v_claim.object_locator_hash IS DISTINCT FROM p_object_locator_hash
     OR v_claim.object_version_hash IS DISTINCT FROM p_object_version_hash THEN
    RAISE EXCEPTION 'retention_provider_effect_claim_invalid' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_item
  FROM privacy_retention.privacy_retention_work_items
  WHERE id = v_claim.work_item_id
  FOR UPDATE;
  SELECT version_row.provider_verifier_ref INTO v_verifier_ref
  FROM privacy_retention.retention_adapter_versions AS version_row
  WHERE version_row.adapter_code = v_claim.adapter_code
    AND version_row.adapter_version = v_claim.adapter_version
    AND version_row.status = 'active'
    AND version_row.removal_mode = 'external_delete';
  IF NOT FOUND
     OR v_item.source_ref_hash IS DISTINCT FROM v_claim.object_locator_hash
     OR v_item.storage_version_hash IS DISTINCT FROM v_claim.object_version_hash
     OR v_verifier_ref IS DISTINCT FROM p_provider_verifier_ref THEN
    RAISE EXCEPTION 'retention_provider_effect_locator_invalid' USING ERRCODE = '55000';
  END IF;

  PERFORM privacy_retention.g014_retention_lock_subject_hash(v_item.subject_ref_hash);
  IF privacy_retention.g014_retention_active_hold_exists(
       v_item.subject_ref_hash, v_item.data_class, pg_catalog.clock_timestamp()
     ) THEN
    UPDATE privacy_retention.g014_retention_storage_claims
    SET status = 'failed', resolved_at = v_now
    WHERE id = v_claim.id AND status = 'active';
    UPDATE privacy_retention.privacy_retention_work_items
    SET status = 'failed', storage_claim_token = NULL, storage_claimed_at = NULL,
        last_error_code = 'retention_legal_hold_active'
    WHERE id = v_item.id
      AND status = 'claimed'
      AND storage_claim_token IS NOT DISTINCT FROM v_claim.claim_token;
    UPDATE privacy_retention.privacy_retention_run_items
    SET status = 'held', error_code = NULL
    WHERE run_id = v_run.id
      AND work_item_id = v_item.id
      AND status = 'storage_claimed';
    RETURN NULL;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM privacy_retention.g014_retention_provider_effects AS effect_row
    WHERE effect_row.claim_token = v_claim.claim_token
  ) THEN
    RAISE EXCEPTION 'retention_provider_effect_already_consumed' USING ERRCODE = '55000';
  END IF;
  SELECT object_row.* INTO v_storage_object
  FROM storage.objects AS object_row
  WHERE privacy_retention.g014_retention_storage_locator_hash(
          object_row.bucket_id::text, object_row.name::text
        ) = v_claim.object_locator_hash
  FOR UPDATE OF object_row;
  v_storage_version := pg_catalog.to_jsonb(v_storage_object) ->> 'version';
  IF NOT FOUND
     OR v_storage_object.id IS NULL
     OR v_storage_object.bucket_id::text !~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,62}$'
     OR pg_catalog.length(v_storage_object.name::text) NOT BETWEEN 1 AND 1024
     OR v_storage_object.name::text !~ '^[A-Za-z0-9][A-Za-z0-9._/:-]*$'
     OR pg_catalog.length(v_storage_version) NOT BETWEEN 1 AND 256
     OR v_storage_version !~ '^[A-Za-z0-9._:-]+$'
     OR pg_catalog.encode(
          extensions.digest(v_storage_version, 'sha256'),
          'hex'
        ) IS DISTINCT FROM v_claim.object_version_hash THEN
    RAISE EXCEPTION 'retention_provider_effect_authoritative_locator_invalid'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO privacy_retention.g014_retention_provider_effects (
    run_id, work_item_id, claim_token, claim_hash, object_locator_hash,
    object_version_hash, adapter_version, source_mapping_version,
    provider_verifier_ref, subject_ref_hash, data_class, lease_expires_at
  ) VALUES (
    v_run.id, v_claim.work_item_id, v_claim.claim_token, v_claim.claim_hash,
    v_claim.object_locator_hash, v_claim.object_version_hash,
    v_run.adapter_version, v_run.source_mapping_version,
    v_verifier_ref, v_item.subject_ref_hash, v_item.data_class,
    v_now + interval '45 seconds'
  )
  RETURNING * INTO v_effect;

  RETURN pg_catalog.jsonb_build_object(
    'workItemId', v_claim.work_item_id,
    'claimToken', v_claim.claim_token,
    'claimHash', v_claim.claim_hash,
    'objectLocatorHash', v_claim.object_locator_hash,
    'objectVersionHash', v_claim.object_version_hash,
    'adapterVersion', v_run.adapter_version,
    'sourceMappingVersion', v_run.source_mapping_version,
    'providerEffectToken', v_effect.provider_effect_token,
    'providerVerifierRef', v_effect.provider_verifier_ref,
    'leaseExpiresAt', v_effect.lease_expires_at,
    'bucketName', v_storage_object.bucket_id::text,
    'objectName', v_storage_object.name::text
  );
END;
$_$;


--
-- Name: resolve_restaurant_identity_name(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_restaurant_identity_name(p_approved_name text, p_origin_name text, p_naver_name text, p_google_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select coalesce(
    nullif(btrim(p_approved_name), ''),
    nullif(btrim(p_origin_name), ''),
    nullif(btrim(p_naver_name), ''),
    nullif(btrim(p_google_name), ''),
    ''
  );
$$;


--
-- Name: restaurant_evidence_recovery_admin(uuid, text, uuid, uuid, uuid, bigint, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_evidence_recovery_admin(p_actor uuid, p_phase text, p_operation_id uuid, p_job_id uuid, p_restaurant_id uuid, p_policy_version bigint, p_row_sha256 text, p_input_sha256 text, p_preview_hash text DEFAULT NULL::text, p_confirmation text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $_$
<<recovery_admin>>
DECLARE job pipeline_control.restaurant_evidence_recovery_jobs; op pipeline_control.admin_record_operations;
 row_value jsonb; expected jsonb; after_state jsonb; payload jsonb; digest text; action text; receipt jsonb;
 audit uuid; is_request boolean; is_retire boolean; changed public.restaurants; prior jsonb;
 policy pipeline_control.restaurant_review_policy; retirement_version bigint; retirement_reason text;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pipeline_control.assert_restaurant_review_operator(p_actor);
 IF p_phase='read' THEN
  SELECT * INTO job FROM pipeline_control.restaurant_evidence_recovery_jobs WHERE id=p_job_id AND actor=p_actor;
  SELECT o.* INTO op FROM pipeline_control.admin_record_operations o WHERE o.id=p_operation_id AND o.actor=p_actor
    AND o.action IN ('restaurant.evidence_recovery.request','restaurant.evidence_recovery.apply','restaurant.evidence_recovery.retire');
  IF job.id IS NULL AND op.id IS NULL THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_NOT_FOUND'; END IF;
  IF op.id IS NOT NULL AND (op.target_ids IS DISTINCT FROM ARRAY[p_restaurant_id] OR
    op.receipt->>'jobId' IS DISTINCT FROM p_job_id::text) THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_IDEMPOTENCY_CONFLICT'; END IF;
  IF job.id IS NOT NULL THEN RETURN pipeline_control.evidence_recovery_metadata(job,op.receipt); END IF;
  job.id:=p_job_id;job.restaurant_id:=p_restaurant_id;job.state:='preview';job.reason:='request_preview';
  job.policy_version:=(op.receipt->>'policyVersion')::bigint;job.row_sha256:=op.receipt->>'rowSha256';
  job.input_sha256:=op.receipt->>'inputSha256';job.video_id:=op.receipt->>'videoId';
  RETURN pipeline_control.evidence_recovery_metadata(job,op.receipt);
 END IF;
 IF p_phase IS NULL OR p_phase NOT IN ('preview_request','request','preview_apply','apply','preview_retire','retire') OR
   p_operation_id IS NULL OR p_job_id IS NULL OR p_restaurant_id IS NULL OR p_policy_version IS NULL OR
   coalesce(p_row_sha256,'') !~ '^[a-f0-9]{64}$' OR coalesce(p_input_sha256,'') !~ '^[a-f0-9]{64}$'
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_INVALID_PAYLOAD'; END IF;
 is_request:=p_phase IN ('preview_request','request');
 is_retire:=p_phase IN ('preview_retire','retire');
 action:=CASE WHEN is_request THEN 'restaurant.evidence_recovery.request' WHEN is_retire THEN 'restaurant.evidence_recovery.retire' ELSE 'restaurant.evidence_recovery.apply' END;
 IF p_phase LIKE 'preview_%' THEN
  IF p_preview_hash IS NOT NULL OR p_confirmation IS NOT NULL THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_INVALID_PAYLOAD'; END IF;
 ELSIF p_confirmation IS DISTINCT FROM (CASE WHEN is_request THEN 'REQUEST EVIDENCE RECOVERY' WHEN is_retire THEN 'RETIRE STALE EVIDENCE RECOVERY' ELSE 'APPLY EVIDENCE RECOVERY' END)
   OR coalesce(p_preview_hash,'') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_CONFIRMATION_REQUIRED'; END IF;
 SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton FOR UPDATE;
 LOCK TABLE public.restaurants IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO job FROM pipeline_control.restaurant_evidence_recovery_jobs WHERE id=p_job_id FOR UPDATE;
 SELECT * INTO op FROM pipeline_control.admin_record_operations WHERE id=p_operation_id FOR UPDATE;
 payload:=jsonb_build_object('schemaVersion',1,'jobId',p_job_id,'restaurantId',p_restaurant_id,'policyVersion',p_policy_version,
  'rowSha256',p_row_sha256,'inputSha256',p_input_sha256,'resultSha256',CASE WHEN is_request THEN NULL ELSE job.result_sha256 END);
 IF is_retire THEN
  retirement_version:=CASE WHEN op.id IS NULL THEN policy.version ELSE (op.receipt->>'retirementPolicyVersion')::bigint END;
  payload:=payload||jsonb_build_object('retirementPolicyVersion',retirement_version);
 END IF;
 digest:=pipeline_control.admin_record_hash(payload);
 IF op.id IS NOT NULL THEN
  IF op.actor IS DISTINCT FROM p_actor OR op.action IS DISTINCT FROM action OR op.target_ids IS DISTINCT FROM ARRAY[p_restaurant_id]
    OR op.payload_sha IS DISTINCT FROM digest THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_IDEMPOTENCY_CONFLICT'; END IF;
  IF p_phase NOT LIKE 'preview_%' AND op.preview_hash IS DISTINCT FROM p_preview_hash THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_PREVIEW_MISMATCH'; END IF;
  -- Lost ACK reconciliation returns the same operation, even if policy/source later changed.
  IF op.state='applied' THEN RETURN pipeline_control.evidence_recovery_metadata(job,op.receipt); END IF;
  IF op.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_PREVIEW_EXPIRED'; END IF;
 ELSIF p_phase NOT LIKE 'preview_%' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_PREVIEW_REQUIRED'; END IF;
 IF job.id IS NOT NULL AND (job.restaurant_id IS DISTINCT FROM p_restaurant_id OR job.actor IS DISTINCT FROM p_actor
   OR job.policy_version IS DISTINCT FROM p_policy_version OR job.row_sha256 IS DISTINCT FROM p_row_sha256
   OR job.input_sha256 IS DISTINCT FROM p_input_sha256) THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_IDEMPOTENCY_CONFLICT'; END IF;
 IF is_request AND job.id IS NOT NULL THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_JOB_EXISTS'; END IF;
 IF NOT is_request AND (job.id IS NULL OR job.state<>'draft' OR job.result_sha256 IS NULL) THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_DRAFT_REQUIRED'; END IF;
 IF is_retire THEN
  -- A completed, confirmed draft only. Preserve paid work; never adopt a
  -- running/uncertain/applied job or disguise a successful evidence apply.
  IF retirement_version IS DISTINCT FROM policy.version THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_POLICY_CHANGED'; END IF;
  SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE r.id=p_restaurant_id;
  row_value:=pipeline_control.evidence_recovery_guard(p_actor,p_restaurant_id,policy.version,
    pipeline_control.admin_record_hash(row_value),pipeline_control.evidence_recovery_input_sha(row_value),p_job_id);
  IF EXISTS(SELECT 1 FROM pipeline_control.admin_record_operations o WHERE o.target_ids=ARRAY[p_restaurant_id]
    AND o.action='restaurant.evidence_recovery.apply' AND o.receipt->>'jobId'=p_job_id::text
    AND (o.state='applied' OR o.receipt->>'state'='applied'
      OR EXISTS(SELECT 1 FROM pipeline_control.admin_record_audit a WHERE a.operation_id=o.id)))
  THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_STATE_CONFLICT'; END IF;
  retirement_reason:=CASE WHEN job.policy_version IS DISTINCT FROM policy.version THEN 'policy_changed'
    WHEN job.row_sha256 IS DISTINCT FROM pipeline_control.admin_record_hash(row_value)
      OR job.input_sha256 IS DISTINCT FROM pipeline_control.evidence_recovery_input_sha(row_value) THEN 'source_changed' END;
  IF retirement_reason IS NULL THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_STATE_CONFLICT'; END IF;
 ELSE
  row_value:=pipeline_control.evidence_recovery_guard(p_actor,p_restaurant_id,p_policy_version,p_row_sha256,p_input_sha256,
    CASE WHEN is_request THEN NULL ELSE p_job_id END);
 END IF;
 expected:=pipeline_control.admin_record_snapshot('restaurant.edit',ARRAY[p_restaurant_id]);
 IF op.id IS NOT NULL AND op.expected IS DISTINCT FROM expected THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_STALE'; END IF;
 IF NOT is_request THEN
  IF pipeline_control.admin_record_hash(job.result) IS DISTINCT FROM job.result_sha256 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_CHANGED'; END IF;
  PERFORM pipeline_control.evidence_recovery_validate_result(job.result,job.original_row,job.input_sha256);
 END IF;
 IF p_phase LIKE 'preview_%' THEN
  IF op.id IS NULL THEN
   receipt:=jsonb_build_object('operationId',p_operation_id,'action',action,'state','preview','targetIds',ARRAY[p_restaurant_id],
   'jobId',p_job_id,'auditId',NULL,'previewHash',pipeline_control.admin_record_hash(jsonb_build_array(p_actor,p_operation_id,action,digest,expected)),
   'expiresAt',clock_timestamp()+interval '15 minutes','readback',pipeline_control.admin_record_readback(expected),'mediaCleanupPending',false,
   'policyVersion',p_policy_version,'rowSha256',p_row_sha256,'inputSha256',p_input_sha256,
   'videoId',public.extract_youtube_video_id(row_value->>'youtube_link'));
   IF is_retire THEN receipt:=receipt||jsonb_build_object('retirementPolicyVersion',retirement_version,
    'videoId',job.video_id); END IF;
   INSERT INTO pipeline_control.admin_record_operations(id,actor,action,target_ids,payload_sha,expected,preview_hash,expires_at,state,receipt)
   VALUES(p_operation_id,p_actor,action,ARRAY[p_restaurant_id],digest,expected,receipt->>'previewHash',(receipt->>'expiresAt')::timestamptz,'preview',receipt);
  ELSE receipt:=op.receipt; END IF;
  -- Preview has no job/provider effect. The receipt's jobId binds the later request.
  IF is_request THEN
   job.id:=p_job_id;job.restaurant_id:=p_restaurant_id;job.state:='preview';job.reason:='request_preview';
   job.policy_version:=p_policy_version;job.row_sha256:=p_row_sha256;job.input_sha256:=p_input_sha256;
   job.video_id:=public.extract_youtube_video_id(row_value->>'youtube_link');
  END IF;
  RETURN pipeline_control.evidence_recovery_metadata(job,receipt);
 END IF;
 IF is_request THEN
  INSERT INTO pipeline_control.restaurant_evidence_recovery_jobs(id,restaurant_id,actor,policy_version,row_sha256,input_sha256,
   video_id,original_row,request_operation_id,state,reason)
   VALUES(p_job_id,p_restaurant_id,p_actor,p_policy_version,p_row_sha256,p_input_sha256,
    public.extract_youtube_video_id(row_value->>'youtube_link'),
    (SELECT jsonb_object_agg(key,value) FROM jsonb_each(row_value) WHERE key=ANY(ARRAY[
      'id','status','origin_name','approved_name','naver_name','google_name','trace_id','trace_id_name_source',
      'channel_name','youtube_link','youtube_meta','reasoning_basis','tzuyang_review','origin_address','recollect_version',
      'source_type','is_missing','is_not_selected','evaluation_results','geocoding_success','geocoding_false_stage',
      'lat','lng','road_address','jibun_address','english_address','address_elements','categories'])),
    p_operation_id,'queued','queued') RETURNING * INTO job;
 ELSIF is_retire THEN
  UPDATE pipeline_control.restaurant_evidence_recovery_jobs SET state='failed',reason=retirement_reason,finished_at=clock_timestamp()
   WHERE id=p_job_id RETURNING * INTO job;
 ELSE
  prior:=row_value;
  changed:=jsonb_populate_record(NULL::public.restaurants,row_value||(job.result-'gemini_decision'));
  UPDATE public.restaurants SET evaluation_results=changed.evaluation_results,geocoding_success=changed.geocoding_success,
   geocoding_false_stage=changed.geocoding_false_stage,lat=changed.lat,lng=changed.lng,road_address=changed.road_address,
   jibun_address=changed.jibun_address,english_address=changed.english_address,address_elements=changed.address_elements,
   naver_name=changed.naver_name,google_name=changed.google_name,categories=changed.categories,
   updated_by_admin_id=p_actor,updated_at=clock_timestamp() WHERE id=p_restaurant_id;
  SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE r.id=p_restaurant_id;
  IF (row_value-ARRAY['evaluation_results','geocoding_success','geocoding_false_stage','lat','lng','road_address',
    'jibun_address','english_address','address_elements','naver_name','google_name','categories','updated_by_admin_id','updated_at'])
    IS DISTINCT FROM (prior-ARRAY['evaluation_results','geocoding_success','geocoding_false_stage','lat','lng','road_address',
    'jibun_address','english_address','address_elements','naver_name','google_name','categories','updated_by_admin_id','updated_at'])
    OR EXISTS(SELECT 1 FROM jsonb_each(job.result-'gemini_decision') item WHERE row_value->item.key IS DISTINCT FROM item.value)
    OR row_value->>'status' IS DISTINCT FROM 'hold' OR row_value->>'updated_by_admin_id' IS DISTINCT FROM p_actor::text
  THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_READBACK_FAILED'; END IF;
  UPDATE pipeline_control.restaurant_evidence_recovery_jobs SET state='applied',reason='evidence_applied',finished_at=clock_timestamp()
   WHERE id=p_job_id RETURNING * INTO job;
 END IF;
 after_state:=pipeline_control.admin_record_snapshot('restaurant.edit',ARRAY[p_restaurant_id]);
 IF is_retire AND after_state IS DISTINCT FROM expected THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_READBACK_FAILED'; END IF;
 audit:=gen_random_uuid();
 INSERT INTO pipeline_control.admin_record_audit(id,operation_id,actor,action,target_ids,payload_sha,before_fingerprints,after_fingerprints)
  VALUES(audit,p_operation_id,p_actor,action,ARRAY[p_restaurant_id],digest,expected,after_state);
 receipt:=op.receipt||jsonb_build_object('state','applied','auditId',audit,'readback',pipeline_control.admin_record_readback(after_state));
 UPDATE pipeline_control.admin_record_operations SET state='applied',receipt=recovery_admin.receipt WHERE id=p_operation_id;
 RETURN pipeline_control.evidence_recovery_metadata(job,receipt);
END $_$;


--
-- Name: restaurant_evidence_recovery_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_evidence_recovery_context(p_actor uuid, p_restaurant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
DECLARE row_value jsonb; version bigint;
BEGIN
 SELECT policy.version INTO version FROM pipeline_control.restaurant_review_policy policy WHERE singleton;
 SELECT to_jsonb(r) INTO row_value FROM public.restaurants r WHERE r.id=p_restaurant_id;
 row_value:=pipeline_control.evidence_recovery_guard(p_actor,p_restaurant_id,version,
   pipeline_control.admin_record_hash(row_value),pipeline_control.evidence_recovery_input_sha(row_value),NULL);
 RETURN jsonb_build_object('schemaVersion',1,'restaurantId',p_restaurant_id,'policyVersion',version,
  'rowSha256',pipeline_control.admin_record_hash(row_value),'inputSha256',pipeline_control.evidence_recovery_input_sha(row_value),
  'videoId',public.extract_youtube_video_id(row_value->>'youtube_link'),
  'originName',row_value->>'origin_name','sourceUpdatedAt',row_value->>'updated_at');
END $$;


--
-- Name: restaurant_evidence_recovery_status(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_evidence_recovery_status(p_actor uuid, p_restaurant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE jobs jsonb:='[]'; job pipeline_control.restaurant_evidence_recovery_jobs;
 apply_id uuid; retire_id uuid; metadata jsonb; entry record; op pipeline_control.admin_record_operations;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pipeline_control.assert_restaurant_review_operator(p_actor);
 FOR entry IN
  SELECT * FROM (
   SELECT j.created_at,j.id AS sort_id,j.id AS job_id,NULL::uuid AS preview_id
    FROM pipeline_control.restaurant_evidence_recovery_jobs j WHERE j.restaurant_id=p_restaurant_id AND j.actor=p_actor
   UNION ALL
   SELECT o.created_at,o.id,NULL::uuid,o.id FROM pipeline_control.admin_record_operations o
    WHERE o.actor=p_actor AND o.action='restaurant.evidence_recovery.request' AND o.state='preview'
     AND o.expires_at>clock_timestamp() AND o.target_ids=ARRAY[p_restaurant_id]
     AND NOT EXISTS(SELECT 1 FROM pipeline_control.restaurant_evidence_recovery_jobs j WHERE j.id::text=o.receipt->>'jobId')
  ) candidates ORDER BY created_at DESC,sort_id DESC LIMIT 5
 LOOP
  IF entry.preview_id IS NOT NULL THEN
   SELECT * INTO op FROM pipeline_control.admin_record_operations WHERE id=entry.preview_id;
   job:=NULL;job.id:=(op.receipt->>'jobId')::uuid;job.restaurant_id:=p_restaurant_id;
   job.state:='preview';job.reason:='request_preview';job.policy_version:=(op.receipt->>'policyVersion')::bigint;
   job.row_sha256:=op.receipt->>'rowSha256';job.input_sha256:=op.receipt->>'inputSha256';job.video_id:=op.receipt->>'videoId';
   metadata:=pipeline_control.evidence_recovery_metadata(job)||jsonb_build_object('requestOperationId',op.id,'applyOperationId',NULL,'retireOperationId',NULL,'proposal',NULL);
   jobs:=jobs||jsonb_build_array(metadata);
   CONTINUE;
  END IF;
  SELECT * INTO job FROM pipeline_control.restaurant_evidence_recovery_jobs WHERE id=entry.job_id;
  SELECT o.id INTO apply_id FROM pipeline_control.admin_record_operations o
   WHERE o.actor=p_actor AND o.action='restaurant.evidence_recovery.apply' AND o.receipt->>'jobId'=job.id::text
    AND o.target_ids=ARRAY[p_restaurant_id] ORDER BY o.created_at DESC,o.id DESC LIMIT 1;
  SELECT o.id INTO retire_id FROM pipeline_control.admin_record_operations o
   WHERE o.actor=p_actor AND o.action='restaurant.evidence_recovery.retire' AND o.receipt->>'jobId'=job.id::text
    AND o.target_ids=ARRAY[p_restaurant_id] ORDER BY o.created_at DESC,o.id DESC LIMIT 1;
  metadata:=pipeline_control.evidence_recovery_metadata(job)||
   jsonb_build_object('requestOperationId',job.request_operation_id,'applyOperationId',apply_id,'retireOperationId',retire_id,'proposal',NULL);
  IF job.state='draft' THEN
   IF pipeline_control.admin_record_hash(job.result) IS DISTINCT FROM job.result_sha256 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_CHANGED'; END IF;
   PERFORM pipeline_control.evidence_recovery_validate_result(job.result,job.original_row,job.input_sha256);
   metadata:=metadata||jsonb_build_object('proposal',job.result-'gemini_decision');
  END IF;
  jobs:=jobs||jsonb_build_array(metadata);
 END LOOP;
 RETURN jsonb_build_object('schemaVersion',1,'restaurantId',p_restaurant_id,'jobs',jobs);
END $$;


--
-- Name: restaurant_evidence_recovery_worker(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_evidence_recovery_worker(p_phase text, p_job_id uuid, p_token uuid, p_result jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
DECLARE job pipeline_control.restaurant_evidence_recovery_jobs; code text; row_value jsonb;
 policy pipeline_control.restaurant_review_policy;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_phase IS NULL OR p_phase NOT IN ('next','claim','complete','fail','read') OR p_token IS NULL
   OR (p_phase<>'next' AND p_job_id IS NULL) OR (p_phase='next' AND p_job_id IS NOT NULL)
 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_INVALID_PAYLOAD'; END IF;
 IF p_phase='next' THEN
  SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton;
  IF NOT FOUND OR NOT policy.enabled THEN RETURN NULL; END IF;
  PERFORM pipeline_control.assert_restaurant_review_operator(policy.operator_id);
  -- Read only: old-policy jobs stay discoverable so claim can retire only a
  -- confirmed unspent request. Concurrent readers do not acquire a paid lease.
  SELECT * INTO job FROM pipeline_control.restaurant_evidence_recovery_jobs
   WHERE state='queued' AND worker_token IS NULL ORDER BY created_at,id LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN pipeline_control.evidence_recovery_metadata(job);
 END IF;
 IF p_phase<>'read' THEN
  PERFORM 1 FROM pipeline_control.restaurant_review_policy WHERE singleton FOR UPDATE;
  LOCK TABLE public.restaurants IN SHARE ROW EXCLUSIVE MODE;
 END IF;
 SELECT * INTO job FROM pipeline_control.restaurant_evidence_recovery_jobs WHERE id=p_job_id
  AND (worker_token IS NULL OR worker_token=p_token) FOR UPDATE;
 IF job.id IS NULL THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_NOT_FOUND'; END IF;
 IF p_phase='read' THEN RETURN pipeline_control.evidence_recovery_metadata(job); END IF;
 IF p_phase='claim' THEN
  -- A repeated claim returns metadata only. Expired/uncertain work is never reclaimed.
  IF job.state<>'queued' THEN RETURN pipeline_control.evidence_recovery_metadata(job); END IF;
  IF job.worker_token IS NOT NULL THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_STATE_CONFLICT'; END IF;
  BEGIN
   row_value:=pipeline_control.evidence_recovery_guard(job.actor,job.restaurant_id,job.policy_version,job.row_sha256,job.input_sha256,job.id);
  EXCEPTION WHEN OTHERS THEN
   GET STACKED DIAGNOSTICS code=MESSAGE_TEXT;
   IF code NOT IN ('EVIDENCE_RECOVERY_STALE','EVIDENCE_RECOVERY_PROTECTED',
     'EVIDENCE_RECOVERY_SOURCE_REQUIRED','EVIDENCE_RECOVERY_POLICY_CHANGED') THEN RAISE; END IF;
   UPDATE pipeline_control.restaurant_evidence_recovery_jobs SET state='failed',
    reason=CASE WHEN code='EVIDENCE_RECOVERY_POLICY_CHANGED' THEN 'policy_changed' ELSE 'source_changed' END,
    finished_at=clock_timestamp() WHERE id=p_job_id AND state='queued' AND worker_token IS NULL RETURNING * INTO job;
   RETURN pipeline_control.evidence_recovery_metadata(job);
  END;
  UPDATE pipeline_control.restaurant_evidence_recovery_jobs SET state='running',reason='claimed',worker_token=p_token,
   lease_until=clock_timestamp()+interval '60 minutes' WHERE id=p_job_id RETURNING * INTO job;
  RETURN pipeline_control.evidence_recovery_metadata(job)||jsonb_build_object('restaurant',row_value,
   'decisionContext',jsonb_build_object('inputSha256',job.input_sha256));
 END IF;
 IF job.worker_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_NOT_FOUND'; END IF;
 IF p_phase='complete' AND job.state IN ('draft','applied') THEN
  IF pipeline_control.admin_record_hash(p_result) IS DISTINCT FROM job.result_sha256 THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_RESULT_CHANGED'; END IF;
  RETURN pipeline_control.evidence_recovery_metadata(job);
 END IF;
 IF p_phase='fail' AND job.state IN ('failed','uncertain') THEN
  IF p_result IS DISTINCT FROM jsonb_build_object('code',job.reason) THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_STATE_CONFLICT'; END IF;
  RETURN pipeline_control.evidence_recovery_metadata(job);
 END IF;
 IF job.state<>'running' THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_STATE_CONFLICT'; END IF;
 IF p_phase='fail' THEN
  code:=p_result->>'code';
  IF jsonb_typeof(p_result) IS DISTINCT FROM 'object' OR p_result IS DISTINCT FROM jsonb_build_object('code',code)
    OR code IS NULL OR code NOT IN ('source_unavailable','gemini_configuration_invalid','evaluation_incomplete',
      'result_invalid','evaluation_failed','gemini_result_uncertain','gemini_decision_invalid','gemini_decision_incomplete','worker_timeout',
      'source_incomplete','source_local_missing','source_input_invalid','source_identity_mismatch','source_recollect_mismatch',
      'source_channel_unverified','source_original_evidence_missing','source_provider_transient','source_provider_unavailable','result_unconfirmed')
  THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_INVALID_PAYLOAD'; END IF;
  -- Only known pre-provider failures are retryable by a later explicit request.
  -- No lease expiry or generic failure asserts that a paid attempt did not occur.
  UPDATE pipeline_control.restaurant_evidence_recovery_jobs SET
   state=CASE WHEN code IN ('source_unavailable','gemini_configuration_invalid','source_incomplete','source_local_missing',
    'source_input_invalid','source_identity_mismatch','source_recollect_mismatch','source_channel_unverified',
    'source_original_evidence_missing','source_provider_transient','source_provider_unavailable') THEN 'failed' ELSE 'uncertain' END,
   reason=code,finished_at=clock_timestamp() WHERE id=p_job_id RETURNING * INTO job;
  RETURN pipeline_control.evidence_recovery_metadata(job);
 END IF;
 IF job.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'EVIDENCE_RECOVERY_LEASE_EXPIRED'; END IF;
 PERFORM pipeline_control.evidence_recovery_guard(job.actor,job.restaurant_id,job.policy_version,job.row_sha256,job.input_sha256,job.id);
 PERFORM pipeline_control.evidence_recovery_validate_result(p_result,job.original_row,job.input_sha256);
 UPDATE pipeline_control.restaurant_evidence_recovery_jobs SET state='draft',reason='evidence_ready',result=p_result,
  result_sha256=pipeline_control.admin_record_hash(p_result),finished_at=clock_timestamp() WHERE id=p_job_id RETURNING * INTO job;
 RETURN pipeline_control.evidence_recovery_metadata(job);
END $$;


--
-- Name: restaurant_review_automation_configure(uuid, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_review_automation_configure(actor uuid, action text, expected_version text, preview_hash text, batch_size integer, daily_limit integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE policy pipeline_control.restaurant_review_policy; expected_hash text;
BEGIN
  PERFORM pipeline_control.assert_restaurant_review_operator(actor);
  SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton FOR UPDATE;
  IF expected_version IS DISTINCT FROM policy.version::text THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_STALE'; END IF;
  IF action='start' THEN
    IF batch_size IS NULL OR batch_size NOT BETWEEN 1 AND 200 OR daily_limit IS NULL OR daily_limit NOT BETWEEN 1 AND 200
      THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_LIMIT_INVALID'; END IF;
    -- The revision row serializes source mutations with activation.
    PERFORM 1 FROM pipeline_control.admin_evaluation_catalog_revision WHERE singleton FOR UPDATE;
    expected_hash:=md5(actor::text||':'||policy.version::text||':'||public.admin_evaluation_revision()||':'||batch_size::text||':'||daily_limit::text);
    IF preview_hash IS DISTINCT FROM expected_hash THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_STALE'; END IF;
    UPDATE pipeline_control.restaurant_review_policy SET enabled=true,operator_id=actor,version=version+1,
      batch_size=restaurant_review_automation_configure.batch_size,daily_limit=restaurant_review_automation_configure.daily_limit WHERE singleton;
  ELSIF action='stop' THEN
    UPDATE pipeline_control.restaurant_review_policy SET enabled=false,version=version+1 WHERE singleton;
    UPDATE pipeline_control.restaurant_review_items SET state='cancelled',finished_at=now() WHERE state IN ('queued','running');
  ELSE RAISE EXCEPTION 'REVIEW_AUTOMATION_ACTION_INVALID'; END IF;
  INSERT INTO pipeline_control.restaurant_review_policy_events(version,operator_id,action) VALUES(policy.version+1,actor,action);
  RETURN public.restaurant_review_automation_status();
END;
$$;


--
-- Name: restaurant_review_automation_manual(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_review_automation_manual(actor uuid, action text, expected_version text, preview_hash text, request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
DECLARE policy pipeline_control.restaurant_review_policy; preview jsonb; result jsonb;
BEGIN
  PERFORM pipeline_control.assert_restaurant_review_operator(actor);
  IF action IN ('preview-run','preview-stop') THEN
    RETURN pipeline_control.restaurant_review_manual_preview(actor,substring(action from 9));
  END IF;
  IF action NOT IN ('run','stop') OR action IS NULL THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_ACTION_INVALID'; END IF;
  SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton FOR UPDATE;
  -- Read a committed request before checking a now-stale preview. A lost response
  -- must not cause a second run or erase the original committed result.
  IF action='run' THEN
    IF request_id IS NULL THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_REQUEST_INVALID'; END IF;
    SELECT to_jsonb(existing) INTO result FROM pipeline_control.restaurant_review_runs existing
      WHERE existing.request_id=restaurant_review_automation_manual.request_id;
    IF FOUND THEN RETURN public.restaurant_review_automation_status()||jsonb_build_object('run',result); END IF;
  END IF;
  LOCK TABLE public.restaurants IN SHARE ROW EXCLUSIVE MODE;
  PERFORM pipeline_control.lock_restaurant_review_catalog_revision();
  preview:=pipeline_control.restaurant_review_manual_preview(actor,action);
  IF expected_version IS DISTINCT FROM preview->>'version' OR preview_hash IS DISTINCT FROM preview->>'previewHash'
    THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_STALE'; END IF;
  IF action='run' THEN
    result:=public.restaurant_review_automation_tick(request_id);
    RETURN public.restaurant_review_automation_status()||jsonb_build_object('run',result);
  END IF;
  RETURN public.restaurant_review_automation_configure(actor,'stop',expected_version,'',policy.batch_size,policy.daily_limit);
END;
$$;


--
-- Name: restaurant_review_automation_preview(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_review_automation_preview(actor uuid, batch_size integer, daily_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE revision text; version bigint; counts jsonb;
BEGIN
  PERFORM pipeline_control.assert_restaurant_review_operator(actor);
  IF (SELECT count(*) FROM (SELECT 1 FROM public.restaurants LIMIT 50001) bounded)>50000
    THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_CAPACITY_EXCEEDED'; END IF;
  IF batch_size IS NULL OR batch_size NOT BETWEEN 1 AND 200 OR daily_limit IS NULL OR daily_limit NOT BETWEEN 1 AND 200
    THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_LIMIT_INVALID'; END IF;
  SELECT policy.version INTO version FROM pipeline_control.restaurant_review_policy policy WHERE singleton;
  revision:=public.admin_evaluation_revision();
  SELECT coalesce(jsonb_object_agg(decision,total),'{}'::jsonb) INTO counts FROM (
    SELECT split_part(pipeline_control.restaurant_review_decision(to_jsonb(restaurant)),':',1) decision,count(*) total
    FROM public.restaurants restaurant WHERE restaurant.status='pending' GROUP BY 1
  ) grouped;
  RETURN jsonb_build_object('version',version::text,'revision',revision,'counts',counts,'batchSize',batch_size,'dailyLimit',daily_limit,
    'previewHash',md5(actor::text||':'||version::text||':'||revision||':'||batch_size::text||':'||daily_limit::text));
END;
$$;


--
-- Name: restaurant_review_automation_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_review_automation_status() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
SELECT jsonb_build_object('policy',(SELECT to_jsonb(policy)-'operator_id' FROM pipeline_control.restaurant_review_policy policy WHERE singleton),
 'runs',coalesce((SELECT jsonb_agg(to_jsonb(run) ORDER BY run.started_at DESC) FROM (SELECT * FROM pipeline_control.restaurant_review_runs ORDER BY started_at DESC LIMIT 10) run),'[]'::jsonb),
 'items',coalesce((SELECT jsonb_agg((to_jsonb(item)-ARRAY['worker_token','fingerprint','applied_fingerprint','input_sha256','gemini_decision'])||jsonb_build_object('geminiDecision',item.gemini_decision) ORDER BY item.created_at DESC) FROM
   (SELECT item.*,left(coalesce(restaurant.approved_name,restaurant.origin_name,restaurant.naver_name,'삭제된 항목'),160) AS restaurant_name
     FROM pipeline_control.restaurant_review_items item LEFT JOIN public.restaurants restaurant ON restaurant.id=item.restaurant_id ORDER BY item.created_at DESC,item.id DESC LIMIT 20) item),'[]'::jsonb),
 'queue',jsonb_build_object('queued',(SELECT count(*) FROM pipeline_control.restaurant_review_items WHERE state='queued'),'running',(SELECT count(*) FROM pipeline_control.restaurant_review_items WHERE state='running'),'failed',(SELECT count(*) FROM pipeline_control.restaurant_review_items WHERE state='failed')),
 'policyEvents',coalesce((SELECT jsonb_agg(jsonb_build_object('id',event.id,'version',event.version,'action',event.action,'created_at',event.created_at)) FROM (SELECT * FROM pipeline_control.restaurant_review_policy_events ORDER BY created_at DESC LIMIT 10) event),'[]'::jsonb),
 'judgmentEngine',jsonb_build_object('provider','gemini','model','gemini-3.8-flash','promptVersion','restaurant-review-v1','requiredForApproval',true,'maxCallsPerClaim',1));
$$;


--
-- Name: restaurant_review_automation_tick(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_review_automation_tick(request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
<<deferred_tick>>
DECLARE policy pipeline_control.restaurant_review_policy; run pipeline_control.restaurant_review_runs;
 restaurant public.restaurants; previous pipeline_control.restaurant_review_items;
 data jsonb; v_fingerprint text; classification text; decision text; reason text; remaining integer;
BEGIN
 IF request_id IS NULL THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_REQUEST_INVALID'; END IF;
 SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton FOR UPDATE;
 SELECT * INTO run FROM pipeline_control.restaurant_review_runs r WHERE r.request_id=restaurant_review_automation_tick.request_id;
 IF FOUND THEN RETURN to_jsonb(run); END IF;
 IF NOT policy.enabled THEN RETURN jsonb_build_object('disabled',true); END IF;
 PERFORM pipeline_control.assert_restaurant_review_operator(policy.operator_id);
 LOCK TABLE public.restaurants IN SHARE ROW EXCLUSIVE MODE;
 SELECT greatest(0,policy.daily_limit-count(*)) INTO remaining FROM pipeline_control.restaurant_review_items
   WHERE restaurant_review_items.decision='approve' AND state='applied' AND finished_at>=date_trunc('day',now() AT TIME ZONE 'Asia/Seoul') AT TIME ZONE 'Asia/Seoul';
 INSERT INTO pipeline_control.restaurant_review_runs(request_id,policy_version) VALUES(request_id,policy.version) RETURNING * INTO run;
 FOR restaurant IN SELECT candidate.* FROM public.restaurants candidate WHERE candidate.status='pending' AND (
   NOT EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items prior WHERE prior.restaurant_id=candidate.id
     AND (prior.fingerprint=pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate)) OR prior.applied_fingerprint=pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate))))
   OR EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items prior JOIN pipeline_control.restaurant_review_runs r ON r.id=prior.run_id
     WHERE prior.restaurant_id=candidate.id AND prior.applied_fingerprint=pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate))
       AND prior.state='succeeded' AND prior.reason='daily_limit' AND r.policy_version=policy.version))
   AND (remaining>0 OR pipeline_control.restaurant_review_decision(to_jsonb(candidate)) NOT LIKE 'approve:%')
   ORDER BY candidate.created_at,candidate.id LIMIT policy.batch_size FOR UPDATE
 LOOP
   data:=to_jsonb(restaurant);v_fingerprint:=pipeline_control.restaurant_review_fingerprint(data);
   classification:=pipeline_control.restaurant_review_decision(data);decision:=split_part(classification,':',1);reason:=split_part(classification,':',2);
   SELECT prior.* INTO previous FROM pipeline_control.restaurant_review_items prior JOIN pipeline_control.restaurant_review_runs r ON r.id=prior.run_id
     WHERE prior.restaurant_id=restaurant.id AND prior.applied_fingerprint=v_fingerprint AND prior.state='succeeded' AND prior.reason='daily_limit'
       AND r.policy_version=policy.version ORDER BY prior.created_at DESC LIMIT 1 FOR UPDATE OF prior;
   IF FOUND THEN
     IF decision='approve' AND remaining>0 AND previous.gemini_decision->>'recommendation'='approve'
       AND pipeline_control.restaurant_review_gemini_valid(previous.gemini_decision-ARRAY['outcome','decidedAt'],previous.input_sha256) THEN
       UPDATE public.restaurants SET status='approved',approved_name=coalesce(nullif(btrim(approved_name),''),nullif(btrim(naver_name),''),nullif(btrim(google_name),''),origin_name),
         updated_by_admin_id=policy.operator_id,updated_at=now() WHERE id=restaurant.id;
       IF NOT EXISTS(SELECT 1 FROM public.restaurants WHERE id=restaurant.id AND status='approved' AND updated_by_admin_id=policy.operator_id)
         THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_READBACK_FAILED'; END IF;
       UPDATE pipeline_control.restaurant_review_items SET state='applied',decision='approve',reason='gemini_approved',finished_at=now(),
         gemini_decision=gemini_decision||jsonb_build_object('outcome','approve') WHERE id=previous.id;
       run.approved:=run.approved+1;remaining:=remaining-1;
     ELSIF decision='approve' AND remaining=0 THEN
       -- The loop may have consumed the last slot after its candidate cursor
       -- opened. Keep the successful judgment deferred; never cancel or requeue it.
       NULL;
     ELSIF decision='hold' THEN
       UPDATE public.restaurants SET status='hold',updated_at=now() WHERE id=restaurant.id;
       IF NOT EXISTS(SELECT 1 FROM public.restaurants WHERE id=restaurant.id AND status='hold')
         THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_READBACK_FAILED'; END IF;
       UPDATE pipeline_control.restaurant_review_items SET state='applied',decision='hold',reason=deferred_tick.reason,
         finished_at=now(),applied_fingerprint=pipeline_control.restaurant_review_fingerprint(
           (SELECT to_jsonb(current_row) FROM public.restaurants current_row WHERE current_row.id=restaurant.id)),
         gemini_decision=gemini_decision||jsonb_build_object('outcome','hold') WHERE id=previous.id;
       run.held:=run.held+1;
     ELSIF decision='recheck' AND
       pipeline_control.restaurant_review_gemini_valid(previous.gemini_decision-ARRAY['outcome','decidedAt'],previous.input_sha256) THEN
       -- This is a new claim after a confirmed completed judgment, never a
       -- retry of uncertain provider work. Retire the old capability and bind
       -- the queue to the current row; one model call per claim stays unchanged.
       UPDATE pipeline_control.restaurant_review_items SET state='queued',decision='recheck',reason=deferred_tick.reason,
         fingerprint=v_fingerprint,applied_fingerprint=NULL,worker_token=NULL,lease_until=NULL,finished_at=NULL,
         gemini_decision=gemini_decision||jsonb_build_object('outcome','recheck') WHERE id=previous.id;
       run.recheck:=run.recheck+1;
     ELSE
       UPDATE pipeline_control.restaurant_review_items SET state='cancelled',reason='server_constraints',finished_at=now(),
         gemini_decision=gemini_decision||jsonb_build_object('outcome','blocked') WHERE id=previous.id;
       IF decision='protected' THEN run.protected:=run.protected+1; END IF;
     END IF;
   ELSE
     IF decision='approve' THEN decision:='recheck';reason:='gemini_decision_required'; END IF;
     IF decision='recheck' THEN run.recheck:=run.recheck+1;
     ELSIF decision='protected' THEN run.protected:=run.protected+1;
     ELSE
       UPDATE public.restaurants SET status='hold',updated_at=now() WHERE id=restaurant.id;
       IF NOT EXISTS(SELECT 1 FROM public.restaurants WHERE id=restaurant.id AND status='hold') THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_READBACK_FAILED'; END IF;
       run.held:=run.held+1;
     END IF;
     INSERT INTO pipeline_control.restaurant_review_items(run_id,restaurant_id,fingerprint,decision,reason,state,finished_at)
       VALUES(run.id,restaurant.id,v_fingerprint,decision,reason,CASE WHEN decision='recheck' THEN 'queued' ELSE 'applied' END,CASE WHEN decision='recheck' THEN NULL ELSE now() END);
   END IF;
   run.scanned:=run.scanned+1;
 END LOOP;
 UPDATE pipeline_control.restaurant_review_runs SET scanned=run.scanned,approved=run.approved,recheck=run.recheck,held=run.held,protected=run.protected WHERE id=run.id;
 UPDATE pipeline_control.restaurant_review_policy SET last_run_at=now() WHERE singleton;
 RETURN to_jsonb(run);
END; $$;


--
-- Name: restaurant_review_automation_worker(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_review_automation_worker(action text, item_id uuid, token uuid, result jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $$
DECLARE policy pipeline_control.restaurant_review_policy; item pipeline_control.restaurant_review_items; restaurant public.restaurants;
 fields text[]:=ARRAY['evaluation_results','geocoding_success','geocoding_false_stage','lat','lng','road_address','jibun_address','english_address','address_elements','naver_name','google_name','categories','gemini_decision'];
 recommendation jsonb; classification text; final_decision text; final_reason text; remaining integer; outcome text;
BEGIN
 IF token IS NULL THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_LEASE_INVALID'; END IF;
 SELECT * INTO policy FROM pipeline_control.restaurant_review_policy WHERE singleton FOR UPDATE;
 IF action='read' THEN
   SELECT * INTO item FROM pipeline_control.restaurant_review_items WHERE id=item_id AND worker_token=token;
   IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_LEASE_INVALID'; END IF;
   RETURN jsonb_build_object('state',item.state,'reason',item.reason,'geminiDecision',item.gemini_decision);
 END IF;
 IF NOT policy.enabled THEN RETURN jsonb_build_object('disabled',true); END IF;
 PERFORM pipeline_control.assert_restaurant_review_operator(policy.operator_id);
 IF action='claim' THEN
   UPDATE pipeline_control.restaurant_review_items SET state='failed',reason='worker_lease_expired',finished_at=now() WHERE state='running' AND lease_until<now();
   IF EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items WHERE state='running') THEN RETURN NULL; END IF;
   UPDATE pipeline_control.restaurant_review_items SET state='cancelled',reason='source_changed',finished_at=now() WHERE id IN (
     SELECT queued.id FROM pipeline_control.restaurant_review_items queued LEFT JOIN public.restaurants candidate ON candidate.id=queued.restaurant_id
     JOIN pipeline_control.restaurant_review_runs r ON r.id=queued.run_id
     WHERE queued.state='queued' AND (candidate.id IS NULL OR candidate.status<>'pending' OR candidate.updated_by_admin_id IS NOT NULL
       OR candidate.created_by IS NOT NULL OR r.policy_version<>policy.version OR pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate))<>queued.fingerprint)
     ORDER BY queued.created_at,queued.id LIMIT 200);
   SELECT queued.* INTO item FROM pipeline_control.restaurant_review_items queued JOIN public.restaurants candidate ON candidate.id=queued.restaurant_id
     JOIN pipeline_control.restaurant_review_runs r ON r.id=queued.run_id
     WHERE queued.state='queued' AND candidate.status='pending' AND candidate.updated_by_admin_id IS NULL AND candidate.created_by IS NULL
       AND r.policy_version=policy.version AND pipeline_control.restaurant_review_fingerprint(to_jsonb(candidate))=queued.fingerprint
     ORDER BY queued.created_at,queued.id LIMIT 1 FOR UPDATE OF queued,candidate SKIP LOCKED;
   IF NOT FOUND THEN RETURN NULL; END IF;
   SELECT * INTO restaurant FROM public.restaurants WHERE id=item.restaurant_id;
   UPDATE pipeline_control.restaurant_review_items SET state='running',worker_token=token,lease_until=now()+interval '60 minutes',
     input_sha256=encode(sha256(convert_to((to_jsonb(restaurant)-ARRAY['search_count','weekly_search_count','review_count','updated_at'])::text,'UTF8')),'hex')
     WHERE id=item.id RETURNING * INTO item;
   RETURN jsonb_build_object('id',item.id,'restaurant',to_jsonb(restaurant),'decisionContext',jsonb_build_object('inputSha256',item.input_sha256));
 END IF;
 SELECT * INTO item FROM pipeline_control.restaurant_review_items WHERE id=item_id FOR UPDATE;
 IF NOT FOUND OR item.worker_token IS DISTINCT FROM token THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_LEASE_INVALID'; END IF;
 IF item.state IN ('applied','succeeded','failed','cancelled') THEN RETURN jsonb_build_object('state',item.state); END IF;
 IF item.state<>'running' OR item.lease_until<now() THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_LEASE_INVALID'; END IF;
 IF (SELECT r.policy_version FROM pipeline_control.restaurant_review_runs r WHERE r.id=item.run_id)<>policy.version THEN
   UPDATE pipeline_control.restaurant_review_items SET state='cancelled',reason='policy_changed',finished_at=now() WHERE id=item.id;
   RETURN jsonb_build_object('state','cancelled');
 END IF;
 IF action='fail' THEN
   IF coalesce(result->>'code','') NOT IN ('source_unavailable','evaluation_failed','evaluation_incomplete','worker_timeout','result_invalid',
     'gemini_configuration_invalid','gemini_result_uncertain','gemini_decision_invalid','gemini_decision_incomplete') THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_RESULT_INVALID'; END IF;
   UPDATE pipeline_control.restaurant_review_items SET state='failed',reason=result->>'code',finished_at=now() WHERE id=item.id;
   RETURN jsonb_build_object('state','failed');
 END IF;
 IF action<>'complete' OR jsonb_typeof(result) IS DISTINCT FROM 'object' OR octet_length(result::text)>131072
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(result) k WHERE NOT k=ANY(fields)) THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_RESULT_INVALID'; END IF;
 recommendation:=result->'gemini_decision';
 IF NOT pipeline_control.restaurant_review_gemini_valid(recommendation,item.input_sha256) THEN
   UPDATE pipeline_control.restaurant_review_items SET state='failed',reason='gemini_decision_invalid',finished_at=now() WHERE id=item.id;
   RETURN jsonb_build_object('state','failed');
 END IF;
 LOCK TABLE public.restaurants IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO restaurant FROM public.restaurants WHERE id=item.restaurant_id FOR UPDATE;
 IF NOT FOUND OR pipeline_control.restaurant_review_fingerprint(to_jsonb(restaurant))<>item.fingerprint
   OR restaurant.updated_by_admin_id IS NOT NULL OR restaurant.created_by IS NOT NULL OR restaurant.status<>'pending' THEN
   UPDATE pipeline_control.restaurant_review_items SET state='cancelled',reason='source_changed',finished_at=now(),
     gemini_decision=recommendation||jsonb_build_object('outcome','blocked','decidedAt',now()) WHERE id=item.id;
   RETURN jsonb_build_object('state','cancelled');
 END IF;
 IF jsonb_typeof(result->'evaluation_results') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_RESULT_INVALID'; END IF;
 restaurant:=jsonb_populate_record(restaurant,result-'gemini_decision');
 -- Preserve the domain evaluation and its actual basis; only the separate
 -- judgment ledger is restricted to structured codes and hashes.
 classification:=pipeline_control.restaurant_review_decision(to_jsonb(restaurant));
 final_decision:=split_part(classification,':',1);final_reason:=split_part(classification,':',2);
 IF final_decision='protected' THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_PROTECTED'; END IF;
 IF recommendation->>'recommendation'='hold' THEN final_decision:='hold';final_reason:='gemini_hold';
 ELSIF recommendation->>'recommendation'='recheck' AND final_decision<>'hold' THEN final_decision:='recheck';final_reason:='gemini_recheck_required';
 END IF;
 SELECT greatest(0,policy.daily_limit-count(*)) INTO remaining FROM pipeline_control.restaurant_review_items WHERE decision='approve' AND state='applied'
   AND finished_at>=date_trunc('day',now() AT TIME ZONE 'Asia/Seoul') AT TIME ZONE 'Asia/Seoul';
 IF final_decision='approve' AND remaining=0 THEN final_reason:='daily_limit';outcome:='deferred';
 ELSE outcome:=final_decision; END IF;
 IF final_decision='approve' AND remaining>0 THEN
   restaurant.status:='approved';restaurant.approved_name:=coalesce(nullif(btrim(restaurant.approved_name),''),nullif(btrim(restaurant.naver_name),''),nullif(btrim(restaurant.google_name),''),restaurant.origin_name);
   restaurant.updated_by_admin_id:=policy.operator_id;final_reason:='gemini_approved';
 ELSIF final_decision='hold' THEN restaurant.status:='hold'; END IF;
 UPDATE public.restaurants SET evaluation_results=restaurant.evaluation_results,geocoding_success=restaurant.geocoding_success,
   geocoding_false_stage=restaurant.geocoding_false_stage,lat=restaurant.lat,lng=restaurant.lng,road_address=restaurant.road_address,
   jibun_address=restaurant.jibun_address,english_address=restaurant.english_address,address_elements=restaurant.address_elements,
   naver_name=restaurant.naver_name,google_name=restaurant.google_name,categories=restaurant.categories,status=restaurant.status,
   approved_name=restaurant.approved_name,updated_by_admin_id=restaurant.updated_by_admin_id,updated_at=now() WHERE id=item.restaurant_id RETURNING * INTO restaurant;
 IF NOT EXISTS(SELECT 1 FROM public.restaurants WHERE id=item.restaurant_id AND status=restaurant.status AND evaluation_results=restaurant.evaluation_results)
   THEN RAISE EXCEPTION 'REVIEW_AUTOMATION_READBACK_FAILED'; END IF;
 UPDATE pipeline_control.restaurant_review_items SET state=CASE WHEN outcome IN ('approve','hold') THEN 'applied' ELSE 'succeeded' END,
   decision=final_decision,reason=final_reason,finished_at=now(),applied_fingerprint=pipeline_control.restaurant_review_fingerprint(to_jsonb(restaurant)),
   gemini_decision=recommendation||jsonb_build_object('outcome',outcome,'decidedAt',now()) WHERE id=item.id RETURNING * INTO item;
 UPDATE pipeline_control.restaurant_review_runs SET approved=approved+CASE WHEN outcome='approve' THEN 1 ELSE 0 END,
   held=held+CASE WHEN outcome='hold' THEN 1 ELSE 0 END WHERE id=item.run_id;
 RETURN jsonb_build_object('state',item.state,'reason',item.reason,'geminiDecision',item.gemini_decision);
END; $$;


--
-- Name: review_admin_restaurant_map_overlay_proposal(uuid, uuid, text, text, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_admin_restaurant_map_overlay_proposal(p_actor_user_id uuid, p_proposal_id uuid, p_transition text, p_reason text, p_expected_proposal_hash text, p_correlation_id uuid, p_idempotency_key text, p_request_hash text, p_request_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_existing_event public.admin_restaurant_map_overlay_proposal_review_events%rowtype;
  v_proposal public.admin_restaurant_map_overlay_proposals%rowtype;
  v_now timestamptz := timezone('utc'::text, now());
  v_request_metadata jsonb := coalesce(p_request_metadata, '{}'::jsonb);
begin
  if auth.role() <> 'service_role' then
    raise exception 'trend_proposal_review_service_role_required';
  end if;

  if p_actor_user_id is null or p_proposal_id is null then
    raise exception 'invalid_trend_proposal_review_request';
  end if;

  if p_transition is null or p_transition not in ('rejected', 'superseded', 'expired') then
    raise exception 'invalid_trend_proposal_review_request';
  end if;

  if p_reason is null or char_length(trim(p_reason)) < 1 or char_length(trim(p_reason)) > 500 then
    raise exception 'trend_proposal_review_reason_required';
  end if;

  if p_expected_proposal_hash is null or p_expected_proposal_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_trend_proposal_review_request';
  end if;

  if p_request_hash is null or p_request_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_trend_proposal_review_request';
  end if;

  if p_correlation_id is null or p_idempotency_key is null or char_length(trim(p_idempotency_key)) < 8 or char_length(trim(p_idempotency_key)) > 128 then
    raise exception 'invalid_trend_proposal_review_request';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_actor_user_id::text || ':' || p_idempotency_key, 0));

  select *
    into v_existing_event
    from public.admin_restaurant_map_overlay_proposal_review_events
   where actor_user_id = p_actor_user_id
     and idempotency_key = p_idempotency_key;

  if found then
    if v_existing_event.proposal_id = p_proposal_id
       and v_existing_event.transition = p_transition
       and v_existing_event.correlation_id = p_correlation_id
       and v_existing_event.request_hash = p_request_hash
       and v_existing_event.proposal_hash = p_expected_proposal_hash then
      select *
        into v_proposal
        from public.admin_restaurant_map_overlay_proposals
       where id = v_existing_event.proposal_id;

      return jsonb_build_object(
        'ok', true,
        'status', v_existing_event.to_status,
        'replayed', true,
        'proposal', jsonb_build_object(
          'id', v_existing_event.proposal_id,
          'proposalStatus', coalesce(v_proposal.proposal_status, v_existing_event.to_status),
          'proposalHash', v_existing_event.proposal_hash,
          'reviewedByAdminId', v_existing_event.reviewed_by_admin_id,
          'reviewedAt', v_existing_event.created_at,
          'reviewReason', v_existing_event.reason
        ),
        'reviewEvent', jsonb_build_object(
          'eventId', v_existing_event.id,
          'transition', v_existing_event.transition,
          'fromStatus', v_existing_event.from_status,
          'toStatus', v_existing_event.to_status,
          'correlationId', v_existing_event.correlation_id,
          'idempotencyKey', v_existing_event.idempotency_key,
          'requestHash', v_existing_event.request_hash
        ),
        'readback', jsonb_build_object(
          'matchedRequestHash', true,
          'matchedProposalHash', true
        )
      );
    end if;

    raise exception 'trend_proposal_review_idempotency_conflict';
  end if;

  select *
    into v_proposal
    from public.admin_restaurant_map_overlay_proposals
   where id = p_proposal_id
   for update;

  if not found then
    raise exception 'trend_proposal_not_found';
  end if;

  if v_proposal.proposal_hash <> p_expected_proposal_hash then
    raise exception 'trend_proposal_hash_stale';
  end if;

  if v_proposal.proposal_status <> 'pending' then
    raise exception 'trend_proposal_not_pending';
  end if;

  update public.admin_restaurant_map_overlay_proposals
     set proposal_status = p_transition,
         reviewed_by_admin_id = p_actor_user_id,
         reviewed_at = v_now,
         review_reason = trim(p_reason)
   where id = p_proposal_id
   returning * into v_proposal;

  insert into public.admin_restaurant_map_overlay_proposal_review_events (
    proposal_id,
    actor_user_id,
    transition,
    from_status,
    to_status,
    reason,
    correlation_id,
    idempotency_key,
    request_hash,
    proposal_hash,
    request_metadata,
    reviewed_by_admin_id,
    created_at
  ) values (
    p_proposal_id,
    p_actor_user_id,
    p_transition,
    'pending',
    p_transition,
    trim(p_reason),
    p_correlation_id,
    trim(p_idempotency_key),
    p_request_hash,
    p_expected_proposal_hash,
    v_request_metadata || jsonb_build_object(
      'proposalId', p_proposal_id,
      'transition', p_transition,
      'expectedProposalHash', p_expected_proposal_hash,
      'requestHash', p_request_hash
    ),
    p_actor_user_id,
    v_now
  )
  returning * into v_existing_event;

  return jsonb_build_object(
    'ok', true,
    'status', p_transition,
    'replayed', false,
    'proposal', jsonb_build_object(
      'id', v_proposal.id,
      'proposalStatus', v_proposal.proposal_status,
      'proposalHash', v_proposal.proposal_hash,
      'reviewedByAdminId', v_proposal.reviewed_by_admin_id,
      'reviewedAt', v_proposal.reviewed_at,
      'reviewReason', v_proposal.review_reason
    ),
    'reviewEvent', jsonb_build_object(
      'eventId', v_existing_event.id,
      'transition', v_existing_event.transition,
      'fromStatus', v_existing_event.from_status,
      'toStatus', v_existing_event.to_status,
      'correlationId', v_existing_event.correlation_id,
      'idempotencyKey', v_existing_event.idempotency_key,
      'requestHash', v_existing_event.request_hash
    ),
    'readback', jsonb_build_object(
      'matchedRequestHash', v_existing_event.request_hash = p_request_hash,
      'matchedProposalHash', v_existing_event.proposal_hash = p_expected_proposal_hash
    )
  );
exception
  when unique_violation then
    raise exception 'trend_proposal_review_idempotency_conflict';
end;
$_$;


--
-- Name: review_media_delete_allowed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_media_delete_allowed(p_path text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u uuid := privacy_retention.g041_current_claim_user_id(); review_id uuid; purpose text;
BEGIN
  IF u IS NULL OR current_setting('transaction_isolation') <> 'read committed' THEN RETURN false; END IF;
  IF octet_length(p_path) > 512 THEN RETURN false; END IF;
  -- Existing composer compensation also uses Storage.remove directly. Admit
  -- only canonical orphan keys, retiring them atomically before that delete;
  -- a delayed insert/update then fails rather than referring to deleted media.
  PERFORM pg_advisory_xact_lock(741093, 1);
  IF EXISTS (SELECT 1 FROM review_media_private.cleanup c WHERE c.path = p_path
    AND c.owner_id = u AND c.retired AND NOT c.complete
    AND review_media_private.owned_legacy(p_path, u, c.purpose)) THEN
    RETURN NOT review_media_private.referenced(p_path);
  END IF;
  BEGIN review_id := split_part(p_path, '/', 3)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
  purpose := split_part(p_path, '/', 4);
  IF NOT review_media_private.canonical(p_path, u, review_id, purpose) THEN RETURN false; END IF;
  IF review_media_private.referenced(p_path) THEN RETURN false; END IF;
  INSERT INTO review_media_private.cleanup(path, owner_id, review_id, purpose, retired)
    VALUES (p_path, u, review_id, purpose, true)
    ON CONFLICT (path) DO UPDATE SET retired = true;
  RETURN true;
END $$;


--
-- Name: review_media_upload_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_media_upload_allowed(p_bucket text, p_path text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u uuid := privacy_retention.g041_current_claim_user_id(); review_id uuid; purpose text;
BEGIN
  IF u IS NULL OR current_setting('transaction_isolation') <> 'read committed'
    OR p_bucket IS NULL OR p_bucket NOT IN ('review-photos','review-verifications')
    OR p_path IS NULL OR octet_length(p_path) > 512 THEN RETURN false; END IF;
  BEGIN review_id := split_part(p_path, '/', 3)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
  purpose := CASE p_bucket WHEN 'review-photos' THEN 'food' ELSE 'verification' END;
  IF NOT review_media_private.canonical(p_path, u, review_id, purpose) THEN RETURN false; END IF;
  PERFORM pg_advisory_xact_lock(741093, 1);
  RETURN NOT EXISTS (SELECT 1 FROM review_media_private.cleanup c WHERE c.path = p_path AND c.retired)
    AND NOT review_media_private.referenced(p_path);
END $$;


--
-- Name: review_restaurant_request(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_restaurant_request(p_request_id uuid, p_admin_user_id uuid, p_action text, p_admin_note text DEFAULT NULL::text, p_rejection_reason text DEFAULT NULL::text) RETURNS TABLE(success boolean, message text, audit_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_status text;
  next_status text;
  created_audit_id uuid;
begin
  if not public.is_user_admin(p_admin_user_id) then
    raise exception 'admin privileges required';
  end if;

  if p_action not in ('approve', 'reject') then
    return query select false, '승인 또는 반려 중 하나를 선택해 주세요.', null::uuid;
    return;
  end if;

  if p_action = 'reject' and nullif(btrim(coalesce(p_rejection_reason, '')), '') is null then
    return query select false, '반려 사유를 입력해 주세요.', null::uuid;
    return;
  end if;

  select restaurant_requests.status
    into current_status
    from public.restaurant_requests
   where restaurant_requests.id = p_request_id
   for update;

  if not found then
    return query select false, '검토할 맛집 추천 요청을 찾을 수 없습니다.', null::uuid;
    return;
  end if;

  if current_status <> 'pending' then
    return query select false, '이미 검토가 완료된 맛집 추천 요청입니다.', null::uuid;
    return;
  end if;

  next_status := case when p_action = 'approve' then 'approved' else 'rejected' end;

  insert into public.restaurant_request_review_audit (
    request_id,
    admin_user_id,
    action,
    before_status,
    after_status,
    admin_note,
    rejection_reason
  )
  values (
    p_request_id,
    p_admin_user_id,
    p_action,
    current_status,
    next_status,
    nullif(btrim(coalesce(p_admin_note, '')), ''),
    case when p_action = 'reject' then nullif(btrim(coalesce(p_rejection_reason, '')), '') else null end
  )
  returning id into created_audit_id;

  update public.restaurant_requests
     set status = next_status,
         reviewed_by_admin_id = p_admin_user_id,
         reviewed_at = timezone('utc', now()),
         admin_note = nullif(btrim(coalesce(p_admin_note, '')), ''),
         rejection_reason = case when p_action = 'reject' then nullif(btrim(coalesce(p_rejection_reason, '')), '') else null end,
         review_audit_id = created_audit_id,
         updated_at = timezone('utc', now())
   where restaurant_requests.id = p_request_id;

  return query select
    true,
    case when p_action = 'approve' then '맛집 추천 요청을 승인했습니다.' else '맛집 추천 요청을 반려했습니다.' end,
    created_audit_id;
end;
$$;


--
-- Name: revoke_release_auth_session_family(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_release_auth_session_family(p_operation_id uuid, p_user_id uuid, p_session_id uuid, p_binding_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE existing public.release_auth_revocation_receipts%ROWTYPE; lease public.release_auth_session_leases%ROWTYPE; refresh_count bigint := 0; session_count integer := 0; revoked_timestamp timestamptz;
BEGIN
  IF COALESCE(NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', pg_catalog.current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE = '42501'; END IF;
  IF p_operation_id IS NULL OR p_user_id IS NULL OR p_session_id IS NULL OR p_binding_sha256 !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'operation, bound identity, and public binding are required' USING ERRCODE = '22023'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_session_id::text, 0));
  SELECT * INTO existing FROM public.release_auth_revocation_receipts r WHERE r.operation_id = p_operation_id FOR UPDATE;
  IF FOUND THEN
    IF existing.user_id IS DISTINCT FROM p_user_id OR existing.session_id IS DISTINCT FROM p_session_id OR existing.binding_sha256 IS DISTINCT FROM p_binding_sha256 THEN RAISE EXCEPTION 'operation binding mismatch' USING ERRCODE = '23505'; END IF;
    IF EXISTS (SELECT 1 FROM privacy_retention.g041_auth_sessions s WHERE s.id = p_session_id) OR EXISTS (SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens r WHERE r.session_id = p_session_id) OR EXISTS (SELECT 1 FROM public.release_auth_session_leases l WHERE l.operation_id = p_operation_id) THEN RAISE EXCEPTION 'revocation readback mismatch' USING ERRCODE = '55000'; END IF;
    RETURN pg_catalog.jsonb_build_object('schemaVersion', 1, 'operationId', existing.operation_id::text, 'bindingSha256', existing.binding_sha256, 'status', existing.status, 'refreshTokensDeleted', existing.refresh_tokens_deleted, 'sessionsDeleted', existing.sessions_deleted, 'sessionAbsent', true, 'refreshTokensAbsent', true, 'revokedAt', pg_catalog.to_char(existing.revoked_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
  END IF;
  SELECT * INTO lease FROM public.release_auth_session_leases l WHERE l.operation_id = p_operation_id FOR UPDATE;
  IF NOT FOUND OR lease.user_id IS DISTINCT FROM p_user_id OR lease.session_id IS DISTINCT FROM p_session_id THEN RAISE EXCEPTION 'exact release lease is required' USING ERRCODE = 'P0002'; END IF;
  DELETE FROM privacy_retention.g041_auth_refresh_tokens r WHERE r.session_id = p_session_id; GET DIAGNOSTICS refresh_count = ROW_COUNT;
  DELETE FROM privacy_retention.g041_auth_sessions s WHERE s.id = p_session_id AND s.user_id = p_user_id; GET DIAGNOSTICS session_count = ROW_COUNT;
  IF session_count <> 1 OR EXISTS (SELECT 1 FROM privacy_retention.g041_auth_sessions s WHERE s.id = p_session_id) OR EXISTS (SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens r WHERE r.session_id = p_session_id) THEN RAISE EXCEPTION 'revocation verification failed' USING ERRCODE = '55000'; END IF;
  revoked_timestamp := pg_catalog.date_trunc('milliseconds', pg_catalog.clock_timestamp());
  INSERT INTO public.release_auth_revocation_receipts (operation_id, user_id, session_id, binding_sha256, status, refresh_tokens_deleted, sessions_deleted, revoked_at) VALUES (p_operation_id, p_user_id, p_session_id, p_binding_sha256, 'revoked_verified', refresh_count, session_count, revoked_timestamp);
  DELETE FROM public.release_auth_session_leases l WHERE l.operation_id = p_operation_id AND l.user_id = p_user_id AND l.session_id = p_session_id;
  IF EXISTS (SELECT 1 FROM public.release_auth_session_leases l WHERE l.operation_id = p_operation_id) THEN RAISE EXCEPTION 'release lease closure failed' USING ERRCODE = '55000'; END IF;
  RETURN pg_catalog.jsonb_build_object('schemaVersion', 1, 'operationId', p_operation_id::text, 'bindingSha256', p_binding_sha256, 'status', 'revoked_verified', 'refreshTokensDeleted', refresh_count, 'sessionsDeleted', session_count, 'sessionAbsent', true, 'refreshTokensAbsent', true, 'revokedAt', pg_catalog.to_char(revoked_timestamp AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
END;
$_$;


--
-- Name: run_account_deletion_session_family_cleanup(uuid, uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_account_deletion_session_family_cleanup(p_actor_user_id uuid, p_target_user_id uuid, p_request_id uuid, p_preview_hash text, p_idempotency_key text, p_source_manifest_hash text, p_attempt_token uuid) RETURNS TABLE(request_id uuid, status text, session_readback_passed boolean, job_state text, checkpoint_state text, source_manifest_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_attempt privacy_retention.account_deletion_external_job_attempts%ROWTYPE;
  v_absent boolean;
BEGIN
  PERFORM privacy_retention.g014_account_deletion_assert_external_job_binding(
    p_actor_user_id, p_target_user_id, p_request_id, p_preview_hash,
    p_idempotency_key, p_source_manifest_hash, 'session', p_attempt_token, false
  );
  SELECT * INTO v_attempt
  FROM privacy_retention.account_deletion_external_job_attempts
  WHERE attempt_token = p_attempt_token
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_deletion_session_cleanup_not_prepared' USING ERRCODE = '55000';
  END IF;

  IF v_attempt.state IN ('egress_unknown', 'reconciliation_required') THEN
    SELECT NOT EXISTS (
      SELECT 1 FROM privacy_retention.g041_auth_sessions WHERE user_id = p_target_user_id
      UNION ALL
      SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens WHERE user_id = p_target_user_id
    ) INTO v_absent;
    IF v_absent THEN
      v_request := privacy_retention.g014_account_deletion_complete_external_job_phase(
        p_request_id, 'session', p_attempt_token
      );
      RETURN QUERY SELECT v_request.id, v_request.status, v_request.session_readback_passed,
        'completed', 'authoritative_absent', v_request.source_manifest_hash;
      RETURN;
    END IF;

    SELECT * INTO v_request
    FROM public.account_deletion_requests
    WHERE id = p_request_id;
    RETURN QUERY SELECT v_request.id, v_request.status, false,
      v_attempt.state, 'verify_absence_only', v_request.source_manifest_hash;
    RETURN;
  END IF;

  PERFORM privacy_retention.g014_account_deletion_assert_external_job_binding(
    p_actor_user_id, p_target_user_id, p_request_id, p_preview_hash,
    p_idempotency_key, p_source_manifest_hash, 'session', p_attempt_token, true
  );
  IF v_attempt.state IS DISTINCT FROM 'leased' THEN
    RAISE EXCEPTION 'account_deletion_session_cleanup_not_prepared' USING ERRCODE = '55000';
  END IF;

  UPDATE privacy_retention.account_deletion_external_job_attempts
  SET state = 'egress_unknown', unknown_outcome_at = pg_catalog.clock_timestamp()
  WHERE attempt_token = p_attempt_token
    AND state = 'leased';
  UPDATE privacy_retention.account_deletion_external_jobs
  SET state = 'egress_unknown', updated_at = pg_catalog.clock_timestamp()
  WHERE request_id = p_request_id AND phase = 'session';
  INSERT INTO privacy_retention.account_deletion_external_job_checkpoints (
    request_id, phase, attempt_token, checkpoint_kind, checkpoint_state, proof_hash
  ) VALUES (
    p_request_id, 'session', p_attempt_token, 'egress_unknown', 'unknown',
    pg_catalog.encode(
      extensions.digest('g014-egress-unknown:v1:' || p_request_id::text || ':session:' || p_attempt_token::text, 'sha256'),
      'hex'
    )
  );

  DELETE FROM privacy_retention.g041_auth_refresh_tokens WHERE user_id = p_target_user_id;
  DELETE FROM privacy_retention.g041_auth_sessions WHERE user_id = p_target_user_id;
  SELECT NOT EXISTS (
    SELECT 1 FROM privacy_retention.g041_auth_sessions WHERE user_id = p_target_user_id
    UNION ALL
    SELECT 1 FROM privacy_retention.g041_auth_refresh_tokens WHERE user_id = p_target_user_id
  ) INTO v_absent;

  IF v_absent THEN
    v_request := privacy_retention.g014_account_deletion_complete_external_job_phase(
      p_request_id, 'session', p_attempt_token
    );
    RETURN QUERY SELECT v_request.id, v_request.status, v_request.session_readback_passed,
      'completed', 'authoritative_absent', v_request.source_manifest_hash;
    RETURN;
  END IF;

  UPDATE public.account_deletion_requests
  SET status = 'partial', reason_code = 'SESSION_READBACK_REQUIRED'
  WHERE id = p_request_id
  RETURNING * INTO v_request;
  RETURN QUERY SELECT v_request.id, v_request.status, false,
    'egress_unknown', 'verify_absence_only', v_request.source_manifest_hash;
END;
$$;


--
-- Name: search_restaurants(text, text[], integer, real); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_restaurants(search_query text, search_categories text[] DEFAULT NULL::text[], max_results integer DEFAULT 50, similarity_threshold real DEFAULT 0.1) RETURNS TABLE(id uuid, name text, categories text[], road_address text, jibun_address text, lat numeric, lng numeric, review_count integer, similarity real, edit_distance integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  return query
  select
    r.id,
    r.approved_name as name,
    r.categories,
    r.road_address,
    r.jibun_address,
    r.lat,
    r.lng,
    r.review_count,
    greatest(
      similarity(coalesce(r.approved_name, ''), search_query),
      similarity(coalesce(r.road_address, ''), search_query),
      similarity(coalesce(r.jibun_address, ''), search_query)
    ) as similarity,
    levenshtein(coalesce(r.approved_name, ''), search_query) as edit_distance
  from public.restaurants r
  where
    (search_categories is null or r.categories && search_categories)
    and coalesce(r.approved_name, '') <> ''
    and greatest(
      similarity(coalesce(r.approved_name, ''), search_query),
      similarity(coalesce(r.road_address, ''), search_query),
      similarity(coalesce(r.jibun_address, ''), search_query)
    ) > similarity_threshold
  order by
    edit_distance asc,
    similarity desc,
    r.review_count desc
  limit max_results;
end;
$$;


--
-- Name: FUNCTION search_restaurants(search_query text, search_categories text[], max_results integer, similarity_threshold real); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_restaurants(search_query text, search_categories text[], max_results integer, similarity_threshold real) IS '맛집 검색 함수 (하이브리드: Trigram 인덱스 필터링 + Levenshtein 정렬)';


--
-- Name: search_restaurants_by_category(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_restaurants_by_category(p_category text, p_limit integer DEFAULT 10) RETURNS TABLE(id uuid, name text, categories text[], youtube_link text, description_map_url text, video_id text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select
    r.id,
    r.approved_name as name,
    r.categories,
    r.youtube_link,
    r.description_map_url,
    -- youtube_link에서 video_id 추출 (간단한 파싱, Regex 필요시 조정)
    substring(r.youtube_link from 'v=([^&]+)') as video_id
  from restaurants r
  where r.status = 'approved'
    and p_category = any(r.categories)
  limit p_limit;
$$;


--
-- Name: search_restaurants_by_name(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_restaurants_by_name(keyword text, p_limit integer DEFAULT 5) RETURNS TABLE(id uuid, name text, categories text[], youtube_link text, video_id text, tzuyang_review text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select
    r.id,
    r.approved_name as name,
    r.categories,
    r.youtube_link,
    substring(r.youtube_link from 'v=([^&]+)') as video_id,
    r.tzuyang_review
  from restaurants r
  where r.status = 'approved'
    and (r.approved_name ilike '%' || keyword || '%')
  limit p_limit;
$$;


--
-- Name: search_restaurants_by_name(text, text[], integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_restaurants_by_name(search_query text, search_categories text[] DEFAULT NULL::text[], max_results integer DEFAULT 50, include_all_status boolean DEFAULT false, korean_only boolean DEFAULT false) RETURNS TABLE(id uuid, name text, road_address text, jibun_address text, phone text, categories text[], youtube_link text, tzuyang_review text, lat numeric, lng numeric, status text, created_at timestamp with time zone, updated_at timestamp with time zone, english_address text, youtube_meta jsonb, complete_match_score integer, word_match_score double precision, trigram_similarity real, levenshtein_distance integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  clean_search_query text;
begin
  clean_search_query := trim(search_query);
  if clean_search_query = '' then
    return;
  end if;

  return query
  select
    r.id,
    r.approved_name as name,
    r.road_address,
    r.jibun_address,
    r.phone,
    r.categories,
    r.youtube_link,
    r.tzuyang_review,
    r.lat,
    r.lng,
    r.status,
    r.created_at,
    r.updated_at,
    r.english_address,
    r.youtube_meta,
    case
      when lower(r.approved_name) like '%' || lower(clean_search_query) || '%' then 1
      else 0
    end as complete_match_score,
    calculate_word_match_score(r.approved_name, clean_search_query) as word_match_score,
    extensions.similarity(
      replace(lower(r.approved_name), ' ', ''),
      replace(lower(clean_search_query), ' ', '')
    ) as trigram_similarity,
    extensions.levenshtein(
      lower(r.approved_name),
      lower(clean_search_query)
    ) as levenshtein_distance
  from public.restaurants r
  where
    (include_all_status = true or r.status = 'approved')
    and (search_categories is null or r.categories && search_categories)
    and r.approved_name is not null
    and r.approved_name != ''
    and (
      korean_only = false
      or coalesce(r.road_address, r.jibun_address, r.english_address, '') ~ '(서울특별시|부산광역시|대구광역시|인천광역시|광주광역시|대전광역시|울산광역시|세종특별자치시|경기도|강원특별자치도|충청북도|충청남도|전북특별자치도|전라남도|경상북도|경상남도|제주특별자치도)'
    )
    and exists (
      select 1
      from unnest(string_to_array(lower(clean_search_query), null)) as query_char
      where query_char != '' and lower(r.approved_name) like '%' || query_char || '%'
    )
  order by
    case when lower(r.approved_name) like '%' || lower(clean_search_query) || '%' then 0 else 1 end,
    word_match_score desc,
    trigram_similarity desc,
    levenshtein_distance asc,
    length(r.approved_name) asc
  limit max_results;
end;
$$;


--
-- Name: FUNCTION search_restaurants_by_name(search_query text, search_categories text[], max_results integer, include_all_status boolean, korean_only boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_restaurants_by_name(search_query text, search_categories text[], max_results integer, include_all_status boolean, korean_only boolean) IS '맛집 이름으로 검색 (완전 포함 → 단어 매칭 → Trigram 유사도 → 레벤슈타인 거리 우선순위)';


--
-- Name: search_restaurants_by_youtube_title(text, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_restaurants_by_youtube_title(search_query text, max_results integer DEFAULT 50, include_all_status boolean DEFAULT false, korean_only boolean DEFAULT false) RETURNS TABLE(id uuid, name text, road_address text, jibun_address text, phone text, categories text[], youtube_link text, tzuyang_review text, lat numeric, lng numeric, status text, english_address text, youtube_title text, youtube_meta jsonb, origin_address jsonb, address_elements jsonb, reasoning_basis text, evaluation_results jsonb, complete_match_score integer, word_match_score double precision, trigram_similarity real, levenshtein_distance integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    clean_search_query TEXT;
    min_word_match_threshold DOUBLE PRECISION := 0.33; -- 최소 1/3 단어 매칭
BEGIN
    -- 검색어 정리
    clean_search_query := TRIM(search_query);
    
    -- 빈 검색어는 빈 결과 반환
    IF clean_search_query = '' THEN
        RETURN;
    END IF;
    
    -- youtube_meta JSONB에서 title 추출하여 검색
    RETURN QUERY
    SELECT 
        r.id,
        r.approved_name AS name,
        r.road_address,
        r.jibun_address,
        r.phone,
        r.categories,
        r.youtube_link,
        r.tzuyang_review,
        r.lat,
        r.lng,
        r.status,
        r.english_address,
        (r.youtube_meta->>'title')::TEXT AS youtube_title,
        r.youtube_meta,
        r.origin_address,
        r.address_elements,
        r.reasoning_basis,
        r.evaluation_results,
        -- 완전 포함 점수
        CASE 
            WHEN LOWER(r.youtube_meta->>'title') LIKE '%' || LOWER(clean_search_query) || '%' THEN 1
            ELSE 0
        END AS complete_match_score,
        -- 단어 매칭 점수
        calculate_word_match_score(r.youtube_meta->>'title', clean_search_query) AS word_match_score,
        -- Trigram 유사도 (띄어쓰기 제거)
        extensions.similarity(
            REPLACE(LOWER(r.youtube_meta->>'title'), ' ', ''),
            REPLACE(LOWER(clean_search_query), ' ', '')
        ) AS trigram_similarity,
        -- 레벤슈타인 거리
        extensions.levenshtein(
            LOWER(r.youtube_meta->>'title'),
            LOWER(clean_search_query)
        ) AS levenshtein_distance
    FROM 
        public.restaurants r
    WHERE 
        -- 상태 필터: include_all_status가 true면 전체, false면 approved만
        (include_all_status = TRUE OR r.status = 'approved')
        AND r.youtube_meta IS NOT NULL
        AND r.youtube_meta->>'title' IS NOT NULL
        AND r.youtube_meta->>'title' != ''
        -- 한국 지역 필터 (선택적)
        AND (
            korean_only = FALSE 
            OR COALESCE(r.road_address, r.jibun_address, r.english_address, '') ~ '(서울특별시|부산광역시|대구광역시|인천광역시|광주광역시|대전광역시|울산광역시|세종특별자치시|경기도|강원특별자치도|충청북도|충청남도|전북특별자치도|전라남도|경상북도|경상남도|제주특별자치도)'
        )
        -- 필수 조건: 최소 1글자 이상 포함
        AND EXISTS (
            SELECT 1
            FROM unnest(string_to_array(LOWER(clean_search_query), NULL)) AS query_char
            WHERE query_char != '' AND LOWER(r.youtube_meta->>'title') LIKE '%' || query_char || '%'
        )
    ORDER BY 
        -- 1단계: 검색어가 그대로 포함되는지 여부 (포함=0, 미포함=1)
        CASE WHEN LOWER(r.youtube_meta->>'title') LIKE '%' || LOWER(clean_search_query) || '%' THEN 0 ELSE 1 END,
        -- 2단계: 우선순위
        -- 2-1. 단어 매칭 점수 (높을수록 좋음)
        word_match_score DESC,
        -- 2-2. Trigram 유사도 (띄어쓰기 제거, 높을수록 좋음)
        trigram_similarity DESC,
        -- 2-3. 레벤슈타인 거리 (작을수록 좋음)
        levenshtein_distance ASC,
        -- 2-4. 제목 길이 (짧을수록 좋음)
        LENGTH(r.youtube_meta->>'title') ASC
    LIMIT max_results;
END;
$$;


--
-- Name: FUNCTION search_restaurants_by_youtube_title(search_query text, max_results integer, include_all_status boolean, korean_only boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_restaurants_by_youtube_title(search_query text, max_results integer, include_all_status boolean, korean_only boolean) IS '유튜브 제목으로 검색 (완전 포함 → 단어 매칭 → Trigram 유사도 → 레벤슈타인 거리 우선순위)';


--
-- Name: search_video_ids_by_query(extensions.vector, jsonb, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_video_ids_by_query(query_embedding extensions.vector, query_sparse jsonb, dense_weight double precision DEFAULT 0.6, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 10) RETURNS TABLE(video_id text, recollect_id integer, best_score double precision, sample_content text, has_peak boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
#variable_conflict use_column
begin
  return query
  with 
  candidates as (
    select
      teb.video_id, teb.recollect_id, teb.page_content, teb.metadata, teb.embedding, teb.sparse_embedding,
      1 - (teb.embedding <=> query_embedding) as dense_score
    from transcript_embeddings_bge teb
    where 1 - (teb.embedding <=> query_embedding) > match_threshold
    order by teb.embedding <=> query_embedding
    limit match_count * 5
  ),
  valid_candidates as (
    select c.*
    from candidates c
    where c.recollect_id = (
        select max(recollect_id) 
        from transcript_embeddings_bge 
        where video_id = c.video_id
    )
  ),
  scored as (
    select 
      vc.video_id,
      vc.recollect_id,
      vc.page_content,
      vc.metadata,
      (vc.dense_score * dense_weight) +
      coalesce(
        (select sum((vc.sparse_embedding->>k)::float * (query_sparse->>k)::float)
         from jsonb_object_keys(query_sparse) k
         where vc.sparse_embedding ? k), 0
      ) * (1 - dense_weight) as score
    from valid_candidates vc
  ),
  ranked as (
    select 
      s.video_id,
      s.recollect_id,
      s.score,
      s.page_content,
      s.metadata,
      row_number() over (partition by s.video_id order by s.score desc) as rn
    from scored s
  )
  select 
    r.video_id,
    r.recollect_id,
    r.score::float as best_score,
    left(r.page_content, 150) as sample_content,
    (r.metadata->>'is_peak')::boolean as has_peak
  from ranked r
  where r.rn = 1
  order by r.score desc
  limit match_count;
end;
$$;


