--
-- Name: storyboard_production_admin(uuid, text, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_admin(p_owner_id uuid, p_action text, p_project_id uuid DEFAULT NULL::uuid, p_revision integer DEFAULT NULL::integer, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  p public.admin_storyboard_production_projects; j public.admin_storyboard_production_jobs;
  old_job public.admin_storyboard_production_jobs; s jsonb; doc jsonb; proof jsonb;
  scene integer; job_request uuid; initial_status text; project_rows jsonb; worker_rows jsonb;
  target_rev integer; restore_request uuid; hist jsonb; hist_scene jsonb; asset_id uuid;
  applied public.admin_storyboard_production_restores; version_rows jsonb; preview jsonb;
BEGIN
  PERFORM storyboard_control.assert_owner(p_owner_id);
  IF p_action = 'list' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'revision', q.revision, 'status', q.status,
      'title', q.title, 'createdAt', q.created_at, 'updatedAt', q.updated_at) ORDER BY q.updated_at DESC), '[]')
      INTO project_rows FROM (SELECT * FROM public.admin_storyboard_production_projects
      WHERE owner_id = p_owner_id ORDER BY updated_at DESC LIMIT 50) q;
    SELECT coalesce(jsonb_agg(jsonb_build_object('id', w.id, 'online',
      NOT w.disabled AND w.revoked_at IS NULL AND coalesce(w.last_heartbeat > clock_timestamp() - interval '120 seconds', false),
      'lastHeartbeat', w.last_heartbeat, 'models', w.models) ORDER BY w.created_at), '[]') INTO worker_rows
      FROM (SELECT * FROM public.admin_storyboard_production_workers WHERE owner_id = p_owner_id ORDER BY created_at LIMIT 64) w;
    RETURN jsonb_build_object('ok', true, 'projects', project_rows, 'workers', worker_rows);
  END IF;
  IF p_action = 'create' THEN
    IF p_payload->>'workflow' IS DISTINCT FROM 'storyboard-gemini-v1'
      OR (p_payload->>'sceneCount')::integer NOT BETWEEN 5 AND 12 THEN RAISE EXCEPTION 'invalid_request'; END IF;
    IF NOT coalesce((p_payload#>>'{providers,externalAI}')::boolean, false) THEN RAISE EXCEPTION 'external_ai_disabled'; END IF;
    IF p_payload#>>'{providers,text,id}' IS DISTINCT FROM 'gemini-api'
      OR p_payload#>>'{providers,image,id}' IS DISTINCT FROM 'gemini-api'
      OR p_payload#>>'{providers,text,model}' IS DISTINCT FROM 'gemini-3.8-flash'
      OR coalesce(p_payload#>>'{providers,image,model}','') NOT IN ('gemini-3.1-flash-image','gemini-3-pro-image')
      THEN RAISE EXCEPTION 'provider_not_configured'; END IF;
    job_request := (p_payload->>'requestId')::uuid;
    PERFORM pg_advisory_xact_lock(hashtextextended(p_owner_id::text || job_request::text, 0));
    SELECT * INTO p FROM public.admin_storyboard_production_projects WHERE owner_id = p_owner_id AND request_id = job_request;
    IF FOUND THEN
      IF p.request <> p_payload THEN RAISE EXCEPTION 'request_conflict'; END IF;
      RETURN public.storyboard_production_snapshot(p_owner_id, p.id);
    END IF;
    initial_status := CASE WHEN p_payload#>>'{providers,text,id}' = 'gemini-api' THEN 'waiting_worker' ELSE 'awaiting_import' END;
    INSERT INTO public.admin_storyboard_production_projects(owner_id, request_id, request, status)
      VALUES (p_owner_id, job_request, p_payload, initial_status) RETURNING * INTO p;
    IF initial_status = 'waiting_worker' THEN
      INSERT INTO public.admin_storyboard_production_jobs(project_id, owner_id, request_id, requested_revision, base_revision, kind)
        VALUES (p.id, p_owner_id, job_request, 0, 0, 'generate') RETURNING * INTO j;
    END IF;
    INSERT INTO public.admin_storyboard_production_events(project_id, owner_id, job_id, operation, revision)
      VALUES (p.id, p_owner_id, j.id, 'created', p.revision);
    RETURN public.storyboard_production_snapshot(p_owner_id, p.id);
  END IF;

  SELECT * INTO p FROM public.admin_storyboard_production_projects WHERE id = p_project_id AND owner_id = p_owner_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'project_not_found'; END IF;
  IF p_action = 'read' THEN
    RETURN public.storyboard_production_snapshot(p_owner_id, p.id) || jsonb_build_object('events',
      (SELECT coalesce(jsonb_agg(jsonb_build_object('id', e.id::text, 'jobId', e.job_id, 'operation', e.operation,
        'revision', e.revision, 'sceneNo', e.scene_no, 'errorCode', e.error_code, 'createdAt', e.created_at)
        ORDER BY e.id), '[]') FROM (SELECT * FROM public.admin_storyboard_production_events
        WHERE project_id = p.id AND owner_id = p_owner_id ORDER BY id DESC LIMIT 100) e));
  END IF;
  IF p_action = 'versions' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'revision', r.revision, 'createdAt', r.created_at, 'title', coalesce(r.document->>'title', ''),
      'sceneCount', coalesce(jsonb_array_length(r.document->'scenes'), 0)) ORDER BY r.revision DESC), '[]')
      INTO version_rows FROM (SELECT * FROM public.admin_storyboard_production_revisions
        WHERE project_id = p.id AND owner_id = p_owner_id ORDER BY revision DESC LIMIT 200) r;
    preview := NULL;
    IF p_payload ? 'targetRevision' THEN
      target_rev := (p_payload->>'targetRevision')::integer;
      SELECT r.document INTO preview FROM public.admin_storyboard_production_revisions r
        WHERE r.project_id = p.id AND r.owner_id = p_owner_id AND r.revision = target_rev;
      IF preview IS NULL THEN RAISE EXCEPTION 'version_not_found'; END IF;
    END IF;
    RETURN jsonb_build_object('ok', true, 'versions', version_rows, 'preview', preview);
  END IF;
  IF p.request->>'workflow' IS DISTINCT FROM 'storyboard-gemini-v1' THEN
    RAISE EXCEPTION 'archived_project_read_only';
  END IF;
  IF p_action NOT IN ('edit','regenerate','retry','cancel','restore') THEN
    RAISE EXCEPTION 'invalid_request';
  END IF;
  IF p_action IN ('retry','regenerate') THEN
    job_request := (p_payload->>'requestId')::uuid;
    SELECT * INTO old_job FROM public.admin_storyboard_production_jobs WHERE owner_id = p_owner_id AND request_id = job_request;
    IF FOUND THEN
      IF old_job.project_id <> p.id OR old_job.requested_revision <> p_revision
        OR old_job.kind <> (CASE WHEN p_action = 'regenerate' THEN 'scene' ELSE 'generate' END)
        OR old_job.scene_no IS DISTINCT FROM (p_payload->>'sceneNo')::integer THEN RAISE EXCEPTION 'request_conflict'; END IF;
      RETURN public.storyboard_production_snapshot(p_owner_id, p.id);
    END IF;
  END IF;
  -- Resolve an already committed request before CAS/busy checks, including a stale HTTP retry.
  IF p_action = 'restore' THEN
    restore_request := (p_payload->>'requestId')::uuid;
    target_rev := (p_payload->>'targetRevision')::integer;
    scene := (p_payload->>'sceneNo')::integer;
    SELECT * INTO applied FROM public.admin_storyboard_production_restores
      WHERE project_id = p.id AND request_id = restore_request;
    IF FOUND THEN
      IF applied.target_revision IS DISTINCT FROM target_rev
        OR applied.scene_no IS DISTINCT FROM scene THEN RAISE EXCEPTION 'request_conflict'; END IF;
      RETURN public.storyboard_production_snapshot(p_owner_id, p.id);
    END IF;
  END IF;
  IF p_revision IS DISTINCT FROM p.revision THEN RAISE EXCEPTION 'revision_conflict'; END IF;
  SELECT * INTO j FROM public.admin_storyboard_production_jobs WHERE project_id = p.id AND status IN ('queued','claimed') FOR UPDATE;
  IF p_action = 'cancel' THEN
    IF j.id IS NULL OR j.id IS DISTINCT FROM (p_payload->>'jobId')::uuid THEN RAISE EXCEPTION 'worker_lease_lost'; END IF;
    UPDATE public.admin_storyboard_production_jobs SET status = 'cancelled', stage = 'cancelled', error_code = 'generation_cancelled',
      lease_token = NULL, lease_expires_at = NULL, updated_at = clock_timestamp() WHERE id = j.id;
    UPDATE public.admin_storyboard_production_projects SET status = 'cancelled', revision = revision + 1,
      document = CASE WHEN document IS NULL THEN NULL ELSE jsonb_set(document, '{revision}', to_jsonb(revision + 1)) END,
      updated_at = clock_timestamp() WHERE id = p.id RETURNING * INTO p;
    IF p.document IS NOT NULL THEN
      INSERT INTO public.admin_storyboard_production_revisions(project_id, owner_id, revision, document)
      VALUES (p.id, p.owner_id, p.revision, p.document)
      ON CONFLICT (project_id, revision) DO NOTHING;
    END IF;
    INSERT INTO public.admin_storyboard_production_events(project_id, owner_id, job_id, operation, revision)
      VALUES (p.id, p_owner_id, j.id, 'cancelled', p.revision);
    RETURN public.storyboard_production_snapshot(p_owner_id, p.id);
  END IF;
  IF j.id IS NOT NULL THEN RAISE EXCEPTION 'project_busy'; END IF;

  IF p_action = 'restore' THEN
    restore_request := (p_payload->>'requestId')::uuid;
    target_rev := (p_payload->>'targetRevision')::integer;
    scene := (p_payload->>'sceneNo')::integer;
    IF restore_request IS NULL OR target_rev IS NULL OR target_rev < 0 OR target_rev >= p.revision THEN
      RAISE EXCEPTION 'invalid_request'; END IF;
    SELECT r.document INTO hist FROM public.admin_storyboard_production_revisions r
      WHERE r.project_id = p.id AND r.owner_id = p_owner_id AND r.revision = target_rev;
    IF hist IS NULL THEN RAISE EXCEPTION 'version_not_found'; END IF;
    IF scene IS NOT NULL THEN
      IF p.document IS NULL OR scene NOT BETWEEN 1 AND jsonb_array_length(hist->'scenes')
        OR scene NOT BETWEEN 1 AND jsonb_array_length(p.document->'scenes') THEN
        RAISE EXCEPTION 'invalid_scene'; END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(
        CASE WHEN scene IS NULL THEN coalesce(hist->'scenes', '[]'::jsonb)
             ELSE jsonb_build_array(hist->'scenes'->(scene - 1)) END) AS img(scene_doc)
      WHERE jsonb_typeof(img.scene_doc->'image') = 'object'
        AND NOT EXISTS (
          SELECT 1 FROM public.admin_storyboard_production_assets a
          WHERE a.id = (img.scene_doc#>>'{image,id}')::uuid AND a.project_id = p.id AND a.owner_id = p_owner_id
            AND a.scene_no = (img.scene_doc->>'sceneNo')::integer
             AND a.metadata = img.scene_doc->'image'
        )
    ) THEN RAISE EXCEPTION 'restore_asset_missing'; END IF;
    IF p.document IS NOT NULL THEN
      INSERT INTO public.admin_storyboard_production_revisions(project_id, owner_id, revision, document)
      VALUES (p.id, p.owner_id, p.revision, p.document)
      ON CONFLICT (project_id, revision) DO NOTHING;
    END IF;
    IF scene IS NULL THEN doc := hist;
    ELSE doc := jsonb_set(p.document, ARRAY['scenes', (scene - 1)::text], hist->'scenes'->(scene - 1)); END IF;
    -- Restore content while keeping scene CAS versions monotonic.
    doc := jsonb_set(doc, '{scenes}', (SELECT jsonb_agg(
      CASE WHEN scene IS NULL OR (x->>'sceneNo')::integer = scene
        THEN jsonb_set(x, '{revision}', to_jsonb(greatest(
          coalesce((p.document->'scenes'->((x->>'sceneNo')::integer - 1)->>'revision')::integer, 0),
          (x->>'revision')::integer) + 1)) ELSE x END ORDER BY (x->>'sceneNo')::integer)
      FROM jsonb_array_elements(doc->'scenes') x));
    doc := jsonb_set(doc, '{revision}', to_jsonb(p.revision + 1));
    UPDATE public.admin_storyboard_production_projects SET document = doc, title = doc->>'title', revision = revision + 1,
      status = public.storyboard_production_final_status(request, doc), updated_at = clock_timestamp()
      WHERE id = p.id RETURNING * INTO p;
    INSERT INTO public.admin_storyboard_production_revisions(project_id, owner_id, revision, document)
      VALUES (p.id, p.owner_id, p.revision, p.document)
      ON CONFLICT (project_id, revision) DO NOTHING;
    INSERT INTO public.admin_storyboard_production_restores(project_id, request_id, target_revision, scene_no, applied_revision)
      VALUES (p.id, restore_request, target_rev, scene, p.revision);
    INSERT INTO public.admin_storyboard_production_events(project_id, owner_id, operation, revision, scene_no)
      VALUES (p.id, p_owner_id, 'restored', p.revision, scene);
    RETURN public.storyboard_production_snapshot(p_owner_id, p.id);
  END IF;

  scene := (p_payload->>'sceneNo')::integer;
  IF p_action IN ('edit','regenerate','import-image') THEN
    IF p.document IS NULL OR scene IS NULL OR scene NOT BETWEEN 1 AND jsonb_array_length(p.document->'scenes') THEN
      RAISE EXCEPTION 'invalid_scene';
    END IF;
    s := p.document->'scenes'->(scene - 1);
  END IF;
  IF p_action = 'edit' THEN
    s := (p_payload->'scene') || jsonb_build_object('sceneNo', scene, 'revision', (s->>'revision')::integer + 1,
      'image', s->'image', 'imageError', s->'imageError');
    doc := jsonb_set(p.document, ARRAY['scenes', (scene - 1)::text], s);
  ELSIF p_action = 'import-text' THEN
    IF p.request#>>'{providers,text,id}' NOT IN ('manual','chatgpt-manual','grok-manual') OR p.document IS NOT NULL
      OR p_payload->>'projectId' IS DISTINCT FROM p.id::text OR p_payload->>'schema' IS DISTINCT FROM 'storyboard-mlx-v1' THEN
      RAISE EXCEPTION 'invalid_request';
    END IF;
    proof := jsonb_build_object('providerId', p.request#>>'{providers,text,id}', 'model', p.request#>>'{providers,text,model}',
      'verification','user-import','generatedAt',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'requestId',gen_random_uuid(),'responseId',NULL,'responseModel',NULL,'modelEvidence','unverified');
    doc := (p_payload->'draft') || jsonb_build_object('schema','storyboard-mlx-v1','projectId',p.id,
      'generatedAt',proof->>'generatedAt','textProvenance',proof,'scenes',
      (SELECT jsonb_agg(x || jsonb_build_object('revision',0,'image',NULL,'imageError',NULL) ORDER BY (x->>'sceneNo')::integer)
       FROM jsonb_array_elements(p_payload#>'{draft,scenes}') x));
  ELSIF p_action = 'import-image' THEN
    IF p.request#>>'{providers,image,id}' NOT IN ('manual','chatgpt-manual','grok-manual') THEN RAISE EXCEPTION 'invalid_request'; END IF;
    IF (p_payload->>'sceneRevision')::integer IS DISTINCT FROM (s->>'revision')::integer THEN RAISE EXCEPTION 'revision_conflict'; END IF;
    INSERT INTO public.admin_storyboard_production_assets(id, project_id, owner_id, scene_no, scene_revision, metadata)
      VALUES ((p_payload#>>'{asset,id}')::uuid, p.id, p_owner_id, scene, (s->>'revision')::integer + 1, p_payload->'asset');
    s := s || jsonb_build_object('image', p_payload->'asset', 'imageError', NULL, 'revision', (s->>'revision')::integer + 1);
    doc := jsonb_set(p.document, ARRAY['scenes', (scene - 1)::text], s);
  ELSIF p_action NOT IN ('retry','regenerate') THEN RAISE EXCEPTION 'invalid_request';
  END IF;

  IF doc IS NOT NULL THEN
    doc := jsonb_set(doc, '{revision}', to_jsonb(p.revision + 1));
    UPDATE public.admin_storyboard_production_projects SET document = doc, title = doc->>'title', revision = revision + 1,
      status = public.storyboard_production_final_status(request, doc), updated_at = clock_timestamp() WHERE id = p.id RETURNING * INTO p;
    IF p.document IS NOT NULL THEN
      INSERT INTO public.admin_storyboard_production_revisions(project_id, owner_id, revision, document)
      VALUES (p.id, p.owner_id, p.revision, p.document)
      ON CONFLICT (project_id, revision) DO NOTHING;
    END IF;
    INSERT INTO public.admin_storyboard_production_events(project_id, owner_id, operation, revision, scene_no)
      VALUES (p.id, p_owner_id, CASE p_action WHEN 'edit' THEN 'edited' WHEN 'import-text' THEN 'draft_saved' ELSE 'image_saved' END, p.revision, scene);
  END IF;
  IF p_action IN ('retry','regenerate') OR (p_action = 'import-text' AND p.request#>>'{providers,image,id}' = 'gemini-api') THEN
    IF (p.document IS NULL AND p.request#>>'{providers,text,id}' <> 'gemini-api')
      OR (p.document IS NOT NULL AND p.request#>>'{providers,image,id}' <> 'gemini-api') THEN RAISE EXCEPTION 'nothing_to_retry'; END IF;
    IF p_action <> 'regenerate' AND p.document IS NOT NULL AND public.storyboard_production_final_status(p.request,p.document) = 'ready' THEN
      RAISE EXCEPTION 'nothing_to_retry';
    END IF;
    job_request := coalesce(job_request, gen_random_uuid());
    UPDATE public.admin_storyboard_production_projects SET revision = revision + 1, status = 'waiting_worker',
      document = CASE WHEN document IS NULL THEN NULL ELSE jsonb_set(document,'{revision}',to_jsonb(revision + 1)) END,
      updated_at = clock_timestamp() WHERE id = p.id RETURNING * INTO p;
    IF p.document IS NOT NULL THEN
      INSERT INTO public.admin_storyboard_production_revisions(project_id, owner_id, revision, document)
      VALUES (p.id, p.owner_id, p.revision, p.document)
      ON CONFLICT (project_id, revision) DO NOTHING;
    END IF;
    INSERT INTO public.admin_storyboard_production_jobs(project_id, owner_id, request_id, requested_revision, base_revision, kind, scene_no)
      VALUES (p.id, p_owner_id, job_request, p_revision, p.revision, CASE WHEN p_action = 'regenerate' THEN 'scene' ELSE 'generate' END,
        CASE WHEN p_action = 'regenerate' THEN scene END) RETURNING * INTO j;
    INSERT INTO public.admin_storyboard_production_events(project_id, owner_id, job_id, operation, revision, scene_no)
      VALUES (p.id, p_owner_id, j.id, 'queued', p.revision, j.scene_no);
  END IF;
  RETURN public.storyboard_production_snapshot(p_owner_id, p.id);
END $$;


--
-- Name: storyboard_production_auth_worker(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_auth_worker(p_token_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE w public.admin_storyboard_production_workers;
BEGIN
  SELECT * INTO w FROM public.admin_storyboard_production_workers
    WHERE token_sha256 = p_token_sha256 AND NOT disabled AND revoked_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'worker_unauthorized'; END IF;
  PERFORM storyboard_control.assert_owner(w.owner_id);
  RETURN jsonb_build_object('id', w.id, 'ownerId', w.owner_id, 'models', w.models);
END $$;


--
-- Name: storyboard_production_error_allowed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_error_allowed(p_code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT p_code IS NULL OR p_code = ANY(ARRAY['worker_lease_lost','generation_cancelled','revision_conflict',
    'model_not_installed','model_capability_mismatch','local_model_unavailable','model_timeout',
    'invalid_structured_response','bge_dependency_unavailable','model_response_too_large',
    'invalid_image_response','invalid_image','image_too_large','provider_auth_failed','provider_forbidden',
    'provider_rate_limited','provider_failed','provider_not_configured','model_identity_mismatch',
    'invalid_local_endpoint','invalid_model_request','invalid_model_response','image_missing',
    'version_not_found','restore_asset_missing']);
$$;


--
-- Name: storyboard_production_final_status(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_final_status(p_request jsonb, p_document jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE missing boolean; failed boolean; has_image boolean;
BEGIN
  IF p_document IS NULL THEN
    RETURN CASE WHEN p_request#>>'{providers,text,id}' IN ('manual','chatgpt-manual','grok-manual')
      THEN 'awaiting_import' ELSE 'failed' END;
  END IF;
  SELECT bool_or(s->'image' IS NULL OR s->'image' = 'null'::jsonb),
    bool_or(s->>'imageError' IS NOT NULL), bool_or(s->'image' IS NOT NULL AND s->'image' <> 'null'::jsonb)
    INTO missing, failed, has_image FROM jsonb_array_elements(p_document->'scenes') s;
  IF missing AND p_request#>>'{providers,image,id}' IN ('manual','chatgpt-manual','grok-manual') THEN RETURN 'awaiting_import'; END IF;
  IF missing OR failed THEN RETURN CASE WHEN has_image THEN 'partial' ELSE 'failed' END; END IF;
  RETURN 'ready';
END $$;


--
-- Name: admin_storyboard_production_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_storyboard_production_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    request_id uuid NOT NULL,
    requested_revision integer NOT NULL,
    base_revision integer NOT NULL,
    kind text NOT NULL,
    scene_no integer,
    scene_versions jsonb DEFAULT '{}'::jsonb NOT NULL,
    result_request_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    stage text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    worker_id uuid,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    last_heartbeat timestamp with time zone,
    error_code text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT admin_storyboard_production_jobs_attempts_check CHECK (((attempts >= 0) AND (attempts <= 3))),
    CONSTRAINT admin_storyboard_production_jobs_base_revision_check CHECK ((base_revision >= 0)),
    CONSTRAINT admin_storyboard_production_jobs_check CHECK (((kind = 'scene'::text) = (scene_no IS NOT NULL))),
    CONSTRAINT admin_storyboard_production_jobs_check1 CHECK (((status = 'claimed'::text) = ((lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (worker_id IS NOT NULL)))),
    CONSTRAINT admin_storyboard_production_jobs_error_code_check CHECK ((error_code ~ '^[a-z_]{1,80}$'::text)),
    CONSTRAINT admin_storyboard_production_jobs_error_code_check1 CHECK (public.storyboard_production_error_allowed(error_code)),
    CONSTRAINT admin_storyboard_production_jobs_kind_check CHECK ((kind = ANY (ARRAY['generate'::text, 'scene'::text]))),
    CONSTRAINT admin_storyboard_production_jobs_requested_revision_check CHECK ((requested_revision >= 0)),
    CONSTRAINT admin_storyboard_production_jobs_result_request_ids_check CHECK ((cardinality(result_request_ids) <= 64)),
    CONSTRAINT admin_storyboard_production_jobs_scene_no_check CHECK (((scene_no >= 1) AND (scene_no <= 12))),
    CONSTRAINT admin_storyboard_production_jobs_scene_versions_check CHECK ((jsonb_typeof(scene_versions) = 'object'::text)),
    CONSTRAINT admin_storyboard_production_jobs_stage_check CHECK ((stage = ANY (ARRAY['queued'::text, 'text'::text, 'images'::text, 'complete'::text, 'failed'::text, 'cancelled'::text, 'uncertain'::text]))),
    CONSTRAINT admin_storyboard_production_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'claimed'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: storyboard_production_job_json(public.admin_storyboard_production_jobs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_job_json(j public.admin_storyboard_production_jobs) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN j.id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object('id', j.id, 'status', j.status,
    'stage', j.stage, 'sceneNo', j.scene_no, 'errorCode', j.error_code, 'attempts', j.attempts,
    'lastHeartbeat', j.last_heartbeat) END;
$$;


--
-- Name: storyboard_production_model_available(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_model_available(p_models jsonb, p_model text, p_capability text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(p_models,'[]')) model
    WHERE model->>'id' = p_model AND model->>'owned_by' = 'gemini-api'
      AND model->'capabilities' ? p_capability
      AND ((p_capability = 'chat' AND p_model = 'gemini-3.8-flash')
        OR (p_capability = 'image' AND p_model IN ('gemini-3.1-flash-image','gemini-3-pro-image'))))
$$;


--
-- Name: admin_storyboard_production_projects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_storyboard_production_projects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    request_id uuid NOT NULL,
    revision integer DEFAULT 0 NOT NULL,
    title text DEFAULT ''::text NOT NULL,
    request jsonb NOT NULL,
    document jsonb,
    status text NOT NULL,
    draft_worker_id uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT admin_storyboard_production_projects_document_workflow_check CHECK (((document IS NULL) OR ((jsonb_typeof(document) = 'object'::text) AND (octet_length((document)::text) <= 196608) AND ((document ->> 'schema'::text) = (request ->> 'workflow'::text)) AND ((document ->> 'projectId'::text) = (id)::text) AND (((document ->> 'revision'::text))::integer = revision)))),
    CONSTRAINT admin_storyboard_production_projects_request_workflow_check CHECK (((jsonb_typeof(request) = 'object'::text) AND (octet_length((request)::text) <= 65536) AND (((request ->> 'workflow'::text) = 'storyboard-mlx-v1'::text) OR (((request ->> 'workflow'::text) = 'storyboard-gemini-v1'::text) AND ((request #>> '{providers,externalAI}'::text[]) = 'true'::text) AND ((request #>> '{providers,text,id}'::text[]) = 'gemini-api'::text) AND ((request #>> '{providers,text,model}'::text[]) = 'gemini-3.8-flash'::text) AND ((request #>> '{providers,image,id}'::text[]) = 'gemini-api'::text) AND ((request #>> '{providers,image,model}'::text[]) = ANY (ARRAY['gemini-3.1-flash-image'::text, 'gemini-3-pro-image'::text])))))),
    CONSTRAINT admin_storyboard_production_projects_revision_check CHECK ((revision >= 0)),
    CONSTRAINT admin_storyboard_production_projects_status_check CHECK ((status = ANY (ARRAY['waiting_worker'::text, 'generating'::text, 'awaiting_import'::text, 'partial'::text, 'ready'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT admin_storyboard_production_projects_title_check CHECK ((length(title) <= 200))
);


--
-- Name: storyboard_production_project_json(public.admin_storyboard_production_projects); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_project_json(p public.admin_storyboard_production_projects) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_object('id', p.id, 'revision', p.revision, 'request', p.request, 'document', p.document,
    'status', p.status, 'createdAt', p.created_at, 'updatedAt', p.updated_at);
$$;


--
-- Name: storyboard_production_reject_archived_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_reject_archived_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE old_project_id uuid; new_project_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'admin_storyboard_production_projects' THEN
    IF (TG_OP = 'UPDATE' AND OLD.request->>'workflow' = 'storyboard-mlx-v1')
      OR NEW.request->>'workflow' = 'storyboard-mlx-v1' THEN
      RAISE EXCEPTION 'archived_project_read_only' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  new_project_id := NEW.project_id;
  IF TG_OP = 'UPDATE' THEN old_project_id := OLD.project_id; END IF;
  IF EXISTS (SELECT 1 FROM public.admin_storyboard_production_projects p
      WHERE p.id IN (new_project_id, old_project_id)
        AND p.request->>'workflow' = 'storyboard-mlx-v1') THEN
    RAISE EXCEPTION 'archived_project_read_only' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: storyboard_production_snapshot(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_snapshot(p_owner_id uuid, p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE p public.admin_storyboard_production_projects; j public.admin_storyboard_production_jobs;
BEGIN
  SELECT * INTO p FROM public.admin_storyboard_production_projects WHERE id = p_project_id AND owner_id = p_owner_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'project_not_found'; END IF;
  SELECT * INTO j FROM public.admin_storyboard_production_jobs WHERE project_id = p.id ORDER BY created_at DESC, id DESC LIMIT 1;
  RETURN jsonb_build_object('ok', true, 'project', public.storyboard_production_project_json(p),
    'job', public.storyboard_production_job_json(j));
END $$;


--
-- Name: storyboard_production_worker(uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_production_worker(p_worker_id uuid, p_action text, p_job_id uuid DEFAULT NULL::uuid, p_lease_token uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  w public.admin_storyboard_production_workers; p public.admin_storyboard_production_projects;
  j public.admin_storyboard_production_jobs; candidate record; doc jsonb; s jsonb; scene integer;
  result_id uuid; final_status text; result_code text; lease_valid boolean := false;
BEGIN
  SELECT * INTO w FROM public.admin_storyboard_production_workers WHERE id = p_worker_id FOR UPDATE;
  IF NOT FOUND OR w.disabled OR w.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'worker_unauthorized'; END IF;
  PERFORM storyboard_control.assert_owner(w.owner_id);
  IF p_action = 'heartbeat' THEN
    UPDATE public.admin_storyboard_production_workers SET last_heartbeat = clock_timestamp(), models = p_payload->'models' WHERE id = w.id;
    IF p_job_id IS NOT NULL THEN
      SELECT project_id INTO candidate FROM public.admin_storyboard_production_jobs WHERE id = p_job_id AND owner_id = w.owner_id;
      IF FOUND THEN
        PERFORM 1 FROM public.admin_storyboard_production_projects WHERE id = candidate.project_id FOR UPDATE;
        UPDATE public.admin_storyboard_production_jobs active_job SET last_heartbeat = clock_timestamp(),
          lease_expires_at = clock_timestamp() + interval '120 seconds', updated_at = clock_timestamp()
          FROM public.admin_storyboard_production_projects q
          WHERE active_job.id = p_job_id AND active_job.worker_id = w.id
            AND active_job.owner_id = w.owner_id AND active_job.status = 'claimed'
            AND q.id = active_job.project_id AND q.owner_id = active_job.owner_id
            AND q.request->>'workflow' = 'storyboard-gemini-v1'
            AND active_job.lease_token = p_lease_token AND active_job.lease_expires_at > clock_timestamp();
        lease_valid := FOUND;
      END IF;
    END IF;
    RETURN jsonb_build_object('ok',true,'leaseValid',lease_valid);
  END IF;
  IF p_action = 'claim' THEN
    -- Recover only this owner's expired leases, even when this worker already has an expired claim.
    FOR candidate IN SELECT q.id FROM public.admin_storyboard_production_projects q
      WHERE q.owner_id = w.owner_id AND q.request->>'workflow' = 'storyboard-gemini-v1'
      AND EXISTS (SELECT 1 FROM public.admin_storyboard_production_jobs x
        WHERE x.project_id = q.id AND x.status = 'claimed' AND x.lease_expires_at <= clock_timestamp())
      ORDER BY q.created_at LIMIT 32 FOR UPDATE OF q SKIP LOCKED
    LOOP
      SELECT * INTO j FROM public.admin_storyboard_production_jobs WHERE project_id = candidate.id AND status = 'claimed' FOR UPDATE;
      IF j.lease_expires_at > clock_timestamp() THEN CONTINUE; END IF;
      SELECT * INTO p FROM public.admin_storyboard_production_projects WHERE id = candidate.id;
      UPDATE public.admin_storyboard_production_jobs SET status = 'failed',
        stage = 'uncertain', error_code = 'worker_lease_lost',
        lease_token = NULL, lease_expires_at = NULL, worker_id = NULL,
        available_at = clock_timestamp() + make_interval(secs => least(60, 5 * (2 ^ greatest(attempts - 1,0))::integer)),
        updated_at = clock_timestamp() WHERE id = j.id;
      UPDATE public.admin_storyboard_production_projects SET status = public.storyboard_production_final_status(request, document),
        updated_at = clock_timestamp() WHERE id = p.id;
      INSERT INTO public.admin_storyboard_production_events(project_id, owner_id, job_id, worker_id, operation, revision, error_code)
        VALUES (p.id, w.owner_id, j.id, j.worker_id, 'lease_expired', p.revision, 'worker_lease_lost');
    END LOOP;
    IF EXISTS (SELECT 1 FROM public.admin_storyboard_production_jobs WHERE worker_id = w.id AND status = 'claimed') THEN
      RETURN jsonb_build_object('ok',true,'job',NULL);
    END IF;
    FOR candidate IN SELECT q.id FROM public.admin_storyboard_production_projects q
      WHERE q.owner_id = w.owner_id AND EXISTS (SELECT 1 FROM public.admin_storyboard_production_jobs x
        WHERE x.project_id = q.id AND x.status = 'queued' AND x.available_at <= clock_timestamp() AND x.attempts < 3)
      AND q.request->>'workflow' = 'storyboard-gemini-v1'
      AND q.request#>>'{providers,text,id}' = 'gemini-api'
      AND q.request#>>'{providers,image,id}' = 'gemini-api'
      AND public.storyboard_production_model_available(w.models,q.request#>>'{providers,text,model}','chat')
      AND public.storyboard_production_model_available(w.models,q.request#>>'{providers,image,model}','image')
      ORDER BY q.created_at LIMIT 64 FOR UPDATE OF q SKIP LOCKED
    LOOP
      SELECT * INTO p FROM public.admin_storyboard_production_projects WHERE id = candidate.id;
      SELECT * INTO j FROM public.admin_storyboard_production_jobs WHERE project_id = p.id AND status = 'queued'
        AND available_at <= clock_timestamp() AND attempts < 3 FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      IF p.request#>>'{providers,text,id}' IS DISTINCT FROM 'gemini-api' OR p.request#>>'{providers,image,id}' IS DISTINCT FROM 'gemini-api' THEN CONTINUE; END IF;
      IF p.document IS NULL THEN
        IF p.request#>>'{providers,text,id}' <> 'gemini-api'
          OR NOT public.storyboard_production_model_available(w.models,p.request#>>'{providers,text,model}','chat') THEN CONTINUE; END IF;
      END IF;
      IF p.request#>>'{providers,image,id}' = 'gemini-api' THEN
        IF NOT public.storyboard_production_model_available(w.models,p.request#>>'{providers,image,model}','image') THEN CONTINUE; END IF;
      ELSIF p.document IS NOT NULL THEN CONTINUE;
      END IF;
      IF p.revision <> j.base_revision OR p.status = 'cancelled' THEN RAISE EXCEPTION 'revision_conflict'; END IF;
      UPDATE public.admin_storyboard_production_jobs SET status = 'claimed', worker_id = w.id, lease_token = gen_random_uuid(),
        lease_expires_at = clock_timestamp() + interval '120 seconds', last_heartbeat = clock_timestamp(), attempts = attempts + 1,
        error_code = NULL, stage = CASE WHEN p.document IS NULL THEN 'text' ELSE 'images' END,
        scene_versions = coalesce((SELECT jsonb_object_agg(x->>'sceneNo', x->'revision') FROM jsonb_array_elements(p.document->'scenes') x),'{}'),
        updated_at = clock_timestamp() WHERE id = j.id RETURNING * INTO j;
      UPDATE public.admin_storyboard_production_workers SET last_heartbeat = clock_timestamp() WHERE id = w.id;
      UPDATE public.admin_storyboard_production_projects SET status = 'generating', updated_at = clock_timestamp() WHERE id = p.id;
      INSERT INTO public.admin_storyboard_production_events(project_id, owner_id, job_id, worker_id, operation, revision, scene_no)
        VALUES (p.id, w.owner_id, j.id, w.id, 'claimed', p.revision, j.scene_no);
      RETURN jsonb_build_object('ok',true,'job',jsonb_build_object('id',j.id,'projectId',p.id,'revision',p.revision,
        'kind',j.kind,'sceneNo',j.scene_no,'request',p.request,'document',p.document,'leaseToken',j.lease_token));
    END LOOP;
    RETURN jsonb_build_object('ok',true,'job',NULL);
  END IF;

  SELECT project_id INTO candidate FROM public.admin_storyboard_production_jobs WHERE id = p_job_id AND owner_id = w.owner_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'worker_lease_lost'; END IF;
  SELECT * INTO p FROM public.admin_storyboard_production_projects WHERE id = candidate.project_id AND owner_id = w.owner_id FOR UPDATE;
  SELECT * INTO j FROM public.admin_storyboard_production_jobs WHERE id = p_job_id FOR UPDATE;
  IF j.status <> 'claimed' OR j.worker_id IS DISTINCT FROM w.id OR j.lease_token IS DISTINCT FROM p_lease_token
    OR j.lease_expires_at <= clock_timestamp() OR p.status = 'cancelled' THEN RAISE EXCEPTION 'worker_lease_lost'; END IF;
  IF p.revision <> j.base_revision THEN RAISE EXCEPTION 'revision_conflict'; END IF;
  IF p.request->>'workflow' IS DISTINCT FROM 'storyboard-gemini-v1' THEN
    RAISE EXCEPTION 'worker_lease_lost';
  END IF;
  scene := (p_payload->>'sceneNo')::integer;
  IF scene IS NOT NULL THEN
    IF p.document IS NULL OR scene NOT BETWEEN 1 AND jsonb_array_length(p.document->'scenes')
      OR (j.kind = 'scene' AND j.scene_no <> scene) THEN RAISE EXCEPTION 'invalid_scene'; END IF;
    s := p.document->'scenes'->(scene - 1);
    IF (j.scene_versions->>scene::text)::integer IS DISTINCT FROM (s->>'revision')::integer THEN RAISE EXCEPTION 'revision_conflict'; END IF;
  END IF;
  IF p_action = 'check' THEN
    RETURN jsonb_build_object('ok',true,'project',public.storyboard_production_project_json(p),'job',
      public.storyboard_production_job_json(j),'kind',j.kind,'sceneRevision',(s->>'revision')::integer,'models',w.models);
  END IF;
  result_code := p_payload->>'errorCode';
  IF NOT public.storyboard_production_error_allowed(result_code) THEN RAISE EXCEPTION 'invalid_request'; END IF;
  IF p_action IN ('draft','image') THEN
    result_id := (p_payload#>>'{provenance,requestId}')::uuid;
    IF result_id IS NULL OR result_id = ANY(j.result_request_ids) THEN RAISE EXCEPTION 'revision_conflict'; END IF;
    IF p_payload#>>'{provenance,providerId}' IS DISTINCT FROM 'gemini-api'
      OR p_payload#>>'{provenance,verification}' IS DISTINCT FROM 'official-api'
      OR p_payload#>>'{provenance,modelEvidence}' IS DISTINCT FROM 'response'
      OR nullif(p_payload#>>'{provenance,responseModel}','') IS NULL
      OR (p_payload#>>'{provenance,responseModel}' IS DISTINCT FROM p_payload#>>'{provenance,model}'
        AND p_payload#>>'{provenance,responseModel}' !~ ('^' || replace(p_payload#>>'{provenance,model}', '.', '[.]') || '-([0-9]{3}|[0-9]{2}-[0-9]{2})$'))
      OR p_payload#>>'{provenance,model}' IS DISTINCT FROM p.request#>>ARRAY['providers',(CASE WHEN p_action = 'draft' THEN 'text' ELSE 'image' END),'model']
      OR NOT public.storyboard_production_model_available(w.models,p_payload#>>'{provenance,model}',CASE WHEN p_action = 'draft' THEN 'chat' ELSE 'image' END)
      THEN RAISE EXCEPTION 'model_identity_mismatch'; END IF;
  END IF;
  IF p_action = 'draft' THEN
    IF p.document IS NOT NULL OR j.kind <> 'generate' OR p.request#>>'{providers,text,id}' <> 'gemini-api' THEN RAISE EXCEPTION 'revision_conflict'; END IF;
    doc := (p_payload->'draft') || jsonb_build_object('schema','storyboard-gemini-v1','projectId',p.id,
      'generatedAt',p_payload#>>'{provenance,generatedAt}','textProvenance',p_payload->'provenance','scenes',
      (SELECT jsonb_agg(x || jsonb_build_object('revision',0,'image',NULL,'imageError',NULL) ORDER BY (x->>'sceneNo')::integer)
       FROM jsonb_array_elements(p_payload#>'{draft,scenes}') x));
    UPDATE public.admin_storyboard_production_jobs SET stage = 'images', scene_versions =
      (SELECT jsonb_object_agg(x->>'sceneNo',0) FROM jsonb_array_elements(doc->'scenes') x) WHERE id = j.id;
    UPDATE public.admin_storyboard_production_projects SET draft_worker_id = w.id WHERE id = p.id;
  ELSIF p_action IN ('image','scene-error') THEN
    IF scene IS NULL OR p.request#>>'{providers,image,id}' <> 'gemini-api' THEN RAISE EXCEPTION 'invalid_scene'; END IF;
    IF p_action = 'image' THEN
      IF (p_payload->>'sceneRevision')::integer IS DISTINCT FROM (s->>'revision')::integer THEN RAISE EXCEPTION 'revision_conflict'; END IF;
      INSERT INTO public.admin_storyboard_production_assets(id,project_id,owner_id,scene_no,scene_revision,metadata,worker_id,job_id)
        VALUES ((p_payload#>>'{asset,id}')::uuid,p.id,w.owner_id,scene,(s->>'revision')::integer + 1,p_payload->'asset',w.id,j.id);
      s := s || jsonb_build_object('image',p_payload->'asset','imageError',NULL,'revision',(s->>'revision')::integer + 1);
    ELSE
      IF result_code IS NULL THEN RAISE EXCEPTION 'invalid_request'; END IF;
      s := s || jsonb_build_object('imageError',result_code,'revision',(s->>'revision')::integer + 1);
    END IF;
    doc := jsonb_set(p.document,ARRAY['scenes',(scene - 1)::text],s);
  ELSIF p_action = 'finish' THEN
    final_status := public.storyboard_production_final_status(p.request,p.document);
    IF result_code IS NOT NULL AND final_status = 'ready' THEN final_status := 'partial'; END IF;
    UPDATE public.admin_storyboard_production_jobs SET status = CASE WHEN result_code IS NULL AND final_status IN ('ready','awaiting_import')
      THEN 'succeeded' ELSE 'failed' END, stage = CASE WHEN result_code IS NULL AND final_status IN ('ready','awaiting_import') THEN 'complete' ELSE 'failed' END,
      error_code = coalesce(result_code,CASE WHEN final_status IN ('failed','partial') THEN 'image_missing' END),
      lease_token = NULL, lease_expires_at = NULL, updated_at = clock_timestamp() WHERE id = j.id;
    UPDATE public.admin_storyboard_production_projects SET status = final_status, updated_at = clock_timestamp() WHERE id = p.id;
    INSERT INTO public.admin_storyboard_production_events(project_id,owner_id,job_id,worker_id,operation,revision,error_code)
      VALUES (p.id,w.owner_id,j.id,w.id,'finished',p.revision,result_code);
    RETURN jsonb_build_object('ok',true);
  ELSE RAISE EXCEPTION 'invalid_request';
  END IF;
  doc := jsonb_set(doc,'{revision}',to_jsonb(p.revision + 1));
  UPDATE public.admin_storyboard_production_projects SET document = doc, title = doc->>'title', revision = revision + 1,
    status = 'generating',
    updated_at = clock_timestamp() WHERE id = p.id RETURNING * INTO p;
    IF p.document IS NOT NULL THEN
      INSERT INTO public.admin_storyboard_production_revisions(project_id, owner_id, revision, document)
      VALUES (p.id, p.owner_id, p.revision, p.document)
      ON CONFLICT (project_id, revision) DO NOTHING;
    END IF;
  UPDATE public.admin_storyboard_production_jobs SET base_revision = p.revision,
    result_request_ids = CASE WHEN result_id IS NULL THEN result_request_ids ELSE array_append(result_request_ids,result_id) END,
    updated_at = clock_timestamp() WHERE id = j.id;
  INSERT INTO public.admin_storyboard_production_events(project_id,owner_id,job_id,worker_id,operation,revision,scene_no,error_code)
    VALUES (p.id,w.owner_id,j.id,w.id,CASE p_action WHEN 'draft' THEN 'draft_saved' WHEN 'image' THEN 'image_saved' ELSE 'scene_failed' END,
      p.revision,scene,result_code);
  RETURN jsonb_build_object('ok',true);
END $_$;


--
-- Name: storyboard_sparse_dot_product(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storyboard_sparse_dot_product(document_weights jsonb, query_weights jsonb) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select coalesce(
    sum(
      coalesce((document_weights ->> key)::double precision, 0.0)
      * coalesce((query_weights ->> key)::double precision, 0.0)
    ),
    0.0
  )
  from jsonb_object_keys(query_weights) as key
  where document_weights ? key;
$$;


--
-- Name: submit_guardian_privacy_consent(text, text, text, uuid, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_guardian_privacy_consent(p_purpose text, p_channel text, p_decision text, p_policy_version_id uuid, p_notice_sha256 text, p_guardian_verification_id uuid, p_idempotency_key text, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_existing privacy_retention.privacy_consent_events%ROWTYPE;
  v_guardian privacy_retention.privacy_guardian_verifications%ROWTYPE;
  v_profile privacy_retention.privacy_age_profiles%ROWTYPE;
  v_policy privacy_retention.privacy_policy_versions%ROWTYPE;
  v_event_id uuid;
  v_audit_id uuid;
BEGIN
  PERFORM privacy_retention.g014_require_service_role();
  IF p_purpose IS DISTINCT FROM 'privacy_required'
     OR p_channel IS DISTINCT FROM 'none'
     OR p_decision IS NULL
     OR p_decision NOT IN ('granted', 'withdrawn')
     OR p_policy_version_id IS NULL
     OR p_notice_sha256 IS NULL
     OR p_notice_sha256 !~ '^[0-9a-f]{64}$'
     OR p_guardian_verification_id IS NULL
     OR p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9_-]{16,128}$'
     OR p_correlation_id IS NULL THEN
    RAISE EXCEPTION 'privacy_guardian_consent_request_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-guardian-consent:' || p_idempotency_key, 0)
  );
  SELECT * INTO v_existing
  FROM privacy_retention.privacy_consent_events AS event
  WHERE event.idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.subject_kind <> 'child'
       OR v_existing.guardian_verification_id IS DISTINCT FROM p_guardian_verification_id
       OR v_existing.purpose IS DISTINCT FROM p_purpose
       OR v_existing.channel IS DISTINCT FROM p_channel
       OR v_existing.decision IS DISTINCT FROM p_decision
       OR v_existing.policy_version_id IS DISTINCT FROM p_policy_version_id
       OR v_existing.notice_sha256 IS DISTINCT FROM p_notice_sha256
       OR v_existing.source <> 'guardian'
       OR v_existing.correlation_id IS DISTINCT FROM p_correlation_id THEN
      RAISE EXCEPTION 'privacy_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    SELECT audit.id INTO v_audit_id
    FROM privacy_retention.privacy_audit_events AS audit
    WHERE audit.operation_id = v_existing.id
      AND audit.event_type = 'consent_recorded'
      AND audit.correlation_id = p_correlation_id
      AND audit.actor_user_id IS NULL
    ORDER BY audit.created_at DESC, audit.id DESC
    LIMIT 1;
    IF v_audit_id IS NULL THEN
      RAISE EXCEPTION 'privacy_consent_audit_missing' USING ERRCODE = '55000';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'operationId', p_correlation_id::text,
      'status', 'applied',
      'readback', pg_catalog.jsonb_build_object('passed', true, 'checks', pg_catalog.jsonb_build_object('consentEventPresent', true)),
      'auditId', v_audit_id::text,
      'consentEventId', v_existing.id::text
    );
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-policy-publication-state', 0)
  );

  SELECT * INTO v_guardian
  FROM privacy_retention.privacy_guardian_verifications AS guardian
  WHERE guardian.id = p_guardian_verification_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_guardian.status <> 'verified'
     OR v_guardian.verified_at IS NULL
     OR v_guardian.verified_at > pg_catalog.clock_timestamp()
     OR v_guardian.expires_at IS NULL
     OR v_guardian.expires_at <= pg_catalog.clock_timestamp()
     OR v_guardian.withdrawn_at IS NOT NULL THEN
    RAISE EXCEPTION 'privacy_guardian_verification_required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_profile
  FROM privacy_retention.privacy_age_profiles AS profile
  WHERE profile.user_id = v_guardian.child_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_profile.age_band <> 'under_14'
     OR v_profile.status NOT IN ('guardian_pending', 'guardian_verified')
     OR v_profile.policy_version_id IS DISTINCT FROM p_policy_version_id THEN
    RAISE EXCEPTION 'privacy_guardian_child_binding_invalid' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_policy
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.status = 'published'
    AND policy.effective_at <= pg_catalog.clock_timestamp()
  ORDER BY policy.effective_at DESC, policy.id DESC
  LIMIT 1;
  IF NOT FOUND
     OR v_policy.id IS DISTINCT FROM p_policy_version_id
     OR v_policy.content_sha256 IS DISTINCT FROM p_notice_sha256 THEN
    RAISE EXCEPTION 'privacy_current_policy_required' USING ERRCODE = '23514';
  END IF;

  INSERT INTO privacy_retention.privacy_consent_events (
    user_id,
    subject_kind,
    guardian_verification_id,
    purpose,
    channel,
    decision,
    policy_version_id,
    notice_sha256,
    source,
    correlation_id,
    idempotency_key
  ) VALUES (
    v_guardian.child_user_id,
    'child',
    v_guardian.id,
    'privacy_required',
    'none',
    p_decision,
    p_policy_version_id,
    p_notice_sha256,
    'guardian',
    p_correlation_id,
    p_idempotency_key
  )
  RETURNING id INTO v_event_id;

  v_audit_id := privacy_retention.append_privacy_audit_event_internal(
    'consent_recorded',
    NULL,
    v_guardian.child_user_id,
    v_event_id,
    p_correlation_id,
    'applied',
    'GUARDIAN_CONSENT_RECORDED',
    pg_catalog.jsonb_build_object('consentEvents', 1, 'guardianVerified', true),
    pg_catalog.jsonb_build_object('route', '/api/privacy/guardian')
  );
  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'operationId', p_correlation_id::text,
    'status', 'applied',
    'readback', pg_catalog.jsonb_build_object('passed', true, 'checks', pg_catalog.jsonb_build_object('consentEventPresent', true)),
    'auditId', v_audit_id::text,
    'consentEventId', v_event_id::text
  );
END;
$_$;


--
-- Name: submit_privacy_consent(text, text, text, uuid, text, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_privacy_consent(p_purpose text, p_channel text, p_decision text, p_policy_version_id uuid, p_notice_sha256 text, p_source text, p_guardian_verification_id uuid, p_idempotency_key text, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_role text;
  v_user_id uuid := privacy_retention.g041_current_claim_user_id();
  v_existing privacy_retention.privacy_consent_events%ROWTYPE;
  v_policy privacy_retention.privacy_policy_versions%ROWTYPE;
  v_profile privacy_retention.privacy_age_profiles%ROWTYPE;
  v_event_id uuid;
  v_audit_id uuid;
BEGIN
  v_role := COALESCE(
    NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    pg_catalog.current_setting('request.jwt.claim.role', true),
    ''
  );
  IF v_role <> 'authenticated' OR v_user_id IS NULL THEN
    RAISE EXCEPTION 'privacy_authentication_required' USING ERRCODE = '42501';
  END IF;
  IF p_purpose IS NULL
     OR p_channel IS NULL
     OR p_decision IS NULL
     OR p_decision NOT IN ('granted', 'withdrawn')
     OR NOT (
       (p_purpose = 'email_marketing' AND p_channel = 'email')
       OR (p_purpose = 'sms_marketing' AND p_channel = 'sms')
       OR (p_purpose = 'push_marketing' AND p_channel = 'push')
       OR (p_purpose = 'night_marketing' AND p_channel IN ('email', 'sms', 'push'))
     )
     OR p_policy_version_id IS NULL
     OR p_notice_sha256 IS NULL
     OR p_notice_sha256 !~ '^[0-9a-f]{64}$'
     OR p_source IS DISTINCT FROM 'settings'
     OR p_guardian_verification_id IS NOT NULL
     OR p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9_-]{16,128}$'
     OR p_correlation_id IS NULL THEN
    RAISE EXCEPTION 'privacy_consent_request_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-adult-consent:' || p_idempotency_key, 0)
  );
  SELECT * INTO v_existing
  FROM privacy_retention.privacy_consent_events AS event
  WHERE event.idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.user_id IS DISTINCT FROM v_user_id
       OR v_existing.subject_kind <> 'self'
       OR v_existing.guardian_verification_id IS NOT NULL
       OR v_existing.purpose IS DISTINCT FROM p_purpose
       OR v_existing.channel IS DISTINCT FROM p_channel
       OR v_existing.decision IS DISTINCT FROM p_decision
       OR v_existing.policy_version_id IS DISTINCT FROM p_policy_version_id
       OR v_existing.notice_sha256 IS DISTINCT FROM p_notice_sha256
       OR v_existing.source IS DISTINCT FROM p_source
       OR v_existing.correlation_id IS DISTINCT FROM p_correlation_id THEN
      RAISE EXCEPTION 'privacy_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    SELECT audit.id INTO v_audit_id
    FROM privacy_retention.privacy_audit_events AS audit
    WHERE audit.operation_id = v_existing.id
      AND audit.event_type = 'consent_recorded'
      AND audit.correlation_id = p_correlation_id
      AND audit.actor_user_id = v_user_id
    ORDER BY audit.created_at DESC, audit.id DESC
    LIMIT 1;
    IF v_audit_id IS NULL THEN
      RAISE EXCEPTION 'privacy_consent_audit_missing' USING ERRCODE = '55000';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'schemaVersion', 1,
      'operationId', p_correlation_id::text,
      'status', 'applied',
      'readback', pg_catalog.jsonb_build_object('passed', true, 'checks', pg_catalog.jsonb_build_object('consentEventPresent', true)),
      'auditId', v_audit_id::text,
      'consentEventId', v_existing.id::text
    );
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('g014-policy-publication-state', 0)
  );

  SELECT * INTO v_policy
  FROM privacy_retention.privacy_policy_versions AS policy
  WHERE policy.status = 'published'
    AND policy.effective_at <= pg_catalog.clock_timestamp()
  ORDER BY policy.effective_at DESC, policy.id DESC
  LIMIT 1;
  IF NOT FOUND
     OR v_policy.id IS DISTINCT FROM p_policy_version_id
     OR v_policy.content_sha256 IS DISTINCT FROM p_notice_sha256 THEN
    RAISE EXCEPTION 'privacy_current_policy_required' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_profile
  FROM privacy_retention.privacy_age_profiles AS profile
  WHERE profile.user_id = v_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_profile.age_band <> 'age_14_plus'
     OR v_profile.status <> 'eligible' THEN
    RAISE EXCEPTION 'privacy_guardian_workflow_required' USING ERRCODE = '42501';
  END IF;

  INSERT INTO privacy_retention.privacy_consent_events (
    user_id,
    subject_kind,
    purpose,
    channel,
    decision,
    policy_version_id,
    notice_sha256,
    source,
    correlation_id,
    idempotency_key
  ) VALUES (
    v_user_id,
    'self',
    p_purpose,
    p_channel,
    p_decision,
    p_policy_version_id,
    p_notice_sha256,
    'settings',
    p_correlation_id,
    p_idempotency_key
  )
  RETURNING id INTO v_event_id;

  v_audit_id := privacy_retention.append_privacy_audit_event_internal(
    'consent_recorded',
    v_user_id,
    v_user_id,
    v_event_id,
    p_correlation_id,
    'applied',
    'CONSENT_RECORDED',
    pg_catalog.jsonb_build_object('consentEvents', 1),
    pg_catalog.jsonb_build_object('route', '/api/privacy/consent')
  );
  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'operationId', p_correlation_id::text,
    'status', 'applied',
    'readback', pg_catalog.jsonb_build_object('passed', true, 'checks', pg_catalog.jsonb_build_object('consentEventPresent', true)),
    'auditId', v_audit_id::text,
    'consentEventId', v_event_id::text
  );
END;
$_$;


--
-- Name: submit_restaurant_edit_request(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_restaurant_edit_request(p_user_id uuid, p_client_request_key text, p_target_restaurant_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    AS $_$ SELECT pipeline_control.submit_restaurant_edit_request($1,$2,$3,$4); $_$;


--
-- Name: submit_restaurant_submission(uuid, text, text, text, text, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_restaurant_submission(p_user_id uuid, p_submission_type text, p_client_submission_key text, p_restaurant_name text, p_restaurant_address text, p_restaurant_phone text DEFAULT NULL::text, p_restaurant_categories text[] DEFAULT NULL::text[], p_youtube_link text DEFAULT NULL::text, p_tzuyang_review text DEFAULT NULL::text) RETURNS TABLE(submission_id uuid, item_id uuid, user_id uuid, submission_type text, client_submission_key text, status text, restaurant_name text, restaurant_address text, restaurant_phone text, restaurant_categories text[], youtube_link text, tzuyang_review text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_submission_id uuid;
  v_item_id uuid;
begin
  if p_user_id is null then
    raise exception 'user_id is required' using errcode = '22023';
  end if;

  if p_submission_type <> 'new' then
    raise exception 'unsupported submission_type' using errcode = '22023';
  end if;

  if p_client_submission_key is null or btrim(p_client_submission_key) = '' then
    raise exception 'client_submission_key is required' using errcode = '22023';
  end if;

  insert into public.restaurant_submissions (
    user_id,
    submission_type,
    client_submission_key,
    status,
    restaurant_name,
    restaurant_address,
    restaurant_phone,
    restaurant_categories
  ) values (
    p_user_id,
    p_submission_type,
    p_client_submission_key,
    'pending',
    btrim(p_restaurant_name),
    btrim(p_restaurant_address),
    nullif(btrim(p_restaurant_phone), ''),
    p_restaurant_categories
  )
  on conflict (user_id, submission_type, client_submission_key)
    where client_submission_key is not null
  do nothing
  returning id into v_submission_id;

  if v_submission_id is not null then
    insert into public.restaurant_submission_items (
      submission_id,
      youtube_link,
      tzuyang_review
    ) values (
      v_submission_id,
      btrim(p_youtube_link),
      nullif(btrim(p_tzuyang_review), '')
    )
    returning id into v_item_id;
  else
    select rs.id
      into v_submission_id
      from public.restaurant_submissions rs
     where rs.user_id = p_user_id
       and rs.submission_type = p_submission_type
       and rs.client_submission_key = p_client_submission_key;

    select rsi.id
      into v_item_id
      from public.restaurant_submission_items rsi
     where rsi.submission_id = v_submission_id
     order by rsi.id asc
     limit 1;
  end if;

  return query
  select
    rs.id as submission_id,
    rsi.id as item_id,
    rs.user_id,
    rs.submission_type,
    rs.client_submission_key,
    rs.status,
    rs.restaurant_name,
    rs.restaurant_address,
    rs.restaurant_phone,
    rs.restaurant_categories,
    rsi.youtube_link,
    rsi.tzuyang_review
  from public.restaurant_submissions rs
  join public.restaurant_submission_items rsi
    on rsi.id = v_item_id
  where rs.id = v_submission_id;
end;
$$;


--
-- Name: sync_submission_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_submission_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_status submission_status;
BEGIN
    -- item 상태가 변경되면 부모 submission 상태 재계산
    v_new_status := public.calculate_submission_status(
        COALESCE(NEW.submission_id, OLD.submission_id)
    );
    
    UPDATE public.restaurant_submissions
    SET 
        status = v_new_status,
        updated_at = now()
    WHERE id = COALESCE(NEW.submission_id, OLD.submission_id)
      AND status != v_new_status; -- 변경이 있을 때만 업데이트
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


