    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_action_results_result_code_check CHECK ((result_code = ANY (ARRAY['agent_action_not_allowlisted'::text, 'human_approval_required'::text, 'agent_action_duplicate'::text, 'agent_action_rate_limited'::text, 'agent_action_unverified'::text, 'agent_allowlist_unavailable'::text, 'agent_action_record_unavailable'::text, 'agent_action_performed'::text])))
);


--
-- Name: agent_action_state; Type: VIEW; Schema: local_analytics; Owner: -
--

CREATE VIEW local_analytics.agent_action_state WITH (security_invoker='true') AS
 SELECT r.action_id,
    r.trigger_signal_id,
    r.signal_severity,
    r.action_kind_id,
    COALESCE(t.result_code, r.result_code) AS result_code,
    r.human_approval_ref,
    r.recorded_at,
    t.recorded_at AS finalized_at
   FROM (local_analytics.agent_action_records r
     LEFT JOIN local_analytics.agent_action_results t USING (action_id));


