    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT agent_approval_pending_decisions_action_kind_id_check CHECK ((action_kind_id = ANY (ARRAY['open_github_issue'::text, 'hosted_database_write'::text, 'hosted_migration_apply'::text, 'deployment_execution'::text, 'rollback_execution'::text, 'branch_protection_change'::text, 'secret_value_change'::text, 'dns_change'::text]))),
    CONSTRAINT agent_approval_pending_decisions_result_code_check CHECK ((result_code = 'human_approval_required'::text)),
    CONSTRAINT agent_approval_pending_decisions_signal_severity_check CHECK ((signal_severity = ANY (ARRAY['info'::text, 'low'::text, 'warning'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
