    update_row_count integer DEFAULT 0 NOT NULL,
    total_row_count integer DEFAULT 0 NOT NULL,
    batch_index integer,
    batch_index_key integer GENERATED ALWAYS AS (COALESCE(batch_index, '-1'::integer)) STORED NOT NULL,
    readback_rows integer,
    matched_rows integer,
    mismatched_rows integer,
    preview_hash text,
    result_code text NOT NULL,
    CONSTRAINT publish_history_counts_nonnegative CHECK (((insert_row_count >= 0) AND (update_row_count >= 0) AND (total_row_count >= 0) AND ((batch_index IS NULL) OR (batch_index >= 0)) AND ((readback_rows IS NULL) OR (readback_rows >= 0)) AND ((matched_rows IS NULL) OR (matched_rows >= 0)) AND ((mismatched_rows IS NULL) OR (mismatched_rows >= 0)))),
    CONSTRAINT publish_history_preview_hash_shape CHECK (((preview_hash IS NULL) OR (preview_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT publish_history_result_code_check CHECK ((result_code = ANY (ARRAY['publication_target_not_admitted'::text, 'preview_hash_mismatch'::text, 'preview_expired'::text, 'batch_upsert_limit'::text, 'publish_readback_mismatch'::text, 'publish_apply_aborted'::text, 'publish_schedule_not_approved'::text, 'preview_generated'::text, 'confirm_admitted'::text, 'apply_completed'::text, 'converged_no_op'::text, 'readback_matched'::text, 'publish_succeeded'::text]))),
