--
-- Name: receipt_credential_release_catalog_contract; Type: TABLE; Schema: ocr_private; Owner: -
--

CREATE TABLE ocr_private.receipt_credential_release_catalog_contract (
    capability_version text NOT NULL,
    migration_version text,
    migration_name text,
    statement_count integer,
    statement_vector_sha256 text,
    ledger_count integer,
    ledger_identity_root text,
    function_contract jsonb NOT NULL,
    table_contract jsonb NOT NULL,
    sealed_at timestamp with time zone,
    CONSTRAINT receipt_credential_release_capability_version_v2_check CHECK ((capability_version = ANY (ARRAY['receipt-ocr-definitive-credential-release-v1'::text, 'receipt-ocr-definitive-credential-release-v2'::text]))),
    CONSTRAINT receipt_credential_release_catalog_seal_check CHECK ((((migration_version IS NULL) AND (migration_name IS NULL) AND (statement_count IS NULL) AND (statement_vector_sha256 IS NULL) AND (ledger_count IS NULL) AND (ledger_identity_root IS NULL) AND (sealed_at IS NULL)) OR ((migration_version ~ '^[0-9]{14}$'::text) AND (migration_name ~ '^[a-z0-9_]+$'::text) AND (statement_count > 0) AND (statement_vector_sha256 ~ '^[0-9a-f]{64}$'::text) AND (ledger_count > 0) AND (ledger_identity_root ~ '^[0-9a-f]{64}$'::text) AND (sealed_at IS NOT NULL)))),
    CONSTRAINT receipt_credential_release_function_contract_check CHECK ((jsonb_typeof(function_contract) = 'object'::text)),
    CONSTRAINT receipt_credential_release_table_contract_check CHECK ((jsonb_typeof(table_contract) = 'object'::text))
);

ALTER TABLE ONLY ocr_private.receipt_credential_release_catalog_contract FORCE ROW LEVEL SECURITY;


