    CONSTRAINT receipt_ocr_indeterminate_recover_verification_photo_hash_check CHECK ((verification_photo_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT receipt_ocr_indeterminate_recoveries_expected_image_hash_check CHECK ((expected_image_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT receipt_ocr_indeterminate_recoveries_input_snapshot_hash_check CHECK ((input_snapshot_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT receipt_ocr_indeterminate_recoveries_model_policy_check CHECK (ocr_private.valid_model_policy(model_policy)),
