--
-- Name: receipt_ocr_recovery_catalog_contract; Type: TABLE; Schema: ocr_private; Owner: -
--

CREATE TABLE ocr_private.receipt_ocr_recovery_catalog_contract (
    capability_version text NOT NULL,
    migration_version text,
    migration_name text,
    statement_count integer,
    statement_vector_sha256 text,
    predecessor_ledger_count integer,
    predecessor_terminal_identity_root text,
    ledger_count integer,
    ledger_identity_root text,
    sealed_at timestamp with time zone,
    function_contract jsonb NOT NULL,
    table_contract jsonb NOT NULL,
    trigger_contract jsonb NOT NULL,
    CONSTRAINT receipt_ocr_recovery_catalog_contract_capability_version_check CHECK ((capability_version = 'receipt-ocr-indeterminate-recovery-v1'::text)),
    CONSTRAINT receipt_ocr_recovery_catalog_seal_check CHECK ((((migration_version IS NULL) AND (migration_name IS NULL) AND (statement_count IS NULL) AND (statement_vector_sha256 IS NULL) AND (predecessor_ledger_count IS NULL) AND (predecessor_terminal_identity_root IS NULL) AND (ledger_count IS NULL) AND (ledger_identity_root IS NULL) AND (sealed_at IS NULL)) OR ((migration_version ~ '^[0-9]{14}$'::text) AND (migration_name = 'receipt_ocr_indeterminate_recovery'::text) AND (statement_count > 0) AND (statement_vector_sha256 ~ '^[0-9a-f]{64}$'::text) AND (predecessor_ledger_count = 107) AND (predecessor_terminal_identity_root ~ '^[0-9a-f]{64}$'::text) AND (ledger_count = 108) AND (ledger_identity_root ~ '^[0-9a-f]{64}$'::text) AND (sealed_at IS NOT NULL))))
);

ALTER TABLE ONLY ocr_private.receipt_ocr_recovery_catalog_contract FORCE ROW LEVEL SECURITY;


