--
-- Name: receipt_results; Type: TABLE; Schema: ocr_private; Owner: -
--

CREATE TABLE ocr_private.receipt_results (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    image_hash text NOT NULL,
    input_context_hash text NOT NULL,
    provider text NOT NULL,
    model_policy jsonb NOT NULL,
    generation uuid NOT NULL,
    prompt_version text NOT NULL,
    preprocess_version text NOT NULL,
    normalization_version text NOT NULL,
    status text NOT NULL,
    dispatch_stage text NOT NULL,
    claim_token uuid,
    result_payload jsonb,
    result_revision uuid,
    claimed_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT receipt_results_dispatch_stage_check CHECK ((dispatch_stage = ANY (ARRAY['reserved'::text, 'possibly_dispatched'::text, 'completed'::text, 'uncertain'::text]))),
    CONSTRAINT receipt_results_image_hash_check CHECK ((image_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT receipt_results_input_context_hash_check CHECK ((input_context_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT receipt_results_model_policy_check CHECK (((jsonb_typeof(model_policy) = 'array'::text) AND ((jsonb_array_length(model_policy) >= 1) AND (jsonb_array_length(model_policy) <= 8)))),
    CONSTRAINT receipt_results_normalization_version_check CHECK (((length(normalization_version) >= 1) AND (length(normalization_version) <= 160))),
    CONSTRAINT receipt_results_preprocess_version_check CHECK (((length(preprocess_version) >= 1) AND (length(preprocess_version) <= 160))),
    CONSTRAINT receipt_results_prompt_version_check CHECK (((length(prompt_version) >= 1) AND (length(prompt_version) <= 160))),
    CONSTRAINT receipt_results_provider_check CHECK ((provider = 'gemini'::text)),
    CONSTRAINT receipt_results_state_check CHECK ((((status = 'processing'::text) AND (dispatch_stage = ANY (ARRAY['reserved'::text, 'possibly_dispatched'::text])) AND (claim_token IS NOT NULL) AND (completed_at IS NULL) AND (((result_payload IS NULL) AND (result_revision IS NULL)) OR ((result_payload IS NOT NULL) AND (result_revision IS NOT NULL)))) OR ((status = 'succeeded'::text) AND (dispatch_stage = ANY (ARRAY['completed'::text, 'uncertain'::text])) AND (claim_token IS NULL) AND (result_payload IS NOT NULL) AND (result_revision IS NOT NULL) AND (completed_at IS NOT NULL)) OR ((status = 'indeterminate'::text) AND (dispatch_stage = 'uncertain'::text) AND (claim_token IS NULL) AND (result_payload IS NULL) AND (result_revision IS NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT receipt_results_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'succeeded'::text, 'indeterminate'::text])))
);

ALTER TABLE ONLY ocr_private.receipt_results FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE receipt_results; Type: COMMENT; Schema: ocr_private; Owner: -
--

COMMENT ON TABLE ocr_private.receipt_results IS 'Owner-bound normalized receipt OCR results. Rows have no automatic TTL: account deletion cascades, version-bound fingerprints prevent stale reuse, undispatched reservations require explicit recovery, and possibly dispatched calls remain blocked from replay.';


