--
-- Name: admin_evaluation_related_rows; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_evaluation_related_rows WITH (security_invoker='true') AS
 SELECT r.id,
    r.approved_name,
    r.origin_name,
    r.naver_name,
    r.google_name,
    r.phone,
    r.status,
    r.road_address,
    r.jibun_address,
    r.youtube_link,
    r.updated_by_admin_id,
    r.lat,
    r.lng,
    r.created_at,
    idx.video AS video_id,
    jsonb_build_object('location_match_TF', jsonb_build_object('eval_value', (r.evaluation_results #> '{location_match_TF,eval_value}'::text[]), 'match_status', (r.evaluation_results #> '{location_match_TF,match_status}'::text[]), 'naver_name', (r.evaluation_results #> '{location_match_TF,naver_name}'::text[]), 'matched_provider', (r.evaluation_results #> '{location_match_TF,matched_provider}'::text[]), 'matched_name', (r.evaluation_results #> '{location_match_TF,matched_name}'::text[]))) AS evaluation_results,
    r.approved_name AS name
   FROM (public.restaurants r
     JOIN pipeline_control.admin_evaluation_read_index idx ON ((idx.id = r.id)));


