--
-- Name: g038_deletion_commitment; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.g038_deletion_commitment (
    commitment_id uuid NOT NULL,
    assertion_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    target_user_id uuid NOT NULL,
    request_id uuid NOT NULL,
    session_id uuid NOT NULL,
    proof_id uuid NOT NULL,
    preview_hash text NOT NULL,
    confirmation_text text NOT NULL,
    idempotency_key text NOT NULL,
    source_manifest_hash text NOT NULL,
    confirmation_digest bytea NOT NULL,
    idempotency_key_digest bytea NOT NULL,
    actor_assertion_digest bytea NOT NULL,
    assertion_root_head_sha256 bytea NOT NULL,
    hmac_head_sha256 bytea NOT NULL,
    assertion_nonce uuid NOT NULL,
    request_digest bytea NOT NULL,
    preflight_id uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    status text NOT NULL,
    mode text NOT NULL,
    response_status smallint NOT NULL,
    response_body_sha256 bytea NOT NULL,
    ciphertext_schema text NOT NULL,
    key_reference text NOT NULL,
    algorithm text NOT NULL,
    nonce bytea NOT NULL,
    aad bytea NOT NULL,
    aad_sha256 bytea NOT NULL,
    ciphertext bytea NOT NULL,
    auth_tag bytea NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT g038_commitment_aad_bounds CHECK (((octet_length(aad) >= 1) AND (octet_length(aad) <= 4096))),
    CONSTRAINT g038_commitment_aad_hash_binding CHECK ((aad_sha256 = sha256(aad))),
    CONSTRAINT g038_commitment_aad_sha256_len CHECK ((octet_length(aad_sha256) = 32)),
    CONSTRAINT g038_commitment_actor_assertion_digest_len CHECK ((octet_length(actor_assertion_digest) = 32)),
    CONSTRAINT g038_commitment_algorithm_exact CHECK ((algorithm = 'AES-256-GCM'::text)),
    CONSTRAINT g038_commitment_assertion_root_head_len CHECK ((octet_length(assertion_root_head_sha256) = 32)),
    CONSTRAINT g038_commitment_auth_tag_len CHECK ((octet_length(auth_tag) = 16)),
    CONSTRAINT g038_commitment_ciphertext_bounds CHECK (((octet_length(ciphertext) >= 1) AND (octet_length(ciphertext) <= 8192))),
    CONSTRAINT g038_commitment_ciphertext_schema_exact CHECK ((ciphertext_schema = 'G038-PREFLIGHT-REPLAY-CIPHERTEXT-V1'::text)),
    CONSTRAINT g038_commitment_confirmation_digest_len CHECK ((octet_length(confirmation_digest) = 32)),
    CONSTRAINT g038_commitment_hmac_head_len CHECK ((octet_length(hmac_head_sha256) = 32)),
    CONSTRAINT g038_commitment_idempotency_digest_len CHECK ((octet_length(idempotency_key_digest) = 32)),
    CONSTRAINT g038_commitment_key_reference_exact CHECK ((key_reference = 'g038_preflight_replay_aead_v1'::text)),
    CONSTRAINT g038_commitment_mode_exact CHECK ((mode = 'V1_COMPAT'::text)),
    CONSTRAINT g038_commitment_nonce_len CHECK ((octet_length(nonce) = 12)),
    CONSTRAINT g038_commitment_request_digest_len CHECK ((octet_length(request_digest) = 32)),
    CONSTRAINT g038_commitment_response_body_sha256_len CHECK ((octet_length(response_body_sha256) = 32)),
    CONSTRAINT g038_commitment_response_status_exact CHECK ((response_status = 200)),
    CONSTRAINT g038_commitment_status_exact CHECK ((status = ANY (ARRAY['AVAILABLE'::text, 'CHECKED_OUT'::text, 'DISPOSED'::text])))
);


