--
-- Name: privacy_consent_state; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.privacy_consent_state WITH (security_barrier='true') AS
 SELECT DISTINCT ON (event.user_id, event.subject_kind, event.purpose, event.channel) event.user_id,
    event.subject_kind,
    event.purpose,
    event.channel,
    event.decision,
    event.policy_version_id,
    event.guardian_verification_id,
    event.id AS consent_event_id,
    event.occurred_at
   FROM privacy_retention.privacy_consent_events event
  WHERE (event.user_id = auth.uid())
  ORDER BY event.user_id, event.subject_kind, event.purpose, event.channel, event.occurred_at DESC, event.id DESC;


