    CONSTRAINT privacy_incident_notices_external_receipt_ref_check CHECK (((external_receipt_ref IS NULL) OR (external_receipt_ref ~ '^[A-Za-z][A-Za-z0-9._:/-]{5,159}$'::text))),
    CONSTRAINT privacy_incident_notices_state_check CHECK ((((status = 'draft'::public.privacy_incident_notice_status) AND (approved_by IS NULL) AND (approved_at IS NULL) AND (submitted_by IS NULL) AND (submitted_at IS NULL) AND (external_receipt_ref IS NULL)) OR ((status = 'approved'::public.privacy_incident_notice_status) AND (approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND (submitted_by IS NULL) AND (submitted_at IS NULL) AND (external_receipt_ref IS NULL)) OR ((status = 'submitted'::public.privacy_incident_notice_status) AND (approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND (submitted_by IS NOT NULL) AND (submitted_at IS NOT NULL) AND (external_receipt_ref IS NOT NULL)) OR ((status = 'failed'::public.privacy_incident_notice_status) AND (approved_by IS NOT NULL) AND (approved_at IS NOT NULL) AND (submitted_by IS NULL) AND (submitted_at IS NULL) AND (external_receipt_ref IS NULL)))),
    CONSTRAINT privacy_incident_notices_template_version_check CHECK ((template_version ~ '^[a-zA-Z0-9._-]{1,64}$'::text))
);

