--
-- Name: privacy_incidents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.privacy_incidents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    status public.privacy_incident_status DEFAULT 'detected'::public.privacy_incident_status NOT NULL,
    severity text NOT NULL,
    detected_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    awareness_at timestamp with time zone,
    deadline_at timestamp with time zone,
    affected_count_estimate integer,
    data_categories public.privacy_incident_data_category[] DEFAULT '{}'::public.privacy_incident_data_category[] NOT NULL,
    sensitive_or_unique_id boolean,
    external_intrusion boolean,
    owner_user_id uuid NOT NULL,
    decision_code text,
    assessment_readback_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT privacy_incidents_affected_count_estimate_check CHECK (((affected_count_estimate IS NULL) OR ((affected_count_estimate >= 0) AND (affected_count_estimate <= 1000000000)))),
    CONSTRAINT privacy_incidents_assessment_check CHECK (((status <> ALL (ARRAY['notice_drafted'::public.privacy_incident_status, 'notice_approved'::public.privacy_incident_status, 'notified'::public.privacy_incident_status, 'closed'::public.privacy_incident_status])) OR ((awareness_at IS NOT NULL) AND (deadline_at IS NOT NULL) AND (affected_count_estimate IS NOT NULL) AND (cardinality(data_categories) > 0) AND (sensitive_or_unique_id IS NOT NULL) AND (external_intrusion IS NOT NULL) AND (decision_code IS NOT NULL) AND (assessment_readback_at IS NOT NULL)))),
    CONSTRAINT privacy_incidents_awareness_deadline_check CHECK ((((awareness_at IS NULL) AND (deadline_at IS NULL)) OR ((awareness_at IS NOT NULL) AND (deadline_at = (awareness_at + '72:00:00'::interval))))),
    CONSTRAINT privacy_incidents_categories_check CHECK (((cardinality(data_categories) <= 10) AND (array_position(data_categories, NULL::public.privacy_incident_data_category) IS NULL))),
    CONSTRAINT privacy_incidents_decision_code_check CHECK (((decision_code IS NULL) OR (decision_code ~ '^[a-z][a-z0-9_]{2,63}$'::text))),
    CONSTRAINT privacy_incidents_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])))
);

