--
-- Name: youtube_channel_kpi_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.youtube_channel_kpi_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel_id text NOT NULL,
    channel_title text,
    channel_handle text,
    subscriber_count bigint,
    view_count bigint,
    video_count integer,
    hidden_subscriber_count boolean DEFAULT false NOT NULL,
    previous_bucket_started_at timestamp with time zone,
    subscriber_delta bigint,
    view_delta bigint,
    video_delta integer,
    bucket_started_at timestamp with time zone NOT NULL,
    fetched_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    source text DEFAULT 'youtube-data-api'::text NOT NULL,
    CONSTRAINT youtube_channel_kpi_snapshots_non_negative_counts CHECK ((((subscriber_count IS NULL) OR (subscriber_count >= 0)) AND ((view_count IS NULL) OR (view_count >= 0)) AND ((video_count IS NULL) OR (video_count >= 0))))
);


--
-- Name: youtube_video_kpi_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.youtube_video_kpi_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    video_id text NOT NULL,
    channel_id text NOT NULL,
    title text DEFAULT '제목 없음'::text NOT NULL,
    published_at timestamp with time zone,
    category_id text,
    duration_seconds integer DEFAULT 0 NOT NULL,
    view_count bigint DEFAULT 0 NOT NULL,
    like_count bigint DEFAULT 0 NOT NULL,
    comment_count bigint DEFAULT 0 NOT NULL,
    bucket_started_at timestamp with time zone NOT NULL,
    fetched_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    source text DEFAULT 'youtube-data-api'::text NOT NULL,
    CONSTRAINT youtube_video_kpi_snapshots_comment_count_check CHECK ((comment_count >= 0)),
    CONSTRAINT youtube_video_kpi_snapshots_duration_seconds_check CHECK ((duration_seconds >= 0)),
    CONSTRAINT youtube_video_kpi_snapshots_like_count_check CHECK ((like_count >= 0)),
    CONSTRAINT youtube_video_kpi_snapshots_view_count_check CHECK ((view_count >= 0))
);


